def etap5_k0(rep, lines, start, until):
    """E6/K0 (209, projekt etapu 6 v2 rozdz. 3 "E6/K0" Test): licznik koni gry u zrodla, stan koni partii (pamiec doby), pasza z tego stanu.
    Linia startowa "HorseState (E6/K0): licznik koni gry u zrodla (postfiks", linia doby "Marsz - konie partii (E6/K0): dzien N" (dzien = doba gry - 1,
    okno doby kampanii 1-until jak etap5_main), dopisek "pasza (E6/K0, FodderFromHorseState" w linii "Zima wedlug krain (E4/1)"."""
    wire = [x for x in lines if x.startswith("HorseState (E6/K0): licznik koni gry u zrodla (postfiks")]
    if not wire:
        rep.add("K0-1: latka licznika koni gry (ItemRoster.OnRosterUpdated)", "brak linii startowej", "jest od wgrania E6/K0", None)
        return
    w = wire[-1]
    rep.add("K0-1: latka licznika koni gry (ItemRoster.OnRosterUpdated)", w[:200], "\"OnRosterUpdated) wpieta\" (bez NIE wpieta)",
            "OnRosterUpdated) wpieta" in w)
    dl = by_day(lines, "Marsz - konie partii (E6/K0): dzien")
    days = sorted(d for d in dl if 1 <= run_day(d, start) <= until)
    rep.add("K0-2: linia Marsz - konie partii (E6/K0) w oknie", f"{len(days)} dob (z {len(dl)} w logu)", "codziennie od wgrania E6/K0", None)
    if not days:
        return
    rows = [dl[d] for d in days]
    counting = [s for s in rows if "): liczy TAK" in s]
    bad = []
    for d in days:
        s = dl[d]
        if "): liczy TAK" not in s:
            continue
        dm = num(r"wierzchowce roznica (\d+)", s, int, 0) or 0
        dp = num(r"\(partii \d+\), juczne (\d+)", s, int, 0) or 0
        if dm or dp:
            bad.append(f"d{d}: {dm}/{dp}")
    rep.add("K0-3: licznik gry = pelne przeliczenie (CalculateCachedStats) w partiach marszu",
            f"dob z licznikiem czynnym {len(counting)}; doby z roznica (wierzchowce/juczne) {len(bad)}" + (f" [{', '.join(bad[:6])}]" if bad else ""),
            "roznica 0 w kazdej dobie z \"liczy TAK\"", (len(bad) == 0) if counting else None)
    low = sum(num(r"nizszy (\d+) \(prog 0\)", s, int, 0) or 0 for s in rows)
    high = sum(num(r"z K0 wyzszy (\d+)", s, int, 0) or 0 for s in rows)
    calls = sum(num(r"sufit tempa AI na sucho \(to samo wywolanie\): (\d+) wywolan", s, int, 0) or 0 for s in rows)
    rep.add("K0-4: sufit tempa AI z K0 nizszy niz bez K0 (na sucho, suma okna)", f"{low} z {calls} wywolan", "0", low == 0)
    a0 = [num(r"srednio bez K0 ([\d.]+)", s, float) for s in rows]
    a1 = [num(r" / z K0 ([\d.]+), z K0 wyzszy", s, float) for s in rows]
    a0 = [x for x in a0 if x is not None]; a1 = [x for x in a1 if x is not None]
    rep.add("K0-5: sufit tempa AI wyzszy z K0 (wolne konie zbrojowni pod piechure)",
            f"wyzszy {high} wywolan; srednio bez K0 {sum(a0) / len(a0):.2f} / z K0 {sum(a1) / len(a1):.2f}" if a0 and a1 else f"wyzszy {high}",
            "INFO (szybsze kolumny - styk z etapem 7)", None)
    cost = [num(r"razem ([\d.]+) ms \(prog 2 ms/dobe\)", s, float) for s in rows]
    cost = [x for x in cost if x is not None]
    # narzedzie progow zb58 (TRIAZ K0-6): prog 2 ms z projektu (KRYTYKA-E6 K0-koszt) pilnuje goracej sciezki - postfiksu ItemRoster.OnRosterUpdated
    # (SpeedPostfix tylko czyta, nie liczy Balance przy kazdej zmianie predkosci). Przeliczenie raz na dobe ("stan doby" = HorseState.Rebuild ->
    # Stables.Balance kazdej partii ze zbrojownia, plus odswiezenia po Remount/awansie) to osobny prog regresji 15 ms (W33 9.56 + 0.57, zb58 9.71 + 0.76;
    # rosnie z liczba partii). Log bez rozbicia kosztu - stary wiersz K0-6 na sumie.
    hot = [x for x in (num(r"OnRosterUpdated \d+ wywolan ([\d.]+) ms", s, float) for s in rows) if x is not None]
    once = [(num(r"stan doby ([\d.]+) ms", s, float), num(r"odswiezenia \d+ \(([\d.]+) ms\)", s, float)) for s in rows]
    once = [(a, b or 0.0) for a, b in once if a is not None]
    if hot and once:
        m = sum(hot) / len(hot)
        rep.add("K0-6a: koszt K0 - goraca sciezka (postfiks OnRosterUpdated)", f"srednio {m:.2f} ms/dobe, najwiecej {max(hot):.2f} ({len(hot)} dob)",
                "srednio <= 2 ms/dobe (prog projektu: K0 nie liczy przy kazdej zmianie)", m <= 2.0)
        tot1 = [a + b for a, b in once]
        m1 = sum(tot1) / len(tot1)
        rep.add("K0-6b: koszt K0 - przeliczenie raz na dobe (stan doby + odswiezenia)",
                f"srednio {m1:.2f} ms/dobe (stan doby {sum(a for a, _ in once) / len(once):.2f} + odswiezenia {sum(b for _, b in once) / len(once):.2f}), "
                f"najwiecej {max(tot1):.2f} ({len(once)} dob)" + (f"; razem z goraca sciezka srednio {sum(cost) / len(cost):.2f}" if cost else ""),
                "srednio <= 15 ms/dobe (prog regresji; wzorzec W33 10.1 - rosnie z liczba partii)", m1 <= 15.0)
    elif cost:
        m = sum(cost) / len(cost)
        rep.add("K0-6: koszt K0 (OnRosterUpdated + stan doby + odswiezenia)", f"srednio {m:.2f} ms/dobe, najwiecej {max(cost):.2f} ({len(cost)} dob)",
                "srednio <= 2 ms/dobe", m <= 2.0)
    st = sum(num(r"potkniecia dzis (\d+)", s, int, 0) or 0 for s in rows)
    rep.add("K0-7: potkniecia HorseState w oknie", str(st), "0", st == 0)
    s = rows[-1]
    pl, md, lm = num(r"bez modyfikatora (\d+)", s), num(r"ze stanem (\d+) \(w tym kulawe", s), num(r"w tym kulawe (\d+)", s)
    fr, un = num(r"wolne w zbrojowni (\d+)", s), num(r"bez konia (\d+)\)", s)
    rep.add("K0-8: luzaki i stan koni partii (ostatnia doba)",
            f"bez modyfikatora {pl}, ze stanem {md} (kulawe {lm}), wolne w zbrojowni {fr}, bez konia {un}", "INFO", None)
    herd = sum(num(r"nadmiar stada (\d+)", x, int, 0) or 0 for x in rows)
    herdm = sum(num(r"nadmiar stada \d+ \(ze stanem (\d+)\)", x, int, 0) or 0 for x in rows)
    wgt = sum(num(r"ponad udzwig (\d+)", x, int, 0) or 0 for x in rows)
    wgtm = sum(num(r"ponad udzwig \d+ \(ze stanem (\d+)\)", x, int, 0) or 0 for x in rows)
    rep.add("K0-9: konie porzucone przez gre (lordowie AI, DiscardItemsCampaignBehavior; suma okna)",
            f"nadmiar stada {herd} (ze stanem {herdm}), ponad udzwig {wgt} (ze stanem {wgtm})", "INFO (od F3 ujscie w ksiedze koni - patrz K1-14; log sprzed F3: ujscie bez przyczyny w ksiedze)", None)
    zw = [x for x in by_day(lines, "Zima wedlug krain (E4/1): dzien").values() if "| pasza (E6/K0, FodderFromHorseState" in x]
    if zw:
        hs = sum(num(r"pasza \(E6/K0, FodderFromHorseState \w+\): konie partii (\d+)", x, int, 0) or 0 for x in zw)
        hd = sum(num(r"\(dawniej po glowie (\d+);", x, int, 0) or 0 for x in zw)
        rep.add("K0-10: pasza zima - konie partii wobec konnych po glowie (suma dob zimy z dopiskiem)",
                f"{hs} wobec {hd} ({len(zw)} dob" + (f", {100.0 * (hs - hd) / hd:+.1f}%" if hd else "") + ")",
                "INFO (projekt: ok. -900 koni swiata; prog glodu lordow zima E4 przeliczyc w biegu B)", None)
    else:
        rep.add("K0-10: pasza zima - konie partii wobec konnych po glowie", "brak dopisku (bieg bez zimy albo log sprzed K0)", "INFO", None)

def etap5_w2(rep, lines, start, until):
    """E6/W2 (210, projekt etapu 6 v2 rozdz. 3 "E6/W2" Test): tozsamosc w biegu - zboze zdjete = ryby dodane kazdej doby (kontrola 0, +-1 sztuka na zaokraglenia),
    ryby na targach okregow rybackich > 0. Linia doby "Wioski wedlug rodzaju (210): dzien N" (dzien = doba gry - 1, okno doby kampanii 1-until jak etap5_main).
    Glod warowni i lordow bez regresji wobec testu koncowego E4 - bloki E4/6 i E4/1 (bezwzglednie)."""
    dl = by_day(lines, "Wioski wedlug rodzaju (210): dzien")
    days = sorted(d for d in dl if 1 <= run_day(d, start) <= until)
    rep.add("W2-1: linia Wioski wedlug rodzaju (210) w oknie", f"{len(days)} dob (z {len(dl)} w logu)", "codziennie od wgrania E6/W2", None)
    if not days:
        return
    rows = [dl[d] for d in days]
    on = [d for d in days if "| CZYNNE |" in dl[d]]
    off = [d for d in days if "| CZYNNE |" not in dl[d]]
    why = ""
    if off:
        m = re.search(r"\| ((?:WYLACZONE|NIECZYNNE)[^|]*)\|", dl[off[-1]])
        why = f"; ostatnia nieczynna d{off[-1]}: {m.group(1).strip() if m else '?'}"
    rep.add("W2-2: krok wiosek wedlug rodzaju CZYNNY w dobach okna", f"{len(on)} z {len(days)}{why}", "wszystkie doby (klucz HamletKindsInDistrict, ksiega wiosek)",
            len(off) == 0)
    bad = []
    ta = tb = 0.0
    for d in on:
        s = dl[d]
        a = num(r", zboza -([\d.]+)", s, float, 0.0) or 0.0
        b = num(r", ryb \+([\d.]+)", s, float, 0.0) or 0.0
        ta += a; tb += b
        if abs(a - b) > 1.0 + 0.001 * a:
            bad.append(f"d{d}: {a:.1f}/{b:.1f}")
    rep.add("W2-3: zboze zdjete = ryby dodane (tozsamosc w kazdej dobie)",
            f"suma okna zboza -{ta:.1f}, ryb +{tb:.1f}; doby z roznica ponad 1 + 0.1% {len(bad)}" + (f" [{', '.join(bad[:6])}]" if bad else ""),
            "0 dob z roznica", (len(bad) == 0) if on else None)
    nd = [num(r"okregow z rybakami (\d+)", dl[d], int, 0) or 0 for d in on]
    with_fishers = sum(1 for x in nd if x > 0)
    rep.add("W2-4: ryby z okregow rybackich > 0 (suma okna)", f"ryb +{tb:.1f} w {with_fishers} dobach z okregami z rybakami",
            "> 0, gdy sa okregi z rybakami", (tb > 0.0) if with_fishers else None)
    s = rows[-1]
    um = num(r"u srednio ([\d.]+)%", s, float)
    nm = sum(num(r"wsi bez pamieci zboza (\d+)", dl[d], int, 0) or 0 for d in on)
    ng = sum(num(r"zboze bez wywolania ryb w dobie (\d+) wsi", dl[d], int, 0) or 0 for d in on)   # recenzja W2: magazyn wsi >= 1.5 W bez ticku
    nl = num(r"okregow z rybakami (\d+)", s, int, 0)
    rep.add("W2-5: okregi z rybakami i wsie bez pamieci zboza", f"okregow (ostatnia doba) {nl}, u srednio {um}%; "
            f"wsi bez pamieci zboza (suma okna) {nm}; zboze bez wywolania ryb (wies-doby, suma okna) {ng}",
            "INFO (ryby bez dopisku - zboze bez zmian; zboze bez ryb - odczyt magazynu wsi bez ticku produkcji; kontrola W2-3 liczy pary z ticku)", None)
    st = sum(num(r"potkniecia dzis (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("W2-6: potkniecia HamletKinds w oknie", str(st), "0", st == 0)

def etap5_k1(rep, lines, start, until):
    """E6/K1 (211, projekt etapu 6 v2 rozdz. 3 "E6/K1" Test, K1-13): linia doby "Konie - smierc, lup, dobytek (E6/K1): dzien N" i pozycje K1 w "Konie (E6/0): dzien N"
    (dzien = doba gry, okno doby kampanii 1-until jak etap5_main). Reszta niewyjasniona koni: kazde 7 dob (bloki od d31) |suma| <= max(5, 1% (zrodla pierwotne + ujscia)).
    Od F9b wiersze poprawki F3 (K1-11..K1-14 - konie mieszczan i konie porzucone przez gre w ksiedze koni) w _k1_f3."""
    dl = by_day(lines, "Konie - smierc, lup, dobytek (E6/K1): dzien")
    days = sorted(d for d in dl if 1 <= run_day(d, start) <= until)
    rep.add("K1-1: linia Konie - smierc, lup, dobytek (E6/K1) w oknie", f"{len(days)} dob (z {len(dl)} w logu)", "codziennie od wgrania E6/K1", None)
    if not days:
        return
    rows = [dl[d] for d in days]
    off = [d for d in days if " | CZYNNE:" not in dl[d]]
    rep.add("K1-2: K1 CZYNNE w dobach okna", f"{len(days) - len(off)} z {len(days)}" + (f"; ostatnia nieczynna d{off[-1]}" if off else ""),
            "wszystkie doby (klucze HorsesDieOnlyKilled, SpoilsOfBrokenParties, VeteranKeepsHorse, NewPartyHorsesFromSeat, TroopSwapNeedsHorse)", len(off) == 0)
    rest = {}
    for d, s in by_day(lines, "Konie (E6/0): dzien").items():
        m = re.search(r"reszta niewyjasniona [\d/-]+ \(razem (-?\d+), mianownik zrodla \+ ujscia (\d+)", s)
        if m:
            rest[run_day(d, start)] = (int(m.group(1)), int(m.group(2)))
    bad, blocks = [], 0
    lo = 31
    while lo + 6 <= until:
        blk = [rest[x] for x in range(lo, lo + 7) if x in rest]
        if len(blk) == 7:
            blocks += 1
            sr = sum(a for a, _ in blk)
            lim = max(5.0, 0.01 * sum(b for _, b in blk))
            if abs(sr) > lim:
                bad.append(f"d{lo}-{lo + 6}: {sr} (prog {lim:.0f})")
        lo += 7
    rep.add("K1-3: reszta niewyjasniona koni - bloki 7 dob od d31 (|suma| <= max(5, 1% zrodla + ujscia))",
            f"blokow pelnych {blocks}, ponad prog {len(bad)}" + (f" [{', '.join(bad[:6])}]" if bad else ""),
            "0 blokow ponad prog (linia Konie (E6/0) przy Stage6MeasureLog; od F3 reszta po ujsciach mieszczanie + porzucone przez gre)",
            (len(bad) == 0) if blocks else None)
    # narzedzie progow zb58 (TRIAZ K1-4): kon z puli weteranow dziala dopiero po siewie puli (HorseFate.VetHorseOn = VeteranKeepsHorse && PeopleBook.VetLive,
    # VetLive wymaga _vSown; siew w pierwszym ticku doby kampanii - linia "Weterani (E4/10): siew dnia N"). Najem z karczm przed siewem idzie stara sciezka
    # 160 (RecruitKit: vetHorse = false -> kon i rzad z wzorca) - dorobek startowy jak karawany startowe, nie regula biegu. Prog 0 dotyczy dob po siewie
    # (linie K1 z dniem > N); doby do siewu - INFO. Log bez linii siewu (wczytany zapis) - liczy sie cale okno.
    sow = None
    for x in lines:
        if x.startswith("Weterani (E4/10): siew dnia "):
            sow = num(r"siew dnia (\d+)", x)
            break
    pre = [d for d in days if sow is not None and d <= sow]
    tpl = sum(num(r"kon z wzorca (\d+)", dl[d], int, 0) or 0 for d in days if d not in pre)
    rep.add("K1-4: kon najemnika z wzorca (suma okna po siewie puli weteranow)", str(tpl), "0 (VeteranKeepsHorse - kon z puli weteranow)", tpl == 0)
    if pre:
        tpl0 = sum(num(r"kon z wzorca (\d+)", dl[d], int, 0) or 0 for d in pre)
        rep.add("K1-4a: kon najemnika z wzorca przed siewem puli weteranow", f"{tpl0} (siew dnia {sow}, linii K1 do siewu {len(pre)})",
                "INFO (karczmy jak w grze - dorobek startowy, sciezka 160: kon i rzad z wzorca)", None)
    nw = sum(num(r", bez miejsca (\d+)", x, int, 0) or 0 for x in rows)
    left = sum(num(r"zostalo w taborze \(unikaty, nie-towar\) (\d+)", x, int, 0) or 0 for x in rows)
    skip = sum(num(r"pominiete partie bez niszczyciela \(inne mody, dostawy BK\) (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("K1-5: dobytek rozbitych bez miejsca (suma okna)", f"{nw}; zostalo w taborze (unikaty - UniqueSpoils, nie-towar) {left}, pominiete partie {skip}",
            "0 (przepadlo z rozbitymi - towary i konie)", nw == 0)
    miss = sum(num(r"brak u pokonanych (\d+)", x, int, 0) or 0 for x in rows)
    mv = sum(num(r"lup DTE: dopisane zwyciezcom (\d+)", x, int, 0) or 0 for x in rows)
    cp = sum(num(r"kopie zdjete u pokonanych (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("K1-6: lup koni DTE jako przeniesienie (suma okna)", f"dopisane zwyciezcom {mv}, kopie zdjete u pokonanych {cp}, bez pokrycia {miss}",
            "bez pokrycia 0", miss == 0)

    def cats(pat, x):
        m = re.search(pat, x)
        return sum(int(v) for v in m.group(1).split("/")) if m else 0
    dm = sum(cats(r"polegle w misji \(zdjete ze zbrojowni\) ([\d/]+)", x) for x in rows)
    da = sum(cats(r"polegle w autobitwie ([\d/]+)", x) for x in rows)
    kr = sum(num(r"zabitych jezdzcow (\d+)", x, int, 0) or 0 for x in rows)
    s = rows[-1]
    w = num(r"\| W ([\d.]+) \(obserwacji", s, float)
    ob = num(r"\(obserwacji (\d+)/", s, int)
    rep.add("K1-7: polegle konie (suma okna) i W", f"misja {dm}, autobitwa {da} (zabitych jezdzcow {kr}, srednio {da / max(1, len(rows)):.0f}/d); W {w} (obserwacji {ob})",
            "INFO (projekt: ok. 40-150 koni/d; w autotescie W = 1.0 - misji nie ma)", None)
    vin = sum(num(r"pula weteranow: \+(\d+)", x, int, 0) or 0 for x in rows)
    vh = sum(num(r"najemnik: kon z puli (\d+)", x, int, 0) or 0 for x in rows)
    vn = sum(num(r"najemnik: kon z puli \d+, bez konia (\d+)", x, int, 0) or 0 for x in rows)
    vs = num(r"\(najem \d+, na polki \d+\), stan (\d+)", s, int)
    rep.add("K1-8: pula koni weteranow (suma okna)", f"do puli {vin}, najem z koniem z puli {vh}, najem konnego bez konia {vn}, stan (ostatnia doba) {vs}", "INFO", None)
    gh = sum(num(r"z polki konie (\d+)", x, int, 0) or 0 for x in rows)
    gf = sum(num(r"z polki konie \d+, zywnosc (\d+)", x, int, 0) or 0 for x in rows)
    gnh = sum(num(r"brak koni (\d+)", x, int, 0) or 0 for x in rows)
    gg = sum(num(r"zloto do siedzib (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("K1-9: dary startowe nowej druzyny z polki siedziby (suma okna)", f"konie {gh}, zywnosc {gf}, brak koni {gnh}, zloto {gg}; z niczego 0 z definicji",
            "INFO (dary z niczego 0)", None)
    rh = sum(num(r"zamiany ROT na konnego: z koniem (\d+)", x, int, 0) or 0 for x in rows)
    rf = sum(num(r"z koniem \d+, na pieszego (\d+)", x, int, 0) or 0 for x in rows)
    rk = sum(num(r"zostal konny bez konia (\d+)", x, int, 0) or 0 for x in rows)
    st = sum(num(r"potkniecia dzis (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("K1-10: zamiany ROT na konnego (suma okna) i potkniecia HorseFate", f"z koniem {rh}, na pieszego {rf}, konny bez konia {rk}; potkniecia {st}",
            "potkniecia 0 (zamiany - INFO)", st == 0)
    _k1_f3(rep, lines, start, until)


def _k1_f3(rep, lines, start, until):
    """Narzedzie progow F9b (F3 krok 1 - konie mieszczan i konie porzucone przez gre w ksiedze koni, TYLKO POMIAR): wiersze K1-11..K1-14 z linii
    "Konie (E6/0): dzien N" (okno d31-until, jak K1-3). Czlon F3 linii: "| ujscia poza K1 (F3, pomiar): mieszczanie miast a/b/c/d szt. za .. zl,
    mieszczanie zamkow .. (...; nawiasy konsumpcji N, bez pelnej wyceny M; kontrola ksiegi towarow: konie w ramce konsumpcji T, roznica R | brak
    (ksiega towarow bez linii)), porzucone przez gre u lordow a/b/c/d/e (nadmiar stada H, ponad udzwig W)". Log sprzed F3 (bez czlonu) - K1-12..K1-14
    INFO "brak linii"; K1-11 liczy sie zawsze (pole "reszta niewyjasniona" jest od E6/0). Linia "stan wyjsciowy" (bez reszty) poza wierszami."""
    kl = {}
    for d, s in by_day(lines, "Konie (E6/0): dzien").items():
        kl[run_day(d, start)] = s
    w31 = [x for x in sorted(kl) if 31 <= x <= until and " | reszta niewyjasniona " in kl[x]]
    f3 = [x for x in w31 if "| ujscia poza K1 (F3, pomiar): " in kl[x]]
    rr = []
    for x in w31:
        m = re.search(r"reszta niewyjasniona (-?\d+)/(-?\d+)/(-?\d+)/(-?\d+)/(-?\d+) \(razem", kl[x])
        if m:
            rr.append([int(v) for v in m.groups()])
    if rr:
        n = float(len(rr))
        a = [sum(r[i] for r in rr) / n for i in range(5)]
        rep.add("K1-11: reszta niewyjasniona koni wedlug kategorii (srednio na dobe, d31-until)",
                f"zwykly {a[0]:+.1f}, bojowy {a[1]:+.1f}, szlachetny {a[2]:+.1f}; juczny {a[3]:+.1f}, egzotyczny {a[4]:+.1f} ({len(rr)} dob)"
                + ("" if f3 else " [log sprzed F3 - reszta bez ujsc mieszczanie + porzucone]"),
                "INFO (od F3 zwykly i bojowy blisko 0, szlachetny bez oczekiwania; przed F3: -119.6 / -28.9 / -3.0, W33 -129.8 / -32.1 / -3.1)", None)
    else:
        rep.add("K1-11: reszta niewyjasniona koni wedlug kategorii (d31-until)", "brak linii Konie (E6/0) z reszta w oknie", "INFO", None)
    if not f3:
        rep.add("K1-12..K1-14: konie mieszczan i konie porzucone przez gre w ksiedze koni (F3)",
                "brak linii (log sprzed F3 - bez czlonu \"ujscia poza K1 (F3, pomiar)\" w linii Konie (E6/0))" if w31 else "okno nie siega d31",
                "czlon jest od F3 (Stage6MeasureLog)", None)
        return
    # ---- K1-12 (INFO): sztuki i zloto mieszczan wedlug kategorii targu, miasta i zamki osobno; udzial w produkcji stadnin (kategorie 1-4)
    fre = re.compile(r"mieszczanie miast (\d+)/(\d+)/(\d+)/(\d+) szt\. za (\d+)/(\d+)/(\d+)/(\d+) zl, mieszczanie zamkow (\d+)/(\d+)/(\d+)/(\d+) szt\. za "
                     r"(\d+)/(\d+)/(\d+)/(\d+) zl")
    tn, tg, cn, cg, prod, nf = [0] * 4, [0] * 4, [0] * 4, [0] * 4, [0] * 4, 0
    for x in f3:
        m = fre.search(kl[x])
        if not m:
            continue
        g = [int(v) for v in m.groups()]
        nf += 1
        for i in range(4):
            tn[i] += g[i]; tg[i] += g[4 + i]; cn[i] += g[8 + i]; cg[i] += g[12 + i]
        mp = re.search(r"zrodla: stadniny wsi (\d+)/(\d+)/(\d+)/(\d+)/(\d+)", kl[x])
        if mp:
            for i in range(4):
                prod[i] += int(mp.group(i + 1))
    if nf:
        k = float(nf)
        pcs, gold = sum(tn) + sum(cn), sum(tg) + sum(cg)

        def row(v):
            return "/".join(f"{q / k:.1f}" for q in v)
        shr = "/".join((f"{100.0 * (tn[i] + cn[i]) / prod[i]:.0f}%" if prod[i] else "-") for i in range(4))
        rep.add("K1-12: konie mieszczan wedlug kategorii targu (zwykly/bojowy/szlachetny/juczny; srednio na dobe, d31-until)",
                f"miasta {row(tn)} szt. za {sum(tg) / k:.0f} zl/d, zamki {row(cn)} szt. za {sum(cg) / k:.0f} zl/d; razem {pcs / k:.1f} szt./d"
                + (f", srednia cena {gold / float(pcs):.0f} zl" if pcs else "") + f"; udzial w produkcji stadnin {shr} ({nf} dob)",
                "INFO (liczby dla kroku 2 F3; gorna granica TRIAZ 119 / 29 / 2.8 szt./d; miedzy biegami porownywac sztuki - zloto tylko przy tym samym cenniku koni E8/C)",
                None)
    else:
        rep.add("K1-12: konie mieszczan wedlug kategorii targu (d31-until)", "brak pola mieszczan w czlonie F3", "INFO", None)
    # ---- K1-13 (wiazacy): (i) nawias konsumpcji czynny w kazdej dobie i 0 wierszy bez pelnej wyceny, (ii) roznica z licznikiem ksiegi towarow 0
    # (doba bez kontroli = INFO; doba zaraz po dobie bez kontroli albo bez linii - poza kontrola: licznik ksiegi towarow obejmuje wtedy wiecej niz dobe),
    # (iii) 0 dob z "nie podpiete (w reszcie): mieszczanie" (tylko linie Konie (E6/0))
    cre = re.compile(r"kontrola ksiegi towarow: konie w ramce konsumpcji (-?\d+), roznica (-?\d+)")
    nobr, part, diff, chk, nochk, skip, bad_d = [], 0, 0, 0, 0, 0, []
    for x in f3:
        m = re.search(r"nawiasy konsumpcji (\d+), bez pelnej wyceny (\d+)", kl[x])
        if not m or int(m.group(1)) <= 0:
            nobr.append(x)
        if m:
            part += int(m.group(2))
        c = cre.search(kl[x])
        if not c:
            nochk += 1
            continue
        if (x - 1) not in kl or not cre.search(kl[x - 1]):
            skip += 1
            continue
        chk += 1
        if int(c.group(2)) != 0:
            diff += abs(int(c.group(2)))
            bad_d.append(f"d{x}: {int(c.group(2)):+d}")
    unh = [x for x in f3 if "nie podpiete (w reszcie): mieszczanie" in kl[x]]
    fail = bool(nobr) or part != 0 or diff != 0 or bool(unh)
    rep.add("K1-13: pomiar koni mieszczan czynny i zgodny z ksiega towarow (d31-until)",
            f"dob bez nawiasu konsumpcji {len(nobr)} z {len(f3)}" + (f" (pierwsza d{nobr[0]})" if nobr else "") + f", wierszy bez pelnej wyceny {part}; "
            f"kontrola ksiegi towarow: dob porownanych {chk}, suma |roznica| {diff}" + (f" [{', '.join(bad_d[:6])}]" if bad_d else "")
            + f", bez kontroli {nochk}, pominiete po przerwie {skip}; dob z \"nie podpiete: mieszczanie\" {len(unh)}",
            "nawias > 0 w kazdej dobie, bez pelnej wyceny 0, suma |roznica| 0, 0 dob \"nie podpiete: mieszczanie\" (bez dob z kontrola - INFO)",
            False if fail else (True if chk > 0 else None))
    # ---- K1-14 (wiazacy): porzucone wedlug kategorii = nadmiar stada + ponad udzwig, a te dwa = liczniki linii K0 tej samej doby (etykieta K0 = N - 1);
    # porownanie z K0 tylko dla doby N, ktora ma linie Konie (E6/0) doby N - 1 (po przerwie licznik ksiegi obejmuje wiecej niz dobe)
    k0 = {}
    for d, s in by_day(lines, "Marsz - konie partii (E6/K0): dzien").items():
        k0[run_day(d, start)] = s
    dre = re.compile(r"porzucone przez gre u lordow (\d+)/(\d+)/(\d+)/(\d+)/(\d+) \(nadmiar stada (\d+), ponad udzwig (\d+)\)")
    bad, cmpn, seen, th, tw = [], 0, 0, 0, 0
    for x in f3:
        m = dre.search(kl[x])
        if not m:
            continue
        g = [int(v) for v in m.groups()]
        seen += 1
        th += g[5]; tw += g[6]
        if sum(g[:5]) != g[5] + g[6]:
            bad.append(f"d{x}: kategorie {sum(g[:5])} wobec {g[5]} + {g[6]}")
            continue
        ks = k0.get(x - 1)
        if (x - 1) not in kl or not ks:
            continue
        h, w = num(r"nadmiar stada (\d+)", ks, int), num(r"ponad udzwig (\d+)", ks, int)
        if h is None or w is None:
            continue
        cmpn += 1
        if (h, w) != (g[5], g[6]):
            bad.append(f"d{x}: ksiega {g[5]}/{g[6]} wobec K0 {h}/{w}")
    rep.add("K1-14: konie porzucone przez gre u lordow - kategorie = nadmiar stada + ponad udzwig = liczniki K0 (d31-until)",
            f"dob z polem {seen}, porownanych z linia K0 {cmpn}, niezgodnych {len(bad)}" + (f" [{', '.join(bad[:5])}]" if bad else "")
            + f"; suma okna: nadmiar stada {th}, ponad udzwig {tw}" + (f" ({(th + tw) / float(seen):.1f}/d)" if seen else ""),
            "0 niezgodnych (suma kategorii = nadmiar stada + ponad udzwig; oba = linia Marsz - konie partii (E6/K0) doby N - 1)",
            (len(bad) == 0) if seen else None)

def etap5_k2(rep, lines, start, until):
    """E6/K2 (212, projekt etapu 6 v2 rozdz. 3 "E6/K2" Test): segment "zapas koni wedlug kategorii (E6/K2)" w linii doby "Konie AI (175): dzien N"
    (dzien = doba gry, okno doby kampanii 1-until jak etap5_main). Nadwyzka ponad 1.5 x zapas po postoju w miescie liczona w d91-until (krotsze okno - cale)."""
    tag = "zapas koni wedlug kategorii (E6/K2):"
    seg = {}
    for d, s in by_day(lines, "Konie AI (175): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until and tag in s:
            seg[rd] = s.split(tag, 1)[1].split(" | ", 1)[0]
    rep.add("K2-1: segment zapasu koni (E6/K2) w linii Konie AI (175)", f"{len(seg)} dob", "codziennie od wgrania E6/K2 (linia przy Army175Measure)", None)
    hook = [s for s in lines if s.startswith("SpareHorses (E6/K2, 212):")]
    if hook:
        rep.add("K2-2: wpiecia handlu koni gry (PartiesBuyHorseCampaignBehavior)", hook[-1][:200], "bez BRAK i bez bledu wpiecia",
                ("BRAK" not in hook[-1]) and ("blad wpiecia" not in hook[-1]))
    if not seg:
        return
    days = sorted(seg)
    off = [x for x in days if not seg[x].startswith(" CZYNNE")]
    rep.add("K2-3: E6/K2 CZYNNE w dobach okna", f"{len(days) - len(off)} z {len(days)}" + (f"; ostatnia nieczynna d{off[-1]}" if off else ""),
            "wszystkie doby (klucz AiSellsSpareHorses)", len(off) == 0)
    lo = 91 if until >= 91 and any(x >= 91 for x in days) else 1
    win = [seg[x] for x in days if x >= lo]
    over = sum(num(r"ponad 1\.5 x zapas zostalo (\d+)", x, int, 0) or 0 for x in win)
    riders = sum(num(r"zostalo \d+ przy (\d+) konnych", x, int, 0) or 0 for x in win)
    vis = sum(num(r"postoje lordow w miescie (\d+)", x, int, 0) or 0 for x in win)
    pct = 100.0 * over / riders if riders else 0.0
    rep.add(f"K2-4: nadwyzka ponad 1.5 x zapas kategorii po postoju w miescie (d{lo}-{until})",
            f"{over} przy {riders} konnych ({pct:.2f}%), postojow {vis}", "<= 2% konnych (kasa miasta bez nadwyzki zostawia konie - INFO w K2-6)",
            (pct <= 2.0) if riders else None)
    rows = [seg[x] for x in days]
    pump = sum(num(r"zakup i sprzedaz tej samej kategorii w 7 dobach (\d+)", x, int, 0) or 0 for x in rows)
    stu = sum(num(r"potkniecia dzis (\d+)", x, int, 0) or 0 for x in rows)

    def cats(pat, x):
        m = re.search(pat, x)
        return [int(v) for v in m.group(1).split("/")] if m else [0, 0, 0]

    def add3(a, b):
        return [a[i] + b[i] for i in range(3)]
    sold, gold, arm, nob, gb, gs = (sum(num(p, x, int, 0) or 0 for x in rows) for p in (
        r"sprzedane z nadwyzki (\d+)", r"sprzedane z nadwyzki \d+ za (\d+)", r"ze zbrojowni (\d+)", r"kasa miasta bez nadwyzki (\d+)",
        r"zakupy/sprzedaze gry pominiete (\d+)", r"zakupy/sprzedaze gry pominiete \d+/(\d+)"))
    bought = [0, 0, 0]
    for x in rows:
        bought = add3(bought, cats(r"kupione do zapasu ([\d/]+)", x))
    # narzedzie progow zb58 (TRIAZ K2-5): licznik pompy zawyza - SpareHorses.NoteVisit dolicza CALA sprzedaz kategorii, gdy partia kupila choc 1 konia tej
    # kategorii w 7 dobach (_pump += soldK[k]), a zakup to srednio 2-3 konie; kon idzie tabor -> polka miasta za zloto kasy miasta (suma koni i zlota bez
    # zmian). Do poprawki licznika (min(sprzedane, kupione w 7 dobach) - nowa linia logu, osobny krok) pompa jest INFO z udzialem w koniach kupionych do
    # zapasu; po poprawce prog: pompa <= 2% kupionych do zapasu. Potkniecia zostaja wiazace.
    rep.add("K2-5a: potkniecia SpareHorses (suma okna)", f"{stu}", "0", stu == 0)
    nb = sum(bought)
    rep.add("K2-5b: pompa koni (zakup i sprzedaz tej samej kategorii w partii w 7 dobach; suma okna)",
            f"pompa {pump}" + (f" = {100.0 * pump / nb:.1f}% z {nb} kupionych do zapasu" if nb else "") + (f" ({100.0 * pump / sold:.1f}% z {sold} sprzedanych)" if sold else ""),
            "INFO do poprawki licznika (dolicza cala sprzedaz kategorii po zakupie 1 konia); po poprawce <= 2% koni kupionych do zapasu", None)
    rep.add("K2-6: sprzedaz nadmiaru i kupno do zapasu (suma okna)", f"sprzedane {sold} za {gold} (ze zbrojowni {arm}; kasa miasta bez nadwyzki {nob} postojow), "
            f"kupione do zapasu zwykle/bojowe/szlachetne {'/'.join(map(str, bought))}; handel koni gry pominiety: zakupy {gb}, sprzedaze {gs} postojow",
            "INFO (projekt: sprzedaze gry 0 - pominiete)", None)


def etap5_k5(rep, lines, start, until):
    """E6/K5 (213, projekt etapu 6 v2 rozdz. 3 "E6/K5" Test): linia doby "Juczne (213): dzien N" (dzien = doba gry, okno doby kampanii 1-until jak etap5_main).
    Wiazace: juczne z niczego 0 (suma okna), partie i sztuki poza CreateCaravanParty 0 we wszystkich dobach (F2-1 - od F2 takze karawany startowe
    przechodza przez CreatePost), karawany policzone przez K5 = "nowe karawany: N" linii "Obieg: notable i karawany" (doba wczesniej; F2-2), juczne
    kupione z targu > 0 i <= cel w kazdej dobie (F2-3), 0 linii "ERROR in PackMarket." (F2-4), potkniecia 0, wpiecia bez BRAK; reszta INFO (F2-5
    karawany startowe, K5-7 zakup i braki, F2-6 targ koni jucznych)."""
    rows = {}
    for d, s in by_day(lines, "Juczne (213): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rows[rd] = s
    rep.add("K5-1: linia Juczne (213)", f"{len(rows)} dob", "codziennie od wgrania E6/K5", None)
    hook = [s for s in lines if s.startswith("PackMarket (E6/K5, 213):")]
    if hook:
        rep.add("K5-2: wpiecia (InitializeCaravanOnCreation, CreateCaravanParty VeryLow, model pojemnosci)", hook[-1][:200], "bez BRAK i bez bledu wpiecia",
                ("BRAK" not in hook[-1]) and ("blad wpiecia" not in hook[-1]))
    if not rows:
        return
    days = sorted(rows)
    off = [x for x in days if "| CZYNNE |" not in rows[x]]
    rep.add("K5-3: E6/K5 CZYNNE w dobach okna", f"{len(days) - len(off)} z {len(days)}" + (f"; ostatnia nieczynna d{off[-1]}" if off else ""),
            "wszystkie doby (klucz PackAnimalsFromMarket)", len(off) == 0)
    win = [rows[x] for x in days]

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in win)
    left = tot(r", z niczego (-?\d+) \(gra dala")
    given, removed = tot(r"\(gra dala (\d+)"), tot(r"\(gra dala \d+, zdjete (\d+)")
    # narzedzie progow F9b (F2, K5-4): w wartosci roznica "gra dala" - "zdjete" i karawany morskie (zdjete bez zakupu) - z niczego > 0 przy samych
    # morskich (bez sierot spoza CreateCaravanParty) to wskazanie na krok 2 poprawki K5
    naval, naval_off = tot(r"\| morskie (\d+) \(zdjete"), tot(r"\| morskie \d+ \(zdjete (\d+) bez zakupu\)")
    orph, orph_n = tot(r"poza CreateCaravanParty (\d+) partii"), tot(r"poza CreateCaravanParty \d+ partii, (\d+) sztuk")
    rep.add("K5-4: juczne nowych karawan z niczego (suma okna)",
            f"{left} (gra dala {given}, zdjete {removed}, roznica {given - removed}; morskie {naval} karawan, zdjete bez zakupu {naval_off})"
            + ("; z niczego przy karawanach morskich bez sierot - wskazanie na krok 2 poprawki K5" if left > 0 and naval > 0 and orph == 0 else ""), "0", left == 0)
    # narzedzie progow zb58 (TRIAZ K5-4/K5-5): K5(a) nie zadzialalo w zadnym biegu (slownik _pend po partii przed nadaniem Id - CreatePost nie znajduje
    # wpisu), a stary K5-5 "nowe z na sucho" byl pusty (przy wlaczonym kluczu zawsze 100%, przy 0 z 0 - INFO), wiec blad przeszedl dwa biegi.
    # K5-4b: partie, ktorych InitializeCaravanOnCreation nie przeszlo przez CreatePost ("poza CreateCaravanParty N partii") - 0 poza pierwsza linia
    # kampanii (karawany startowe - stan wyjsciowy). K5-5: karawany policzone przez CreatePost = "nowe karawany: N" z linii "Obieg: notable i karawany"
    # (finalizer O17 na tej samej metodzie; etykieta Juczne o 1 dobe pozniej). Skladniki z kodu PackMarket.CreatePost: nowe (_new - morskie sa JUZ w nim,
    # _naval liczone po _new++), startowe (_start), przy wylaczonym kluczu (_off), konwoje DTE (_dte) - TRIAZ pisal "+ morskie", to liczyloby je dwa razy.
    # narzedzie progow F9b (F2-1): od F2 (slownik _pend po referencji partii) takze karawany startowe przechodza przez CreatePost (pole "startowe N z M
    # jucznymi gry"), wiec "poza CreateCaravanParty" ma byc 0 partii i 0 sztuk we WSZYSTKICH dobach okna - razem z pierwsza linia kampanii, ktora F9a
    # pomijal (przed F2 karawany startowe byly sierotami). Jedna regula na jedno zjawisko: wiersz F9a K5-4b jest teraz F2-1.
    first = days[0] if days[0] <= 2 else None
    tail = [x for x in days if x != first]
    orph0 = (num(r"poza CreateCaravanParty (\d+) partii", rows[first], int, 0) or 0) if first is not None else None
    rep.add("K5-4b (F2-1): nowe karawany poza CreateCaravanParty (partii / sztuk; suma wszystkich dob okna)",
            f"{orph} partii / {orph_n} sztuk w {len(days)} dobach" + (f"; w tym pierwsza linia kampanii (karawany startowe) {orph0} partii" if orph0 is not None else ""),
            "0 / 0 (kazda nowa karawana, takze startowa, przechodzi przez CreatePost; okno d2-120: a589def 1307 / 13622, W33 1404 / 14603 - w pelnych 120 "
            "liniach 1315 / 13739 i 1408 / 14649)", orph == 0 and orph_n == 0)
    o17 = {}
    for d, s in by_day(lines, "Obieg: notable i karawany: dzien").items():
        v = num(r"\| nowe karawany: (\d+)", s, int)
        if v is not None:
            o17[run_day(d, start)] = v
    pair = [x for x in tail if (x - 1) in o17]
    seen = sum((num(r"nowe karawany (\d+) \(na sucho", rows[x], int, 0) or 0) + (num(r"; startowe (\d+) z", rows[x], int, 0) or 0)
               + (num(r"przy wylaczonym kluczu (\d+) z", rows[x], int, 0) or 0) + (num(r"\| konwoje DTE (\d+)", rows[x], int, 0) or 0) for x in pair)
    exp = sum(o17[x - 1] for x in pair)
    rep.add("K5-5 (F2-2): nowe karawany policzone przez K5 wobec linii Obieg: notable i karawany (suma okna, doba Juczne = doba Obiegu + 1)",
            f"{seen} z {exp} ({len(pair)} dob z para linii)", "rowne (nowe z morskimi + startowe po pierwszej linii + przy wylaczonym kluczu + konwoje DTE; "
            "wyjatek: karawana zadania gracza Caravan Ambush jest w Obiegu, nie w K5 - w biegu automatycznym 0)", (seen == exp) if pair else None)
    stu = tot(r"potkniecia dzis (\d+)")
    rep.add("K5-6: potkniecia (suma okna)", f"{stu}", "0", stu == 0)
    bought, paid, target, short = tot(r"kupily (\d+) za"), tot(r"kupily \d+ za (\d+)"), tot(r"\(cel (\d+);"), tot(r", brak (\d+) \(")
    zero, dte, dte_n = tot(r"kapital 0 przy tworzeniu - karawany gracza (\d+)"), tot(r"\| konwoje DTE (\d+)"), tot(r"\| konwoje DTE \d+ - juczne gry zostaja (\d+)")
    # narzedzie progow F9b (F2-3, F2-4): zakup K5(a) zyje - w oknie kupiono > 0 jucznych za > 0 zl i zadna doba nie kupila ponad cel (przed F2 slownik
    # _pend gubil kazda partie: 0 za 0 w obu biegach); 0 linii bledu PackMarket. Okno bez nowych karawan (K5 i Obieg 0) - INFO.
    newc, obg = tot(r"nowe karawany (\d+) \(na sucho"), sum(o17.get(x - 1, 0) for x in days)
    over = [x for x in days if (num(r"kupily (\d+) za", rows[x], int, 0) or 0) > (num(r"\(cel (\d+);", rows[x], int, 0) or 0)]
    rep.add("F2-3: juczne nowych karawan kupione z targu (suma okna) i zakup <= cel w kazdej dobie",
            f"kupione {bought} za {paid} zl (cel {target}); dob z zakupem ponad cel {len(over)}" + (" [" + ", ".join(f"d{x}" for x in over[:6]) + "]" if over else "")
            + f"; nowych karawan: K5 {newc}, linia Obieg {obg}",
            "kupione > 0 sztuk i > 0 zl, zadna doba ponad cel (a589def i W33: 0 za 0 - zakup K5(a) nie dzialal)",
            (bought > 0 and paid > 0 and not over) if (newc > 0 or obg > 0) else None)
    perr = [x for x in lines if x.startswith("ERROR in PackMarket.")]
    rep.add("F2-4: bledy PackMarket (linie ERROR in PackMarket.)", f"{len(perr)}" + (f" (pierwszy: {perr[0][:160]})" if perr else ""), "0", len(perr) == 0)
    if first is not None:
        ms_ = re.search(r"startowe (\d+) z (\d+) jucznymi gry", rows[first])
        rep.add("F2-5: karawany startowe w pierwszej linii kampanii", f"{ms_.group(1)} z {ms_.group(2)} jucznymi gry (d{first})" if ms_ else "brak pola",
                "INFO (nowa kampania od F2: ok. 364 z ok. 5100; log sprzed F2: 0 z 0 - startowe byly poza CreateCaravanParty)", None)
    else:
        rep.add("F2-5: karawany startowe w pierwszej linii kampanii", "okno bez pierwszej doby kampanii (wczytany zapis: 0 z 0)", "INFO", None)
    last = rows[days[-1]]
    under, foot = num(r"luzakow pod jukami (\d+)", last, int, 0) or 0, num(r"pod piechurem albo jencem (\d+)", last, int, 0) or 0

    def part(ds):
        def t_(pat):
            return sum(num(pat, rows[x], int, 0) or 0 for x in ds)
        b, c = t_(r"kupily (\d+) za"), t_(r"\(cel (\d+);")
        full, some, none = t_(r"; pelne (\d+), czesciowo"), t_(r", czesciowo (\d+), bez jucznych"), t_(r", bez jucznych (\d+)\)")
        sh, z0, nt, es = (t_(r", brak (\d+) \("), t_(r"kapital 0 przy tworzeniu - karawany gracza (\d+)"), t_(r"nie miasto albo oblezone (\d+)"),
                          t_(r"polka bez jucznych w budzecie (\d+)"))
        return (f"kupione {b} z celu {c}" + (f" ({100.0 * b / c:.0f}%)" if c else "") + f", pelne {full} / czesciowo {some} / bez jucznych {none}, "
                f"brak {sh} (kapital 0 {z0}, nie miasto albo oblezone {nt}, polka bez jucznych w budzecie {es})")
    d231, rest = [x for x in days if 2 <= x <= 31], [x for x in days if x > 31]
    rep.add("K5-7: zakup jucznych, brak i udzwig (suma okna; udzwig - ostatnia doba)",
            f"kupione {bought} za {paid} (cel {target}, brak {short}; kapital 0 - gracz {zero}; morskie {naval}; konwoje DTE {dte} - juczne gry zostaja {dte_n}); "
            + (f"doby 2-31: {part(d231)}; " if d231 else "") + (f"doby 32-{days[-1]}: {part(rest)}; " if rest else "")
            + f"luzakow pod jukami {under}, pod piechurem albo jencem {foot} (d{days[-1]})",
            "INFO (utarg kupcow - linia Kupcy/obieg; od F2 oczekiwane: kapital 0 ok. 21 - karawany notabli bez kapitalu, nie miasto do ok. 35 - kupno lordow BK "
            "w zamkach i wsiach, konwoje DTE ok. 146 / ok. 1320 sztuk na 120 dob - juczne z niczego poza K5-4)", None)
    # F2-6 (INFO, targ koni): czwarta liczba (juczne) z "polki miast i zamkow" i z "reszta niewyjasniona" linii "Konie (E6/0)" oraz czwarty mnoznik
    # linii "Hodowla (220)" - nowy popyt karawan na juczne (ok. 61/d) ma zdjac przyrost stosu jucznych na targach. Doba = dzien ksiegi (etykieta
    # linii - 1, jak "Pieniadz swiata" tego samego ticku) - tak licza liczby odniesienia wpisu F2 (doba 2 = pierwsza linia z reszta, rozruch)
    kon = {}
    for d, s in by_day(lines, "Konie (E6/0): dzien").items():
        if 1 <= run_day(d, start) - 1 <= until:
            kon[run_day(d, start) - 1] = s
    shelf = {x: num(r"polki miast i zamkow -?\d+/-?\d+/-?\d+/(-?\d+)/", kon[x], int) for x in kon}
    shelf = {x: v for x, v in shelf.items() if v is not None}
    rst = {x: num(r"reszta niewyjasniona -?\d+/-?\d+/-?\d+/(-?\d+)/", kon[x], int) for x in kon}
    rst = {x: v for x, v in rst.items() if v is not None}
    mul = None
    for d, s in sorted(by_day(lines, "Hodowla (220): dzien").items()):
        if 1 <= run_day(d, start) <= until:
            v = num(r"mnozniki x[\d.]+/x[\d.]+/x[\d.]+/x([\d.]+)", s, float)
            mul = v if v is not None else mul
    if shelf or rst:
        sd = sorted(shelf)
        a = 30 if 30 in shelf else (sd[0] if sd else None)
        r3 = [rst[x] for x in sorted(rst) if x >= 3]
        rep.add("F2-6: targ koni jucznych - polki miast i zamkow, reszta niewyjasniona, mnoznik hodowli (linie Konie (E6/0) i Hodowla (220))",
                (f"polki d{a} {shelf[a]} -> d{sd[-1]} {shelf[sd[-1]]}" if sd else "polki: brak pola")
                + (f"; reszta niewyjasniona jucznych suma dob 3-{max(rst)} {sum(r3):+d} ({sum(r3) / float(len(r3)):+.1f}/d)" if r3 else "; reszta: brak dob od 3")
                + (f", doba 2 osobno {rst[2]:+d} (rozruch)" if 2 in rst else "") + (f"; mnoznik hodowli jucznych x{mul:.2f}" if mul is not None else ""),
                "INFO (doba = dzien ksiegi; a589def: polki 1768 -> 5138, reszta +3748, doba 2 +4110, mnoznik 1.00; W33: 1922 -> 3862, +1892, doba 2 +4023; "
                "od F2 spodziewany spadek reszty o ok. 61/d)", None)
    else:
        rep.add("F2-6: targ koni jucznych (linie Konie (E6/0) i Hodowla (220))", "brak linii Konie (E6/0) w oknie", "INFO", None)


def etap5_r1_stock(rep, lines, start, until, rows, ref=False):
    """Narzedzie progow zb58 (TRIAZ "PROGI R1-8, R1-9, R1-10", R1-8 i R1-10 z podwazeniem): trzy progi skutku wytopu liczone z linii zelaza (rows -
    "Zelazo (lupy) (214)" albo, w logu bez dymarki, "Ruda:"), "Drewno:" i "Warsztaty:". ref=True (log bez linii startowej Bloomery - wzorzec):
    te same miary jako INFO, zeby porownanie z wzorcem bylo w raporcie. Progi: R1-8 srednio d61-until <= 30 (nie gorzej niz W33 29.4; cel projektu 15
    osobnym wierszem INFO - W33 nigdy nie zszedl ponizej 19), R1-9 przyrost stosu drewna miast d61 -> until <= 290 ladunkow/d (W33 +17 095 w 59 dob;
    stos rosl tez we wzorcu), R1-10 srednio d91-until <= 715/d (okno, z ktorego pochodzi 584 z biegu z31A; 715 = najwyzszy z 4 biegow bez dymarki)."""
    tag = " [wzorzec bez dymarki - linia Ruda:]" if ref else ""

    def okv(v):
        return None if ref else v
    days = sorted(rows)
    w61 = [x for x in days if x >= 61]
    # narzedzie progow p2 (TRIAZ-2 d-R1-8): prog <= 30 liczony z d91-until - doby 61-90 to jeszcze dochodzenie po starcie (liczba miast bez zelaza
    # schodzi przez caly bieg: bieg 2 zbior-e8 d61-120 33.4, d91-120 30.9; wzorzec W33 ta sama miara 29.4 i 26.7). Okno krotsze niz d91 - INFO ze srednia
    # d61-until. Bieg 2 zostaje NIE (30.9) - objaw prawdziwy: przewoznik kontraktu surowca (174.2) to karawana STOJACA w zrodle, a po E8/G1 stoi ich
    # kilka razy mniej (G1-6b).
    w91 = [x for x in days if x >= 91]
    if w61:
        empty = [num(r"miast bez towaru (\d+) z", rows[x], int, 0) or 0 for x in w61]
        avg61 = sum(empty) / len(empty)
        if w91:
            e91 = [num(r"miast bez towaru (\d+) z", rows[x], int, 0) or 0 for x in w91]
            avg = sum(e91) / len(e91)
            rep.add("R1-8: miasta bez zelaza (srednio d91-until)" + tag, f"{avg:.1f} (d{w91[0]}-d{w91[-1]}; d61-until {avg61:.1f})",
                    "<= 30 w d91-until (d61-90 to dochodzenie po starcie; wzorzec W33 d91-120: 26.7, d61-120: 29.4)" if not ref
                    else "INFO (prog biegu z dymarka: <= 30 w d91-until)", okv(avg <= 30.0))
        else:
            avg = avg61
            rep.add("R1-8: miasta bez zelaza (srednio d91-until)" + tag, f"okno nie siega d91 (srednio d{w61[0]}-d{w61[-1]}: {avg61:.1f})",
                    "INFO (prog <= 30 liczony z d91-until)", None)
        if not ref:
            rep.add("R1-8b: miasta bez zelaza wobec celu projektu (srednio d91-until)", f"{avg:.1f}",
                    "INFO (cel projektu <= 15 - do oceny po dowozie drewna do dymarek i E8/G1; wzorzec nie zszedl ponizej 19)", None)
    wood, flow = {}, {}
    for d, s in by_day(lines, "Drewno: dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            v = num(r"zapas: miasta (\d+)", s, int)
            if v is not None:
                wood[rd] = v
            flow[rd] = num(r"las okregu poza zapasem (\d+)", s, int, 0) or 0
    wd = sorted(x for x in wood if x >= 61)
    if len(wd) >= 2:
        a, b = wood[wd[0]], wood[wd[-1]]
        per = (b - a) / float(wd[-1] - wd[0])
        rep.add("R1-9: stos drewna miast (d61 -> until)" + tag, f"{a} -> {b} (d{wd[0]}-d{wd[-1]}, {100.0 * (b - a) / max(1, a):+.1f}%, {per:+.0f}/d)",
                "przyrost <= 290 ladunkow/d (wzorzec W33 +17 095 w 59 dob; po dowozie drewna do dymarek zaostrzyc do <= 0)" if not ref
                else "INFO (prog biegu z dymarka: przyrost <= 290 ladunkow/d)", okv(per <= 290.0))
    led = {}
    for s in lines:
        if s.startswith("Towary: dzien "):
            m = re.match(r"Towary: dzien (\d+) - hardwood \([^)]*\): zapas -?\d+ .*?\| produkcja (\d+) .*?\| zuzycie (\d+) ", s)
            if m:
                rd = run_day(int(m.group(1)), start)
                if 61 <= rd <= until:
                    led[rd] = (int(m.group(2)), int(m.group(3)))
    if led:
        n = float(len(led))
        fo = sum(flow.get(x, 0) for x in led) / n
        pr, co = sum(v[0] for v in led.values()) / n + fo, sum(v[1] for v in led.values()) / n + fo
        rep.add("R1-9b: drewno - produkcja z lasem okregu minus zuzycie (ksiega Towary, srednio d61-until)" + tag,
                f"produkcja {pr:.0f}/d (w tym las okregu poza zapasem {fo:.0f}), zuzycie {co:.0f}/d, roznica {pr - co:+.0f}/d ({len(led)} dob)",
                "INFO (stos rosnie, gdy swiat tnie wiecej drewna, niz pali)", None)
    ws, ws31 = {}, {}
    for d, s in by_day(lines, "Warsztaty: dzien").items():
        rd = run_day(d, start)
        v = num(r"brak surowca \d+ \[ruda (\d+)", s, int)
        if v is None:
            continue
        if 91 <= rd <= until:
            ws[rd] = v
        if 31 <= rd <= until:
            ws31[rd] = v
    if ws:
        avg = sum(ws.values()) / len(ws)
        rep.add("R1-10: cykle warsztatow \"brak surowca [ruda\" (srednio d91-until)" + tag,
                f"{avg:.0f}/d ({len(ws)} dob; d31-until {sum(ws31.values()) / len(ws31):.0f}/d)"
                + ("" if ref else "; miara zanizona przy lupie (cykle z pustym rankingiem nie sa liczone) - wiazace dla zjawiska jest R1-8"),
                "<= 715/d (najwyzszy z 4 biegow bez dymarki w d91-120: z31A 584, 464, 714, W33 509)" if not ref else "INFO (prog biegu z dymarka: <= 715/d)",
                okv(avg <= 715.0))
    elif ws31:
        rep.add("R1-10: cykle warsztatow \"brak surowca [ruda\"" + tag, f"okno nie siega d91 (srednio d31-until {sum(ws31.values()) / len(ws31):.0f}/d, {len(ws31)} dob)",
                "<= 715/d srednio d91-until", None)
    # narzedzie progow F9b (F4a R1-10b): woz dymarki nie moze zabierac drewna kuzniom miast handlowych - cykle "brak surowca [.., drewno" srednio
    # d91-until nie wiecej niz w biegu sprzed wozow (a589def 177/d, W33 199/d); liczba porownywana po zaokragleniu, jak w wierszu
    wdw = {}
    for d, s in by_day(lines, "Warsztaty: dzien").items():
        rd = run_day(d, start)
        v = num(r"brak surowca \d+ \[ruda \d+, drewno (\d+)", s, int)
        if v is not None and 91 <= rd <= until:
            wdw[rd] = v
    if wdw:
        avg = sum(wdw.values()) / len(wdw)
        rep.add("R1-10b: cykle warsztatow \"brak surowca [.., drewno\" (srednio d91-until)" + tag, f"{avg:.0f}/d ({len(wdw)} dob)",
                "<= 177/d (bieg sprzed wozow dymarek a589def 177, W33 199 - woz nie zabiera drewna kuzniom miast handlowych)" if not ref
                else "INFO (prog biegu z dymarka: <= 177/d)", okv(round(avg) <= 177))


def etap5_r1(rep, lines, start, until):
    """E6/R1 (214, projekt etapu 6 v2 rozdz. 3 "E6/R1" Test): linia startowa "Bloomery (E6/R1, 214):" i linia doby "Zelazo (lupy) (214): dzien N"
    (OreLedger - dzien = doba gry, okno doby kampanii 1-until jak etap5_main). Wiazace: tozsamosci lup i drewna w kazdej dobie, lupy bez drewna 0,
    kopalnia bez wegla <= 5% lup (d61-until - po pierwszej decyzji regulatora drewna d56; d8-60 INFO), miasta bez zelaza <= 30 (srednio d61-until;
    cel 15 INFO), przyrost stosu drewna miast d61-until <= 290/d (linia "Drewno:"), "brak surowca [ruda" <= 715/d srednio d91-until (linia "Warsztaty:"),
    brak zlota i pusta kiesa wsi <= 5% potrzeby drewna (R1-7b, d61-until; NIE tylko, gdy zapas zelaza swiata nie rosnie w d91-until), potkniecia 0;
    od F9b wiersze poprawek F4a / F4b (_r1_f4: wozy dymarek R1-7c..R1-7e, R1-13, rachunek za drewno R1-14..R1-18) i R1-10b; reszta INFO. Log bez linii
    startowej Bloomery (wzorzec bez dymarki): R1-8/R1-9/R1-10/R1-10b z linii "Ruda:" i "Warsztaty:" jako INFO (etap5_r1_stock)."""
    start_l = [x for x in lines if x.startswith("Bloomery (E6/R1, 214): ") and ("CZYNNE" in x or "NIEAKTYWNE" in x or "WYLACZONE" in x)]
    wire = [x for x in lines if x.startswith("Bloomery (E6/R1, 214): tick produkcji") or x.startswith("Bloomery (E6/R1, 214): BRAK")]
    if wire:
        rep.add("R1-2: wpiecie ticku produkcji wsi (TickGoodProduction)", wire[-1][:160], "bez BRAK", "BRAK" not in wire[-1])
    if not start_l:
        rep.add("R1-1: linia startowa Bloomery (E6/R1, 214)", "brak", "jest od wgrania E6/R1 (HistoricalPrices.Apply)", None)
        ore = {}
        for d, s in by_day(lines, "Ruda: dzien").items():
            rd = run_day(d, start)
            if 1 <= rd <= until:
                ore[rd] = s
        if ore:
            etap5_r1_stock(rep, lines, start, until, ore, ref=True)
        return
    if "CZYNNE" not in start_l[-1]:
        rep.add("R1-1: wytop przy kopalni", start_l[-1][:200], "CZYNNE w nowej kampanii (stary zapis / wylaczone - ruda jak dotad)", None)
        return
    rep.add("R1-1: wytop przy kopalni", start_l[-1][:200], "CZYNNE", True)
    rows = {}
    for d, s in by_day(lines, "Zelazo (lupy) (214): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rows[rd] = s
    rep.add("R1-3: linia Zelazo (lupy) (214)", f"{len(rows)} dob", "codziennie od wgrania E6/R1", None)
    if not rows:
        return
    days = sorted(rows)
    bad_id = [x for x in days if (num(r"kontrola wsie - ticki = (-?\d+)", rows[x], int, 0) or 0) != 0]
    rep.add("R1-4: lupy wsi (OnItemProduced) = lupy z tickow kopalni (kazda doba)", f"rozjazd w {len(bad_id)} z {len(days)} dob" + (f"; pierwsza d{bad_id[0]}" if bad_id else ""),
            "0 dob z rozjazdem", len(bad_id) == 0)
    bad_w = [x for x in days if (num(r"x lupy \(roznica (-?\d+)\)", rows[x], int, 0) or 0) != 0]
    rep.add("R1-5: drewno spalone w dymarkach = drewna na lupe x lupy (kazda doba)", f"rozjazd w {len(bad_w)} z {len(days)} dob", "0 dob z rozjazdem", len(bad_w) == 0)

    def tot(pat, ds, cast=int):
        return sum(num(pat, rows[x], cast, 0) or 0 for x in ds)
    over = tot(r"lupy bez drewna (\d+)", days)
    rep.add("R1-6: lupy bez drewna w dymarce (suma okna)", str(over), "0", over == 0)
    # narzedzie progow zb58 (TRIAZ R1-7 pkt 9): swiatu brakuje drewna do pelnej potrzeby dymarek az do pierwszej decyzji regulatora drewna (d56), wiec
    # 5% jest wiazace w d61-until; d8-60 (od pierwszej doby kopalni bez drewna) - INFO. Okno krotsze niz d61 - sam wiersz INFO.
    def coal(ds):
        made = tot(r"lupy z tickow kopalni (\d+)", ds)
        unwon = tot(r"kopalnia bez wegla ([\d.]+) lup", ds, float)
        return made, unwon, 100.0 * unwon / max(1.0, made + unwon)
    w61 = [x for x in days if x >= 61]
    w8 = [x for x in days if 8 <= x <= 60]
    if w61:
        made, unwon, share = coal(w61)
        rep.add("R1-7: kopalnia bez wegla wobec lup (d61-until)", f"{unwon:.0f} lup niewytopionych przy {made} wytopionych ({share:.1f}%)", "<= 5%", share <= 5.0)
    if w8:
        made, unwon, share = coal(w8)
        rep.add("R1-7a: kopalnia bez wegla wobec lup (d8-60, przed pierwsza decyzja regulatora drewna)",
                f"{unwon:.0f} lup niewytopionych przy {made} wytopionych ({share:.1f}%)", "INFO (prog <= 5% wiazacy w d61-until)", None)
    etap5_r1_stock(rep, lines, start, until, rows)
    stu = tot(r"potkniecia dzis (\d+) \(od wczytania", days)
    rep.add("R1-11: potkniecia Bloomery (suma okna)", str(stu), "0", stu == 0)
    woods, bought, gold = tot(r", las okregu (\d+), targ", days), tot(r", targ (\d+) za", days), tot(r", targ \d+ za (\d+) zl", days)
    shelf, nogold, nomk = tot(r"\(brak na polce (\d+)", days), tot(r"brak zlota wsi (\d+)", days), tot(r"bez miasta handlowego (\d+)", days)
    tm, tmw, tms = tot(r"kopalnie BK w miastach: lupy (\d+)", days), tot(r"kopalnie BK w miastach: lupy \d+, drewno (\d+)", days), tot(r"bez drewna/kapitalu (\d+)", days)
    miss = shelf + nogold + nomk
    rep.add("R1-12: wegiel dymarek - skad (suma okna)",
            f"las okregu {woods} ({woods / float(len(days)):.0f}/d), targ {bought} ladunkow za {gold} zl" + (f" ({gold / float(bought):.1f} zl za ladunek)" if bought else "")
            + f"; braki: na polce {shelf}, zlota wsi {nogold}" + (f" ({100.0 * nogold / miss:.0f}% brakow)" if miss else "") + f", bez miasta handlowego {nomk}; "
            f"kopalnie BK w miastach: lupy {tm}, drewno {tmw}, bez drewna/kapitalu {tms}",
            "INFO (las okregu z pomiaru; szacunek projektu ok. 100/d nieaktualny; reszta z targu)", None)
    # narzedzie progow zb58 (TRIAZ R1-12 pkt 4, PROGI pkt 5) + F9b (F4a R1-7b, dopisek F4b): niedobor drewna z braku zlota wsi wobec potrzeby doby.
    # Jedna regula na jedno zjawisko: wiersz F9a "R1-13 brak zlota wsi (d91-until)" jest teraz R1-7b z listy F4a - okno d61-until, licznik = "brak zlota
    # wsi" (polka wlasnego miasta handlowego) + "pusta kiesa wsi" (woz z dalszego miasta; pole od F4a, w logu sprzed F4a - 0). Ponad 5% przy rosnacym
    # zapasie zelaza swiata ("razem" w linii, d91-until: 5 ostatnich dob > 5 pierwszych) = niewyplacalna kopalnia jako regulator nadprodukcji (cena lupy
    # ponizej kosztu drewna) - INFO; NIE dopiero, gdy zelaza nie przybywa. Numer R1-13 nosi od F4a wiersz "najbardziej bez wegla" (INFO).
    w91 = [x for x in days if x >= 91]
    if w61:
        ng, npu, need = tot(r"brak zlota wsi (\d+)", w61), tot(r"pusta kiesa wsi (\d+)", w61), tot(r"przy potrzebie doby (\d+)", w61)
        has_cart = any(", pusta kiesa wsi " in rows[x] for x in w61)
        stock = [num(r"zapas: miasta .*?, razem (\d+) \(", rows[x], int) for x in w91]
        stock = [v for v in stock if v is not None]
        if need > 0:
            sh = 100.0 * (ng + npu) / need
            grows = len(stock) >= 10 and sum(stock[-5:]) > sum(stock[:5])
            n91, need91 = tot(r"brak zlota wsi (\d+)", w91) + tot(r"pusta kiesa wsi (\d+)", w91), tot(r"przy potrzebie doby (\d+)", w91)
            rep.add("R1-7b: brak zlota wsi i pusta kiesa wsi wobec potrzeby drewna dymarek (d61-until)",
                    f"{sh:.1f}% (brak zlota wsi {ng} + pusta kiesa wsi {npu}" + ("" if has_cart else " [pole od F4a - brak w logu]") + f" z {need} ladunkow)"
                    + (f"; zapas zelaza swiata d91-until: 5 pierwszych dob {sum(stock[:5]) / 5.0:.0f}, 5 ostatnich {sum(stock[-5:]) / 5.0:.0f}" if len(stock) >= 10 else "")
                    + (" - rosnie (regulator nadprodukcji)" if grows and sh > 5.0 else "")
                    + (f"; okno d91-until {100.0 * n91 / need91:.1f}% ({n91} z {need91})" if need91 > 0 else ""),
                    "<= 5% (ponad 5% przy rosnacym zapasie zelaza swiata w d91-until - INFO \"regulator nadprodukcji\"; NIE, gdy zelaza nie przybywa)",
                    True if sh <= 5.0 else (None if grows else False))
        else:
            rep.add("R1-7b: brak zlota wsi i pusta kiesa wsi wobec potrzeby drewna dymarek (d61-until)", "brak potrzeby doby w oknie", "<= 5%", None)
    else:
        rep.add("R1-7b: brak zlota wsi i pusta kiesa wsi wobec potrzeby drewna dymarek (d61-until)", "okno nie siega d61", "<= 5%", None)
    _r1_f4(rep, lines, start, until, rows, days)


def _r1_f4(rep, lines, start, until, rows, days):
    """Narzedzie progow F9b: wiersze poprawek F4a (wozy dymarek) i F4b (rachunek za drewno przed dzialka pana) z wstawek linii "Zelazo (lupy) (214)":
    "; wozy dymarek (F4a): CZYNNE zasieg R, wozem kupione a ladunkow za b zl w c wozach (srednio d dob drogi; miast z nadwyzka e), dojechalo ..,
    czeka .. wozow, zawrocone f w g wozach (zwrot h zl), w drodze wozem ..; niedobor doby bez wozu: bez nadwyzki w zasiegu i, pusta kiesa wsi j;
    kontrola wozow: ... - bez celu k - w drodze dzis = reszta r; czas wozow t ms", "; rachunek za drewno (F4b): CZYNNE, powroty wozow kopaln ..;
    kontrola rachunku: ... = reszta r; kiesy kopaln: ..; najwiecej bez zlota: ..", "; najbardziej bez wegla: ..; miasta handlowe kopaln ponizej
    potrzeby: .." oraz z dopisku "rachunek za drewno kopaln (F4b)" linii "Utarg wsi (112)" (ta sama etykieta doby). Log sprzed poprawki (bez wstawki)
    - INFO "brak linii"."""
    def tot(pat, ds, cast=int):
        return sum(num(pat, rows[x], cast, 0) or 0 for x in ds)
    w31, w61 = [x for x in days if x >= 31], [x for x in days if x >= 61]
    need61 = tot(r"przy potrzebie doby (\d+)", w61)
    # ---- F4a: wozy dymarek
    cart = [x for x in days if "; wozy dymarek (F4a): " in rows[x]]
    if not cart:
        rep.add("R1-7c..R1-7e: wozy dymarek (F4a)", "brak linii (log sprzed F4a - bez wstawki \"wozy dymarek (F4a)\" w linii Zelazo)",
                "wstawka jest od F4a (klucz BloomeryCartRange)", None)
    else:
        offc = [x for x in days if "; wozy dymarek (F4a): CZYNNE" not in rows[x]]
        b31 = tot(r", wozem kupione (\d+) ladunkow", [x for x in cart if x >= 31])
        rep.add("R1-7c: wozy dymarek CZYNNE w kazdej dobie i zakupy wozem w d31-until",
                f"CZYNNE w {len(days) - len(offc)} z {len(days)} dob" + (f" (ostatnia nieczynna d{offc[-1]})" if offc else "") + f"; wozem kupione w d31-until {b31} ladunkow",
                "CZYNNE we wszystkich dobach i kupione > 0 (klucz BloomeryCartRange > 0)", (len(offc) == 0 and b31 > 0) if w31 else (False if offc else None))
        cre = re.compile(r"kontrola wozow: w drodze wczoraj \d+ \+ kupione - dojechalo - zawrocone - bez celu (\d+) - w drodze dzis = reszta (-?\d+)")
        cc = []
        for x in cart:
            m = cre.search(rows[x])
            if m:
                cc.append((x, int(m.group(1)), int(m.group(2))))
        badc = [c for c in cc if c[1] != 0 or c[2] != 0]
        rep.add("R1-7d: kontrola wozow dymarek (w drodze wczoraj + kupione - dojechalo - zawrocone - bez celu = w drodze dzis)",
                f"dob z kontrola {len(cc)}, z reszta albo \"bez celu\" {len(badc)}"
                + (" [" + ", ".join(f"d{c[0]}: bez celu {c[1]}, reszta {c[2]}" for c in badc[:5]) + "]" if badc else ""),
                "reszta 0 i bez celu 0 w kazdej dobie z tym polem", (len(badc) == 0) if cc else None)
        ere = re.compile(r", wozem kupione (\d+) ladunkow za (\d+) zl w (\d+) wozach \(srednio ([\d.]+) dob drogi; miast z nadwyzka (\d+|-)\)")
        bre = re.compile(r", zawrocone (\d+) w (\d+) wozach \(zwrot (\d+) zl\)")
        cb = cg = cn = bk = bkc = rf = 0
        dsum, srcs = 0.0, []
        for x in cart:
            m = ere.search(rows[x])
            if m:
                cb += int(m.group(1)); cg += int(m.group(2)); cn += int(m.group(3)); dsum += float(m.group(4)) * int(m.group(3))
                if m.group(5) != "-":
                    srcs.append(int(m.group(5)))
            m = bre.search(rows[x])
            if m:
                bk += int(m.group(1)); bkc += int(m.group(2)); rf += int(m.group(3))
        ns61 = tot(r"bez nadwyzki w zasiegu (\d+)", [x for x in cart if x >= 61])
        tms = [v for v in (num(r"czas wozow ([\d.]+) ms", rows[x], float) for x in cart) if v is not None]
        tavg = sum(tms) / len(tms) if tms else 0.0
        rep.add("R1-7e: wozy dymarek - zakupy, zawrocone, niedobor bez nadwyzki w zasiegu, czas (suma okna)",
                f"kupione {cb} ladunkow ({cb / float(len(cart)):.0f}/d) za {cg} zl" + (f" ({cg / float(cb):.1f} zl za ladunek)" if cb else "") + f" w {cn} wozach"
                + (f" (srednio {dsum / cn:.1f} dob drogi)" if cn else "") + (f"; miast z nadwyzka srednio {sum(srcs) / float(len(srcs)):.1f}" if srcs else "")
                + f"; zawrocone {bk} w {bkc} wozach (zwrot {rf} zl); bez nadwyzki w zasiegu d61-until {ns61}"
                + (f" ({100.0 * ns61 / need61:.1f}% potrzeby)" if need61 > 0 else "")
                + (f"; czas wozow srednio {tavg:.1f} ms/dobe, najwiecej {max(tms):.1f}" + (" - UWAGA: ponad 20 ms" if tavg > 20.0 else "") if tms else ""),
                "INFO (oczekiwane: zawrocone 0, bez nadwyzki w zasiegu <= 5% potrzeby w d61-until, czas ok. 10 ms/dobe - ostrzegawczo > 20)", None)
    # ---- R1-13 (F4a, INFO): kopalnie najbardziej bez wegla i miasta handlowe kopaln ponizej potrzeby
    mre = re.compile(r"najbardziej bez wegla: (.*?); miasta handlowe kopaln ponizej potrzeby: (.*?); potkniecia")
    mm = []
    for x in days:
        m = mre.search(rows[x])
        if m:
            mm.append((x, m.group(1), m.group(2)))
    if not mm:
        rep.add("R1-13: kopalnie najbardziej bez wegla i miasta handlowe kopaln ponizej potrzeby", "brak linii (log sprzed F4a - bez wstawki \"najbardziej bez wegla\")",
                "INFO", None)
    else:
        towns, mines, n61 = {}, {}, 0
        for x, a, b in mm:
            if x < 61:
                continue
            n61 += 1
            for nm in b.split(", "):
                if nm and nm != "-":
                    towns[nm] = towns.get(nm, 0) + 1
            for nm in re.findall(r"(?:^|\), )([^\[\]]+?) \[", a):
                mines[nm] = mines.get(nm, 0) + 1
        top = sorted(towns.items(), key=lambda kv: (-kv[1], kv[0]))[:5]
        topm = sorted(mines.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
        lx, la, lb = mm[-1]
        rep.add("R1-13: kopalnie najbardziej bez wegla i miasta handlowe kopaln ponizej potrzeby",
                f"d{lx}: {la[:320]} | miasta ponizej potrzeby: {lb[:160]}"
                + (f"; najczestsze miasta w d61-until ({n61} dob): " + ", ".join(f"{k} {v}" for k, v in top) if top else "")
                + ("; najczestsze kopalnie: " + ", ".join(f"{k} {v}" for k, v in topm) if topm else ""),
                "INFO (warunek odbioru R1-8 / R1-10: wsrod najczestszych nie ma juz stale Yunkai, Meereen, Tolos, Mantarys, Vaes Diaf; brak nie spada stale na "
                "te same kopalnie)", None)
    # ---- F4b: rachunek za drewno przed dzialka pana
    bill = [x for x in days if "; rachunek za drewno (F4b): " in rows[x]]
    if not bill:
        rep.add("R1-14..R1-18: rachunek za drewno przed dzialka pana (F4b)", "brak linii (log sprzed F4b - bez wstawki \"rachunek za drewno (F4b)\" w linii Zelazo)",
                "wstawka jest od F4b (klucz BloomeryCoalBeforeLordShare)", None)
        return
    ut = {}
    for d, s in by_day(lines, "Utarg wsi (112): dzien").items():
        if 1 <= run_day(d, start) <= until:
            ut[run_day(d, start)] = s
    offb = [x for x in days if "; rachunek za drewno (F4b): CZYNNE" not in rows[x]]
    offu = [x for x in sorted(ut) if "; rachunek za drewno kopaln (F4b): CZYNNE" not in ut[x]]
    rep.add("R1-14: rachunek za drewno CZYNNE w kazdej dobie (linia Zelazo 214 i linia Utarg wsi 112)",
            f"Zelazo: CZYNNE w {len(days) - len(offb)} z {len(days)} dob" + (f" (ostatnia nieczynna d{offb[-1]})" if offb else "")
            + f"; Utarg wsi: CZYNNE w {len(ut) - len(offu)} z {len(ut)} dob" + (f" (ostatnia nieczynna d{offu[-1]})" if offu else ""),
            "CZYNNE we wszystkich dobach obu linii (klucze BloomeryCoalBeforeLordShare i VillageTakingsWhole)", (not offb and not offu) if ut else (False if offb else None))
    kre = re.compile(r"kontrola rachunku: otwarty wczoraj (\d+) \+ drewno kupione (\d+) - na rachunek (\d+) - wygasle ponad \d+ dob zakupow (\d+) - zwrot "
                     r"zawroconych wozow (\d+) - otwarty dzis = reszta (-?\d+)")
    kk = []
    for x in bill:
        m = kre.search(rows[x])
        if m:
            kk.append((x, int(m.group(6))))
    badk = [c for c in kk if c[1] != 0]
    rep.add("R1-15: kontrola rachunku za drewno (otwarty wczoraj + kupione - na rachunek - wygasle - zwrot zawroconych = otwarty dzis)",
            f"dob z kontrola {len(kk)}, z reszta {len(badk)}" + (" [" + ", ".join(f"d{c[0]}: {c[1]:+d}" for c in badk[:5]) + "]" if badk else ""),
            "reszta 0 w kazdej dobie z tym polem", (len(badk) == 0) if kk else None)
    # R1-16: dwa niezalezne liczniki tej samej doby (Bloomery i VillageTakings) - sumy "na rachunek" i zwrotu rowne w dobach z obiema liniami; zwrot kazdej
    # doby <= 0.55 x "na rachunek" + 2 na powrot ze zwrotem (0.55 = polityka wysoka przy czynnej kiesie ludu; + 2 = dwa obciecia do calosci w modelu)
    zre = re.compile(r"z tego na rachunek (\d+) zl, z licznikow panow do kies wsi (\d+) zl \((\d+) powrotow\)")
    ure = re.compile(r"powroty ze zwrotem (\d+), utarg zaliczony na rachunek (\d+), z licznikow panow do kies wsi (\d+)")
    za, ua = {}, {}
    for x in bill:
        m = zre.search(rows[x])
        if m:
            za[x] = tuple(int(v) for v in m.groups())      # (na rachunek, zwrot, powrotow ze zwrotem)
    for x in ut:
        m = ure.search(ut[x])
        if m:
            ua[x] = tuple(int(v) for v in m.groups())      # (powrotow ze zwrotem, na rachunek, zwrot)
    both = sorted(set(za) & set(ua))
    if both:
        zs, zb, zn = (sum(za[x][i] for x in both) for i in range(3))
        un, us, ub = (sum(ua[x][i] for x in both) for i in range(3))
        over = [x for x in sorted(za) if za[x][1] > 0.55 * za[x][0] + 2 * za[x][2]]
        rep.add("R1-16: rachunek za drewno - licznik dymarek (214) = licznik utargu wsi (112); zwrot <= 0.55 x \"na rachunek\" + 2 na powrot",
                f"na rachunek {zs} wobec {us}, zwrot z licznikow panow do kies wsi {zb} wobec {ub} (powrotow ze zwrotem {zn} wobec {un}; {len(both)} dob z para linii); "
                f"dob ze zwrotem ponad granice {len(over)}" + (" [" + ", ".join(f"d{x}" for x in over[:6]) + "]" if over else "")
                + (f"; zwrot / na rachunek {zb / float(zs):.2f}" if zs else ""),
                "obie pary rowne i 0 dob ponad granice (INFO: zwrot / na rachunek oczekiwane ok. 0.40-0.45)", zs == us and zb == ub and not over)
    else:
        rep.add("R1-16: rachunek za drewno - licznik dymarek (214) = licznik utargu wsi (112)", "brak dob z para linii (pole F4b w linii Utarg wsi 112)",
                "obie pary rowne", None)
    ore = re.compile(r"rachunek otwarty (\d+) zl w (\d+) kopalniach")
    op = {}
    for x in bill:
        m = ore.search(rows[x])
        if m:
            op[x] = (int(m.group(1)), int(m.group(2)))
    cut_ = tot(r"wygasle ponad \d+ dob zakupow (\d+)", [x for x in bill if x >= 15])
    ret, hand, settled = (tot(r"powroty wozow kopaln (\d+) z utargiem", bill), tot(r"powroty wozow kopaln \d+ z utargiem (\d+) zl", bill),
                          tot(r"z tego na rachunek (\d+) zl", bill))
    o91 = [op[x][0] for x in op if x >= 91]
    ld = None
    for x in lines:
        m = re.search(r"rachunki za drewno \(F4b\) (\d+) \((\d+) zl\)(?:, nieczytelnych (\d+))?", x)
        if m:
            ld = m
    lx = max(op) if op else None
    rep.add("R1-17: rachunek za drewno - otwarty, wygasle, utarg wozow kopaln (okno)",
            (f"otwarty d{lx}: {op[lx][0]} zl w {op[lx][1]} kopalniach" if lx is not None else "otwarty: brak pola")
            + (f", srednio d91-until {sum(o91) / float(len(o91)):.0f} zl" if o91 else "") + f"; wygasle ponad 14 dob zakupow (suma d15-until) {cut_}"
            + (" - UWAGA: > 0 (wozy kopalni nie wracaja albo zakupy drewna stale ponad utarg)" if cut_ > 0 else "")
            + f"; powroty wozow kopaln {ret} z utargiem {hand} zl ({hand / float(len(bill)):.0f} zl/d)" + (f", na rachunek {100.0 * settled / hand:.0f}% utargu" if hand else "")
            + (f"; wczytanie: rachunki {ld.group(1)} ({ld.group(2)} zl)" + (f", nieczytelnych {ld.group(3)}" if ld.group(3) else "") if ld else ""),
            "INFO (wygasle ostrzegawczo > 0; bazy nie ma - w biegu a589def zakup drewna ok. 47% utargu z zelaza)", None)
    pre = re.compile(r"kiesy kopaln: min (\d+) / mediana (\d+) / suma (\d+) zl w (\d+) kopalniach, ponizej kosztu drewna doby (\d+) z (\d+)")
    nre = re.compile(r"najwiecej bez zlota: (.*?); najbardziej bez wegla:")
    w91b = [x for x in bill if x >= 91] or bill
    pp = [tuple(int(v) for v in m.groups()) for m in (pre.search(rows[x]) for x in w91b) if m]
    names, lastn = {}, None
    for x in w91b:
        m = nre.search(rows[x])
        if not m:
            continue
        lastn = (x, m.group(1))
        for nm in re.findall(r"(?:^|\), )(.+?) \(kiesa ", m.group(1)):
            names[nm] = names.get(nm, 0) + 1
    topn = sorted(names.items(), key=lambda kv: (-kv[1], kv[0]))[:3]
    if pp:
        k = float(len(pp))
        rep.add(f"R1-18: kiesy kopaln i kopalnie najwiecej bez zlota (srednio d{w91b[0]}-d{w91b[-1]})",
                f"min {sum(q[0] for q in pp) / k:.0f} / mediana {sum(q[1] for q in pp) / k:.0f} / suma {sum(q[2] for q in pp) / k:.0f} zl w {pp[-1][3]} kopalniach; "
                f"ponizej kosztu drewna doby srednio {sum(q[4] for q in pp) / k:.1f} z {sum(q[5] for q in pp) / k:.1f}"
                + (f"; d{lastn[0]} najwiecej bez zlota: {lastn[1][:260]}" if lastn else "")
                + ("; najczestsze: " + ", ".join(f"{a} {b}" for a, b in topn) if topn else ""),
                "INFO (bazy nie ma - pierwszy bieg ustala; kopalnia, ktora nic nie kupila, nie dostaje zwrotu - cecha reguly F4b)", None)
    else:
        rep.add("R1-18: kiesy kopaln i kopalnie najwiecej bez zlota", "brak pola kies kopaln", "INFO", None)


def etap5_r3(rep, lines, start, until):
    """E6/R3 (215, projekt etapu 6 v2 rozdz. 3 "E6/R3" Test): linie doby "Przewoz kupcow wozem (215): dzien N", "Uprzaz (215): dzien N",
    "Narzedzia wedlug zuzycia (215): dzien N" (dzien = doba gry, okno doby kampanii 1-until jak etap5_main). Wiazace: przewoz CZYNNY we wszystkich dobach
    (przerzut natychmiastowy 0 - kazda sztuka hurtu idzie wozem; awaryjny przerzut tylko przy potknieciu), kontrola "w drodze" reszta 0 w kazdej dobie,
    potkniecia 0, polki uprzezy bez wzrostu d91-until (<= +2%); reszta INFO (sredni czas drogi, zakupy uprzezy, wstrzymane cykle narzedzi)."""
    def rows_of(prefix):
        r = {}
        for d, s in by_day(lines, prefix).items():
            rd = run_day(d, start)
            if 1 <= rd <= until:
                r[rd] = s
        return r
    cart = rows_of("Przewoz kupcow wozem (215): dzien")
    rep.add("R3-1: linia Przewoz kupcow wozem (215)", f"{len(cart)} dob", "codziennie od wgrania E6/R3", None)
    if cart:
        days = sorted(cart)
        off = [x for x in days if "| CZYNNE |" not in cart[x]]
        rep.add("R3-2: hurt kupcow wozem CZYNNY w dobach okna (przerzut natychmiastowy 0)", f"{len(days) - len(off)} z {len(days)}" + (f"; ostatnia nieczynna d{off[-1]}" if off else ""),
                "wszystkie doby (klucz ArmsTradeByCart)", len(off) == 0)
        chk = [x for x in days if "kontrola: w drodze wczoraj" in cart[x]]
        bad = [x for x in chk if (num(r"= reszta (-?\d+)", cart[x], int, 0) or 0) != 0]
        rep.add("R3-3: kupione = dowiezione + zawrocone + w drodze (reszta, kazda doba)", f"rozjazd w {len(bad)} z {len(chk)} dob" + (f"; pierwsza d{bad[0]}" if bad else ""),
                "0 dob z rozjazdem", (len(bad) == 0) if chk else None)
        stu = sum(num(r"potkniecia dzis (\d+)", cart[x], int, 0) or 0 for x in days)
        rep.add("R3-4: potkniecia wozow kupcow (suma okna)", str(stu), "0", stu == 0)

        def tot(pat, cast=int):
            return sum(num(pat, cart[x], cast, 0) or 0 for x in days)
        bought, arr, back = tot(r"\| kupione (\d+) szt\."), tot(r"\| dowiezione (\d+) szt\."), tot(r"\| zawrocone (\d+) szt\.")
        carts, arrc = tot(r"szt\. za \d+ zl w (\d+) wozach"), tot(r"\| dowiezione \d+ szt\. w (\d+) wozach")
        dsum = sum((num(r"wozach \(srednio ([\d.]+) dob drogi\)", cart[x], float, 0) or 0) * (num(r"szt\. za \d+ zl w (\d+) wozach", cart[x], int, 0) or 0) for x in days)
        asum = sum((num(r"wozach \(srednio ([\d.]+) dob od zakupu\)", cart[x], float, 0) or 0) * (num(r"\| dowiezione \d+ szt\. w (\d+) wozach", cart[x], int, 0) or 0) for x in days)
        last = cart[days[-1]]
        road = num(r"\| w drodze (\d+) szt\.", last, int, 0) or 0
        wait = tot(r"czeka pod oblezeniem (\d+) wozow")
        rep.add("R3-5: hurt kupcow wozem (suma okna; w drodze - ostatnia doba)",
                f"kupione {bought} szt. w {carts} wozach (srednio {dsum / carts if carts else 0:.1f} dob drogi), dowiezione {arr} szt. w {arrc} wozach "
                f"(srednio {asum / arrc if arrc else 0:.1f} dob od zakupu), zawrocone {back}, czeka pod oblezeniem {wait} wozo-dob; w drodze {road} szt. (d{days[-1]})",
                "INFO (dotad 1301 szt./d przerzutem tej samej doby)", None)
    bard = rows_of("Uprzaz (215): dzien")
    rep.add("R3-6: linia Uprzaz (215)", f"{len(bard)} dob", "codziennie od wgrania E6/R3", None)
    if bard:
        bd = sorted(bard)
        pcs = sum(num(r"kupiona (\d+) szt\.", bard[x], int, 0) or 0 for x in bd)
        gold = sum(num(r"kupiona \d+ szt\. za (\d+) zl", bard[x], int, 0) or 0 for x in bd)
        short = sum(num(r"po zakupach (\d+) szt\.", bard[x], int, 0) or 0 for x in bd)
        rep.add("R3-7: uprzaz kupiona przez lordow AI (suma okna)", f"{pcs} szt. za {gold} zl; brak po zakupach (suma dob) {short}", "INFO (dotad 0 - AI nie kupowalo uprzezy)", None)
        stu = sum(num(r"potkniecia (\d+)\.", bard[x], int, 0) or 0 for x in bd)
        rep.add("R3-8: potkniecia zakupow uprzezy (suma okna)", str(stu), "0", stu == 0)
        shelf = {x: num(r"uprzaz (\d+) szt\. \|", bard[x], int) for x in bd if x >= 91}
        sd = sorted(x for x in shelf if shelf[x] is not None)
        if len(sd) >= 2:
            a, b = shelf[sd[0]], shelf[sd[-1]]
            # recenzja E8/Z (251): uprzaz ponad zapas ze zbrojowni AI idzie od E8/Z na te same polki (przeniesienie starego zapasu, nie produkcja) -
            # suma "sprzedana" linii E8/Z z dob po pierwszej dobie pomiaru; wzrost polek nie wiekszy niz to przeniesienie = DECYZJA zamiast NIE
            zrow = rows_of("Zakupy i nadwyzki AI (E8/Z): dzien")
            zin = sum(num(r"uprzaz ponad zapas \[[^\]]*\]: sprzedana (\d+) szt", zrow[x], int, 0) or 0 for x in zrow if sd[0] < x <= sd[-1])
            ok9 = b <= a * 1.02
            rep.add("R3-9: polki uprzezy miast i zamkow (d91 -> until)",
                    f"{a} -> {b} (d{sd[0]}-d{sd[-1]}, {100.0 * (b - a) / max(1, a):+.1f}%)"
                    + (f"; w tym ze zbrojowni AI na polki (E8/Z, uprzaz ponad zapas) +{zin} szt. - bez nich {a} -> {b - zin} ({100.0 * (b - zin - a) / max(1, a):+.1f}%)" if zin > 0 else ""),
                    "bez wzrostu (<= +2%)" + ("; wzrost nie wiekszy niz przeniesienie ze zbrojowni AI (E8/Z) - DECYZJA, czytac z Z-3" if zin > 0 else ""),
                    ok9, decide=(not ok9 and zin > 0 and b - zin <= a * 1.02))
    tools = rows_of("Narzedzia wedlug zuzycia (215): dzien")
    rep.add("R3-10: linia Narzedzia wedlug zuzycia (215)", f"{len(tools)} dob", "codziennie od wgrania E6/R3", None)
    if tools:
        td = sorted(tools)
        run = sum(num(r"puszczone (\d+)", tools[x], int, 0) or 0 for x in td)
        held = sum(num(r"wstrzymane (\d+)", tools[x], int, 0) or 0 for x in td)
        inp = sum(num(r"wsad niezuzyty (\d+) szt\.", tools[x], int, 0) or 0 for x in td)
        rep.add("R3-11: cykle linii narzedzi (suma okna)", f"puszczone {run}, wstrzymane {held} (wsad niezuzyty {inp} szt.)",
                "INFO (projekt: ruda na narzedzia w dol z 32 ladunkow/d, stos narzedzi bez wzrostu)", None)
        stu = sum(num(r"potkniecia dzis (\d+)", tools[x], int, 0) or 0 for x in td)
        rep.add("R3-12: potkniecia ToolsByUse (suma okna)", str(stu), "0", stu == 0)


def etap5_f1(rep, lines, start, until, logp=None):
    """Narzedzie progow F9b - poprawka F1 (test zbiorczy 5-8; TradeCarts 215, ValyrianBlades, UniqueSpoils): spis stali valyrianskiej i kronika
    unikatow widza sztuki w wozach kupcow. Linie: "ERROR in ValyrianBlades.Census" (UBYTEK - klinga poza spisem), "Stal valyrianska: dzien N - X klng,
    Y miar (rejestr Z klng, ...), ..., w drodze wozem W" (glowny log; pisana przy zmianie; pole "w drodze wozem" od F1) oraz plik sesji unikaty.log:
    "Kronika unikatow: dzien N - stan swiata (K unikatow w obiegu): <id>: <miejsce> | ..." / "... - zmiany: <id>: <miejsce> | ..." (miejsce = skladniki
    po "; ", "nigdzie" = zero skladnikow). Wiazace (prog 0): F1-1 bledy spisu, F1-2 spis z klng < rejestr (bez pierwszej linii pliku - spis startowy
    sesji, magazyny DTE odtwarzane po starcie), F1-3 wpis kroniki, w ktorym ubyl skladnik "targ " albo "w drodze wozem " i nie przybyl zaden nowy.
    INFO: F1-4 wpisy kroniki "w drodze wozem" i najwiecej kling w wozach (brak pola = stary DLL), F1-5 wszystkie wpisy "nigdzie"."""
    cre = re.compile(r"^Stal valyrianska: dzien (\d+) - (\d+) klng, \d+ miar \(rejestr (\d+) klng")
    cen = []
    for x in lines:
        m = cre.match(x)
        if m:
            cen.append((int(m.group(1)), int(m.group(2)), int(m.group(3)), x))
    errs = [x for x in lines if x.startswith("ERROR in ValyrianBlades.Census")]
    rep.add("F1-1: bledy spisu stali valyrianskiej (linie ERROR in ValyrianBlades.Census)", f"{len(errs)}" + (f" (pierwszy: {errs[0][:220]})" if errs else ""),
            "0 (UBYTEK = klinga poza spisem; od F1 woz kupca jest miejscem spisu; a589def 1, W33 0)", (len(errs) == 0) if (cen or errs) else None)
    body = [c for c in cen[1:] if run_day(c[0], start) <= until + 1]
    low = [c for c in body if c[1] < c[2]]
    if cen:
        rep.add("F1-2: spis stali valyrianskiej z liczba kling ponizej rejestru (bez spisu startowego sesji)",
                f"{len(low)} z {len(body)} linii spisu" + (" [" + ", ".join(f"d{run_day(c[0], start)}: {c[1]} z {c[2]}" for c in low[:6]) + "]" if low else ""),
                "0 (a589def 4 ze 120 - klinga w wozie kupca; W33 0)", (len(low) == 0) if body else None)
    else:
        rep.add("F1-2: spis stali valyrianskiej z liczba kling ponizej rejestru", "brak linii Stal valyrianska: dzien", "0", None)
    fld = [v for v in (num(r", w drodze wozem (\d+)", c[3], int) for c in cen) if v is not None]
    up = session_file_find(logp, "unikaty.log") if logp else None
    if not up or not os.path.exists(up):
        rep.add("F1-3: unikat z targu albo z wozu na \"nigdzie\" bez nowego miejsca (kronika unikatow)", f"brak pliku unikaty.log ({up or 'bez sciezki logu'})",
                "0 (plik sesji unikaty.log obok logu albo w Logs/<sesja>/)", None)
        rep.add("F1-4: unikaty i stal valyrianska w wozach kupcow", ("spis: najwiecej kling w wozach " + str(max(fld)) + f" ({len(fld)} linii z polem)") if fld
                else ("spis: BRAK pola \"w drodze wozem\" (stary DLL)" if cen else "brak linii spisu") + "; kronika: brak pliku", "INFO", None)
        rep.add("F1-5: wpisy kroniki \"nigdzie\"", "brak pliku unikaty.log", "INFO", None)
        return
    kre = re.compile(r"^Kronika unikatow: dzien (\d+) - (stan swiata \(\d+ unikatow w obiegu\): |zmiany: )(.*)$")
    state, hits, road, nowhere, nlines = {}, [], 0, [], 0
    for x in read(up):
        m = kre.match(x)
        if not m:
            continue
        rd = run_day(int(m.group(1)), start)
        first = m.group(2).startswith("stan")
        txt = m.group(3)
        if txt.endswith("."):
            txt = txt[:-1]
        if first:
            state = {}
        inwin = rd <= until + 1
        nlines += 1 if inwin else 0
        for ent in txt.split(" | "):
            if ": " not in ent:
                continue
            uid, place = ent.split(": ", 1)
            comp = set() if place.startswith("nigdzie") else set(place.split("; "))
            old = state.get(uid)
            if inwin and not first:
                if any(c.startswith("w drodze wozem ") for c in comp):
                    road += 1
                if not comp:
                    nowhere.append(f"d{rd} {uid}")
                if old:
                    lost = [c for c in old - comp if c.startswith("targ ") or c.startswith("w drodze wozem ")]
                    if lost and not (comp - old):
                        hits.append(f"d{rd} {uid}: {sorted(lost)[0]} -> " + ("nigdzie" if not comp else "ubylo"))
            state[uid] = comp
    rep.add("F1-3: unikat z targu albo z wozu na \"nigdzie\" bez nowego miejsca (kronika unikatow, unikaty.log)",
            f"{len(hits)} w {nlines} liniach kroniki" + (" [" + "; ".join(hits[:5]) + "]" if hits else ""),
            "0 (a589def 2 - oba woz kupca, od F1 0; W33 1 - cersei_red_dress z polki, inna droga)", (len(hits) == 0) if nlines else None)
    rep.add("F1-4: unikaty i stal valyrianska w wozach kupcow (wpisy kroniki \"w drodze wozem\" / najwiecej kling w wozach w spisie)",
            f"wpisow kroniki {road}; spis: " + (f"najwiecej {max(fld)} ({len(fld)} linii z polem)" if fld else ("BRAK pola \"w drodze wozem\" (stary DLL)" if cen else "brak linii spisu")),
            "INFO (od F1 woz kupca jest miejscem w kronice i w spisie)", None)
    rep.add("F1-5: wpisy kroniki unikatow \"nigdzie\" (wszystkie, okno)", f"{len(nowhere)}" + (" [" + ", ".join(nowhere[:8]) + "]" if nowhere else ""),
            "INFO (a589def 5, W33 3; po F1 zostaja przejsciowe \"nigdzie\" rzeczy noszonych i przypadki poza wozem)", None)


def etap5_w1(rep, lines, start, until):
    """E6/W1 (216, projekt etapu 6 v2 rozdz. 3 "E6/W1" Test): linia startowa sesji "Receptury (216):" (raz na sesje, po HistoricalPrices.Apply - ocena
    ostatniej w logu) i linie ksiegi "Towary: dzien N - <towar> (W d): zapas S" (dzien = doba gry - 1, okno doby kampanii 1-until jak etap5_main).
    Wiazace: WLACZONE, zadna linia z mniejszym wsadem niz receptura gry, dla welny, lnu i skor co najmniej jedna linia zmieniona, potkniecia 0;
    len i welna - stos z ostatniej decyzji regulatora wsi <= 60 dni zuzycia albo decyzja w dol w oknie (bez decyzji regulatora: co najmniej jeden
    z miesiecy 2-4 (d29-56, d57-84, d85-112) z przyrostem <= +2% zapasu z poczatku miesiaca); gdy okno siega d112, inaczej INFO;
    skora i plotno - srednia zmiana zapasu d91-until >= -10/d (gdy okno siega d92, inaczej INFO); kolejka odziezy wojska (150, skora + sukno + plotno
    "czeka") d90 -> until bez wzrostu (<= +2%, gdy okno siega d92, inaczej INFO)."""
    st = [s for s in lines if s.startswith("Receptury (216):")]
    if not st:
        rep.add("W1-1: linia startowa Receptury (216)", "brak linii startowej", "jest od wgrania E6/W1", None)
        return
    last = st[-1]
    rep.add("W1-1: Receptury (216) WLACZONE (ostatnia sesja logu)", last[:150], "WLACZONE (klucz WorkshopRecipesByValue)", "WLACZONE" in last)
    pairs = re.findall(r"(\w+): (\w+) -> ([^,\[\]]+), sztuk wsadu dawniej (\d+), teraz (\d+)", last)
    less = [p for p in pairs if int(p[4]) < int(p[3])]
    rep.add("W1-2: linie z mniejszym wsadem niz receptura gry", f"{len(less)} z {len(pairs)} linii" + (f"; np. {less[0][0]}" if less else ""), "0",
            (len(less) == 0) if pairs else None)
    up = {k: [p for p in pairs if p[1] == k and int(p[4]) > int(p[3])] for k in ("wool", "flax", "hides")}
    miss = [k for k in up if not up[k]]
    rep.add("W1-3: linie z welny, lnu i skor ze zmienionym wsadem", "; ".join(f"{p[0]}: {p[1]} -> {p[2]} {p[3]} -> {p[4]}" for k in up for p in up[k]) or "brak",
            "kazdy z trzech surowcow (projekt: filc 3 welny -> 2, plotno 6 lnu -> 2, skora 5 skor -> 2)", len(miss) == 0)
    stu = num(r"potkniecia (\d+)\.", last, int, 0) or 0
    rep.add("W1-4: potkniecia Receptury (216)", str(stu), "0", stu == 0)
    ser = {}
    for s in lines:
        if s.startswith("Towary: dzien "):
            m = re.match(r"Towary: dzien (\d+) - (\w+) \([^)]*\): zapas (-?\d+)", s)
            if m and m.group(2) in ("wool", "flax", "linen", "leather"):
                rd = run_day(int(m.group(1)), start)
                if 1 <= rd <= until:
                    ser.setdefault(m.group(2), {})[rd] = int(m.group(3))

    def at(x, d):
        ks = [k for k in x if k <= d]
        return x[max(ks)] if ks else None
    # narzedzie progow zb58 (TRIAZ W1-5): prog sprzed W3 ("ktorys miesiac bez wzrostu") przeczyl pasmu regulatora wsi - towar ze stosem w pasmie albo
    # ponizej pasma (LO-HI dni zuzycia, ValveStockDaysHigh 60) ma rosnac powoli z zamiaru. (a) miesiac zaliczony przy zmianie <= +2% zapasu z poczatku
    # miesiaca (tolerancja jak W3-6 / W1-7); (b) gdy sa decyzje regulatora dla towaru: NIE dopiero, gdy stos z ostatniej decyzji > HI bez zadnej decyzji
    # "w dol" w oknie (wolne puchniecie ponad pasmo). Log bez decyzji regulatora - sama regula (a), gdy okno siega d112.
    vdec, vlo, vhi = valve_decisions(lines, start, until)
    for k, name in (("wool", "welna"), ("flax", "len")):
        x = ser.get(k, {})
        if not x:
            rep.add(f"W1-5: {name} - zmiana zapasu w miesiacach 2-4", "brak linii Towary", "co najmniej jeden miesiac <= +2% (gdy okno siega d112)", None)
            continue
        ch, tol = [], []
        for mth in (2, 3, 4):
            a, b2 = at(x, 28 * (mth - 1)), at(x, 28 * mth)
            c = None if a is None or b2 is None or max(x) < 28 * mth else b2 - a
            ch.append(c)
            tol.append(c is not None and c <= 0.02 * a)
        full = max(x) >= 112 and all(c is not None for c in ch)
        txt = ", ".join("-" if c is None else f"{c:+d}" for c in ch) + f" (ostatnia doba d{max(x)}; miesiecy z przyrostem <= +2%: {sum(1 for t in tol if t)})"
        dd = vdec.get(k, [])
        if dd:
            rd, dn, dirn = dd[-1][0], dd[-1][1], dd[-1][2]
            down = [q[0] for q in dd if q[2] == "w dol"]
            swollen = dn > vhi and not down
            pos = "ponad pasmem" if dn > vhi else ("w pasmie" if dn >= vlo else "ponizej pasma")
            rep.add(f"W1-5: {name} - zmiana zapasu w miesiacach 2-4", txt + f"; regulator d{rd}: stos {dn} dni zuzycia ({pos} {vlo}-{vhi}), {dirn}"
                    + (f", w dol w d{down[-1]}" if down else ""),
                    f"stos regulatora <= {vhi} dni zuzycia albo decyzja w dol w oknie (wzrost w pasmie i ponizej pasma zamierzony); bez decyzji regulatora: "
                    "co najmniej jeden miesiac <= +2%", (not swollen) if full else None)
        else:
            rep.add(f"W1-5: {name} - zmiana zapasu w miesiacach 2-4", txt, "co najmniej jeden miesiac <= +2% zapasu z poczatku miesiaca (gdy okno siega d112)",
                    (any(tol)) if full else None)
    for k, name in (("leather", "skora"), ("linen", "plotno")):
        x = ser.get(k, {})
        a = at(x, 90) if x else None
        if not x or a is None or max(x) < 92:
            rep.add(f"W1-6: {name} - srednia zmiana zapasu d91-until", "za krotkie okno albo brak linii Towary", ">= -10/d (gdy okno siega d92)", None)
            continue
        e = max(x)
        avg = (x[e] - a) / float(e - max(k2 for k2 in x if k2 <= 90))
        rep.add(f"W1-6: {name} - srednia zmiana zapasu d91-until", f"{avg:+.1f}/d (zapas d90 {a} -> d{e} {x[e]})", ">= -10/d", avg >= -10)
    clo = {}
    for d, s in by_day(lines, "Odziez wojska (150): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            clo[rd] = s
    if clo:
        def wait(s):
            i = s.find("| czeka: ")
            return s[i + 9:s.find(" (", i)] if i >= 0 else "?"

        def wsum(s):
            return sum(float(v) for v in re.findall(r"(?:skora|sukno|plotno) (\d+(?:\.\d+)?)", wait(s)))
        # recenzja 216: test projektu "odziez wojska - kolejka nie rosnie" wiazacy - okno jak W1-6 (od d90, po pierwszej decyzji kroku W3 d56),
        # tolerancja +2% jak R1-9; okno krotsze niz d92 - INFO
        f0, f1 = min(clo), max(clo)
        wd = sorted(k for k in clo if k >= 90)
        if len(wd) >= 2 and wd[-1] >= 92:
            a, b2 = wsum(clo[wd[0]]), wsum(clo[wd[-1]])
            rep.add("W1-7: kolejka odziezy wojska (czeka, d90 -> until)", f"d{wd[0]}: {wait(clo[wd[0]])}; d{wd[-1]}: {wait(clo[wd[-1]])} (razem {a:.0f} -> {b2:.0f})",
                    "bez wzrostu (<= +2%)", b2 <= a * 1.02 + 0.5)
        else:
            rep.add("W1-7: kolejka odziezy wojska (czeka)", f"d{f0}: {wait(clo[f0])}; d{f1}: {wait(clo[f1])}", "bez wzrostu d90 -> until (gdy okno siega d92)", None)
    rep.add("W1-8: receptury - wszystkie linie z zakresu (ostatnia sesja)", "; ".join(f"{p[0]}: {p[3]} -> {p[4]}" for p in pairs) or "brak", "INFO", None)


def etap5_w3(rep, lines, start, until):
    """E6/W3 (221, projekt etapu 6 v2 rozdz. 3 "E6/W3" Test): linie "Regulator wsi (221): dzien N - ..." (start pomiaru, koniec kubelka, decyzja co 28 dob,
    stan z zapisu), "BK gnicie surowcow (174.3): dzien N - skasowano X szt." i ksiegi "Towary: dzien N - <towar> (W d): zapas S" (dzien = doba gry - 1, okno
    doby kampanii 1-until jak etap5_main). Wiazace: regulator CZYNNY w oknie, pierwsza decyzja do d60 (nowa kampania; gdy okno siega d60), kasowanie 0
    w kazdej dobie po dobie pierwszej decyzji, zaden towar nie zmienia kierunku w dwoch kolejnych decyzjach (gdy >= 2 decyzje), potkniecia 0; sol i glina -
    stos z ostatniej decyzji regulatora <= 60 dni zuzycia albo decyzja w gore (ponad 60 dni - zapas bez wzrostu <= +2% od tej decyzji; towar
    bez decyzji - zapas d90 -> until bez wzrostu <= +2%; gdy okno siega d92); mnozniki ostatniej decyzji i liczba decyzji w dol / w gore - INFO."""
    reg = {}
    for d, s in by_day(lines, "Regulator wsi (221): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            reg[rd] = s
    if not reg:
        rep.add("W3-1: linie Regulator wsi (221)", "brak linii w oknie", "jest od wgrania E6/W3", None)
        return
    off = [rd for rd, s in reg.items() if "WYLACZONY" in s or "NIEAKTYWNY" in s]
    rep.add("W3-1: regulator wsi CZYNNY w oknie", f"linii {len(reg)}, wylaczony/nieaktywny w {len(off)}" + (f" (np. d{min(off)})" if off else ""),
            "CZYNNY (klucz HarvestValve)", len(off) == 0)
    dec = {rd: s for rd, s in reg.items() if " - CZYNNY, decyzja " in s}
    fresh = any("start pomiaru" in s for s in reg.values())
    first = min(dec) if dec else None
    if first is not None:
        k = num(r"decyzja (\d+) \(", dec[first], int, 0) or 0
        rep.add("W3-2: pierwsza decyzja regulatora", f"d{first} (decyzja {k})", "do d60 (nowa kampania: 56 dob po starcie pomiaru)",
                (first <= 60) if fresh and k == 1 else None)
    else:
        rep.add("W3-2: pierwsza decyzja regulatora", "brak decyzji w oknie", "do d60 (gdy okno siega d60)",
                (False if fresh and max(reg) >= 60 else None))
    rot = {}
    for d, s in by_day(lines, "BK gnicie surowcow (174.3): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rot[rd] = num(r"skasowano (\d+) szt", s, int, 0) or 0
    if first is not None:
        after = {rd: x for rd, x in rot.items() if rd > first}
        bad = sorted(rd for rd, x in after.items() if x > 0)
        pre = [x for rd, x in rot.items() if rd <= first]
        rep.add("W3-3: kasowanie towaru po pierwszej decyzji (BK gnicie 174.3)",
                f"dob {len(after)}, z kasowaniem > 0: {len(bad)}" + (f" (np. d{bad[0]}: {after[bad[0]]})" if bad else "")
                + f"; przed decyzja srednio {sum(pre) / max(1, len(pre)):.0f}/d",
                "0 w kazdej dobie (projekt: 135/d -> 0)", (len(bad) == 0) if after else None)
    else:
        rep.add("W3-3: kasowanie towaru po pierwszej decyzji", "brak decyzji w oknie", "0 od pierwszej decyzji", None)
    flips = sum(num(r"zmiany kierunku w kolejnych decyzjach (\d+)", s, int, 0) or 0 for s in dec.values())
    rep.add("W3-4: zmiany kierunku towaru w dwoch kolejnych decyzjach (suma okna)", f"{flips} w {len(dec)} decyzjach", "0 (brak kolysania)",
            (flips == 0) if len(dec) >= 2 else None)
    stu = max((num(r"potkniecia (\d+)\.", s, int, 0) or 0) for s in reg.values())
    rep.add("W3-5: potkniecia regulatora wsi (najwiecej w oknie)", str(stu), "0", stu == 0)
    ser = {}
    for s in lines:
        if s.startswith("Towary: dzien "):
            m = re.match(r"Towary: dzien (\d+) - (\w+) \([^)]*\): zapas (-?\d+)", s)
            if m and m.group(2) in ("salt", "clay"):
                rd = run_day(int(m.group(1)), start)
                if 1 <= rd <= until:
                    ser.setdefault(m.group(2), {})[rd] = int(m.group(3))
    # narzedzie progow zb58 (TRIAZ W3-6 sol, glina): prog "bez wzrostu" zakladal nadmiar sprzed zakupow wsi E5/B1 i przeczyl pasmu regulatora. Ocena
    # z ostatniej decyzji regulatora dla towaru: stos D <= HI (ValveStockDaysHigh 60) albo decyzja "w gore" - wzrost zamierzony (sol: 10 dni, x1.30;
    # glina: 41 dni w pasmie - ciecie dopiero powyzej 60); dopiero przy D > HI wymagany brak wzrostu zapasu (<= +2%) od tej decyzji. Towar bez decyzji
    # w oknie - stara regula d90 -> until.
    vdec, vlo, vhi = valve_decisions(lines, start, until)
    for key, name in (("salt", "sol"), ("clay", "glina")):
        x = ser.get(key, {})
        ks = [d for d in x if d <= 90]
        if not x or not ks or max(x) < 92:
            rep.add(f"W3-6: {name} - zapas d90 -> until", "za krotkie okno albo brak linii Towary", "bez wzrostu <= +2% (gdy okno siega d92)", None)
            continue
        a, e = x[max(ks)], max(x)
        dd = vdec.get(key, [])
        if not dd:
            rep.add(f"W3-6: {name} - zapas d90 -> until", f"d{max(ks)} {a} -> d{e} {x[e]}", "bez wzrostu (<= +2%)", x[e] <= a * 1.02 + 1)
            continue
        rd, dn, dirn, stos, cons, prod, okno = dd[-1]
        ups = [q[0] for q in dd if q[2] == "w gore"]
        txt = f"d{max(ks)} {a} -> d{e} {x[e]}; regulator d{rd}: stos {stos} = {dn} dni zuzycia, {dirn}" + (f" (w gore w d{ups[-1]})" if ups and dirn != "w gore" else "")
        if dn <= vhi or dirn == "w gore":
            txt += f" - {'ponizej pasma' if dn < vlo else 'w pasmie'} {vlo}-{vhi}, wzrost zamierzony"
            grow = (prod - cons) / float(max(1, okno))
            if vlo <= dn <= vhi and grow > 0 and cons > 0:
                txt += f"; przy {grow:+.0f}/d stos {vhi} dni ok. d{rd + (vhi * cons / float(okno) - stos) / grow:.0f} - wtedy ciecie (prog wiazacy w biegu dlugim)"
            rep.add(f"W3-6: {name} - zapas d90 -> until", txt, f"stos regulatora <= {vhi} dni zuzycia albo decyzja w gore; ponad {vhi} dni - zapas bez wzrostu "
                    "(<= +2%) od tej decyzji", True)
        else:
            kd = [d for d in x if d <= rd]
            base = x[max(kd)] if kd else a
            rep.add(f"W3-6: {name} - zapas d90 -> until", txt + f" - ponad pasmo {vlo}-{vhi}; zapas od decyzji {base} -> {x[e]}",
                    f"stos regulatora <= {vhi} dni zuzycia albo decyzja w gore; ponad {vhi} dni - zapas bez wzrostu (<= +2%) od tej decyzji", x[e] <= base * 1.02 + 1)
    if dec:
        last = dec[max(dec)]
        i, j = last.find(": ["), last.rfind("]; w dol")
        body = last[i + 3:j] if i >= 0 and j > i else ""
        moved = [p.split(",")[0] for p in body.split("; ") if " -> x" in p]
        rep.add("W3-7: ostatnia decyzja - towary ze zmiana mnoznika", f"d{max(dec)}: " + ("; ".join(moved) or "brak"), "INFO", None)
        dirs = []
        for rd, s in sorted(dec.items()):
            dn = num(r"w dol (\d+), w gore", s, int, 0)
            upn = num(r"w gore (\d+), bez zmian", s, int, 0)
            dirs.append(f"d{rd}: w dol {dn}, w gore {upn}")
        rep.add("W3-8: decyzje w oknie (w dol / w gore)", "; ".join(dirs), "INFO", None)


def etap5_k4(rep, lines, start, until):
    """E6/K4 (220, projekt etapu 6 v2 rozdz. 3 "E6/K4" Test i rozdz. 4 prog 6.12): linie "Hodowla (220): dzien N - ..." (doba: CZYNNA | produkcja doby,
    WYLACZONA, NIEAKTYWNA, CZYNNA od tej doby, start pomiaru koni; decyzja co 28 dob) i "Przeglad stadnin (220)" (dzien = doba gry - 1, okno 1-until jak
    etap5_main). Wiazace: hodowla CZYNNA w oknie (klucz HorseBreedingByDemand i regulator wsi), podaz koni bojowych d61-until > d1-60 (srednio na dobe, gdy
    w decyzji do d60 bojowe chciane i okno siega d90), stos zwyklych w kazdej decyzji po przesunieciu > 0 nie ponizej dolnego progu stosu (30 dni zuzycia),
    zaden kierunek kategorii nie zmienia sie w dwoch kolejnych decyzjach (gdy >= 2 decyzje), potkniecia 0; bieg roczny (okno >= d360): stos koni na targu
    d180 -> until bez trendu (+-10%); mnozniki i przesuniecie ostatniej decyzji, ciecie na sucho, przeglad stadnin - INFO."""
    day_l, dec_l, rev = {}, {}, None
    for s in lines:
        if s.startswith("Przeglad stadnin (220): dzien "):
            rev = s
            continue
        if not s.startswith("Hodowla (220): dzien "):
            continue
        d = num(r"dzien (\d+)", s)
        if d is None:
            continue
        rd = run_day(d, start)
        if not (1 <= rd <= until):
            continue
        if " - decyzja " in s:
            dec_l[rd] = s
        else:
            day_l[rd] = s
    if not day_l and not dec_l:
        rep.add("K4-1: linie Hodowla (220)", "brak linii w oknie", "jest od wgrania E6/K4", None)
        return
    off = sorted(rd for rd, s in day_l.items() if "WYLACZONA" in s or "NIEAKTYWNA" in s)
    act = {rd: s for rd, s in day_l.items() if " - CZYNNA |" in s}
    rep.add("K4-1: hodowla wedlug popytu CZYNNA w oknie", f"linii doby CZYNNA {len(act)}, wylaczona/nieaktywna {len(off)}" + (f" (np. d{off[0]})" if off else ""),
            "CZYNNA (klucze HorseBreedingByDemand i HarvestValve)", len(off) == 0 and len(act) > 0)

    def prod(s):
        m = re.search(r"produkcja doby zwykly/bojowy/szlachetny/juczny (\d+)/(\d+)/(\d+)/(\d+)", s)
        return [int(x) for x in m.groups()] if m else None

    a = [prod(s)[1] for rd, s in act.items() if rd <= 60 and prod(s)]
    b = [prod(s)[1] for rd, s in act.items() if rd >= 61 and prod(s)]
    early = sorted(rd for rd in dec_l if rd <= 60)
    wanted = ("bojowe chciane TAK" in dec_l[early[0]]) if early else None
    if a and b and max(act) >= 90:
        ma, mb = sum(a) / len(a), sum(b) / len(b)
        note = (f"; bojowe chciane w decyzji d{early[0]}: {'TAK' if wanted else 'NIE'}" if early else "; brak decyzji do d60")
        rep.add("K4-2: podaz koni bojowych d61-until wobec d1-60 (srednio na dobe)", f"{ma:.1f} -> {mb:.1f}{note}",
                "wiecej (gdy bojowe chciane; projekt 6.12)", (mb > ma) if wanted else None)
    else:
        rep.add("K4-2: podaz koni bojowych d61-until wobec d1-60", "za krotkie okno albo brak linii doby", "wiecej (gdy okno siega d90 i bojowe chciane)", None)
    bad, chk = [], 0
    for rd, s in sorted(dec_l.items()):
        sh = re.search(r"przesuniecie zwykle -> bojowe ([\d.]+)% -> ([\d.]+)%", s)
        lo = num(r"stos (\d+)-\d+ dni zuzycia", s, int, 30) or 30
        z = re.search(r"\[zwykly: [^;\]]*?stos (\d+) = (\d+) dni zuzycia", s)
        if sh and float(sh.group(1)) > 0:
            chk += 1
            if z and int(z.group(2)) < lo:
                bad.append(f"d{rd}: {z.group(2)} dni")
    rep.add("K4-3: stos zwyklych w decyzjach po przesunieciu zwykle -> bojowe", f"decyzji z przesunieciem {chk}, ponizej progu {len(bad)}" + (f" ({'; '.join(bad[:3])})" if bad else ""),
            ">= dolny prog stosu (30 dni zuzycia)", (len(bad) == 0) if chk else None)
    flips = sum(num(r"zmiany kierunku w kolejnych decyzjach (\d+)", s, int, 0) or 0 for s in dec_l.values())
    rep.add("K4-4: zmiany kierunku kategorii koni w dwoch kolejnych decyzjach (suma okna)", f"{flips} w {len(dec_l)} decyzjach", "0 (brak kolysania)",
            (flips == 0) if len(dec_l) >= 2 else None)
    stu = max([num(r"potkniecia (\d+)\.", s, int, 0) or 0 for s in list(act.values()) + list(dec_l.values())] or [0])
    rep.add("K4-5: potkniecia regulatora (najwiecej w liniach Hodowla)", str(stu), "0", stu == 0)
    if dec_l:
        last = dec_l[max(dec_l)]
        sh = re.search(r"przesuniecie zwykle -> bojowe ([\d.]+%) -> ([\d.]+%)", last)
        i, j = last.find(": ["), last.find("] | przesuniecie")
        body = last[i + 3:j] if i >= 0 and j > i else ""
        mult = [p.split(",")[0] for p in body.split("; ")]
        rep.add("K4-6: ostatnia decyzja - mnozniki kategorii i przesuniecie", f"d{max(dec_l)}: " + "; ".join(mult) + (f" | przesuniecie {sh.group(1)} -> {sh.group(2)}" if sh else ""), "INFO", None)
        dry = re.search(r"\| ciecie na sucho: (.*?) \(czynne", last)
        rep.add("K4-7: ciecie na sucho (ostatnia decyzja)", dry.group(1) if dry else "-", "INFO (czynne po biegu rocznym)", None)
    else:
        rep.add("K4-6: decyzje hodowli", "brak decyzji w oknie", "INFO (pierwsza 56 dob po starcie pomiaru)", None)
    if rev:
        rep.add("K4-8: przeglad stadnin", rev.split(" - ", 1)[-1][:300], "INFO", None)
    st = {}
    for rd, s in act.items():
        m = re.search(r"stos na targu \(spis co \d+ dob\) (\d+)/(\d+)/(\d+)/(\d+)", s)
        if m:
            st[rd] = sum(int(x) for x in m.groups())
    if st and max(st) >= 360:
        ks = [d for d in st if d >= 180]
        a0, e0 = st[min(ks)], st[max(st)]
        rep.add("K4-9: bieg roczny - konie na targu d180 -> until", f"d{min(ks)} {a0} -> d{max(st)} {e0}", "bez trendu (+-10%)", abs(e0 - a0) <= 0.10 * max(1, a0))
    else:
        rep.add("K4-9: bieg roczny - konie na targu bez trendu", "okno krotsze niz d360", "+-10% (tylko bieg roczny)", None)


def etap5_k3(rep, lines, start, until, logp=None):
    """E6/K3 (219, projekt etapu 6 v2 rozdz. 3 "E6/K3" Test; rozdz. 4 prog 6.14): linia doby "Rycerze i jazda (219): dzien N | ..." (dzien = doba gry, okno
    1-until jak etap5_main). Progi po triazu zb58 (miara = to, czym K3 steruje - konni wsrod ludzi t3+): wykonanie celu szablonow (t3+ % / cel %) srednio
    >= 80% w d91-until (bieg roczny >= 90%) i nie spada wobec d61-90 (tolerancja 2 pp), Dothrakowie (khuzait) t3+ >= 90% celu i czekajacy na konia
    <= 10% ludzi (konie-krolestwa.csv), Zelazne Wyspy (sturgia) <= 5%, Wolni Ludzie (freefolk) t3+ <= cel szablonow + 3 pp, czeka na konia swojej
    kategorii - mediana dziennej zmiany w d91-until <= +30/d (TRIAZ-2 K3-8; poziom wobec braku do celu t3+ bez khuzait - INFO), K3-4b jezdzcy z para
    (spis E8/H) d91-until >= d61-90,
    przerwa "zostaje (K3 bez K2)" 0 przy czynnej sprzedazy K2(b), potkniecia 0; jazda wszystkich ludzi z sufitem (12% / 60% wiazace tylko w biegu
    rocznym), decyzje sterowania przy rozwidleniu z awansami wykonanymi (linia "Konie AI (175)"), konie rycerzy (stada, targ, zloto, budzet sprzetu) -
    INFO. Pompa koni - K2-5, wojsko lordow i bankruci - progi E2/E5."""
    seg = {}
    for d, s in by_day(lines, "Rycerze i jazda (219): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            seg[rd] = s
    rep.add("K3-1: linia Rycerze i jazda (219)", f"{len(seg)} dob", "codziennie od wgrania E6/K3 (linia przy Stage6MeasureLog albo kluczach K3)", None)
    if not seg:
        return
    days = sorted(seg)
    off = [x for x in days if "jazda wedlug szablonu CZYNNE" not in seg[x] or "kon rycerza od rodu CZYNNE" not in seg[x]]
    rep.add("K3-2: E6/K3 CZYNNE w dobach okna (oba klucze)", f"{len(days) - len(off)} z {len(days)}" + (f"; ostatnia nieczynna d{off[-1]}" if off else ""),
            "wszystkie doby (CavalryShareByTemplate, KnightHorseFromHouse; wymaga AiSellsSpareHorses)", len(off) == 0)

    def share(s):
        return num(r"\| jazda partii ([\d.]+)%", s, float)

    def realm(s, kid):
        m = re.search(r"(?:\[|, )" + re.escape(kid) + r" ([\d.]+)%/t3 ([\d.]+)% \(cel ([\d.]+)%", s)
        return (float(m.group(1)), float(m.group(2)), float(m.group(3))) if m else None

    def mean(v):
        return sum(v) / len(v) if v else None
    lo = 91 if until >= 91 and any(x >= 91 for x in days) else None
    w91 = [x for x in days if lo is not None and x >= lo]
    w61 = [x for x in days if 61 <= x <= 90]
    a91 = mean([v for v in (share(seg[x]) for x in w91) if v is not None])
    a61 = mean([v for v in (share(seg[x]) for x in w61) if v is not None])
    # narzedzie progow zb58 (TRIAZ K3-3 "Poprawka ostateczna" B i "K3-3 / K3-5 / K3-8 - miara progow"): K3 steruje udzialem konnych wsrod ludzi t3+
    # (CavalryTemplate), a stare progi mierzyly wszystkich ludzi z rekrutami t1-t2 - sufit miary przy pelnym celu to ok. 12.7% (d91-120), wiec 12% bylo
    # 95% sufitu, a Dothrakom (cel 99%, t3+ 97.9%) brakowalo nie K3, tylko koni dla rekrutow t1. Wiazace teraz: K3-3 wykonanie celu = srednia (t3+ %)
    # / srednia (cel szablonow %) w d91-until >= 80% (bieg roczny >= 90%); K3-4 to samo wykonanie nie spada wobec d61-90 (tolerancja 2 pp); K3-5a
    # Dothrakowie t3+ >= 90% celu; K3-5 czekajacy Dothrakow <= 10% ludzi (konie-krolestwa.csv - prawdziwy objaw: rekruci t1 bez konia). Udzial jazdy
    # wszystkich ludzi - INFO z sufitem; 12% (i 60% Dothrakow) zostaje progiem tylko w biegu rocznym (okno >= d360).
    def tmpl(s):
        m = re.search(r"konnych (\d+) z (\d+) ludzi .*?; t3\+ ([\d.]+)% z (\d+) wobec celu szablonow ([\d.]+)%", s)
        return (int(m.group(1)), int(m.group(2)), float(m.group(3)), int(m.group(4)), float(m.group(5))) if m else None

    def done(ds):
        tt = [t for t in (tmpl(seg[x]) for x in ds) if t]
        got, goal = mean([t[2] for t in tt]), mean([t[4] for t in tt])
        return (100.0 * got / goal, got, goal) if tt and goal else None

    def ceil_of(ds):
        tt = [t for t in (tmpl(seg[x]) for x in ds) if t and t[1] > 0]
        return mean([100.0 * (t[4] / 100.0 * t[3] + max(0.0, t[0] - t[2] / 100.0 * t[3])) / t[1] for t in tt])
    year = until >= 360 and days[-1] >= 360
    khz = {}
    cp = session_file_find(logp, "konie-krolestwa.csv") if logp else None
    if cp and os.path.exists(cp):
        try:
            with open(cp, encoding="utf-8", errors="replace") as fh:
                for r in csv.DictReader(fh, delimiter=";"):
                    if r.get("krolestwo") == "khuzait":
                        khz[run_day(int(r["dzien"]), start)] = (int(r["czeka"]), int(r["wszyscy"]))
        except (KeyError, ValueError, OSError):
            khz = {}
    if a91 is None:
        allv = [v for v in (share(seg[x]) for x in days) if v is not None]
        e0 = done(days)
        rep.add("K3-3: jazda t3+ wobec celu szablonow srednio w d91-until", "okno nie siega d91 (" + (f"wykonanie celu {e0[0]:.0f}%, " if e0 else "")
                + f"jazda partii srednio {mean(allv) or 0:.1f}% w d{days[0]}-{days[-1]})", ">= 80% celu [S]", None)
    else:
        e91, e61 = done(w91), done(w61)
        cl = ceil_of(w91)
        # narzedzie progow p2 (TRIAZ-2 K3-3 / K3-4 "Poprawka ostateczna" pkt 4): spis par E8/H (jezdziec = kon + uprzaz) w tych samych oknach - K3-3 i K3-4
        # licza TYP jednostki (CavalryTemplate, IsMounted), a przy bramie uprzezy awans na jezdnego czeka na siodlo; prog K3-3 zostaje, dopisek mowi, na co czeka
        h_pair = {}
        for d, s in by_day(lines, E8_H_LINE).items():
            rd = run_day(d, start)
            if 61 <= rd <= until and "| regula [WL]" in s:
                g = e8h_group(s, "partie rodow AI")
                if g:
                    h_pair[rd] = g["para"]
        if e91:
            ok3 = e91[0] >= (90.0 if year else 80.0)
            rep.add(f"K3-3: jazda t3+ wobec celu szablonow srednio w d91-{until} (wykonanie celu K3)",
                    f"{e91[0]:.0f}% (t3+ {e91[1]:.1f}% przy celu {e91[2]:.1f}%)"
                    + (" - przy bramie uprzezy E8/H awanse na jezdnego czekaja na podaz siodel (H-1 / H-3); nie regresja K3" if (not ok3 and h_pair) else ""),
                    (">= 90% celu (bieg roczny)" if year else ">= 80% celu [S] (bieg roczny >= 90%)"), ok3)
        else:
            rep.add(f"K3-3: jazda t3+ wobec celu szablonow srednio w d91-{until}", "brak udzialu t3+ i celu w linii", ">= 80% celu [S]", None)
        rep.add(f"K3-3b: jazda partii AI (wszyscy ludzie, z rekrutami t1-t2) srednio w d91-{until}",
                f"{a91:.1f}%" + (f"; sufit przy pelnym celu t3+ {cl:.1f}%" if cl is not None else ""),
                ">= 12% [S] (bieg roczny 18-22%)" if year else "INFO (12% i 18-22% to progi biegu rocznego; wzorzec W33 7.4%)", (a91 >= 12.0) if year else None)
        if e91 and e61:
            def t3n(ds):
                tt = [t for t in (tmpl(seg[x]) for x in ds) if t]
                return mean([t[3] for t in tt]) or 0.0, mean([t[2] / 100.0 * t[3] for t in tt]) or 0.0
            (m61, c61), (m91, c91) = t3n(w61), t3n(w91)
            rep.add("K3-4: wykonanie celu K3 nie spada (d61-90 -> d91-until)", f"{e61[0]:.0f}% -> {e91[0]:.0f}% (jazda partii {a61:.1f}% -> {a91:.1f}%; "
                    f"ludzi t3+ {m61:.0f} -> {m91:.0f}, konnych t3+ wedlug typu {c61:.0f} -> {c91:.0f})",
                    "nie mniej niz d61-90 - 2 pp", e91[0] >= e61[0] - 2.0)
        elif a61 is not None:
            rep.add("K3-4: jazda partii nie spada (d61-90 -> d91-until)", f"{a61:.1f}% -> {a91:.1f}%", "nie mniej niz d61-90 - 0.3 pp", a91 >= a61 - 0.3)
        # narzedzie progow p2 (TRIAZ-2 K3-4 pkt 4b): K3-4 liczy TYP jednostki - spadek moze znaczyc "mniej konnych wedlug typu bez konia", a nie mniej jazdy.
        # K3-4b: jezdzcy z para (kon + uprzaz) partii rodow AI ze spisu E8/H, srednia d91-until >= srednia d61-90; tylko doby z regula [WL] (log bez linii
        # E8/H albo bez reguly - bez wiersza). K3-4 NIE przy K3-4b TAK czytac: maleje kolejka wedlug typu, prawdziwa jazda rosnie.
        p61, p91 = [v for rd, v in h_pair.items() if rd <= 90], [v for rd, v in h_pair.items() if rd >= 91]
        if p61 and p91:
            rep.add(f"K3-4b: prawdziwa jazda partii rodow AI - jezdzcy z para (kon + uprzaz) d61-90 -> d91-{until} (linia Jezdzcy i uprzaz (E8/H))",
                    f"{mean(p61):.0f} -> {mean(p91):.0f} ({len(p61)} i {len(p91)} dob z regula)",
                    ">= srednia d61-90 (K3-4 NIE przy K3-4b TAK = maleje kolejka wedlug typu, prawdziwa jazda rosnie)", mean(p91) >= mean(p61))
        rr = [r for r in (realm(seg[x], "khuzait") for x in w91) if r]
        if not rr:
            rep.add(f"K3-5: jazda partii - Dothrakowie (khuzait) d91-{until}", "brak krainy w linii", "t3+ >= 90% celu; czeka <= 10% ludzi", None)
        else:
            m0, t3, tg = mean([r[0] for r in rr]), mean([r[1] for r in rr]), mean([r[2] for r in rr])
            kw = [khz[x] for x in w91 if x in khz]
            if kw and sum(b for _, b in kw) > 0:
                wsh = 100.0 * sum(a for a, _ in kw) / sum(b for _, b in kw)
                rep.add(f"K3-5: Dothrakowie (khuzait) - czekajacy na konia wobec ludzi d91-{until} (konie-krolestwa.csv, lordowie i zalogi)",
                        f"{wsh:.1f}% (czeka srednio {mean([a for a, _ in kw]):.0f} z {mean([b for _, b in kw]):.0f} ludzi; {len(kw)} dob)",
                        "<= 10% (rekrut t1 Dothrakow ma jeden cel - konnego t2; bez konia czeka)", wsh <= 10.0)
            else:
                rep.add(f"K3-5: Dothrakowie (khuzait) - czekajacy na konia wobec ludzi d91-{until}", "brak konie-krolestwa.csv albo wierszy khuzait w oknie",
                        "<= 10% (plik sesji konie-krolestwa.csv)", None)
            rep.add(f"K3-5a: Dothrakowie (khuzait) - jazda t3+ wobec celu szablonow d91-{until}", f"{100.0 * t3 / tg:.0f}% (t3+ {t3:.1f}% przy celu {tg:.1f}%)" if tg
                    else f"t3+ {t3:.1f}%, cel 0", ">= 90% celu", (t3 >= 0.9 * tg) if tg else None)
            rep.add(f"K3-5b: jazda partii - Dothrakowie (khuzait), wszyscy ludzie d91-{until}", f"{m0:.1f}%",
                    ">= 60% [S]" if year else "INFO (60% to prog biegu rocznego - rekruci t1 czekaja na konia; sufit szablonu ok. 63%)", (m0 >= 60.0) if year else None)
        for code, kid, name, rule, ok in (("K3-6", "sturgia", "Zelazne Wyspy", "<= 5% [S]", lambda r: r[0] <= 5.0),):
            rr = [realm(seg[x], kid) for x in w91]
            rr = [r for r in rr if r]
            if not rr:
                rep.add(f"{code}: jazda partii - {name} ({kid}) d91-{until}", "brak krainy w linii", rule, None)
                continue
            m0 = mean([r[0] for r in rr])
            rep.add(f"{code}: jazda partii - {name} ({kid}) d91-{until}", f"{m0:.1f}% (t3+ {mean([r[1] for r in rr]):.1f}%, cel szablonow {mean([r[2] for r in rr]):.1f}%)",
                    rule, ok((m0, 0, 0)))
        rr = [r for r in (realm(seg[x], "freefolk") for x in w91) if r]
        if rr:
            t3, tg = mean([r[1] for r in rr]), mean([r[2] for r in rr])
            rep.add(f"K3-7: Wolni Ludzie (freefolk) t3+ wobec celu szablonow d91-{until}", f"{t3:.1f}% przy celu {tg:.1f}%", "<= cel + 3 pp", t3 <= tg + 3.0)
        else:
            rep.add(f"K3-7: Wolni Ludzie (freefolk) t3+ wobec celu szablonow d91-{until}", "brak krainy w linii", "<= cel + 3 pp", None)
        wd = {x: num(r"\| czeka (\d+)", seg[x]) for x in days}
        wd = {x: v for x, v in wd.items() if v is not None}
        wv = [wd[x] for x in w91 if x in wd]
        if len(wv) >= 10:
            f5, l5 = mean(wv[:5]), mean(wv[-5:])
            # narzedzie progow p2 (TRIAZ-2 K3-8 "Poprawka ostateczna" pkt 1): miare "5 ostatnich dob < 5 pierwszych" rozstrzygala jedna przegrana bitwa
            # (a589def: Dothrakowie d100 -> d101 czeka -511 przy stracie 504 ludzi - stad jedyne TAK; bez dni strat kolejka rosla w kazdym biegu:
            # a589def +36/d, W33 +18/d, bieg 2 zbior-e8 +55/d). Wiazaca jest MEDIANA dziennej zmiany w d91-until (odporna na pojedyncza bitwe):
            # <= +30/d = 1.25 x baza a589def (+24; W33 +22). Cel "maleje" (<= 0) - INFO do czasu paczki limitu polki koni (AiMountMarketSharePercent).
            dif = sorted(wd[x] - wd[x - 1] for x in w91 if x in wd and (x - 1) in wd)
            if len(dif) >= 10:
                med = dif[len(dif) // 2] if len(dif) % 2 else 0.5 * (dif[len(dif) // 2 - 1] + dif[len(dif) // 2])
                up, dn = sum(1 for v in dif if v > 0), [v for v in dif if v < 0]
                rep.add(f"K3-8: czeka na konia swojej kategorii d91-{until} (lordowie i zalogi AI) - mediana dziennej zmiany",
                        f"{med:+.0f}/d ({len(dif)} zmian dobowych: rosnie w {up}, spada w {len(dn)} - suma spadkow {sum(dn)}); 5 pierwszych dob {f5:.0f}, 5 ostatnich {l5:.0f}",
                        "<= +30/d (1.25 x baza a589def +24, W33 +22; miara odporna na jedna bitwe); cel <= 0 - INFO; NIE = znane, czeka na poprawke uprzezy "
                        "i limit polki koni (TRIAZ-2 K3-8)", med <= 30.0)
            else:
                rep.add(f"K3-8: czeka na konia swojej kategorii d91-{until} - mediana dziennej zmiany", f"{len(dif)} zmian dobowych (doby nie po kolei)",
                        "<= +30/d - potrzeba >= 10 zmian dobowych", None)
            # narzedzie progow zb58 (TRIAZ "K3-3 / K3-5 / K3-8 - miara", pkt 3): sam trend przechodzil przy poziomie 2.2 x wzorca i rownym brakowi do celu -
            # dochodzi poziom: czekajacy (bez Dothrakow - ich rekruci t1 to osobny wiersz K3-5) <= 0.5 x brak konnych do celu t3+ partii rodow
            gap = [t[3] * max(0.0, t[4] - t[2]) / 100.0 for t in (tmpl(seg[x]) for x in w91) if t]
            kwt = [khz[x][0] for x in w91 if x in khz]
            # narzedzie progow p2 (TRIAZ-2 K3-8 pkt 6 i "Poprawka ostateczna" pkt 1): prog 0.5 nie byl spelniony w zadnym biegu z K3 (a589def 2839 / ok. 3750
            # = 0.76; sterowanie liczy kazdy stos osobno - CavalryTemplate.WantRider / Steer), wiec nie odroznia biegow - wiersz INFO z baza
            if gap and kwt:
                wl, gp = mean(wv) - mean(kwt), mean(gap)
                rep.add(f"K3-8b: czeka na konia - poziom wobec braku do celu t3+ d91-{until} (bez khuzait)",
                        f"czeka srednio {wl:.0f} (wszyscy {mean(wv):.0f}, khuzait {mean(kwt):.0f}) wobec braku do celu t3+ {gp:.0f}"
                        + (f" = {wl / gp:.2f}" if gp > 0 else ""),
                        "INFO (baza a589def 0.76; stary prog 0.5 niespelniony w zadnym biegu z K3 - TRIAZ-2 K3-8)", None)
            else:
                rep.add(f"K3-8b: czeka na konia - poziom wobec braku do celu t3+ d91-{until} (bez khuzait)",
                        "brak konie-krolestwa.csv (czekajacy khuzait) albo udzialu t3+ w linii", "INFO (baza a589def 0.76)", None)
        else:
            rep.add(f"K3-8: czeka na konia swojej kategorii d91-{until}", f"{len(wv)} dob z pomiarem (Army175Measure)", "nie rosnie - potrzeba >= 10 dob", None)
    rows = [seg[x] for x in days]
    kept = sum(num(r"zostaje \(K3 bez K2\) (\d+)", x, int, 0) or 0 for x in rows)
    lifted = sum(num(r"przerwa: zdjeta (\d+)", x, int, 0) or 0 for x in rows)
    sell = all("pominieta K2(b): TAK" in x for x in rows)
    stu = sum(num(r"potkniecia dzis (\d+)", x, int, 0) or 0 for x in rows)
    rep.add("K3-9: przerwa zakupow (zdjeta / zostaje K3 bez K2) i potkniecia (suma okna)", f"zdjeta {lifted}, zostaje {kept}, potkniecia {stu}"
            + ("" if sell else " (sprzedaz K2(b) nie we wszystkich dobach)"), "zostaje 0 przy czynnym K2(b), potkniecia 0", (kept == 0 if sell else True) and stu == 0)

    def cats(pat, x):
        m = re.search(pat, x)
        return [int(v) for v in m.groups()] if m else [0, 0, 0]
    herd, mkt = [0, 0, 0], [0, 0, 0]
    for x in rows:
        h = cats(r"ze stad wsi postoju (\d+)/(\d+)/(\d+)", x)
        k = cats(r"z targu (\d+)/(\d+)/(\d+)", x)
        herd = [herd[i] + h[i] for i in range(3)]
        mkt = [mkt[i] + k[i] for i in range(3)]
    th, tf, gold, gear = (sum(num(p, x, int, 0) or 0 for x in rows) for p in (
        r"awanse przy rozwidleniu: do jazdy (\d+)", r", do piechoty (\d+) ludzi", r"z targu \d+/\d+/\d+, za (\d+) zl", r"\(budzet sprzetu (\d+)\)"))
    # narzedzie progow zb58 (TRIAZ K3-10): licznik "awanse przy rozwidleniu" nie liczy awansow - CavalryTemplate dodaje n przy kazdym wywolaniu
    # GetPossibleUpgradeTargets przed filtrem koni, wiec ci sami czekajacy sa liczeni co dobe (osobo-proby). Awanse wykonane, skret w piechote i czekajacy
    # - z linii "Konie AI (175)" tych samych dob.
    kai = {}
    for d, s in by_day(lines, "Konie AI (175): dzien").items():
        if run_day(d, start) in seg:
            kai[run_day(d, start)] = s
    kr = [kai[x] for x in sorted(kai)]
    dn, dz, db, dsz, skr = (sum(num(p, x, int, 0) or 0 for x in kr) for p in (
        r"awanse na jezdzca: wykonane (\d+)", r"awanse na jezdzca: wykonane \d+ \(zwykly (\d+)", r"awanse na jezdzca: wykonane \d+ \(zwykly \d+, bojowy (\d+)",
        r"awanse na jezdzca: wykonane \d+ \(zwykly \d+, bojowy \d+, szlachetny (\d+)", r"proby odrzucone z braku konia \d+ \(skret (\d+)"))
    wlast = num(r"stan: czeka na konia swojej kategorii (\d+) ludzi", kr[-1], int) if kr else None
    rep.add("K3-10: decyzje sterowania przy rozwidleniu (osobo-proby - czekajacy liczeni co dobe) i konie rycerzy od rodu (suma okna)",
            f"decyzje do jazdy {th}, do piechoty {tf}" + (f"; awanse wykonane na jezdzca {dn} (zwykly {dz}, bojowy {db}, szlachetny {dsz}), skret w piechote {skr}, "
                                                           f"czeka (ostatnia doba) {wlast} - linia Konie AI (175), {len(kr)} dob" if kr else "")
            + f"; konie rycerzy ze stad wsi postoju {'/'.join(map(str, herd))}, z targu {'/'.join(map(str, mkt))} (zwykly/bojowy/szlachetny) za {gold} zl "
            f"(budzet sprzetu {gear})", "INFO", None)
    _k3_f5(rep, lines, start, until, seg, days)


def _k3_f5(rep, lines, start, until, seg, days):
    """Narzedzie progow F9b: wiersze poprawki F5 (konie lordow z przydzialu sprzetu rodu; okno d91-until). Pole linii "Rycerze i jazda (219)":
    "| zwykle konie z przydzialu sprzetu rodu (F5): CZYNNE udzial kiesy ponad rezerwe u, postoje n (budzet wyznaczyl przydzial a, kiesa b; bez budzetu:
    brak przydzialu c, brak zlota ponad rezerwe d), zdjete z przydzialu e zl; rycerze zatrzymani rezerwa kiesy f"; zakupy i nieudane wizyty z linii
    "Konie AI (175)" ("zakupy lordow: n koni ...; wizyt z potrzeba v ...), nieudane: brak zlota g, brak koni h (pusto .., za drogie i, ..), brak
    przydzialu sprzetu rodu j" - ostatnie pole od F5); korpus z "Pokrycie zbrojowni AI (171)"; przydzial i przeterminowane z "Budzet rodow (166)"."""
    w91 = [x for x in days if 91 <= x <= until]
    if not w91:
        rep.add("F5-1..F5-7: konie lordow z przydzialu sprzetu rodu (F5)", "okno nie siega d91", "progi F5 licza sie w d91-until", None)
        return
    f5d = [x for x in w91 if "| zwykle konie z przydzialu sprzetu rodu (F5): " in seg[x]]
    fre = re.compile(r"postoje (\d+) \(budzet wyznaczyl przydzial (\d+), kiesa (-?\d+); bez budzetu: brak przydzialu (\d+), brak zlota ponad rezerwe (\d+)\), "
                     r"zdjete z przydzialu (\d+) zl; rycerze zatrzymani rezerwa kiesy (\d+)")
    if not f5d:
        rep.add("F5-1: zwykle konie z przydzialu sprzetu rodu CZYNNE (linia Rycerze i jazda 219)",
                "brak linii (log sprzed F5 - bez pola \"zwykle konie z przydzialu sprzetu rodu (F5)\")", "CZYNNE w kazdej dobie d91-until i postoje > 0", None)
        rep.add("F5-5: postoje lordow z budzetem na konie (liczniki F5, linia 219)", "brak linii (log sprzed F5)", "INFO", None)
    else:
        offd = [x for x in w91 if "| zwykle konie z przydzialu sprzetu rodu (F5): CZYNNE" not in seg[x]]
        tt = [0] * 7
        for x in f5d:
            m = fre.search(seg[x])
            if m:
                for i in range(7):
                    tt[i] += int(m.group(i + 1))
        kn = sum(num(r"postoje z rycerzami (\d+)", seg[x], int, 0) or 0 for x in f5d)
        rep.add(f"F5-1: zwykle konie z przydzialu sprzetu rodu CZYNNE w kazdej dobie d91-{until} i postoje z budzetem > 0 (linia Rycerze i jazda 219)",
                f"CZYNNE w {len(w91) - len(offd)} z {len(w91)} dob" + (f" (ostatnia nieczynna d{offd[-1]})" if offd else "") + f"; postoje (suma okna) {tt[0]}",
                "CZYNNE we wszystkich dobach (WYLACZONE / NIECZYNNE = NIE) i suma postojow > 0", len(offd) == 0 and tt[0] > 0)
        warn = []
        if tt[0] and tt[1] > 0.5 * tt[0]:
            warn.append("przydzial wyznaczyl ponad 50% postojow")
        if kn and tt[6] > 0.1 * kn:
            warn.append("rezerwa kiesy zatrzymala ponad 10% postojow z rycerzami")
        rep.add(f"F5-5: postoje lordow z budzetem na konie (liczniki F5, suma d91-{until})",
                f"postoje {tt[0]}: budzet wyznaczyl przydzial {tt[1]}" + (f" ({100.0 * tt[1] / tt[0]:.0f}%)" if tt[0] else "") + f", kiesa {tt[2]}; bez budzetu: brak "
                f"przydzialu {tt[3]}, brak zlota ponad rezerwe {tt[4]}; zdjete z przydzialu {tt[5]} zl; rycerze zatrzymani rezerwa kiesy {tt[6]} z {kn} postojow "
                "z rycerzami" + (" - UWAGA [S]: " + ", ".join(warn) if warn else ""),
                "INFO (uwaga, gdy przydzial wyznaczyl > 50% postojow albo rezerwa zatrzymala > 10% postojow z rycerzami)", None)
    kr = []
    for d, s in sorted(by_day(lines, "Konie AI (175): dzien").items()):
        if 91 <= run_day(d, start) <= until:
            kr.append(s)
    buy = [v for v in (num(r"\| zakupy lordow: (\d+) koni", x, int) for x in kr) if v is not None]
    if buy:
        avg = sum(buy) / float(len(buy))
        # narzedzie progow p2 (TRIAZ-2 F5-2): 80/d bylo prognoza [S] przy zalozeniu, ze jedynym gardlem jest budzet postoju. Pomiar biegu 2: F5 dziala
        # (2.67 konia na zakup wobec 2.48, przydzial sprzetu wydany w 47% wobec 23%), a zakupy trzymaja nastepne gardla - pusta polka 37% wizyt z potrzeba
        # i limit 25% polki (AiMountMarketSharePercent). Wiazace: >= 1.15 x bieg bez F5 (a589def 50.8/d w tym oknie = 58.4/d); 80/d - cel INFO do biegu
        # po poprawce siodel i limitu polki.
        rep.add(f"F5-2: zakupy koni lordow srednio d91-{until} (linia Konie AI 175)", f"{avg:.1f}/d ({len(buy)} dob; cel prognozy F5 80-95/d - INFO)",
                ">= 58.4/d = 1.15 x bieg bez F5 (a589def 50.8 w tym oknie); prognoza 80/d [S] czeka na polki koni i siodla (TRIAZ-2 F5-2)", avg >= 58.4)
        vis = sum(num(r"; wizyt z potrzeba (\d+),", x, int, 0) or 0 for x in kr)
        dear = sum(num(r"brak koni \d+ \(pusto \d+, za drogie (\d+)", x, int, 0) or 0 for x in kr)
        nog = sum(num(r"nieudane: brak zlota (\d+)", x, int, 0) or 0 for x in kr)
        rep.add(f"F5-3: nieudane zakupy koni lordow \"za drogie\" wobec wizyt z potrzeba d91-{until}",
                f"{100.0 * dear / vis:.1f}% ({dear} z {vis} wizyt)" if vis else f"brak wizyt z potrzeba (za drogie {dear})",
                "<= 5% [S] (a589def 20%; powyzej - krok 2 TRIAZ: za konie placi glowa rodu; od F5 pole liczy tylko \"za drogie\" z kiesy pana)",
                (100.0 * dear / vis <= 5.0) if vis else None)
        nsh = [v for v in (num(r", brak przydzialu sprzetu rodu (\d+)", x, int) for x in kr) if v is not None]
        if nsh and vis:
            a, b = 100.0 * sum(nsh) / vis, 100.0 * nog / vis
            rep.add(f"F5-4: nieudane zakupy koni lordow - brak przydzialu sprzetu rodu i brak zlota wobec wizyt d91-{until}",
                    f"brak przydzialu {a:.1f}% ({sum(nsh)} z {vis}), brak zlota {b:.1f}% ({nog} z {vis})", "oba <= 10% wizyt [S]", a <= 10.0 and b <= 10.0)
        else:
            rep.add(f"F5-4: nieudane zakupy koni lordow - brak przydzialu sprzetu rodu i brak zlota wobec wizyt d91-{until}",
                    ("brak linii (log sprzed F5 - bez pola \"brak przydzialu sprzetu rodu\")" if not nsh else "brak wizyt z potrzeba")
                    + (f"; brak zlota {100.0 * nog / vis:.1f}% ({nog} z {vis})" if vis else ""), "oba <= 10% wizyt [S]", None)
    else:
        rep.add(f"F5-2..F5-4: zakupy koni lordow d91-{until} (linia Konie AI 175)", "brak linii Konie AI (175) z polem zakupow w oknie", "pomiar Army175Measure", None)
    cov = {}
    for d, s in by_day(lines, "Pokrycie zbrojowni AI (171): dzien").items():
        v = num(r"partie rodow AI \(\d+ ludzi\): korpus (\d+)%", s, int)
        if v is not None and 1 <= run_day(d, start) <= until:
            cov[run_day(d, start)] = v
    if cov:
        lc = max(cov)
        rep.add("F5-6: korpus partii rodow AI - ostatnia linia Pokrycie zbrojowni AI (171) w oknie", f"{cov[lc]}% (d{lc}; pierwsza d{min(cov)} {cov[min(cov)]}%)",
                ">= 62% [S] (a589def 65 - konie z przydzialu sprzetu nie moga zjesc zbroi)", (cov[lc] >= 62) if lc >= 91 else None)
    else:
        rep.add("F5-6: korpus partii rodow AI (linia Pokrycie zbrojowni AI 171)", "brak linii w oknie", ">= 62% [S]", None)
    bud = e4_series(lines, "Budzet rodow (166): dzien", 1)
    bw = [bud[d] for d in sorted(bud) if 91 <= run_day(d, start) <= until]
    gear = [(num(r"sprzet: przydzial dnia (\d+)", x, int), num(r"wydane przez panow od wczoraj (\d+)", x, int)) for x in bw]
    gear = [(a, b) for a, b in gear if a is not None and b is not None]
    lap = [v for v in (num(r"przeterminowane dzis (\d+)", x, int) for x in bw) if v is not None]
    twn = [v for v in (num(r"\(miasta (\d+) / zamki \d+\)", x, int) for x in bw) if v is not None]
    cas = [v for v in (num(r"\(miasta \d+ / zamki (\d+)\)", x, int) for x in bw) if v is not None]
    if gear:
        ga, gb = sum(a for a, _ in gear), sum(b for _, b in gear)
        rep.add(f"F5-7: przydzial sprzetu rodow - wydane, przeterminowane, do kas siedzib (linia Budzet rodow 166, srednio d91-{until})",
                f"wydane przez panow {gb / float(len(gear)):.0f} z przydzialu {ga / float(len(gear)):.0f} na dobe" + (f" ({100.0 * gb / ga:.0f}%)" if ga else "")
                + (f"; przeterminowane {sum(lap) / float(len(lap)):.0f}/d" if lap else "")
                + (f"; do kas siedzib: miasta {sum(twn) / float(len(twn)):.0f}/d, zamki {sum(cas) / float(len(cas)):.0f}/d" if twn and cas else ""),
                "INFO (a589def: wydane 23%, przeterminowane 156 tys./d, zamki 65 tys./d; oczekiwane po F5 [S]: 50-65%, 50-65 tys./d, zamki ok. 20 tys./d)", None)
    else:
        rep.add("F5-7: przydzial sprzetu rodow (linia Budzet rodow 166)", "brak linii z polem sprzetu w oknie", "INFO", None)


def etap5_n1(rep, lines, start, until):
    """E6/N1 (217, projekt etapu 6 v2 rozdz. 3 "E6/N1" Test): linie doby "Zuzycie AI: dzien N - lup obity a szt., zuzyte w bitwach b, naprawione w miastach c
    ...; pominiete (lup nienoszony) s szt., robocizna do kiesy ludu f. Material napraw z targu: ... czeka na material w szt. (metal, drewno, skora x, plotno)"
    (dzien = doba gry - 1, okno doby kampanii 1-until jak etap5_main) i "Odziez wojska (150): dzien N ... | czeka: ..." (skora kolejki odziezy).
    Wiazace (srednie d91-until, gdy okno siega d92; inaczej INFO): AiMendsWornOnly WLACZONE (segment "pominiete (lup nienoszony) N szt."), czeka na material
    <= 1000 szt./d, w tym skora <= 500; naprawy noszonych bez spadku - naprawione w miastach >= 0.9 x zuzyte w bitwach (zastepczo: zuzycie walki dotyka tylko
    sztuk w uzyciu, wiec kowale musza nadazac co najmniej za nim); skora w kolejce odziezy wojska d90 -> until bez wzrostu (<= +2%). INFO - pominiete i
    robocizna do kiesy ludu (B1) na dobe. Wlasne rece gracza (SelfRepairSameRule) autotest nie cwiczy - test reczny."""
    zu = {}
    for d, s in by_day(lines, "Zuzycie AI: dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            zu[rd] = s
    seg = {d: s for d, s in zu.items() if "pominiete (lup nienoszony)" in s}
    if not seg:
        rep.add("N1-1: Zuzycie AI - pominiete (lup nienoszony)", "brak segmentu w oknie" if zu else "brak linii Zuzycie AI", "jest od wgrania E6/N1", None)
        return
    last = seg[max(seg)]
    on = num(r"pominiete \(lup nienoszony\) (\d+) szt\.", last) is not None
    rep.add("N1-1: AI naprawia tylko noszone (AiMendsWornOnly)", f"d{max(seg)}: " + last[last.find("pominiete"):last.find("pominiete") + 70], "WLACZONE (\"pominiete ... N szt.\")", on)

    def avg(pat):
        ks = [d for d in seg if d >= 91]
        vals = [num(pat, seg[d], int) for d in ks]
        vals = [v for v in vals if v is not None]
        return (sum(vals) / float(len(vals)), len(vals)) if vals else (None, 0)
    full = max(seg) >= 92
    w, nw = avg(r"czeka na material (\d+) szt\.")
    sk, _ = avg(r"czeka na material \d+ szt\. \(metal \d+, drewno \d+, skora (\d+)")
    if full and w is not None:
        rep.add("N1-2: czeka na material (srednia d91-until)", f"{w:.0f} szt./d ({nw} dob)", "<= 1000 (przed N1: 2070)", w <= 1000)
        rep.add("N1-3: czeka na material - skora (srednia d91-until)", f"{sk:.0f} szt./d" if sk is not None else "brak", "<= 500 (przed N1: 1700)",
                (sk <= 500) if sk is not None else None)
    else:
        rep.add("N1-2: czeka na material (srednia d91-until)", "okno krotsze niz d92 albo brak dopisku materialu", "<= 1000, skora <= 500", None)
    md, _ = avg(r"naprawione w miastach (\d+)")
    bw, _ = avg(r"zuzyte w bitwach (\d+)")
    if full and md is not None and bw is not None:
        rep.add("N1-4: naprawy noszonych bez spadku (srednia d91-until)", f"naprawione {md:.0f}/d, zuzyte w bitwach {bw:.0f}/d", ">= 0.9 x zuzyte w bitwach",
                md >= 0.9 * bw)
    else:
        rep.add("N1-4: naprawy noszonych bez spadku", "okno krotsze niz d92", "naprawione >= 0.9 x zuzyte w bitwach (d91-until)", None)
    sp = [num(r"pominiete \(lup nienoszony\) (\d+) szt\.", s, int) or 0 for s in seg.values()]
    fk = [num(r"robocizna do kiesy ludu (\d+)", s, int) or 0 for s in seg.values()]
    rep.add("N1-5: pominiete (lup nienoszony) i robocizna do kiesy ludu - srednio na dobe", f"{sum(sp) / float(len(sp)):.0f} szt., {sum(fk) / float(len(fk)):.0f} zl ({len(sp)} dob)",
            "INFO (kiesa ludu > 0 przy czynnym B1)", None)
    clo = {}
    for d, s in by_day(lines, "Odziez wojska (150): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            i = s.find("| czeka: ")
            j = s.find(" (", i) if i >= 0 else -1
            v = num(r"skora (\d+(?:\.\d+)?)", s[i + 9:j] if j > i else s[i + 9:], float) if i >= 0 else None   # jak W1-7 (wait)
            if v is not None:
                clo[rd] = v
    wd = sorted(k for k in clo if k >= 90)
    if len(wd) >= 2 and wd[-1] >= 92:
        a, b2 = clo[wd[0]], clo[wd[-1]]
        rep.add("N1-6: odziez wojska - skora w kolejce (d90 -> until)", f"d{wd[0]} {a:.0f} -> d{wd[-1]} {b2:.0f}", "bez wzrostu (<= +2%)", b2 <= a * 1.02 + 0.5)
    else:
        rep.add("N1-6: odziez wojska - skora w kolejce", "okno krotsze niz d92 albo brak linii", "bez wzrostu d90 -> until", None)


def etap5_fee(rep, lines):
    """E5 decyzja 9 Jeffa (12.10): oplata za werbunek zalog (Clan.AutoRecruitmentExpenses, H6) nie znika - do notabla, ktory dal czlowieka (zmarly -
    kasa jego osady). Linia startowa "GarrisonRecruitFee (E5 decyzja 9)" i linia doby "Oplata za werbunek zalog (E5 decyzja 9): dzien N"."""
    wire = [x for x in lines if x.startswith("GarrisonRecruitFee (E5 decyzja 9)")]
    fee = [x for x in lines if x.startswith("Oplata za werbunek zalog (E5 decyzja 9): dzien")]
    if not wire:
        rep.add("E5 dec. 9: latki oplaty za werbunek zalog", "brak linii startowej", "jest od wgrania (GarrisonRecruitFee)", None)
        return
    rep.add("E5 dec. 9: latki oplaty za werbunek zalog", wire[-1][:180], "werbunek, splata i rozliczenie wpiete (bez NIEPELNE)", "NIEPELNE" not in wire[-1])
    if not fee:
        rep.add("E5 dec. 9: linia oplaty za werbunek zalog", "brak", "codziennie, gdy zalogi werbuja od notabli", None)
        return
    def tot(rx):
        return sum(num(rx, x, int, 0) or 0 for x in fee)
    acc, paid = tot(r"naliczone przy werbunku (\d+)"), tot(r"splacone przez rody (\d+)")
    nb, ss, unc = tot(r"do notabli (\d+)"), tot(r"do kas osad \(notabl zmarly\) (\d+)"), tot(r"bez pokrycia w kiesie glowy (\d+)")
    leg, nt, out = tot(r"w nicosc jak dotad (\d+)"), tot(r"bez odbiorcy (\d+)"), tot(r"poza rozliczeniem rodu \(nic nie oddane\) (\d+)")
    stum = tot(r"potkniecia (\d+)")
    rep.add("E5 dec. 9: oplata za werbunek zalog do sprzedajacych (suma dob w logu)",
            f"naliczone {acc}, splacone przez rody {paid}: notable {nb}, kasy osad {ss}, bez pokrycia {unc}, saldo sprzed paczki {leg}, bez odbiorcy {nt}, poza rozliczeniem {out}",
            "notable + kasy osad > 0, gdy rody splacaja; bez odbiorcy 0", (nb + ss > 0 and nt == 0) if paid > 0 else None)
    rep.add("E5 dec. 9: potkniecia GarrisonRecruitFee", str(stum), "0", stum == 0)


def etap5_aud(rep, lines, start, until):
    """Audyt zlota z niczego 11.10 (docs/etap5/AUDYT-ZLOTO-Z-NICZEGO-2026-10-11.md, rozdz. 5a i 5b) - cztery male zmiany w Armoury:
    A3' (Notable Bk Gift Cut): drugie 10 000 BK nowego notabla uciete - linia "Notable (E5/A3)" + "inne" z niczego w bilansie w dobach z nowymi notablami ~ tlo;
    zaulki (Alley Income From Town): 30 zl/d za zaulek z nadwyzki kasy miasta - linia "Notable (E5/A3)" + "Obieg: notable i karawany" (z niczego netto ~ 0);
    RP' (RealPayer TourneyPre High - przed RBMTournament): "nagrody turniejow" w ZRODLACH bilansu = 0, RealPayer > 0 wyplat (INFO - turnieje AI bywaja rzadko);
    G24/N3 (pomiar, tylko licznik): dopisek linii "Kasy miast (169c)" - INFO (latka dopiero, gdy licznik > 0). Doby kampanii 2-until (doba 1 = sam stan ksiegi)."""
    nob = by_day(lines, "Notable (E5/A3): dzien")
    onk = by_day(lines, "Obieg: notable i karawany: dzien")
    cau = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    sea = by_day(lines, "Szczelnosc (164a): dzien")
    k169 = by_day(lines, "Kasy miast (169c): dzien")
    win = lambda src: [d for d in sorted(src) if 2 <= run_day(d, start) <= until]
    # ---------------- A3': dar BK
    bre = re.compile(r"dar BK nowych notabli \(A3'\)( WYLACZONE[^:]*)?: uciete (\d+) u (\d+) notabli \(okien CreateNotable (\d+)\)")
    nre = re.compile(r"\| nowi notable: (\d+), z kas (\d+)")
    ine = re.compile(r"zloto dane przez gre z niczego poza rozliczeniami rodow -?\d+ \(w tym: .*?, inne (-?\d+)\)")
    nw = win(nob)
    bk = {}
    off = 0
    for d in nw:
        m = bre.search(nob[d])
        if m:
            if m.group(1):
                off += 1
            mn = nre.search(nob[d])
            bk[d] = (int(m.group(2)), int(m.group(3)), int(m.group(4)), int(mn.group(1)) if mn else 0)
    if not nw:
        rep.add("audyt A3': linia Notable (E5/A3)", "brak w logu", "jest od wgrania E5/A3 (LogEnabled)", None)
    elif not bk:
        rep.add("audyt A3'-1: dopisek \"dar BK nowych notabli (A3')\" w linii Notable (E5/A3)", f"brak w {len(nw)} dobach", "jest od wgrania poprawki A3' (audyt 11.10)", False)
    else:
        cut = sum(v[0] for v in bk.values()); cutn = sum(v[1] for v in bk.values()); wn = sum(v[2] for v in bk.values()); newn = sum(v[3] for v in bk.values())
        rep.add("audyt A3'-1: dar BK nowych notabli uciety (suma dob 2-%d)" % until,
                f"uciete {cut} u {cutn} notabli; okien CreateNotable {wn}; nowi notable z kas (A3) {newn}" + (f"; WYLACZONE w {off} dobach" if off else ""),
                "INFO (BK daje kazdemu nowemu notablowi poza wedrowcem drugie 10 000 - BK NotablePatches.cs:77-81; bez BK okna nic nie widza)", None)
        # "inne" z niczego w dobach z dar BK uciety wobec dob bez nowych notabli (audyt 5a: test A3 - "inne w dobach z nowymi notablami ~ tlo")
        dz = [d for d in bk if bk[d][1] > 0 and d in cau]
        d0 = [d for d in bk if bk[d][1] == 0 and bk[d][3] == 0 and d in cau]
        iv = {d: num(ine.pattern, cau[d]) for d in dz + d0}
        a = [iv[d] for d in dz if iv.get(d) is not None]
        b = [iv[d] for d in d0 if iv.get(d) is not None]
        if a and b and not off:
            per = (st.mean(a) - st.mean(b)) / max(1.0, st.mean(bk[d][1] for d in dz))
            rep.add("audyt A3'-2: \"inne\" z niczego w dobach z nowymi notablami BK wobec tla (na notabla)",
                    f"{per:+.0f} zl (srednio {st.mean(a):.0f} w {len(a)} dobach wobec {st.mean(b):.0f} w {len(b)} dobach bez nowych notabli)",
                    "< 5 000 (bez A3': ok. +10 000 na nowego notabla - audyt 1b wiersz 11)", per < 5000)
        else:
            rep.add("audyt A3'-2: \"inne\" z niczego w dobach z nowymi notablami BK wobec tla", f"dob z nowymi notablami {len(a)}, tla {len(b)}" + (" (WYLACZONE)" if off else ""),
                    "INFO (za malo dob do porownania)", None)
    # ---------------- zaulki
    are = re.compile(r"\| zaulki z kasy miasta( WYLACZONE[^:]*)?: nalezne (\d+) u (\d+) notabli, z kas (\d+), uciete (\d+) \(kasa bez nadwyzki u (\d+), w tym nic (\d+)\)")
    al, aoff = {}, 0
    for d in nw:
        m = are.search(nob[d])
        if m:
            if m.group(1):
                aoff += 1
            al[d] = [int(x) for x in m.groups()[1:]]
    if nw and not al:
        rep.add("audyt Z-1: dopisek \"zaulki z kasy miasta\" w linii Notable (E5/A3)", f"brak w {len(nw)} dobach", "jest od wgrania poprawki zaulkow (audyt 11.10)", False)
    elif al:
        due = sum(v[0] for v in al.values()); paid = sum(v[2] for v in al.values()); cutz = sum(v[3] for v in al.values())
        sgz = sum(num(r"w uciete wstrzymane w oblezonym miescie \(R22\) (\d+)", nob[d], int, 0) or 0 for d in al)   # Jeff 12.10: zaulki oblezonych miast
        rep.add("audyt Z-1: zaulki - nalezne = z kas + uciete (suma dob 2-%d)" % until,
                f"nalezne {due} (srednio {due / len(al):.0f}/d u {st.mean(v[1] for v in al.values()):.0f} notabli), z kas {paid}, uciete {cutz} (w tym oblezone miasta {sgz})" + (f"; WYLACZONE w {aoff} dobach" if aoff else ""),
                "z kas + uciete = nalezne (+-0); bez poprawki ok. 6 600-6 900/d z niczego (audyt 1b wiersz 10)", (paid + cutz == due) if not aoff else None)
    zre = re.compile(r"zloto z niczego netto \(zaulki, majatki BK, minus podatek warsztatow BK\) ([-+]?\d+)")
    kw = win(onk)
    zv = [num(zre.pattern, onk[d]) for d in kw]
    zv = [v for v in zv if v is not None]
    if zv:
        rep.add("audyt Z-2: dochod notabli - zloto z niczego netto (Obieg, srednia dob 2-%d)" % until, f"{st.mean(zv):+.0f}/d (najwiecej {max(zv, key=abs):+d})",
                "|srednia| <= 100 zl/d (bez poprawki = 30 x zaulki, ok. +6 600/d)", (abs(st.mean(zv)) <= 100) if (al and not aoff) else None)
    # ---------------- RealPayer: nagrody turniejow przed RBM
    tre = re.compile(r"nagrody turniejow: gra chciala (\d+), zaplacili (\d+), uciete (\d+) \((\d+) wyplat")
    sw = win(sea)
    tv = [tre.search(sea[d]) for d in sw]
    tv = [[int(x) for x in m.groups()] for m in tv if m]
    toff = any("WYLACZONE (Town Pays Rewards)" in sea[d] for d in sw)
    cw = win(cau)
    src = [num(r"\(w tym: .*?, nagrody turniejow (\d+)", cau[d]) for d in cw]
    src = [v for v in src if v is not None]
    if tv or src:
        rep.add("audyt RP'-1: nagrody turniejow AI z niczego (ZRODLA bilansu, suma dob 2-%d)" % until, f"{sum(src)} w {len(src)} dobach",
                "0 (bez poprawki RBMTournament placil przed RealPayer: ok. 80-120 zl/d)", (sum(src) == 0) if (src and not toff) else None)
        rep.add("audyt RP'-2: RealPayer - nagrody turniejow przez kase miasta (suma)",
                f"wyplat {sum(v[3] for v in tv)}, gra chciala {sum(v[0] for v in tv)}, zaplacili {sum(v[1] for v in tv)}, uciete {sum(v[2] for v in tv)}" + (" (WYLACZONE)" if toff else ""),
                "INFO (> 0 wyplat, gdy w biegu byly turnieje AI; bez poprawki 0 wyplat przez caly bieg)", None)
    else:
        rep.add("audyt RP': linie Szczelnosc (164a) / bilans przyczyn", "brak w logu", "sa przy LogEnabled i ksiedze obiegu", None)
    # ---------------- pomiar G24 / N3
    gre = re.compile(r"pomiar G24/N3 \(audyt 11\.10[^)]*\): osada zaplacila bohaterowi ponad kase (\d+) w (\d+) zdarzeniach \(gracz (\d+)\), warsztaty BK - niedoplata pustej kasy (?:(\d+) w (\d+) wyrobach|-)")
    kd = win(k169)
    gv = [gre.search(k169[d]) for d in kd]
    gv = [m for m in gv if m]
    if not kd:
        rep.add("audyt G24/N3: linia Kasy miast (169c)", "brak w logu", "jest przy LogEnabled", None)
    elif not gv:
        rep.add("audyt G24/N3: dopisek \"pomiar G24/N3\" w linii Kasy miast (169c)", f"brak w {len(kd)} dobach", "jest od wgrania pomiaru (audyt 11.10)", False)
    else:
        g = sum(int(m.group(1)) for m in gv); gn = sum(int(m.group(2)) for m in gv); gp = sum(int(m.group(3)) for m in gv)
        n3 = sum(int(m.group(4) or 0) for m in gv); n3n = sum(int(m.group(5) or 0) for m in gv)
        hook = any("[G24: latka niewpieta]" in k169[d] for d in kd)
        rep.add("audyt G24: osada zaplacila bohaterowi ponad kase (suma dob 2-%d)" % until, f"{g} zl w {gn} zdarzeniach (gracz {gp}; dob z G24 {sum(1 for m in gv if int(m.group(1)) > 0)})"
                + ("; LATKA NIEWPIETA" if hook else ""),
                "INFO (z niczego w reszcie R; > 0 = dopisac obciecie kwoty do kasy - audyt 5b \"N3 / G24\")", False if hook else None)
        rep.add("audyt N3: warsztaty BK - niedoplata pustej kasy (suma)", f"{n3} zl w {n3n} wyrobach", "INFO (> 0 = obciac zaplate BK ProduceOutputPrefix do kasy - audyt 5b)", None)
def etap5_a7(rep, lines, start, until):
    """E5/A7 (audyt zlota z niczego 11.10, wiersze 12-14 i 16; SmallGold.cs, MercContract.TierPostfix) - drobne zrodla gry. Linie: startowa
    "Drobne zrodla (E5/A7): latki przy starcie gry" i doby "Drobne zrodla (E5/A7): dzien N"; zamkniecie widac w "Hearth (E4/0)" (lup z niczego 0)
    i "Pieniadz swiata (rody - przyczyny)" (dochod za tier (z niczego) 0). Doby kampanii 2-until."""
    wire = [x for x in lines if x.startswith("Drobne zrodla (E5/A7): latki przy starcie gry")]
    a7 = by_day(lines, "Drobne zrodla (E5/A7): dzien")
    win = [d for d in sorted(a7) if 2 <= run_day(d, start) <= until]
    if not wire and not a7:
        rep.add("E5/A7: linie Drobne zrodla (E5/A7)", "brak w logu", "sa od wgrania E5/A7 (LogEnabled)", None)
        return
    if wire:
        rep.add("E5/A7-0: latki (rabunek, nowa zaloga, kiesa starej zalogi, Insurance Plans, Rapid Development, strona przelewu)", wire[-1][:240], "BRAK: - (6 wpietych)", "BRAK: -;" in wire[-1])
    if not win:
        rep.add("E5/A7: linia doby", "brak w dobach 2-%d" % until, "codziennie (LogEnabled)", False)
        return

    def tot(rx, days=None):
        return sum(num(rx, a7[d], int, 0) or 0 for d in (days if days is not None else win))
    # ---------------- 1. rabunek wsi z kiesy wsi
    ron = [d for d in win if "rabunek wsi z kiesy wsi WYLACZONE" not in a7[d]]
    due, paid = tot(r"rabunek wsi z kiesy wsi[^:]*: gra dalaby (\d+)"), tot(r"krokach, z kies wsi (\d+), uciete")
    steps, short, empty = tot(r"gra dalaby \d+ w (\d+) krokach"), tot(r"kiesa wsi nie starczyla w (\d+) krokach"), tot(r"pusta w (\d+)\)")
    duep, paidp = tot(r"gracz: gra dalaby (\d+)"), tot(r"gracz: gra dalaby \d+, z kies wsi (\d+)")
    off = tot(r"; z niczego jak dotad (\d+) w \d+ krokach")
    rep.add("E5/A7-1: rabunek wsi - lup z kiesy wsi (suma dob 2-%d)" % until,
            f"gra dalaby {due} w {steps} krokach, z kies wsi {paid}, uciete {due - paid} (kiesa nie starczyla w {short}, pusta w {empty}); gracz {paidp} z {duep}"
            + (f"; WYLACZONE w {len(win) - len(ron)} dobach (z niczego jak dotad {off})" if len(ron) < len(win) else ""),
            "zaplacone <= nalezne; INFO (audyt: ok. 0,7 tys./d lupu z niczego, rosnie z wojna)", paid <= due)
    hea = by_day(lines, "Hearth (E4/0): dzien")
    hd = [d for d in ron if d in hea]
    if hd:
        ln = sum(num(r"lup z niczego (\d+) zl", hea[d], int, 0) or 0 for d in hd)
        rep.add("E5/A7-2: lup z niczego w rabunku (Hearth E4/0, doby z czynnym Raid Loot From Village)", f"{ln} zl w {len(hd)} dobach", "0 (lup tylko z kies wsi)", ln == 0)
    else:
        rep.add("E5/A7-2: lup z niczego w rabunku (Hearth E4/0)", "brak linii Hearth (E4/0) w dobach z czynnym wylacznikiem", "0", None)
    # ---------------- 2. nowe zalogi
    gn, gt = tot(r"\| nowe zalogi[^:]*: (\d+), kiesa startowa"), tot(r"kiesa startowa gry (\d+) -> 0")
    goff = tot(r"rozliczeniem zoldu\), z niczego jak dotad (\d+)")
    # recenzja A7: kiesa starej zalogi przy zdobyciu przechodzi na nowa zaloge (przelew; wczesniej znikala - U8 "garnizony")
    gh, ghn = tot(r"przy zdobyciu: nowej zalodze (\d+)"), tot(r"przy zdobyciu: nowej zalodze \d+ \((\d+)\)")
    gb = tot(r"z powrotem do zalogi osady (\d+)")
    op = [x for x in lines if x.startswith("Drobne zrodla (E5/A7): start")]
    rep.add("E5/A7-3: nowe zalogi bez kiesy startowej z niczego (suma dob 2-%d)" % until,
            f"zalog {gn}, kiesa startowa gry niepowstala {gt}" + (f" (sr. {gt / gn:.0f} na zaloge)" if gn else "") + (f"; z niczego jak dotad {goff}" if goff else "")
            + f"; kiesa starej zalogi przejeta przez nowa {gh} w {ghn} zdobyciach" + (f", z powrotem do zalogi osady {gb}" if gb else "")
            + (" | bilans otwarcia" + op[-1].split("bilans otwarcia")[-1][:100] if op else ""),
            "INFO (audyt: 5000 na zdobycie twierdzy - reszta R +5000 w dobach zdobycia znika, U8 garnizony przy zdobyciu ok. 0; kiese wypelnia rod rozliczeniem zoldu)", None)
    # ---------------- 3. za tier
    ton = [d for d in win if "za tier rody AI bez lenn WYLACZONE" not in a7[d]]
    tc, tn = tot(r"za tier rody AI bez lenn[^:]*: gra dalaby (\d+)"), tot(r"za tier rody AI bez lenn[^:]*: gra dalaby \d+ u (\d+) rodow")
    tm = tot(r"rodow \(w tym najemnicy (\d+)\), dostaly 0")
    rep.add("E5/A7-4: za tier rodow AI bez lenn zdjete (suma dob 2-%d)" % until, f"{tc} zl w {tn} rozliczeniach (w tym najemnicy {tm})",
            "INFO (audyt: 0,6-0,7 tys./d; najemnicy z umowa 185 - linia Kontrakty najemnikow)", None)
    cau = by_day(lines, "Pieniadz swiata (rody - przyczyny): dzien")
    cd = [d for d in ton if d in cau]
    if cd:
        tl = sum(num(r"dochod za tier \(z niczego\) ([+-]?\d+)", cau[d], int, 0) or 0 for d in cd)
        rep.add("E5/A7-5: dochod za tier (z niczego) w ksiedze (rody - przyczyny, doby z czynnym Tier Income Ai Off)", f"{tl} w {len(cd)} dobach", "0", tl == 0)
    else:
        rep.add("E5/A7-5: dochod za tier (z niczego) w ksiedze", "brak linii rody - przyczyny w dobach z czynnym wylacznikiem", "0", None)
    # ---------------- 4. perki 5000
    pi, pin_ = tot(r"Insurance Plans uciete (\d+)"), tot(r"Insurance Plans uciete \d+ \((\d+)\)")
    pr, prn = tot(r"Rapid Development uciete (\d+)"), tot(r"Rapid Development uciete \d+ \((\d+)\)")
    pp = tot(r"gracz bez zmian: Insurance Plans (\d+)") + tot(r"gracz bez zmian: Insurance Plans \d+ \(\d+\), Rapid Development (\d+)")
    rep.add("E5/A7-6: perki 5000 AI uciete (suma dob 2-%d)" % until, f"Insurance Plans {pi} ({pin_}), Rapid Development {pr} ({prn}); gracz bez zmian {pp}",
            "kwota = 5000 x liczba; INFO (audyt: 3 / 2 / 14 paczek na bieg)", pi == 5000 * pin_ and pr == 5000 * prn)
    # ---------------- kontrola
    st, ov, sm = tot(r"zdarzenia w oknie rabunku niedopasowane (\d+)"), tot(r"stos przepelniony (\d+)"), tot(r"\| potkniecia (\d+)")
    gtw = tot(r"kiesa starej zalogi bez zalogi - do kasy osady (\d+)")
    errs = sum(1 for x in lines if "ERROR" in x and "SmallGold." in x)
    rep.add("E5/A7-7: kontrola (niedopasowane w oknie rabunku, stos, potkniecia, ERROR SmallGold.*, kiesa starej zalogi do kasy osady)", f"{st} / {ov} / {sm} / {errs} / {gtw}",
            "0 / 0 / 0 / 0 / 0", st == 0 and ov == 0 and sm == 0 and errs == 0 and gtw == 0)


def etap5_a8(rep, lines, start, until):
    """E5/A8 (audyt zlota z niczego 11.10, wiersze 17, 18, 23 i rozdz. 2b koszt paktu Diplomacy; BkDipGold.cs) - BK i Diplomacy bez platnika albo odbiorcy.
    Linie: startowa "BK i Diplomacy (E5/A8): latki przy starcie gry" i doby "BK i Diplomacy (E5/A8): dzien N"; zamkniecie widac w reszcie R
    ("Pieniadz swiata (bilans - przyczyny)") w dobach z nowym rodem szlachty, hersztem i paktem (dotad skoki +15 000..+38 000, +10 000, -500..-25 500).
    Doby kampanii 2-until."""
    wire = [x for x in lines if x.startswith("BK i Diplomacy (E5/A8): latki przy starcie gry")]
    a8 = by_day(lines, "BK i Diplomacy (E5/A8): dzien")
    win = [d for d in sorted(a8) if 2 <= run_day(d, start) <= until]
    if not wire and not a8:
        rep.add("E5/A8: linie BK i Diplomacy (E5/A8)", "brak w logu", "sa od wgrania E5/A8 (LogEnabled)", None)
        return
    if wire:
        rep.add("E5/A8-0: latki (rod szlachty, herszt, juki herszta, uczta BK; okna NAP i pokoju, koszt bez odbiorcy Diplomacy)", wire[-1][:260], "BRAK: - (7 wpietych)",
                "BRAK: -." in wire[-1])
    if not win:
        rep.add("E5/A8: linia doby", "brak w dobach 2-%d" % until, "codziennie (LogEnabled)", False)
        return

    def tot(rx, days=None):
        return sum(num(rx, a8[d], int, 0) or 0 for d in (days if days is not None else win))
    # ---------------- 1. nowy rod szlachty BK
    gn, gd, gp = tot(r"nowe rody szlachty BK[^:]*: (\d+), BK dalby"), tot(r"nowe rody szlachty BK[^:]*: \d+, BK dalby (\d+)"), tot(r"z kas miast handlu wsi (\d+)")
    gs, gc, gcn = tot(r"kasa nie starczyla u (\d+)\)"), tot(r"cena majatku bez odbiorcy niepowstala (\d+)"), tot(r"cena majatku bez odbiorcy niepowstala \d+ \((\d+)\)")
    go, goff = tot(r"majatek z wlascicielem - cena z niczego jak dotad \d+ \((\d+)\)"), tot(r"; z niczego jak dotad (\d+) u \d+ \| herszt")
    rep.add("E5/A8-1: nowe rody szlachty BK - 15 000 z kasy miasta handlu wsi majatku (suma dob 2-%d)" % until,
            f"rodow {gn}, BK dalby {gd}, z kas miast {gp}, uciete {gd - gp} (kasa nie starczyla u {gs}); cena majatku niepowstala {gc} w {gcn}"
            + (f"; majatek z wlascicielem (cena jak dotad) {go}" if go else "") + (f"; WYLACZONE - z niczego jak dotad {goff}" if goff else ""),
            "z kas <= BK dalby <= 15 000 x rody; INFO (audyt: 1 / 0 / 2 rody na bieg)", gp <= gd <= 15000 * gn)
    # ---------------- 2. herszt BK
    hn, hd, hp = tot(r"\| herszt BK[^:]*: nowi (\d+)"), tot(r"\| herszt BK[^:]*: nowi \d+, BK dalby (\d+)"), tot(r"z nadwyzki kryjowek (\d+)")
    hs, hoff = tot(r"kryjowka nie starczyla u (\d+)\)"), tot(r"; z niczego jak dotad (\d+) u \d+; juki")
    rep.add("E5/A8-2: herszt BK - 10 000 z nadwyzki kasy kryjowki (suma dob 2-%d)" % until,
            f"hersztow {hn}, BK dalby {hd}, z kryjowek {hp}, uciete {hd - hp} (kryjowka nie starczyla u {hs})" + (f"; WYLACZONE - z niczego jak dotad {hoff}" if hoff else ""),
            "z kryjowek <= BK dalby <= 10 000 x herszci; INFO (audyt: 0 / 1 / 6 na bieg)", hp <= hd <= 10000 * hn)
    pl, pu, pv = tot(r"\(BK sprzedawal z niczego\): wyjsc (\d+)"), tot(r"\(BK sprzedawal z niczego\): wyjsc \d+, (\d+) szt\."), tot(r"szt\. o wartosci (\d+) -> paser")
    ps, pp, pn = tot(r"paser \(kasy miast\) kupil (\d+) szt\."), tot(r"paser \(kasy miast\) kupil \d+ szt\. \(z zywnoscia, gdy ja skupuje\) za (\d+)"), tot(r"; bez pasera (\d+)")
    poff = tot(r"sprzedane z niczego jak dotad (\d+)")
    rep.add("E5/A8-3: juki herszta BK przy wyjsciu z kryjowki - przez kasy miast paserem OutlawLaw (suma dob 2-%d)" % until,
            f"wyjsc {pl}, {pu} szt. o wartosci {pv}; paser kupil {ps} szt. za {pp}, bez pasera {pn}" + (f"; WYLACZONE - sprzedane z niczego jak dotad {poff}" if poff else ""),
            "INFO (dotad BK sprzedawal je z niczego po cenie miasta; teraz kasy miast przez pasera, bron i sprzet zostaja jak u kazdej bandy)", None)
    # ---------------- 3. uczta BK
    fn, fp, fg = tot(r"\| uczty BK[^:]*: zakupow (\d+)"), tot(r"gospodarze zaplacili (\d+)"), tot(r"miasta dostalyby (-?\d+)")
    fc, fcn, foff = tot(r"cofniete z kas miast (\d+)"), tot(r"cofniete z kas miast \d+ \((\d+)\)"), tot(r"; z niczego jak dotad (\d+) \(\d+\) \| pakty")
    rep.add("E5/A8-4: uczty BK - miasto dostaje tyle, ile zaplacil gospodarz (suma dob 2-%d)" % until,
            f"zakupow {fn}, gospodarze zaplacili {fp}, miasta dostalyby {fg}, cofniete {fc} w {fcn}" + (f"; WYLACZONE - z niczego jak dotad {foff}" if foff else ""),
            "cofniete <= miasta dostalyby - zaplacone; INFO (audyt: male, tylko biedny gospodarz)", fc <= max(0, fg - fp))
    # ---------------- 4. koszt paktu Diplomacy
    kn, kd, kp = tot(r"\| pakty Diplomacy \(nieagresja, pokoj\)[^:]*: (\d+), koszt"), tot(r"\(nieagresja, pokoj\)[^:]*: \d+, koszt (\d+)"), tot(r"do skarbcow drugiej strony (\d+)")
    kpl, knr, knrn = tot(r"drugiej strony \d+ \(w tym gracz (\d+)\)"), tot(r"bez drugiej strony nie pobrane (\d+)"), tot(r"bez drugiej strony nie pobrane \d+ \((\d+)\)")
    koff, kfall = tot(r"; w nicosc jak dotad (\d+)"), tot(r"okna pokoju z upadkiem drugiej strony (\d+)")   # recenzja: druga strona upada z tym pokojem - nie pobrane
    rep.add("E5/A8-5: koszt paktu o nieagresji i pokoju Diplomacy do skarbca drugiej strony (suma dob 2-%d)" % until,
            f"paktow {kn}, koszt {kd}, do skarbcow drugiej strony {kp} (gracz {kpl}); bez drugiej strony nie pobrane {knr} w {knrn} (okna pokoju z upadkiem drugiej strony {kfall})"
            + (f"; WYLACZONE - w nicosc jak dotad {koff}" if koff else ""),
            "do skarbcow <= koszt; INFO (audyt z31-A: 39 NAP + 18 pokojow, -2,66 tys./d w nicosc)", kp <= kd)
    # ---------------- reszta R w dobach ze zdarzeniami A8 (dotad skoki)
    bil = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    ev = [d for d in win if d in bil and (num(r"nowe rody szlachty BK: (\d+)", a8[d], int, 0) or num(r"\| herszt BK: nowi (\d+)", a8[d], int, 0)
                                          or num(r"\(nieagresja, pokoj\): (\d+)", a8[d], int, 0))]
    rest = [d for d in win if d in bil and d not in ev]
    if ev:
        rv = [num(r" R=(-?\d+)", bil[d], int, 0) or 0 for d in ev]
        rr = [num(r" R=(-?\d+)", bil[d], int, 0) or 0 for d in rest]
        rep.add("E5/A8-6: reszta R w dobach z nowym rodem, hersztem albo paktem (czynne klucze)",
                f"srednio {sum(rv) / len(rv):+.0f} w {len(ev)} dobach (najwiecej {max(rv, key=abs):+d}); pozostale doby srednio " + (f"{sum(rr) / len(rr):+.0f}" if rr else "-"),
                "INFO (dotad: nowy rod +15 000..+38 000, herszt +10 000, pakt -500..-25 500; po A8 jak tlo)", None)
    else:
        rep.add("E5/A8-6: reszta R w dobach ze zdarzeniami A8", "brak dob z nowym rodem, hersztem albo paktem przy czynnych kluczach", "INFO", None)
    # ---------------- kontrola
    ov, op_, sm = tot(r"stos paktow przepelniony (\d+)"), tot(r"otwarte okna paktow (\d+)"), tot(r"\| potkniecia (\d+)")
    errs = sum(1 for x in lines if "ERROR" in x and "BkDipGold." in x)
    rep.add("E5/A8-7: kontrola (stos paktow, otwarte okna na koniec doby, potkniecia, ERROR BkDipGold.*)", f"{ov} / {op_} / {sm} / {errs}", "0 / 0 / 0 / 0",
            ov == 0 and op_ == 0 and sm == 0 and errs == 0)

def etap5_c1(rep, lines, start, until, logp=None):
    """E5/C1 (202, PLAN 5.8 - kasy miast bez dosypki; projekt etapu 5 rozdz. 3 "E5/C1" Test). Regulator bez dosypki to tryb 2 klucza Town Purse Regulator
    (E5/A1, decyzja Jeffa 11.10 16:10 - osobnego klucza TownPurseNoTopUp nie ma); tu kontrola zbioru C. C1-1 tryb 2 kazdej doby i dosypka kas miast
    i zamkow 0; C1-2 zakup plonu w miastach-zaulkach >= 98% (dopisek "plon w zaulkach (E5/C1)" w linii "Kasy miast (169c)" - kasa ponizej zapasu kupcow
    przy wejsciu taboru); C1-3 miasta z kasa < 1 000: 0 kazdej doby; C1-4 zloto swiata |zmiana| < 0.1% na 28 dob (ostatnie 28 dob okna; najgorsze okno
    od doby 2 - INFO). Okno: doby kampanii 2-until (jak A1). Warunki "rok testu B" (reszta R < 10 tys./d - A1-T13) w bloku A1."""
    k169 = by_day(lines, "Kasy miast (169c): dzien")
    win = [d for d in sorted(k169) if 2 <= run_day(d, start) <= until]
    if not win:
        rep.add("E5/C1: linia Kasy miast (169c)", "brak w dobach 2-%d" % until, "codziennie (LogEnabled)", None)
        return
    seg = {}
    for d in win:
        s = k169[d]
        i = s.find(" | E5/A1:")
        seg[d] = s[i:] if i >= 0 else ""
    # ---------------- C1-1: regulator bez dosypki (miasta i zamki)
    zz = by_day(lines, "Zawor zamkow (110): dzien")
    m2 = sum(1 for d in win if num(r"^ \| E5/A1: tryb regulatora (\d)", seg[d]) == 2)
    up_t = sum(num(r"dosypka do zapasu \(tryb 1\) (\d+)", seg[d], int, 0) or 0 for d in win)
    # recenzja C1: Castle Purse Enabled wylaczone = linia "WYLACZONE" raz na sesje (czesto doba 1, poza oknem) i regulator gry dosypuje zamkom z niczego -
    # wtedy liczba 0 nic nie dowodzi (NIE); brak linii zamkow w oknie - zamki niesprawdzone (INFO), nie TAK
    zoff = sum(1 for s in zz.values() if "WYLACZONE" in s)
    zd = [d for d in win if d in zz and "WYLACZONE" not in zz[d]]
    up_c = sum(num(r"dosypka do zapasu \(tryb 1, zostaje do etapu 3\) (\d+)", zz[d], int, 0) or 0 for d in zd)
    ok11 = m2 == len(win) and up_t == 0 and up_c == 0
    rep.add("E5/C1-1: regulator kas bez dosypki (tryb 2 Town Purse Regulator; suma okna)",
            f"tryb 2 w {m2} z {len(win)} dob; dosypka kas miast {up_t}, kas zamkow {up_c}"
            + (" (Castle Purse Enabled WYLACZONE - zamki z dosypka gry z niczego)" if zoff else ("" if zd else " (brak linii Zawor zamkow (110) w oknie - zamki niesprawdzone)")),
            "tryb 2 kazdej doby; dosypka miast 0, zamkow 0 (linia Zawor zamkow (110) czynna)",
            False if zoff else (ok11 if (zd or not ok11) else None))
    # ---------------- C1-2: zakup plonu w miastach-zaulkach
    hre = re.compile(r"plon w zaulkach \(E5/C1\): przywiezione (\d+) szt\. w (\d+) wizytach, niesprzedane (\d+) szt\. \((\d+) miast\);"
                     r" do wszystkich miast przywiezione (\d+) szt\.")
    hv = {}
    for d in win:
        m = hre.search(seg[d])
        if m:
            hv[d] = [int(x) for x in m.groups()]
    if hv:
        ab, av, au, hb = (sum(v[k] for v in hv.values()) for k in (0, 1, 2, 4))
        share = 100.0 * (ab - au) / ab if ab > 0 else None
        tdays = sum(1 for v in hv.values() if v[2] > 0)
        worst = max(hv, key=lambda d: (hv[d][2] / hv[d][0]) if hv[d][0] else 0.0)
        val = (f"{share:.2f}% ({ab - au} z {ab} szt. w {av} wizytach, niesprzedane {au})" if share is not None
               else f"brak wizyt taborow w zaulkach (do miast przywiezione {hb} szt.)")
        val += (f"; doby z niesprzedanym w zaulku {tdays} z {len(hv)} (najgorsza d{run_day(worst, start)}: {hv[worst][2]} z {hv[worst][0]} szt., {hv[worst][3]} miast)"
                + (f"; zaulki dostaly {100.0 * ab / hb:.1f}% plonu przywiezionego do miast" if hb > 0 else "")
                + (f"; dopisek w {len(hv)} z {len(win)} dob" if len(hv) < len(win) else ""))
        rep.add("E5/C1-2: zakup plonu w miastach-zaulkach (kasa ponizej zapasu kupcow przy wejsciu taboru; suma okna)", val,
                ">= 98% (projekt E5/C1; ponizej - zaulek kupuje mniej: zapasowo platnik dla zaulka, pytanie do Jeffa)",
                (share >= 98.0) if share is not None else None)
    else:
        rep.add("E5/C1-2: zakup plonu w miastach-zaulkach", "brak dopisku \"plon w zaulkach (E5/C1)\" (log sprzed C1 albo A1 wylaczone)", ">= 98%", None)
    # ---------------- C1-3: miasta z kasa ponizej 1 000
    b1k = {}
    for d in win:
        v = num(r"zaulki: kas ponizej zapasu \d+, ponizej 1000 (\d+)", seg[d])
        if v is not None:
            b1k[d] = v
    # narzedzie progow p2 (TRIAZ-2 b-E5/C1-3): dopisek linii "Kasy miast" powstaje w innej chwili doby niz stan zapisany w kasy-miast.csv - w biegu 2 linia
    # widziala 1 dobe, a kolumna "kasa" 16 dob (Karhold, minimum 31 zl). Gdy plik sesji jest - liczy sie kolumna "kasa" (dzien ksiegi); bez pliku - dopisek linii.
    csv_k, csv_min = {}, None
    cp = session_file_find(logp, "kasy-miast.csv") if logp else None
    if cp and os.path.exists(cp):
        try:
            with open(cp, encoding="utf-8", errors="replace", newline="") as fh:
                for r in csv.DictReader(fh, delimiter=";"):
                    d, k = int(r["dzien"]), int(float(r["kasa"]))
                    if 2 <= run_day(d, start) <= until:
                        csv_k.setdefault(d, 0)
                        if k < 1000:
                            csv_k[d] += 1
                            if csv_min is None or k < csv_min[0]:
                                csv_min = (k, r.get("miasto", "?"), d)
        except (KeyError, ValueError, OSError):
            csv_k, csv_min = {}, None
    if csv_k:
        bad = sorted(d for d, v in csv_k.items() if v > 0)
        lb = sorted(d for d, v in b1k.items() if v > 0)
        rep.add("E5/C1-3: miasta z kasa ponizej 1 000 - kazda doba okna",
                f"niezerowe w {len(bad)} z {len(csv_k)} dob (kasy-miast.csv, kolumna kasa)"
                + (f" - najwiecej {max(csv_k[d] for d in bad)} miast, pierwsza d{run_day(bad[0], start)}, minimum {csv_min[0]} zl ({csv_min[1]}, d{run_day(csv_min[2], start)})" if bad else "")
                + f"; dopisek linii Kasy miast: niezerowe w {len(lb)} z {len(b1k)} dob",
                "0 kazdej doby (projekt E5/C1; stan z pliku kasy-miast.csv)", len(bad) == 0)
    elif b1k:
        bad = sorted(d for d, v in b1k.items() if v > 0)
        rep.add("E5/C1-3: miasta z kasa ponizej 1 000 - kazda doba okna",
                f"niezerowe w {len(bad)} z {len(b1k)} dob" + (f" (najwiecej {max(b1k[d] for d in bad)}, pierwsza d{run_day(bad[0], start)})" if bad else "")
                + " - z dopisku linii (brak kasy-miast.csv; dopisek zaniza liczbe dob)",
                "0 kazdej doby (projekt E5/C1)", len(bad) == 0)
    else:
        rep.add("E5/C1-3: miasta z kasa ponizej 1 000", "brak liczb (dopisek zaulkow A1)", "0 kazdej doby", None)
    # ---------------- C1-4: zloto swiata na 28 dob
    pw = by_day(lines, "Pieniadz swiata: dzien")
    tot = {}
    for d in sorted(pw):
        if 2 <= run_day(d, start) <= until:
            v = num(r"\| razem (\d+)", pw[d])
            if v:
                tot[d] = v
    pd = sorted(tot)
    if len(pd) >= 29:
        a, b = pd[-29], pd[-1]
        ch = (tot[b] - tot[a]) / tot[a] * 100.0
        wch, wd = max((((tot[pd[i]] - tot[pd[i - 28]]) / tot[pd[i - 28]] * 100.0, pd[i]) for i in range(28, len(pd))), key=lambda x: abs(x[0]))
        rep.add("E5/C1-4: zloto swiata - zmiana na 28 dob (ostatnie 28 dob okna)",
                f"{ch:+.3f}% (d{run_day(a, start)} -> d{run_day(b, start)}: {tot[a]} -> {tot[b]}); najgorsze okno 28 dob od doby 2: {wch:+.3f}% (do d{run_day(wd, start)})",
                "|zmiana| < 0.1% (projekt E5/C1; najgorsze okno - INFO)", abs(ch) < 0.1)
    else:
        rep.add("E5/C1-4: zloto swiata - zmiana na 28 dob", f"za malo dob z linia Pieniadz swiata ({len(pd)} < 29)", "|zmiana| < 0.1%", None)


def etap5_c2(rep, lines, start, until):
    """E5/C2 (203, PLAN 5.9 - glod ma skutki; projekt etapu 5 rozdz. 3 "E5/C2" Test). Linia "Glod ludu (E5/C2): dzien" (kiesa czynna, LogEnabled):
    jedna definicja glodu Hunger.Of - brak jedzenia (Food 0 warowni, glod okregu E4/6) bez kary zadowolenia (BK Food Shortage, RBL Severe Starvation, E4/6),
    brak pieniedzy (Afford jedzenia < 0.95 przez 7 dob, kampania >= 120 dob) - galaz jedzenia R14. C2-1 obie kary tej samej doby (korekta jedzenia C2 w oknie
    i warownia z Food 0 w chwili doby) = 0 kazdej doby; C2-2 doby z kampania < 120: korekt C2 0; C2-3 korekty Food w linii R14 = korekty C2 tej samej doby
    (przy kluczu wlaczonym galezi jedzenia poza C2 nie ma); C2-4 korekty C2 na osade-dobe <= 1% (bieg bez oblezen i drozyzny ~0, KL: jedzenia stac 100% dob);
    C2-5 przyczyny glodu (INFO). Okno: doby kampanii 2-until."""
    c2 = by_day(lines, "Glod ludu (E5/C2): dzien")
    win = [d for d in sorted(c2) if 2 <= run_day(d, start) <= until]
    if not win:
        rep.add("E5/C2: linia Glod ludu (E5/C2)", "brak w dobach 2-%d" % until, "codziennie przy kiesie czynnej (LogEnabled; log sprzed C2 - brak)", None)
        return
    on = [d for d in win if "TownFolkHungerHurts tak" in c2[d]]
    if len(on) < len(win):
        rep.add("E5/C2-0: klucz TownFolkHungerHurts", f"wlaczony w {len(on)} z {len(win)} dob", "wlaczony kazdej doby (wylaczony - galaz jedzenia R14 jak B1)", None if not on else False)
    if not on:
        return
    hit = {d: num(r"korekty jedzenia R14 \(C2\) (\d+);", c2[d], int, 0) or 0 for d in on}
    osad = {d: num(r", osad (\d+) \|", c2[d], int, 0) or 0 for d in on}
    # ---------------- C2-1: obie kary tej samej doby
    both = {d: num(r"obie kary tej samej doby (\d+)\.", c2[d]) for d in on}
    miss = [d for d in on if both[d] is None]
    bad = sorted(d for d in on if (both[d] or 0) > 0)
    rep.add("E5/C2-1: obie kary tej samej doby (korekta jedzenia C2 i warownia z Food 0 - BK Food Shortage / RBL Severe Starvation)",
            f"niezerowe w {len(bad)} z {len(on)} dob" + (f" (najwiecej {max(both[d] for d in bad)}, pierwsza d{run_day(bad[0], start)})" if bad else "")
            + (f"; bez liczby w {len(miss)} dobach" if miss else ""),
            "0 kazdej doby (projekt E5/C2: zadna osada nie dostaje obu kar tej samej doby)", (len(bad) == 0) if len(miss) < len(on) else None)
    # ---------------- C2-2: nie w pierwszych 120 dobach kampanii
    early = [d for d in on if "(kara od 120: nie)" in c2[d]]
    if early:
        eh = sum(hit[d] for d in early)
        a0, a1 = num(r"kampania (\d+) dob", c2[early[0]]), num(r"kampania (\d+) dob", c2[early[-1]])
        rep.add("E5/C2-2: korekty jedzenia C2 przed 120. doba kampanii", f"{eh} w {len(early)} dobach (kampania {a0}-{a1})",
                "0 (projekt E5/C2 [D 09.10 A])", eh == 0)
    else:
        rep.add("E5/C2-2: korekty jedzenia C2 przed 120. doba kampanii", "brak dob z kampania < 120 w oknie", "0", None)
    # ---------------- C2-3: galaz jedzenia R14 tylko z C2
    r14 = by_day(lines, "Zadowolenie ludu (R14): dzien")
    pair = [(d, num(r"\(Food (\d+) /", r14[d]), hit[d]) for d in on if d in r14]
    pair = [x for x in pair if x[1] is not None]
    if pair:
        diff = [x for x in pair if x[1] != x[2]]
        rep.add("E5/C2-3: korekty Food w linii R14 = korekty C2 tej samej doby",
                f"rozne w {len(diff)} z {len(pair)} dob" + (f" (pierwsza d{run_day(diff[0][0], start)}: R14 Food {diff[0][1]}, C2 {diff[0][2]})" if diff else f"; suma {sum(x[2] for x in pair)}"),
                "rowne kazdej doby (galaz jedzenia R14 tylko przy glodzie z braku pieniedzy)", len(diff) == 0)
    else:
        rep.add("E5/C2-3: korekty Food w linii R14 = korekty C2", "brak linii Zadowolenie ludu (R14) w dobach C2", "rowne kazdej doby", None)
    # ---------------- C2-4: skala (bieg bez oblezen i drozyzny ~0)
    sh = sum(hit.values()); so = sum(osad.values())
    q = 100.0 * sh / so if so > 0 else None
    wd = max(on, key=lambda d: hit[d])
    rep.add("E5/C2-4: korekty jedzenia C2 na osade-dobe (suma okna)",
            (f"{q:.2f}% ({sh} korekt na {so} osado-dob; najwiecej d{run_day(wd, start)}: {hit[wd]})" if q is not None else "brak osad w linii"),
            "<= 1% (projekt E5/C2: bez oblezen i drozyzny ~0, KL: jedzenia stac 100% dob; wyzej - sprawdz drozyzne jedzenia i kiesy ludu)",
            (q <= 1.0) if q is not None else None)
    # ---------------- C2-5: przyczyny glodu (INFO)
    last = on[-1]
    def _s(pat):
        return sum(num(pat, c2[d], int, 0) or 0 for d in on)
    n = len(on)
    mo, sk = _s(r"przez 7 dob\): (\d+) \("), _s(r"z licznikiem >= 1 doby (\d+)")
    fz, dg = _s(r"Food 0 warowni (\d+)"), _s(r"glod okregu ponad prog (\d+)")
    xf, xw, xs = _s(r"zdjete: brak jedzenia (\d+)"), _s(r"< 120 dob\) (\d+)"), _s(r"bez jedzenia na polce (\d+)")
    rep.add("E5/C2-5: przyczyny glodu (srednio na dobe okna; INFO)",
            f"brak pieniedzy {mo / n:.1f}, z licznikiem >= 1 doby {sk / n:.1f} | brak jedzenia: Food 0 warowni {fz / n:.1f}, glod okregu {dg / n:.1f}"
            f" | zdjete z R14 (suma): brak jedzenia {xf}, poza glodem z braku pieniedzy {xw}, bez jedzenia na polce {xs} | ostatnia doba d{run_day(last, start)}",
            "INFO", None)


def etap5_c4(rep, lines, start, until):
    """E5/C4 (205, PLAN 5.13 - napis "czy ludzi stac na chleb" w oknie "People of this land"; projekt etapu 5 rozdz. 3 "E5/C4"). Linie "PeopleMenu (E5/C4): start"
    (klucz PeopleMenuShowsBread, stan kiesy ludu) i "PeopleMenu (E5/C4): dzien N | ..." przy kazdym otwarciu okna - autotest okna nie otwiera (reczne sprawdzenie Jeffa).
    C4-0 klucz i kiesa (INFO); C4-1 fragment "w linii Kiesa ludu: ..." linii okna jest podciagiem ostatniej wczesniejszej linii "Kiesa ludu: dzien N" tej samej doby
    (liczba okna pochodzi z liczb linii Kiesa ludu); C4-2 liczba w oknie = udzial z linii okna x 100 w dol (+-1 za zaokraglenie F2/N0), 0-100; C4-3 linie
    "ERROR in PeopleMenu.Bread" / "ERROR in PeopleMenu.Consequence" 0. Okno: doby kampanii 1-until; bez linii okna - C4-1/C4-2 INFO."""
    stl = [s for s in lines if s.startswith("PeopleMenu (E5/C4): start")]
    if not stl:
        rep.add("E5/C4-0: linia PeopleMenu (E5/C4): start", "brak w logu", "przy kazdym starcie sesji (log sprzed C4 - brak)", None)
    else:
        last = stl[-1]
        on = "(PeopleMenuShowsBread) wlaczone" in last
        live = "| kiesa ludu czynna" in last
        rep.add("E5/C4-0: klucz PeopleMenuShowsBread i kiesa ludu (ostatni start sesji)",
                f"zdanie {'wlaczone' if on else 'wylaczone'}, kiesa {'czynna' if live else 'NIECZYNNA'} ({len(stl)} startow)",
                "INFO (domyslnie wlaczone; kiesa nieczynna - okno bez zdania)", None)
    # C4-1 / C4-2: linie okna w kolejnosci logu, z ostatnia wczesniejsza linia "Kiesa ludu: dzien N"
    kl = {}
    ok1 = bad1 = nofolk = early = 0
    ok2 = 0
    bad1x, bad2x = [], []
    for s in lines:
        if s.startswith("Kiesa ludu: dzien"):
            k = num(r"dzien (\d+)", s)
            if k is not None:
                kl[k] = s
            continue
        if not s.startswith("PeopleMenu (E5/C4): dzien"):
            continue
        d = num(r"dzien (\d+)", s)
        if d is None or not (1 <= run_day(d, start) <= until):
            continue
        if "brak liczb tej doby" in s:
            early += 1
            continue
        if "| w linii Kiesa ludu: " not in s:
            nofolk += 1
            continue
        frag = s.split("| w linii Kiesa ludu: ", 1)[1].strip()
        if frag and frag in kl.get(d, ""):
            ok1 += 1
        else:
            bad1 += 1
            bad1x.append(d)
        # C4-2: liczba w oknie z udzialu w tej samej linii
        m = re.search(r"\| stac jedzenie ([\d.]+), pelny ([\d.]+) \(w oknie (\d+) / (\d+) na 100", s)
        pairs = []
        if m:
            pairs = [(float(m.group(1)), int(m.group(3))), (float(m.group(2)), int(m.group(4)))]
        else:
            m = re.search(r"\| wies: zakupy (\d+) z ([\d.]+) \(w oknie (\d+) na 100", s)
            if m and float(m.group(2)) > 0:
                pairs = [(min(1.0, int(m.group(1)) / float(m.group(2))), int(m.group(3)))]
        if pairs and all(0 <= v <= 100 and abs(v - 100.0 * x) <= 1.0 + 1e-9 for x, v in pairs):
            ok2 += 1
        else:
            bad2x.append(d)
    n = ok1 + bad1
    if n == 0:
        rep.add("E5/C4-1: liczba w oknie = liczba z linii Kiesa ludu (ta sama doba)",
                f"brak otwarc okna z liczbami w dobach 1-{until}" + (f" ('not reckoned yet' {early}, bez zdania {nofolk})" if early or nofolk else ""),
                "reczne sprawdzenie Jeffa (autotest nie otwiera menu): fragment linii okna = fragment linii Kiesa ludu", None)
        rep.add("E5/C4-2: liczba w oknie = udzial x 100 (w dol)", "brak otwarc okna z liczbami", "+-1, 0-100", None)
    else:
        rep.add("E5/C4-1: liczba w oknie = liczba z linii Kiesa ludu (ta sama doba)",
                f"zgodne {ok1} z {n} otwarc" + (f" (pierwsza niezgodna d{run_day(bad1x[0], start)})" if bad1x else "")
                + (f"; 'not reckoned yet' {early}, bez zdania {nofolk}" if early or nofolk else ""),
                "wszystkie zgodne (fragment linii okna jest w linii Kiesa ludu: dzien N)", bad1 == 0)
        rep.add("E5/C4-2: liczba w oknie = udzial x 100 (w dol)",
                f"zgodne {ok2} z {n}" + (f" (pierwsza niezgodna d{run_day(bad2x[0], start)})" if bad2x else ""),
                "+-1 (zaokraglenie F2/N0 w linii), 0-100", len(bad2x) == 0)
    # C4-3: bledy
    err = [s for s in lines if s.startswith(("ERROR in PeopleMenu.Bread", "ERROR in PeopleMenu.Consequence"))]
    rep.add("E5/C4-3: bledy okna (ERROR in PeopleMenu.Bread / Consequence)", f"{len(err)}", "0", len(err) == 0)


def etap5_b1(rep, lines, start, until, logp):
    """E5/B1 (173, kiesa ludu czynna; plan kodu docs/etap5/PLAN-KODU-E5B1.md rozdz. 11, progi B1-T1..T20). Okno: doby kampanii 2-until; sr28 - ostatnie 28 dob okna.
    Linie: "Kiesa ludu (E5/B1): CZYNNA" (stan), "Kiesa ludu: dzien" (doba), "Podstawa robocizny (E5/B1)", "Prawa panskie (E5/B1)", "Zadowolenie ludu (R14)",
    "Kiesa ludu (E5/B1): zapasy startowe", "Gotowka wsi (E5/0)", "Przeplywy osad (kasy miast|kasy zamkow)", "Pieniadz swiata (bilans - przyczyny)"."""
    st_on = [x for x in lines if x.startswith("Kiesa ludu (E5/B1): CZYNNA")]
    st_off = [x for x in lines if x.startswith("Kiesa ludu (E5/B1): NIECZYNNA")]
    stl = next((x for x in lines if x.startswith("Kiesa ludu (E5/B1): okna wpiete:")), None)
    kie = by_day(lines, "Kiesa ludu: dzien")
    win = sorted(d for d in kie if 2 <= run_day(d, start) <= until)
    full = [d for d in win if "doba niepelna" not in kie[d] and "czeka na kalibracje" not in kie[d]]
    w28 = _last28(full)
    # ---- B1-T1 bledy i potkniecia
    errs = [x for x in lines if x.startswith("ERROR in TownFolk")]
    sites = sorted(set(x[len("ERROR in "):].split(":")[0] for x in errs))
    stum = sum(num(r"\| potkniecia (\d+) \(sesja", kie[d], int, 0) or 0 for d in win)
    brak = re.search(r"; BRAK: (.*?); klucz przy starcie", stl) if stl else None
    rep.add("B1-T1: bledy, potkniecia, okna B1 (linia startowa)",
            f"ERROR in TownFolk {len(errs)}" + (f" ({', '.join(sites[:6])})" if sites else "") + f"; potkniecia {stum}; BRAK: {brak.group(1) if brak else '?'}",
            "0 bledow; <= 5 potkniec w biegu; BRAK: -", len(errs) == 0 and stum <= 5 and brak is not None and brak.group(1).strip() == "-")
    # ---- B1-T2 czynna kazdej doby (bieg B bez kiesy czynnej - NIE, P K3)
    a1 = bool(st_on) and all(" | A1: tak" in x for x in st_on)
    miss = [run_day(d, start) for d in range(min(win) if win else 0, (max(win) + 1) if win else 0) if d not in kie]
    rep.add("B1-T2: kiesa czynna kazdej doby (linia stanu CZYNNA, A1 tak, linia doby)",
            f"linii CZYNNA {len(st_on)}, NIECZYNNA {len(st_off)}; dob z linia {len(win)} (pelnych {len(full)}), brak w {len(miss)}" + (f" (d{', d'.join(str(x) for x in miss[:5])})" if miss else ""),
            "CZYNNA, A1 tak, linia kazdej doby 2-until; NIE, gdy bieg B bez kiesy czynnej", bool(st_on) and a1 and not st_off and len(miss) == 0 and len(win) > 0)
    if st_on:
        rep.add("B1-T2b: klucze B w linii stanu (P K3)", _grp(r"klucze B: ([^|]+)", st_on[-1], 1).strip()[:200], "INFO (wartosci czynne: przy wyrownaniu B3 0.50 i 2/1.5/0.25, bez - 0.67 i 3/1/0.25; statki B5 ON/ON/ON; progi w blokach B2/B3/B5)", None)
        rep.add("B1-T2c: stawki i przelaczniki (linia stanu)", (_grp(r"stawki: ([^|]+)", st_on[-1], 1).strip() + " | " + _grp(r"kotwica: ([^|]+)", st_on[-1], 1).strip())[:300], "INFO", None)
        rep.add("B1-T2d: kategorie lepsze i zakupy wsi (znalezione)", _grp(r"kategorie \"lepsze\": ([^|]+)", st_on[-1], 1).strip()[:200], "INFO (BRAK = lista do poprawy)", None)
    if not full:
        return
    # ---- B1-T3 kontrola zamknieta kies
    bad3 = []
    for d in full:
        m = re.search(r"kontrola: zmiana kies (-?\d+) = wplywy (-?\d+) - wydatki (-?\d+), r = (-?\d+|-)", kie[d])
        if m and m.group(4) != "-" and abs(int(m.group(4))) > 1:
            bad3.append((run_day(d, start), int(m.group(4))))
    rep.add("B1-T3: kontrola zamknieta kies ludu (zmiana = wplywy - wydatki)", f"poza progiem {len(bad3)} z {len(full)} dob" + (f" (np. d{bad3[0][0]}: r = {bad3[0][1]})" if bad3 else ""),
            "|r| <= 1 zl kazdej doby", len(bad3) == 0)
    # ---- B1-T4 reszta ksiegi (etap 3)
    cau = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    cd = [d for d in full if d in cau]
    rv = num(r"srednia 28 dob ([+-]?\d+)", cau[cd[-1]]) if cd else None
    rep.add("B1-T4: reszta ksiegi R (srednia 28 dob, ostatnia doba okna)", f"{rv}" if rv is not None else "brak linii", "|R| < 10 000 (prog etapu 3)", (abs(rv) < 10000) if rv is not None else None)
    # ---- B1-T5 "zakupy" z niczego 0 (miasta i zamki)
    pm, pz = by_day(lines, "Przeplywy osad (kasy miast): dzien"), by_day(lines, "Przeplywy osad (kasy zamkow): dzien")
    nz = [run_day(d, start) for d in full if (num(r'"zakupy" mieszkancow ([+-]?\d+)', pm.get(d, ""), int, 0) or 0) != 0 or (num(r'"zakupy" mieszkancow ([+-]?\d+)', pz.get(d, ""), int, 0) or 0) != 0]
    lf = _mean([num(r"lud za towar \(E5/B1\) ([+-]?\d+)", pm.get(d, ""), int) for d in w28])
    rep.add("B1-T5: \"zakupy\" z niczego (kasy miast i zamkow)", f"dob != 0: {len(nz)} z {len(full)}" + (f" (d{', d'.join(str(x) for x in nz[:5])})" if nz else "") + (f"; lud za towar sr28 {lf:.0f}/d" if lf is not None else ""),
            "0 kazdej doby (A1-T4 dalej)", len(nz) == 0)
    # ---- B1-T6 zjedzone bez zaplaty < 1% wydatku gry
    q6 = _mean([fnum(r"zjedzone bez zaplaty \d+ \(([\d.]+)%", kie[d]) for d in w28])
    rep.add("B1-T6: zjedzone bez zaplaty (sr28)", f"{q6:.2f}% wydatku gry" if q6 is not None else "-", "< 1% (miasta + zamki)", (q6 < 1.0) if q6 is not None else None)
    # ---- B1-T7 stac jedzenie - kazde miasto (prog projektu 0 - spodziewane NIE: rozklad, nie stawki - plan rozdz. 7.3, raport dla Jeffa)
    n7 = [num(r"miast ze stac jedzenie < 95%: (\d+)", kie[d], int) for d in full]
    n7 = [x for x in n7 if x is not None]
    n28 = _mean([num(r"miast ze stac jedzenie < 95%: (\d+)", kie[d], int) for d in w28])
    d40 = [d for d in full if run_day(d, start) <= 40]
    t40 = _mean([num(r"miast ze stac jedzenie < 95%: (\d+)", kie[d], int) for d in d40[-14:]]) if d40 else None
    rep.add("B1-T7: miast ze stac jedzenie < 95% (sr28, max, trend wobec d40)",
            (f"sr28 {n28:.1f}, max {max(n7)}" if n7 and n28 is not None else "-") + (f", d27-40 {t40:.1f}" if t40 is not None else ""),
            "prog projektu 0 kazdej doby - spodziewane NIE (rozklad dochodu miast, plan rozdz. 7.3) - raport dla Jeffa", (max(n7) == 0) if n7 else None, decide=True)
    # ---- B1-T8 pelny koszyk swiata (projekt rozdz. 4: swiat >= 98% i miast z pelnym < 95% najwyzej 5%; recenzja B1 (1-6) - obie czesci progu)
    pw = _mean([fnum(r"pelny W/R/P ([\d.]+)%", kie[d]) for d in w28])
    pr8 = _mean([fnum(r"pelny W/R/P [\d.]+% / ([\d.]+)%", kie[d]) for d in w28])
    pp8 = _mean([fnum(r"pelny W/R/P [\d.]+% / [\d.]+% / ([\d.]+)%", kie[d]) for d in w28])
    ps8 = _mean([fnum(r"pelny W/R/P [^,|]*\(swiat ([\d.]+)%\)", kie[d]) for d in w28])
    q8 = []
    for d in w28:
        t8, n8 = num(r"\| miasta (\d+): ludzie ksiegi", kie[d], int), num(r"pelny < 95%: (\d+)", kie[d], int)
        if t8 and n8 is not None:
            q8.append(n8 * 100.0 / t8)
    q8 = _mean(q8)
    rep.add("B1-T8: pelny koszyk swiat (waga potrzeb) i miast z pelnym < 95% (sr28)",
            (f"swiat {ps8:.1f}%" if ps8 is not None else "swiat - (linia bez wagi swiata)") + (f" (W {pw:.1f}% / R {pr8:.1f}% / P {pp8:.1f}%)" if None not in (pw, pr8, pp8) else "")
            + (f"; miast z pelnym < 95% {q8:.1f}%" if q8 is not None else ""),
            "swiat >= 98% i miast z pelnym < 95% najwyzej 5% (P rozdz. 4) - spodziewane NIE (plan 7.1), raport",
            (ps8 >= 98 and q8 <= 5) if (ps8 is not None and q8 is not None) else None, decide=True)
    # ---- B1-T9 podzamcze
    c9 = _mean([fnum(r"\| podzamcze \d+: .*?stac ([\d.]+)%", kie[d]) for d in w28])
    nc = _mean([num(r"zamkow bez kredytu (\d+)", kie[d], int) for d in w28])
    rep.add("B1-T9: podzamcze - stac (sr28, z kuchnia pana)", (f"{c9:.1f}%" if c9 is not None else "-") + (f"; zamkow bez kredytu dworu sr28 {nc:.0f}" if nc is not None else ""),
            ">= 95% (INFO, gdy NIE - liczba zamkow bez dworu)", (c9 >= 95) if c9 is not None else None)
    # ---- B1-T10/T11 wies: pan w utargu i w gotowce (Gotowka wsi - linia przy LogEnabled i ksiedze obiegu)
    gw = by_day(lines, "Gotowka wsi (E5/0): dzien")
    ut, gg, worst = [], [], []
    for d in w28:
        x = gw.get(d)
        if not x:
            continue
        for mm in re.finditer(r"(niska|zwykla|wysoka|zwolnienie): wsi \d+, G -?\d+ \([^)]*\), pan [^,]+, pan z majatkami ([\d.]+)%, w utargu: pan ([\d.]+)% / majatki ([\d.]+)%", x):
            if mm.group(1) == "zwykla":
                ut.append(float(mm.group(3)) + float(mm.group(4))); gg.append(float(mm.group(2)))
            worst.append(float(mm.group(2)))
    u10, g11 = _mean(ut), _mean(gg)
    # decyzja Jeffa 12.10 (wsie nie gromadza): dopisek pana z utargu (VillageLordExtraShare) z linii stanu - zwykla 35 + dopisek (0.10 -> 45%, niska 35, wysoka 55);
    # log sprzed decyzji (bez segmentu) - dopisek 0 (35 / 25 / 45%); udzial w gotowce G przesuniety o 0.8 dopisku (utarg ok. 80% G), sufit kazdej polityki o caly dopisek
    ex10 = (fnum(r"dopisek pana z utargu wsi ([\d.]+)", st_on[-1]) or 0.0) * 100 if st_on else 0.0
    e10 = 35 + ex10
    rep.add("B1-T10: wies - pan z majatkami w utargu (zwykla, sr28)", f"{u10:.1f}%" if u10 is not None else "brak linii Gotowka wsi",
            f"{e10:.0f}% +-2 pp (niska {e10 - 10:.0f}, wysoka {e10 + 10:.0f}; 35 + dopisek z linii stanu)", (abs(u10 - e10) <= 2) if u10 is not None else None)
    lo11, hi11, cap11 = 28 + 0.8 * ex10, 45 + 0.8 * ex10, 50 + ex10
    rep.add("B1-T11: wies - pan z majatkami w gotowce G (zwykla sr28; najwiecej z polityk)", (f"{g11:.1f}%" if g11 is not None else "-") + (f"; max {max(worst):.1f}%" if worst else ""),
            f"zwykla {lo11:.0f}-{hi11:.0f}%, kazda <= {cap11:.0f}% (28-45 / 50 + dopisek)", (lo11 <= g11 <= hi11 and max(worst) <= cap11) if (g11 is not None and worst) else None)
    # ---- B1-T12 renta 20% wsi zastapiona oplatami
    pr = by_day(lines, "Prawa panskie (E5/B1): dzien")
    fee = _mean([num(r"oplaty stale wsi (\d+)", pr[d], int) for d in w28 if d in pr])
    rep.add("B1-T12: oplaty stale wsi (sr28; renta 20% = 0 przy kiesie czynnej)", f"{fee:.0f}/d" if fee is not None else "brak linii Prawa panskie", "5-15 tys./d [R 9.0]",
            (5000 <= fee <= 15000) if fee is not None else None)
    # ---- B1-T13 zakupy wsi
    vb = [(num(r"wsie \d+: zakupy (\d+) z (\d+)", kie[d], int), num(r"wsie \d+: zakupy \d+ z (\d+)", kie[d], int)) for d in w28]
    vb = [(a, b) for a, b in vb if a is not None and b]
    q13 = sum(a for a, _ in vb) / sum(b for _, b in vb) * 100 if vb else None
    rep.add("B1-T13: zakupy wsi wobec potrzeby (sr28)", f"{q13:.1f}%" if q13 is not None else "-", ">= 75% (INFO; KL 90% - wsie bez gotowki)", None)
    # ---- B1-T14 zapasy startowe
    sl = [x for x in lines if x.startswith("Kiesa ludu (E5/B1): zapasy startowe")]
    if sl:
        tot = [int(t) for t in re.findall(r"\) = (\d+) \(miast", sl[0])]
        rep.add("B1-T14: zapasy startowe (linia jednorazowa)", f"linii {len(sl)}; razem {sum(tot)}; " + _grp(r"zapasy startowe ([^-]+)", sl[0], 1).strip()[:120],
                "nowa kampania: 5-10 mln z daru; zapis z d362: \"z nadwyzki\"", (5e6 <= sum(tot) <= 10e6) if "z daru" in sl[0] else None)
        # recenzja B1 (1-6): S = M20 w ksiedze +-1 (plan rozdz. 11) - przelew kas do kies W/R/P i podzamczy; zapas wsi to przelew kasa miasta -> kiesa wsi (w ksiedze netto 0)
        exp14, parts14 = 0, 0
        for x in sl:
            for mm in re.finditer(r"wsie (\d+) \(\d+ wsi\) = (\d+) \(miast", x):
                exp14 -= int(mm.group(2)) - int(mm.group(1))
                parts14 += 1
        m20 = [int(v) for x in lines if x.startswith("Przeplywy osad (")
               for v in re.findall(r"zapasy startowe kies ludu \(E5/B1, raz\): z daru kas albo z nadwyzki \(stary zapis\) ([+-]\d+)", x)]
        if m20 and parts14:
            rep.add("B1-T14b: zapasy startowe = M20 w ksiedze (+-1 na klase)", f"M20 {sum(m20)} (wpisow {len(m20)}), z linii zapasow {exp14} ({parts14} czesci)",
                    "rowne +-1 na klase", abs(sum(m20) - exp14) <= 3 * parts14)
        else:
            rep.add("B1-T14b: zapasy startowe = M20 w ksiedze", "brak M20 w liniach Przeplywy osad" if parts14 else "linia zapasow bez sumy", "M20 w dobie zapasow (ksiega obiegu wlaczona)", None)
    else:
        rep.add("B1-T14: zapasy startowe", "brak linii", "1 linia (nowa kampania albo stary zapis)", False)
    # ---- B1-T15 R14
    r14 = by_day(lines, "Zadowolenie ludu (R14): dzien")
    k15 = _mean([num(r"korekty (\d+)", r14[d], int) for d in w28 if d in r14])
    rep.add("B1-T15: R14 - korekty zadowolenia (sr28; tylko osady z Afford < 0.98)", f"{k15:.0f}/d" if k15 is not None else "brak linii", "INFO", None)
    # ---- B1-T16 koszt
    cost = [(fnum(r"czas: latki ([\d.]+) ms", kie[d]) or 0) + (fnum(r", doba ([\d.]+) ms", kie[d]) or 0) for d in full if "czas: latki" in kie[d]]
    if cost:
        rep.add("B1-T16: koszt (latki + doba) srednio", f"{sum(cost) / len(cost):.1f} ms/dobe (max {max(cost):.1f})", "<= 50 ms (INFO; optymalizacja na koniec - decyzja 08.10)", None)
    # ---- B1-T17/T18/T19 odsylacze
    rep.add("B1-T17: S4 jedzenie warowni", "--grupa etap4 (F6/F7) i linia \"Jedzenie z targu (E5/0)\"", "warownie miast glodne 0 przed 30. doba zimy", None)
    rep.add("B1-T18: progi etapow 2-4", "--grupa etap2 / etap3 / etap4 na tym samym logu", "glowy < 5 000 najwyzej 10; 0 bankructw; wojsko lordow w wojnie 95-115 tys. (podloga 85)", None)
    # ---- B1-T20 haki 75/25: wojsko w dochodzie ludu wobec podstawy robocizny (75%)
    lab = by_day(lines, "Podstawa robocizny (E5/B1): dzien")
    xa = sum(num(r"\| dochod ludu miast z zewnatrz i z kas -?\d+: wojsko (\d+)", kie[d], int, 0) or 0 for d in w28)
    ya = sum(fnum(r"zolnierze i zalogi \(75%\) ([\d.]+)", lab.get(d, ""), 0.0) or 0.0 for d in w28)
    q20 = xa / (xa + ya) * 100 if xa + ya > 0 else None
    rep.add("B1-T20: haki 75/25 - czesc ludu w wydatkach zolnierzy w miastach (sr28)", f"{q20:.2f}%" if q20 is not None else "-", "25% +-1 pp", (abs(q20 - 25) <= 1) if q20 is not None else None)


def etap5_wsie(rep, lines, start, until):
    """Decyzja Jeffa 12.10 10:15 (wsie i lud nie gromadza; projekt etapu 5 R11, R13, R21, C3): dziesiecina (linia "Dziesiecina (E5/C3)"), pan z majatkami
    w utargu wszystkich wsi (linia "Utarg wsi (112)"), tempo nadwyzki (linia doby kiesy ludu), zmiana kies wsi i ludu miast ("Pieniadz swiata"). Okno: doby
    kampanii 2-until; sr28 - ostatnie 28 pelnych dob. Wartosci czynne z linii stanu "Kiesa ludu (E5/B1): CZYNNA" (segment "decyzja 12.10")."""
    st_on = [x for x in lines if x.startswith("Kiesa ludu (E5/B1): CZYNNA")]
    if not st_on or "decyzja 12.10:" not in st_on[-1]:
        rep.add("W12: linia stanu z segmentem decyzja 12.10", "brak (log sprzed decyzji)", "jest od wgrania (wsie nie gromadza)", None)
        return
    st = st_on[-1]
    extra = fnum(r"dopisek pana z utargu wsi ([\d.]+)", st) or 0.0
    tempo = fnum(r"tempo nadwyzki ([\d.]+)/d", st)
    tithe_on = "dziesiecina tak" in st
    share = fnum(r"dziesiecina tak \(wsie ([\d.]+) utargu", st) or 0.0
    kie = by_day(lines, "Kiesa ludu: dzien")
    win = sorted(d for d in kie if 2 <= run_day(d, start) <= until)
    full = [d for d in win if "doba niepelna" not in kie[d] and "czeka na kalibracje" not in kie[d]]
    w28 = _last28(full)
    rep.add("W12-0: wartosci czynne (linia stanu)", _grp(r"decyzja 12.10: ([^|]+)", st, 1).strip()[:200], "INFO (dopisek 0.10, tempo 0.15, dziesiecina tak 0.05, kaplani BK odczyt ok)", None)
    # ---- W12-1/2/3 dziesiecina
    ti = by_day(lines, "Dziesiecina (E5/C3): dzien")
    if tithe_on:
        miss = [run_day(d, start) for d in full if d not in ti]
        skip = [run_day(d, start) for d in full if d in ti and "POMINIETA" in ti[d]]
        rep.add("W12-1: dziesiecina - linia kazdej pelnej doby, bez dob pominietych (kaplani BK)",
                f"brak w {len(miss)}, pominieta w {len(skip)} z {len(full)} dob" + (f" (d{', d'.join(str(x) for x in (miss + skip)[:5])})" if miss or skip else "")
                + ("; " + _grp(r"kaplani BK: ([^|]+)", st, 1).strip() if "kaplani BK:" in st else ""),
                "0 i 0; kaplani BK: odczyt ok", len(miss) == 0 and len(skip) == 0 and "kaplani BK: odczyt ok" in st)
        t28 = [ti[d] for d in w28 if d in ti]
        def s28(pat):
            return sum(num(pat, x, int, 0) or 0 for x in t28)
        tot, tv, tt = s28(r"\| razem (\d+) ="), s28(r"= wsie (\d+) \("), s28(r"\) \+ lud miast (\d+) \(")
        via, alms, wage, mat, nomk = s28(r"\| przez kaplanow (\d+)"), s28(r"jalmuzna (\d+)"), s28(r"place ludu (\d+)"), s28(r"material do kas miast (\d+)"), s28(r"bez miasta targowego \(zostalo w kiesie\) (\d+)")
        nop, due = s28(r"\| bez kaplana (\d+)"), s28(r"nalezne (\d+) =")
        n = max(1, len(t28))
        rep.add("W12-2: dziesiecina razem (sr28)", f"{tot / n:.0f}/d = wsie {tv / n:.0f} + lud miast {tt / n:.0f}; przez kaplanow {via / n:.0f} (jalmuzna {alms / n:.0f}, place septow {wage / n:.0f}, "
                f"material {mat / n:.0f}, wsie bez targu {nomk / n:.0f}); bez kaplana {nop / n:.0f}", "INFO (rachunek z kopia-fin3: wsie ok. 14 tys./d, lud miast ok. 10 tys./d)", None)
        build = wage + mat
        ok3 = via > 0 and abs(alms / via - 0.5) <= 0.005 and (build == 0 or abs(wage / build - 0.75) <= 0.005) and abs(alms + wage + mat + nomk - via) <= len(t28) * 2
        rep.add("W12-3: podzial przez kaplanow: jalmuzna 50%, z budowy place 75% / material 25%, suma = przez kaplanow (sr28)",
                f"jalmuzna {alms / via * 100:.2f}%, place {wage / build * 100:.2f}% budowy, rozjazd sumy {alms + wage + mat + nomk - via}" if via > 0 and build > 0 else "brak przeplywu przez kaplanow",
                "50% +-0.5 pp, 75% +-0.5 pp, rozjazd <= 2 zl na dobe", ok3 if via > 0 else False)
        # nalezne wsi wobec utargu okna (linia Utarg wsi (112) - ta sama doba ksiegi)
        ut = by_day(lines, "Utarg wsi (112): dzien")
        handed = sum(num(r"powroty taborow z utargiem \d+: oddane (\d+)", ut.get(d, ""), int, 0) or 0 for d in w28 if d in ti)
        q4 = due / handed if handed > 0 else None
        rep.add("W12-4: dziesiecina wsi nalezna wobec utargu taborow (sr28)", f"{q4 * 100:.2f}% (nalezne {due}, utarg {handed}; niezaplacone {due - tv})" if q4 is not None else "brak linii Utarg wsi (112)",
                f"{share * 100:.0f}% +-0.3 pp (Tithe Village Share)", (abs(q4 - share) <= 0.003) if q4 is not None else None)
    else:
        rep.add("W12-1: dziesiecina", "wylaczona (Temple Tithe 0)" + (f"; linii {len(ti)}" if ti else ""), "0 linii przy wylaczonej", len(ti) == 0)
    # ---- W12-5 pan z majatkami w utargu wszystkich wsi (mieszanka polityk; przed decyzja 35.0% w kopia-fin3)
    ut = by_day(lines, "Utarg wsi (112): dzien")
    hd = lt = es = 0
    for d in w28:
        m = re.search(r"oddane (\d+) = pan \(licznik podatku\) (\d+) .*?wlasciciele majatkow BK (\d+)", ut.get(d, ""))
        if m:
            hd += int(m.group(1)); lt += int(m.group(2)); es += int(m.group(3))
    e5 = 35 + extra * 100
    q5 = (lt + es) / hd * 100 if hd > 0 else None
    rep.add("W12-5: pan z majatkami w utargu taborow - wszystkie wsie (sr28)", f"{q5:.1f}% (pan {lt / hd * 100:.1f}%, majatki {es / hd * 100:.1f}%)" if q5 is not None else "brak linii Utarg wsi (112)",
            f"{e5:.0f}% +-3 pp (mieszanka polityk, gros zwykla; przed decyzja 35.0%)", (abs(q5 - e5) <= 3) if q5 is not None else None)
    # ---- W12-6 tempo nadwyzki: oferta (W = tempo x lokata, R/P na wierzch) / lokata W
    off = sum(num(r"oferta nadwyzki na jutro (\d+)", kie[d], int, 0) or 0 for d in w28)
    lok = sum(fnum(r"lokata \(kiesa W ponad zapas dni\) ([\d.]+)", kie[d], 0.0) or 0.0 for d in w28)
    q6 = off / lok if lok > 0 else None
    rep.add("W12-6: tempo nadwyzki - oferta nadwyzki / lokata W (sr28)", f"{q6:.3f} (oferta {off / max(1, len(w28)):.0f}/d, lokata {lok / max(1, len(w28)):.0f})" if q6 is not None else "-",
            f">= {tempo:.2f} - 0.002 (tempo z linii stanu; dotad 0.07)" if tempo is not None else ">= tempo", (q6 >= tempo - 0.002) if (q6 is not None and tempo is not None) else None)
    # ---- W12-7 zmiana kies wsi i ludu miast (cel decyzji: wsie i lud nie gromadza; przed: wsie +57.6 tys./d, lud miast +93.0 tys./d sr28 kopia-fin3)
    ps = by_day(lines, "Pieniadz swiata: dzien")
    pd = [d for d in sorted(ps) if 2 <= run_day(d, start) <= until][-28:]
    dv = _mean([num(r"kiesy wsi \d+ \(([+-]\d+)\)", ps[d], int) for d in pd])
    dt = _mean([num(r"kiesy ludu \(E5/B1\): miasta \d+ \(([+-]\d+)\)", ps[d], int) for d in pd])
    rep.add("W12-7: zmiana kies wsi i ludu miast (sr28)", (f"wsie {dv:+.0f}/d" if dv is not None else "wsie -") + (f", lud miast {dt:+.0f}/d" if dt is not None else ", lud miast -"),
            "INFO dla Jeffa (przed: wsie +57.6 tys./d, lud miast +93.0 tys./d; danina wsi 2.5% z e6-p2 dziala razem)", None)


def etap5_rows(rep, lines, start, win, logp, csvp=None):
    """Wiersze etapu 5 (projekt rozdz. 4) w szkielecie - w E5/0 INFO "stan wyjsciowy"; paczki, ktore je wiaza, zmieniaja werdykt we wlasnym bloku."""
    w28 = _last28(win)
    # panowie samych zamkow (budzet-rodow.csv): udzial w D swiata i w D stalym, mediana kiesy glowy - rody z wojna >= 21 z 28 dob (wiaze B3)
    csvp = csvp or csv_path_of(logp)
    rows = read_csv(csvp)
    if rows:
        byd = {}
        for r in rows:
            try:
                byd.setdefault(int(r.get("dzien") or 0), []).append(r)
            except ValueError:
                continue
        cd = sorted(d for d in byd if run_day(d, start) >= 1)
        wd = [d for d in cd if 252 <= run_day(d, start) <= 364] or cd[-28:]

        def fv(v):
            try:
                return float(v)
            except (TypeError, ValueError):
                return None
        warc = {}
        for d in wd:
            for r in byd[d]:
                if r.get("rodzaj") == "zamek" and r.get("wojna") == "1":
                    warc[r.get("rod_id")] = warc.get(r.get("rod_id"), 0) + 1
        need = min(21, max(1, len(wd) * 3 // 4))
        shD, shS, kies = [], [], []
        for d in wd:
            tD = tS = zD = zS = 0.0
            for r in byd[d]:
                if r.get("rodzaj") == "gracz":
                    continue
                D, S = fv(r.get("D")) or 0.0, fv(r.get("d_staly")) or 0.0
                tD += D
                tS += S
                if r.get("rodzaj") == "zamek":
                    zD += D
                    zS += S
                    if warc.get(r.get("rod_id"), 0) >= need:
                        k = fv(r.get("kiesa_glowy"))
                        if k is not None:
                            kies.append(k)
            if tD:
                shD.append(zD / tD)
            if tS:
                shS.append(zS / tS)
        kies.sort()
        rep.add("etap 5 (B3): panowie samych zamkow - udzial w D / D stalym, mediana kiesy glowy",
                f"D {(_mean(shD) or 0) * 100:.1f}%, D staly {(_mean(shS) or 0) * 100:.1f}%, mediana kiesy (wojna >= {need} dob okna) {kies[len(kies) // 2] if kies else '-'}"
                f" (doby {run_day(wd[0], start) if wd else '-'}-{run_day(wd[-1], start) if wd else '-'})", "stan wyjsciowy (wiaze B3)", None)
    else:
        rep.add("etap 5 (B3): panowie samych zamkow", f"brak {csvp}", "stan wyjsciowy (wiaze B3)", None)
    obg = by_day(lines, "Obieg: dzien")
    sak = _mean([fnum(r"= ([\d.]+) dni zoldu naliczonego", obg[d]) for d in w28 if d in obg])
    rep.add("etap 5 (A3): sakiewki zolnierzy w dniach zoldu", f"sr28 {sak:.1f}" if sak is not None else "brak dopisku (TownFolkMode 0 albo bieg sprzed E5/0)",
            "stan wyjsciowy; <= 15 dni po A3 (dzis ok. 29)", None)
    pw = by_day(lines, "Pieniadz swiata: dzien")
    pd = [d for d in win if d in pw]
    if len(pd) >= 2:
        a = pd[-29] if len(pd) > 28 else pd[0]
        za, zb = num(r"\| razem (\d+)", pw[a]), num(r"\| razem (\d+)", pw[pd[-1]])
        ch = (zb - za) / za * 100 if za and zb is not None else None
        rep.add("etap 5 (C1): zloto swiata na 28 dob", f"{ch:+.2f}% (d{run_day(a, start)} -> d{run_day(pd[-1], start)})" if ch is not None else "-",
                "stan wyjsciowy; < 0.1% po C1", None)
    dow = by_day(lines, "Dowoz (skutki): dzien")
    zat = _mean([num(r"wsie zamkowe (\d+) z", dow[d]) for d in w28 if d in dow])
    rep.add("etap 5 (B4): zatkane magazyny wsi zamkowych", f"sr28 {zat:.1f}" if zat is not None else "brak linii", "stan wyjsciowy (lato/zima osobno - wiaze B4)", None)
    prz = by_day(lines, "Przeplywy osad: dzien")
    uns = _mean([num(r"towar niesprzedany po wizycie: w miastach (\d+) szt", prz[d]) for d in w28 if d in prz])
    rep.add("etap 5 (kazdy zbior): towar wsi niesprzedany w miastach", f"sr28 {uns:.0f} szt./d" if uns is not None else "brak linii",
            "stan wyjsciowy (miasta kupuja >= 98% plonu)", None)
    lud = by_day(lines, "Ludzie: dzien")
    arm = _mean([num(r"partie rodow (\d+)", lud[d]) for d in w28 if d in lud])
    rep.add("etap 5 (kazdy zbior): wojsko lordow", f"sr28 {arm:.0f}" if arm is not None else "brak linii", "stan wyjsciowy (w wojnie 95-115 tys., podloga 85)", None)


def etap5_e50(rep, lines, start, win, **kw):
    """E5/0 (195): progi E50-T1..T10 (plan kodu E5/0 rozdz. 8) - linie "Kiesa ludu (E5/0)", "Kiesa ludu (na sucho)", "Nadwyzka kas (E5/0)", "Bitwy (E5/0)",
    "Notable (E5/0)", "Jedzenie z targu (E5/0)", "Zadowolenie BK (E5/0)", "Gotowka wsi (E5/0)" i dopisek "Obieg". Doby niepelne (pierwsza w sesji) - poza progami."""
    stl = next((s for s in lines if s.startswith("Kiesa ludu (E5/0): okna wpiete:")), None)
    if stl is None:
        rep.add("E5/0: linia startowa Kiesa ludu (E5/0)", "brak linii startowej", "jest (paczka E5/0 w DLL)", None)
        return
    kie = by_day(lines, "Kiesa ludu (na sucho): dzien")
    full = [d for d in win if d in kie and "doba niepelna" not in kie[d] and "czeka na kalibracje" not in kie[d]]
    w28 = _last28(full)
    # ---- T1 bledy, linia startowa, potkniecia, linia sesji
    errs = [s for s in lines if s.startswith("ERROR in TownFolk")]
    sites = sorted(set(s[len("ERROR in "):].split(":")[0] for s in errs))
    brak = re.search(r"; BRAK: (.*?); wlasciciele", stl)
    stum = sum(num(r"\| potkniecia (\d+) \(sesja", kie[d], int, 0) or 0 for d in win if d in kie)
    sess = [s for s in lines if s.startswith("Kiesa ludu (E5/0): sesja od dnia")]
    ok1 = len(errs) == 0 and brak is not None and brak.group(1).strip() == "-" and stum <= 5 and len(sess) > 0
    rep.add("E50-T1: bledy, linia startowa, potkniecia, linia sesji",
            f"ERROR in TownFolk {len(errs)}" + (f" ({', '.join(sites[:6])})" if sites else "") + f"; BRAK: {brak.group(1) if brak else '?'}; potkniecia {stum}; linii sesji {len(sess)}",
            "0 bledow; BRAK: -; potkniecia <= 5 w biegu; linia sesji jest", ok1)
    rep.add("E50-T1: wlasciciele latek celow (linia startowa)", _grp(r"wlasciciele latek celow: (.*?); tryb przy starcie", stl, 1)[:400], "lista (INFO)", None)
    # poprawki po tescie koncowym etapu 4 (sceptyk SCRIBE-POLYKA pkt 4): wyjatek TownFolk polkniety przez CrashScribe nie trafia do "ERROR in TownFolk" - log sesji tego startu
    if kw.get("logp"):
        crashscribe_t1_row(rep, "E50-T1: bledy TownFolk polkniete przez CrashScribe (log sesji)", kw["logp"], kw.get("csp"), where_filter="TownFolk")
    if not full:
        live = any(x.startswith("Kiesa ludu (E5/B1): CZYNNA") for x in lines)   # E5/B1: kiesa czynna - model na sucho nie biegnie (progi w bloku etap5_b1)
        rep.add("E5/0: linia Kiesa ludu (na sucho)", f"pelnych dob {len(full)} z {len(win)}" + ("; kiesa czynna E5/B1 - progi w bloku B1" if live else ""),
                "kazda doba po kalibracji (przy kiesie czynnej - INFO)", None if (live or not win) else False)
        return
    miss = [run_day(d, start) for d in win if d not in kie]
    rep.add("E5/0: linia Kiesa ludu (na sucho) codziennie", f"brak w {len(miss)} z {len(win)} dob" + (f" (d{', d'.join(str(x) for x in miss[:5])})" if miss else ""),
            "0", len(miss) == 0)
    # ---- T2 koszt
    cost = []
    for d in full:
        a, b = fnum(r"czas: latki ([\d.]+) ms", kie[d]), fnum(r", doba ([\d.]+) ms", kie[d])
        if a is not None and b is not None:
            cost.append((a + b, run_day(d, start)))
    if cost:
        m = sum(c for c, _ in cost) / len(cost)
        mx = max(cost)
        # poprawka po tescie koncowym etapu 4 (P5-E50-T2): 15 ms z prognozy planu (PLAN-KODU-E50 :466-469) -> 50 ms (ok. 0.3% doby); paczka pomiarowa do B1;
        # wiersz zbiorczy czasu linii etapow 4+5 (<= 1% doby) w --grupa etap4
        cap, crule = cost_cap(lines, full, 0.3, 50.0)     # recenzja fixC (3): udzial doby tych samych dob (0.3% = ok. 52 ms przy dobie 17.5 s)
        rep.add("E50-T2: koszt (latki + doba) srednio", f"{m:.1f} ms/dobe ({len(cost)} dob)", crule + " srednio (zbiorczo etapy 4+5 <= 1% doby - --grupa etap4)", m <= cap)
        rep.add("E50-T2: koszt najwiekszy", f"{mx[0]:.1f} ms (d{mx[1]})", "INFO", None)
    # ---- T3 kontrola na sucho
    bad3 = []
    for d in full:
        q = fnum(r"kontrola: r=-?[\d.]+ \(([\d.]+)% dochodu\)", kie[d])
        if q is not None and q > 1.0:
            bad3.append((run_day(d, start), q))
    rep.add("E50-T3: kontrola na sucho (zamknieta)", f"poza progiem {len(bad3)} z {len(full)} dob" + (f" (np. d{bad3[0][0]}: {bad3[0][1]}%)" if bad3 else ""),
            "|r| <= 1% dochodu kazdej pelnej doby", len(bad3) == 0)
    # ---- T4 bitwy wobec ksiegi + A6
    bit = by_day(lines, "Bitwy (E5/0): dzien")
    bal = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    sc1 = sa = sx = sy = soff = noff = n3 = 0
    es = []
    for d in w28:
        if d not in bit:
            continue
        s = bit[d]
        sc1 += num(r"zwyciezcy dostali -?\d+ \(wodzowie (\d+)", s, int, 0) or 0
        sa += num(r"pula z pokonanych \(zeszlo z kies\): wodzowie (\d+)", s, int, 0) or 0
        # recenzja E5/0 (1-1): wodzowie zdjeci z partii (A6 - obciazenie w nawiasie CommitGoldChanges) i partie lordow z wodzem zdjetym
        soff += num(r"zdjeci z partii - A6 - (\d+) w \d+", s, int, 0) or 0
        noff += num(r"zdjeci z partii - A6 - \d+ w (\d+)", s, int, 0) or 0
        n3 += num(r"partie lordow z wodzem zdjetym \(niewola, ucieczka\) (\d+)", s, int, 0) or 0
        x = y = None
        if d in bal:
            mz = re.search(r"\| ZRODLA .*?\bbitwy (-?\d+)", bal[d])
            mu = re.search(r"\| UJSCIA .*?\bbitwy (-?\d+)", bal[d])
            x = int(mz.group(1)) if mz else None
            y = int(mu.group(1)) if mu else None
        if x is None:
            x = num(r'zrodla "bitwy" (-?\d+)', s, int, None)
        if y is None:
            y = num(r"ujscia (-?\d+) \(a - y", s, int, None)
        sx += x or 0
        sy += y or 0
        es.append(num(r"z niczego netto na ladzie (-?\d+)", s, int, None))

    def within(v, ref, tol):
        return abs(v - ref) <= tol * max(abs(ref), 1) if (v or ref) else True
    rep.add("E50-T4: bitwy - wodzowie zwyciezcow (c1) wobec zrodel \"bitwy\" ksiegi (sr28)", f"c1 {sc1} wobec {sx} ({len(w28)} dob)", "+-2%", within(sc1, sx, 0.02) if w28 else None)
    rep.add("E50-T4: bitwy - wodzowie pokonanych (a) wobec ujsc \"bitwy\" ksiegi (sr28)", f"a {sa} wobec {sy}", "+-2%", within(sa, sy, 0.02) if w28 else None)
    rep.add("E50-T4: wodzowie zdjeci z partii - obciazenie A6 (sr28; INFO)", f"{soff} zl w {noff} obciazeniach; partii lordow z wodzem zdjetym {n3}",
            "INFO (bez A6: 0 zl - gra ich nie obciaza; z A6 > 0, w a i w ujsciach \"bitwy\")", None)
    em = _mean(es)
    if em is not None:
        rep.add("E50-T4: A6 - z niczego netto na ladzie sr28", f"{em:.0f}/d", "<= 5 000/d - inaczej A6 POTRZEBNE (Jeff 11.10 16:20: A6 i tak w porcji A)",
                em <= 5000, decide=em > 5000)
    # ---- T5 wydatek z petli BK wobec ConsumedValue
    # poprawka po tescie koncowym etapu 4 (E50-T5): BK zdejmuje z budzetu ilosc ULAMKOWA x cena, a do ConsumedValue zapisuje MBRandom.RoundRandomized(ilosc) x cena -
    # wartosc oczekiwana rowna, ale kazda doba ma rozrzut kilku procent (d1-120: odchylenie ok. 7%). Prog na sumie 28 dob +-2% (K1: budzet raz na kategorie, nawias
    # nie gubi wierszy - stale obciazenie), dzien - INFO z progiem bezpieczenstwa |r| <= 25% (bledny nawias = rzad wielkosci), sumy calego okna - INFO
    bad5, nob, lfn, lfc, r5 = [], [], [], 0, []
    rx5 = re.compile(r"wydatek z petli BK (\d+) wobec ConsumedValue (\d+) \(roznica (-?[\d.]+)%\)")
    for d in full:
        q = fnum(r"\(roznica (-?[\d.]+)%\)", kie[d])
        if q is not None and abs(q) > 2.0:
            bad5.append((run_day(d, start), q))
        m5 = rx5.search(kie[d])
        if m5:
            r5.append((d, int(m5.group(1)), int(m5.group(2)), float(m5.group(3))))
        nob.append(num(r"osad z konsumpcja bez BK (\d+)", kie[d], int, 0) or 0)
        # recenzja E5/0 (2-1): dokup jedzenia BK (zapas <= 10%) - nadwyzka petli nad ConsumedValue zdjeta z wydatku jedzenia przed porownaniem
        lfn.append(num(r"dokup jedzenia BK \(zapas <= 10%\): osad (\d+)", kie[d], int, 0) or 0)
        if d in w28:
            lfc += num(r"petla ponad ConsumedValue zdjeta z wydatku jedzenia (\d+)", kie[d], int, 0) or 0
    if r5:
        s28 = [x for x in r5 if x[0] in w28]
        w5, c5 = sum(x[1] for x in s28), sum(x[2] for x in s28)
        q28 = 100.0 * (w5 / c5 - 1.0) if c5 else None
        rep.add("E50-T5: wydatek z petli BK wobec ConsumedValue - suma 28 dob", (f"{q28:+.2f}% (wydatek {w5} wobec CV {c5}, {len(s28)} dob)" if q28 is not None else "-"),
                "|suma wydatku / suma CV - 1| <= 2% (K1: budzet raz na kategorie; dzien rozrzuca RoundRandomized BK)", (abs(q28) <= 2.0) if q28 is not None else None)
        wa, ca = sum(x[1] for x in r5), sum(x[2] for x in r5)
        qs = [x[3] for x in r5]
        worst5 = max(r5, key=lambda x: abs(x[3]))
        rep.add("E50-T5: wydatek wobec ConsumedValue dziennie (rozklad) i suma okna",
                f"srednia {st.mean(qs):+.2f}%, odchylenie {st.pstdev(qs):.2f}%, najwieksze |r| {abs(worst5[3]):.2f}% (d{run_day(worst5[0], start)}); poza +-2%: {len(bad5)} z {len(full)} dob (INFO);"
                f" suma okna {100.0 * (wa / ca - 1.0) if ca else 0:+.2f}% ({len(r5)} dob)",
                "kazda doba |r| <= 25% (prog bezpieczenstwa - bledny nawias dalby rzad wielkosci); +-2% dziennie i suma okna - INFO", all(abs(x) <= 25.0 for x in qs))
    else:
        rep.add("E50-T5: wydatek z petli BK wobec ConsumedValue", f"brak pola \"wydatek z petli BK ... wobec ConsumedValue\"; poza +-2%: {len(bad5)} z {len(full)} dob",
                "suma 28 dob +-2%", None)
    rep.add("E50-T5: osad z konsumpcja bez BK (INFO)", f"najwiecej {max(nob) if nob else '-'}", "INFO (d120 zbioru 31: 0)", None)
    rep.add("E50-T5: dokup jedzenia BK - osad (najwiecej na dobe), zdjete z wydatku jedzenia (sr28; INFO)",
            f"osad najwiecej {max(lfn) if lfn else '-'}; zdjete {lfc / max(len(w28), 1):.0f}/d", "INFO (oblezenia, glod - zapas warowni <= 10%)", None)
    # ---- T6 notable wobec "Obieg: notable"
    nt = by_day(lines, "Notable (E5/0): dzien")
    obn = by_day(lines, "Obieg: notable i karawany: dzien")
    so = si = lo = li = ko = ki = 0
    for d in w28:
        if d not in nt or d not in obn:
            continue
        s = nt[d]
        # recenzja E5/0 (1-2): przelewy notabl <-> kasa osady (A3) osobno - do kontroli z ksiega tylko "w nicosc / z niczego"
        ko += (num(r"do kasy osady (\d+) /", s, int, 0) or 0) + (num(r"do kasy osady targowej (\d+) /", s, int, 0) or 0)
        ki += (num(r"/ z kasy osady (\d+)", s, int, 0) or 0) + (num(r"/ z kasy osady targowej (\d+)", s, int, 0) or 0)
        so += (num(r"miasta: w nicosc (\d+)", s, int, 0) or 0) + (num(r"wsie: w nicosc (\d+)", s, int, 0) or 0)
        si += (num(r"miasta: w nicosc \d+ / z niczego (\d+)", s, int, 0) or 0) + (num(r"wsie: w nicosc \d+ / z niczego (\d+)", s, int, 0) or 0)
        lo += abs(num(r"nadwyzka w nicosc (-?\d+)", obn[d], int, 0) or 0)
        li += num(r"dosypka z niczego \+?(-?\d+)", obn[d], int, 0) or 0
    rep.add("E50-T6: notable - w nicosc wobec Obieg (sr28)", f"{so} wobec {lo}", "+-1%", within(so, lo, 0.01) if w28 else None)
    rep.add("E50-T6: notable - z niczego wobec Obieg (sr28)", f"{si} wobec {li}", "+-1%", within(si, li, 0.01) if w28 else None)
    rep.add("E50-T6: notable - przez kase osady (A3; sr28; INFO)", f"do kasy {ko}, z kasy {ki}", "INFO (bez A3: 0; z A3 - pasmo w kasach, w nicosc / z niczego ok. 0)", None)
    # ---- T7 gotowka wsi: podzial wedlug polityki = liczby swiata
    gw = by_day(lines, "Gotowka wsi (E5/0): dzien")
    bad7, share = [], []
    for d in full:
        if d not in gw:
            continue
        m7 = re.search(r"kontrola podzialu: utarg (-?\d+) wobec (-?\d+), przelewy (-?\d+) wobec (-?\d+), sakiewki (-?\d+) wobec (-?\d+)", gw[d])
        if not m7:
            continue
        v = [int(x) for x in m7.groups()]
        if abs(v[0] - v[1]) > 1 or abs(v[2] - v[3]) > 1 or abs(v[4] - v[5]) > 1:
            bad7.append(run_day(d, start))
        g = num(r"wplynelo (-?\d+)", gw[d], int, 0) or 0
        t, r_ = num(r"licznik podatku wsi (-?\d+)", gw[d], int, 0) or 0, num(r"\+ renta (-?\d+)\)", gw[d], int, 0) or 0
        if d in w28 and g > 0:
            share.append((t + r_) / g)
    nd7 = sum(1 for d in full if d in gw)
    rep.add("E50-T7: gotowka wsi - suma wedlug polityki = swiat", f"rozjazd w {len(bad7)} z {nd7} dob" + (f" (d{', d'.join(str(x) for x in bad7[:5])})" if bad7 else ""),
            "+-1 zl kazdej doby (jedna definicja z Przeplywy osad)", len(bad7) == 0 if nd7 else None)
    rep.add("E50-T7: udzial pana (licznik + renta) w gotowce wsi sr28 (INFO)", f"{(_mean(share) or 0) * 100:.1f}%" if share else "-", "INFO (rozpoznanie A: 86.2%)", None)
    # ---- T8 gra bez zmian
    rep.add("E50-T8: gra bez zmian (reszta ksiegi < 10 tys./d)", "--grupa etap3 na tym samym logu; recenzja diffu \"tylko odczyt\"", "INFO", None)
    # ---- T9 odczyty do kalibracji B (sr28 i ostatnia doba)
    last = full[-1]
    k = kie[last]
    mav = _mean([fnum(r"kotwica m srednio ([\d.]+)", kie[d]) for d in w28])
    kav = _mean([fnum(r"kasy miast po B1 \(szacunek\): (-?\d+)", kie[d]) for d in w28])
    rep.add("E50-T9: stac jedzenie W/R/P (ostatnia doba)", _grp(r"stac jedzenie W/R/P ([^,|]+)", k, 1).strip(), "INFO", None)
    rep.add("E50-T9: pelny koszyk W/R/P; miast < 95% (ostatnia doba)", _grp(r"pelny W/R/P [^,|]+, miast ze stac jedzenie < 95%: \d+, pelny < 95%: \d+", k), "INFO", None)
    rep.add("E50-T9: kotwica m srednio sr28; zjedzone bez zaplaty (ostatnia doba)",
            (f"m {mav:.2f}" if mav is not None else "m -") + "; " + _grp(r"zjedzone bez zaplaty (\d+ \([^)]*\))", k, 1), "INFO", None)
    rep.add("E50-T9: kasy miast po B1 (szacunek) sr28", f"{kav:.0f}/d" if kav is not None else "-", "INFO (rachunek przed testem B)", None)
    nad = by_day(lines, "Nadwyzka kas (E5/0): dzien")
    if last in nad:
        s = nad[last]
        rep.add("E50-T9: nadwyzka D4 i pas ponizej zapasu (ostatnia doba)", _grp(r"ponad zapasem \d+ w \d+ miastach", s) + "; "
                + _grp(r"zakupy kas miast z pasa ponizej zapasu: [^|]+", s)[:160], "INFO", None)
        rep.add("E50-T9: korona - potrzeba R15, K3", _grp(r"potrzeba R15 dzis: \d+ krolestw", s) + "; " + _grp(r"K3: [^|]+", s)[:140], "INFO", None)
        rep.add("E50-T9: udzial zysku kupcow zabierany przez pana i korone (Jeff 16:10)", _grp(r"udzial zysku kupcow zabierany przez pana i korone: [^|]+", s)[:260],
                "INFO (odniesienie historyczne ok. 10% - decyzja Jeffa po tescie)", None)
        rep.add("E50-T9: zaulki - kasy ponizej zapasu (Jeff 16:10)", _grp(r"zaulki \(od startu sesji\): [^|]+", s)[:240], "INFO", None)
    fo = by_day(lines, "Jedzenie z targu (E5/0): dzien")
    if last in fo:
        rep.add("E50-T9: zamki z polka jedzenia < 10 dni zuzycia (B4)", _grp(r"polka < 10 dni zuzycia: \d+ z \d+ \(mediana [^)]*\)", fo[last]), "INFO (stan wyjsciowy B4)", None)
    sa_ = by_day(lines, "Zadowolenie BK (E5/0): dzien")
    if last in sa_:
        rep.add("E50-T9: zadowolenie BK (R14)", _grp(r"srednie Food / Industrial / General / Luxury \(0\.\.1\) [^|]+", sa_[last])[:220], "INFO", None)
    if sess:
        rep.add("E50-T9: modele czynne (lojalnosc BK, warstwa BK)", _grp(r"modele czynne: (.*?) \| zapasy startowe", sess[-1], 1)[:300], "INFO (RB 7 pkt 2 i 4)", None)
    if last in gw:
        rep.add("E50-T9: gotowka wsi wedlug polityki BK (ostatnia doba)", _grp(r"wedlug polityki BK: (.*?) \| kontrola podzialu", gw[last], 1)[:300], "INFO (wiaze B1, C3)", None)
    # ---- T10 zapis: linia sesji po wczytaniu, kalibracja od nowa, 0 bledow
    loads = [s for s in sess if (num(r"sesja od dnia (\d+)", s, int, None) or start) - start + 1 > 2]
    if loads:
        rep.add("E50-T10: zapis - linia sesji po wczytaniu, 0 bledow", f"sesji z zapisu {len(loads)}, ERROR in TownFolk {len(errs)}", "linia sesji, 0 bledow", len(errs) == 0)
    else:
        rep.add("E50-T10: zapis (9 dob)", "bieg nowej kampanii - prog z biegu z zapisu", "INFO", None)

def etap5_a1(rep, lines, start, until, logp):
    """E5/A1 (111', kasy miast; plan kodu docs/etap5/PLAN-KODU-E5A1.md rozdz. 9.1, progi A1-T1..T22). Stan A1 - z dopisku dziennego w linii
    "Kasy miast (169c)" (" | E5/A1: ..."), nie z linii startowej (ta powstaje przed MCM). Okno: doby kampanii 2-until (doba 1 = dar startowy
    i pierwsze ticki); sr28 = ostatnie 28 dob okna. Dzien linii ksiegi (169c, Przeplywy, Zawor zamkow, przyczyny, Towary) = dzien gry - 1;
    linie z dniem gry (Korona 165, Budzet rodow 166) przesuniete o 1."""
    k169 = by_day(lines, "Kasy miast (169c): dzien")
    pt = by_day(lines, "Przeplywy osad (kasy miast): dzien")
    pz = by_day(lines, "Przeplywy osad (kasy zamkow): dzien")
    pv = by_day(lines, "Przeplywy osad: dzien")
    zz = by_day(lines, "Zawor zamkow (110): dzien")
    cau = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    tow = by_day(lines, "Towary (utarg wozow): dzien")
    e50 = by_day(lines, "Nadwyzka kas (E5/0): dzien")
    kor = e4_series(lines, "Korona: wplywy dnia (165): dzien", 1)
    bud = e4_series(lines, "Budzet rodow (166): dzien", 1)
    win = [d for d in sorted(k169) if 2 <= run_day(d, start) <= until]
    last28 = win[-28:]
    seg = {}
    for d in win:
        s = k169[d]
        i = s.find(" | E5/A1:")
        seg[d] = s[i:] if i >= 0 else None

    def vals(src, days, pat, cast=int):
        out = {}
        for d in days:
            s = src.get(d)
            if s is None:
                continue
            v = num(pat, s, cast)
            if v is not None:
                out[d] = v
        return out

    # ---------------- A1-T1: bledy i potkniecia
    errs = [s for s in lines if s.startswith("ERROR in ") and "TownPurse" in s]
    stum = vals(seg, win, r"\| potkniecia (\d+)")
    rep.add("E5/A1 A1-T1: bledy TownPurse (ERROR in) / potkniecia w biegu", f"{len(errs)} / {sum(stum.values())}", "0 bledow; potkniecia <= 5",
            len(errs) == 0 and sum(stum.values()) <= 5)

    # ---------------- A1-T2: linia startowa
    stl = next((s for s in lines if s.startswith("TownPurse (E5/A1): kasy miast jako")), None)
    if stl is None:
        rep.add("E5/A1 A1-T2: linia startowa", "brak", "jest, BRAK: -, modele >= 1, konsumpcja: tak", False)
    else:
        mod = num(r"w (\d+) modelach", stl, int, 0) or 0
        ok2 = "BRAK: -" in stl and mod >= 1 and "konsumpcja: tak" in stl
        rep.add("E5/A1 A1-T2: linia startowa", f"modele {mod}, konsumpcja {'tak' if 'konsumpcja: tak' in stl else 'BRAK'}, "
                + ("BRAK: -" if "BRAK: -" in stl else "BRAK: " + (re.search(r"BRAK: ([^|]*)", stl).group(1).strip() if re.search(r"BRAK: ([^|]*)", stl) else "?")),
                "BRAK: -, modele >= 1, konsumpcja: tak", ok2)

    # ---------------- A1-T3: tryb czynny kazdej doby
    modes = {}
    for d in win:
        s = seg.get(d)
        if s is None:
            continue
        m = num(r"E5/A1: tryb regulatora (\d)", s)
        if m is None:
            m = 0 if "E5/A1: WYLACZONE" in s else (-1 if "E5/A1: NIECZYNNE" in s else None)
        if m is not None:
            modes[d] = m
    miss3 = [d for d in win if d not in modes]
    mset = sorted(set(modes.values()))
    mode = mset[0] if len(mset) == 1 else (2 if 2 in mset else (mset[0] if mset else None))
    if not win:
        rep.add("E5/A1 A1-T3: tryb regulatora kazdej doby", "brak dob w oknie", "2 kazdej doby", None)
    elif len(mset) > 1 or miss3:
        rep.add("E5/A1 A1-T3: tryb regulatora kazdej doby", f"tryby {mset}, bez dopisku {len(miss3)} z {len(win)} dob", "jeden tryb caly bieg (2; zmiana w biegu = NIE)", False)
    elif mset == [2]:
        rep.add("E5/A1 A1-T3: tryb regulatora kazdej doby", f"2 w {len(win)} dobach", "2 kazdej doby (Jeff 16:10)", True)
    elif mset == [1]:
        rep.add("E5/A1 A1-T3: tryb regulatora kazdej doby", f"1 w {len(win)} dobach - bieg awaryjny", "2 (1 = bieg awaryjny: T6/T7 wedlug trybu 1)", None)
    else:
        rep.add("E5/A1 A1-T3: tryb regulatora kazdej doby", f"{mset[0]} w {len(win)} dobach ({'WYLACZONE' if mset[0] == 0 else 'NIECZYNNE - latki 110 BRAK'})",
                "2 (0 caly bieg = bieg porownawczy - progi INFO)", None if mset[0] == 0 else False)
    live = mode in (1, 2)

    def zero_each(name, src, pat, base, rule="0 kazdej doby okna"):
        v = vals(src, win, pat)
        bad = [d for d, x in v.items() if x != 0]
        if not v:
            rep.add(name, "brak linii", rule, None)
            return v
        rep.add(name, f"niezerowe w {len(bad)} z {len(v)} dob" + (f" (najwiecej {max(abs(v[d]) for d in bad)}, doba {run_day(bad[0], start)})" if bad else "") + f"; dzis (baza) {base}",
                rule, (len(bad) == 0) if live else None)
        return v

    # ---------------- A1-T4/T5/T6: kasy miast - "zakupy", kasowanie, dosypka
    zero_each("E5/A1 A1-T4: \"zakupy\" w kasach miast", pt, r'"zakupy" mieszkancow ([+-]?\d+)', "425 318 (L:31722)")
    zero_each("E5/A1 A1-T5: regulator kas miast - skasowal", pt, r"regulator kasy [+-]?\d+ \[P\] \(dosypal \d+, skasowal (\d+)", "248 065 (L:31686)")
    if mode == 1:
        dos = vals(pt, last28, r"regulator kasy [+-]?\d+ \[P\] \(dosypal (\d+), skasowal")
        m6 = st.mean(dos.values()) if dos else None
        rep.add("E5/A1 A1-T6: dosypka kas miast (tryb 1, sr28)", f"{m6:.0f}/d" if m6 is not None else "brak linii", "<= 35 000/d (2 x dzis 17 057); wiecej - DECYZJA",
                (m6 <= 35000) if m6 is not None else None, decide=True)
    else:
        zero_each("E5/A1 A1-T6: dosypka kas miast (tryb 2)", pt, r"regulator kasy [+-]?\d+ \[P\] \(dosypal (\d+), skasowal", "sr28 17 057")

    # ---------------- A1-T7: dosypka kas zamkow i linia 110 z "tryb 2"
    dz = vals(pz, win, r"dosypal (\d+), skasowal")
    zt2 = [d for d in win if d in zz and "dosypka zablokowana (tryb 2" in zz[d]]
    if not zz:
        rep.add("E5/A1 A1-T7: dosypka kas zamkow (tryb 2)", "brak linii Zawor zamkow (110) - Castle Purse Enabled wylaczone?", "tryb 2: dosypal 0, linia 110 z \"tryb 2\"", None)
    elif mode == 2:
        badz = [d for d, x in dz.items() if x != 0]
        rep.add("E5/A1 A1-T7: dosypka kas zamkow (tryb 2)", f"dosypal != 0 w {len(badz)} z {len(dz)} dob; linia 110 z \"tryb 2\" w {len(zt2)} z {len([d for d in win if d in zz])} dob",
                "dosypal 0 kazdej doby; linia 110 z \"dosypka zablokowana (tryb 2\"", len(badz) == 0 and len(zt2) == len([d for d in win if d in zz]))
    else:
        m7 = st.mean([dz[d] for d in last28 if d in dz]) if any(d in dz for d in last28) else None
        rep.add("E5/A1 A1-T7: dosypka kas zamkow", f"sr28 {m7:.0f}/d (tryb {mode})" if m7 is not None else "brak linii", "INFO poza trybem 2 (dzis ok. 1 tys./d)", None)

    # ---------------- A1-T8: zawor - suma i podzial
    vre = re.compile(r"zeszlo (\d+) = panom (\d+) \(przed dekretem (\d+); w krolestwach przed dekretem (\d+);.*?\+ koronie (\d+)")
    vz = {}
    for d in win:
        s = seg.get(d)
        m = vre.search(s) if s else None
        if m:
            vz[d] = [int(x) for x in m.groups()]
    off8 = [d for d in win if seg.get(d) and "zawor: NIE DZIALA" in seg[d]]
    # E5/B3 (Z15-5): udzial pana czynny dzis z linii "Wyrownanie panow zamkow (E5/B3)" (dzien gry; ten sam blok dobowy co 169c) - przy wyrownaniu 1/2;
    # doba bez linii B3 (log sprzed B3) - klucz 0.67. Oczekiwany udzial korony = srednia (1 - udzial pana) wazona podstawa LBk + K
    b3l = e4_series(lines, "Wyrownanie panow zamkow (E5/B3): dzien", 1)
    if vz:
        badsum = [d for d, v in vz.items() if v[0] != v[1] + v[4]]
        k28 = sum(vz[d][4] for d in last28 if d in vz)
        lbk28 = sum(vz[d][3] for d in last28 if d in vz)
        ratio = k28 / (lbk28 + k28) if lbk28 + k28 > 0 else None
        ew = en = 0.0
        nb3 = 0
        for d in last28:
            if d not in vz:
                continue
            sh = fnum(r"\| zawor kas miast \(A1 [^)]*\): panu ([\d.]+)%", b3l.get(d))
            if sh is not None:
                nb3 += 1
            base = vz[d][3] + vz[d][4]
            ew += (1.0 - (sh / 100.0 if sh is not None else 0.67)) * base
            en += base
        exp8 = ew / en if en > 0 else 0.33
        lo8, hi8 = exp8 - 0.01, exp8 + 0.01
        rule8 = (f"0 dob; {lo8:.2f}-{hi8:.2f} (1 - udzial pana z linii E5/B3 w {nb3} dobach sr28, poza nimi klucz 0.67)" if nb3
                 else "0 dob; 0.32-0.34 (1/3 - klucz 0.67)")
        rep.add("E5/A1 A1-T8: zawor D = L + K; udzial korony sr28 K / (LBk + K)",
                f"D != L + K w {len(badsum)} z {len(vz)} dob; udzial korony " + (f"{ratio:.3f}" if ratio is not None else "-") + (f"; NIE DZIALA w {len(off8)} dobach" if off8 else ""),
                rule8, len(badsum) == 0 and ratio is not None and lo8 <= ratio <= hi8 if live else None)
    else:
        rep.add("E5/A1 A1-T8: zawor D = L + K; udzial korony", "brak liczb zaworu" + (f" (NIE DZIALA w {len(off8)} dobach - Population Rent Enabled?)" if off8 else ""),
                "zawor czynny w biegu A", None if not live else False)

    # ---------------- A1-T9: "10 miast bez placenia"
    v9 = vals(seg, win, r"miast z nadwyzka bez zaworu \(10 miast\) (\d+)")
    bad9 = [d for d, x in v9.items() if x != 0]
    rep.add("E5/A1 A1-T9: \"10 miast bez placenia\"", f"niezerowe w {len(bad9)} z {len(v9)} dob" + (f" (najwiecej {max(v9[d] for d in bad9)})" if bad9 else "") if v9 else "brak liczb",
            "0 kazdej doby (dzis 10, RB 5.4)", (len(bad9) == 0) if (v9 and live) else None)

    # ---------------- A1-T10: tarcze
    held = vals(k169, win, r"pod tarcza zoldu \(zold i wydatki ludzi w drodze do pana\) (\d+)")
    badh = [d for d, x in held.items() if x != 0]
    court = [d for d in win if d in bud and (num(r"tarcza dworu wlaczona: znacznik (\d+)", bud[d], int, 0) or 0) > 0]
    rep.add("E5/A1 A1-T10: tarcze 107b/162m", f"znacznik zoldu != 0 w {len(badh)} z {len(held)} dob; znacznik dworu w 166 w {len(court)} dobach",
            "0 (dzis pod tarcza 2 863 805, L:31686)", (len(badh) == 0 and len(court) == 0) if live else None)

    # ---------------- A1-T11: BK rynek osady
    bk = vals(cau, last28, r"BK rynek osady ([+-]?\d+)")
    m11 = st.mean(bk.values()) if bk else None
    rep.add("E5/A1 A1-T11: BK rynek osady (sr28)", f"{m11:.0f}/d" if m11 is not None else "brak linii", "|x| <= 2 000/d (dzis -34 610 L:31718, sr28 -30 495)",
            (abs(m11) <= 2000) if (m11 is not None and live) else None)

    # ---------------- A1-T12: dar startowy (linia raz; dzien = najblizsza linia 169c po niej - ten sam blok)
    trims = []
    for i, s in enumerate(lines):
        if s.startswith("TownPurse (E5/A1):") and "dar startowy w kasach miast" in s and "zdjeto" in s:
            day = None
            for s2 in lines[i + 1:i + 4000]:
                if s2.startswith("Kasy miast (169c): dzien"):
                    day = num(r"dzien (\d+)", s2)
                    break
            trims.append((s, day))
    # diagnoza 2 (bieg zbiorczy 329f2c7): przy E5/B1 najpierw zapasy startowe kies ludu biora czesc daru (linia "Kiesa ludu (E5/B1): zapasy startowe z daru kas
    # miast"), reszta jest przycinana - prog 8-20 mln dotyczy calego daru ("dar do podzialu"), a zdjeto + zapasy = dar +-1. Przyciecie jest przed pierwsza migawka
    # ksiegi (bilans otwarcia) - brak ujscia w przyczynach pierwszej doby to nie blad
    seed_b1 = None
    for s0 in lines:
        if s0.startswith("Kiesa ludu (E5/B1): zapasy startowe z daru kas miast"):
            m0 = re.search(r"= (\d+) \(miast \d+, zamkow \d+; dar do podzialu (\d+)", s0)
            if m0:
                seed_b1 = (int(m0.group(1)), int(m0.group(2)))
            break
    if not trims:
        rep.add("E5/A1 A1-T12: dar startowy", "brak linii przyciecia", "nowa kampania: 1 linia, zdjeto 8-20 mln; zapis z doby 362: przyciecie 0", None)
    else:
        for s, day in trims:
            cut = num(r"zdjeto (\d+)", s, int, 0) or 0
            old = "zapis z" in s or "przyciecie wlaczone" in s
            sink = num(r"dar startowy kas miast przyciety \(E5/A1\) (\d+)", cau.get(day, "")) if day is not None else None
            if old:
                rep.add("E5/A1 A1-T12: dar startowy (stary zapis)", f"zdjeto {cut}", "0 (0.75^wiek)", cut == 0)
            elif seed_b1 is not None:
                seed, dar = seed_b1
                okc = 8000000 <= dar <= 20000000 and abs(cut + seed - dar) <= 1
                rep.add("E5/A1 A1-T12: dar startowy (nowa kampania, z E5/B1)",
                        f"dar do podzialu {dar} = zapasy startowe kies ludu {seed} + zdjeto {cut} (roznica {cut + seed - dar:+d})"
                        + (f"; ujscie {sink}" if sink is not None else "; ujscie: bilans otwarcia przed pierwsza migawka ksiegi (bez linii przyczyn)"),
                        "dar do podzialu 8-20 mln ([S] ok. 14 mln); zdjeto + zapasy = dar +-1; ujscie = zdjeto +-1 albo bilans otwarcia",
                        okc and (sink is None or abs(sink - cut) <= 1))
            else:
                okc = 8000000 <= cut <= 20000000
                if sink is None:
                    rep.add("E5/A1 A1-T12: dar startowy (nowa kampania)", f"zdjeto {cut}; ujscie w przyczynach: brak (pierwsza doba ksiegi bez linii)",
                            "zdjeto 8-20 mln ([S] ok. 14 mln); ujscie = zdjeto +-1", okc)
                else:
                    rep.add("E5/A1 A1-T12: dar startowy (nowa kampania)", f"zdjeto {cut}, ujscie {sink}", "zdjeto 8-20 mln ([S] ok. 14 mln); ujscie = zdjeto +-1",
                            okc and abs(sink - cut) <= 1)
        if len(trims) > 1:
            rep.add("E5/A1 A1-T12: linie przyciecia w logu", len(trims), "1 na kampanie (kolejne sesje: flaga arm_townpurse)", None)

    # ---------------- A1-T13: reszta ksiegi
    r28 = vals(cau, win, r"srednia 28 dob ([+-]?\d+)")
    if r28:
        dl = sorted(r28)[-1]
        rep.add("E5/A1 A1-T13: reszta ksiegi R (srednia 28 dob, ostatnia doba)", f"{r28[dl]} (doba {run_day(dl, start)})", "|R| < 10 000 (etap 3; dzis sr28 -1 302)", abs(r28[dl]) < 10000)
    else:
        rep.add("E5/A1 A1-T13: reszta ksiegi R", "brak linii", "|R| < 10 000", None)

    # ---------------- A1-T14: nasze zakupy z pasa ponizej zapasu
    # poprawka po recenzji: E5/0 liczy jako "nasze sciezki" kazda ujemna kwote kasy miasta z MoneyLedger.Note/Note169 - takze sciezki swiadomie
    # bez BuyFloor (likwidacja RecruitKit, zwrot 171 GarrisonCarts, zwrot dokupu BK CaravanBulk, wedrowcy 36b). Prog 0 (NIE) tylko, gdy linia E5/0
    # podaje je osobno ("zwroty i likwidacje" - do dopisania przy scaleniu, CHANGELOG A1 "Scalanie"); bez rozbicia - INFO
    v14 = vals(e50, win, r"nasze sciezki (\d+)")
    if v14:
        b14 = [d for d, x in v14.items() if x != 0]
        split14 = any("zwroty i likwidacje" in (e50.get(d) or "") for d in v14)
        if split14:
            # narzedzie progow zb58 (TRIAZ A1-T14, wariant bez DLL): sonda liczy "ponizej zapasu" z Seal31.TownReserve (mnozenie w float), a BuyFloor /
            # Seal31.Spare z TownPurse.Reserve (double) - rozjazd zaokraglen 1 zl w ok. 0.2-0.4% miasto-dob; kapital karawany notabla zbija kase
            # dokladnie do Reserve, sonda mierzy wobec Reserve + 1. Prawdziwy zakup ponizej BuyFloor to dziesiatki zl - doba liczona dopiero ponad 2 zl.
            r14 = [d for d, x in v14.items() if 0 < x <= 2]
            b14 = [d for d, x in v14.items() if x > 2]
            rep.add("E5/A1 A1-T14: nasze zakupy kas miast ponizej zapasu (E5/0, bez zwrotow i likwidacji)",
                    f"ponad 2 zl w {len(b14)} z {len(v14)} dob (suma okna {sum(v14.values())} zl; doby z 1-2 zl: {len(r14)} - rozjazd zaokraglen zapasu kupcow float/double)",
                    "0 dob ponad 2 zl (BuyFloor)", (len(b14) == 0) if live else None)
        else:
            rep.add("E5/A1 A1-T14: nasze sciezki kas miast ponizej zapasu (E5/0 bez rozbicia)", f"niezerowe w {len(b14)} z {len(v14)} dob, suma {sum(v14.values())}",
                    "INFO - E5/0 liczy tu tez sciezki bez BuyFloor (RecruitKit, zwrot 171, zwrot CaravanBulk, wedrowcy 36b); 0 (NIE) po rozbiciu przy scaleniu", None)
    else:
        q = vals(seg, win, r"zapytan (\d+), przy zapasie \(0\)")
        z = vals(seg, win, r"zapytan \d+, przy zapasie \(0\) (\d+)")
        rep.add("E5/A1 A1-T14: nasze zakupy kas miast ponizej zapasu", f"bez linii E5/0; zapytan {sum(q.values())}, przy zapasie (0) {sum(z.values())}",
                "INFO (z budowy: BuyFloor) - 0 z linii E5/0 po scaleniu", None)

    # ---------------- A1-T15/T17: stan ustalony kas i zawor razem
    sp = vals(seg, last28, r"\| zapas kupcow \d+, ponad zapasem (\d+)")
    d28 = [vz[d][0] for d in last28 if d in vz]
    if sp and d28:
        m15 = st.mean(sp.values()); m17 = st.mean(d28)
        rep.add("E5/A1 A1-T15: kasy ponad zapasem wobec zawor / 0.07 (sr28)", f"{m15:.0f} wobec {m17 / 0.07:.0f} (stosunek {m15 / (m17 / 0.07):.2f})" if m17 > 0 else f"{m15:.0f}",
                "INFO (ok. 1 = stan ustalony; P111)", None)
        rep.add("E5/A1 A1-T17: zawor razem (sr28)", f"{m17:.0f}/d", "INFO 250-550 tys./d ([S] ok. 381 tys. = panom 254 + koronie 127; renta dzis 487 312)", None)
    else:
        rep.add("E5/A1 A1-T15/T17: stan kas i zawor (sr28)", "brak liczb", "INFO", None)

    # ---------------- A1-T16: korona (165)
    k16 = vals(kor, last28, r"prawa trzecich \(178\) (\d+)")
    rep.add("E5/A1 A1-T16: korona - wplywy \"nasze\" (165, sr28)", f"{st.mean(k16.values()):.0f}/d" if k16 else "brak linii",
            "INFO (w wojnie >= bieg bazowy - prog B2; dzis 256 287/d)", None)

    # ---------------- A1-T18: rody
    rep.add("E5/A1 A1-T18: rody (glowy, bankruci, wojsko)", "--grupa etap2 na tym samym logu", "progi etapu 2 ([S] rody ok. -89 tys./d bez A3)", None)

    # ---------------- A1-T19/T21: zakup plonu i zaulki (Jeff 16:10)
    uns = vals(pv, win, r"towar niesprzedany po wizycie: w miastach (\d+) szt")
    sold = vals(tow, win, r"za (\d+) szt\.")
    su, ss = sum(uns.values()), sum(sold.values())
    share = (100.0 * su / ss) if ss > 0 else None
    rep.add("E5/A1 A1-T19: towar wsi niesprzedany w miastach", f"{su} szt. wobec sprzedanych {ss} ({share:.3f}%)" if share is not None else f"{su} szt. (brak linii Towary (utarg wozow))",
            "< 0.1% (dzis 0 szt.)", (share < 0.1) if (share is not None and live) else None)
    zre = re.compile(r"zaulki: kas ponizej zapasu (\d+), ponizej 1000 (\d+), przy 0 (\d+); najdluzej ponizej zapasu (\d+) dob")
    zl = {}
    for d in win:
        s = seg.get(d)
        m = zre.search(s) if s else None
        if m:
            zl[d] = [int(x) for x in m.groups()]
    w7 = vals(seg, win, r"miast >= 7 dob (\d+)")
    if zl:
        zero_days = [d for d, v in zl.items() if v[2] > 0]
        dl = sorted(zl)[-1]
        ok21 = len(zero_days) == 0 and (share is None or share <= 0.1)
        rep.add("E5/A1 A1-T21: zaulki (Jeff 16:10)", f"kasy przy 0 w {len(zero_days)} dobach; ostatnia doba: ponizej zapasu {zl[dl][0]}, ponizej 1000 {zl[dl][1]}, przy 0 {zl[dl][2]},"
                f" najdluzsza seria {max(v[3] for v in zl.values())} dob, miast >= 7 dob {w7.get(dl, '-')}; towar niesprzedany " + (f"{share:.3f}%" if share is not None else "-"),
                "kasy przy 0: 0 kazdej doby; towar wsi niesprzedany <= 0.1% (serie > 7 dob z towarem niesprzedanym w tym samym miescie - bez licznika na miasto, INFO);"
                " przekroczenie -> bieg z Town Purse Regulator 1 i raport dla Jeffa (dzis 15 z 97 ponizej celu)", ok21 if live else None)
    else:
        rep.add("E5/A1 A1-T21: zaulki", "brak liczb", "jw.", None)

    # ---------------- A1-T22: udzial zysku kupcow (INFO)
    u = {}
    for d in win:
        s = seg.get(d)
        m = re.search(r"udzial zysku kupcow .*? dzis (-|[\d.]+)%.*?srednia 28 dob (-|[\d.]+)%", s) if s else None
        if m:
            u[d] = m.groups()
    if u:
        dl = sorted(u)[-1]
        dv = [float(x[0]) for x in u.values() if x[0] != "-"]
        rep.add("E5/A1 A1-T22: udzial zysku kupcow zabierany przez pana i korone", f"srednia 28 dob {u[dl][1]}% (ostatnia doba); srednia dziennych {st.mean(dv):.1f}%" if dv else f"srednia 28 dob {u[dl][1]}%",
                "INFO (odniesienie historyczne ok. 10%; decyzja Jeffa po tescie)", None)
    else:
        rep.add("E5/A1 A1-T22: udzial zysku kupcow", "brak liczb", "INFO", None)

    # ---------------- A1-T20: zakupy dla nas - towar zostaje u sprzedajacych (INFO wobec biegu bazowego)
    # poprawka po recenzji: wedrowcy 36b bez BuyFloor (reszta ladunku szlaby na polke celu bez zaplaty); doszly warsztaty zbrojne (WorkshopLaw - "brak zlota/kupca")
    names = ("Paser: dzien", "Kontrakty surowca (174): dzien", "Karawany bez amunicji (172b): dzien", "Warsztaty: dzien")
    have = [n.split(":")[0] for n in names if any(s.startswith(n) for s in lines)]
    q = vals(seg, win, r"zapytan (\d+), przy zapasie \(0\)")
    z = vals(seg, win, r"zapytan \d+, przy zapasie \(0\) (\d+)")
    wsk = vals(by_day(lines, "Warsztaty: dzien"), win, r"brak zlota/kupca (\d+)")
    rep.add("E5/A1 A1-T20: zakupy dla nas - towar u sprzedajacych", f"linie: {', '.join(have) if have else '-'}; BuyFloor: zapytan {sum(q.values())}, przy zapasie (0) {sum(z.values())}"
            + (f"; warsztaty zbrojne - brak zlota/kupca sr {st.mean(wsk.values()):.1f}/d (baza z31-A 0 kazdej doby)" if wsk else ""),
            "INFO wobec biegu bazowego (liczniki \"brak kasy miasta\"); skok x3 -> wylaczyc Town Pays From Surplus i powtorzyc", None)
def etap5_a2(rep, lines, start, until, logp, bud):
    """E5/A2 (162, PLAN 5.2 - dwor pelny, R8): projekt rozdz. 3 "E5/A2" Test: dwor rosnie o przelew ze sprzetu, nic w nicosc, gracz bez dworu,
    D staly bez zmian definicji; ryzyko (rozdz. 3): wiecej zlota do kas siedzib - udzial panow zamkow (prog B3) jako INFO. Przelew zaczyna sie
    po AiGearDaysCap (30) dobach od startu kampanii (przydzial musi dojsc do pulapu) - progi przelewu w dobach 31-until.
    Recenzja A2 (uwaga 1): A2-10/A2-11 - sprzet wplacony do kasy WLASNEJ siedziby wraca jako "wlasne" (zapas w dopisku linii "D staly (169c)")."""
    obg = by_day(lines, "Obieg: dzien")
    cau = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    win = [d for d in sorted(bud) if 1 <= run_day(d, start) <= until]
    late = [d for d in win if run_day(d, start) >= 31]
    a2re = re.compile(r"-> dwor \(E5/A2\): przeterminowane dzis (\d+) u (\d+) rodow, wplacone do kas siedzib (\d+) u (\d+) rodow \(miasta (\d+) / zamki (\d+)\)"
                      r"; zostalo w kiesie glowy: ponizej rezerwy rodu \(wojna R, pokoj \d+ D\) (\d+), ustapilo zoldowi (\d+), kiesa glowy \(zold dnia, podloga\) (\d+)"
                      r", dluznicy \(polowa\) (\d+), najemnicy bez dworu (\d+), bez siedziby (\d+); udzial ludu \(hak B1\) (\d+)%")
    obre = re.compile(r"dwor \(166/162m\) do kas siedzib (\d+) \(w tym miasta pod tarcza dworu (\d+), zamki (\d+); w tym sprzet niewydany -> dwor \(E5/A2\) (\d+)"
                      r": miasta (\d+) / zamki (\d+)\)")
    rows = {}
    for d in win:
        m = a2re.search(bud[d])
        if m:
            rows[d] = [int(x) for x in m.groups()]
    off = [d for d in win if "-> dwor (E5/A2): wylaczone" in bud[d]]
    miss = [d for d in win if d not in rows and d not in off]
    rep.add("E5/A2 A2-1: linia sprzetu niewydanego codziennie", f"brak/nieczytelna w {len(miss)} z {len(win)} dob" + (f", wylaczone w {len(off)}" if off else ""),
            "0 (dopisek linii Budzet rodow (166))", len(miss) == 0 if win else None)
    if off:
        rep.add("E5/A2 A2-2: paczka czynna", f"wylaczone w {len(off)} dobach (Court Gets Lapsed Arms Share / Household Minimal)", "czynna w biegu zbioru A - progi przelewu INFO", None)

    def mean_late(i):
        v = [rows[d][i] for d in late if d in rows]
        return st.mean(v) if v else None
    paid = mean_late(2)
    rep.add("E5/A2 A2-3: sprzet niewydany -> dwor (srednia dob 31-%d)" % until,
            f"{paid:.0f}/d (przeterminowane {mean_late(0):.0f}/d u {mean_late(1):.0f} rodow; miasta {mean_late(4):.0f} / zamki {mean_late(5):.0f})" if paid is not None else "brak dob >= 31",
            "> 0 (bieg z31-A: przydzial 516 615 wobec 35 155 wydanych w d120 - oczekiwane ok. 300-480 tys./d [S])", (paid > 0) if (paid is not None and not off) else None)
    # A2-4: dwor rosnie o przelew - ta sama liczba w linii 166 i w Obiegu tej doby; dwor razem >= sprzet; miasta + zamki = sprzet
    bad, noobg = [], 0
    for d in win:
        if d not in rows:
            continue
        if d not in obg:   # pierwsza doba sesji: ksiega pisze sam stan, bez linii "Obieg"
            noobg += 1
            continue
        r = rows[d]
        tot = num(r"dwor \(162m\): wplacone do kas siedzib (\d+)", bud[d])
        o = obre.search(obg[d])
        ok = (tot is not None and tot >= r[2] and r[4] + r[5] == r[2] and o is not None and int(o.group(4)) == r[2] and int(o.group(1)) == tot
              and int(o.group(5)) == r[4] and int(o.group(6)) == r[5])
        if not ok:
            bad.append(run_day(d, start))
    rep.add("E5/A2 A2-4: dwor rosnie o przelew ze sprzetu (166 = Obieg, dwor >= sprzet, miasta + zamki)",
            f"niezgodne {len(bad)} z {len(rows) - noobg} dob" + (f" (doby {bad[:6]})" if bad else "") + (f"; bez linii Obieg {noobg} (pierwsza doba sesji)" if noobg else ""),
            "0", (len(bad) == 0) if len(rows) > noobg else None)
    # A2-5: nic w nicosc - reszta ksiegi pieniadza (przelew glowa -> kasa siedziby w naszym ticku, pozycja MBudget)
    cd = [d for d in sorted(cau) if 1 <= run_day(d, start) <= until]
    rv = num(r"srednia 28 dob ([+-]?\d+)", cau[cd[-1]]) if cd else None
    rep.add("E5/A2 A2-5: nic w nicosc - reszta ksiegi R (srednia 28 dob, ostatnia doba okna)", f"{rv}" if rv is not None else "brak linii", "|R| < 10 000 (prog etapu 3; --grupa etap3)",
            (abs(rv) < 10000) if rv is not None else None)
    # A2-6: glowy rodow < 5 000 (przelew z kiesy glowy najwyzej do podlogi rodziny) - warunek etapu 2
    heads = [num(r"glowy < 5000 \(rody z budzetem\): (\d+)", bud[d]) for d in win]
    heads = [x for x in heads if x is not None]
    rep.add("E5/A2 A2-6: glowy rodow < 5 000 (najwiecej w oknie)", f"{max(heads)}" if heads else "brak linii", "<= 10 (warunek etapu 2)", (max(heads) <= 10) if heads else None)
    # A2-7: hak B1 = 0 do kiesy ludu; A2-8: gracz bez dworu (Eligible - gracz bez budzetu; linia 166 to wypisuje)
    folk = [rows[d][12] for d in rows]
    b1 = any(x.startswith("Kiesa ludu (E5/B1): CZYNNA") for x in lines)   # E5/B1: hak czynny - CourtFolkShare (20%) przy kiesie czynnej
    if b1:
        rep.add("E5/A2 A2-7: udzial ludu w dworze (hak B1)", f"najmniej {min(folk)}%, najwiecej {max(folk)}%" if folk else "brak",
                "E5/B1 czynne: Court Folk Share (domyslnie 20%) w dobach kiesy czynnej (INFO - 0% w dobach przed CZYNNA)", None)
    else:
        rep.add("E5/A2 A2-7: udzial ludu w dworze (hak B1)", f"najwiecej {max(folk)}%" if folk else "brak", "0% do B1 (TownFolkLive)", (max(folk) == 0) if folk else None)
    pl = sum(1 for d in win if "gracz - bez budzetu" in bud[d])
    rep.add("E5/A2 A2-8: gracz bez dworu", f"linia 'gracz - bez budzetu' w {pl} z {len(win)} dob", "kazda doba ([D] 08.10)", (pl == len(win)) if win else None)
    # A2-9: bledy i potkniecia paczki (licznik potkniec - na sesje)
    errs = [s for s in lines if s.startswith("ERROR in ") and "CourtFull" in s]
    stum = max([num(r"potkniecia E5/A2 (\d+)", bud[d], int, 0) or 0 for d in win] or [0])
    rep.add("E5/A2 A2-9: bledy CourtFull / potkniecia E5/A2", f"bledy {len(errs)}, potkniecia {stum}", "0 / 0", len(errs) == 0 and stum == 0)
    # A2-10 / A2-11 (recenzja A2, uwaga 1): sprzet wplacony do kasy WLASNEJ siedziby wraca zaworem jako "wlasne", nie "ziemia" (zapas CourtFull.Own/OwnBack,
    # dopisek linii "D staly (169c)"): zapas zamyka sie z doby na dobe (zapas = wczoraj zapas + wczoraj wplacone - wrocilo - korona i danina - ponad zawor
    # - przyciete - utracone) i po zbudowaniu zapasu (doby 45-until) wraca > 0 jako "wlasne". Recenzja E5/A5: wplaty gracza do kasy wlasnej osady
    # (akcja z menu, poza blokiem doby) wchodza do zapasu przy najblizszej dobie - linia tej doby podaje je osobno ("wplaty gracza ... od wczorajszej linii")
    sdl = by_day(lines, "D staly (169c): dzien")
    owre = re.compile(r"\[E5/A2 zapas wlasny[^\]]*?: wrocilo dzis (\d+), do korony i daniny (\d+), ponad zawor dnia (\d+), przyciete \(osada wydala\) (\d+)"
                      r", utracone \(nowy pan\) (\d+), zapas (\d+) w (\d+) osadach, wplacone dzis (\d+)")
    owlate = re.compile(r"wplaty gracza do kasy wlasnej osady \(E5/A5\) od wczorajszej linii (\d+)")
    # E5 A2b (decyzja 5 Jeffa 12.10): wplaty rodow (NoteOwnPaid) poza blokiem doby wchodza do zapasu tak samo jak wplaty gracza
    owlate2 = re.compile(r"wplaty rodow do kas wlasnych osad poza blokiem doby \(A2b\) od wczorajszej linii (\d+)")
    ow = {}
    for d in sorted(sdl):
        if 1 <= run_day(d, start) <= until:
            m = owre.search(sdl[d])
            if m:
                ow[d] = [int(x) for x in m.groups()] + [(num(owlate, sdl[d], int, 0) or 0) + (num(owlate2, sdl[d], int, 0) or 0)]
    if not ow:
        rep.add("E5/A2 A2-10: zapas wlasny (sprzet do wlasnej siedziby) w linii D staly (169c)", "brak dopisku",
                "jest przy czynnej paczce i D stalym (Clan Income Book Stable D)", False if (rows and not off and sdl) else None)
    else:
        bad, pairs, resets = [], 0, 0
        for d in sorted(ow):
            if d - 1 not in ow:
                continue
            y0, r = ow[d - 1], ow[d]
            outs = r[0] + r[1] + r[2] + r[3] + r[4]
            pin = r[8]   # (diagnoza 5: nie "late" - nadpisywalo liste dob mean_late) recenzja E5/A5: wplaty gracza od wczorajszej linii (w zapasie od dzis); E5 A2b: + wplaty rodow spoza bloku doby
            exp = y0[5] + y0[7] + pin - outs
            # wczytanie zapisu w tej samej sesji (Reset) - zapas od zera (najwyzej wplaty gracza po wczytaniu, przed doba)
            if abs(r[5] + outs - pin) <= 5 and (y0[5] > 0 or y0[7] > 0) and abs(r[5] - exp) > 5 + max(0, y0[6] - r[6]):
                resets += 1
                continue
            pairs += 1
            if abs(r[5] - exp) > 5 + max(0, y0[6] - r[6]):   # zaokraglenia 7 liczb linii + reszta < 1 zl kazdej osady, ktora wyszla z zapasu
                bad.append(run_day(d, start))
        rep.add("E5/A2 A2-10: zapas wlasny zamyka sie z doby na dobe (zapas = wczoraj zapas + wplacone - wrocilo - korona - ponad zawor - przyciete - utracone)",
                f"niezgodne {len(bad)} z {pairs} par dob" + (f" (doby {bad[:6]})" if bad else "") + (f"; wczytania (zapas od zera) {resets}" if resets else ""),
                "0 (tolerancja 5 zl + 1 zl na osade, ktora wyszla z zapasu)", (len(bad) == 0) if pairs else None)
        lw = [d for d in ow if run_day(d, start) >= 45]
        if lw:
            back = st.mean(ow[d][0] for d in lw); inn = st.mean(ow[d][7] for d in lw)
            stock = ow[max(lw)][5]
            rep.add("E5/A2 A2-11: sprzet do wlasnych siedzib wraca jako wlasne (srednia dob 45-%d)" % until,
                    f"wrocilo jako wlasne {back:.0f}/d, wplacone do wlasnych siedzib {inn:.0f}/d, zapas na koncu {stock} w {ow[max(lw)][6]} osadach",
                    "> 0, gdy wplacone > 0 (inaczej zwrot wlasnego zlota szedlby do D stalego jako ziemia)", (back > 0) if inn > 0 else None)
            crown = st.mean(ow[d][1] for d in lw); cap = st.mean(ow[d][2] for d in lw); trim = st.mean(ow[d][3] for d in lw); lost = st.mean(ow[d][4] for d in lw)
            share = (100.0 * inn / paid) if paid else 0.0
            rep.add("E5/A2 INFO: zapas wlasny - odplywy poza wlasne i udzial wlasnych siedzib w przelewie (srednia dob 45-%d)" % until,
                    f"korona i danina {crown:.0f}, ponad zawor dnia {cap:.0f}, przyciete {trim:.0f}, utracone {lost:.0f}; do wlasnych siedzib {share:.0f}% przelewu sprzetu",
                    "INFO (recenzja A2: ok. 93% przelewu do wlasnych siedzib - budzet-rodow.csv z31-A d120; zamek 1/3 do korony)", None)
    # E5 A2b (decyzja 5 Jeffa 12.10, "najwyzej wojsko spadnie, trudno"): skala zmiany D stalego - zwrot wplat rodu do kas wlasnych osad jako wlasne
    # wobec starej reguly (ulamek zaworu jednej doby); roznica to tyle mniej "ziemi" na dobe (pierscienie D stalego - 28 dob)
    a2re = re.compile(r"A2b \(Own Payments Back As Own (\w+)[^)]*\): wrocilo jako wlasne (-?\d+) \(w tym zold zalog (-?\d+)\), po staremu \(ulamek jednej doby\) (-?\d+)"
                      r" -> ziemia dzis mniej o ok\. (-?\d+), w zapasie (-?\d+)")
    a2 = {d: a2re.search(sdl[d]) for d in sdl if 31 <= run_day(d, start) <= until}
    a2 = {d: m for d, m in a2.items() if m}
    if a2:
        on = any(m.group(1) == "on" for m in a2.values())
        bk = st.mean(int(m.group(2)) for m in a2.values()); wg = st.mean(int(m.group(3)) for m in a2.values())
        od = st.mean(int(m.group(4)) for m in a2.values()); dl = st.mean(int(m.group(5)) for m in a2.values())
        last = a2[max(a2)]
        rep.add("E5 A2b INFO: zwrot wplat rodow do kas wlasnych osad jako wlasne (srednia dob 31-%d)" % until,
                f"{'czynne' if on else 'WYLACZONE'}: wrocilo jako wlasne {bk:.0f}/d (zold zalog {wg:.0f}), po staremu {od:.0f}/d -> ziemia mniej o {dl:.0f}/d; zapas na koncu {last.group(6)}",
                "INFO - skala zmiany D stalego (porownaj 'ziemia' i D staly mediana z biegiem bez A2b)", None)
    # INFO: co zostalo w kiesie glowy i dwor bez sprzetu (srednie dob 31-until)
    if late and rows and paid is not None:
        rep.add("E5/A2 INFO: zostalo w kiesie glowy (srednia dob 31-%d)" % until,
                f"ponizej rezerwy {mean_late(6):.0f}, ustapilo zoldowi {mean_late(7):.0f}, kiesa glowy (zold dnia) {mean_late(8):.0f}, dluznicy {mean_late(9):.0f}"
                f", najemnicy {mean_late(10):.0f}, bez siedziby {mean_late(11):.0f}",
                "INFO (regula R8: rezerwa rodu, zold w wojnie, zold dnia w kiesie glowy)", None)
        cv = [num(r"dwor \(162m\): wplacone do kas siedzib (\d+)", bud[d]) for d in late]
        cv = [x for x in cv if x is not None]
        if cv:
            rep.add("E5/A2 INFO: dwor razem / sam dwor (srednia dob 31-%d)" % until, f"{st.mean(cv):.0f} / {st.mean(cv) - paid:.0f}",
                    "INFO (bieg z31-A bez A2: dwor 175-190 tys./d w dobach 31-120, L:31679)", None)
    # INFO (ryzyko - prog B3): udzial panow samych zamkow w D stalym i mediana kies ich glow (budzet-rodow.csv, rodzaj=zamek; wzor e5A/csv.py)
    rws = read_csv(csv_path_of(logp))
    if rws:
        byd = {}
        for x in rws:
            try:
                dz = int(x["dzien"])
            except (ValueError, KeyError, TypeError):
                continue
            if 1 <= run_day(dz, start) <= until:
                byd.setdefault(dz, []).append(x)
        ser = []
        for dz in sorted(byd):
            tot = zam = 0.0
            kies = []
            for x in byd[dz]:
                try:
                    v = float(x.get("d_staly") or "nan")
                except ValueError:
                    continue
                if v != v:
                    continue
                tot += v
                if x.get("rodzaj") == "zamek":
                    zam += v
                    try:
                        kies.append(float(x.get("kiesa_glowy")))
                    except (TypeError, ValueError):
                        pass
            ser.append((dz, zam / tot if tot else 0.0, st.median(kies) if kies else 0.0))
        w = ser[-28:]
        if w:
            ch = (w[-1][2] / w[0][2] - 1) * 100 if w[0][2] else 0.0
            rep.add("E5/A2 INFO: panowie samych zamkow - udzial w d_staly, mediana kiesy glowy (ostatnie 28 dob okna)",
                    f"{st.mean(x[1] for x in w) * 100:.1f}%; mediana {w[0][2]:.0f} -> {w[-1][2]:.0f} ({ch:+.1f}%)",
                    "INFO - ryzyko A2 (wiekszy zawor kas siedzib); prog w B3; bieg z31-A d93-120: 24.3%, -2.5%", None)
    else:
        rep.add("E5/A2 INFO: panowie samych zamkow (budzet-rodow.csv)", "brak pliku CSV", "INFO", None)


def etap5_a3(rep, lines, start, until, mar, nob):
    """E5/A3 (163 + 164c, PLAN 5.3 - markietani R9, notable R10): projekt rozdz. 3 "E5/A3" Test i rozdz. 4 (sakiewki <= 15 dni zoldu).
    Linie: "Markietani (E5/A3): dzien N" (dzien gry - jak 166; mar ma klucz = dzien ksiegi), "Notable (E5/A3): dzien N" (dzien ksiegi), "Obieg: dzien"
    (sakiewki, zold), "Obieg: notable i karawany" (pasmo, nowi notable, karawany), "Pieniadz swiata (bilans - przyczyny)" (korekta zrodel E5/A3).
    Doba 1 kampanii to sam stan ksiegi (bez Obiegu) - progi przeplywow od doby 2."""
    obg = by_day(lines, "Obieg: dzien")
    onk = by_day(lines, "Obieg: notable i karawany: dzien")
    cau = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    mwin = [d for d in sorted(mar) if 1 <= run_day(d, start) <= until]
    mre = re.compile(r"stawka ([\d.]+)% \(pelna ([\d.]+)%; ([^)]*)\) \| w polu (\d+) partii, wydaly (\d+): z sakiewek (\d+) \(gracz (\d+)\) -> kasy miast (\d+) w (\d+) miastach"
                     r" \(([\d.]+)%\), kiesy wsi (\d+) w (\d+) wsiach \| we wlasnych miastach rodow \(K3\) (\d+) \| bez niewrogiego miasta -> najblizsze miasto (\d+) partii \((\d+)\)"
                     r" \| bez niewrogiej wsi w stanie Normal -> miasto (\d+) partii \((\d+)\)")
    rows, off = {}, []
    for d in mwin:
        s = mar[d]
        if "| wylaczone (Sutlers Enabled" in s:
            off.append(d)
            continue
        m = mre.search(s)
        if m:
            g = m.groups()
            rows[d] = {"rate": float(g[0]), "full": float(g[1]), "ramp": g[2], "n": int(g[3]), "paid": int(g[4]), "tot": int(g[5]), "pl": int(g[6]),
                       "town": int(g[7]), "towns": int(g[8]), "vill": int(g[10]), "vills": int(g[11]), "k3": int(g[12]), "nt": int(g[13]), "ntg": int(g[14]),
                       "nv": int(g[15]), "nvg": int(g[16]), "ms": num(r"koszt ([\d.]+) ms", s, float, 0.0) or 0.0,
                       "days": num(r"sakiewki partii rodow \d+ = ([\d.]+) dni zoldu", s, float),
                       "kdays": num(r"w tym oszczednosci K1 \d+ = ([\d.]+) dni", s, float),
                       "ks": num(r"w tym oszczednosci K1 (\d+) = ", s, int), "kk": num(r"rezerwy: naprawy i odziez \d+, oszczednosci K1 (\d+)", s, int)}
    miss = [d for d in mwin if d not in rows and d not in off]
    rep.add("E5/A3 A3-1: linia Markietani (E5/A3) codziennie", f"brak/nieczytelna w {len(miss)} z {len(mwin)} dob" + (f", wylaczone w {len(off)}" if off else ""),
            "0 (LogEnabled; paczka czynna w biegu zbioru A)", (len(miss) == 0) if mwin else None)
    # A3-2 (rozdz. 4): sakiewki zolnierzy <= 15 dni zoldu - "Obieg": stan sakiewek / (zold partii + zold zalog) naliczony tej doby; ostatnia doba okna
    od = [d for d in sorted(obg) if 2 <= run_day(d, start) <= until]
    sd = None
    if od:
        o = obg[od[-1]]
        purse, zp, zz = num(r"sakiewki ludzi \[P\]: stan (\d+)", o), num(r"zold partii (\d+)", o), num(r"zold zalog (\d+)", o)
        if purse is not None and zp and zz is not None:
            sd = purse / float(zp + zz)
    ramp_on = any(r["ramp"].startswith("rozruch") for r in rows.values())
    lastm = rows[mwin[-1]] if mwin and mwin[-1] in rows else None
    rep.add("E5/A3 A3-2: sakiewki <= 15 dni zoldu (Obieg: stan / zold partii i zalog, ostatnia doba okna)",
            (f"{sd:.1f} dni" if sd is not None else "brak linii Obieg") + (f"; partie rodow (linia markietanow) {lastm['days']:.1f} dni" if lastm and lastm["days"] is not None else "")
            + (f", w tym oszczednosci K1 {lastm['kdays']:.1f} dni (markietani ich nie ruszaja)" if lastm and lastm["kdays"] is not None else "")
            + ("; rozruch w biegu (stary zapis)" if ramp_on else ""),
            "<= 15 (oczekiwane 5-12 [S]; bieg z31-A bez A3: d40 12.8, d120 29.3)", (sd <= 15.0) if (sd is not None and rows and not off) else None)
    late = [d for d in mwin if d in rows and run_day(d, start) >= 2]
    if late:
        tot = sum(rows[d]["tot"] for d in late) / len(late)
        town = sum(rows[d]["town"] for d in late)
        vill = sum(rows[d]["vill"] for d in late)
        share = 100.0 * town / (town + vill) if (town + vill) else 0.0
        rep.add("E5/A3 A3-3: markietani wydaja w polu (srednia dob 2-%d)" % until,
                f"{tot:.0f}/d (do kas miast {town / len(late):.0f}, do kies wsi {vill / len(late):.0f}; partii w polu {st.mean(rows[d]['n'] for d in late):.0f}"
                f", wydalo {st.mean(rows[d]['paid'] for d in late):.0f})",
                "> 0 (rachunek [S]: ok. 100-190 tys./d, ile dzis przybywa sakiewkom)", tot > 0)
        full = rows[late[-1]]["full"]
        rep.add("E5/A3 A3-4: podzial miasto / wies (Sutler Town Share)", f"miasta {share:.1f}% (czesc wsi bez odbiorcy -> miasto: {sum(rows[d]['nvg'] for d in late)})",
                "85% (+- 1 pp; wyzej tylko o czesc bez niewrogiej wsi w stanie Normal)", (84.0 <= share <= 100.0) if (town + vill) else None)
        rep.add("E5/A3 A3-5: markietani bez niewrogiego miasta -> najblizsze miasto (licznik)",
                f"partii {sum(rows[d]['nt'] for d in late)}, zl {sum(rows[d]['ntg'] for d in late)} w {len(late)} dobach",
                "INFO (regula R9: brak odbiorcy - kasa najblizszego miasta, licznik)", None)
        rep.add("E5/A3 A3-6: K3 - markietani we wlasnych miastach rodow (srednia)", f"{st.mean(rows[d]['k3'] for d in late):.0f}/d; gracz razem {sum(rows[d]['pl'] for d in late)}",
                "INFO (ten sam licznik co OnLeft: CrownIncome.NoteOwnSpend; gracz = AI)", None)
        ms = [rows[d]["ms"] for d in late]
        # narzedzie progow zb58 (TRIAZ A3-7 pkt 4 i podwazenie pkt 6): 20 ms z projektu [S] jest nieosiagalne z zasady - sama baza to 0.031 ms x ok. 530
        # partii = 16-17 ms, wzorzec W33 mial 38.7 / 69.9. Prog = pomiar wzorca + ok. 30%; po biegu z poprawka wydajnosci (Sutlers / AiWear) ustawic wedlug
        # pomiaru. Regresja E6/N1 (109.7 / 221.0) zostaje NIE.
        rep.add("E5/A3 A3-7: koszt petli markietanow (srednia / najwiecej)", f"{st.mean(ms):.1f} / {max(ms):.1f} ms",
                "srednia <= 50 ms/dobe i najwiecej <= 90 ms (wzorzec W33 38.7 / 69.9 + ok. 30%; projekt [S] 20 ms ponizej samej bazy; F6 czesc 1 z 3 - "
                "rezerwa napraw raz na partie w polu, czesci 2-3 w AiWear po scaleniu etapu 8)", st.mean(ms) <= 50.0 and max(ms) <= 90.0)
        # narzedzie progow F9b (F6): F6-1 koszt ostatnich 30 dob i koszt na partie w polu (INFO - miara czesci 1 z 3 poprawki wydajnosci); F6-2 rezerwa
        # K1 liczona przez markietanow (K - "rezerwy: ..., oszczednosci K1") nie moze przekraczac oszczednosci K1 w sakiewkach partii rodow (S - dopisek
        # "w tym oszczednosci K1") w zadnej dobie: KeptFor zostaje dla partii pominietych, wiec S > K
        l30 = late[-30:]
        m30 = st.mean(rows[d]["ms"] for d in l30)
        pa, p30 = [rows[d]["ms"] / rows[d]["n"] for d in late if rows[d]["n"] > 0], [rows[d]["ms"] / rows[d]["n"] for d in l30 if rows[d]["n"] > 0]
        rep.add("E5/A3 F6-1: koszt petli markietanow w ostatnich 30 dobach i na partie w polu (srednia z dob)",
                f"ostatnie {len(l30)} dob {m30:.1f} ms" + (f"; na partie w polu {st.mean(pa):.3f} ms (okno) / {st.mean(p30):.3f} ms (ostatnie {len(l30)} dob)"
                                                           if pa and p30 else "")
                + (" - UWAGA: >= 182 ms = poprawka F6 nie dziala" if m30 >= 182.0 else ""),
                "INFO (a589def 182.2 ms, 0.214 / 0.353; W33 60.3, 0.079 / 0.124; po F6 czesc 1 oczekiwane ok. 130-160 ms i 0.25-0.31)", None)
        sk = [(d, rows[d]["ks"], rows[d]["kk"]) for d in late if rows[d]["ks"] is not None and rows[d]["kk"] is not None]
        if sk and not off:
            neg = [run_day(d, start) for d, a, b in sk if a < b]
            dsum, ssum = sum(a - b for _, a, b in sk), sum(a for _, a, _b in sk)
            rep.add("E5/A3 F6-2: oszczednosci K1 w sakiewkach partii rodow (S) nie mniejsze niz rezerwa K1 markietanow (K) w kazdej dobie",
                    f"dob z S < K: {len(neg)} z {len(sk)}" + (f" (doby {neg[:6]})" if neg else "") + f"; S - K srednio {dsum / float(len(sk)):.0f}/d"
                    + (f", udzial (S - K) / S {100.0 * dsum / ssum:.1f}%" if ssum else ""),
                    "0 dob z S < K i suma (S - K) > 0 (a589def 20.8%, W33 19.3%)", len(neg) == 0 and dsum > 0)
        else:
            rep.add("E5/A3 F6-2: oszczednosci K1 w sakiewkach partii rodow (S) nie mniejsze niz rezerwa K1 markietanow (K)",
                    "bez wyniku (paczka wylaczona w biegu albo brak pol w linii)", "0 dob z S < K i suma (S - K) > 0", None)
        rr = [d for d in late if rows[d]["ramp"].startswith("rozruch")]
        rep.add("E5/A3 INFO: stawka i rozruch", f"stawka pelna {full:.1f}%; doby rozruchu w oknie {len(rr)}"
                + (f" (stawka {rows[rr[0]]['rate']:.1f}% -> {rows[rr[-1]]['rate']:.1f}%)" if rr else ""),
                "INFO (rozruch tylko w zapisie z sakiewkami > 15 dni zoldu: od 1% do pelnej w Sutler Ramp Days)", None)
    ru = [s for s in lines if s.startswith("Markietani (E5/A3): rozruch")]
    rep.add("E5/A3 INFO: decyzja rozruchu (raz na kampanie)", ru[-1][:200] if ru else "brak linii", "INFO (nowa kampania: bez rozruchu)", None)
    # notable (164c): pasmo i nowi notable bez zlota z niczego / w nicosc, kapital karawan z kies i kas (= korekta zrodel), kontrolki prog 0
    nwin = [d for d in sorted(nob) if 2 <= run_day(d, start) <= until]
    kwin = [d for d in sorted(onk) if 2 <= run_day(d, start) <= until]
    if kwin:
        bo = sum(abs(num(r"pasmo 4500-10500: nadwyzka w nicosc ([-+]?\d+)", onk[d], int, 0) or 0) for d in kwin)
        bi = sum(abs(num(r"dosypka z niczego ([-+]?\d+)", onk[d], int, 0) or 0) for d in kwin)
        nn = sum(abs(num(r"nowi notable ([-+]?\d+)", onk[d], int, 0) or 0) for d in kwin)
        rep.add("E5/A3 A3-8: pasmo notabli - w nicosc / z niczego (Obieg, doby 2-%d)" % until, f"{bo} / {bi}",
                "0 / 0 (bieg z31-A bez A3: ok. -107 tys. / +69 tys. na dobe)", (bo == 0 and bi == 0) if nwin else None)
        rep.add("E5/A3 A3-9: nowi notable z niczego (Obieg, doby 2-%d)" % until, f"{nn}", "0 (po starcie gry; tworzenie swiata - bilans otwarcia)",
                (nn == 0) if nwin else None)
    nre = re.compile(r"nadwyzka do kas (\d+) \(notable miast (\d+) / wsi (\d+); zdarzen (\d+)\), brak z kas (\d+) \(notable miast (\d+) / wsi (\d+); zdarzen (\d+), nalezne (\d+)\)"
                     r", uciete (\d+) \(kasa bez nadwyzki u (\d+) notabli - sila nie zeszla (\d+) pkt")
    cre = re.compile(r"kapital karawan notabli[^:]*: (\d+) karawan, gra dalaby (\d+), z kies notabli (\d+), z kas miast startu (\d+), uciete ([-\d]+) \(bez kapitalu (\d+)\)")
    kre = re.compile(r"bez kasy handlu - jak w grze \(prog 0\): zdarzen (\d+), w nicosc (\d+), z niczego (\d+) \| kontrola \(prog 0\): zdarzenia w kontekscie niedopasowane (\d+)"
                     r", stos przepelniony (\d+), karawana bez odczytu modelu (\d+)")
    nb, cb, kb, bad_corr, nofix = [], [], [], [], 0
    for d in nwin:
        s = nob[d]
        m, c, k = nre.search(s), cre.search(s), kre.search(s)
        if m:
            nb.append([int(x) for x in m.groups()])
        if c:
            cv = [int(x) for x in c.groups()]
            cb.append(cv)
            corr = num(r"minus kapital karawan notabli z kies notabli i kas miast startu \(E5/A3\) (\d+)", cau.get(d, ""))
            if corr is None:
                nofix += 1
            elif corr != cv[2] + cv[3]:
                bad_corr.append(run_day(d, start))
        if k:
            kb.append([int(x) for x in k.groups()])
    if not nwin:
        rep.add("E5/A3: linia Notable (E5/A3)", "brak w logu", "jest od wgrania E5/A3 (LogEnabled)", None)
    else:
        if nb:
            rep.add("E5/A3 INFO: pasmo przez kasy miast handlu (suma dob 2-%d)" % until,
                    f"do kas {sum(x[0] for x in nb)} (notable miast {sum(x[1] for x in nb)} / wsi {sum(x[2] for x in nb)}), z kas {sum(x[4] for x in nb)}"
                    f" (miast {sum(x[5] for x in nb)} / wsi {sum(x[6] for x in nb)}), nalezne {sum(x[8] for x in nb)}, uciete {sum(x[9] for x in nb)}"
                    f" (notabli ponizej pasma z sila: najwiecej {max(x[10] for x in nb)} na dobe)",
                    "INFO (miasta i wsie osobno - projekt Test A3; uciete = kasa bez nadwyzki, sila nie schodzi)", None)
        # scalenie porcji A (recenzja A3 R2-1 b): przelewy pasma z kasa osady w linii "Notable (E5/0)" = pasmo przez kasy w linii A3 (ta sama doba, +-1 zl;
        # miasta + wsie razem - podzial miasto/wies liczony w obu liniach inaczej: E5/0 wedlug osady notabla, A3 wedlug kasy handlu)
        nt0 = by_day(lines, "Notable (E5/0): dzien")
        ncmp, nbad = 0, []
        for d in nwin:
            m, s0 = nre.search(nob[d]), nt0.get(d)
            if not m or not s0:
                continue
            ko = (num(r"do kasy osady (\d+) /", s0, int, 0) or 0) + (num(r"do kasy osady targowej (\d+) /", s0, int, 0) or 0)
            ki = (num(r"/ z kasy osady (\d+)", s0, int, 0) or 0) + (num(r"/ z kasy osady targowej (\d+)", s0, int, 0) or 0)
            ncmp += 1
            if abs(ko - int(m.group(1))) > 1 or abs(ki - int(m.group(5))) > 1:
                nbad.append(run_day(d, start))
        if ncmp:
            rep.add("E5/A3 + E5/0: pasmo przez kasy - E5/0 \"do kasy / z kasy osady\" = A3 \"do kas / z kas\" (kazda doba)",
                    f"niezgodne {len(nbad)} z {ncmp} dob" + (f" (doby {nbad[:6]})" if nbad else ""), "0 (+-1 zl)", len(nbad) == 0)
        else:
            rep.add("E5/A3 + E5/0: pasmo przez kasy - E5/0 wobec A3", "brak linii Notable (E5/0) w dobach linii A3", "INFO (E5/0 wylaczone - Town Folk Mode 0)", None)
        if cb:
            rep.add("E5/A3 A3-10: kapital karawan notabli z kies i kas = korekta zrodel bilansu (kazda doba)",
                    f"niezgodne {len(bad_corr)} z {len(cb)} dob" + (f" (doby {bad_corr[:6]})" if bad_corr else "") + (f"; bez linii bilansu {nofix}" if nofix else "")
                    + f"; razem karawan {sum(x[0] for x in cb)}, gra dalaby {sum(x[1] for x in cb)}, z kies {sum(x[2] for x in cb)}, z kas {sum(x[3] for x in cb)}"
                    + f", bez kapitalu {sum(x[5] for x in cb)}",
                    "0 (kapital z niczego 0: O17 widzi go jako nadany, korekta zrodel zdejmuje go w calosci)", len(bad_corr) == 0)
        if kb:
            nt = sum(x[0] for x in kb)
            ctrl = sum(x[3] + x[4] + x[5] for x in kb)
            rep.add("E5/A3 A3-11: notable bez kasy handlu (jak w grze) / kontrolki",
                    f"zdarzen {nt} (w nicosc {sum(x[1] for x in kb)}, z niczego {sum(x[2] for x in kb)}); kontrolki {ctrl}", "0 / 0 (prog 0)", nt == 0 and ctrl == 0)
    if kwin:
        def cars(rd):
            ds = [d for d in kwin if run_day(d, start) <= rd]
            return num(r"karawany notabli \[P\]: (\d+) karawan", onk[ds[-1]]) if ds else None
        rep.add("E5/A3 A3-12: karawany notabli (d40 / ostatnia doba okna)", f"{cars(40)} / {cars(until)}",
                ">= 90% biegu bez A3 (z31-A: d40 750, d120 914 - bez bazy tylko odczyt; test po scaleniu z E4/8)", None)
    st0 = [s for s in lines if s.startswith("Notable (E5/A3): start")]
    rep.add("E5/A3 INFO: bilans otwarcia i latki (linia startowa)", st0[0][st0[0].find("| latki"):][:260] if st0 else "brak linii",
            "nowa kampania: notable n > 0 (zloto gry), karawany startowe m > 0; latki BRAK: -", None)
    errs = [s for s in lines if s.startswith("ERROR in ") and ("Sutlers" in s or "NotableGold" in s)]
    stm = max([num(r"potkniecia (\d+)", mar[d], int, 0) or 0 for d in mwin] + [num(r"potkniecia (\d+)", nob[d], int, 0) or 0 for d in nwin] + [0])
    rep.add("E5/A3 A3-13: bledy Sutlers / NotableGold, potkniecia", f"bledy {len(errs)}, potkniecia {stm}", "0 / 0", len(errs) == 0 and stm == 0)
    cd = [d for d in sorted(cau) if 1 <= run_day(d, start) <= until]
    rv = num(r"srednia 28 dob ([+-]?\d+)", cau[cd[-1]]) if cd else None
    rep.add("E5/A3 A3-14: nic w nicosc - reszta ksiegi R (srednia 28 dob, ostatnia doba okna)", f"{rv}" if rv is not None else "brak linii",
            "|R| < 10 000 (prog etapu 3; --grupa etap3)", (abs(rv) < 10000) if rv is not None else None)


def etap5_a4(rep, lines, start, until, obl, bud):
    """E5/A4 (196, PLAN 5.4 - osada oblezona nie placi nic, R22): projekt rozdz. 3 "E5/A4" Test - wplaty z oblezonych osad 0; miasta z zywym panem
    i nadwyzka > 0 bez zaworu 0 ("10 miast" - z definicji A1, prog A1-T9; tu tylko odczyt, gdy dopisek A1 jest w logu); wplaty z kas ponizej zapasu 0
    (z definicji: pobor = min(nalezne, kasa - prog); zamki - prog B-4 max(20 000, zapas kupcow), miasta - zapas kupcow od A1).
    Linia "Oblezone (E5/A4): dzien N" (dzien gry; obl ma klucz = dzien ksiegi): liczniki od poprzedniej linii - renta miast z naszego bloku doby,
    polityki korony z dziennego ticku rodu krola w grze (tylko prawdziwe rozliczenie, bez prognozy ekranu). Zloto nie rusza - mniej przelewow;
    reszta ksiegi - wiersze A3-14 / A1-T13 / --grupa etap3. Doby oczekiwane - z linii "Budzet rodow (166)" (bud, ten sam klucz), a bez niej - z samej linii A4.
    Recenzja A4: wstrzymanie tylko przy kasie prawdziwym pieniadzem (miasta - A1, zamki - 110), inaczej osada placi jak dotad (licznik "kasa pod
    regulatorem gry"); A4-3 czyta KONTROLE niezalezna od bramki (co naprawde zeszlo z kas oblezonych: renta, zawor 110, danina, polityki) -
    "bez wyjasnienia" (ponad to, co bramka jawnie przepuscila) = 0 w kazdej dobie, przy kazdym stanie klucza."""
    win = sorted(set(d for d in obl if 1 <= run_day(d, start) <= until) | set(d for d in bud if 1 <= run_day(d, start) <= until))
    kinds = ("renta miast", "Crown Duty", "War Tax", "Road Tolls")

    def part(s, head):
        i = s.find(head)
        if i < 0:
            return None
        seg = s[i + len(head):]
        j = seg.find(" | ")
        seg = seg if j < 0 else seg[:j]
        out = []
        for k in kinds:
            m = re.search(re.escape(k) + r" (\d+) \((\d+)\)", seg)
            if not m:
                return None
            out.append((int(m.group(1)), int(m.group(2))))
        m = re.search(r"razem (\d+) z (\d+) osad", seg)
        if not m:
            return None
        return out, int(m.group(1)), int(m.group(2))
    rows, off = {}, []
    for d in win:
        s = obl.get(d)
        if s is None:
            continue
        if "| Besieged Pay Nothing: nie" in s:
            off.append(d)
        h = part(s, "| wstrzymane (oblezona osada nie placi - zostaje w jej kasie): ")
        p = part(s, "| zaplacone mimo oblezenia - wylacznik wylaczony: ")
        g = part(s, "| zaplacone mimo oblezenia - kasa pod regulatorem gry (miasta bez A1, zamki bez 110): ")
        m = re.search(r"oblezone teraz: miasta (\d+), zamki (\d+); wsie w rabunku lub spladrowane (\d+)", s)
        f = re.search(r"ponad zapasem kupcow \(D4\): (\d+) z (\d+) zamkow", s)
        c = re.search(r"kontrola \(niezalezna od bramki[^)]*\): renta (\d+), zawor 110 (\d+), danina (\d+), polityki (\d+)(?:, zaulki \d+)?; razem (\d+) z (\d+) osad"
                      r"; w tym zaplacone jawnie \(wyzej\) (\d+); bez wyjasnienia (\d+) z (\d+) osad", s)
        r = re.search(r"kasa prawdziwym pieniadzem \(wstrzymanie tylko tam\): miasta \(A1\) (tak|nie), zamki \(110\) (tak|nie)", s)
        if h and p and g and m and f and c and r:
            rows[d] = {"held": h, "paid": p, "reg": g, "towns": int(m.group(1)), "castles": int(m.group(2)), "vill": int(m.group(3)),
                       "floor": int(f.group(1)), "castleN": int(f.group(2)), "stum": num(r"potkniecia (\d+)", s, int, 0) or 0,
                       "ctl": [int(c.group(i)) for i in range(1, 10)], "townReal": r.group(1) == "tak", "castleReal": r.group(2) == "tak"}
    miss = [d for d in win if d not in rows]
    rep.add("E5/A4 A4-1: linia Oblezone (E5/A4) codziennie", f"brak/nieczytelna w {len(miss)} z {len(win)} dob" + (f", wylacznik wylaczony w {len(off)}" if off else ""),
            "0 (LogEnabled; paczka czynna w biegu zbioru A)", (len(miss) == 0) if win else None)
    on = [d for d in win if d in rows and d not in off]
    if off:
        rep.add("E5/A4 A4-2: wylacznik Besieged Pay Nothing", f"wylaczony w {len(off)} z {len(win)} dob", "wlaczony caly bieg zbioru A (wylaczony - A4-3 INFO)", None)
    # A4-3 (recenzja): kontrola niezalezna od bramki - co naprawde zeszlo z kas oblezonych osad ponad to, co bramka jawnie przepuscila (kasa pod
    # regulatorem gry) = 0 w kazdej dobie z wlaczonym kluczem (zgubiona bramka po scaleniu, nowa droga poboru bez Holds, zawor 110 / Levies bez
    # warunku oblezenia). Doby z kluczem wylaczonym - INFO: zawor A1 (po scaleniu) placi panu dekretem BK (High 1.3) od czesci pana, wiec w miescie
    # bez krolestwa czesc pana moze przekroczyc kwote bramki (pay) - "bez wyjasnienia" do 30% renty bez bledu.
    if on:
        cs = [sum(rows[d]["ctl"][i] for d in on) for i in range(9)]
        bad = [d for d in on if rows[d]["ctl"][7] > 0]
        rep.add("E5/A4 A4-3: kontrola - zeszlo z kas oblezonych bez wyjasnienia (suma dob z wlaczonym kluczem; niezalezne od bramki)",
                f"bez wyjasnienia {cs[7]} zl (osado-dni {cs[8]}; dob z > 0: {len(bad)}" + (f", pierwsza {bad[0]}" if bad else "") + ")"
                + f" | zeszlo razem {cs[4]} (renta {cs[0]}, zawor 110 {cs[1]}, danina {cs[2]}, polityki {cs[3]}), w tym jawnie przez bramke {cs[6]}",
                "0 (projekt Test A4: wplaty z oblezonych osad 0 - poza jawnie przepuszczonymi przy kasie pod regulatorem gry)", cs[7] == 0 and cs[8] == 0)
    if off:
        ofr = [d for d in off if d in rows]
        co = [sum(rows[d]["ctl"][i] for d in ofr) for i in range(9)]
        rep.add("E5/A4 INFO: kontrola w dobach z wylaczonym kluczem", f"zeszlo {co[4]}, w tym jawnie {co[6]}, bez wyjasnienia {co[7]} (osado-dni {co[8]})",
                "INFO - wszystko placi jak przed paczka; > 0 = zawor 110 / Levies bez warunku oblezenia albo dekret High w miescie bez krolestwa (A1)", None)
    if rows:
        ds = [d for d in win if d in rows]
        rg = [sum(rows[d]["reg"][0][i][0] for d in ds) for i in range(len(kinds))]
        rgn = [sum(rows[d]["reg"][0][i][1] for d in ds) for i in range(len(kinds))]
        tr = len([d for d in ds if rows[d]["townReal"]]); cr = len([d for d in ds if rows[d]["castleReal"]])
        rep.add("E5/A4 A4-3b: zaplacone mimo oblezenia - kasa pod regulatorem gry (suma okna)",
                ", ".join(f"{kinds[i]} {rg[i]} ({rgn[i]})" for i in range(len(kinds)))
                + f" | kasa prawdziwym pieniadzem: miasta (A1) w {tr} z {len(ds)} dob, zamki (110) w {cr} z {len(ds)} dob",
                "INFO - bez A1 oblezone miasta placa jak dotad (regulator gry skasowalby wstrzymane); zbior A po scaleniu z A1 (A1 i 110 czynne): 0", None)
    if off:
        pz = sum(rows[d]["paid"][1] for d in off if d in rows)
        rep.add("E5/A4 INFO: zaplacone mimo oblezenia w dobach z wylaczonym kluczem", f"{pz} zl w {len([d for d in off if d in rows])} dobach",
                "INFO - stan sprzed paczki (renta miast i polityki korony z oblezonych)", None)
    if rows:
        ds = [d for d in win if d in rows]
        held = [sum(rows[d]["held"][0][i][0] for d in ds) for i in range(len(kinds))]
        heldn = [sum(rows[d]["held"][0][i][1] for d in ds) for i in range(len(kinds))]
        tw, cs = [rows[d]["towns"] for d in ds], [rows[d]["castles"] for d in ds]
        rep.add("E5/A4 A4-4: wstrzymane - oblezona osada nie placi (suma okna; zostaje w jej kasie)",
                ", ".join(f"{kinds[i]} {held[i]} ({heldn[i]})" for i in range(len(kinds)))
                + f"; razem {sum(held)} = {sum(held) / len(ds):.0f}/d; osado-dni ze wstrzymaniem {sum(rows[d]['held'][2] for d in ds)}"
                + f" | oblezone przy linii: miasta srednio {st.mean(tw):.2f} (najwiecej {max(tw)}), zamki {st.mean(cs):.2f} (najwiecej {max(cs)})",
                "INFO ([S] z31-A: ok. 1.3 oblezonego miasta na dobe w d93-120 x ok. 5 tys. renty = ok. 6.5 tys./d renty; polityki - tylko krolestwa z nimi)", None)
        # A4-5: drogi "od dawna" - zawor zamkow 110 i zawor A1 pomijaja oblezone (odczyt liczby z ich linii)
        # recenzja scalenia A: linie 110 i 169c maja juz numer doby ksiegi (dzien gry - 1: CastlePurse.Daily, Measure169c.Daily) - bez przesuniecia,
        # jak w etap5_a1; przesuniecie tylko dla linii "Oblezone (E5/A4)" (dzien gry) - inaczej A4-5/6/9 czytaly 110/169c z nastepnego bloku doby
        z110 = by_day(lines, "Zawor zamkow (110): dzien")
        k169 = by_day(lines, "Kasy miast (169c): dzien")
        zc = [num(r"oblezone (\d+), bez pana", z110[d], int) for d in win if d in z110]
        zc = [x for x in zc if x is not None]
        ac = [num(r"bez poboru: kasa nie ponad zapasem \d+, oblezone (\d+)", k169[d], int) for d in win if d in k169]
        ac = [x for x in ac if x is not None]
        rep.add("E5/A4 A4-5: zawor zamkow (110) i zawor kas miast (A1) - oblezone pominiete (suma okna)",
                (f"zamki {sum(zc)} w {len(zc)} dobach" if zc else "zamki: brak liczby w linii 110") + "; "
                + (f"miasta (A1) {sum(ac)} w {len(ac)} dobach" if ac else "miasta: brak dopisku E5/A1 (A1 nie w logu - oblezone miasta placa jak dotad, A4-3b)"),
                "INFO (regula od dawna, bez wylacznika A4; danina i clo - KingdomTreasury.Levies)", None)
        # A4-6: "10 miast bez placenia" - z definicji A1 (prog A1-T9); tu tylko gdy dopisek A1 jest w logu
        v9 = [num(r"miast z nadwyzka bez zaworu \(10 miast\) (\d+)", k169[d], int) for d in win if d in k169]
        v9 = [x for x in v9 if x is not None]
        rep.add("E5/A4 A4-6: miasta z zywym panem i nadwyzka bez zaworu (\"10 miast\")",
                (f"niezerowe w {len([x for x in v9 if x])} z {len(v9)} dob" + (f" (najwiecej {max(v9)})" if any(v9) else "")) if v9 else "brak dopisku E5/A1 w logu",
                "0 (z definicji A1 - zawor od nadwyzki, bez filtra ludnosci; prog A1-T9)", (not any(v9)) if v9 else None)
        # A4-9 (recenzja R1-2, krok scalania 2): zawor A1 przez bramke R22 - bez kroku 2 zawor A1 pomija oblezone przed bramka (nic nie wyplywa,
        # wiec A4-3 tego nie widzi): oblezone w zaworze A1 (_vSiege) > 0, a "wstrzymane: renta miast" 0 w dobach z kluczem i A1
        dd = [d for d in win if d in rows and d in k169 and d not in off and rows[d]["townReal"]]
        if dd:
            vs = sum(num(r"bez poboru: kasa nie ponad zapasem \d+, oblezone (\d+)", k169[d], int, 0) or 0 for d in dd)
            hn = sum(rows[d]["held"][0][0][1] for d in dd)
            rep.add("E5/A4 A4-9: zawor kas miast A1 przez bramke R22 (krok scalania 2)",
                    f"oblezone w zaworze A1 {vs}, wstrzymana renta miast {hn} miasto-dni (w {len(dd)} dobach z kluczem i A1)",
                    "> 0, gdy oblezone > 0 (0 = zawor A1 pomija oblezone przed bramka - krok scalania 2 nie zrobiony)", (hn > 0) if vs > 0 else None)
        last = rows[ds[-1]]
        fl = [rows[d]["floor"] for d in ds]
        rep.add("E5/A4 A4-7: prog podatkow korony zamkow ponad zapasem kupcow (D4)",
                f"ostatnia doba {last['floor']} z {last['castleN']} zamkow (najwiecej {max(fl)})",
                "INFO - B-4 PayFloor = max(20 000, zapas kupcow): zamki z zapasem < 20 000 placa Crown Duty / War Tax od 20 000, nie od D4"
                " (decyzja po tescie A; wplaty z kas ponizej progu - 0 z definicji)", None)
    errs = [s for s in lines if s.startswith("ERROR in ") and "BesiegedPay" in s]
    stm = max([rows[d]["stum"] for d in rows] + [0])
    rep.add("E5/A4 A4-8: bledy BesiegedPay, potkniecia", f"bledy {len(errs)}, potkniecia {stm}", "0 / 0", len(errs) == 0 and stm == 0)
    st0 = [s for s in lines if s.startswith("Oblezone (E5/A4): start")]
    rep.add("E5/A4 INFO: linia startowa", st0[0][st0[0].find("| wylacznik"):][:420] if st0 else "brak linii",
            "wylacznik tak; Population Rent Enabled tak; Policy Income Conserved tak; kasy miast A1 tak (zbior A), Castle Purse Enabled tak, latka regulatora 110 wpieta", None)


def etap5_a5(rep, lines):
    """E5/A5 (197, R23 - BetterEconomy: prawdziwa wplata gracza do kasy osady i dar dla notabli): projekt rozdz. 3 "E5/A5" Test - zbior A + reczne
    sprawdzenie Jeffa (autotest nie klika menu): przelew w ksiedze, nic z niczego. Linia startowa BEE (170) - prefiksy Try* wpiete; linia kampanii
    BEE (170) - dopisek "E5/A5 (prawdziwa wplata i dar dla notabli)"; kazda akcja gracza - linia "BEE (E5/A5) wplata|wplata odmowiona|dar: dzien N | ..."
    ze zlotem gracza i odbiorcy przed i po (gracz traci dokladnie tyle, ile dostaje kasa osady / notable - inaczej dopisek ROZNICA)."""
    st = [x for x in lines if x.startswith("BEE domkniecie (170): BetterEconomy")]
    camp = [x for x in lines if x.startswith("BEE domkniecie (170): kampania")]
    pays = [x for x in lines if x.startswith("BEE (E5/A5) wplata: dzien")]
    refs = [x for x in lines if x.startswith("BEE (E5/A5) wplata odmowiona: dzien")]
    gifts = [x for x in lines if x.startswith("BEE (E5/A5) dar: dzien")]
    labels = ("prawdziwa wplata do kasy miasta (E5/A5)", "prawdziwa wplata do kasy zamku (E5/A5)")
    # A5-1: prefiksy Try* wpiete (linia startowa BEE 170; bez BEE albo inna wersja - INFO)
    if not st:
        rep.add("E5/A5 A5-1: prefiksy Try* wplaty (linia startowa BEE 170)", "brak linii startowej BEE", "jest przy BetterEconomy w grze", None)
    else:
        x = st[-1]
        if "nieobecny" in x or "NIC nie wpiete" in x:
            rep.add("E5/A5 A5-1: prefiksy Try* wplaty (linia startowa BEE 170)", x[:200], "BetterEconomy v1.4.5 obecny (inaczej paczka nieczynna - INFO)", None)
        else:
            m = re.search(r"wpiete (\d+)/(\d+)", x)
            head = x.split(" | BRAK:")[0]
            ok = all(l in head for l in labels)
            rep.add("E5/A5 A5-1: prefiksy Try* wplaty (linia startowa BEE 170)",
                    (f"wpiete {m.group(1)}/{m.group(2)}" if m else "?") + "; " + ", ".join(("tak" if l in head else "NIE") + " - " + l for l in labels)
                    + (" | BRAK: " + x.split(" | BRAK:")[1][:200] if " | BRAK:" in x else ""),
                    "oba wpiete (18/18 przy pelnym 170)", ok)
    # A5-2: dopisek linii kampanii (kazda sesja: start / wczytanie)
    rows = []
    for x in camp:
        i = x.find("E5/A5 (prawdziwa wplata i dar dla notabli): ")
        rows.append(x[i:] if i >= 0 else None)
    if not camp:
        rep.add("E5/A5 A5-2: linia kampanii BEE (170) - dopisek E5/A5", "brak linii kampanii", "jest w kazdej sesji", None)
    else:
        bad, off = [], 0
        for r in rows:
            if r is None:
                bad.append("brak dopisku")
                continue
            if "wylacznik wylaczony" in r:
                off += 1
                continue
            if not ("prefiksy Try*: miasto tak, zamek tak" in r and "okno kwot przy opcjach wplaty 2/2" in r and "opcje daru dla notabli 2/2" in r):
                bad.append(r[:160])
        last = rows[-1] or "brak dopisku"
        rep.add("E5/A5 A5-2: linia kampanii BEE (170) - dopisek E5/A5 (sesje)",
                f"sesji {len(camp)}, niepelnych {len(bad)}" + (f", wylacznik wylaczony w {off}" if off else "") + " | ostatnia: " + last[:300],
                "kazda sesja: wylacznik wlaczony, prefiksy Try* tak/tak, okno kwot 2/2, opcje daru 2/2", len(bad) == 0 and off == 0)
        m = re.search(r"kasa prawdziwym pieniadzem: miasta \(A1\) (tak|nie).*?, zamki \(110\) (tak|nie)", last)
        rep.add("E5/A5 A5-3: kasa osady prawdziwym pieniadzem (wplata otwarta tylko tam)",
                (f"miasta (A1) {m.group(1)}, zamki (110) {m.group(2)}" if m else "brak w dopisku") + " | przerwa po darze: "
                + (re.search(r"przerwa po darze: ([^;]+)", last).group(1)[:90] if re.search(r"przerwa po darze: ([^;]+)", last) else "?"),
                "INFO - zbior A po scaleniu z A1: miasta tak, zamki tak (bez A1 wplata do miast zamknieta z powodem - regulator gry)", None)
    # A5-4: wplaty - gracz traci tyle, ile dostaje kasa osady
    if pays:
        diff = [x for x in pays if "| ROZNICA" in x]
        tot = sum(num(r"\| gracz \d+ -> \d+ \(-(\d+)\)", x, int, 0) or 0 for x in pays)
        got = sum(num(r"\| kasa osady \d+ -> \d+ \(\+(-?\d+)\)", x, int, 0) or 0 for x in pays)
        tw = len([x for x in pays if "(miasto)" in x]); cs = len([x for x in pays if "(zamek)" in x])
        rep.add("E5/A5 A5-4: wplaty gracza do kasy osady - gracz traci tyle, ile dostaje kasa",
                f"wplat {len(pays)} (miasta {tw}, zamki {cs}), gracz -{tot}, kasy +{got}, linii z ROZNICA {len(diff)}" + (f" (pierwsza: {diff[0][:160]})" if diff else ""),
                "ROZNICA 0 i suma gracza = suma kas (nic z niczego, nic w nicosc)", len(diff) == 0 and tot == got)
    else:
        rep.add("E5/A5 A5-4: wplaty gracza do kasy osady", "brak linii wplat", "INFO - autotest nie klika menu; reczny test Jeffa: wplata do wlasnego zamku/miasta -> linia z ROZNICA 0", None)
    # A5-4b (recenzja A5): wplata to pieniadze rodu gracza w kasie WLASNEJ osady - cala do zapasu "wlasnego" (CourtFull.OwnPlayer; wraca zaworem jako wlasne
    # D stalego, nie ziemia - inaczej zawyza StableLand gracza: powinnosci 165, limit Banku 168); linia "D staly" doby po wplacie podaje ja w zapasie
    if pays:
        own_re = re.compile(r"\| do zapasu wlasnego (\d+)")
        late_re = re.compile(r"wplaty gracza do kasy wlasnej osady \(E5/A5\) od wczorajszej linii (\d+)")
        bad, off, tot_on, own_on, pend, before, late_sum, sdn = [], 0, 0, 0, 0, 0, 0, 0
        for x in lines:
            if x.startswith("BEE (E5/A5) wplata: dzien"):
                o = num(own_re, x, int, None)
                pd = num(r"\| gracz \d+ -> \d+ \(-(\d+)\)", x, int, 0) or 0
                if o is None:
                    bad.append("brak pola: " + x[:120])
                    continue
                pend += o
                if "(D staly wylaczony)" in x:
                    off += 1
                    continue
                tot_on += pd; own_on += o
                if o != pd:
                    bad.append(x[:160])
            elif x.startswith("D staly (169c): dzien"):
                sdn += 1
                late_sum += num(late_re, x, int, 0) or 0
                before += pend; pend = 0
        close = (late_sum == before) if sdn else None
        rep.add("E5/A5 A5-4b: wplaty do zapasu wlasnego (wraca zaworem jako wlasne, nie ziemia D stalego)",
                f"wplaty {tot_on} -> do zapasu {own_on}, niezgodnych linii {len(bad)}" + (f" (pierwsza: {bad[0]})" if bad else "")
                + (f", przy D stalym wylaczonym {off}" if off else "")
                + (f"; w liniach D staly weszlo do zapasu {late_sum} z {before} wplaconych przed nimi" if sdn else "; brak linii D staly")
                + (f" (po ostatniej linii jeszcze {pend})" if pend else ""),
                "do zapasu = wplata w kazdej linii; w liniach D staly = suma wplat przed nimi (wyjatek: wczytanie zapisu miedzy wplata a doba - ta wplata wypada z zapasu)",
                len(bad) == 0 and close is not False)
    # A5-5: dary - gracz traci tyle, ile dostaja notable
    if gifts:
        diff = [x for x in gifts if "| ROZNICA" in x]
        tot = sum(num(r"\| gracz \d+ -> \d+ \(-(\d+)\)", x, int, 0) or 0 for x in gifts)
        got = sum(num(r"\| notable razem \+(-?\d+)", x, int, 0) or 0 for x in gifts)
        rel = sum(num(r"\| relacja razem \+(-?\d+)", x, int, 0) or 0 for x in gifts)
        nn = sum(num(r"\| notabli (\d+)", x, int, 0) or 0 for x in gifts)
        rep.add("E5/A5 A5-5: dary dla notabli - gracz traci tyle, ile dostaja notable",
                f"darow {len(gifts)}, notabli razem {nn}, gracz -{tot}, notable +{got}, relacja razem +{rel}, linii z ROZNICA {len(diff)}" + (f" (pierwsza: {diff[0][:160]})" if diff else ""),
                "ROZNICA 0 i suma gracza = suma notabli; relacja jak nadplata w barterze (najwyzej ok. +3 na notabla)", len(diff) == 0 and tot == got)
    else:
        rep.add("E5/A5 A5-5: dary dla notabli", "brak linii darow", "INFO - autotest nie klika menu; reczny test Jeffa: dar w miescie i we wsi -> linia z ROZNICA 0", None)
    # A5-6: odmowy (ekrany BK, konsola, menu) - INFO
    why = {}
    for x in refs:
        k = x.split("| powod: ", 1)[1][:70] if "| powod: " in x else "?"
        why[k] = why.get(k, 0) + 1
    rep.add("E5/A5 A5-6: odmowy wplaty (powody)", (f"{len(refs)}: " + "; ".join(f"{k} x{v}" for k, v in sorted(why.items(), key=lambda t: -t[1])[:5])) if refs else "0",
            "INFO - zloto nie schodzi przy odmowie; \"Closed for now\" = kasa pod regulatorem gry (miasta bez A1)", None)
    # A5-7: bledy i potkniecia
    errs = [x for x in lines if x.startswith("ERROR in BeeGifts")]
    stm = max([num(r"potkniecia (\d+)", x, int, 0) or 0 for x in pays + gifts] + [num(r"E5/A5 \(prawdziwa.*?potkniecia (\d+)", x, int, 0) or 0 for x in camp] + [0])
    rep.add("E5/A5 A5-7: bledy BeeGifts, potkniecia", f"bledy {len(errs)}, potkniecia {stm}" + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0", len(errs) == 0 and stm == 0)


def etap5_b2(rep, lines, start, until, wt):
    """E5/B2 (184, PLAN 5.6 - podatek wojenny korony od zarobku ludu, R15 (b), NA WIERZCH daniny): projekt rozdz. 3 "E5/B2" Test (zbior B, z kiesa ludu B1).
    Linia "Korona: podatek wojenny ludu (184): dzien N" (dzien gry; wt ma klucz = dzien ksiegi, jak 165) - po rentach 180, przed CrownIncome.End; na krolestwo
    (oddzielone " ; "): s, pulap, wojna/pokoj, potrzeba K (kredyt 186 w 7 dobach) / Z (zwrot ponad wplywy dnia bez 1/360) / S (skarbiec < zapas wojny), luz,
    krok tygodnia (doby gry podzielne przez 7), skarbiec, zapas wojny, dlug 186, ZALEGLOSC. Wiersze B2-1..B2-14 (progi projektu: s rosnie przy potrzebie,
    dlug 186 d364 <= d182, bez zaleglosci przy s < pulapu, zwrot >= 70% naleznego w wojnie; wielkosc 184 - odczyt)."""
    win = sorted(d for d in wt if 1 <= run_day(d, start) <= until)
    alld = sorted(d for d in by_day(lines, "Pieniadz swiata: dzien") if 1 <= run_day(d, start) <= until)
    kre = re.compile(r"^(.*?): s ([\d.]+)% / pulap ([\d.]+)%, (wojna|pokoj)(?:, potrzeba ([KZS]+))?(, luz)?(?:, krok ([+-]?[\d.]+) pkt)?, skarbiec (-?\d+) / zapas wojny (\d+)"
                     r"(?:, dlug 186 (\d+))?(, ZALEGLOSC)?")
    rows = {}
    for d in win:
        s = wt[d]
        cap = re.search(r"\| pulap ([\d.]+)% \(z polityka War Tax ([\d.]+)%\), krok ([\d.]+) pkt", s)
        sv = re.search(r"s krolestw w wojnie \(srednia, max\): ([\d.]+)%, ([\d.]+)% - krolestw w wojnie (\d+), z s > 0 (\d+), na pulapie (\d+); s > 0 w pokoju \(spada, bez poboru\) (\d+)", s)
        tk = re.search(r"\| pobrano (\d+) zl \(ludzie miast (\d+): W (\d+), R (\d+), P (\d+); podzamcza (\d+)\), wolan poboru (\d+)", s)
        hd = re.search(r"wstrzymane w oblezeniu (\d+) \((\d+)\)", s)
        nd = re.search(r"potrzeba \(7 dob, krolestwa w wojnie\): kredyt 186 (\d+) krolestw, zwrot ponad wplywy (\d+), skarbiec < zapas wojny (\d+)", s)
        if not (cap and sv and tk and hd and nd):
            continue
        ks = []
        i = s.find("| na krolestwo: ")
        if i >= 0:
            seg = s[i + len("| na krolestwo: "):]
            j = seg.rfind(" | potkniecia ")
            seg = seg[:j] if j >= 0 else seg
            if seg != "-":
                for part in seg.split(" ; "):
                    m = kre.match(part)
                    if m:
                        ks.append({"name": m.group(1), "s": float(m.group(2)), "cap": float(m.group(3)), "war": m.group(4) == "wojna", "need": m.group(5) or "",
                                   "luz": bool(m.group(6)), "krok": float(m.group(7)) if m.group(7) is not None else None, "wallet": int(m.group(8)),
                                   "reserve": int(m.group(9)), "debt": int(m.group(10)) if m.group(10) else 0, "arr": bool(m.group(11))})
                    else:
                        ks.append({"bad": part[:80]})
        rows[d] = {"on": "wylacznik War Tax From Folk tak" in s, "inc": "165 Crown Current Income tak" in s, "folk": "kiesa ludu (B1) czynna" in s,
                   "cap": float(cap.group(1)), "capP": float(cap.group(2)), "step": float(cap.group(3)),
                   "avg": float(sv.group(1)), "max": float(sv.group(2)), "warK": int(sv.group(3)), "posK": int(sv.group(4)), "capK": int(sv.group(5)),
                   "taken": int(tk.group(1)), "town": int(tk.group(2)), "castle": int(tk.group(6)), "calls": int(tk.group(7)),
                   "held": int(hd.group(1)), "heldN": int(hd.group(2)), "nLoan": int(nd.group(1)), "nOver": int(nd.group(2)), "nLow": int(nd.group(3)),
                   "stepDay": "krok tygodnia: dzis" in s, "ks": ks, "stum": num(r"\| potkniecia (\d+)\.", s, int, 0) or 0}
    exp = sorted(set(alld) | set(win))
    miss = [d for d in exp if d not in rows]
    bad = sum(1 for d in rows for k in rows[d]["ks"] if "bad" in k)
    rep.add("E5/B2 B2-1: linia Korona: podatek wojenny ludu (184) codziennie (czytelna)", f"brak/nieczytelna w {len(miss)} z {len(exp)} dob; nieczytelnych wpisow krolestw {bad}",
            "0 / 0 (LogEnabled)", (len(miss) == 0 and bad == 0) if exp else None)
    if not rows:
        return
    ds = sorted(rows)
    off = [d for d in ds if not (rows[d]["on"] and rows[d]["inc"] and rows[d]["folk"])]
    nofolk = len([d for d in ds if not rows[d]["folk"]])
    rep.add("E5/B2 B2-2: wylacznik War Tax From Folk, 165 (Crown Current Income) i kiesa ludu (B1) czynna", f"wylaczone w {len(off)} z {len(ds)} dob (w tym kiesa ludu nieczynna {nofolk})"
            + (f" (pierwsza {off[0]})" if off else ""),
            "wlaczone caly bieg zbioru B (wylaczone albo kiesa nieczynna - s = 0 i pobor 0, jak przed paczka - K3)", len(off) == 0)
    # B2-3: s nigdy ponad pulap krolestwa
    over = [(d, k["name"]) for d in ds for k in rows[d]["ks"] if "bad" not in k and k["s"] > k["cap"] + 1e-6]
    mx = max(rows[d]["max"] for d in ds)
    rep.add("E5/B2 B2-3: s krolestwa nie ponad pulap (3% / 6% z War Tax)", f"przekroczen {len(over)}" + (f" (pierwsze {over[0]})" if over else "") + f"; s max w biegu {mx:.2f}%",
            "0", len(over) == 0)
    # B2-4: krok tygodnia zgodny z regula potrzeby (wojna i 165: potrzeba -> w gore az do pulapu; luz -> w dol; pokoj albo bez 165 -> w dol az do 0)
    steps = [d for d in ds if rows[d]["stepDay"] and rows[d]["on"] and rows[d]["folk"]]
    n_up = n_up_bad = n_down = n_down_bad = n_peace = n_peace_bad = 0
    first_bad = None
    for d in steps:
        inc = rows[d]["inc"]
        for k in rows[d]["ks"]:
            if "bad" in k or k["krok"] is None:
                continue
            s0 = k["s"] - k["krok"]
            if k["war"] and inc and k["need"]:
                if s0 < k["cap"] - 1e-6:
                    n_up += 1
                    if not k["krok"] > 0:
                        n_up_bad += 1
                        first_bad = first_bad or (d, k["name"], "potrzeba bez wzrostu")
            elif k["war"] and inc and k["luz"]:
                if s0 > 1e-9:
                    n_down += 1
                    if not k["krok"] < 0:
                        n_down_bad += 1
                        first_bad = first_bad or (d, k["name"], "luz bez spadku")
            elif (not k["war"] or not inc) and s0 > 1e-9:
                n_peace += 1
                if not k["krok"] < 0:
                    n_peace_bad += 1
                    first_bad = first_bad or (d, k["name"], "pokoj bez spadku")
    rep.add("E5/B2 B2-4: s rosnie tydzien po potrzebie (K kredyt 186 / Z zwrot ponad wplywy / S skarbiec < zapas wojny), spada przy luzie i w pokoju",
            f"krokow tygodnia {len(steps)}: potrzeba ponizej pulapu {n_up} (bez wzrostu {n_up_bad}), luz {n_down} (bez spadku {n_down_bad}), pokoj z s > 0 {n_peace} (bez spadku {n_peace_bad})"
            + (f"; pierwsze odstepstwo {first_bad}" if first_bad else ""),
            "0 odstepstw (projekt Test B2: kredyt 186 w tygodniu -> s tydzien pozniej wyzsze, az do pulapu)", (n_up_bad + n_down_bad + n_peace_bad == 0) if steps else None)
    # B2-5: dlug 186 w drugim polroczu nie rosnie (d364 <= d182 na krolestwo w wojnie obu dob) - bieg roczny
    rd = {run_day(d, start): d for d in ds}
    if 182 in rd and 364 in rd:
        a = {k["name"]: k for k in rows[rd[182]]["ks"] if "bad" not in k}
        b = {k["name"]: k for k in rows[rd[364]]["ks"] if "bad" not in k}
        both = [n for n in b if n in a and a[n]["war"] and b[n]["war"]]
        up = [n for n in both if b[n]["debt"] > a[n]["debt"]]
        rep.add("E5/B2 B2-5: dlug 186 d364 <= d182 (krolestwa w wojnie obu dob)", f"krolestw {len(both)}, dlug wzrosl u {len(up)}" + (f": {', '.join(up[:5])}" if up else ""),
                "0 (bieg roczny zbioru B)", (len(up) == 0) if both else None)
    else:
        rep.add("E5/B2 B2-5: dlug 186 d364 <= d182", f"bieg do doby {max(rd) if rd else '-'}", "INFO - prog tylko w biegu rocznym (364 doby)", None)
    # B2-6: brak zaleglosci 186 u krolestw w wojnie z s ponizej pulapu
    arr = [(d, k["name"], k["s"], k["cap"]) for d in ds for k in rows[d]["ks"] if "bad" not in k and k["arr"] and k["war"] and k["s"] < k["cap"] - 1e-6]
    narr = len(set(x[1] for x in arr))
    rep.add("E5/B2 B2-6: zaleglosc 186 u krolestw w wojnie z s < pulapu (krolestwo-dni)", f"{len(arr)} (krolestw {narr})" + (f"; pierwsza {arr[0]}" if arr else ""),
            "0 (inaczej s nie nadaza za potrzeba - krok albo pulap za maly)", len(arr) == 0)
    # B2-7, B2-8: korona (165) - wplywy "nasze" i zwrot zoldu w wojnie
    kor = e4_series(lines, "Korona: wplywy dnia (165): dzien", 1)
    kd = [d for d in ds if d in kor]
    w84 = [num(r"w tym podatek wojenny ludu \(184\) (\d+)", kor[d]) for d in kd]
    o28 = [num(r"prawa trzecich \(178\) (\d+)", kor[d]) for d in _last28(kd)]
    o28 = [x for x in o28 if x is not None]
    rep.add("E5/B2 B2-7: korona - wplywy \"nasze\" 165 (sr28) i w tym podatek wojenny ludu",
            (f"{st.mean(o28):.0f}/d" if o28 else "brak linii 165") + f"; 184 w liniach 165 razem {sum(x for x in w84 if x is not None)} (w liniach 184 razem {sum(rows[d]['taken'] for d in ds)})",
            "INFO - prog: wplywy korony w wojnie po B >= bieg A (danina + 1/2 zaworu + 184 wobec danina + 1/3 zaworu) - porownanie z biegiem A", None)
    gv = dv = 0
    for d in kd:
        m = re.search(r"zwrot zoldu (\d+) \(nalezny (\d+)", kor[d])
        if m:
            gv += int(m.group(1))
            dv += int(m.group(2))
    rep.add("E5/B2 B2-8: zwrot zoldu w wojnie / nalezny (okno, 165)", f"{gv} / {dv} = {100.0 * gv / dv:.1f}%" if dv else "brak naleznego (bez wojny)",
            ">= 70%", (gv >= 0.7 * dv) if dv else None)
    rep.add("E5/B2 B2-9: \"stac pelny\" przy s na pulapie (6%)", "doby z krolestwami na pulapie: " + str(len([d for d in ds if rows[d]["capK"] > 0])),
            "INFO - prog projektu >= 95% swiat (z linii kiesy ludu B1 w tych dobach)", None)
    # B2-10: pobor przy zarobku ludu czynny (kiesa ludu B1 wpieta) - w dobach z krolestwami w wojnie i s > 0
    pd = [d for d in ds if rows[d]["posK"] > 0 and rows[d]["on"] and rows[d]["inc"] and rows[d]["folk"]]
    tk = sum(rows[d]["taken"] for d in pd)
    cl = sum(rows[d]["calls"] for d in pd)
    rep.add("E5/B2 B2-10: pobor 184 czynny (doby z krolestwami w wojnie i s > 0)", f"dob {len(pd)}, pobrano {tk} zl, wolan poboru {cl}",
            "> 0 (0 = pobor niewpiety - TownFolk.PayCrown raz na dobe, po scaleniu B1 musi byc > 0; kiesa nieczynna - s = 0, wiersz INFO, B2-2 NIE)", (tk > 0) if pd else None)
    t28 = _last28(ds)
    rep.add("E5/B2 B2-11: wielkosc 184 (sr28): pobrano / ludzie miast / podzamcza",
            f"{st.mean(rows[d]['taken'] for d in t28):.0f} / {st.mean(rows[d]['town'] for d in t28):.0f} / {st.mean(rows[d]['castle'] for d in t28):.0f} zl/d"
            + f"; s srednia {st.mean(rows[d]['avg'] for d in t28):.2f}%, max {max(rows[d]['max'] for d in t28):.2f}%"
            + f"; potrzeba (sr28 krolestw): K {st.mean(rows[d]['nLoan'] for d in t28):.1f}, Z {st.mean(rows[d]['nOver'] for d in t28):.1f}, S {st.mean(rows[d]['nLow'] for d in t28):.1f}",
            "INFO - odczyt, nie prog (wynika z potrzeby; [S] 30-60 tys./d)", None)
    rep.add("E5/B2 B2-12: wstrzymane w oblezeniu (R22, suma okna)", f"{sum(rows[d]['held'] for d in ds)} zl ({sum(rows[d]['heldN'] for d in ds)} poborow)",
            "INFO - oblezona osada nie placi (bramka BesiegedPay, rodzaj 184)", None)
    # B2-13: Obieg (korona) = linia 184 tej samej doby (LastFolkWarTax)
    obg = by_day(lines, "Obieg: dzien")
    ncmp, diff = 0, []
    for d in ds:
        if d in obg:
            v = num(r"podatek wojenny ludu \(184\) kiesy ludu -> skarbce (\d+)", obg[d])
            if v is None:
                continue
            ncmp += 1
            if v != rows[d]["taken"]:
                diff.append(d)
    rep.add("E5/B2 B2-13: Obieg (korona) = pobrano w linii 184 tej doby", f"porownanych dob {ncmp}, roznych {len(diff)}" + (f" (pierwsza {diff[0]})" if diff else ""),
            "0 roznych", (len(diff) == 0) if ncmp else None)
    errs = [s for s in lines if s.startswith("ERROR in ") and "KingdomTreasury.WarTax" in s]
    stm = sum(rows[d]["stum"] for d in ds)
    rep.add("E5/B2 B2-14: bledy KingdomTreasury.WarTax, potkniecia (suma)", f"bledy {len(errs)}, potkniecia {stm}" + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0",
            len(errs) == 0 and stm == 0)


def etap5_b3(rep, lines, start, until, eq, logp=None, csvp=None):
    """E5/B3 (Z15-5, PLAN 5.7 - wyrownanie dla panow zamkow: R4 zawor kasy miasta pan 1/2 : korona 1/2, R16 renty korony wedlug wag lenn 2 / 1.5 / 0.25):
    projekt rozdz. 3 "E5/B3" Test i rozdz. 4 (progi panow zamkow; zbior B, z kiesa ludu B1). Linia "Wyrownanie panow zamkow (E5/B3): dzien N" (dzien gry;
    eq ma klucz = dzien ksiegi, jak 165/180) - po rentach 180. Wiersze B3-1..B3-10: linia, stan (czynne caly bieg B - K3), zawor (udzial korony z kwot =
    1 - udzial pana z linii), wartosci czynne zgodne z regula i z linia 180, udzial panow samych zamkow w D swiata (prog glowny, srednia d252-364) i w D stalym
    (30-35%), mediana kiesy (odczyt - srednia 4 blokow 28 dob), renty dnia wedlug rodzaju rodu, gracz, bledy."""
    win = sorted(d for d in eq if 1 <= run_day(d, start) <= until)
    alld = sorted(d for d in by_day(lines, "Pieniadz swiata: dzien") if 1 <= run_day(d, start) <= until)
    r180 = e4_series(lines, "Renty korony (180): dzien", 1)
    rst = re.compile(r"\| wylacznik Castle Lords Even Up (tak|nie), kiesa ludu \(B1\) (czynna|nieczynna) -> wyrownanie (CZYNNE|NIECZYNNE)")
    rzv = re.compile(r"\| zawor kas miast \(A1 (czynny|nieczynny)[^)]*\): panu ([\d.]+)%, koronie ([\d.]+)% \(z wyrownaniem ([\d.]+)%, bez ([\d.]+)%")
    rwg = re.compile(r"\| wagi rent korony \(180 (czynne|nieczynne)\): miasto ([\d.]+), zamek ([\d.]+), wies ([\d.]+) \(z wyrownaniem ([\d.]+) / ([\d.]+) / ([\d.]+),"
                     r" bez ([\d.]+) / ([\d.]+) / ([\d.]+)\)")
    rzd = re.compile(r"\| zawor dzis: panom (\d+) \(w krolestwach przed dekretem (\d+)\) \+ koronie (\d+)")
    rrd = re.compile(r"\| renty korony dzis (\d+): rody samych zamkow (\d+) \(rodow (\d+), z renta (\d+); wag ([\d.]+)%, rent ([\d.]+)%\), rody z miastem (\d+)"
                     r" \(rodow (\d+), z renta (\d+); wag ([\d.]+)%, rent ([\d.]+)%\), rod gracza (\d+) \(wag ([\d.]+)%\)")
    rpl = re.compile(r"\| gracz: zawor \(czesc pana\) (\d+), renta (\d+)")
    rows = {}
    for d in win:
        s = eq[d]
        a, z, w, v, r, p = rst.search(s), rzv.search(s), rwg.search(s), rzd.search(s), rrd.search(s), rpl.search(s)
        if not (a and z and w and v and r and p):
            continue
        rows[d] = {"key": a.group(1) == "tak", "folk": a.group(2) == "czynna", "live": a.group(3) == "CZYNNE",
                   "valve": z.group(1) == "czynny", "lord": float(z.group(2)), "lordW": float(z.group(4)), "lordB": float(z.group(5)),
                   "w": tuple(float(w.group(i)) for i in (2, 3, 4)), "wW": tuple(float(w.group(i)) for i in (5, 6, 7)), "wB": tuple(float(w.group(i)) for i in (8, 9, 10)),
                   "rentsOn": w.group(1) == "czynne",
                   "vLord": int(v.group(1)), "vBaseK": int(v.group(2)), "vCrown": int(v.group(3)),
                   "rAll": int(r.group(1)), "rCastle": int(r.group(2)), "nCastle": int(r.group(3)), "pCastle": int(r.group(4)), "wCastle": float(r.group(5)),
                   "shCastle": float(r.group(6)), "rTown": int(r.group(7)), "nTown": int(r.group(8)), "wTown": float(r.group(10)), "shTown": float(r.group(11)),
                   "rPlayer": int(r.group(12)), "pValve": int(p.group(1)), "pRent": int(p.group(2)),
                   "stum": num(r"\| potkniecia (\d+)\.", s, int, 0) or 0}
    exp = sorted(set(alld) | set(win))
    miss = [d for d in exp if d not in rows]
    rep.add("E5/B3 B3-1: linia Wyrownanie panow zamkow (E5/B3) codziennie (czytelna)", f"brak/nieczytelna w {len(miss)} z {len(exp)} dob" + (f" (pierwsza {miss[0]})" if miss else ""),
            "0 (LogEnabled)", (len(miss) == 0) if exp else None)
    if not rows:
        return
    ds = sorted(rows)
    # B3-2: wyrownanie czynne caly bieg zbioru B (K3: tylko z czynna kiesa ludu; nieczynne = udzial 2/3 i wagi 3/1/0.25 sprzed paczki)
    off = [d for d in ds if not rows[d]["live"]]
    nofolk = len([d for d in ds if not rows[d]["folk"]])
    nokey = len([d for d in ds if not rows[d]["key"]])
    rep.add("E5/B3 B3-2: wyrownanie CZYNNE (wylacznik Castle Lords Even Up i kiesa ludu B1 czynna)",
            f"nieczynne w {len(off)} z {len(ds)} dob (kiesa ludu nieczynna {nofolk}, wylacznik wylaczony {nokey})" + (f" (pierwsza {off[0]})" if off else ""),
            "czynne caly bieg zbioru B (nieczynne - zawor 2/3 i wagi 3/1/0.25 jak przed paczka - K3)", len(off) == 0)
    # B3-3: zawor - udzial korony z kwot dnia = 1 - udzial pana z linii (doby z czynnym wyrownaniem i zaworem A1, ostatnie 28 takich dob)
    vd = [d for d in ds if rows[d]["live"] and rows[d]["valve"] and rows[d]["vBaseK"] + rows[d]["vCrown"] > 0][-28:]
    if vd:
        kk = sum(rows[d]["vCrown"] for d in vd)
        bb = sum(rows[d]["vBaseK"] + rows[d]["vCrown"] for d in vd)
        ex = sum((1.0 - rows[d]["lord"] / 100.0) * (rows[d]["vBaseK"] + rows[d]["vCrown"]) for d in vd) / bb
        q = kk / bb
        rep.add("E5/B3 B3-3: zawor kas miast - udzial korony K / (LBk + K) przy wyrownaniu (sr28 dob czynnych)",
                f"{q:.3f} wobec {ex:.3f} (1 - udzial pana z linii; {len(vd)} dob; koronie {kk}, podstawa {bb})",
                "+-0.01 (Z15-5: 1/2 - korona 0.49-0.51 przy kluczu 0.5)", abs(q - ex) <= 0.01)
    else:
        rep.add("E5/B3 B3-3: zawor kas miast - udzial korony przy wyrownaniu", "brak dob z czynnym wyrownaniem i zaworem A1 (z poborem)",
                "+-0.01 wobec 1 - udzial pana (zbior B)", None)
    # B3-4: wartosci czynne zgodne z regula (czynne - klucze With Folk, nieczynne - klucze sprzed B3) i wagi w linii 180 te same co w linii B3
    bad4 = []
    n180 = 0
    for d in ds:
        x = rows[d]
        want_l, want_w = (x["lordW"], x["wW"]) if x["live"] else (x["lordB"], x["wB"])
        if abs(x["lord"] - want_l) > 0.05 or any(abs(a - b) > 1e-6 for a, b in zip(x["w"], want_w)):
            bad4.append((d, "regula"))
            continue
        s180 = r180.get(d)
        if s180:
            m = re.search(r"\| wagi: miasto ([\d.]+), zamek ([\d.]+), wies ([\d.]+) \(E5/B3: (z wyrownaniem|bez wyrownania)\)", s180)
            if m:
                n180 += 1
                if any(abs(float(m.group(i + 1)) - x["w"][i]) > 1e-6 for i in range(3)) or (m.group(4) == "z wyrownaniem") != x["live"]:
                    bad4.append((d, "linia 180"))
    lv = [d for d in ds if rows[d]["live"]]
    last = rows[ds[-1]]
    rep.add("E5/B3 B3-4: wartosci czynne zgodne z regula; wagi w linii Renty korony (180) = linia B3",
            f"niezgodnych {len(bad4)} z {len(ds)} dob (porownanych z 180: {n180})" + (f" (pierwsza {bad4[0]})" if bad4 else "")
            + f"; ostatnia doba: panu {last['lord']:.1f}%, wagi {last['w'][0]:g} / {last['w'][1]:g} / {last['w'][2]:g} ({'z wyrownaniem' if last['live'] else 'bez wyrownania'})",
            "0 (czynne: 50% i 2 / 1.5 / 0.25 przy domyslnych; nieczynne: 67% i 3 / 1 / 0.25)", len(bad4) == 0)
    # narzedzie progow p2 (TRIAZ-2 O2-2 "Poprawka ostateczna" pkt 4a): rody z lennem bez warunku renty korony (pole "bez warunku N (P%)" linii 180),
    # srednia d31-until <= 20% - prog projektu etapu 2 (C1-POSTEP: "bez warunku < 20%"), dotad bez wiersza. Niespelniony w zadnym biegu (a589def 32.4%,
    # W33 27.7%, bieg 2 zbior-e8 35.8% - Polnoc: renta u 2 z 20 rodow przez 80 dob) - NIE do czasu poprawki warunku sluzby (CrownRents.Daily).
    nc = [fnum(r"z warunkiem \d+, bez warunku \d+ \(([0-9.]+)%\)", s) for d, s in r180.items() if 31 <= run_day(d, start) <= until]
    nc = [v for v in nc if v is not None]
    if nc:
        rep.add(f"180: rody z lennem bez warunku renty korony, srednia d31-{until}", f"{sum(nc) / len(nc):.1f}% ({len(nc)} dob, najwiecej {max(nc):.1f}%)",
                "<= 20% (prog projektu etapu 2; a589def 32.4%, W33 27.7% - NIE = czeka na poprawke warunku sluzby, TRIAZ-2 O2-2)", sum(nc) / len(nc) <= 20.0)
    # B3-5..B3-7: panowie samych zamkow (budzet-rodow.csv; rodzaj "zamek" = rod z zamkami bez miasta, gracz poza)
    csvp = csvp or (csv_path_of(logp) if logp else None)
    crow = read_csv(csvp) if csvp else []
    if not crow:
        rep.add("E5/B3 B3-5..B3-7: panowie samych zamkow (budzet-rodow.csv)", f"brak {csvp}", "udzial w D swiata >= 30% (d252-364)", None)
    else:
        byd = {}
        for r in crow:
            try:
                byd.setdefault(int(r.get("dzien") or 0), []).append(r)
            except ValueError:
                continue
        cd = sorted(d for d in byd if 1 <= run_day(d, start) <= until)
        # narzedzie progow p2 - recenzja (TRIAZ-2 O2-2 "Poprawka ostateczna" pkt 4b i O2-1 pkt 1 "Sprawdzic"): kolumna "warunek_180" pliku budzet-rodow.csv
        # ("<status> S/N" = rod sluzyl S z wymaganych N dob). Status "sluzba" albo "zaloga+sluzba" przy N < 7 = rod traci rente za sluzbe w wojnie, ktora
        # krolestwo widzialo krocej niz CrownRentServiceDays (20) dob: regula proporcjonalna ponizej 60 dob styku daje wtedy wymog 1-6 dob (bieg 2 zbior-e8:
        # doba 60 - 41 rodow, Polnoc bez renty u 18 z 20 rodow przez 80 dob). Po poprawce warunku sluzby pierwszy wymog to 7 z 20 (przy 20 dobach styku),
        # wiec takich rodo-dob ma byc 0 w calym oknie. Kolumna istnieje od paczki 180 - wiersz czyta stan dzisiejszy; CSV bez kolumny - bez wiersza.
        w180 = [(d, (r.get("warunek_180") or "").strip()) for d in cd for r in byd[d]]
        if any(v for _, v in w180):
            low = {}
            for d, v in w180:
                m = re.match(r"(\S+) (\d+)/(\d+)", v)
                if m and "sluzba" in m.group(1) and int(m.group(3)) < 7:
                    low[d] = low.get(d, 0) + 1
            top = max(low, key=lambda d: (low[d], -d)) if low else None
            rep.add("180 (CSV): rody bez renty za sluzbe przy wymogu ponizej 7 dob (warunek_180: sluzba / zaloga+sluzba S/N, N < 7) - rodo-doby okna",
                    f"{sum(low.values())} rodo-dob w {len(low)} z {len(cd)} dob"
                    + (f"; najwiecej {low[top]} rodow (d{run_day(top, start)}), ostatnia doba {low.get(cd[-1], 0)}" if low else ""),
                    "0 (wymog sluzby dopiero od 20 dob wojny ze stykiem - pierwszy wymog 7 z 20, przy domyslnym Crown Rent Service Days; NIE = czeka na "
                    "poprawke warunku sluzby, TRIAZ-2 O2-2 pkt 4b)", not low)
        wd = [d for d in cd if 252 <= run_day(d, start) <= 364]
        # werdykt TAK/NIE tylko przy calym oknie d252-364 (113 dob CSV; luz na kilka brakujacych dob i koniec biegu tuz przed d364); okno niepelne
        # (bieg przerwany, --do-doby < 364) = odczyt INFO z dob okna, a bez 28 dob okna - z ostatnich 28 dob biegu
        full = len(wd) >= 100 and run_day(wd[-1], start) >= 360
        use = wd if len(wd) >= 28 else cd[-28:]
        short = ("" if full else
                 (f" - okno niepelne ({len(wd)} z 113 dob d252-364; bieg przerwany albo --do-doby < 364): odczyt" if len(wd) >= 28
                  else " - bieg krotszy niz 279 dob (--do-doby 364): odczyt ostatnich 28 dob"))

        def fv(v):
            try:
                return float(v)
            except (TypeError, ValueError):
                return None
        shD, shS = [], []
        for d in use:
            tD = tS = zD = zS = 0.0
            for r in byd[d]:
                D, S = fv(r.get("D")) or 0.0, fv(r.get("d_staly")) or 0.0
                tD += D
                tS += S
                if r.get("rodzaj") == "zamek":
                    zD += D
                    zS += S
            if tD:
                shD.append(zD / tD)
            if tS:
                shS.append(zS / tS)
        mD, mS = _mean(shD), _mean(shS)
        span = f"doby {run_day(use[0], start)}-{run_day(use[-1], start)}" if use else "-"
        rep.add("E5/B3 B3-5: udzial panow samych zamkow w D swiata (srednia d252-364) - PROG GLOWNY",
                (f"{mD * 100:.1f}%" if mD is not None else "-") + f" ({span})" + short,
                ">= 30% (bieg A z31 d93-120: 30.1%)", (mD is not None and mD >= 0.30) if full else None)
        rep.add("E5/B3 B3-6: udzial panow samych zamkow w D stalym (srednia d252-364)",
                (f"{mS * 100:.1f}%" if mS is not None else "-") + f" ({span})" + short,
                "30-35% (bieg A z31: 24.3%)", (mS is not None and 0.30 <= mS <= 0.35) if full else None)
        # B3-7 (odczyt, v2 E5K1-10): zmiana mediany kiesy glowy w 4 blokach po 28 dob (d252-279, 280-307, 308-335, 336-363); tylko rody, ktorych krolestwo bylo
        # w wojnie >= 21 z 28 dob bloku; srednia blokow >= -2% - przy niezdanym, a B3-5 zdanym, B3 nie jest wylaczane (rozrzut blokow dzis 16 pkt)
        blocks = []
        for b in range(4):
            lo = 252 + 28 * b
            bd = [d for d in cd if lo <= run_day(d, start) <= lo + 27]
            if len(bd) < 21:
                continue
            war = {}
            for d in bd:
                for r in byd[d]:
                    if r.get("rodzaj") == "zamek" and r.get("wojna") == "1":
                        war[r.get("rod_id")] = war.get(r.get("rod_id"), 0) + 1
            need = min(21, max(1, len(bd) * 3 // 4))
            ids = {k for k, n in war.items() if n >= need}

            def med(d):
                ks = sorted(k for k in (fv(r.get("kiesa_glowy")) for r in byd[d] if r.get("rodzaj") == "zamek" and r.get("rod_id") in ids) if k is not None)
                return ks[len(ks) // 2] if ks else None
            m0, m1 = med(bd[0]), med(bd[-1])
            if m0 and m1 is not None:
                blocks.append((lo, (m1 / m0 - 1) * 100, len(ids)))
        if blocks:
            mb = _mean([x[1] for x in blocks])
            rep.add("E5/B3 B3-7: mediana kiesy panow samych zamkow w wojnie - srednia zmiany w blokach 28 dob d252-364 (odczyt)",
                    f"{mb:+.1f}% (bloki: " + ", ".join(f"d{x[0]} {x[1]:+.1f}% ({x[2]} rodow)" for x in blocks) + f"); >= -2%: {'tak' if mb >= -2 else 'nie'}",
                    "INFO - odczyt >= -2% (prog glowny B3-5; z31 d93-120: -2.5%)", None)
        else:
            rep.add("E5/B3 B3-7: mediana kiesy panow samych zamkow (bloki 28 dob d252-364)", "brak pelnych blokow (bieg krotszy niz 279 dob)", "INFO - odczyt (bieg roczny)", None)
    # B3-8: renty dnia wedlug rodzaju rodu (sr28) - czy wyrownanie trafia do panow samych zamkow
    t28 = _last28(lv if lv else ds)
    rep.add("E5/B3 B3-8: renty korony dnia - rody samych zamkow: udzial w rentach / w wagach (sr28" + (" dob z wyrownaniem" if lv else ", wyrownanie nieczynne") + ")",
            f"renty {st.mean(rows[d]['rAll'] for d in t28):.0f}/d, rodom samych zamkow {st.mean(rows[d]['rCastle'] for d in t28):.0f}/d"
            f" ({st.mean(rows[d]['shCastle'] for d in t28):.1f}% rent, {st.mean(rows[d]['wCastle'] for d in t28):.1f}% wag), rodom z miastem"
            f" {st.mean(rows[d]['shTown'] for d in t28):.1f}% rent / {st.mean(rows[d]['wTown'] for d in t28):.1f}% wag",
            "INFO - renta wedlug wag lenn za sluzbe (udzial rent < udzial wag = rody bez warunku albo krolestwa bez reszty po zwrocie)", None)
    rep.add("E5/B3 B3-9: gracz - ta sama regula (suma okna): zawor (czesc pana) / renta",
            f"{sum(rows[d]['pValve'] for d in ds)} / {sum(rows[d]['pRent'] for d in ds)} zl",
            "INFO - zawor jego miast i renta jego rodu jak u AI (decyzja Jeffa 09.10 E)", None)
    errs = [s for s in lines if s.startswith("ERROR in ") and "LordsEvenUp" in s]
    stm = sum(rows[d]["stum"] for d in ds)
    rep.add("E5/B3 B3-10: bledy LordsEvenUp, potkniecia (suma)", f"bledy {len(errs)}, potkniecia {stm}" + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0",
            len(errs) == 0 and stm == 0)


def _b5_segs(s):
    """Linia "Statki (181)" -> {klucz segmentu: tekst}; segmenty rozdziela " | " (kod ShipsToPort181.Daily)."""
    out = {}
    for seg in s.split(" | ")[1:]:
        for key, pre in (("sw", "wylaczniki:"), ("p1", "1. "), ("p2", "2. "), ("p3", "3. "), ("pk", "premie zarzadcow"), ("p4", "4. "),
                         ("tot", "razem naprawde dzis"), ("ov", "zakupy portow ponad liczbe idealna stoczni"), ("pp", "kasy portow (miasta z portem i stocznia)"),
                         ("err", "wyjatki zlapane")):
            if seg.startswith(pre):
                out[key] = seg
                break
    return out


def etap5_b5(rep, lines, start, until, sh):
    """E5/B5 (181 ON, PLAN 3.3): projekt etapu 5 rozdz. 3 "E5/B5" Test (zbior B) i rozdz. 5.2 pkt 9 (K3: bieg B ze statkami OFF = blad). Linia "Statki (181): dzien N"
    (dzien ksiegi, jak "Pieniadz swiata") z segmentem E5/B5 "kasy portow". Wiersze B5-1..B5-14: linia, trzy wylaczniki WL caly bieg, latki, zloto z niczego / w nicosc
    sciezek 181 = 0, kontrolki prog 0, nadwyzka portow z D4 (A1), kasy portow bez nadwyzki <= 28 dob, pozycje statkow w ksiedze = 0, zgodnosc z A6 i pomiarami
    (164a, E5/0) = 0, wyplaty portow / zloto swiata / wraki - INFO, bledy; B5-14 (po recenzji) zakupy portow ponad liczbe idealna stoczni i gracz bez ceny kupna - INFO."""
    alld = sorted(d for d in by_day(lines, "Pieniadz swiata: dzien") if 1 <= run_day(d, start) <= until)
    win = sorted(d for d in sh if 1 <= run_day(d, start) <= until)
    rsw = re.compile(r"do portu \(Ships To Port\) (WL|WYL), handel przez kase portu \(Ship Trade Through Port\) (WL|WYL), pryzy do portu \(Ship Prizes To Port\) (WL|WYL)")
    rtot = re.compile(r"z niczego (-?\d+), w nicosc (-?\d+), netto (-?\d+); kasy portow wydaly \(181\) (\d+) w (\d+) portach, przyjely (\d+); wyplaty ponad nadwyzke (\d+) \(prog 0\),"
                      r" statki przekazane za 0 zl (\d+) \(prog 0\)")
    rpp = re.compile(r"kasy portow \(miasta z portem i stocznia\) (\d+), nadwyzka (z D4 TownPurse \(A1 czynne\)|ze starej formuly[^:]*): bez nadwyzki dzis (\d+)"
                     r" \(nadwyzka portow razem (\d+)\), najdluzej bez nadwyzki (\d+) dob z rzedu \((.*?)\), >= 7 dob (\d+), >= 28 dob (\d+)")
    rreal = re.compile(r"regula 181 - naprawde: statkow (\d+): nalezne (\d+), zaplacone (\d+)")
    rscrap = re.compile(r"zlom: brak portu z miejscem (\d+), brak pieniedzy (\d+)")
    rows = {}
    for d in win:
        s = sh[d]
        g = _b5_segs(s)
        a, t, p = rsw.search(g.get("sw", "")), rtot.search(g.get("tot", "")), rpp.search(g.get("pp", ""))
        if not (a and t and p):
            continue
        r1, r4 = rreal.search(g.get("p1", "")), rreal.search(g.get("p4", ""))
        s1, s4 = rscrap.search(g.get("p1", "")), rscrap.search(g.get("p4", ""))
        rows[d] = {"lost": a.group(1) == "WL", "trade": a.group(2) == "WL", "prize": a.group(3) == "WL",
                   "from": int(t.group(1)), "to": int(t.group(2)), "spent": int(t.group(4)), "nports": int(t.group(5)), "took": int(t.group(6)),
                   "over": int(t.group(7)), "free": int(t.group(8)),
                   "ports": int(p.group(1)), "d4": p.group(2).startswith("z D4"), "dry": int(p.group(3)), "spare": int(p.group(4)), "streak": int(p.group(5)),
                   "streakName": p.group(6), "w28": int(p.group(8)),
                   "paid1": int(r1.group(3)) if r1 else 0, "due1": int(r1.group(2)) if r1 else 0, "paid4": int(r4.group(3)) if r4 else 0, "due4": int(r4.group(2)) if r4 else 0,
                   "noMoney": (int(s1.group(2)) if s1 else 0) + (int(s4.group(2)) if s4 else 0),
                   "game1": num(r"zloto gry \(dzis z niczego[^)]*\) (\d+) - wedlug", g.get("p1", ""), int, 0) or 0,
                   "removed4": num(r"zdjete z lupu zwyciezcow (\d+)", g.get("p4", ""), int, 0) or 0,
                   "sell2": num(r"; z kas portow (\d+)", g.get("p2", ""), int, 0) or 0,
                   "buy3": num(r"; do kas portow (\d+)", g.get("p3", ""), int, 0) or 0,
                   "wrecks": num(r"wraki po uszkodzeniu po bitwie \(gra nie placi, 181 nie rusza - E5/B5\) (\d+)", g.get("p4", ""), int, 0) or 0,
                   "hasOv": "ov" in g,
                   "ovN": num(r"\): naprawde (\d+) / \d+", g.get("ov", ""), int, 0) or 0,
                   "ovGold": num(r"\): naprawde \d+ / (\d+)", g.get("ov", ""), int, 0) or 0,
                   "shortBuy": num(r"kupno przed sprzedaza w jednym potwierdzeniu, pominiete \(E5/B5\) (\d+)", g.get("p3", ""), int, 0) or 0,
                   "stum": num(r"wyjatki zlapane (\d+)", g.get("err", ""), int, 0) or 0}
    exp = sorted(set(alld) | set(win))
    miss = [d for d in exp if d not in rows]
    rep.add("E5/B5 B5-1: linia Statki (181) codziennie (czytelna, z segmentem kas portow E5/B5)", f"brak/nieczytelna w {len(miss)} z {len(exp)} dob" + (f" (pierwsza {miss[0]})" if miss else ""),
            "0 (LogEnabled)", (len(miss) == 0) if exp else None)
    if not rows:
        return
    ds = sorted(rows)
    # B5-2: trzy wylaczniki WL caly bieg zbioru B (K3: bieg B ze statkami OFF - blad)
    off = [d for d in ds if not (rows[d]["lost"] and rows[d]["trade"] and rows[d]["prize"])]
    rep.add("E5/B5 B5-2: wylaczniki Ships To Port, Ship Trade Through Port, Ship Prizes To Port WLACZONE",
            f"ktorys WYL w {len(off)} z {len(ds)} dob (do portu WYL {sum(1 for d in ds if not rows[d]['lost'])}, handel WYL {sum(1 for d in ds if not rows[d]['trade'])},"
            f" pryzy WYL {sum(1 for d in ds if not rows[d]['prize'])})" + (f" (pierwsza {off[0]})" if off else ""),
            "WL caly bieg zbioru B (WYL = MCM/Armoury.json z wartoscia sprzed B5 - pulapka MCM)", len(off) == 0)
    # B5-3: latki (linia startowa kazdej sesji) i cudze latki na naszych metodach
    stl = [s for s in lines if s.startswith("Statki (181): latki - ")]
    hk = [s for s in lines if s.startswith("Statki (181) - start sesji:")]
    bad3 = [s for s in stl if ("BRAK" in s or " NIE" in s.split(". Wylaczniki")[0] or "podmienione zaplaty 8/8" not in s
                               or "handel 1/1" not in s or "naprawa 1/1" not in s)]
    foreign = sorted({_grp(r"cudze latki na naszych metodach: (.*?)\.$", s, 1) for s in hk})
    rep.add("E5/B5 B5-3: latki 181 wpiete (linia startowa kazdej sesji: 10 latek, podmienione zaplaty 8/8 + 1/1 + 1/1)",
            f"sesji {len(stl)}, z brakiem {len(bad3)}; cudze latki na naszych metodach: {', '.join(foreign) if foreign else '-'}",
            "0 sesji z brakiem (BRAK/NIE = gra albo NavalDLC inne niz 1.4.8 - wylaczyc B5)", (len(bad3) == 0) if stl else None)
    on = [d for d in ds if rows[d]["lost"] and rows[d]["trade"] and rows[d]["prize"]]
    # B5-4: zloto z niczego / w nicosc sciezek 181 przy trzech WL = 0 (wyjatek w sprzedazy oddaje grze - licznik B5-13)
    f4 = sum(rows[d]["from"] for d in on)
    t4 = sum(rows[d]["to"] for d in on)
    rep.add("E5/B5 B5-4: sciezki statkow - zloto z niczego / w nicosc przy trzech WL (suma dob WL)", f"{f4} / {t4} ({len(on)} dob)",
            "0 / 0 (R18: rozbita druzyna, handel z portem i pryzy przez kase portu)", (f4 == 0 and t4 == 0) if on else None)
    # B5-5: kontrolki prog 0
    ov, fr = sum(rows[d]["over"] for d in ds), sum(rows[d]["free"] for d in ds)
    rep.add("E5/B5 B5-5: kontrolki - wyplaty ponad nadwyzke portu / statki przekazane za 0 zl (suma)", f"{ov} / {fr}", "0 / 0", ov == 0 and fr == 0)
    # B5-6: porty placa z nadwyzki D4 (A1) - caly bieg
    nod4 = [d for d in ds if not rows[d]["d4"]]
    rep.add("E5/B5 B5-6: nadwyzka portow = D4 TownPurse (A1 czynne)", f"stara formula w {len(nod4)} z {len(ds)} dob" + (f" (pierwsza {nod4[0]})" if nod4 else ""),
            "D4 caly bieg (projekt R18: porty z TownPurse.Spare)", len(nod4) == 0)
    # B5-7: kasy portow bez nadwyzki (kasa <= zapas kupcow) nie dluzej niz 28 dob z rzedu
    worst = max(ds, key=lambda d: rows[d]["streak"])
    t28 = _last28(ds)
    rep.add("E5/B5 B5-7: kasy portow bez nadwyzki - najdluzsza seria dob z rzedu (pamiec sesji)",
            f"{rows[worst]['streak']} dob ({rows[worst]['streakName']}, dzien {worst}); portow {rows[ds[-1]]['ports']}, bez nadwyzki sr28 {st.mean(rows[d]['dry'] for d in t28):.1f},"
            f" >= 28 dob maks. {max(rows[d]['w28'] for d in ds)}; nadwyzka portow razem sr28 {st.mean(rows[d]['spare'] for d in t28):.0f}",
            "<= 28 dob (projekt E5/B5 Test)", rows[worst]["streak"] <= 28)
    # B5-8: pozycje statkow w ksiedze pieniadza (Pieniadz swiata - przyczyny) przy trzech WL = 0
    bal = by_day(lines, "Pieniadz swiata (bilans - przyczyny): dzien")
    zs = zo = uk = uo = 0
    nb = 0
    for d in on:
        s = bal.get(d)
        if not s:
            continue
        segs = s.split(" | ")
        zr = next((x for x in segs if x.startswith("ZRODLA")), "")
        uj = next((x for x in segs if x.startswith("UJSCIA")), "")
        zs += num(r"statki: sprzedaz osadom i premie zarzadcow (-?\d+)", zr, int, 0) or 0
        zo += num(r"statki NavalDLC inne (-?\d+)", zr, int, 0) or 0
        uk += num(r"statki: kupno od osad (-?\d+)", uj, int, 0) or 0
        uo += num(r"statki NavalDLC inne (-?\d+)", uj, int, 0) or 0
        nb += 1
    rep.add("E5/B5 B5-8: ksiega - ZRODLA statki (sprzedaz osadom i premie; NavalDLC inne) / UJSCIA statki (kupno od osad; NavalDLC inne), doby trzech WL",
            f"{zs} + {zo} / {uk} + {uo} ({nb} dob)", "0 / 0 (bieg E4 bez B5: ok. 0.4 mln/d z niczego)", (zs == 0 and zo == 0 and uk == 0 and uo == 0) if nb else None)
    # B5-9: zgodnosc z A6 i pomiarami (dopisek pryzow zdjety przed rozliczeniem A6 i finalizerem 164a; zwrot 164a bez wyplat portow)
    a6 = by_day(lines, "Lup w bitwie (A6): dzien")
    m164 = by_day(lines, "Szczelnosc (164a): dzien")
    b50 = by_day(lines, "Bitwy (E5/0): dzien")
    pa6 = p164 = r164 = p50 = 0
    n9 = 0
    for d in ds:
        x = rows[d]
        if x["prize"]:
            if d in a6:
                pa6 += num(r"wyplacone z niczego (\d+)", a6[d], int, 0) or 0
                n9 += 1
            if d in m164:
                p164 += num(r"bitwach morskich \(PlunderedGold\) (-?\d+)", m164[d], int, 0) or 0
                n9 += 1
            if d in b50:
                p50 += num(r"\| statki zatopione (-?\d+)", b50[d], int, 0) or 0
                n9 += 1
        if x["lost"] and d in m164:
            m = re.search(r"zwrot za statki: przy rozwiazaniu (-?\d+) \(\d+\), przy zniszczeniu na ladzie (-?\d+) \(\d+\), poza oknami (-?\d+)", m164[d])
            if m:
                r164 += int(m.group(1)) + int(m.group(2)) + int(m.group(3))
                n9 += 1
    rep.add("E5/B5 B5-9: zgodnosc z A6 i pomiarami - statki z niczego: A6 / 164a pryzy / E5/0 Bitwy / 164a zwrot (suma dob WL)",
            f"{pa6} / {p164} / {p50} / {r164}", "0 / 0 / 0 / 0 (dopisek pryzow zdjety przed A6 i 164a; zwrot 164a bez wyplat portow)",
            (pa6 == 0 and p164 == 0 and p50 == 0 and r164 == 0) if n9 else None)
    # B5-10..12: INFO - wyplaty portow, zloto z niczego zastapione i zloto swiata, wraki
    rep.add("E5/B5 B5-10: wyplaty portow sr28 (INFO): rozbite druzyny / pryzy / sprzedaz AI i graczu; kasy portow wydaly / przyjely; zlom z braku pieniedzy",
            f"{st.mean(rows[d]['paid1'] for d in t28):.0f} (z naleznych {st.mean(rows[d]['due1'] for d in t28):.0f}) / {st.mean(rows[d]['paid4'] for d in t28):.0f}"
            f" (z {st.mean(rows[d]['due4'] for d in t28):.0f}) / {st.mean(rows[d]['sell2'] for d in t28):.0f}; kasy portow wydaly {st.mean(rows[d]['spent'] for d in t28):.0f}"
            f" w {st.mean(rows[d]['nports'] for d in t28):.1f} portach, przyjely {st.mean(rows[d]['took'] for d in t28):.0f}; zlom z braku pieniedzy {sum(rows[d]['noMoney'] for d in t28)} statkow",
            "INFO (rabat AI 0.01 przy kupnie - 181d - zostaje do pomiaru, projekt rozdz. 7)", None)
    pw = by_day(lines, "Pieniadz swiata: dzien")
    pd = [d for d in alld if d in pw]
    ch = "-"
    if len(pd) >= 2:
        a0 = pd[-29] if len(pd) > 28 else pd[0]
        za, zb = num(r"\| razem (\d+)", pw[a0]), num(r"\| razem (\d+)", pw[pd[-1]])
        if za and zb is not None:
            ch = f"{(zb - za) / max(1, pd[-1] - a0):+.0f}/d ({(zb - za) / za * 100:+.2f}% d{run_day(a0, start)}-d{run_day(pd[-1], start)})"
    rep.add("E5/B5 B5-11: zloto z niczego zastapione przez porty sr28 (zloto gry za rozbite druzyny + zdjete z lupu pryzow) i zloto swiata (INFO)",
            f"{st.mean(rows[d]['game1'] + rows[d]['removed4'] for d in t28):.0f}/d; zloto swiata {ch}",
            "INFO - wobec biegu bez B5 (bieg E4 bez B5: statki NavalDLC ok. 0.37-0.43 mln/d z niczego)", None)
    rep.add("E5/B5 B5-12: wraki po uszkodzeniu po bitwie - gra nie placi, 181 nie rusza (suma, INFO)", sum(rows[d]["wrecks"] for d in ds), "INFO", None)
    errs = [s for s in lines if s.startswith("ERROR in ShipsToPort181")]
    stm = sum(rows[d]["stum"] for d in ds)
    rep.add("E5/B5 B5-13: bledy ShipsToPort181, wyjatki zlapane (suma)", f"bledy {len(errs)}, wyjatki {stm}" + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0",
            len(errs) == 0 and stm == 0)
    # B5-14 (poprawka po recenzji B5): zakupy portow, przy ktorych port mial juz liczbe idealna stoczni NavalDLC (limit - 2) - nadmiar, ktory stocznia
    # kasuje nastepnej doby (TryRemoveExcessShipsFromTown); miejsce do limitu zostaje (wiazace) - decyzja Jeffa; gracz bez ceny kupna (kupno przed sprzedaza)
    ovd = [d for d in ds if rows[d]["hasOv"]]
    if ovd:
        t28o = _last28(ovd)
        og, spo = sum(rows[d]["ovGold"] for d in t28o), sum(rows[d]["spent"] for d in t28o)
        rep.add("E5/B5 B5-14: zakupy portow ponad liczbe idealna stoczni (limit - 2) sr28; gracz bez ceny kupna - pominiete (suma) - INFO",
                f"{st.mean(rows[d]['ovN'] for d in t28o):.1f} statkow / {og / len(t28o):.0f} zl na dobe = {(og / spo * 100) if spo else 0:.1f}% wydatkow portow (181);"
                f" gracz {sum(rows[d]['shortBuy'] for d in ds)}",
                "INFO - decyzja Jeffa: miejsce w porcie do liczby idealnej zamiast limitu stoczni (mniej odplywu z kas portow, wiecej zlomu - mniej zlota lordow)", None)
    else:
        rep.add("E5/B5 B5-14: zakupy portow ponad liczbe idealna stoczni - INFO", "brak pola w logu (linie 181 sprzed poprawki po recenzji B5)", "INFO", None)


def etap5_b4(rep, lines, start, win):
    """E5/B4 (199, PLAN 5.11, R17 - targ przy zamku): projekt etapu 5 rozdz. 3 "E5/B4" Test (zbior B). Linia startowa "CastleMarket (E5/B4)" (sprzedaz w zamku
    i straz przed BK VillagersCastleTick wpiete), dzienna "Targ przy zamku (5.11): dzien N" (dzien ksiegi = dzien gry - 1, jak "Dowoz:"). Progi: sprzedaz do dni
    popytu > 0, powtorne wizyty 0, zatkane magazyny wsi zamkowych osobno lato (<= 5.6%) i zima (INFO wobec biegu A: 6.5%), reszta ladunku do miasta (wrocone do domu
    z ladunkiem <= 5% wozow wyslanych dalej), bledy i potkniecia 0. Zamki z polka ponizej dni zuzycia (wobec biegu A), odmowy (Spendable), rozbite tabory - INFO."""
    stl = [x for x in lines if x.startswith("CastleMarket (E5/B4):")]
    tm = by_day(lines, "Targ przy zamku (5.11): dzien")
    days = [d for d in win if d in tm]
    # B4-1: linia startowa
    if not stl:
        rep.add("E5/B4 B4-1: linia startowa CastleMarket (E5/B4)", "brak linii startowej", "wpiete: sprzedaz w zamku, straz BK; BRAK: -", None)
    else:
        x = stl[-1]
        brak = re.search(r"; BRAK: (.*?); wlasciciele", x)
        ok = "sprzedaz w zamku" in x and "straz przed odeslaniem do domu" in x and brak is not None and brak.group(1).strip() == "-"
        rep.add("E5/B4 B4-1: linia startowa CastleMarket (E5/B4)", ("BRAK: " + brak.group(1) if brak else x[:160]),
                "wpiete: sprzedaz w zamku (prefiks High) i straz przed BK VillagersCastleTick; BRAK: -", ok)
    # B4-2: linia dzienna w kazdej dobie okna, stan CZYNNY
    on = [d for d in days if "| CZYNNY |" in tm[d]]
    off = [d for d in days if "| WYLACZONY" in tm[d]]
    dead = [d for d in days if "| NIECZYNNY" in tm[d]]
    rep.add("E5/B4 B4-2: linia dzienna Targ przy zamku (5.11), stan CZYNNY",
            f"dob z linia {len(days)} z {len(win)}, CZYNNY {len(on)}, WYLACZONY {len(off)}, NIECZYNNY {len(dead)}"
            + (f" (pierwsza: {tm[dead[0]].split(' | ')[1][:120]})" if dead else ""),
            "kazda doba okna z linia i CZYNNY (bieg zbioru B)", (len(days) == len(win) and len(on) == len(days)) if win else None)
    if not days:
        return

    def tot(pat):
        return sum(num(pat, tm[d], int, 0) or 0 for d in days)
    visits, sold, gold, onward = tot(r"\| wizyt (\d+),"), tot(r"jedzenie sprzedane zamkom (\d+) szt\."), tot(r"szt\. \((\d+) zl wedlug"), tot(r"dalej do miasta (\d+) wozow")
    empty, fall, routed = tot(r"pusty po zamku (\d+)"), tot(r"bez miasta dalej \(zamek kupil (?:reszte|caly woz) jak dotad\) (\d+)"), tot(r"skierowane do zamku (\d+) \(")
    # B4-3: sprzedaz do dni popytu > 0
    rep.add("E5/B4 B4-3: jedzenie sprzedane zamkom (do dni popytu podzamcza)",
            f"skierowane {routed}, wizyt {visits}, sprzedane {sold} szt. ({gold} zl wedlug ceny pierwszej sztuki), dalej do miasta {onward}, pusty po zamku {empty}, bez miasta dalej {fall}",
            "> 0 w oknie (zamki z brakiem jedzenia kupuja od wozow swoich wsi)", sold > 0 if on else None)
    # B4-4: powtorne wizyty bez znacznika
    rep_d = [run_day(d, start) for d in days if (num(r"powtorne wizyty bez znacznika: (\d+)", tm[d], int, 0) or 0) > 0]
    rep.add("E5/B4 B4-4: powtorne wizyty bez znacznika (petla zamek-zamek)", f"dob z powtorna wizyta {len(rep_d)}" + (f" (d{', d'.join(str(x) for x in rep_d[:6])})" if rep_d else ""),
            "0 kazdej doby", len(rep_d) == 0)
    # B4-5: zamki z polka ponizej dni zuzycia - popyt BK (ta linia) i ten sam pomiar co E5/0 (zjedzone, srednia 7 dob) wobec biegu A
    lowre = re.compile(r"zamki z polka < ([\d.]+) dni zuzycia podzamcza \(popyt BK\): (\d+) z (\d+) \(mediana ([\d.\-]+) dni")
    rows = [lowre.search(tm[d]) for d in days]
    rows = [m for m in rows if m]
    l28 = _last28(days)
    m28 = [lowre.search(tm[d]) for d in l28]
    m28 = [m for m in m28 if m]
    first7 = rows[:7]
    fmean = _mean([int(m.group(2)) for m in first7])
    lmean = _mean([int(m.group(2)) for m in m28])
    e50 = by_day(lines, "Jedzenie z targu (E5/0): dzien")
    e28 = _mean([num(r"polka < 10 dni zuzycia: (\d+) z", e50[d]) for d in l28 if d in e50])
    rep.add("E5/B4 B4-5: zamki z polka jedzenia ponizej dni zuzycia podzamcza",
            (f"popyt BK: d1-7 sr {fmean:.1f}, sr28 {lmean:.1f} z {m28[-1].group(3)} (mediana dni ostatniej doby {m28[-1].group(4)})" if (fmean is not None and lmean is not None and m28) else "brak odcinka")
            + (f" | pomiar E5/0 (zjedzone, srednia 7 dob) sr28 {e28:.1f}" if e28 is not None else " | brak linii E5/0"),
            "INFO - mniej niz w biegu A (ten sam pomiar: linia Jedzenie z targu (E5/0) biegu A; popyt BK - od d1-7 do sr28 maleje)", None)
    # B4-6: zatkane magazyny wsi zamkowych - lato i zima osobno
    dow = by_day(lines, "Dowoz (skutki): dzien")
    fam = e4_series(lines, "Spichlerze (E4/6): dzien")
    clog = re.compile(r"zatkane magazyny: wsie zamkowe (\d+) z (\d+)")
    summer, winter = [], []
    for d in win:
        m = clog.search(dow.get(d, ""))
        if not m or int(m.group(2)) <= 0:
            continue
        share = 100.0 * int(m.group(1)) / int(m.group(2))
        (winter if "zima: TAK" in fam.get(d, "") else summer).append((d, share))
    s28 = _mean([v for _, v in summer[-28:]])
    w28 = _mean([v for _, v in winter[-28:]])
    rep.add("E5/B4 B4-6: zatkane magazyny wsi zamkowych - lato (sr28 dob bez zimy)", f"{s28:.2f}% ({len(summer)} dob bez zimy)" if s28 is not None else "brak dob bez zimy",
            "<= 5.6% (bieg letni)", (s28 <= 5.6) if s28 is not None else None)
    rep.add("E5/B4 B4-6b: zatkane magazyny wsi zamkowych - zima (sr28 dob zimy)", f"{w28:.2f}% ({len(winter)} dob zimy)" if w28 is not None else "brak zimy w biegu",
            "INFO - <= wynik zimowy biegu A (zbior 31 B: 6.5%)", None)
    # B4-7: reszta ladunku do miasta - wrocone do domu z ladunkiem (straz BK nie zadzialala)
    home, held = tot(r"wrocily do domu z ladunkiem po zamku (\d+)"), tot(r"BK odeslanie do domu wstrzymane (\d+)")
    share = 100.0 * home / onward if onward > 0 else None
    rep.add("E5/B4 B4-7: reszta ladunku do miasta (wrocone do domu z ladunkiem po zamku)",
            f"wyslane dalej {onward}, wrocone do domu z ladunkiem {home}" + (f" ({share:.1f}%)" if share is not None else "") + f", BK odeslanie wstrzymane {held}",
            "<= 5% wozow wyslanych dalej (wiecej - straz BK nie dziala, np. JIT wkleil VillagersCastleTick)", (share <= 5.0) if share is not None else None)
    # B4-8: odmowy (brak Spendable) - INFO
    nc, ncu, rnc, full = tot(r"odmowy \(brak Spendable\) (\d+) \(niekupione"), tot(r"\(niekupione (\d+) szt\.\)"), tot(r"odmowy przy wyborze \(brak Spendable\) (\d+)"), tot(r"zamek mial dosc (\d+)")
    rep.add("E5/B4 B4-8: odmowy - kasa zamku przy zapasie kupcow (Spendable)", f"przy sprzedazy {nc} wizyt ({ncu} szt. niekupione), przy wyborze {rnc}; zamek mial dosc {full}",
            "INFO - zamki bez nadwyzki nie kupuja (do B1 podzamcze zjada bez zaplaty - kasa zamku traci)", None)
    # B4-9: rozbite tabory (linia Dowoz) - INFO wobec biegu A
    dz = by_day(lines, "Dowoz: dzien")
    lost = _mean([num(r"rozbite tabory wsi \(wszystkich\) (\d+)", dz[d]) for d in l28 if d in dz])
    rep.add("E5/B4 B4-9: rozbite tabory wsi (sr28)", f"{lost:.1f}/d" if lost is not None else "brak linii", "INFO - nie wiecej niz +10% wobec biegu A", None)
    # B4-10: jedzenie okregu dla zamkow (danina w naturze E4/11 + woz) - INFO
    trib = _mean([fnum(r"danina w naturze ([\d.]+) Food/d", tm[d]) for d in l28 if d in tm])
    cart = _mean([num(r"\+ woz (\d+) szt\.", tm[d]) for d in l28 if d in tm])
    rep.add("E5/B4 B4-10: jedzenie okregu dla zamkow (sr28)", (f"danina w naturze {trib:.1f} Food/d + woz {cart:.1f} szt./d" if trib is not None and cart is not None else "-"),
            "INFO - jedno zjawisko z E4/11 pkt 8 (spichlerz zalogi + polka podzamcza)", None)
    # B4-11: bledy i potkniecia, koszt
    errs = [x for x in lines if x.startswith("ERROR in CastleMarket")]
    stm = tot(r"\| POTKNIECIA (\d+)")
    ms = _mean([fnum(r"\| czas ([\d.]+) ms", tm[d]) for d in l28 if d in tm])
    rep.add("E5/B4 B4-11: bledy CastleMarket, potkniecia (koszt linii - INFO)", f"bledy {len(errs)}, potkniecia {stm}" + (f"; czas linii sr28 {ms:.1f} ms" if ms is not None else "")
            + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0", len(errs) == 0 and stm == 0)


def etap5_b6(rep, lines, start, win, bud):
    """E5/B6 (201, R19 - pieniadze weterana i najmu): projekt etapu 5 rozdz. 3 "E5/B6" Test (zbior B): sakiewki zwolnionych do karczmy (czesc ludzi w karczmie -
    E4/10, od tieru 3, 1/3 uprawnionych) do puli weteranow miasta karczmy, najem do kas miast 0. Linia startowa "VetPurse (E5/B6)" (zaplata gracza 2/2), dzienna
    "Weterani - pieniadze (E5/B6): dzien N" (dzien gry - jak 166; klucz = dzien ksiegi), dopisek "do puli weteranow w karczmach (E5/B6)" w "Budzet rodow (166)",
    posiadacz "sakiewki weteranow w karczmach (E5/B6)" w "Pieniadz swiata", dopisek "(E5/B6: oplata za najem do sakiewek najetych)" w "Werbunek:"."""
    stl = [x for x in lines if x.startswith("VetPurse (E5/B6):")]
    vp = e4_series(lines, "Weterani - pieniadze (E5/B6): dzien", 1)
    days = [d for d in win if d in vp]
    # B6-1: linia startowa
    if not stl:
        rep.add("E5/B6 B6-1: linia startowa VetPurse (E5/B6)", "brak linii startowej", "wpiete: zaplata gracza 2/2; BRAK: -", None)
    else:
        x = stl[-1]
        brak = re.search(r"; BRAK: (.*?); wlasciciele", x)
        two = ") 2/2;" in x
        ok = two and brak is not None and brak.group(1).strip() == "-"
        rep.add("E5/B6 B6-1: linia startowa VetPurse (E5/B6)", ("BRAK: " + brak.group(1) if brak else x[:160]) + ("; zaplata gracza 2/2" if two else "; zaplata gracza NIE 2/2"),
                "wpiete: zaplata gracza za najem (BuyMercenaries, buy_mercenaries_on_consequence) 2/2; BRAK: -", ok)
    # B6-2: linia dzienna w kazdej dobie okna, stan CZYNNE (z zaplata za najem do sakiewek)
    on = [d for d in days if "| CZYNNE |" in vp[d]]
    half = [d for d in days if "| CZYNNE bez zaplaty" in vp[d]]
    off = [d for d in days if "| WYLACZONE" in vp[d]]
    rep.add("E5/B6 B6-2: linia dzienna Weterani - pieniadze (E5/B6), stan CZYNNE",
            f"dob z linia {len(days)} z {len(win)}, CZYNNE {len(on)}, bez zaplaty za najem {len(half)}, WYLACZONE {len(off)}",
            "kazda doba okna z linia i CZYNNE (bieg zbioru B)", (len(days) == len(win) and len(on) == len(days)) if win else None)
    if not days:
        return

    def tot(pat, dd=None):
        return sum(num(pat, vp[d], int, 0) or 0 for d in (dd if dd is not None else days))
    # B6-3: kontrola puli (pula wczoraj + wejscia - najem - wydane = pula) - roznica 0 kazdej doby
    bad = [run_day(d, start) for d in days if (num(r"\(roznica (-?\d+)\) \| potkniecia", vp[d], int, 0) or 0) != 0]
    rep.add("E5/B6 B6-3: kontrola puli sakiewek weteranow (roznica)", f"dob z roznica != 0: {len(bad)}" + (f" (d{', d'.join(str(x) for x in bad[:6])})" if bad else ""),
            "0 kazdej doby (pula wczoraj + wejscia - najem - wydane = pula)", len(bad) == 0)
    # B6-4: sakiewki zwolnionych 166 do karczmy - czesc ludzi w karczmie niesie swoja czesc sakiewki do puli; zgodnosc z linia 166 tej samej doby
    took = tot(r"sakiewki zwolnionych 166 (\d+) zl w")
    rin = tot(r"-> do puli (\d+) = ")
    gone = tot(r"zwolnieniach \(ludzi (\d+),")
    tav = tot(r", w karczmach (\d+) = [\d.]+%\) -> do puli")
    gp = 100.0 * rin / took if took else None
    mp = 100.0 * tav / gone if gone else None
    rep.add("E5/B6 B6-4: sakiewki zwolnionych 166 do puli weteranow (czesc ludzi w karczmie)",
            f"sakiewki zwolnionych {took} zl (ludzi {gone}, w karczmach {tav}" + (f" = {mp:.1f}%" if mp is not None else "") + f") -> do puli {rin} zl"
            + (f" = {gp:.1f}%" if gp is not None else "") + f", do kies wsi {took - rin}",
            "> 0, gdy zwolnieni staneli w karczmach (E4/10: 1/3 uprawnionych od tieru 3); udzial zlota bliski udzialowi ludzi (rozjazd - rozne sakiewki partii; INFO)",
            (rin > 0) if tav > 0 else None)
    if bud:
        b166 = sum(num(r"do puli weteranow w karczmach \(E5/B6\) (\d+) zl", bud[d], int, 0) or 0 for d in days if d in bud)
        rep.add("E5/B6 B6-4b: zgodnosc z linia Budzet rodow (166) tej samej doby", f"166: {b166} zl, linia E5/B6: {rin} zl",
                "rowne (ta sama doba, ten sam przelew)", b166 == rin)
    # B6-5: zaplata za najem - oplata do kas miast 0 (najem do kas miast 0; za konie z polki 157 osobno)
    ftown_bad = [(run_day(d, start), num(r"oplata do kas miast (\d+)", vp[d], int, 0) or 0) for d in on]
    ftown_bad = [x for x in ftown_bad if x[1] > 0]
    fee = tot(r"zaplata za najem: do sakiewek najetych (\d+) zl")
    horse = tot(r"za konie z polki do kas miast (\d+)")
    rep.add("E5/B6 B6-5: zaplata za najem - oplata do kas miast",
            f"dob CZYNNE z oplata do kas miast > 0: {len(ftown_bad)}" + (f" (d{ftown_bad[0][0]}: {ftown_bad[0][1]} zl)" if ftown_bad else "")
            + f"; do sakiewek najetych {fee} zl, za konie z polki do kas {horse} zl",
            "0 kazdej doby CZYNNE (dzis ok. 12-44 tys./d do kas miast)", (len(ftown_bad) == 0) if on else None)
    # B6-6: zaplata za najem do sakiewek > 0, gdy byl najem z karczmy (linia Weterani (E4/10) - najeci lordowie, karawany, gracz)
    vet = by_day(lines, "Weterani (E4/10): dzien")
    hired = sum(num(r"\| najeci (\d+):", vet[d], int, 0) or 0 for d in win if d in vet)
    nfee = tot(r"zl w (\d+) najmach")
    fl = tot(r"najmach \(lordowie (\d+)")
    fc = tot(r"najmach \(lordowie \d+, karawany (\d+)")
    fpl = tot(r"najmach \(lordowie \d+, karawany \d+, gracz (\d+)")
    rep.add("E5/B6 B6-6: zaplata za najem do sakiewek najetych",
            f"najmow z oplata {nfee}, {fee} zl (lordowie {fl}, karawany {fc}, gracz {fpl}); najetych z karczm (E4/10) {hired}",
            "> 0, gdy najeto z karczm", (fee > 0) if (hired > 0 and on) else None)
    # B6-7: najem z puli - udzial w puli do sakiewek najetych (INFO); zostalo w puli bez okna / sakiewki (oczekiwane 0)
    hout = tot(r"najem z puli: do sakiewek najetych (\d+) zl")
    hmen = tot(r"najem z puli: do sakiewek najetych \d+ zl \(ludzi (\d+);")
    stay = tot(r"zostalo w puli \(bez okna albo sakiewki\) (\d+)")
    rep.add("E5/B6 B6-7: najem z puli - udzial najetych do sakiewki partii", f"{hout} zl (ludzi {hmen}), zostalo w puli bez okna albo sakiewki {stay} zl",
            "INFO - zostalo w puli oczekiwane 0 (najem bez okna 0 w linii E4/10)", None)
    # B6-8: pule bez weteranow po dobie (zloto bez ludzi) - 0 kazdej doby
    emp_bad = [(run_day(d, start), num(r"pule bez weteranow po dobie (\d+)", vp[d], int, 0) or 0) for d in days]
    emp_bad = [x for x in emp_bad if x[1] > 0]
    rep.add("E5/B6 B6-8: pule bez weteranow po dobie (zloto bez ludzi)", f"dob z pula bez weteranow: {len(emp_bad)}" + (f" (d{emp_bad[0][0]}: {emp_bad[0][1]})" if emp_bad else ""),
            "0 kazdej doby (miasto bez weteranow - cala pula wydana tej samej doby)", len(emp_bad) == 0)
    # B6-9: wydatek puli wobec puli z wczoraj (stawka zycia) - INFO
    l28 = _last28(days)
    pools = [num(r"\| pula sakiewek weteranow (\d+) zl", vp[d], int) for d in l28]
    spent = [num(r"\(zycie, stawka [\d.]+%\) (\d+) zl", vp[d], int) for d in l28]
    rate = num(r"\(zycie, stawka ([\d.]+)%\)", vp[l28[-1]], float)
    share = []
    for i in range(1, len(l28)):
        p0, s1 = pools[i - 1], spent[i]
        if p0 and s1 is not None:
            share.append(100.0 * s1 / p0)
    sm = _mean(share)
    drn = tot(r"pule bez weteranow \(wyjazd ostatnich\) (\d+)")
    oth = tot(r"miasto Innych -> najblizsze miasto ludzi (\d+)")
    rep.add("E5/B6 B6-9: wydatek puli w miastach karczm (sr28)", f"pula sr28 {(_mean(pools) or 0):.0f} zl, wydane sr28 {(_mean(spent) or 0):.0f} zl/d"
            + (f" = {sm:.1f}% puli z wczoraj" if sm is not None else "") + (f" (stawka {rate:.1f}%)" if rate is not None else "")
            + f"; pule bez weteranow (wyjazd ostatnich) {drn} zl, miasto Innych -> miasto ludzi {oth} zl",
            "INFO - wydane ok. stawki zycia (+ pule bez weteranow); pula = kilka dni wejsc", None)
    # B6-10: osierocone (miasto z zapisu nie istnieje) - 0
    orph = max([num(r"osierocone \(miasto z zapisu nie istnieje\) (\d+) zl", vp[d], int, 0) or 0 for d in days] or [0])
    rep.add("E5/B6 B6-10: osierocone pule (miasto z zapisu nie istnieje)", f"najwiecej {orph} zl", "0", orph == 0)
    # B6-11: posiadacz w "Pieniadz swiata" = pula w linii E5/B6 tej samej doby (jedna definicja posiadacza)
    pw = by_day(lines, "Pieniadz swiata: dzien")
    pairs = [(d, num(r"sakiewki weteranow w karczmach \(E5/B6\) (\d+)", pw[d], int), num(r"\| pula sakiewek weteranow (\d+) zl", vp[d], int)) for d in days if d in pw]
    pairs = [x for x in pairs if x[1] is not None and x[2] is not None]
    neq = [x for x in pairs if x[1] != x[2]]
    rep.add("E5/B6 B6-11: posiadacz Pieniadz swiata = pula linii E5/B6", f"dob porownanych {len(pairs)}, rozne {len(neq)}"
            + (f" (d{run_day(neq[0][0], start)}: {neq[0][1]} wobec {neq[0][2]})" if neq else ""),
            "0 roznych (ta sama doba)", (len(neq) == 0) if pairs else None)
    # B6-12: Werbunek (LevyGold) - zloto za najemnikow do miast tylko za konie z polki (INFO, okna dob przesuniete)
    wer = by_day(lines, "Werbunek: dzien")
    wt = sum(num(r"za najemnikow do miast (\d+)", wer[d], int, 0) or 0 for d in win if d in wer)
    wp = sum(num(r"oplata za najem do sakiewek najetych (\d+)", wer[d], int, 0) or 0 for d in win if d in wer)
    rep.add("E5/B6 B6-12: Werbunek (LevyGold) - do miast / do sakiewek najetych (okno)", f"do miast {wt} zl, do sakiewek najetych (AI i karawany) {wp} zl; linia E5/B6: konie z polki {horse} zl",
            "INFO - do miast tylko konie z polki (157; przy paczce 160 - 0)", None)
    # B6-13: bledy i potkniecia; B6-14: reszta ksiegi - grupa etap3
    errs = [x for x in lines if x.startswith("ERROR in VetPurse")]
    stm = tot(r"\| potkniecia (\d+) \(razem")
    ms = _mean([num(r"\| czas ([\d.]+) ms", vp[d], float) for d in l28])
    rep.add("E5/B6 B6-13: bledy VetPurse, potkniecia (koszt - INFO)", f"bledy {len(errs)}, potkniecia {stm}" + (f"; czas sr28 {ms:.2f} ms" if ms is not None else "")
            + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 / 0", len(errs) == 0 and stm == 0)
    rep.add("E5/B6 B6-14: reszta ksiegi pieniadza < 10 tys./d (nowy posiadacz H37)", "--grupa etap3 na tym samym logu", "INFO", None)

E7_WAR = re.compile(r"^Wojna i pokoj \(E7/0\): dzien (\d+) \| (.+?) - (.+?): (WOJNA|POKOJ) \(przyczyna (.*?)\) \| dni od poprzedniego zdarzenia tej pary (\S+)")
E7_FALL = re.compile(r"^Wojna i pokoj \(E7/0\): dzien (\d+) \| (.+?): KROLESTWO ZNISZCZONE")
E7_KRON = re.compile(r"^KRONIKA WOJEN \((dzien|po wczytaniu), [^)]*\): (.*)$")


def _start_dt_of(path, fallback=None):
    """Chwila startu pliku z nazwy (Armoury-/session-RRRR-MM-DD_GG-MM-SS.log); bez niej - fallback."""
    import datetime as dt
    m = re.search(r"(\d{4})-(\d\d)-(\d\d)_(\d\d)-(\d\d)-(\d\d)", os.path.basename(path))
    if m:
        try:
            return dt.datetime(*(int(x) for x in m.groups()))
        except ValueError:
            pass
    return fallback


def _abs_lines(path, start_dt):
    """E7/0: linie logu z chwila bezwzgledna (data startu pliku + [gg:mm:ss], przejscie przez polnoc = spadek godziny o > 1 h) -> [(datetime, tekst)]."""
    import datetime as dt
    out, day, prev = [], 0, None
    base = dt.datetime(start_dt.year, start_dt.month, start_dt.day)
    with open(path, encoding="utf-8-sig", errors="replace") as f:
        for ln in f:
            m = TS.match(ln.strip())
            if not m:
                continue
            hh, mi, ss = (int(x) for x in m.group(1).split(":"))
            t = hh * 3600 + mi * 60 + ss
            if prev is not None and t < prev - 3600:
                day += 1
            prev = t
            out.append((base + dt.timedelta(days=day, seconds=t), m.group(2)))
    return out


def _kron_set(body):
    if body.startswith("POKOJ WSZEDZIE"):
        return set()
    out = set()
    for part in body.split("; "):
        if " vs " in part:
            a, b = part.split(" vs ", 1)
            out.add(frozenset((a.strip(), b.strip())))
    return out


def etap7_t1(rep, logp, csp, t_lo, t_hi):
    """E7/0 T1: kazda zmiana KRONIKI WOJEN (CrashScribe, raz na dobe) ma linie zdarzenia E7/0 tej pary i rodzaju (pokoj - takze upadek krolestwa)
    w oknie +-1 doba (od linii KRONIKI przed poprzednia do linii po nastepnej; chwile z zegara obu logow tego samego startu). Przejscie do linii
    "po wczytaniu" pomijane (inny zapis). Tylko zmiany w czasie okna dob linii E7/0 (t_lo..t_hi)."""
    import datetime as dt
    name = "E7/0 T1: kazda zmiana KRONIKI WOJEN (CS) ma linie E7/0 z przyczyna (+-1 doba)"
    path, how = crashscribe_session_of(logp, csp)
    if not path:
        rep.add(name, how, "100% zmian (bez logu sesji - INFO)", None)
        return
    a0 = _start_dt_of(logp) or (armoury_start_times(logp) or [None])[0]
    c0 = _start_dt_of(path)
    if a0 is None or c0 is None:
        rep.add(name, "brak chwili startu logu Armoury albo CS (nazwa pliku)", "100% zmian", None)
        return
    kr = []
    for t, s in _abs_lines(path, c0):
        m = E7_KRON.match(s)
        if m:
            kr.append((t, m.group(1), _kron_set(m.group(2))))
    ev, fall = [], []
    for t, s in _abs_lines(logp, a0):
        m = E7_WAR.match(s)
        if m:
            ev.append((t, frozenset((m.group(2), m.group(3))), m.group(4)))
            continue
        m = E7_FALL.match(s)
        if m:
            fall.append((t, m.group(2)))
    day = dt.timedelta(days=1)
    total, miss = 0, []
    for i in range(1, len(kr)):
        t, kind, now = kr[i]
        if kind != "dzien" or t_lo is None or not (t_lo <= t <= t_hi):
            continue
        prev = kr[i - 1][2]
        lo = kr[i - 2][0] if i >= 2 else kr[i - 1][0] - day
        hi = kr[i + 1][0] if i + 1 < len(kr) else t + day
        for p, want in [(p, "WOJNA") for p in now - prev] + [(p, "POKOJ") for p in prev - now]:
            total += 1
            ok = any(e[1] == p and e[2] == want and lo <= e[0] <= hi for e in ev)
            if not ok and want == "POKOJ":
                ok = any(f[1] in p and lo <= f[0] <= hi for f in fall)
            if not ok:
                miss.append(f"{' - '.join(sorted(p))} {want} ({t:%H:%M:%S})")
    val = (f"zmian KRONIKI {total}, z linia E7/0 {total - len(miss)}" + (f"; bez linii: {', '.join(miss[:5])}" + (" ..." if len(miss) > 5 else "") if miss else "")
           + f" | {os.path.basename(path)} ({how}); linii KRONIKI {len(kr)}, zdarzen E7/0 {len(ev)}, upadkow {len(fall)}")
    rep.add(name, val, "100% zmian w oknie (zmiana bez linii = NIE)", (len(miss) == 0) if total else None)


def etap7_0(rep, lines, start, until, logp=None, csp=None):
    """E7/0 (224): pomiar etapu 7 - tylko log (projekt etapu 7 v2 rozdz. 3 "E7/0" Test). Okno: doby kampanii 1-until (dzien linii = doba ksiegi, jak
    "Pieniadz swiata"). T0 bledy i potkniecia, koszt <= 1 ms/dobe, T1 KRONIKA (CS), T2 linia zbiorki co noc, T3 linia turniejow i linia dobowa wojny
    co dobe; przyczyny wojen i pokojow, pary z nowa wojna < 21 dni po pokoju, sen czlonkow armii, okna bez startu turnieju i tygodnie pory - INFO
    (progi wynikowe maja E7/K i E7/O1)."""
    # linia dobowa (z "od poprzedniej linii") - by_day wzialby ostatnia linie doby, a linie zdarzen tej samej doby moga ja przykryc
    wd = {}
    for s in lines:
        if s.startswith("Wojna i pokoj (E7/0): dzien") and "| od poprzedniej linii:" in s:
            k = num(r"dzien (\d+)", s)
            if k is not None:
                wd[k] = s
    tu = by_day(lines, "Turnieje (E7/0): dzien")
    zb = {}
    for s in lines:
        if s.startswith("Zbiorka (E7/0): noc"):
            k = num(r"noc (\d+)", s)
            if k is not None:
                zb[k] = s
    if not wd and not tu:
        rep.add("E7/0: linie Wojna i pokoj / Turnieje (E7/0)", "brak w logu", "sa od wgrania E7/0 (Stage7MeasureLog)", None)
        return
    win = [d for d in sorted(set(wd) | set(tu)) if 1 <= run_day(d, start) <= until]
    base = sorted(d for d in by_day(lines, "Pieniadz swiata: dzien") if 1 <= run_day(d, start) <= until)
    # ---- T0 bledy, potkniecia, koszt
    errs = [s for s in lines if s.startswith("ERROR in WorldClock7")]
    stum = max([num(r"\| potkniecia (\d+)", wd[d], default=0) for d in win if d in wd] or [0])
    rep.add("E7/0 T0: bledy WorldClock7 i potkniecia", f"ERROR in WorldClock7 {len(errs)}; potkniecia (najwiecej w linii dobowej) {stum}", "0 i 0", len(errs) == 0 and stum == 0)
    if logp:
        crashscribe_t1_row(rep, "E7/0 T0: bledy WorldClock7 polkniete przez CrashScribe (log sesji)", logp, csp, where_filter="WorldClock7")
    cost = [(fnum(r"koszt E7/0 ([0-9.]+) ms/dobe", tu[d]), d) for d in win if d in tu]
    cost = [(c, d) for c, d in cost if c is not None]
    if cost:
        m = sum(c for c, _ in cost) / len(cost)
        mx = max(cost)
        rep.add("E7/0 koszt linii dobowych", f"srednio {m:.3f} ms/dobe, najwiecej {mx[0]:.3f} ms (d{run_day(mx[1], start)}) - {len(cost)} dob", "<= 1 ms/dobe srednio", m <= 1.0)
    else:
        rep.add("E7/0 koszt linii dobowych", "brak liczby kosztu w linii Turnieje (E7/0)", "<= 1 ms/dobe", None)
    # ---- T1 KRONIKA (CS)
    t_lo = t_hi = None
    if logp and win:
        a0 = _start_dt_of(logp) or (armoury_start_times(logp) or [None])[0]
        if a0 is not None:
            times = [t for t, s in _abs_lines(logp, a0) if s.startswith("Turnieje (E7/0): dzien") and num(r"dzien (\d+)", s) in set(win)]
            if times:
                t_lo, t_hi = min(times), max(times)
    if logp:
        etap7_t1(rep, logp, csp, t_lo, t_hi)
    # ---- T2 zbiorka co noc
    nights = [d for d in win if d in zb]
    lead = [d for d in nights if (num(r"wodzowie armii obozuja \d+/(\d+)", zb[d], default=0) or 0) > 0]
    missing = [run_day(d, start) for d in win if d not in zb]
    rep.add("E7/0 T2: linia Zbiorka (E7/0) w kazdej nocy okna", f"noce z linia {len(nights)} z {len(win)} dob (z wodzem armii w polu {len(lead)})"
            + (f"; bez linii doby kampanii {missing[:8]}" if missing else ""),
            "brakuje najwyzej 1 nocy (ostatnia doba logu; bez obozu swiata AiCampsAtNight - brak linii)", len(missing) <= 1 if win else None)
    off = sum(1 for d in nights if "regula powodow T10 wylaczona" in zb[d])
    a = sum(num(r"partio-godzin (\d+)", zb[d], default=0) or 0 for d in nights)
    b = sum(num(r", spia (\d+) \(", zb[d], default=0) or 0 for d in nights)
    c = sum(num(r"ida z powodem (\d+)", zb[d], default=0) or 0 for d in nights)
    g = sum(num(r"\), alarm (\d+)", zb[d], default=0) or 0 for d in nights)
    nr = sum(num(r"ida bez powodu (\d+)", zb[d], default=0) or 0 for d in nights)
    wk = sum(num(r"w tym uspieni (\d+)", zb[d], default=0) or 0 for d in nights)
    le = sum(num(r"wodzowie armii obozuja (\d+)/", zb[d], default=0) or 0 for d in nights)
    lf = sum(num(r"wodzowie armii obozuja \d+/(\d+)", zb[d], default=0) or 0 for d in nights)
    rep.add("E7/0 zbiorka: czlonkowie armii w drodze w oknie obozu (suma okna)",
            (f"partio-godzin {a}, spia {b} ({100.0 * b / a:.1f}%), ida z powodem {c}, alarm {g}, ida bez powodu {nr} (w tym uspieni {wk}); "
             if a else "partio-godzin 0; ") + f"wodzowie armii obozuja {le}/{lf}" + (f"; noce z regula T10 wylaczona {off}" if off else ""),
            "INFO (prog >= 95% snu - E7/O1 T7)", None)
    # ---- T3 linie dobowe co dobe
    rep.add("E7/0 T3: linia Turnieje (E7/0) co dobe", f"{sum(1 for d in base if d in tu)} z {len(base)} dob z linia Pieniadz swiata (okno 1-{until})",
            f"{len(base)}/{len(base)}", (all(d in tu for d in base)) if base else None)
    rep.add("E7/0 T3b: linia dobowa Wojna i pokoj (E7/0) co dobe", f"{sum(1 for d in base if d in wd)} z {len(base)} dob",
            f"{len(base)}/{len(base)}", (all(d in wd for d in base)) if base else None)
    # ---- INFO: przyczyny, szybkie wojny, przerwy pokoj -> wojna
    causes, quick, gaps, n_ev = {}, [], [], 0
    for s in lines:
        m = E7_WAR.match(s)
        if not m or not (1 <= run_day(int(m.group(1)), start) <= until):
            continue
        n_ev += 1
        k = m.group(4) + " " + m.group(5).split(",")[0]
        causes[k] = causes.get(k, 0) + 1
        if m.group(4) == "WOJNA" and "(POKOJ)" in s:
            dd = num(r"tej pary (\d+) \(POKOJ\)", s)
            if dd is not None:
                gaps.append(dd)
                if dd < 21:
                    quick.append(f"{m.group(2)} - {m.group(3)} {dd} d ({m.group(5).split(',')[0]})")
    top = ", ".join(f"{k} {v}" for k, v in sorted(causes.items(), key=lambda kv: -kv[1])[:8])
    rep.add("E7/0 wojny i pokoje krolestw wedlug przyczyny (okno)", f"zdarzen {n_ev}" + (f": {top}" if top else ""), "INFO (kazde z przyczyna - T1)", None)
    rep.add("E7/0 przerwy pokoj -> wojna tej samej pary (pamiec sesji)",
            (f"{len(gaps)} przerw, najkrotsza {min(gaps)} d, mediana {st.median(gaps):.0f} d; < 21 dni: {len(quick)}" + (f" ({'; '.join(quick[:5])})" if quick else ""))
            if gaps else "brak par z pokojem i nowa wojna w oknie", "INFO (prog >= 87/90 dni - E7/K)", None)
    # ---- INFO: turnieje - okna bez startu, tygodnie pory
    started = {d: (num(r"rozpoczete od poprzedniej linii (\d+)", tu[d], default=0) or 0) for d in win if d in tu}
    gap, best, best_end, weeks = 0, 0, None, {}
    for d in sorted(started):
        if started[d] > 0:
            gap = 0
            w = num(r"tydzien pory (\d+)", tu[d])
            if w is not None:
                weeks[w] = weeks.get(w, 0) + started[d]
        else:
            gap += 1
            if gap > best:
                best, best_end = gap, d
    wmax = num(r"tydzien pory \d+ \(0-(\d+)", tu[win[-1]]) if win and win[-1] in tu else None
    empty = [w for w in range(0, (wmax if wmax is not None else 12) + 1) if w not in weeks]
    rep.add("E7/0 turnieje: starty w oknie, najdluzsze okno bez startu, tygodnie pory bez startu",
            f"startow {sum(started.values())}, najdluzej bez startu {best} dob" + (f" (do d{run_day(best_end, start)})" if best_end is not None else "")
            + f"; tygodnie pory bez startu {empty if empty else '-'}", "INFO (prog: okno < 14 dob, starty w kazdym tygodniu 0-12 - E7/K)", None)


E7O1_GATE = re.compile(r"\| E7/O1 \(SleepersHoldOrders (on|off)\): obudzeni cudza reka: lordowie (\d+), karawany (\d+) \| rozkazy zatrzymane u spiacych: "
                       r"lordowie (\d+) \(GoToSettlement (\d+), GoToPoint (\d+), Engage (\d+), inne (-?\d+)\), karawany (\d+) \(zwolnienie z Hold przez BK (\d+), "
                       r"inne (-?\d+)\), inne partie (\d+); do snu dlugu (\d+) \(nowych dluznikow (\d+)\), oddane przy koncu snu dlugu (\d+) \| AI odnowione (\d+) "
                       r"\(oboz (\d+)/dlug (\d+)/osada (\d+)\) \| AI wstalo przed switem: lordowie (\d+), karawany (\d+), inne (\d+) \| SleepGate (\d+) x, "
                       r"sr\. ([\d.]+) us, razem ([\d.]+) ms, potkniecia w sesji (\d+)")
E7O1_DAWN = re.compile(r"E7/O1 swit: AI wlaczone o swicie (\d+) \(oboz (\d+)/osada (\d+)\), rozkazy zatrzymane i oddane o swicie (\d+), dluznicy obudzeni o 6:00 (\d+)")
E7O1_MOVE = re.compile(r"^AiNightCamp: ruch .*BEZ WPISU POWODU (\d+):.*wyjazd z osady / po bitwie (\d+)")
# narzedzie progow F9b (F7-6): dopisek na koncu dopisku E7/O1 (linie nocy w noc.log i linia switu w glownym logu)
E7O1_KEPT = re.compile(r"\| F7: cudze rozkazy zlapane przez straznika i zachowane do switu: lordowie (\d+), karawany (\d+), inne (\d+)")
E7O1_KEYS = ("wl", "wc", "gl", "gls", "glp", "gle", "glo", "gc", "gcb", "gco", "go", "gd", "gdn", "gdv", "rn", "rnc", "rnd", "rnt", "awl", "awc", "awo",
             "gn", "gus", "gms", "gst")


def etap7_o1(rep, lines, start, until, logp=None, csp=None):
    """E7/O1 (228): sen do switu (projekt etapu 7 v2 rozdz. 3 "E7/O1" Test, rozdz. 4 (7.6)). Noc = linie "AiNightCamp: H:00 - spi" i "AiNightCamp: ruch"
    (plik sesji noc.log - wplatany w glowny log po znaczniku czasu) zamkniete linia "NightRest swit"; doba nocy = ostatnia linia "Pieniadz swiata:
    dzien N" przed switem. Okno progow T1-T4: doby kampanii 31-until. T1 obudzonych cudza reka <= 10 na noc (srednio), lordowie <= 3; T2 zjazd sr.
    obudzonych rozkazem <= 0.15 jedn. (probka >= 20, mniej - INFO; Hold bez rozkazu - INFO); T3 lordowie w ruchu bez wpisu powodu (bez klasy
    Inni/doczepieni) <= 2 na noc, w tym wyjazd z osady / po bitwie <= 1.7 (prog po F7); T4 AI spiacych lordow wstalo przed switem = 0 w kazdej nocy; T6 bledy/potkniecia SleepGate i straznikow 0, dluznicy
    obudzeni o 6:00 = 0; T7 zbiorka (E7/0) >= 95% partio-godzin snu; T9 koszt bramki <= 5 ms/dobe; reszta (rozkazy zatrzymane, zwolnienia BK, odnowienia,
    oddane dluznikom) - INFO. T5 (dlug 3) i T8 (KRONIKA, Miara: marsz) - poza blokiem (grupa etap6/T10 i marsz.py). F9b (poprawka F7 - jeden koniec
    snu = tick switu, wezwania przez bramke snu): F7-2 spiacy ruszeni cudza reka w liniach "AiNightCamp: ruch" <= 1.0 na noc (d31-okno) i <= 3.0 (d1-30),
    F7-3 wywolania HoldSleepers w takcie switu >= 0.8 x srednia taktow 1:00-5:00, F7-4 GoToSettlement zatrzymane do switu >= 2.0 na noc (nowa kampania),
    F7-5 "inny rozkaz" <= 8 w jednej linii nocy i switu, F7-6 rozkazy zlapane przez straznika (pole od F7) - INFO."""
    nights, cur, day, klucz = [], None, None, set()

    def new():
        return {"woken": 0, "drift_sum": 0.0, "nr": 0, "exit": 0, "dawn": None, "lines": 0, "hourly": 0, "att": 0, "nr56": 0,
                "hold": 0, "our": 0, "oth": 0, "d_ord": 0.0, "d_hold": 0.0, "mixed": 0,
                "mw": 0, "hs_d": None, "hs_h": [], "ox_h": 0, "ox_d": 0, "k7": [0, 0, 0], "k7n": 0,   # F9b (F7-2..F7-6)
                **{k: 0 for k in E7O1_KEYS}}

    # narzedzie progow zb58 (TRIAZ "E7/O1 T2 (i caly blok etap7_o1)", "E7/O1 T3"): linie "AiNightCamp" ida do pliku tematycznego noc.log (Log.TopicOf),
    # w glownym logu zostaje tylko "NightRest swit" - 1 z 7 taktow nocy, wiec blok czytal ulamek nocy (falszywe TAK, wiersze INFO zanizone ok. 6 x).
    # Linie noc.log sa wplatane w glowny log po znaczniku czasu; przy tej samej sekundzie linie nocy ida przed liniami glownego logu (kolejnosc w grze:
    # "ruch 5:00-6:00" przed "NightRest swit" tego samego taktu). Linia "ruch" po switaniu bez otwartej nocy dopisuje sie do nocy wlasnie zamknietej.
    src, noc_n, nocp = lines, 0, None
    if logp:
        nocp = session_file_find(logp, "noc.log")
        if os.path.exists(nocp):
            try:
                import datetime as _dt
                t0 = _start_dt_of(logp, fallback=_dt.datetime(2000, 1, 1))
                a = _abs_lines(logp, t0)
                b = _abs_lines(nocp, t0)
                if a and b and b[0][0] < a[0][0] - _dt.timedelta(hours=1):   # noc.log zaczety po polnocy, glowny log przed nia
                    b = [(t + _dt.timedelta(days=1), s) for t, s in b]
                both = [(t, 1, i, s) for i, (t, s) in enumerate(a)] + [(t, 0, i, s) for i, (t, s) in enumerate(b)]
                both.sort(key=lambda q: q[:3])
                src, noc_n = [q[3] for q in both], len(b)
            except (OSError, ValueError):
                src, noc_n = lines, 0
    for s in src:
        if s.startswith("Pieniadz swiata: dzien"):
            k = num(r"dzien (\d+)", s)
            if k is not None:
                day = k
            continue
        hourly = s.startswith("AiNightCamp: ") and " - spi " in s[:40]
        dawn = s.startswith("NightRest swit ")
        mv = E7O1_MOVE.match(s) if s.startswith("AiNightCamp: ruch") else None
        if not (hourly or dawn or mv):
            continue
        if mv:
            tgt = cur if cur is not None else (nights[-1] if nights and " ruch 5:00-6:00 " in s[:40] else None)
            if tgt is None:
                cur = tgt = new()
            att = num(r"Inni/doczepieni (\d+)", s, default=0) or 0
            tgt["nr"] += int(mv.group(1))
            tgt["exit"] += int(mv.group(2))
            tgt["att"] += att
            tgt["mw"] += num(r"obudzeni cudza reka (\d+),", s, default=0) or 0   # F9b (F7-2): spiacy ruszeni cudza reka - wszystkie linie ruchu nocy
            if " ruch 5:00-6:00 " in s[:40]:
                tgt["nr56"] += int(mv.group(1)) - att
            continue
        if cur is None:
            cur = new()
        cur["lines"] += 1
        if hourly:
            cur["hourly"] += 1
        w = num(r"obudzonych cudza reka od poprzedniej godziny: (\d+)", s, default=0) or 0
        cur["woken"] += w
        dr = fnum(r"Zjazd obudzonych: sr\. ([\d.]+)", s)
        if dr is not None:
            cur["drift_sum"] += dr * w
        # narzedzie progow F9b (F7-3, F7-6): wywolania straznika HoldSleepers w takcie (swit osobno, takty 1:00-5:00 osobno), rozkazy zlapane przez straznika
        hs = num(r"Stoper: HoldSleepers (\d+) x", s)
        if hs is not None:
            if dawn:
                cur["hs_d"] = hs
            elif re.match(r"AiNightCamp: [1-5]:00 - spi ", s):
                cur["hs_h"].append(hs)
        k7 = E7O1_KEPT.search(s)
        if k7:
            cur["k7n"] += 1
            for i7 in range(3):
                cur["k7"][i7] += int(k7.group(i7 + 1))
        mk = re.search(r"rodzaj: Hold bez rozkazu (\d+), rozkaz jak nasz zapamietany (\d+), inny rozkaz (\d+)", s)
        if mk:
            kh, ko, kx = (int(v) for v in mk.groups())
            cur["ox_d" if dawn else "ox_h"] = max(cur["ox_d" if dawn else "ox_h"], kx)   # F9b (F7-5): najwieksza seria "inny rozkaz" w jednej linii
            cur["hold"] += kh
            cur["our"] += ko
            cur["oth"] += kx
            if dr is not None:   # linia podaje jedna srednia zjazdu dla wszystkich obudzonych godziny - w liniach mieszanych przyjeta dla obu rodzajow
                cur["d_ord"] += dr * (ko + kx)
                cur["d_hold"] += dr * kh
                if kh and (ko + kx):
                    cur["mixed"] += ko + kx
        m = E7O1_GATE.search(s)
        if m:
            klucz.add(m.group(1))
            vals = m.groups()[1:]
            for k, v in zip(E7O1_KEYS, vals):
                if k in ("gus",):
                    continue
                if k == "gms":
                    cur[k] += float(v)
                elif k == "gst":
                    cur[k] = max(cur[k], int(v))
                else:
                    cur[k] += int(v)
        if dawn:
            md = E7O1_DAWN.search(s)
            if md:
                cur["dawn"] = tuple(int(x) for x in md.groups())
            cur["day"] = day
            nights.append(cur)
            cur = None
    have = [n for n in nights if n.get("day") is not None]
    if not have or not klucz:
        rep.add("E7/O1: linie AiNightCamp / NightRest swit z dopiskiem E7/O1", "brak w logu" if not klucz else "brak nocy z doba",
                "sa od wgrania E7/O1 (SleepersHoldOrders)", None)
        return
    if "off" in klucz:
        rep.add("E7/O1: klucz SleepersHoldOrders", "off w " + ("czesci" if "on" in klucz else "wszystkich") + " linii", "on (progi T1-T4 dotycza klucza on)", None)
    win = [n for n in have if 31 <= run_day(n["day"], start) <= until]
    allw = [n for n in have if 1 <= run_day(n["day"], start) <= until]
    nw = len(win)
    # narzedzie progow zb58: bez linii godzinowych nocy (brak noc.log obok logu) blok widzi tylko takt switu - T1-T4 i T9 nie sa wtedy pomiarem (INFO)
    full = sum(n["hourly"] for n in have) > 0
    rep.add("E7/O1: zrodlo linii nocy (noc.log wpleciony w glowny log po znaczniku czasu)",
            (f"noc.log {noc_n} linii, " if noc_n else f"brak noc.log ({nocp or 'bez sciezki logu'}), ") + f"taktow godzinowych w nocach {sum(n['hourly'] for n in have)}, "
            f"switow {len(have)}", "INFO (bez linii godzinowych T1-T4 i T9 sa INFO - sam swit to 1 z 7 taktow nocy)", None)

    def okf(v):
        return v if full else None
    # ---- T1 obudzeni cudza reka
    if nw:
        avg = sum(n["woken"] for n in win) / nw
        avl = sum(n["wl"] for n in win) / nw
        avc = sum(n["wc"] for n in win) / nw
        worst = max(win, key=lambda n: n["woken"])
        t1ok = avg <= 10 and avl <= 3
        rep.add("E7/O1 T1: obudzeni cudza reka na noc (d31-okno, srednio)", f"{avg:.1f} na noc (lordowie {avl:.1f}, karawany {avc:.1f}); najwiecej {worst['woken']} "
                f"(d{run_day(worst['day'], start)}) - {nw} nocy", "<= 10 na noc, lordowie <= 3 (dzis 91, 79% karawan)", okf(t1ok))
        # T2 (TRIAZ): srednia tylko z obudzonych rozkazem ("rozkaz jak nasz" + "inny rozkaz"); "Hold bez rozkazu" (partia stoi na Hold bez celu i zjechala
        # z legowiska - przejscia lad/morze rodow wysp i portow, tez we wzorcu) osobnym wierszem INFO; prog tylko przy probce >= 20
        tw = sum(n["woken"] for n in win)
        to, th = sum(n["our"] + n["oth"] for n in win), sum(n["hold"] for n in win)
        tmix = sum(n["mixed"] for n in win)
        if to + th == 0 and tw:   # log bez podzialu na rodzaj - stara miara na wszystkich obudzonych
            drift = sum(n["drift_sum"] for n in win) / tw
            rep.add("E7/O1 T2: zjazd obudzonych srednio (d31-okno)", f"{drift:.2f} jedn. ({tw} obudzonych)", "<= 0.15 jedn. (dzis 0.40)", okf(drift <= 0.15))
        else:
            drift = sum(n["d_ord"] for n in win) / to if to else 0.0
            rep.add("E7/O1 T2: zjazd obudzonych rozkazem srednio (d31-okno)",
                    f"{drift:.2f} jedn. ({to} obudzonych rozkazem: jak nasz {sum(n['our'] for n in win)}, inny {sum(n['oth'] for n in win)}"
                    + (f"; {tmix} w liniach z Hold - srednia linii" if tmix else "") + ")"
                    + ("" if to >= 20 else " - probka < 20" + (", T1 spelniony" if t1ok and full else "")),
                    "<= 0.15 jedn. przy probce >= 20 obudzonych rozkazem (mniej - INFO; dzis 0.40)", okf(drift <= 0.15) if to >= 20 else None)
            rep.add("E7/O1 T2a: obudzeni z Hold bez rozkazu (zjazd z legowiska bez celu - przejscia lad/morze)",
                    f"{th} w {nw} nocach" + (f", zjazd sr. {sum(n['d_hold'] for n in win) / th:.2f} jedn." if th else ""), "INFO (nie rozkaz - bramka ich nie dotyczy)", None)
        # T3 (TRIAZ): klasa "Inni/doczepieni" to nie spiacy (NightMarch) - poza miara; godzina 5:00-6:00 osobno (takt switu)
        anr = sum(n["nr"] - n["att"] for n in win) / nw
        aex = sum(n["exit"] for n in win) / nw
        rep.add("E7/O1 T3: lordowie w ruchu bez wpisu powodu w oknie obozu (d31-okno, srednio)",
                f"{anr:.1f} na noc (klasa Inni/doczepieni {sum(n['att'] for n in win) / nw:.1f} poza miara - to nie spiacy), w tym wyjazd z osady / po bitwie {aex:.1f}, "
                f"w godzinie 5:00-6:00 {sum(n['nr56'] for n in win) / nw:.1f}",
                "<= 2.0 na noc (bez klasy Inni/doczepieni), wyjazd z osady / po bitwie <= 1.7 (prog po F7: W33 1.75 / 1.53 + ok. 10%; czesc \"cudza reka\" "
                "pilnuje F7-2)", okf(anr <= 2.0 and aex <= 1.7))
        bad = [run_day(n["day"], start) for n in win if n["awl"] > 0]
        rep.add("E7/O1 T4: AI spiacych lordow wstalo przed switem (d31-okno)", f"noce z wstaniem {len(bad)} z {nw}" + (f" (doby {bad[:8]})" if bad else "")
                + f"; razem lordowie {sum(n['awl'] for n in win)}, karawany {sum(n['awc'] for n in win)} (odczyt), inne {sum(n['awo'] for n in win)}",
                "lordowie 0 w kazdej nocy (dowod fazy)", okf(not bad))
    else:
        rep.add("E7/O1 T1-T4: noce d31-okno", f"brak (nocy w logu {len(have)})", "noce d31-120", None)
    # ---- narzedzie progow F9b (F7): sen do switu - jeden koniec snu = tick switu, wezwania na turniej i rozkazy odsieczy przez bramke snu
    w30 = [n for n in have if 1 <= run_day(n["day"], start) <= min(30, until)]
    if win or w30:
        a31 = sum(n["mw"] for n in win) / float(len(win)) if win else None
        a30 = sum(n["mw"] for n in w30) / float(len(w30)) if w30 else None
        rep.add("E7/O1 F7-2: spiacy lordowie ruszeni cudza reka (linie AiNightCamp: ruch, srednio na noc)",
                (f"d31-okno {a31:.2f} ({len(win)} nocy)" if a31 is not None else "d31-okno: brak nocy") + "; "
                + (f"d1-30 {a30:.2f} ({len(w30)} nocy)" if a30 is not None else "d1-30: brak nocy"),
                "<= 1.0 na noc w d31-okno i <= 3.0 w d1-30 (a589def 5.45 i 62.4 - w TRIAZ 5.54 i 61.9, noc graniczna liczona inaczej; W33 ok. 1.0 i 64; bieg z zapisu 0)",
                okf((a31 is None or a31 <= 1.0) and (a30 is None or a30 <= 3.0)))
    hd = [n["hs_d"] for n in allw if n["hs_d"] is not None]
    hh = [v for n in allw for v in n["hs_h"]]
    if hd and hh and sum(hh) > 0:
        md_, mh_ = sum(hd) / float(len(hd)), sum(hh) / float(len(hh))
        rep.add("E7/O1 F7-3: straznik HoldSleepers pracuje do ticku switu (wywolan w takcie switu wobec taktow 1:00-5:00, srednio)",
                f"{md_:.2f} wobec {mh_:.2f} = {md_ / mh_:.2f} ({len(hd)} switow, {len(hh)} taktow nocy)",
                ">= 0.8 x srednia taktow nocy (a589def 3.29 / 6.74 = 0.49; W33 3.27 / 6.77; oczekiwane ok. 1.0)", md_ >= 0.8 * mh_)
    else:
        rep.add("E7/O1 F7-3: straznik HoldSleepers pracuje do ticku switu", "brak taktow 1:00-5:00 (brak noc.log) albo pola Stoper: HoldSleepers",
                ">= 0.8 x srednia taktow nocy", None)
    if allw:
        n7 = float(len(allw))
        newc = any(x.startswith("Weterani (E4/10): siew dnia ") for x in lines)
        gs = sum(n["gls"] for n in allw)
        rep.add("E7/O1 F7-4: wezwania GoToSettlement zatrzymane u spiacych lordow do switu (na noc, okno)",
                f"{gs / n7:.2f} na noc ({gs} w {len(allw)} nocach)" + ("" if newc else " - bieg z zapisu (tick dobowy poza obozem)"),
                ">= 2.0 na noc w nowej kampanii (a589def 0.12; oczekiwane kilkanascie - tylu spiacych budzil herold; bieg z zapisu - INFO)",
                okf(gs / n7 >= 2.0) if newc else None)
        xh, xd = max(n["ox_h"] for n in allw), max(n["ox_d"] for n in allw)
        rep.add("E7/O1 F7-5: serie \"inny rozkaz\" u obudzonych - najwiecej w jednej linii (takty nocy / linia switu)", f"{xh} / {xd}",
                "<= 8 w jednej linii taktu nocy i w linii switu (a589def 41 i 28)", okf(xh <= 8 and xd <= 8))
        if sum(n["k7n"] for n in allw):
            k7l, k7c, k7o = (sum(n["k7"][i7] for n in allw) for i7 in range(3))
            rep.add("E7/O1 F7-6: cudze rozkazy zlapane przez straznika i zachowane do switu (na noc, okno)",
                    f"{(k7l + k7c + k7o) / n7:.2f} na noc (lordowie {k7l}, karawany {k7c}, inne {k7o} w {len(allw)} nocach)",
                    "INFO (oczekiwane pojedyncze - nie wiecej niz \"inny rozkaz\" tej nocy)", None)
        else:
            rep.add("E7/O1 F7-6: cudze rozkazy zlapane przez straznika i zachowane do switu", "brak linii (log sprzed F7 - bez dopisku \"| F7: cudze rozkazy\")",
                    "INFO", None)
    # ---- T6 bledy, potkniecia, dluznicy o 6:00
    errs = [s for s in lines if s.startswith("ERROR in SleepGate") or s.startswith("ERROR in HoldSleepers") or s.startswith("ERROR in KeepTownAsleep")
            or s.startswith("ERROR in DawnWake") or s.startswith("ERROR in HoldDebtSleepers")]
    gst = max([n["gst"] for n in have] or [0])
    gs = max([num(r"Potkniecia straznikow w sesji: (\d+)", s, default=0) or 0 for s in src if s.startswith("AiNightCamp: ") or s.startswith("NightRest swit")] or [0])
    rep.add("E7/O1 T6: bledy i potkniecia SleepGate / straznikow snu", f"ERROR {len(errs)}; potkniecia bramki w sesji {gst}, straznikow w sesji {gs}"
            + (f" (pierwszy: {errs[0][:140]})" if errs else ""), "0 / 0 / 0", len(errs) == 0 and gst == 0 and gs == 0)
    if logp:
        crashscribe_t1_row(rep, "E7/O1 T6: bledy NightRest polkniete przez CrashScribe (log sesji)", logp, csp, where_filter="NightRest")
    dd = [n["dawn"] for n in allw if n["dawn"] is not None]
    deb = sum(x[4] for x in dd)
    rep.add("E7/O1 T6b: dluznicy obudzeni o 6:00 (galaz switu)", f"{deb} w {len(dd)} switach", "0", deb == 0 if dd else None)
    gdn = sum(n["gdn"] for n in allw)
    gdv = sum(n["gdv"] for n in allw)
    rep.add("E7/O1 T6c: rozkazy zatrzymane dluznikom - nowi dluznicy z rozkazem / oddane przy koncu snu dlugu (okno)",
            f"zatrzyman {sum(n['gd'] for n in allw)}, dluznikow z rozkazem {gdn}, oddanych przy ReleaseDebt {gdv}",
            "INFO (oddane ~ dluznicy z rozkazem; roznica = alarm, cudza blokada, zniszczona partia)", None)
    # ---- rozkazy zatrzymane, zwolnienia BK, odnowienia, swit - INFO
    if allw:
        n_ = len(allw)
        rep.add("E7/O1 rozkazy zatrzymane u spiacych (okno, na noc)",
                f"lordowie {sum(n['gl'] for n in allw) / n_:.1f} (GoToSettlement {sum(n['gls'] for n in allw) / n_:.1f}, GoToPoint {sum(n['glp'] for n in allw) / n_:.1f}, "
                f"Engage {sum(n['gle'] for n in allw) / n_:.1f}), karawany {sum(n['gc'] for n in allw) / n_:.1f} (zwolnienie z Hold przez BK "
                f"{sum(n['gcb'] for n in allw) / n_:.1f}), inne partie {sum(n['go'] for n in allw) / n_:.1f}", "INFO (zwolnien BK zatrzymanych - odczyt, ryzyko 5)", None)
        rep.add("E7/O1 faza snu: AI odnowione (okno, na noc)",
                f"{sum(n['rn'] for n in allw) / n_:.1f} (oboz {sum(n['rnc'] for n in allw) / n_:.1f} / dlug {sum(n['rnd'] for n in allw) / n_:.1f} / osada "
                f"{sum(n['rnt'] for n in allw) / n_:.1f})", "INFO", None)
        if dd:
            rep.add("E7/O1 swit: AI wlaczone o swicie / rozkazy zatrzymane oddane o swicie (srednio)",
                    f"AI {sum(x[0] for x in dd) / len(dd):.1f} (oboz {sum(x[1] for x in dd) / len(dd):.1f} / osada {sum(x[2] for x in dd) / len(dd):.1f}), "
                    f"rozkazy {sum(x[3] for x in dd) / len(dd):.1f}", "INFO", None)
        # ---- T9 koszt bramki
        ms = [n["gms"] for n in allw]
        mx = max(allw, key=lambda n: n["gms"])
        calls = sum(n["gn"] for n in allw)
        rep.add("E7/O1 T9: koszt SleepGate na noc (okno)", f"srednio {sum(ms) / len(ms):.3f} ms, najwiecej {mx['gms']:.3f} ms (d{run_day(mx['day'], start)}); wywolan {calls}",
                "<= 5 ms/dobe (odnawianie - stoper HoldSleepers w tej samej linii)", okf(sum(ms) / len(ms) <= 5.0))
    # ---- T7 zbiorka (linia E7/0)
    a = b = 0
    for s in lines:
        if s.startswith("Zbiorka (E7/0): noc"):
            k = num(r"noc (\d+)", s)
            if k is None or not (31 <= run_day(k, start) <= until):
                continue
            a += num(r"partio-godzin (\d+)", s, default=0) or 0
            b += num(r", spia (\d+) \(", s, default=0) or 0
    rep.add("E7/O1 T7: czlonkowie armii w drodze do wodza spia (linia Zbiorka E7/0, d31-okno)", f"{100.0 * b / a:.1f}% ({b}/{a} partio-godzin)" if a else "brak partio-godzin",
            ">= 95%", (b >= 0.95 * a) if a else None)
    rep.add("E7/O1 T5/T8: dlug 3 AI i kara, KRONIKA i Miara: marsz", "poza blokiem", "dlug 3 = 0 (linie T10), wojny i tempo bez zmian (marsz.py, rozdz. 4)", None)


E7T_PAIR = r"{} ([0-9.]+|-)/([0-9.]+|-) \(n (\d+)/(\d+)\)"


def _e7t_pair(s, label):
    """E7/T: "<label> a/b (n x/y)" -> (a, b, x, y); srednia '-' = None."""
    m = re.search(E7T_PAIR.format(re.escape(label)), s)
    if not m:
        return None
    a, b = (None if v == "-" else float(v) for v in m.groups()[:2])
    return a, b, int(m.group(3)), int(m.group(4))


def etap7_t(rep, lines, start, until, logp=None, csp=None):
    """E7/T (225): kary terenu dokladnie jak gra (projekt etapu 7 v2 rozdz. 3 "E7/T" Test, PLAN 7.4). Linia "Kary terenu (E7/T): dzien N" (doba ksiegi).
    T1 z rozpiski gry (wpisy GRY przed naszym zwrotem i zmiany od zwrotu i kary w tej samej liczbie): zwrot > kary gry = 0 i kara Jeffa poza ulamkiem
    gry = 0 w kazdej dobie, maks. |netto| <= 0.001 jedn. (klucz on; off - INFO, stara regula); T2 partio-godzin w lesie z cecha lasu >= 50 (inaczej
    DECYZJA - prog nieczytelny); T3 ponizej sufitu MarchPace (karawany i wozy wsi; d31-until, srednie wazone): Polnoc las < rownina, Dorne pustynia
    <= rownina; T4 koszt probki <= 30 ms/dobe (srednio), bledy TerrainEase i potkniecia 0; T6 regresja E5: towar wsi niesprzedany w miastach <= 2%
    sprzedanego (miasta kupuja >= 98% plonu, d31-until). Rody (na suficie i nie), zwrot ponad netto starej reguly, udzial probek na suficie - INFO;
    T5 tempo marszu - poza blokiem (marsz.py, rozdz. 4). Probki pkt 6 bez "Marching column" nie wchodza do T3: sa tylko w lesie/na pustyni, bez
    pary na rowninie (srednia bylaby stronnicza) - T3 liczy karawany i wozy wsi, ktorych MarchPace nigdy nie tnie."""
    kt = by_day(lines, "Kary terenu (E7/T): dzien")
    if not kt:
        rep.add("E7/T: linia Kary terenu (E7/T)", "brak w logu", "jest od wgrania E7/T (Stage7MeasureLog)", None)
        return
    win = [d for d in sorted(kt) if 1 <= run_day(d, start) <= until]
    w31 = [d for d in win if run_day(d, start) >= 31]
    if not win:
        rep.add("E7/T: linia Kary terenu (E7/T) w oknie", "brak dob w oknie", f"doby kampanii 1-{until}", None)
        return
    keys = {m.group(1) for d in win for m in [re.search(r"TerrainEaseExact (on|off)", kt[d])] if m}
    on = keys == {"on"}
    # ---- T1 z rozpiski gry
    rn = sum(num(r"z rozpiski gry: probek (\d+)", kt[d], default=0) or 0 for d in win)
    rf = sum(num(r"z cecha/perkiem (\d+)\)", kt[d], default=0) or 0 for d in win)
    viol = sum(num(r"zwrot > kary gry (\d+)", kt[d], default=0) or 0 for d in win)
    mis = sum(num(r"kara Jeffa poza ulamkiem gry (\d+)", kt[d], default=0) or 0 for d in win)
    umax = max([fnum(r"maks\. \|u\| ([0-9.]+)", kt[d], default=0.0) or 0.0 for d in win] or [0.0])
    rep.add("E7/T T1: netto lasu/pustyni po naszym postfiksie z rozpiski gry (okno)",
            f"klucz {'/'.join(sorted(keys)) or '-'}; probek {rn} (z cecha/perkiem {rf}), zwrot > kary gry {viol}, kara Jeffa poza ulamkiem gry {mis}, maks. |netto| {umax:.4f} jedn.",
            "zwrot > kary gry 0, kara Jeffa poza ulamkiem 0, maks. |netto| <= 0.001 (klucz on; bez probek z cecha/perkiem czesc 'przy cesze' niesprawdzona - INFO)",
            None if not (on and rn > 0) else (False if (viol or mis or umax > 0.001) else (True if rf > 0 else None)))
    # ---- T2 probek las z cecha lasu
    ff = sum(num(r"\(cecha lasu (\d+)", kt[d], default=0) or 0 for d in win)
    fa = sum(num(r"partio-godziny\): las (\d+)", kt[d], default=0) or 0 for d in win)
    fk = sum(num(r"ForestKin (\d+)\)", kt[d], default=0) or 0 for d in win)
    dd = sum(num(r"\), pustynia (\d+)", kt[d], default=0) or 0 for d in win)
    df = sum(num(r"\(cecha pustyni (\d+)\)", kt[d], default=0) or 0 for d in win)
    rep.add("E7/T T2: partio-godziny AI w lesie z cecha lasu (okno)", f"{ff} (las razem {fa}, ForestKin {fk}; pustynia {dd}, z cecha pustyni {df})",
            ">= 50 (inaczej prog T3 nieczytelny - zglosic, nie zaliczac)", ff >= 50, decide=True)
    # ---- T3 ponizej sufitu (karawany, wozy wsi), d31-until, srednie wazone
    def wavg(label, days):
        sa = sb_ = 0.0
        na = nb = 0
        for d in days:
            seg = kt[d].split("| ponizej sufitu", 1)
            if label.startswith("ponizej:"):
                if len(seg) < 2:
                    continue
                p = _e7t_pair(seg[1], label.split(":", 1)[1])
            else:
                p = _e7t_pair(seg[0], label)
            if not p:
                continue
            a, b, x, y = p
            if a is not None and x:
                sa += a * x; na += x
            if b is not None and y:
                sb_ += b * y; nb += y
        return (sa / na if na else None), (sb_ / nb if nb else None), na, nb

    nf, npl, n1, n2 = wavg("ponizej:Polnoc las/rownina", w31)
    df_, dpl, n3, n4 = wavg("ponizej:Dorne pustynia/rownina", w31)
    f3 = lambda v: f"{v:.3f}" if v is not None else "-"
    ok3 = None
    near3 = False
    if nf is not None and npl is not None and df_ is not None and dpl is not None:
        ok3 = (nf < npl) and (df_ <= dpl)
        # recenzja E7/T: przy kluczu on Dorne z cecha ma na pustyni te sama predkosc co na rowninie (oczekiwana roznica 0), Polnoc w lesie ok. -1.5%;
        # srednie z roznych partii i godzin (ladunek, pogoda, pora) rozjezdzaja sie o 1-2% w obie strony, wiec scisly prog bylby rzutem moneta.
        # Chybienie w granicy 2% = DECYZJA (ocenic z T1), nie NIE; stara regula daje +12% / +5%, wiec ta granica nadal ja odroznia
        near3 = (not ok3) and nf <= npl * 1.02 and df_ <= dpl * 1.02
    rep.add("E7/T T3: ponizej sufitu MarchPace - karawany i wozy wsi (d31-okno, srednie wazone)",
            f"Polnoc las/rownina {f3(nf)}/{f3(npl)} (n {n1}/{n2}), Dorne pustynia/rownina {f3(df_)}/{f3(dpl)} (n {n3}/{n4})",
            "Polnoc las < rownina, Dorne pustynia <= rownina (klucz on; off - spodziewane odwrotnie; chybienie do 2% - DECYZJA: rozrzut skladu probek, ocenic z T1)",
            ok3 if on else None, decide=near3)
    lf, lpl, m1, m2 = wavg("Polnoc las/rownina", w31)
    ld, ldp, m3, m4 = wavg("Dorne pustynia/rownina", w31)
    caps = [fnum(r"na suficie MarchPace ([0-9.]+)%", kt[d]) for d in w31]
    caps = [c for c in caps if c is not None]
    capt = f"sr. {sum(caps) / len(caps):.1f}%" if caps else "-"
    rep.add("E7/T: rody (na suficie i nie) - odczyt (d31-okno)",
            f"Polnoc las/rownina {f3(lf)}/{f3(lpl)} (n {m1}/{m2}), Dorne pustynia/rownina {f3(ld)}/{f3(ldp)} (n {m3}/{m4}); probek rozpiski na suficie MarchPace {capt}",
            "INFO (kolumny piesze na suficie - zmiana 0-2%)", None)
    xo = [fnum(r"stara regula ([0-9.]+) jedn\.", kt[d]) for d in win]
    xn = [fnum(r"jedn\., teraz ([0-9.]+) jedn\.", kt[d]) for d in win]
    xo = [x for x in xo if x is not None]
    xn = [x for x in xn if x is not None]
    rep.add("E7/T: zwrot ponad netto gry (ok., na partio-godzine w lesie/na pustyni)",
            f"stara regula sr. {sum(xo) / len(xo):.4f} jedn., teraz sr. {sum(xn) / len(xn):.4f} jedn." if xo and xn else "brak",
            "INFO (teraz 0 przy kluczu on)", None)
    # ---- T4 koszt, bledy, potkniecia
    cost = [(fnum(r"\| koszt ([0-9.]+) ms", kt[d]), d) for d in win]
    cost = [(c, d) for c, d in cost if c is not None]
    if cost:
        m = sum(c for c, _ in cost) / len(cost)
        mx = max(cost)
        # narzedzie progow zb58 (TRIAZ E7/T T4): koszt z konstrukcji rosnie z liczba partii (pomiar: ok. 4.7 ms stale + 3.4 ms na 1000 partio-godzin
        # w lesie i na pustyni; projekt liczyl ok. 1000 partii, jest kilka razy wiecej) - to sam pomiar pod Stage7MeasureLog, ok. 0.1% doby
        rep.add("E7/T T4: koszt probki (godzinna + rozpiska gry)", f"srednio {m:.3f} ms/dobe, najwiecej {mx[0]:.3f} ms (d{run_day(mx[1], start)}) - {len(cost)} dob",
                "<= 30 ms/dobe srednio (koszt rosnie z liczba partii; szacunek projektu 20 ms liczyl ok. 1000 partii)", m <= 30.0)
    errs = [s for s in lines if s.startswith("ERROR in TerrainEase")]
    stum = max([num(r"\| potkniecia (\d+)", kt[d], default=0) or 0 for d in win] or [0])
    rep.add("E7/T T4: bledy TerrainEase i potkniecia probki", f"ERROR in TerrainEase {len(errs)}; potkniecia (najwiecej w linii) {stum}", "0 i 0",
            len(errs) == 0 and stum == 0)
    if logp:
        crashscribe_t1_row(rep, "E7/T T4: bledy TerrainEase polkniete przez CrashScribe (log sesji)", logp, csp, where_filter="TerrainEase")
    # ---- T6 regresja E5: miasta kupuja >= 98% plonu (wozy wsi Polnocy w lesie wolniej)
    pv = by_day(lines, "Przeplywy osad: dzien")
    tw = by_day(lines, "Towary (utarg wozow): dzien")
    days6 = [d for d in sorted(set(pv) | set(tw)) if 31 <= run_day(d, start) <= until]
    su = sum(num(r"towar niesprzedany po wizycie: w miastach (\d+) szt", pv[d], default=0) or 0 for d in days6 if d in pv)
    ss = sum(num(r"za (\d+) szt\.", tw[d], default=0) or 0 for d in days6 if d in tw)
    share = (100.0 * su / (su + ss)) if (su + ss) > 0 else None
    rep.add("E7/T T6: regresja E5 - towar wsi niesprzedany w miastach (d31-okno)",
            f"{su} szt. wobec sprzedanych {ss} ({share:.3f}% plonu)" if share is not None else "brak linii Przeplywy osad / Towary (utarg wozow)",
            "<= 2% (miasta kupuja >= 98% plonu)", (share <= 2.0) if share is not None else None)
    rep.add("E7/T T5: tempo marszu", "poza blokiem", "Miara: marsz (marsz.py, rozdz. 4) w progu 124-138 km/dobe", None)


# E7/C (227): wyjatki od R4 "kazda decyzja gry na zegarze gry" - plik -> (dozwolonych trafien, powod). Liczba to gorna granica: nowe trafienie w pliku = NIE
# Narzedzie progow p2 (TRIAZ-2 f-E7/C T1): HideoutPurge.cs 2 -> 4 - E8/S (246) dopisal dwa odczyty DateTime.UtcNow w OnTick: po wyjatku przy otwieraniu
# menu przeszukania kryjowki GRACZA kolejna proba najwczesniej po 1 s realnej, najwyzej 3 proby. To odstep ponownej proby okna gracza (jak dlawienie
# komunikatow w Wayfinder / QuartermasterLaw), nie prawo swiata: nie dotyka partii AI, zlota ani czasu gry. Limit trzymany OSOBNO na metode (_E7C_ONLY_IN),
# zeby stara regula "3 s realne" nie mogla wrocic do OnTick pod tym samym licznikiem. Log.cs 4 -> 5: E8/O6 (270) dopisal piaty znacznik czasu linii logu
# (wspolny rdzen zapisu Log.Append) - wszystkie 5 trafien to "[HH:mm:ss]" / naglowek / nazwa pliku logu, zadnej decyzji gry.
_E7C_ALLOWED = {
    "Log.cs": (5, "znaczniki czasu logu (piaty od E8/O6: wspolny rdzen zapisu)"),
    "GoodsLedger.cs": (1, "godzina w linii logu"),
    "NightRest.cs": (4, "widok: namiot gracza (ReassertPlayerTent, co 5 s) i namioty mijanych obozow (co 2 s)"),
    "Wayfinder.cs": (2, "dlawienie komunikatu drogi"),
    "QuartermasterLaw.cs": (4, "dlawienie okrzyku kwatermistrza"),
    "MapVillagesView.cs": (2, "widok mapy wsi (OnVisualTick realDt)"),
    "MapRoadsProbe.cs": (3, "widok proby drog E7/D0 (OnVisualTick realDt: czas klatki do histogramu, dlawienie 4 x na sekunde, podsumowanie; klucz MapRoadsProbeEnabled domyslnie false)"),
    "CrossingLaw.cs": (3, "etap 8 (rozdz. 7): komunikat co 5 s i akumulator _acc"),
    "HideoutPurge.cs": (4, "wylacznik HideoutPursuitHours 0 = stara regula 3 s realne (PursuitDue, 2) i E8/S: odstep ponownej proby otwarcia menu gracza (OnTick, 2)"),
}
_E7C_PAT = re.compile(r"DateTime\.(?:Now|UtcNow)\b|Environment\.TickCount|ApplicationTime|\+=\s*realDt\b")
_E7C_ACC = re.compile(r"\b_acc\w*\s*\+=\s*dt\b")
# plik -> ((naglowek metody, najwyzej trafien w jej ciele), ...): zegar realny tylko w tych metodach i najwyzej w tej liczbie; trafienie poza nimi = NIE
_E7C_ONLY_IN = {"HideoutPurge.cs": (("bool PursuitDue()", 2), ("void OnTick(float dt)", 2))}


def etap7_c(rep, lines, start, until, logp=None, csp=None):
    """E7/C (227): jedna skala czasu (projekt etapu 7 v2 rozdz. 3 "E7/C" Test, PLAN 7.1, R4). T1 grep kodu Armoury/src (katalog obok tools/): zegar realny
    (DateTime.Now/UtcNow, Environment.TickCount, ApplicationTime, += realDt) i akumulator dt (_acc += dt) poza plikami misji (OnMissionTick - zegar misji
    to zegar gry w bitwie) tylko w plikach z _E7C_ALLOWED i najwyzej w ich liczbie; brak zrodel obok narzedzia - INFO. T2 podpowiedz World Pace Percent
    (Settings.cs i McmSettings.cs) bez "168" i "month". Linia startowa i T3 odnowien pogoni na dobe gry (dopisek "E7/C:" linii konca pogoni) - INFO."""
    src = os.path.join(os.path.dirname(os.path.dirname(os.path.abspath(__file__))), "Armoury", "src")
    if not os.path.isdir(src):
        rep.add("E7/C T1: zegar realny i akumulatory klatek w logice gry (grep kodu)", f"brak zrodel ({src})", "uruchomic z drzewa repo", None)
        rep.add("E7/C T2: tekst MCM World Pace Percent bez 168", "brak zrodel", "uruchomic z drzewa repo", None)
    else:
        hits, over = {}, []
        for fn in sorted(os.listdir(src)):
            if not fn.endswith(".cs"):
                continue
            try:
                with open(os.path.join(src, fn), encoding="utf-8", errors="replace") as f:
                    txt = f.read()
            except OSError:
                continue
            mission = "OnMissionTick" in txt
            # plik z wyjatkiem w jednej metodzie (wylacznik): trafienia poza jej cialem sa zawsze NIE (stara regula w OnTick dawala tyle samo trafien)
            only_in = _E7C_ONLY_IN.get(fn)
            spans = []
            for sig, cap in (only_in or ()):
                a = txt.find(sig)
                b = txt.find("\n        }", a) if a >= 0 else -1
                spans.append((sig, cap, (txt.count("\n", 0, a), txt.count("\n", 0, b)) if a >= 0 and b >= 0 else (-1, -1)))
            per = [0] * len(spans)
            n = 0
            outside = 0
            for i, ln in enumerate(txt.splitlines()):
                code = ln.split("//", 1)[0]
                k = len(_E7C_PAT.findall(code)) + (0 if mission else len(_E7C_ACC.findall(code)))
                n += k
                if spans and k:
                    for j, (_, _, sp) in enumerate(spans):
                        if sp[0] <= i <= sp[1]:
                            per[j] += k
                            break
                    else:
                        outside += k
            over_m = [f"{sig}: {per[j]}/{cap}" for j, (sig, cap, _) in enumerate(spans) if per[j] > cap]
            if n:
                hits[fn] = n
                lim = _E7C_ALLOWED.get(fn, (0, ""))[0]
                if n > lim or outside or over_m:
                    over.append(f"{fn} {n}/{lim}" + (f" (poza {' / '.join(sig for sig, _, _ in spans)}: {outside})" if outside else "")
                                + (f" (ponad limit metody - {', '.join(over_m)})" if over_m else ""))
        hp = hits.get("HideoutPurge.cs", 0)
        rep.add("E7/C T1: zegar realny i akumulatory klatek w logice gry (grep kodu Armoury/src)",
                f"poza lista wyjatkow: {', '.join(over) if over else '0'}; w wyjatkach: "
                + ", ".join(f"{k} {v}" for k, v in sorted(hits.items()) if k in _E7C_ALLOWED)
                + f" (HideoutPurge {hp} - wylacznik w PursuitDue i odstep ponownej proby okna gracza w OnTick, E8/S)",
                "0 poza lista (widok, komunikaty, log, wylacznik HideoutPursuitHours 0 i ponowna proba okna gracza E8/S - po 2 w swojej metodzie, CrossingLaw - etap 8)",
                not over)
        bad = []
        for fn in ("Settings.cs", "McmSettings.cs"):
            try:
                with open(os.path.join(src, fn), encoding="utf-8", errors="replace") as f:
                    row = [ln for ln in f if ("WorldPacePercent =" in ln and "//" in ln) or ('"World Pace Percent"' in ln and "HintText" in ln)]
            except OSError:
                row = []
            if not row:
                bad.append(f"{fn}: brak wiersza")
            for ln in row:
                if "168" in ln or "month" in ln.lower():
                    bad.append(fn)
        rep.add("E7/C T2: tekst MCM World Pace Percent bez 168 i obietnicy miesiaca", "; ".join(bad) if bad else "czysty (Settings.cs, McmSettings.cs)",
                "bez '168' i 'month'", not bad)
    st_ = [s for s in lines if s.startswith("Jedna skala czasu (E7/C)")]
    rep.add("E7/C: linia startowa", st_[-1] if st_ else "brak (log sprzed E7/C?)", "INFO (co ile godzin gry odwet odnawia pogon)", None)
    rr = [s for s in lines if s.startswith("HideoutPurge: pogon") and "(E7/C:" in s]
    if rr:
        ren = sum(num(r"odnowien (\d+) w", s, default=0) or 0 for s in rr)
        hrs = sum(fnum(r" w ([0-9.]+) h gry =", s, default=0.0) or 0.0 for s in rr)
        steps = sorted({m.group(1) for s in rr for m in [re.search(r"; (co [^)]+)\)", s)] if m})
        rate = f"{ren * 24.0 / hrs:.1f}" if hrs > 0.01 else "-"
        rep.add("E7/C T3: odnowien pogoni odwetu na dobe gry (caly log)", f"{len(rr)} pogoni, odnowien {ren} w {hrs:.1f} h gry = {rate} na dobe ({'; '.join(steps)})",
                "INFO (klucz 0.5 h - ok. 48 na dobe przy kazdej predkosci gry)", None)
    else:
        rep.add("E7/C T3: odnowien pogoni odwetu na dobe gry", "brak pogoni w logu", "INFO (odwet rusza po przeszukaniu kryjowki z bandami w poblizu)", None)


E7K_START = "Czas swiata (E7/K):"
E7K_CTW = re.compile(r"^Wezwania do wojny \(168\): .+ wzywa .+ przez (\d+) dob")


def etap7_k(rep, lines, start, until, logp=None, csp=None):
    """E7/K (226): turnieje, sojusze i rozejm w roku 364 (projekt etapu 7 v2 rozdz. 3 "E7/K" Test, PLAN 7.7, R8). T8 linia startowa "Czas swiata (E7/K)":
    prefiks turniejow wpiety i trafia (metoda na koncu lancucha modeli z DefaultTournamentModel), postfiksy sojuszy wpiete, postfiks rozejmu wpiety i po BK;
    T1 najdluzsze okno bez startu turnieju gry < 14 dob, T2 starty w kazdym tygodniu pory (okno >= tyle tygodni, ile ma pora), T3 nowe porozumienia wezwan
    168 "przez N dob" = wezwanie z linii startowej (182 przy roku 364; caly log po linii startowej), T4 KRONIKA WOJEN (CS) - wojen naraz w kazdej linii dob
    kampanii 61-until >= 7, T7 nowa wojna z decyzji krolestwa (przyczyna CausedByKingdomDecision) po pokoju tej pary krocej niz rozejm z linii startowej
    (cale dni linii, -1 na zaokraglenie dnia) - 0, T0 bledy WorldTime7 i potkniecia E7/K 0. Wstrzymane propozycje, T5 nagrody turniejow (Szczelnosc 164a),
    T6 GrandTourney - INFO. Wylacznik off w linii startowej - progi tej czesci INFO."""
    st_ = [s for s in lines if s.startswith(E7K_START)]
    if not st_:
        rep.add("E7/K: linia startowa Czas swiata (E7/K)", "brak w logu", "jest od wgrania E7/K (log sprzed E7/K?)", None)
        return
    s0 = st_[-1]
    tour_on = "turnieje co 3. tydzien" in s0
    diplo_on = "DiplomacyYearLong off" not in s0
    part = num(r"wezwanie (\d+)", s0)
    truce = num(r"rozejm gry (\d+) dni", s0)
    bad = []
    if tour_on and ("prefiks wpiety" not in s0 or "(trafia)" not in s0):
        bad.append("prefiks turniejow niewpiety albo nie trafia")
    if "postfiksy wpiete" not in s0:
        bad.append("postfiksy sojuszy niewpiete")
    if "(postfiks wpiety" not in s0:
        bad.append("postfiks rozejmu niewpiety")
    if "po BK NIE" in s0:
        bad.append("rozejm przed BK")
    if "| BRAK:" in s0:
        bad.append("BRAK")
    rep.add("E7/K T8: linia startowa - latki wpiete (rozejm po BK, prefiks turniejow trafia)", s0[:400] + (f" | {'; '.join(bad)}" if bad else ""),
            "postfiks rozejmu wpiety, bez BRAK i NIE", not bad)
    # ---- T0 bledy i potkniecia
    errs = [s for s in lines if s.startswith("ERROR in WorldTime7")]
    wd = {}
    for s in lines:
        if s.startswith("Wojna i pokoj (E7/0): dzien") and "| od poprzedniej linii:" in s:
            k = num(r"dzien (\d+)", s)
            if k is not None:
                wd[k] = s
    win_w = [d for d in sorted(wd) if 1 <= run_day(d, start) <= until]
    stum = max([num(r"E7/K potkniecia (\d+)", wd[d], default=0) or 0 for d in win_w] or [0])
    rep.add("E7/K T0: bledy WorldTime7 i potkniecia E7/K", f"ERROR in WorldTime7 {len(errs)}; potkniecia (najwiecej w linii dobowej) {stum}"
            + (f" (pierwszy: {errs[0][:160]})" if errs else ""), "0 i 0", len(errs) == 0 and stum == 0)
    if logp:
        crashscribe_t1_row(rep, "E7/K T0: bledy WorldTime7 polkniete przez CrashScribe (log sesji)", logp, csp, where_filter="WorldTime7")
    held = [num(r"wstrzymane rozejmem: (\d+)", wd[d]) for d in win_w]
    held = [h for h in held if h is not None]
    rep.add("E7/K: propozycje wojny gry wstrzymane rozejmem (okno)",
            f"{sum(held)} w {len(held)} dobach z liczba" if held else "brak liczby w linii dobowej (pomiar E7/0 wylaczony albo DiplomacyYearLong off)",
            "INFO (gra losuje znow przy nastepnej probie)", None)
    # ---- T1/T2 turnieje
    tu = by_day(lines, "Turnieje (E7/0): dzien")
    win = [d for d in sorted(tu) if 1 <= run_day(d, start) <= until]
    if not win:
        rep.add("E7/K T1/T2: turnieje gry", "brak linii Turnieje (E7/0) w oknie", "linia E7/0 (Stage7MeasureLog)", None)
    else:
        started = {d: (num(r"rozpoczete od poprzedniej linii (\d+)", tu[d], default=0) or 0) for d in win}
        gap, best, best_end, weeks = 0, 0, None, {}
        for d in win:
            if started[d] > 0:
                gap = 0
                w = num(r"tydzien pory (\d+)", tu[d])
                if w is not None:
                    weeks[w] = weeks.get(w, 0) + started[d]
            else:
                gap += 1
                if gap > best:
                    best, best_end = gap, d
        rep.add("E7/K T1: najdluzsze okno bez startu turnieju gry", f"{best} dob" + (f" (do d{run_day(best_end, start)})" if best_end is not None else "")
                + f"; startow {sum(started.values())} w {len(win)} dobach", "< 14 dob" if tour_on else "INFO (TournamentsAllSeason off)",
                (best < 14) if tour_on else None)
        wmax = num(r"tydzien pory \d+ \(0-(\d+)", tu[win[-1]])
        nweeks = (wmax if wmax is not None else 12) + 1
        empty = [w for w in range(nweeks) if w not in weeks]
        enough = len(win) >= 7 * nweeks
        rep.add("E7/K T2: starty turniejow w kazdym tygodniu pory", f"tygodnie bez startu {empty if empty else '-'} (z 0-{nweeks - 1}; okno {len(win)} dob)",
                "brak pustych tygodni" if tour_on and enough else "INFO (okno krotsze niz pora albo TournamentsAllSeason off)",
                (not empty) if tour_on and enough else None)
    # ---- T3 porozumienia wezwan 168 (caly log po pierwszej linii startowej E7/K)
    i0 = lines.index(st_[0])
    durs = []
    for s in lines[i0:]:
        m = E7K_CTW.match(s)
        if m:
            durs.append(int(m.group(1)))
    if not durs:
        rep.add("E7/K T3: nowe porozumienia wezwan (168) - przez N dob", "brak nowych porozumien po linii startowej", f"INFO (oczekiwane {part} dob)", None)
    else:
        other = sorted({x for x in durs if x != part})
        rep.add("E7/K T3: nowe porozumienia wezwan (168) - przez N dob", f"{len(durs)} porozumien, inne niz {part}: {other if other else '-'}",
                f"wszystkie {part} dob (wezwanie z linii startowej)", (not other) if part is not None else None)
    # ---- T4 KRONIKA (CS): wojen naraz w dobach kampanii 61-until (chwile z zegara obu logow, jak E7/0 T1)
    name4 = f"E7/K T4: KRONIKA WOJEN (CS) - wojen naraz w dobach kampanii 61-{until}"
    if until < 61:
        rep.add(name4, f"okno do d{until}", ">= 7 (od doby 61)", None)
    elif not logp:
        rep.add(name4, "bez logu", ">= 7", None)
    else:
        path, how = crashscribe_session_of(logp, csp)
        a0 = _start_dt_of(logp) or (armoury_start_times(logp) or [None])[0]
        c0 = _start_dt_of(path) if path else None
        if not path or a0 is None or c0 is None:
            rep.add(name4, how if not path else "brak chwili startu logu Armoury albo CS", ">= 7 (bez logu sesji - INFO)", None)
        else:
            days = {d for d in tu if 61 <= run_day(d, start) <= until}
            times = [t for t, s in _abs_lines(logp, a0) if s.startswith("Turnieje (E7/0): dzien") and num(r"dzien (\d+)", s) in days]
            if not times:
                rep.add(name4, "brak linii Turnieje (E7/0) w dobach 61-until", ">= 7", None)
            else:
                lo, hi = min(times), max(times)
                cnt = []
                for t, s in _abs_lines(path, c0):
                    m = E7_KRON.match(s)
                    if m and m.group(1) == "dzien" and lo <= t <= hi:
                        cnt.append(len(_kron_set(m.group(2))))
                if not cnt:
                    rep.add(name4, f"brak linii KRONIKI (dzien) w czasie dob 61-until ({os.path.basename(path)})", ">= 7", None)
                else:
                    rep.add(name4, f"najmniej {min(cnt)}, srednio {sum(cnt) / len(cnt):.1f}, najwiecej {max(cnt)} ({len(cnt)} linii; {os.path.basename(path)})",
                            ">= 7 w kazdej linii (polowa 14-17 z 11.10)", min(cnt) >= 7)
    # ---- T7 nowa wojna z decyzji krolestwa przed koncem rozejmu gry
    lim = (truce - 1) if truce is not None else None
    viol, n_kd = [], 0
    for s in lines:
        m = E7_WAR.match(s)
        if not m or m.group(4) != "WOJNA" or not m.group(5).startswith("CausedByKingdomDecision") or not (1 <= run_day(int(m.group(1)), start) <= until):
            continue
        n_kd += 1
        dd = num(r"tej pary (\d+) \(POKOJ\)", s)
        if dd is not None and lim is not None and dd < lim:
            viol.append(f"{m.group(2)} - {m.group(3)} {dd} d (d{run_day(int(m.group(1)), start)})")
    val7 = f"{len(viol)} z {n_kd} wojen z decyzji krolestwa" + (f": {'; '.join(viol[:5])}" if viol else "")
    rep.add("E7/K T7: nowa wojna z decyzji krolestwa krocej niz rozejm gry po pokoju tej pary", val7,
            f"0 (rozejm {truce} dni, prog {lim} cale dni; decyzje gracza i Diplomacy - pytanie 3 - recznie)" if diplo_on else "INFO (DiplomacyYearLong off)",
            (not viol) if diplo_on and lim is not None else None)
    # ---- T5 nagrody turniejow (Szczelnosc 164a), T6 GrandTourney
    sea = by_day(lines, "Szczelnosc (164a): dzien")
    want = paid = cut = 0
    for d in sea:
        if 1 <= run_day(d, start) <= until:
            m = re.search(r"nagrody turniejow: gra chciala (\d+), zaplacili (\d+), uciete (\d+)", sea[d])
            if m:
                want += int(m.group(1))
                paid += int(m.group(2))
                cut += int(m.group(3))
    rep.add("E7/K T5: nagrody turniejow AI (Szczelnosc 164a, okno)", f"gra chciala {want}, zaplacili {paid}, uciete {cut}" + (f" ({100.0 * cut / want:.1f}%)" if want else ""),
            "INFO (platnik - miasto-gospodarz z nadwyzka)", None)
    rep.add("E7/K T6: GrandTourney - zjazdy lordow na sezon", "poza blokiem (log GrandTourney - skopiowac przed biegiem zapisu)", "INFO (ok. 4x wiecej turniejow na rok)", None)


E7O2_START = "CampScene (E7/O2): prefaby dostepne"


def etap7_o2(rep, lines, start, until, logp=None, csp=None):
    """E7/O2 (229): namioty i ogniska przy napadzie na oboz gracza (projekt etapu 7 v2 rozdz. 3 "E7/O2", R18). T1 linia startowa "CampScene (E7/O2):
    prefaby dostepne - namioty x/5, ogniska y/3, pochodnie z/2, plot w/2 (bez fizyki)" (co sesje przy kluczu CampBattlePropsEnabled): kazdy element >= 1
    (wszyscy kandydaci sa w Native 1.4.8), bez bledow PrefabExists; T0 bledy CampScene (ERROR in CampScene...) 0; postawione w misjach - INFO
    (T2 test Jeffa: napad na jego oboz, wojsko nie grzeznie - autotest nie gra bitew w obozie gracza)."""
    st_ = [s for s in lines if s.startswith(E7O2_START)]
    if not st_:
        rep.add("E7/O2 T1: linia startowa CampScene (prefaby obozu)", "brak",
                "linia w kazdej sesji (klucz CampBattlePropsEnabled = true - wpis Armoury.json Jeffa poprawiony przy wgraniu)", False)
    else:
        bad = set()
        for s in st_:
            for lab in ("namioty", "ogniska", "pochodnie", "plot"):
                if (num(lab + r" (\d+)/\d+", s, default=0) or 0) < 1:
                    bad.add(lab)
            if "bledy PrefabExists" in s:
                bad.add("bledy PrefabExists")
        rep.add("E7/O2 T1: linia startowa CampScene (prefaby obozu)", f"{len(st_)} sesji; ostatnia: {st_[-1][len('CampScene (E7/O2): '):]}"
                + (f"; braki: {', '.join(sorted(bad))}" if bad else ""), "kazdy element >= 1, bez bledow PrefabExists", not bad)
    errs = [s for s in lines if s.startswith("ERROR in CampScene")]
    rep.add("E7/O2 T0: bledy CampScene (ERROR in CampScene)", len(errs), "0", len(errs) == 0)
    pl = [s for s in lines if s.startswith("CampScene: postawiono")]
    if pl:
        n = [num(r"postawiono (\d+)", s, default=0) or 0 for s in pl]
        fr = sorted({m.group(1) for s in pl for m in [re.search(r"front: ([^,]+),", s)] if m})
        rep.add("E7/O2: bitwy w obozie gracza ze scenografia", f"{len(pl)} bitew, elementow {sum(n)} (min {min(n)}, maks {max(n)} z 10); front: {', '.join(fr) or '-'}",
                "INFO (T2 - test Jeffa: wojsko nie grzeznie)", None)
    else:
        rep.add("E7/O2: bitwy w obozie gracza ze scenografia", "brak w logu", "INFO (autotest nie gra bitew w obozie gracza; T2 - test Jeffa)", None)


def etap7_main(logp, start_arg, until=120, csp=None):
    """E7/0 (224): grupa --grupa etap7 (projekt etapu 7 v2 rozdz. 3 i 4). Okno: doby kampanii 1-until (--do-doby), start kampanii jak etap5_main
    (linia "Pomiary 169c: ... start kampanii dzien N", inaczej pierwsza doba logu). Kolejne paczki dopisuja WLASNE bloki etap7_<paczka>(rep, lines,
    start, until, ...); kazdy blok rusza tylko przy swojej linii - brak linii = wiersz INFO, nigdy wyjatek.
    Scalenie zbior-5-8: bloki galezi e7-b (E7/B 231 i dalej) maja konwencje (rep, lines, start, win, until=..) - win = doby z linia "Pieniadz swiata"
    w oknie; bloki galezi e7-a (E7/0 224 i dalej) - (rep, lines, start, until, logp=, csp=)."""
    lines = read(logp)
    rep = Report()
    start = start_arg
    if start is None:
        for s in lines:
            if s.startswith("Pomiary 169c: okna"):
                start = num(r"start kampanii dzien (\d+)", s)
                if start is not None:
                    break
    alld = sorted(by_day(lines, "Pieniadz swiata: dzien"))
    if start is None:
        start = alld[0] if alld else 0
    win = [d for d in alld if 1 <= run_day(d, start) <= until]
    print(f"plik: {logp} | doby z linia Pieniadz swiata: {len(alld)} (doby kampanii {run_day(alld[0], start) if alld else '-'}-{run_day(alld[-1], start) if alld else '-'})"
          f" | start kampanii {start} | okno progow: doby kampanii 1-{until} ({len(win)} dob)")
    # scalenie zbior-5-8: obie galezie etapu 7 zbudowaly szkielet grupy; jeden szkielet, dwie konwencje wywolania (opis w docstringu)
    blocks = ([(b, False) for b in (etap7_0, etap7_o1, etap7_t, etap7_c, etap7_k, etap7_o2)]
              + [(b, True) for b in (etap7_b, etap7_w1, etap7_w2, etap7_w3, etap7_w5, etap7_d0, etap7_r1, etap7_r2, etap7_w4)])
    for blk, by_win in blocks:   # kolejne paczki etapu 7 dopisuja tu swoje bloki
        try:
            if by_win:
                blk(rep, lines, start, win, until=until, logp=logp)   # narzedzie progow zb58: logp dla plikow sesji (E7/R1 T5 - wioski-okregi.csv)
            else:
                blk(rep, lines, start, until, logp=logp, csp=csp)
        except Exception as e:   # narzedzie nigdy nie przerywa raportu
            rep.add(f"blok {blk.__name__}", f"wyjatek narzedzia: {e}", "bez wyjatku", False)
    rep.show()
    return 0


# ============================================================ ETAP 7 (E7/B, paczka 231): bloki galezi e7-b (szkielet grupy - etap7_main wyzej, wspolny po scaleniu)
def etap7_b(rep, lines, start, win, until=120, **kw):
    """E7/B (231, PLAN 7.12, projekt etapu 7 v2 rozdz. 3 "E7/B" Test): linia startowa "Przeprawa Bliznaki (E7/B): os rzeki" i linia doby
    "Przeprawa Bliznaki (E7/B): dzien N" (dzien = doba gry, jak "Juczne (213)"; "Pieniadz swiata" nosi dzien ksiegi = doba gry - 1, stad -1 w T1).
    Wiazace: os bez BRAK OSI, T1 linia z licznikiem w kazdej dobie okna, T2 przejsc > 0, T3 pozycje <= 2 jedn. od mostu (od F8 pole "odl. od mostu";
    log sprzed F8: <= 1 jedn. od srodka lukow wody na osi rzeki), T4 koszt < 0.5 ms/dobe (mediana), potkniecia 0; od F9b (poprawka F8 - strefa r 8 wokol
    mostu): F8-1 przejsc poza mostem 0, F8-2 zmiana strony poza strefa 0, F8-3 linia startowa "most na osi", "strefa r 8 od mostu", brama < 8 jedn. od
    mostu i linie doby "od mostu" (log sprzed F8 - INFO "brak linii")."""
    axis = [s for s in lines if s.startswith("Przeprawa Bliznaki (E7/B): os rzeki")]
    rows = {}
    for d, s in by_day(lines, "Przeprawa Bliznaki (E7/B): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rows[rd] = s
    if not axis and not rows:
        rep.add("E7/B: linie Przeprawa Bliznaki (E7/B)", "brak w logu", "sa od wgrania E7/B (TwinsCrossingCount, LogEnabled)", None)
        return
    if axis:
        a = axis[-1]
        ok = ("BRAK OSI" not in a) and (" nie ma " not in a)
        rep.add("E7/B B-0: os rzeki przy moscie (2 luki wody na okregu r 4)", a[:420], "os wyznaczona (bez BRAK OSI) - inaczej wzorce okregow r3-r6 w linii", ok)
    else:
        rep.add("E7/B B-0: os rzeki przy moscie", "brak linii startowej", "jest przy pierwszej godzinie gry sesji", None)
    days = sorted(rows)
    live = [x for x in days if "| przejsc " in rows[x]]
    need = max(0, len(win) - 1)
    rep.add("E7/B T1: linia Przeprawa Bliznaki z licznikiem", f"{len(live)} dob (wszystkich linii {len(days)}; dob okna {len(win)})",
            f">= {need} (codziennie w oknie; dzien gry = dzien ksiegi + 1)", (len(live) >= need and need > 0) if win else None)
    if not live:
        return
    w = [rows[x] for x in live]

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    n = tot(r"\| przejsc (\d+) \(")
    rep.add("E7/B T2: przejsc mostem (suma okna)", f"{n} ({n / len(w):.1f}/d)", "> 0", n > 0)
    # narzedzie progow F9b (F8, T3): od F8 strefa probek lezy wokol mostu, a pole pozycji nazywa sie "odl. od mostu" (liczba w nawiasie = odleglosc od
    # mostu na osi rzeki) - prog wszystkie <= 2 jedn.; log sprzed F8 ("odl. od bramy") - miara F9a nizej (odleglosc od srodka lukow wody, <= 1 jedn.)
    pos, pts, from_bridge = [], [], False
    for x in w:
        m = re.search(r"pozycje przejsc \(x/y, odl\. od (bramy|mostu)\): (.*?)\.$", x)
        if m and m.group(1) == "mostu":
            from_bridge = True
        if m and m.group(2) != "brak":
            for px, py, pd in re.findall(r"(-?[\d.]+)/(-?[\d.]+) \(([\d.]+)\)", m.group(2)):
                pos.append(float(pd))
                pts.append((float(px), float(py)))
    # narzedzie progow zb58 (TRIAZ E7/B T3): pozycja osady (brama) to nie most - na mapie ROT rzeka plynie obok miasta (brama 4.69 jedn. od osi), wiec
    # odleglosc od bramy to geometria, nie znak brodu. Most = punkt na osi rzeki: srodek dwoch srodkow lukow wody z linii startowej ("luki 2 (srodki
    # a/b, c/d)"); wszystkie pozycje maja lezec <= 1 jedn. od niego (pozycje w drugim skupisku = brod albo drugi most w strefie). Linia startowa bez
    # dwoch lukow - stara miara od bramy.
    brg = None
    if axis:
        m = re.search(r"luki 2 \(srodki (-?[\d.]+)/(-?[\d.]+), (-?[\d.]+)/(-?[\d.]+)\)", axis[-1])
        if m:
            c = [float(v) for v in m.groups()]
            brg = (0.5 * (c[0] + c[2]), 0.5 * (c[1] + c[3]))
    if from_bridge:
        far = [v for v in pos if v > 2.0]
        rep.add("E7/B T3: pozycje przejsc z 3 pierwszych dob sesji - odleglosc od mostu (pole \"odl. od mostu\", od F8)",
                f"{len(pos)} pozycji, dalej niz 2 jedn.: {len(far)}" + (f" (najdalej {max(pos):.1f})" if pos else ""),
                "wszystkie <= 2 jedn. od mostu (oczekiwane 0.0-0.3; inaczej brod albo drugi most w strefie)", (len(far) == 0) if pos else None)
    elif brg and pts:
        dist = [((px - brg[0]) ** 2 + (py - brg[1]) ** 2) ** 0.5 for px, py in pts]
        far = [v for v in dist if v > 1.0]
        rep.add("E7/B T3: pozycje przejsc z 3 pierwszych dob sesji - odleglosc od mostu (srodek lukow wody na osi rzeki)",
                f"{len(pts)} pozycji, most {brg[0]:.2f}/{brg[1]:.2f}, dalej niz 1 jedn.: {len(far)} (najdalej {max(dist):.2f}; od bramy najdalej {max(pos):.1f})",
                "wszystkie <= 1 jedn. od mostu (inaczej brod albo drugi most w strefie - zmniejszyc promien)", len(far) == 0)
    else:
        far = [v for v in pos if v > 3.0]
        rep.add("E7/B T3: pozycje przejsc z 3 pierwszych dob sesji - odleglosc od bramy", f"{len(pos)} pozycji, dalej niz 3 jedn.: {len(far)}" + (f" (najdalej {max(pos):.1f})" if pos else ""),
                "wszystkie <= 3 jedn. (inaczej brod albo drugi most w strefie - zmniejszyc promien)", (len(far) == 0) if pos else None)
    cost = [num(r"koszt probek ([\d.]+) ms/dobe", x, float) for x in w]
    cm = _mean(cost)
    # narzedzie progow zb58 (TRIAZ E7/B T4): prog 0.1 ms byl szacunkiem "ok. 0"; 24 zapytania lokatora mapy na dobe to ok. 0.19 ms (mediana), a srednia
    # zawyza pierwsza doba sesji z jednorazowym liczeniem osi rzeki (ok. 3 ms) - prog 0.5 ms liczony z mediany
    cs = sorted(v for v in cost if v is not None)
    if cs:
        med = cs[len(cs) // 2] if len(cs) % 2 else 0.5 * (cs[len(cs) // 2 - 1] + cs[len(cs) // 2])
        rep.add("E7/B T4: koszt probek godzinnych (mediana)", f"mediana {med:.3f} ms/dobe (srednio {cm:.3f}, najwiecej {cs[-1]:.3f} - doba z liczeniem osi rzeki)",
                "< 0.5 ms/dobe z mediany (szacunek projektu 0.1 = 'ok. 0')", med < 0.5)
    else:
        rep.add("E7/B T4: koszt probek godzinnych (mediana)", "brak", "< 0.5 ms/dobe z mediany", None)
    stu = tot(r"potkniecia dzis (\d+)")
    rep.add("E7/B B-5: potkniecia (suma okna)", f"{stu}", "0", stu == 0)
    # narzedzie progow F9b (F8): strefa probek wokol mostu na osi rzeki i dwa liczniki kontrolne linii doby ("| kontrola: przejsc poza mostem N (...;
    # najdalej dzis X), zmiana strony poza strefa M (...)"); log sprzed F8 (strefa od bramy, bez licznikow) - INFO "brak linii"
    f8 = [x for x in w if "| kontrola: przejsc poza mostem " in x]
    a8 = axis[-1] if axis else ""
    if not f8 and "most na osi " not in a8:
        rep.add("E7/B F8-1..F8-3: strefa wokol mostu i liczniki kontrolne (F8)",
                "brak linii (log sprzed F8" + (" - strefa r 8 od bramy, licznik zaniza do ok. 5%" if "strefa r 8 od bramy" in a8 else "") + ")",
                "pola sa od F8 (most na osi, kontrola: przejsc poza mostem, zmiana strony poza strefa)", None)
    else:
        offb = sum(num(r"kontrola: przejsc poza mostem (\d+)", x, int, 0) or 0 for x in f8)
        farv = [v for v in (num(r"najdalej dzis ([\d.]+)", x, float) for x in f8) if v is not None]
        rep.add("E7/B F8-1: przejscia poza mostem (punkt przejscia ponad prog od mostu; suma okna)",
                f"{offb} w {len(f8)} dobach" + (f"; najdalej od mostu {max(farv):.1f} jedn." if farv else "; brak przejsc z pomiarem"),
                "0 (wynik > 0: os nie pasuje do rzeki albo cieciwa dlugiego skoku - zglosic, nie zaliczac)", (offb == 0) if f8 else None)
        ls = [x for x in f8 if ", zmiana strony poza strefa " in x]
        lost = sum(num(r"zmiana strony poza strefa (\d+)", x, int, 0) or 0 for x in ls)
        # narzedzie progow p2 (TRIAZ-2 f-E7/B F8-2): licznik lapie partie zapamietana w strefie r 8, ktora godzine pozniej jest poza strefa po drugiej
        # stronie PROSTEJ osi - bieg 2: 12 zdarzen w 119 dobach (po 1 na dobe) przy 1096 przejsciach mostem i F8-1 = 0 (najdalej 1.8 jedn.). Prosta os
        # zmierzono do ok. 5 jedn. od mostu; dalej rozjezdza sie z rzeka (partia idaca brzegiem "zmienia strone" bez przeprawy) albo jest druga przeprawa
        # 8-16 jedn. od mostu - log tego nie rozroznia (licznik nie zapisuje pozycji). Dla licznika myta to najwyzej 12 / 1096 = 1.1% zanizenia, wiec
        # prog: <= 2% przejsc mostem zamiast 0; F8-1 (przejscia poza mostem = 0) bez zmian.
        rep.add("E7/B F8-2: zmiana strony rzeki poza strefa (suma okna)", f"{lost} w {len(ls)} dobach" + (f" = {100.0 * lost / n:.1f}% z {n} przejsc mostem" if n else ""),
                "<= 2% przejsc mostem (tyle najwyzej zaniza licznik przejsc i myta; wiecej = rozjazd osi z rzeka albo inna przeprawa - rozstrzyga F8-1 i pozycje zdarzen)",
                (lost <= 0.02 * n) if (ls and n) else ((lost == 0) if ls else None))
        mb = re.search(r"most na osi (-?[\d.]+)/(-?[\d.]+)", a8)
        gd = num(r"\), ([\d.]+) jedn\. od mostu", a8, float)
        zone = "strefa r 8 od mostu" in a8
        dz = [x for x in w if re.search(r"strefa r \d+ od mostu: partii", x)]
        rep.add("E7/B F8-3: strefa probek wokol mostu na osi rzeki (linia startowa i linie doby)",
                ((f"most na osi {mb.group(1)}/{mb.group(2)}" if mb else "brak pola \"most na osi\"") + (", strefa r 8 od mostu" if zone else ", brak \"strefa r 8 od mostu\"")
                 + (f", brama {gd:.2f} jedn. od mostu" if gd is not None else ", brak odleglosci bramy od mostu") if axis else "brak linii startowej")
                + f"; linie doby ze strefa od mostu {len(dz)} z {len(w)}"
                + (" - stary napis \"strefa r 8 od bramy\" (licznik sprzed F8 zaniza do ok. 5%)" if "strefa r 8 od bramy" in a8 else ""),
                "most na osi, strefa r 8 od mostu, brama < 8 jedn. od mostu, wszystkie linie doby \"od mostu\"",
                (bool(mb) and zone and gd is not None and gd < 8.0 and len(dz) == len(w)) if axis else None)
    car, vil, cown, cfor = tot(r" - karawany (\d+) \("), tot(r", wozy wsi (\d+)"), tot(r"\(krolestwo pana (\d+) /"), tot(r" / obce (\d+)\)")
    band, oth, pl = tot(r", bandy (\d+), inne"), tot(r", inne (\d+), gracz"), tot(r", gracz TAK \((\d+)\)")
    ns = (tot(r"\(na polnoc (\d+),"), tot(r", na poludnie (\d+)\)"))
    ew = (tot(r"\(na wschod (\d+),"), tot(r", na zachod (\d+)\)"))
    side = f"na polnoc {ns[0]}, na poludnie {ns[1]}" if ns != (0, 0) or ew == (0, 0) else f"na wschod {ew[0]}, na zachod {ew[1]}"
    rep.add("E7/B B-6: przejscia wedlug rodzaju (suma okna)", f"{side}; karawany {car}, wozy wsi {vil}, rody krolestwa pana {cown} / obce {cfor}, bandy {band}, inne {oth}, gracz {pl}",
            "INFO", None)
    toll = tot(r"\| myto gdyby bylo (\d+) zl")
    gold = tot(r"\(kiesy (\d+) zl")
    rep.add("E7/B B-7: myto gdyby bylo (suma okna, 2 zl od czlowieka, 1 zl od zwierzecia, rody krolestwa pana bez myta)",
            f"{toll} zl ({toll / len(w):.0f}/d); kiesy karawan przy przejsciu {gold} zl", "INFO (tylko do porownania - nikt nie placi; decyzja Jeffa po tescie)", None)
    ent = 0
    for d, s in by_day(lines, "Miara historyczna cz. 2 (169c): dzien").items():
        if 1 <= run_day(d, start) <= until:
            ent += num(r"\(e\) Bliznaki: wejscia do osady (\d+)", s, int, 0) or 0
    rep.add("E7/B B-8: wejscia do osady Bliznaki (169c (e)) obok przejsc", f"wejsc {ent}, przejsc {n}", "INFO (porownanie)", None)



def etap7_w1(rep, lines, start, win, until=120, **kw):
    """E7/W1 (232, PLAN 7.10 a, projekt etapu 7 v2 rozdz. 3 "E7/W1" Test): linia doby "Wioski - wiesci (E7/W1): dzien N" (dzien ksiegi = doba gry - 1, jak
    "Ksiega wiosek (E4/11)" i "Ludzie (spustoszenie)"), linia zapisu "Wioski - wiesci (E7/W1): zapis - pamiec wojny N wpisow" i odcinek "pamiec wojny (E7/W1) M wpisow"
    linii "Ksiega wiosek (E4/11): start sesji". Wiazace: T0, T1 (+-1/dobe), T2, T3 (gdy byl zapis i wczytanie), T4, T5."""
    rows = {}
    for d, s in by_day(lines, "Wioski - wiesci (E7/W1): dzien").items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rows[d] = s
    saves = [s for s in lines if s.startswith("Wioski - wiesci (E7/W1): zapis")]
    if not rows and not saves:
        rep.add("E7/W1: linie Wioski - wiesci (E7/W1)", "brak w logu", "sa od wgrania E7/W1 (LogEnabled)", None)
        return
    days = sorted(rows)
    need = max(0, len(win) - 1)
    rep.add("E7/W1 T0: linia Wioski - wiesci (E7/W1)", f"{len(days)} dob (dob okna {len(win)})", f">= {need} (codziennie w oknie)",
            (len(days) >= need and need > 0) if win else None)

    def tot(pat):
        return sum(num(pat, rows[x], int, 0) or 0 for x in days)
    if days:
        a = tot(r"\| plonie: zdarzen (\d+) \(")
        dev = {}
        for d, s in by_day(lines, "Ludzie (spustoszenie): dzien").items():
            if d in rows:
                dev[d] = num(r"\| rabunki zakonczone (\d+) \(", s, int, 0) or 0
        r1 = {}
        for d, s in by_day(lines, "Rabunek osada po osadzie (E7/R1): dzien").items():
            if d in rows:
                r1[d] = num(r"sesji (\d+)", s, int, 0) or 0
        raids = sum(dev.values()) + sum(r1.values())
        rep.add("E7/W1 T1: zdarzen plonie = rabunki zakonczone (Ludzie (spustoszenie)) + sesje E7/R1 (suma okna)",
                f"plonie {a}, rabunki {sum(dev.values())} + R1 {sum(r1.values())} = {raids} (roznica {a - raids:+d}, dob {len(days)})",
                "|roznica| <= liczba dob (+-1/dobe - dedup milicji, rabunek przegrany z milicja bez lupienia)", (abs(a - raids) <= len(days)) if dev else None)
        p_shown = tot(r"\), komunikatow (\d+) \(by bylo")
        shown = p_shown + tot(r"komunikatow \"burned\" (\d+),") + tot(r"komunikatow \"plundered\" (\d+),")
        would = tot(r"\(by bylo (\d+)\); spladrowane") + tot(r"\"burned\" \d+, by bylo (\d+)\)") + tot(r"\"plundered\" \d+, by bylo (\d+);")
        own = tot(r"\(wsie gracza (\d+),")
        rep.add("E7/W1 T2: komunikaty zbudowane, a nie pokazane (by bylo - dowod sciezki)", f"by bylo {would}, pokazanych {shown} (wsie gracza w zdarzeniach plonie {own})",
                "> 0", (would > 0) if a > 0 else None)
        rep.add("E7/W1 T2b: pokazane plonie przy braku wsi gracza w zdarzeniach", f"{p_shown} (wsie gracza {own})", "0 gdy wsie gracza 0 (autotest bez lenna)",
                (p_shown == 0) if own == 0 else None)
        stu = tot(r"potkniecia dzis (\d+)")
        rep.add("E7/W1 T4: potkniecia (suma okna)", f"{stu}", "0", stu == 0)
        book = by_day(lines, "Ksiega wiosek (E4/11): dzien")
        bad, tot_i, tot_b = [], 0, 0
        for x in days:
            i = num(r"\| spalone w ksiedze (\d+) \(", rows[x], int, 0) or 0
            b = num(r"\| spalone dzis (\d+)", book.get(x, ""), int, 0) or 0
            tot_i += i
            tot_b += b
            if i != b:
                bad.append(f"d{x}: {i}/{b}")
        rep.add("E7/W1 T5: spalone w ksiedze (W1) = spalone dzis (Ksiega wiosek) w kazdej dobie",
                f"{tot_i} / {tot_b}; dob niezgodnych {len(bad)}" + (f" ({', '.join(bad[:6])})" if bad else ""), "0 dob niezgodnych", len(bad) == 0)
        kb = tot(r"komunikatow \"burned\" (\d+),") + tot(r"\"burned\" \d+, by bylo (\d+)\)")
        rep.add("E7/W1 T5b: komunikaty burned (z by bylo) <= spalone w ksiedze", f"{kb} <= {tot_i}", "burned tylko przy przejsciu na spalona (R10)", kb <= tot_i)
        f, j = tot(r"; spladrowane (\d+) \("), tot(r", splondrowane bez spalenia (\d+) \(")
        same, nob = tot(r"sesja spalila - bez drugiego (\d+)[,)]"), tot(r"\(bez ksiegi (\d+)\)")
        old = tot(r"juz spalona w ksiedze (\d+)\)")
        rep.add("E7/W1 W1-7: spladrowane (Looted gry) wedlug ksiegi", f"spladrowane {f}: splondrowane bez spalenia {j}, sesja spalila {same}, juz spalona {old}, bez ksiegi {nob}",
                "INFO (f = j + sesja spalila + juz spalona + bez ksiegi)", None)
        mem = num(r"\| pamiec wojny: wpisow (\d+) \(", rows[days[-1]], int, 0) or 0
        mnew = tot(r"pamiec wojny: wpisow \d+ \(nowe (\d+),")
        rep.add("E7/W1 W1-8: pamiec wojny (ostatnia doba okna)", f"wpisow {mem}, nowych zdarzen w oknie {mnew}", "INFO (> 0 przy VillageWarMemory)", None)
        smp = []
        for x in days[:20]:
            m = re.search(r"\| przyklady: (.*)\.$", rows[x])
            if m:
                smp.append(m.group(1))
        rep.add("E7/W1 W1-9: przyklady komunikatow (pierwsze doby)", (smp[0][:240] if smp else "brak"), "INFO (angielski, nazwy wiosek z ksiegi)", None)
    # T3: wczytanie po zapisie - wpisy pamieci przy wczytaniu = ostatni zapis przed nim (stary zapis bez sekcji: 0 wpisow, bez pary)
    pairs, mism, last_save = 0, [], None
    for s in lines:
        if s.startswith("Wioski - wiesci (E7/W1): zapis"):
            last_save = num(r"pamiec wojny (\d+) wpisow", s, int)
        elif s.startswith("Ksiega wiosek (E4/11): start sesji") and "pamiec wojny (E7/W1)" in s:
            got = num(r"pamiec wojny \(E7/W1\) (\d+) wpisow", s, int)
            if last_save is not None and got is not None:
                pairs += 1
                if got != last_save:
                    mism.append(f"{got}/{last_save}")
    rep.add("E7/W1 T3: pamiec wojny zapis -> wczytanie", f"par {pairs}, niezgodnych {len(mism)}" + (f" ({', '.join(mism[:5])})" if mism else ""),
            "0 niezgodnych (bieg zapisu 9 dob)", (len(mism) == 0) if pairs else None)
    rej = sum(num(r"odrzucone przez BadId (\d+)", s, int, 0) or 0 for s in saves)
    rep.add("E7/W1 T6: zapis pamieci - same identyfikatory", f"zapisow {len(saves)}, identyfikatorow odrzuconych przez BadId {rej}",
            "INFO (nazw w sekcji m: nie ma z konstrukcji)", None)


def etap7_r1(rep, lines, start, win, until=120, **kw):
    """E7/R1 (235, PLAN 7.11 a, projekt etapu 7 v2 rozdz. 3 "E7/R1" Test i rozdz. 4 (7.11)): linia startowa "Rabunek osada po osadzie (E7/R1): latki przy starcie gry",
    linia doby "Rabunek osada po osadzie (E7/R1): dzien N" (dzien ksiegi = doba gry - 1, jak "Ludzie (spustoszenie)"), linie "zapis - sesji N, czujnosc M wsi" i
    "wczytanie - sesji N, czujnosc M wsi". Wiazace: R1-0, R1-1, T1, T2, T3, T4 (>= 10 krokow lordow), T5 (przy oknie >= 240 dob; krotsze - INFO), T7, T9 (gdy byl zapis i wczytanie), T10 (>= 20 sesji), T11, koszt."""
    P = "Rabunek osada po osadzie (E7/R1): "
    starts = [x for x in lines if x.startswith(P + "latki przy starcie gry")]
    rows = {}
    for d, x in by_day(lines, P + "dzien").items():
        if 1 <= run_day(d, start) <= until:
            rows[d] = x
    if not starts and not rows:
        rep.add("E7/R1: linie Rabunek osada po osadzie (E7/R1)", "brak w logu", "sa od wgrania E7/R1 (LogEnabled)", None)
        return
    if starts:
        a = starts[-1]
        rep.add("E7/R1 R1-0: latki przy starcie gry", a[:240], "GOTOWE, BRAK: -", ("GOTOWE" in a) and ("BRAK: -" in a))
    off = [x for x in rows.values() if "| WYLACZONE" in x]
    live = sorted(d for d in rows if "| sesji " in rows[d])
    need = max(0, len(win) - 1)
    rep.add("E7/R1 R1-1: linia doby z sesjami", f"{len(live)} dob (wylaczone {len(off)}; dob okna {len(win)})", f">= {need} (codziennie w oknie, klucz Raid By Settlement Enabled)",
            (len(live) >= need and need > 0) if win and not off else None)
    if not live:
        return
    w = [rows[d] for d in live]

    def tot(pat, cast=int):
        return sum(num(pat, x, cast, 0) or 0 for x in w)
    ses = tot(r"\| sesji (\d+) \(")
    steps = tot(r", krokow (\d+) \(")
    intr = tot(r", przerwanych (\d+) \(")
    rel = tot(r"oddane grze \((?:gracz w zdarzeniu, )?potkniecia\) (\d+)")   # E7/R2: sama etykieta "(potkniecia)" - rabunki z graczem prowadzi ta sama regula
    rep.add("E7/R1 R1-2: sesje zakonczone (suma okna)", f"sesji {ses}, krokow pelnych {steps}, przerwanych {intr}, oddanych grze {rel}", "> 0 (rabunki AI pod R1)", ses > 0)
    # T1 - bilans zlota kazdej doby i lup z niczego AI w linii spustoszenia
    b1 = [(d, num(r"zloto wodza - kiesa wsi " + F_, rows[d], float)) for d in live]
    bad1 = [f"d{d}: {x}" for d, x in b1 if x is None or abs(x) >= 1]
    rep.add("E7/R1 T1: bilans zlota (zloto wodza - kiesa wsi) w kazdej dobie", f"dob niezgodnych {len(bad1)} z {len(b1)}" + (f" ({', '.join(bad1[:6])})" if bad1 else ""),
            "0 w kazdej dobie (lup zlota tylko z kiesy wsi - jeden platnik E5/A7)", len(bad1) == 0)
    dev = by_day(lines, "Ludzie (spustoszenie): dzien")
    ai_free = 0
    for d in live:
        x = dev.get(d, "")
        t = num(r"lup z niczego (\d+) zl \(gracz", x, int, 0) or 0
        pl = num(r"lup z niczego \d+ zl \(gracz (\d+)\)", x, int, 0) or 0
        ai_free += t - pl
    rep.add("E7/R1 T1b: lup z niczego AI w rabunkach pod spustoszeniem (Ludzie (spustoszenie), suma okna)", f"{ai_free} zl (sesji oddanych grze {rel})",
            "0 zl (AI pod R1 nie dostaje zlota gry za hearth)", (ai_free == 0) if rel == 0 else None)
    # T2 - bilans towaru i spichlerza
    bad2 = []
    for d in live:
        g = num(r"towar \+ spalone - magazyn " + F_, rows[d], float)
        f = num(r"zjedzone - spichlerz " + F_, rows[d], float)
        if g is None or f is None or abs(g) >= 1 or abs(f) >= 0.5:
            bad2.append(f"d{d}: {g}/{f}")
    rep.add("E7/R1 T2: bilans towaru (towar + spalone - magazyn) i spichlerza (zjedzone - spichlerz) w kazdej dobie", f"dob niezgodnych {len(bad2)}" + (f" ({', '.join(bad2[:6])})" if bad2 else ""),
            "towar 0, spichlerz |x| < 0.5 (towar i jedzenie tylko z zasobow wsi)", len(bad2) == 0)
    # T3 - kontrola trafionych
    chk = [(d, num(r"\(kontrola " + F_ + r"; uderzen", rows[d], float)) for d in live]
    bad3 = [f"d{d}: {x}" for d, x in chk if x is None or abs(x) > 0.01]
    rep.add("E7/R1 T3: trafieni = zabici + las + jency + uchodzcy (kontrola) w kazdej dobie", f"dob niezgodnych {len(bad3)}" + (f" ({', '.join(bad3[:6])})" if bad3 else ""), "|kontrola| <= 0.01", len(bad3) == 0)
    # T4 - mediana dob na osade lorda (lista z linii)
    vals = []
    for x in w:
        m = re.search(r"\(lordowie \d+: ([\d./]+)\)", x)
        if m:
            vals += [float(v) for v in m.group(1).split("/") if v]
    vals.sort()
    med = (vals[len(vals) // 2] if len(vals) % 2 else 0.5 * (vals[len(vals) // 2 - 1] + vals[len(vals) // 2])) if vals else None
    rep.add("E7/R1 T4: mediana dob na osade - lordowie (krok pelny, doby lupienia / osady kroku)", f"{med:.2f} d ({len(vals)} krokow)" if med is not None else "brak krokow lordow",
            "<= 5 dob (lord ze 112 ludzmi ok. 4.6)", (med <= 5.0) if len(vals) >= 10 else None)
    # T5 - wioski spalone w ksiedze
    book = by_day(lines, "Ksiega wiosek (E4/11): dzien")
    burnt = sum(num(r"\| spalone dzis (\d+)", book[d], int, 0) or 0 for d in win if d in book)
    # narzedzie progow zb58 (TRIAZ E7/R1 T5): spalona = puste osady >= 50% osad JEDNEJ wioski (ok. 16 osad po 250 ludzi -> 8 osad = 2000 ludzi); przy
    # tempie rabunku z biegu (najbardziej spustoszony okreg ok. 4.6 pustych osad w d120, takze we wzorcu) prog "> 0 w 120 dob" jest nieosiagalny w tym
    # oknie. Prog twardy "> 0" tylko przy oknie >= 240 dob; w krotszym - INFO z najwiekszym puste_r okregu (wioski-okregi.csv) i tempem 30 dob.
    if len(win) >= 240 or not book:
        rep.add("E7/R1 T5: wioski spalone w ksiedze (Ksiega wiosek (E4/11) spalone dzis, suma okna)", f"{burnt}", "> 0 przy oknie >= 240 dob (przed R1: 0)",
                (burnt > 0) if book else None)
    else:
        top = ""
        cp = session_file_find(kw["logp"], "wioski-okregi.csv") if kw.get("logp") else None
        if cp and os.path.exists(cp):
            try:
                emp = {}
                with open(cp, encoding="utf-8", errors="replace") as fh:
                    for r in csv.DictReader(fh, delimiter=";"):
                        rd = run_day(int(r["dzien"]) - 1, start)
                        if 1 <= rd <= until:
                            emp.setdefault(rd, {})[r["okreg"]] = float(r["puste_r"])
                if emp:
                    ld = max(emp)
                    nm = max(emp[ld], key=lambda k: emp[ld][k])
                    pd = max([d for d in emp if d <= ld - 30 and nm in emp[d]] or [min(d for d in emp if nm in emp[d])])
                    pace = (emp[ld][nm] - emp[pd][nm]) / float(max(1, ld - pd))
                    top = (f"; najbardziej spustoszony okreg {nm}: {emp[ld][nm]:.2f} pustych osad (d{ld}) wobec ok. 8 potrzebnych w jednej wiosce, "
                           f"tempo {pace:.3f} osady/d (d{pd}-d{ld})" + (f" - 8 osad ok. d{ld + (8.0 - emp[ld][nm]) / pace:.0f}" if pace > 0 and emp[ld][nm] < 8.0 else ""))
            except (KeyError, ValueError, OSError):
                top = "; wioski-okregi.csv nieczytelny"
        else:
            top = "; brak wioski-okregi.csv (najwieksze spustoszenie okregu nieznane)"
        rep.add("E7/R1 T5: wioski spalone w ksiedze (Ksiega wiosek (E4/11) spalone dzis, suma okna)", f"{burnt}" + top,
                "INFO w oknie < 240 dob (spalona = puste osady >= 50% osad jednej wioski, ok. 8 x 250 ludzi); > 0 wiazace przy oknie >= 240 dob", None)
    rep.add("E7/R1 T6: udzial przerwanych sesji", f"{intr} z {ses} ({100.0 * intr / ses:.0f}%)" if ses else "-", "INFO (przed R1: 233 z 308 rabunkow przerwanych)", None)
    # T7 - potkniecia
    stu = tot(r"\| potkniecia (\d+)\.")
    err = [x for x in lines if x.startswith("ERROR in DistrictRaid.")]
    rep.add("E7/R1 T7: potkniecia (suma okna) i linie ERROR in DistrictRaid.", f"potkniecia {stu}, linii ERROR {len(err)}" + (f" (pierwsza: {err[0][:120]})" if err else ""), "0", stu == 0 and not err)
    # T10 - jency z rabunkow R1, T11 - zabici w stanie rabunku = zabici R1
    cap = tot(r"\| jency z rabunkow R1 (\d+),")
    rep.add("E7/R1 T10: jency z rabunkow R1 do lochu najezdzcy (suma okna)", f"{cap} (sesji {ses})", "> 0 (najezdzcy z niewola - E4/9 na wspolnym stanie rabunku)", (cap > 0) if ses >= 20 else None)
    rd = tot(r"zabici w stanie rabunku \(RaidDead\) " + F_, float)
    r1d = tot(r"\(zabici R1 " + F_ + r"\)", float)
    rep.add("E7/R1 T11: zabici w stanie rabunku (RaidDead, Inni i jency) = zabici z uderzen R1 (suma okna)", f"{rd:.1f} / {r1d:.1f} (roznica {rd - r1d:+.1f}, sesji {ses})",
            "|roznica| <= liczba sesji", abs(rd - r1d) <= max(1, ses))
    # koszt
    cost = [num(r"\| czas " + F_ + r" ms \|", x, float) for x in w]
    cm = _mean([c for c in cost if c is not None])
    rep.add("E7/R1 R1-3: koszt prefiksu rabunku (srednio)", f"{cm:.1f} ms/dobe" if cm is not None else "brak", "< 50 ms/dobe", (cm < 50.0) if cm is not None else None)
    # INFO
    gold, take, tval = tot(r"zloto z kiesy wsi (\d+) zl"), tot(r"towar z magazynu (\d+) szt\."), tot(r"towar z magazynu \d+ szt\. \((\d+) zl\)")
    burn, bval, eat = tot(r"spalone w rabunku (\d+) szt\."), tot(r"spalone w rabunku \d+ szt\. \((\d+) zl\)"), tot(r"jedzenie ze spichlerza (\d+) szt\.")
    rep.add("E7/R1 R1-4: lup (suma okna)", f"zloto z kies wsi {gold} zl, towar {take} szt. ({tval} zl), spalone {burn} szt. ({bval} zl), zboze ze spichlerza {eat} szt.",
            "INFO (zloto gry z niczego przed R1 ok. 670 zl/d)", None)
    alert = num(r"\| czujnosc: wsi (\d+) \(", w[-1], int, 0) or 0
    held = tot(r"leczenie wstrzymane (\d+)\)")
    bo, uc = tot(r"\| okreg wypalony (\d+),"), tot(r"u przyciete do [\d.]+ (\d+),")
    rep.add("E7/R1 R1-5: czujnosc, okreg wypalony, u przyciete", f"czujnosc wsi (ostatnia doba) {alert}, leczenie wstrzymane (suma) {held}; okreg wypalony {bo}, u przyciete {uc} (sesji {ses})",
            "INFO (u przyciete czesto = okregi prawie wypalone - sprawdzic tempo wojny)", None)
    # T9 - zapis -> wczytanie
    pairs, mism, last = 0, [], None
    for x in lines:
        if x.startswith(P + "zapis - sesji"):
            last = (num(r"sesji (\d+)", x, int), num(r"czujnosc (\d+)", x, int))
        elif x.startswith(P + "wczytanie - sesji"):
            got = (num(r"sesji (\d+)", x, int), num(r"czujnosc (\d+)", x, int))
            if last is not None:
                pairs += 1
                if got != last:
                    mism.append(f"{got[0]}/{got[1]} wobec {last[0]}/{last[1]}")
    rep.add("E7/R1 T9: sesje i czujnosc zapis -> wczytanie", f"par {pairs}, niezgodnych {len(mism)}" + (f" ({', '.join(mism[:4])})" if mism else ""),
            "0 niezgodnych (bieg zapisu 9 dob)", (len(mism) == 0) if pairs else None)

def etap7_r2(rep, lines, start, win, until=120, **kw):
    """E7/R2 (236, PLAN 7.11 b, projekt etapu 7 v2 rozdz. 3 "E7/R2" Test): linia startowa "Okienko rabunku gracza (E7/R2): latki przy starcie gry" i linia doby
    "Okienko rabunku gracza (E7/R2): dzien N" (tylko w dobach z rabunkiem gracza; dzien ksiegi = doba gry - 1, jak linia R1). Autotest gra AI, wiec bez sesji
    gracza wiaza tylko R2-0 (latki) i R2-1 (bledy); okienko, "End the raid", "End Raiding", wczytanie w stanie decyzji - test Jeffa (lista RB ryzyko 7)."""
    P = "Okienko rabunku gracza (E7/R2): "
    starts = [x for x in lines if x.startswith(P + "latki przy starcie gry")]
    rows = {}
    for d, x in by_day(lines, P + "dzien").items():
        if 1 <= run_day(d, start) <= until:
            rows[d] = x
    if not starts and not rows:
        rep.add("E7/R2: linie Okienko rabunku gracza (E7/R2)", "brak w logu", "sa od wgrania E7/R2 (LogEnabled)", None)
        return
    if starts:
        a = starts[-1]
        rep.add("E7/R2 R2-0: latki okienka przy starcie gry", a[len(P):][:220], "GOTOWE, BRAK: - (tick menu raiding_village i End Raiding)", ("GOTOWE" in a) and ("BRAK: -" in a))
    else:
        rep.add("E7/R2 R2-0: latki okienka przy starcie gry", "brak linii startowej", "jest przy kazdym starcie gry", None)
    w = [rows[d] for d in sorted(rows)]

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    err = [x for x in lines if x.startswith("ERROR in DistrictRaid.R2")]
    fail = tot(r"okienko zawiodlo (\d+)")
    rep.add("E7/R2 R2-1: bledy okienka (linie ERROR in DistrictRaid.R2, okienko zawiodlo)", f"linii ERROR {len(err)}, okienko zawiodlo {fail}" + (f" (pierwsza: {err[0][:120]})" if err else ""),
            "0", not err and fail == 0)
    new, ended = tot(r"sesji gracza: nowych (\d+),"), tot(r", zakonczonych (\d+) \(spalone")
    won, called, broken = tot(r"\(spalone (\d+),"), tot(r"odwolane przy 0 osadach (\d+),"), tot(r"przerwane po >= 1 osadzie (\d+)\)")
    steps, settl = tot(r"\| krokow pelnych (\d+) \("), tot(r"\| krokow pelnych \d+ \(osad (\d+)\)")
    shown, asks, again, nonext = tot(r"\| okienek (\d+) z "), tot(r"\| okienek \d+ z (\d+) decyzji"), tot(r"\(ponownie (\d+),"), tot(r"bez nastepnej osady (\d+)\)")
    nxt, endp = tot(r"wybory: nastepna (\d+),"), tot(r"wybory: nastepna \d+, koniec (\d+);")
    em, em0, auto = tot(r"End Raiding po >= 1 osadzie (\d+),"), tot(r"przy 0 osadach (\d+);"), tot(r"koniec bez okienka \(klucz zdjety w decyzji\) (\d+),")
    off = [d for d in rows if "| okienko NIE" in rows[d]]
    if not rows or (new == 0 and ended == 0 and steps == 0):
        rep.add("E7/R2 R2-2: rabunki gracza w oknie", "0 sesji (autotest gra AI)", "INFO - test Jeffa: pasek 99% przy okienku, End the raid, End Raiding po 1 osadzie i przy 0, wczytanie w decyzji, armia, Escape", None)
        return
    rep.add("E7/R2 R2-2: rabunki gracza w oknie (suma)",
            f"sesji nowych {new}, zakonczonych {ended} (spalone {won}, odwolane przy 0 osadach {called}, przerwane po >= 1 osadzie {broken}); krokow pelnych {steps} (osad {settl})"
            + (f"; dob z okienkiem NIE: {len(off)}" if off else ""), "INFO", None)
    # R2-3: sesje gracza w linii R1 = zakonczone w linii R2 (te same zdarzenia konca rabunku)
    r1 = {}
    for d, x in by_day(lines, "Rabunek osada po osadzie (E7/R1): dzien").items():
        if 1 <= run_day(d, start) <= until:
            r1[d] = x
    r1p = sum(num(r"\(AI \d+, gracz (\d+)\)", x, int, 0) or 0 for x in r1.values())
    rep.add("E7/R2 R2-3: sesje gracza w linii R1 (gracz N) = zakonczone w linii R2 (suma okna)", f"{r1p} / {ended}", "rowne", r1p == ended)
    rep.add("E7/R2 R2-4: wybory z okienka <= okienka otwarte (suma okna)", f"nastepna {nxt} + koniec {endp} wobec okienek {shown} + ponownie {again} (decyzji {asks}, bez nastepnej osady {nonext})",
            "wybory <= okienka", (nxt + endp) <= (shown + again))
    rep.add("E7/R2 R2-5: End Raiding i koniec bez okienka (suma okna)", f"End Raiding po >= 1 osadzie {em} (rabunek spalony), przy 0 osadach {em0} (odwolany - gra); koniec bez okienka (klucz zdjety w decyzji) {auto}",
            "INFO", None)


def etap7_w2(rep, lines, start, win, until=120, **kw):
    """E7/W2 (233, PLAN 7.9 a, projekt etapu 7 v2 rozdz. 3 "E7/W2" Test): linia startowa "Dymek wioski (E7/W2): start" (OnSessionLaunched), linia doby
    "Dymek wioski (E7/W2): dzien N" (dzien = doba gry) i probka wiary raz na sesje "Dymek wioski (E7/W2): probka wiary" (pierwsza doba). Wiazace: T1, T2, T4;
    W2-0 linia doby; T3 (zdjecia dymka) poza narzedziem."""
    starts = [s for s in lines if s.startswith("Dymek wioski (E7/W2): start")]
    rows = {}
    for d, s in by_day(lines, "Dymek wioski (E7/W2): dzien").items():
        if 1 <= run_day(d, start) <= until:
            rows[d] = s
    samples = [s for s in lines if s.startswith("Dymek wioski (E7/W2): probka wiary")]
    if not starts and not rows:
        rep.add("E7/W2: linie Dymek wioski (E7/W2)", "brak w logu", "sa od wgrania E7/W2 (VillageTipLore, LogEnabled)", None)
        return
    if starts:
        s = starts[-1]
        body = s.split("| ", 1)[1] if "| " in s else s
        if "WYLACZONY" in s:
            rep.add("E7/W2 T1: linia startowa (ostatnia sesja)", body[:200], "klucz VillageTipLore wlaczony", False)
        else:
            m = re.search(r"lore (\d+)/(\d+) \(bramka ([0-9A-F]{8}) zgodna, odrzucone (\d+), bez lore (\d+)", s)
            reg = "dymek ArmMapVillageTooltip zarejestrowany" in s
            herb = num(r"herby z lore niewazne (\d+)", s, int)
            ok = bool(m) and m.group(1) == m.group(2) and int(m.group(4)) == 0 and reg and herb == 0
            rep.add("E7/W2 T1: lore i dymek (linia startowa, ostatnia sesja)", body[:260],
                    "lore N/N, bramka zgodna (5A8C2735), odrzucone 0, dymek zarejestrowany, herby z lore niewazne 0", ok)
            bk = re.search(r"BK: wiara (tak|nie), tytuly (tak|nie)", s)
            rep.add("E7/W2 W2-1b: odczyty BK (odbicie)", bk.group(0) if bk else "brak", "wiara tak, tytuly tak (BannerKings w zestawie)",
                    (bk.group(1) == "tak" and bk.group(2) == "tak") if bk else None)
    else:
        rep.add("E7/W2 T1: linia startowa", "brak", "jest przy starcie kazdej sesji (OnSessionLaunched)", None)
    days = sorted(rows)
    need = max(0, len(win) - 1)
    rep.add("E7/W2 W2-0: linia doby Dymek wioski (E7/W2)", f"{len(days)} dob (dob okna {len(win)})", f">= {need} (codziennie w oknie)",
            (len(days) >= need and need > 0) if win else None)
    if days:
        def tot(pat):
            return sum(num(pat, rows[x], int, 0) or 0 for x in days)

        def most(pat):
            return max([num(pat, rows[x], int, 0) or 0 for x in days] or [0])
        sb, sr = tot(r"budowa (\d+), odswiezanie"), tot(r"odswiezanie (\d+) \(sesja")
        fw, ft, fr = most(r"wiara (\d+), tytul"), most(r"tytul (\d+), wiersz"), most(r"wiersz (\d+) \(sesja\)")
        rep.add("E7/W2 T2: potkniecia dymka (suma okna) i lore/BK (najwiecej w sesji)", f"budowa {sb}, odswiezanie {sr}; wiara {fw}, tytul {ft}, wiersz {fr}", "0",
                sb + sr + fw + ft + fr == 0)
        tips, fb = tot(r"dymkow z herbem (\d+)"), tot(r"zapas bez herbu (\d+)")
        rep.add("E7/W2 W2-2b: dymki pokazane (suma okna)", f"z herbem {tips}, zapas bez herbu {fb}",
                "INFO (bez najechan 0; zapas > 0 = brak prefabu GUI\\Prefabs albo rejestracji)", None)
    if samples:
        s = samples[-1]
        a = num(r"najwiekszy udzial BK (\d+)/", s, int)
        b = num(r"najwiekszy udzial BK \d+/(\d+)", s, int)
        n = num(r"\(wiosek probki (\d+),", s, int)
        rep.add("E7/W2 T4: wiara w dymku = najwiekszy udzial BK (probka 20 wiosek, ostatnia sesja)", f"{a}/{b} wiosek z danymi BK (probki {n})",
                "wszystkie wioski probki z danymi BK, co najmniej 10", (a == b and b >= 10) if a is not None and b is not None else None)
        m = re.search(r"zdanie lore o swietym miejscu: (\d+)/(\d+) wiosek z lore \(okreg bez danych BK (\d+)\)", s)
        rep.add("E7/W2 W2-4b: zdanie lore o swietym miejscu (faith_bk = dominujaca wiara BK okregu, cala mapa)", m.group(0) if m else "brak", "INFO", None)
    else:
        rep.add("E7/W2 T4: probka wiary", "brak linii", "jest w pierwszej dobie sesji (VillageTipLore)", None)
    rep.add("E7/W2 T3: zdjecia dymka (Polnoc, Reach, Dorne) - herb, rycerz, Alt", "poza narzedziem", "tryb zdjec autotestu", None)


def etap7_w3(rep, lines, start, win, until=120, **kw):
    """E7/W3 (234, PLAN 7.9 b, projekt etapu 7 v2 rozdz. 3 "E7/W3" Test): linia startowa "Menu okregu (E7/W3): start" (pierwsza doba sesji - index pozycji
    po wszystkich modach) i linia doby "Menu okregu (E7/W3): dzien N" (tylko gdy okno otwarto albo bylo potkniecie). Wiazace: T1 (pozycja w obu menu),
    T3 (0 potkniec i 0 linii ERROR okna); T2 (zdjecie okna, herb w ramce 86 x 63 prefabu ROT) poza narzedziem."""
    starts = [s for s in lines if s.startswith("Menu okregu (E7/W3): start")]
    rows = {}
    for d, s in by_day(lines, "Menu okregu (E7/W3): dzien").items():
        if 1 <= run_day(d, start) <= until:
            rows[d] = s
    if not starts:
        rep.add("E7/W3 T1: linia startowa Menu okregu (E7/W3)", "brak w logu", "jest w pierwszej dobie kazdej sesji od wgrania E7/W3 (LogEnabled)", None)
    else:
        s = starts[-1]
        body = s.split("| ", 1)[1] if "| " in s else s
        if "WYLACZONY" in s or "NIEWPIETA" in s:
            rep.add("E7/W3 T1: pozycja w menu (ostatnia sesja)", body[:200], "klucz DistrictMenuEnabled wlaczony, pozycja wpieta", False)
        else:
            v = re.search(r"village index (\d+) z (\d+) \(przed: ([^,]*), po: ([^)]*)\)", s)
            lo = re.search(r"village_looted index (\d+) z (\d+) \(przed: ([^,]*), po: ([^)]*)\)", s)
            book = "ksiega wiosek czynna" in s
            rep.add("E7/W3 T1: \"Look over the district\" w menu village i village_looted (ostatnia sesja)", body[:260],
                    "pozycja w obu menu (bez BRAK), ksiega wiosek czynna", bool(v) and bool(lo) and book)
            nb = []
            if v:
                nb.append(f"village: przed {v.group(3)}, po {v.group(4)}")
            if lo:
                nb.append(f"village_looted: przed {lo.group(3)}, po {lo.group(4)}")
            rep.add("E7/W3 W3-1b: sasiedzi pozycji (BK i ROT dokladaja do village)", "; ".join(nb) or "brak",
                    "INFO (oczekiwane: przed arm_people_village / arm_people_village_looted)", None)
    days = sorted(rows)
    st = sum(num(r"potkniecia dzis (\d+)", rows[x], int, 0) or 0 for x in days)
    err = [s for s in lines if s.startswith("ERROR in DistrictMenu.") or s.startswith("ERROR in VillageBook.DistrictView")]
    rep.add("E7/W3 T3: potkniecia okna okregu (suma okna) i linie ERROR okna", f"potkniecia {st} (dob z uzyciem {len(days)}), linii ERROR {len(err)}", "0", st == 0 and not err)
    if days:
        def tot(pat):
            return sum(num(pat, rows[x], int, 0) or 0 for x in days)
        o, m = tot(r"okien (\d+)"), tot(r"Hear more (\d+)")
        hb, hl, hp, hn = tot(r"rod posiadacza tytulu BK (\d+)"), tot(r"rycerz z lore (\d+)"), tot(r"pan (\d+), bez"), tot(r"bez herbu (\d+)")
        rep.add("E7/W3 W3-3b: uzycie okna (suma okna)", f"okien {o}, Hear more {m}; herby: rod tytulu BK {hb}, rycerz z lore {hl}, pan {hp}, bez herbu {hn}",
                "INFO (autotest bez klikniec - 0; bez herbu > 0 tylko przy wsi bez pana)", None)
    rep.add("E7/W3 T2: zdjecie okna okregu (herb w ramce 86 x 63 prefabu ROT, dymek wiersza, Hear more)", "poza narzedziem", "tryb zdjec autotestu", None)


def etap7_w5(rep, lines, start, win, until=120, **kw):
    """E7/W5 (238, PLAN 7.9 c, projekt etapu 7 v2 rozdz. 3 "E7/W5"): linia startowa "Proporczyki (E7/W5): start" (pierwszy tick widoku wiosek na
    mapie - raz na mape / wczytanie) i linia stanu "Proporczyki (E7/W5): w kadrze ..." (co 2 minuty przy zmianie i na koniec mapy; liczniki od
    wczytania mapy). Widok mapy nie ma doby - progi z calego logu. Wiazace: T1, W5-2, W5-3; T2 (spadek klatek < 5%) w trybie zdjec poza narzedziem."""
    starts = [s for s in lines if s.startswith("Proporczyki (E7/W5): start")]
    rows = [s for s in lines if s.startswith("Proporczyki (E7/W5): w kadrze")]
    if not starts and not rows:
        rep.add("E7/W5: linie Proporczyki (E7/W5)", "brak w logu",
                "sa od wgrania E7/W5 przy czynnych wioskach na mapie (MapVillagesEnabled, VillagePennants, LogEnabled)", None)
        return
    if starts:
        s = starts[-1]
        body = s.split("| ", 1)[1] if "| " in s else s
        if "siatka BRAK" in s:
            rep.add("E7/W5 T1: siatka choragwi (ostatnia mapa)", body[:200], "campaign_flag (zapas map_banner)", False)
        else:
            rep.add("E7/W5 T1: siatka choragwi (ostatnia mapa)", body[:200], "campaign_flag z plotnem (ZAPAS map_banner - INFO)",
                    True if "siatka campaign_flag" in s else None)
    else:
        rep.add("E7/W5 T1: linia startowa", "brak", "jest przy pierwszym ticku widoku z wlaczonym kluczem VillagePennants", None)
    off = [s for s in lines if s.startswith("Proporczyki (E7/W5): wylaczone w MCM")]
    if off:
        rep.add("E7/W5: wylacznik VillagePennants w biegu", f"wylaczen {len(off)}", "INFO (proba wylacznika albo bisekcja)", None)
    if not rows:
        rep.add("E7/W5 W5-1: linia stanu", "brak", "co 2 minuty przy zmianie i na koniec mapy", None)
        return
    seen = max([num(r"\(najwiecej (\d+)\)", s, int, 0) or 0 for s in rows] or [0])
    rep.add("E7/W5 W5-1: proporczykow w kadrze naraz (najwiecej w biegu)", str(seen), "1-80 (0 = kamera nie zjechala ponizej 90 - INFO)",
            (1 <= seen <= 80) if seen > 0 else None)
    ms = max([num(r"budowa sr\. ([0-9.]+) ms/klatke", s, float, 0.0) or 0.0 for s in rows] or [0.0])
    bt = max([num(r"klatek z budowa (\d+)", s, int, 0) or 0 for s in rows] or [0])
    rep.add("E7/W5 W5-2: budowa proporczykow sr. ms na klatke z budowa (najgorsza linia)", f"{ms:.3f} ms (klatek z budowa najwiecej {bt})",
            "< 8 ms (budzet tworzenia obrazkow wiosek na tick)", ms < 8.0 if bt > 0 else None)
    st = max([num(r"potkniecia (\d+) \(wiosek bez", s, int, 0) or 0 for s in rows] or [0])
    fl = max([num(r"wiosek bez proporczyka (\d+)\)", s, int, 0) or 0 for s in rows] or [0])
    # PickPennantMesh (start mapy) i RemovePennants (wylacznik, koniec mapy - po linii stanu) tez: ich potkniecia nie trafiaja do linii z konca mapy
    err = [s for s in lines if s.startswith(("ERROR in MapVillagesView.Pennant", "ERROR in MapVillagesView.PickPennant", "ERROR in MapVillagesView.RemovePennants"))]
    rep.add("E7/W5 W5-3: potkniecia proporczykow (najwiecej w linii mapy) i linie ERROR", f"potkniecia {st} (wiosek bez proporczyka {fl}), linii ERROR {len(err)}",
            "0", st == 0 and not err)
    pm = max([num(r"przebudowy po misji (\d+)", s, int, 0) or 0 for s in rows] or [0])
    mi = max([num(r"\(misji (\d+)\)", s, int, 0) or 0 for s in rows] or [0])
    lc = max([num(r"zmiany herbu (\d+)", s, int, 0) or 0 for s in rows] or [0])
    rep.add("E7/W5 W5-4: przebudowy po misji i zmiany herbu (najwiecej w linii mapy)", f"po misji {pm} (misji {mi}), zmiany herbu {lc}",
            "INFO (po bitwie z proporczykami w poblizu > 0)", None)
    rep.add("E7/W5 T2: spadek klatek przy kamerze 30 / 60 / 90 i 0 / 40 / 80 proporczykach, plotno, puste flagi po bitwie", "poza narzedziem",
            "< 5% w trybie zdjec (inaczej VillagePennants domyslnie false)", None)


def etap7_w4(rep, lines, start, win, until=120, **kw):
    """E7/W4 (237, PLAN 7.10 b, projekt etapu 7 v2 rozdz. 3 "E7/W4"): linia startowa "Wioski - wyglad (E7/W4): start" (pierwszy tick widoku wiosek na
    mapie - raz na mape / wczytanie) i linia stanu "Wioski - wyglad (E7/W4): przebudowy obrazka ..." (co 2 minuty przy zmianie i na koniec mapy; liczniki
    od wczytania mapy). Widok mapy nie ma doby - progi z calego logu. Wiazace: T1 (kazda przebudowa obrazka ma swoja zmiane stanu, zadna wioska nie miga),
    W4-3 (napisy <= 30, przeliczenie pozycji), T4 (potkniecia 0). T2 (zdjecie spalonej wioski) i T3 (spadek klatek z napisami < 2%) - tryb zdjec, poza
    narzedziem; DLL zdjec (-p:W4Photo=true) zglasza sie w linii startowej."""
    starts = [s for s in lines if s.startswith("Wioski - wyglad (E7/W4): start")]
    rows = [s for s in lines if s.startswith("Wioski - wyglad (E7/W4): przebudowy obrazka")]
    if not starts and not rows:
        rep.add("E7/W4: linie Wioski - wyglad (E7/W4)", "brak w logu",
                "sa od wgrania E7/W4 przy czynnych wioskach na mapie (MapVillagesEnabled, LogEnabled)", None)
        return
    if starts:
        s = starts[-1]
        look, lbl, book = "wioski CZYNNY" in s, "spalonymi CZYNNE" in s, "ksiega wiosek czynna" in s
        rep.add("E7/W4 W4-0: klucze i ksiega wiosek (ostatnia mapa)",
                f"wyglad {'CZYNNY' if look else 'wylaczony'}, napisy {'CZYNNE' if lbl else 'wylaczone'}, ksiega {'czynna' if book else 'NIECZYNNA'}",
                "wyglad CZYNNY, napisy CZYNNE, ksiega czynna (klucz zdjety - INFO: proba wylacznika; ksiega nieczynna - NIE, bez niej nie ma spalonych)",
                True if (look and lbl and book) else (False if not book else None))
        lv = re.search(r"wiosek poziomu 2 w pliku (\d+), poziomu 3 (\d+) z (\d+)", s)
        if lv:
            rep.add("E7/W4: wioski, ktore moga zmalec (poziom 2 i 3 w pliku)", f"poziom 2: {lv.group(1)}, poziom 3: {lv.group(2)} z {lv.group(3)}",
                    "INFO (poziom 1 nie maleje - u tych wiosek zmienia sie tylko wyglad spalonej)", None)
        if "KOMPILACJA ZDJEC" in s:
            rep.add("E7/W4: DLL zdjec (W4_PHOTO)", "TAK - pierwsza wioska kazdego okregu pokazana jako spalona",
                    "tylko bieg zdjec; ten DLL NIE idzie do biegu A ani do Jeffa", None)
    else:
        rep.add("E7/W4 W4-0: linia startowa", "brak", "jest przy pierwszym ticku widoku wiosek na mapie", None)
    for key, what in (("wyglad malejacej i spalonej wioski wylaczony w MCM", "BurnedVillageLook"), ("napisy nad spalonymi wylaczone w MCM", "BurnedVillageLabels")):
        off = [s for s in lines if s.startswith("Wioski - wyglad (E7/W4): " + key)]
        if off:
            rep.add(f"E7/W4: wylacznik {what} w biegu", f"wylaczen {len(off)}", "INFO (proba wylacznika albo bisekcja)", None)
    if not rows:
        rep.add("E7/W4 T1: linia stanu", "brak", "co 2 minuty przy zmianie i na koniec mapy", None)
        return

    def g(pat, s):
        return num(pat, s, int, 0) or 0

    def parts_of(s):
        return (g(r"; pokazane (\d+)", s), g(r"schowane do nastepnego pokazania (\d+)", s), g(r"bez obrazka (\d+)", s),
                g(r"polaczone (\d+)", s), g(r"czeka (\d+)", s))

    bad, worst, top = [], 0, None
    for s in rows:
        n, m = g(r"przebudowy obrazka (\d+) \(zmiany stanu", s), g(r"zmiany stanu (\d+);", s)
        if n > m or sum(parts_of(s)) != m:
            bad.append((n, m))
        worst = max(worst, g(r"najwiecej przebudow jednej wioski (\d+)", s))
        if top is None or m >= top[1]:
            top = (n, m, s)
    n, m, s = top
    pp = parts_of(s)
    detail = (f"przebudowy {n}, zmiany stanu {m} (pokazane {pp[0]}, schowane {pp[1]}, bez obrazka {pp[2]}, polaczone {pp[3]}, czeka {pp[4]});"
              f" linii zlych {len(bad)} z {len(rows)}")
    rep.add("E7/W4 T1: przebudowy obrazka wobec zmian stanu ksiegi (linia z najwieksza liczba zmian)", detail,
            "przebudowy <= zmiany stanu i skladniki = zmiany stanu w KAZDEJ linii (0 przebudow bez zmiany); 0 zmian w biegu - INFO",
            (not bad) if m > 0 else (None if not bad else False))
    rep.add("E7/W4 T1b: najwiecej przebudow jednej wioski (obrazek nie miga)", str(worst), "<= 20 na mape (poziom w dol / w gore, spalona, odbudowa)",
            worst <= 20 if m > 0 else None)
    burned = max(g(r"spalonych w ksiedze (\d+)", x) for x in rows)
    dark = max(g(r"ciemny obrazek stoi (\d+)", x) for x in rows)
    smoke = max(g(r"dym nad spalonymi (\d+)", x) for x in rows)
    small = max(g(r"mniejszych (\d+)", x) for x in rows)
    built = max(g(r"ciemnych obrazkow od wczytania (\d+)", x) for x in rows)
    tint = max(g(r"encji przyciemnionych (\d+)", x) for x in rows)
    rep.add("E7/W4 W4-2: spalone w ksiedze widziane przez widok, ciemne obrazki, dym, mniejsze (najwiecej w linii mapy)",
            f"spalonych {burned}, ciemny obrazek {dark}, dym {smoke}, mniejszych {small}; ciemnych obrazkow od wczytania {built} (encji {tint})",
            "ciemny obrazek ma przyciemnione encje (ciemnych > 0 => encji > 0); spalonych 0 - INFO (T2 wtedy z DLL zdjec)",
            (tint > 0) if built > 0 else None)
    lmax = max(g(r"napisy w kadrze teraz \d+, maks\. (\d+)", x) for x in rows)
    fr = max(g(r"klatek z napisami (\d+)", x) for x in rows)
    ms = max([num(r"przeliczenie pozycji sr\. ([0-9.]+) ms/klatke", x, float, 0.0) or 0.0 for x in rows] or [0.0])
    rep.add("E7/W4 W4-3: napisy nad spalonymi w kadrze (najwiecej w biegu) i przeliczenie pozycji",
            f"maks. {lmax}, sr. {ms:.4f} ms/klatke (klatek z napisami najwiecej {fr})",
            "1-30 napisow i < 0.3 ms/klatke (2% klatki przy 60/s); 0 napisow = kamera nie zjechala ponizej 90 przy spalonej wiosce - INFO",
            (1 <= lmax <= 30 and ms < 0.3) if lmax > 0 else None)
    st = max(g(r"potkniecia: wyglad (\d+)", x) for x in rows)
    sl = max(g(r"potkniecia: wyglad \d+, napisy (\d+)", x) for x in rows)
    # recenzja E7/W4: przebudowa obrazka (TryCreate -> Create z barwa, bez detali, z nizszym poziomem), zdjecie starego obrazka (DropPicture) i dym nad
    # spalonymi (BurnedFx -> ApplyFx) licza potkniecia w STARYCH licznikach linii "Wioski:" (tworzenie, ogien, zdejmowanie) i pisza ERROR pod starymi
    # nazwami - bez nich T4 byl zielony takze wtedy, gdy spalona wioska nie stawala (3 potkniecia tworzenia = wioska znika z mapy do wczytania).
    # Liczniki wspolne z W2: kazde potkniecie w nich to blad obrazkow wiosek (bieg bazowy 11-12.10: wszedzie 0).
    wl = [x for x in lines if x.startswith("Wioski: ") and "potkniecia: tworzenie" in x]
    sc = max([g(r"potkniecia: tworzenie (\d+)", x) for x in wl] or [0])
    sf = max([g(r"potkniecia: tworzenie \d+, wzor \d+, ogien (\d+)", x) for x in wl] or [0])
    sr = max([g(r"zdejmowanie (\d+), tick", x) for x in wl] or [0])
    err = [x for x in lines if x.startswith(("ERROR in MapVillagesView.Look", "ERROR in MapVillagesView.Label", "ERROR in MapVillagesView.Create ",
                                             "ERROR in MapVillagesView.Remove ", "ERROR in MapVillagesView.ApplyFx", "ERROR in MapVillagesView.PollRaids"))]
    lost = [x for x in lines if x.startswith("Wioski - wyglad (E7/W4):") and ("BRAK prefabu" in x or "WYLACZONE do nastepnego wczytania" in x)]
    rep.add("E7/W4 T4: potkniecia wygladu i napisow (najwiecej w linii mapy), tworzenia / ognia / zdejmowania obrazkow (linia Wioski), linie ERROR,"
            " napisy zgaszone / brak prefabu",
            f"wyglad {st}, napisy {sl}, tworzenie {sc}, ogien {sf}, zdejmowanie {sr}, linii ERROR {len(err)}, napisy zgaszone albo brak prefabu {len(lost)}",
            "0 (brak prefabu = katalog GUI\\Prefabs nie wgrany razem z DLL; tworzenie / ogien / zdejmowanie - liczniki wspolne z W2, tedy ida przebudowa"
            " i dym W4)", st == 0 and sl == 0 and sc == 0 and sf == 0 and sr == 0 and not err and not lost)
    rep.add("E7/W4 T2 / T3: zdjecie spalonej wioski (ciemna, bez detali, dym, napis), spadek klatek z napisami", "poza narzedziem",
            "tryb zdjec: wyglad czytelny, klik i dymek mapy pod napisem dzialaja, spadek klatek < 2%", None)


def etap7_d0(rep, lines, start, win, until=120, **kw):
    """E7/D0 (239, PLAN 1.13 -> 7.5, projekt etapu 7 v2 rozdz. 3 "E7/D0"): proba drog P2 kluczem MapRoadsProbeEnabled (domyslnie false). Linia startu
    sesji "MapRoadsProbe: wylaczona" / "wlaczona"; przy wlaczonej (osobny krotki bieg zdjec): "MapRoadsProbe: plik ...", "MapRoadsProbe: postawione N z M ...",
    linia pomiaru "MapRoadsProbe: stempli N ...; klatki z drogami w kadrze: ..." (co minute przy zmianie i na koniec mapy). Widok mapy nie ma doby - progi
    z calego logu, tryb biegu wedlug OSTATNIEJ linii startu sesji. Wiazace: bieg A - D0-1 (wylaczona, nic nie postawione); bieg zdjec - D0-2 (CRC zgodne,
    zle wiersze 0, postawione N z N); oba - D0-3 (potkniecia i linie ERROR 0). Czas stawiania i klatki - INFO; zdjecia - poza narzedziem."""
    ses = [s for s in lines if s.startswith(("MapRoadsProbe: wylaczona", "MapRoadsProbe: wlaczona"))]
    files = [s for s in lines if s.startswith("MapRoadsProbe: plik")]
    built = [s for s in lines if s.startswith("MapRoadsProbe: postawione")]
    rows = [s for s in lines if s.startswith(("MapRoadsProbe: stempli", "MapRoadsProbe: koniec mapy"))]
    err = [s for s in lines if s.startswith("ERROR in MapRoadsProbe")]   # MapRoadsProbe.SessionStart, "MapRoadsProbe: komponent ...", MapRoadsProbeView.*
    if not ses and not files and not built and not rows and not err:
        rep.add("E7/D0: linie MapRoadsProbe", "brak w logu", "sa od wgrania E7/D0 (linia startu sesji, LogEnabled)", None)
        return
    on = bool(ses) and ses[-1].startswith("MapRoadsProbe: wlaczona")
    if not on:
        off_ok = bool(ses) and all(s.startswith("MapRoadsProbe: wylaczona") for s in ses)
        rep.add("E7/D0 D0-1: bieg A - proba drog wylaczona (klucz false)", f"linii 'wylaczona' {len(ses)} z {len(ses)} startow sesji, linii 'postawione' {len(built)}"
                if off_ok else f"startow sesji {len(ses)} (wlaczona w ktorejs), linii 'postawione' {len(built)}",
                "'wylaczona' przy kazdym starcie sesji, nic nie postawione", off_ok and not built)
    else:
        if files:
            f = files[-1]
            bad = num(r"zle wiersze (\d+)", f, int, -1)
            crc_bad = "NIEZGODNE" in f
            nst = num(r"stempli (\d+) w oknach", f, int, 0) or 0
            rep.add("E7/D0 D0-2a: plik proby (ostatnia mapa)", f"stempli {nst}, zle wiersze {bad}, CRC sceny {'NIEZGODNE' if crc_bad else 'zgodne / brak w pliku'}",
                    "stempli > 0, zle wiersze 0, CRC zgodne", nst > 0 and bad == 0 and not crc_bad)
        else:
            miss = [s for s in lines if s.startswith("MapRoadsProbe: brak pliku")]
            rep.add("E7/D0 D0-2a: plik proby", "brak pliku (ModuleData\\arm_map_roads_probe.tsv)" if miss else "brak linii 'plik' (widok mapy sie nie zarejestrowal?)",
                    "plik wgrany na bieg zdjec, linia 'MapRoadsProbe: plik ...'", False)
        if built:
            b = built[-1]
            m = re.search(r"postawione (\d+) z (\d+) \(prefab (\d+), kod (\d+), pominiete bez materialu (\d+), potkniecia (\d+)\)", b)
            if m:
                made, tot, pf, cd, skip, st = (int(x) for x in m.groups())
                rep.add("E7/D0 D0-2b: stemple postawione (ostatnia mapa)", f"{made} z {tot} (prefab {pf}, kod {cd}, bez materialu {skip}, potkniecia {st})",
                        "N z N, N > 0, bez materialu 0, potkniecia 0 (kod zamiast prefabu - INFO: prefab nie wgrany)", tot > 0 and made == tot and skip == 0 and st == 0)
            else:
                rep.add("E7/D0 D0-2b: linia 'postawione'", b[:160], "format linii E7/D0", False)
            ms = num(r"\) w ([0-9.]+) ms \(", b, float, 0.0) or 0.0
            mx = num(r"najdluzszy tick ([0-9.]+) ms", b, float, 0.0) or 0.0
            rep.add("E7/D0 D0-4: czas stawiania (ostatnia mapa)", f"{ms:.1f} ms w sumie, najdluzszy tick {mx:.1f} ms", "INFO (budzet ok. 8 ms na cwierc sekundy)", None)
        else:
            rep.add("E7/D0 D0-2b: linia 'postawione'", "brak", "jest po wejsciu na mape przy wlaczonym kluczu", False)
        if rows:
            r = rows[-1]
            fr = re.search(r"klatki z drogami w kadrze: (\d+)(?: \(srednio ([0-9.]+) ms, mediana (\d+), p95 (\d+))?", r)
            fb = re.search(r"; bez: (\d+)(?: \(srednio ([0-9.]+) ms, mediana (\d+), p95 (\d+))?", r)
            txt = (f"z drogami w kadrze {fr.group(1)} klatek" + (f" (sr. {fr.group(2)} ms, p95 {fr.group(4)})" if fr and fr.group(2) else "") if fr else "z drogami -")
            txt += (f"; bez {fb.group(1)}" + (f" (sr. {fb.group(2)} ms, p95 {fb.group(4)})" if fb and fb.group(2) else "") if fb else "; bez -")
            rep.add("E7/D0 D0-5: klatka z drogami w kadrze i bez (ostatnia linia pomiaru)", txt, "INFO (do zdjec i decyzji D1; bieg A bez proby)", None)
    st = 0
    for s in rows:
        m = re.search(r"potkniecia: stawianie (\d+), widocznosc (\d+), zdejmowanie (\d+), tick (\d+)", s)
        if m:
            st = max(st, sum(int(x) for x in m.groups()))
    rep.add("E7/D0 D0-3: potkniecia proby (najwiecej w linii mapy) i linie ERROR in MapRoadsProbe*", f"potkniecia {st}, linii ERROR {len(err)}", "0", st == 0 and not err)
    offm = [s for s in lines if s.startswith("MapRoadsProbe: wylaczone w MCM")]
    if offm:
        rep.add("E7/D0: wylacznik MapRoadsProbeEnabled w biegu", f"wylaczen {len(offm)}", "INFO (proba wylacznika)", None)
    if on:
        rep.add("E7/D0 D0-6: zdjecia obu okien (Fairmarket, Winterfell) z bliska i z daleka", "poza narzedziem", "dla Jeffa - pytanie 2 \"ile drog\"", None)

# ============================================================ ETAP 8 (E8/0, paczka 242): szkielet grupy --grupa etap8 i bloki etap8_t0, etap8_0
E8_PROF = "Profil doby (E8/0): dzien"


def etap8_t0(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/0 (242): T0 etapu 8 (projekt etapu 8 v2 rozdz. 4 pkt 1) - 0 ERROR w logu Armoury; w logu sesji CrashScribe 0 blokow "# ERROR IN A MOD" i 0 powtorek
    naszych modow (Armoury, RealisticCaptivity, GrandTourney); 0 wyjatkow BK CorrectPlayerEducation (blokow CS ze sladem tej metody - zamyka E8/M).
    Logi RealisticCaptivity i GrandTourney maja wlasne pliki - poza narzedziem (wiersz INFO)."""
    errs = [s for s in lines if s.startswith("ERROR in ")]
    sites = {}
    for s in errs:
        k = s[len("ERROR in "):].split(":", 1)[0]
        sites[k] = sites.get(k, 0) + 1
    top = ", ".join(f"{k} x{v}" for k, v in sorted(sites.items(), key=lambda kv: -kv[1])[:5])
    rep.add("E8 T0: ERROR w logu Armoury (cala sesja)", f"{len(errs)}" + (f" ({top})" if top else ""), "0", len(errs) == 0)
    if not logp:
        return
    path, how = crashscribe_session_of(logp, csp)
    if not path:
        rep.add("E8 T0: bloki ERROR IN A MOD naszych modow (CS)", how, "0 (bez logu sesji - INFO)", None)
        return
    for mod in ("Armoury", "RealisticCaptivity", "GrandTourney"):
        blk, pm, pu = crashscribe_mod_errors(path, mod)
        rep.add(f"E8 T0: bloki ERROR IN A MOD [{mod}] (CS)", f"bloki {len(blk)}, powtorki {len(pm)} | {os.path.basename(path)} ({how})", "0 i 0",
                len(blk) == 0 and len(pm) == 0)
    # narzedzie progow p2 (TRIAZ-2 a "E8 T0"): blok raportu CS konczy sie na linii "####" po tresci (trzecia linia krat) albo na pierwszej zwyklej linii logu
    # "[HH:MM:SS] ..." (blok bez stosu nie ma kraty zamykajacej). Dotad po "# ...ERROR" doklejane byly WSZYSTKIE nastepne linie az do kolejnego bloku, wiec
    # zwykle linie "Quiet (E8/M): znany wyjatek BK CorrectPlayerEducation ... odfiltrowany" i "Mends: edukacja BK gracza (E8/M) ..." liczyly sie jako
    # wyjatek w cudzym bloku (bieg 2: 2 przy 0 blokow ze sladem tej metody; filtr E8/M zlapal jedyny wyjatek).
    n_cpe, n_quiet, cur = 0, 0, None

    def cpe_close(blk):
        return 1 if blk and any("CorrectPlayerEducation" in x for x in blk) else 0
    with open(path, encoding="utf-8-sig", errors="replace") as f:
        for ln in f:
            if ln.startswith("# ") and "ERROR" in ln:
                n_cpe += cpe_close(cur)
                cur = [ln]
            elif cur is not None and (TS.match(ln) or (ln.startswith("####") and len(cur) >= 3)):
                n_cpe += cpe_close(cur)
                cur = None
            elif cur is not None:
                cur.append(ln)
            if cur is None and "Quiet (E8/M): znany wyjatek BK CorrectPlayerEducation" in ln:
                n_quiet += 1
    n_cpe += cpe_close(cur)
    rep.add("E8 T0: wyjatki BK CorrectPlayerEducation (bloki CS)", f"{n_cpe} (bloki ze sladem metody w tresci; odfiltrowane przez Quiet E8/M: {n_quiet} linii)",
            "0 (zamyka E8/M)", n_cpe == 0)
    rep.add("E8 T0: ERROR w logach RealisticCaptivity / GrandTourney", "poza narzedziem (wlasne pliki logu)", "0 - sprawdzic recznie", None)


def etap8_0(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/0 (242, projekt etapu 8 v2 rozdz. 3 "E8/0" Test): linia "Profil doby (E8/0)" (DayProfile.cs).
    E80-1 linia w kazdej dobie okna (bez pierwszej i ostatniej - linia doby N powstaje w takcie doby N+1); E80-2 pokrycie: "nasze razem (dolna granica)"
    >= 80% sumy z linii "Koszt 171-174 (doba)" tej doby ("nasze 171-174b" + "ceny sprzetu (PricePostfix)" - ceny zachodza czesciowo na pozycje sumy, wiec
    wzorzec jest raczej zawyzony) - srednio w oknie; E80-3 koszt samego profilu <= 15 ms/dobe srednio (TRIAZ-2: 126 tys. opakowan zdarzen); E80-4 INFO - takt doby (mediana, maks.) i udzial dob
    ze sprzataniem pamieci gen2 w szczytach taktu (10% najdluzszych) wobec wszystkich dob. INFO: nasze mody s/dobe, najdrozsze wywolania taktu, zapis logu,
    linia "Profil CS (E8/0)" z logu sesji CrashScribe (bledy pierwszej szansy, czas Blame.Culprits)."""
    prof = {d: s for d, s in by_day(lines, E8_PROF).items() if 1 <= run_day(d, start) <= until}
    if not prof:
        rep.add("E8/0: linia Profil doby (E8/0)", "brak w logu", "jest od wgrania E8/0 (Stage8ProfileLog)", None)
        return
    kos = by_day(lines, "Koszt 171-174 (doba): dzien")
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in prof]
    rep.add("E80-1: linia Profil doby w kazdej dobie okna",
            f"dob z linia {len(prof)}, brak w {len(miss)} z {len(inner)}" + (f" (doby kampanii {miss[:8]}" + (" ..." if len(miss) > 8 else "") + ")" if miss else ""),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (len(miss) == 0) if inner else None)
    days = sorted(prof)
    ours = {d: fnum(r"nasze razem \(dolna granica\) ([0-9.]+) ms", prof[d]) for d in days}
    ratios = []
    for d in days:
        k = kos.get(d)
        if k is None or ours[d] is None:
            continue
        a = fnum(r"nasze 171-174b ([0-9.]+) ms", k)
        b = fnum(r"ceny sprzetu \(PricePostfix\) ([0-9.]+) ms/", k)
        if a is None or b is None or a + b <= 0:
            continue
        ratios.append((ours[d] / (a + b), d))
    if ratios:
        m = sum(r for r, _ in ratios) / len(ratios)
        lo = min(ratios)
        rep.add("E80-2: pokrycie - nasze razem wobec Koszt 171-174 (nasze 171-174b + ceny)",
                f"srednio {100 * m:.0f}% ({len(ratios)} dob), najmniej {100 * lo[0]:.0f}% (d{run_day(lo[1], start)})", ">= 80% srednio", m >= 0.80)
    else:
        rep.add("E80-2: pokrycie - nasze razem wobec Koszt 171-174", "brak par linii Profil / Koszt tej samej doby", ">= 80%", None)
    cost = [(fnum(r"\| koszt profilu ([0-9.]+) ms", prof[d]), d) for d in days]
    cost = [(c, d) for c, d in cost if c is not None]
    if cost:
        m = sum(c for c, _ in cost) / len(cost)
        mx = max(cost)
        # narzedzie progow p2 (TRIAZ-2 E80-3): prog 1 ms zakladal ok. 13 tys. opakowan zdarzen na dobe; pomiar: 126 tys./d (8 sluchaczy wejscia do osady
        # x 9.3 tys. wejsc + 5 sluchaczy doby partii x 5.8 tys. partii) x 73.6 ns = 9.3 ms + linia 0.3 ms. Koszt staly w calym biegu (0.04% doby), wiec
        # prog <= 15 ms/dobe; klucz Stage8ProfileLog = false zdejmuje calosc po zakonczeniu optymalizacji.
        rep.add("E80-3: koszt samego profilu", f"srednio {m:.2f} ms/dobe, najwiecej {mx[0]:.2f} ms (d{run_day(mx[1], start)})",
                "<= 15 ms/dobe srednio (126 tys. opakowan zdarzen x 74 ns; szacunek projektu 1 ms liczyl 13 tys.)", m <= 15.0)
    else:
        rep.add("E80-3: koszt samego profilu", "brak liczby w linii", "<= 15 ms/dobe", None)
    tick = [(fnum(r"\| takt doby ([0-9.]+) ms", prof[d]), d) for d in days]
    tick = [(t, d) for t, d in tick if t is not None]
    if tick:
        ts = sorted(t for t, _ in tick)
        med = ts[len(ts) // 2]
        mx = max(tick)
        gc2 = {d: num(r"GC 0/1/2 \+\d+/\+\d+/\+(\d+)", prof[d]) for d in days}
        top = sorted(tick, reverse=True)[:max(1, len(tick) // 10)]
        share_top = sum(1 for _, d in top if (gc2.get(d) or 0) > 0) / len(top)
        share_all = sum(1 for _, d in tick if (gc2.get(d) or 0) > 0) / len(tick)
        rep.add("E80-4: takt doby (jedna klatka) i sprzatanie pamieci gen2 w szczytach",
                f"mediana {med:.0f} ms, maks. {mx[0]:.0f} ms (d{run_day(mx[1], start)}); doby z gen2 w 10% najdluzszych taktow {100 * share_top:.0f}%"
                f" wobec {100 * share_all:.0f}% wszystkich", "INFO (prog etapu: takt doby maks. <= 1.0 s po O1-O6)", None)
    vals = [v for v in ours.values() if v is not None]
    if vals:
        rep.add("E8/0: nasze mody razem (dolna granica, srednio)", f"{sum(vals) / len(vals) / 1000:.2f} s/dobe ({len(vals)} dob)", "INFO (do Jeffa: bylo X, jest Y)", None)
    acc = {}
    for d in days:
        mt = re.search(r"top: (.*?)\); inne sluchacze", prof[d])
        if not mt:
            continue
        for part in mt.group(1).split(", "):
            if " " in part:
                nm, v = part.rsplit(" ", 1)
                try:
                    acc[nm] = acc.get(nm, 0.0) + float(v)
                except ValueError:
                    pass
    if acc:
        nd = len(days)
        rep.add("E8/0: najdrozsze wywolania taktu doby (srednio ms/dobe)",
                ", ".join(f"{k} {v / nd:.1f}" for k, v in sorted(acc.items(), key=lambda kv: -kv[1])[:8]), "INFO", None)
    lw = [fnum(r"\| log zapis ([0-9.]+) ms", prof[d]) for d in days]
    lw = [x for x in lw if x is not None]
    if lw:
        rep.add("E8/0: zapis logu", f"srednio {sum(lw) / len(lw):.1f} ms/dobe", "INFO (prog etapu po O6: <= 20 ms/dobe)", None)
    if logp:
        path, how = crashscribe_session_of(logp, csp)
        fc, cu = [], []
        if path:
            for s in read(path):
                if s.startswith("Profil CS (E8/0): dzien"):
                    a = num(r"FirstChance (\d+)", s)
                    b = fnum(r"Blame\.Culprits ([0-9.]+) ms", s)
                    if a is not None:
                        fc.append(a)
                    if b is not None:
                        cu.append(b)
        if fc:
            val = f"FirstChance {sum(fc) / len(fc):.1f}, Culprits {(sum(cu) / len(cu)) if cu else 0:.1f} ms ({len(fc)} dob) | {os.path.basename(path)}"
        else:
            val = f"brak linii Profil CS (E8/0) | {os.path.basename(path)} ({how})" if path else how
        rep.add("E8/0: CrashScribe - bledy pierwszej szansy i czas Blame.Culprits (srednio na dobe)", val, "INFO", None)


# ============================================================ ETAP 8 (E8/P1, paczka 243): ksiega umiejetnosci - blok etap8_p1
E8_P1_UM = "Umiejetnosci (E8/P1): dzien"
E8_P1_TR = "XP wojska (E8/P1): dzien"
E8_P1_LV = "Poziomy lordow (E8/P1): dzien"
E8_P1_ST = "Ksiega umiejetnosci (E8/P1): start sesji"
E8_P1_ENT = re.compile(r"^(.+?) (-?\d+)/(\d+) \((\d+)%\)$")


def e8p1_sources(seg):
    """'marsz 123/45 (36%), jedzenie 10/2 (3%), inne 5/1 (1%)' -> {zrodlo: (xp, wywolan)}; wpis bez wzorca pomijany."""
    out = {}
    for part in (seg or "").split(", "):
        m = E8_P1_ENT.match(part.strip())
        if m:
            out[m.group(1)] = (int(m.group(2)), int(m.group(3)))
    return out


def etap8_p1(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/P1 (243, projekt etapu 8 v2 rozdz. 3 "E8/P1" Test): linie "Umiejetnosci (E8/P1)", "XP wojska (E8/P1)", "Poziomy lordow (E8/P1)" (SkillLedger.cs).
    P1-1 obie linie doby w kazdej dobie okna (bez pierwszej i ostatniej - linia doby N powstaje w takcie doby N+1, pierwszy takt sesji bez linii);
    P1-2 koszt ksiegi <= 40 ms/dobe srednio (TRIAZ-2: w tym znaczniki zrodel; stopery probkowane 1/64 + znaczniki + probki stosu + linie); P1-3 zrodlo "inne" <= 20% surowego XP lordow AI
    w oknie (pokrycie znacznikow; XP wprost z ChangeSkillLevel jest poza suma); P1-4 latki wpiete N/N przy kazdym starcie sesji, potkniecia 0 (R11).
    INFO: XP lordow i gracza wedlug zrodla (stan "przed" dla E8/X: jedzenie, marsz, marsz premia AI, strzal RBM), kto wola "inne" (probka stosu),
    XP wojska wedlug zrodla (zadane / przyjete), znaczniki zerwane, poziomy lordow - pierwsza i ostatnia linia okna."""
    um = {d: s for d, s in by_day(lines, E8_P1_UM).items() if 1 <= run_day(d, start) <= until}
    tr = {d: s for d, s in by_day(lines, E8_P1_TR).items() if 1 <= run_day(d, start) <= until}
    st = [s for s in lines if s.startswith(E8_P1_ST)]
    off = [s for s in lines if s.startswith("Ksiega umiejetnosci (E8/P1): WYLACZONA")]
    if not um and not st:
        rep.add("E8/P1: linia Umiejetnosci (E8/P1)", "brak w logu" + (f" (WYLACZONA x{len(off)})" if off else ""), "jest od wgrania E8/P1 (SkillLedgerLog)", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss_u = [run_day(d, start) for d in inner if d not in um]
    miss_t = [run_day(d, start) for d in inner if d not in tr]
    miss = sorted(set(miss_u + miss_t))
    rep.add("P1-1: linie Umiejetnosci i XP wojska w kazdej dobie okna",
            f"Umiejetnosci {len(um)} dob (brak {len(miss_u)}), XP wojska {len(tr)} dob (brak {len(miss_t)}) z {len(inner)}"
            + (f" (doby kampanii bez linii {miss[:8]}" + (" ..." if len(miss) > 8 else "") + ")" if miss else ""),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)
    days = sorted(um)
    cost = [(fnum(r"\| koszt ksiegi ([0-9.]+) ms", um[d]), d) for d in days]
    cost = [(c, d) for c, d in cost if c is not None]
    if cost:
        m = sum(c for c, _ in cost) / len(cost)
        mx = max(cost)
        # narzedzie progow p2 (TRIAZ-2 P1-2): ponad polowe kosztu daja znaczniki zrodel (ok. 83 tys./d x 215 ns = 18 ms), ktorych szacunek projektu
        # (30 ms) nie liczyl; koszt plaski w calym biegu (d30 33.4, d90 34.0 ms; nie rosnie z karawanami), sam pomiar - prog <= 40 ms/dobe.
        # Klucz SkillLedgerLog = false zdejmuje calosc po zebraniu pomiarow E8/P1.
        rep.add("P1-2: koszt ksiegi umiejetnosci", f"srednio {m:.1f} ms/dobe, najwiecej {mx[0]:.1f} ms (d{run_day(mx[1], start)}; {len(cost)} dob)",
                "<= 40 ms/dobe srednio (w tym znaczniki zrodel ok. 18 ms, poza szacunkiem projektu 30 ms)", m <= 40.0)
    else:
        rep.add("P1-2: koszt ksiegi umiejetnosci", "brak liczby w linii", "<= 40 ms/dobe", None)
    lords, player = {}, {}
    for d in days:
        ml = re.search(r"\| zrodla lordow AI: (.*?) \| zrodla gracza: (.*?) \| umiejetnosci lordow AI:", um[d])
        if not ml:
            continue
        for acc, seg in ((lords, ml.group(1)), (player, ml.group(2))):
            for k, (xp, n) in e8p1_sources(seg).items():
                a = acc.get(k, (0, 0))
                acc[k] = (a[0] + xp, a[1] + n)
    tot_l = sum(v[0] for v in lords.values())
    if tot_l > 0:
        oth = lords.get("inne", (0, 0))[0]
        rep.add("P1-3: zrodlo 'inne' w surowym XP lordow AI (pokrycie znacznikow)", f"{100.0 * oth / tot_l:.1f}% ({oth} z {tot_l}, {len(days)} dob)", "<= 20%", oth <= 0.20 * tot_l)
    else:
        rep.add("P1-3: zrodlo 'inne' w surowym XP lordow AI", "brak XP lordow w liniach okna", "<= 20%", None)
    wired = [(num(r"latki wpiete (\d+)/\d+", s), num(r"latki wpiete \d+/(\d+)", s)) for s in st]
    bad = [f"{a}/{b}" for a, b in wired if a is None or b is None or a != b]
    stum = max([num(r", potkniecia (\d+)", um[d], default=0) for d in days] + [0])
    stale = max([num(r", zerwane (\d+),", um[d], default=0) for d in days] + [0])
    nf = [s.split(" | nie znaleziono: ", 1)[1] for s in st if " | nie znaleziono: " in s]
    rep.add("P1-4: latki ksiegi wpiete przy kazdym starcie sesji, potkniecia 0",
            (f"starty {len(st)}, wpiete " + (", ".join(sorted(set(f"{a}/{b}" for a, b in wired))) if wired else "-") + f", potkniecia {stum}"
             + (f" | nie znaleziono: {nf[-1][:200]}" if nf else "") + (f" | WYLACZONA x{len(off)}" if off else "")),
            "N/N i 0", (len(st) > 0 and not bad and stum == 0))
    nd = max(1, len(days))

    def top(acc, n=8):
        tot = sum(v[0] for v in acc.values())
        if tot <= 0:
            return "-"
        return ", ".join(f"{k} {v[0] / nd:.0f} XP/d ({100.0 * v[0] / tot:.0f}%, {v[1] / nd:.0f} wyw./d)" for k, v in sorted(acc.items(), key=lambda kv: -kv[1][0])[:n])
    rep.add("E8/P1: surowe XP lordow AI wedlug zrodla (srednio na dobe)", top(lords), "INFO (stan 'przed' dla E8/X: jedzenie, marsz, marsz premia AI)", None)
    rep.add("E8/P1: surowe XP gracza wedlug zrodla (srednio na dobe)", top(player), "INFO (strzal RBM - X-1)", None)
    if days:
        mc = re.search(r"\| inne wedlug wolajacego \(sesja, probka stosu\): (.*?) \| znaczniki", um[days[-1]])
        rep.add("E8/P1: kto wola 'inne' (probka stosu, ostatnia doba okna)", (mc.group(1)[:420] if mc else "brak w linii"), "INFO (kolejne znaczniki przy P1-3 > 20%)", None)
        md = re.search(r"\| XP wprost poza suma [^:]*: (.*?) \| inne wedlug", um[days[-1]])
        rep.add("E8/P1: XP wprost poza suma (ostatnia doba okna) / znaczniki zerwane wyjatkiem w metodzie gry",
                (md.group(1) if md else "brak w linii") + f" / zerwane {stale}", "INFO", None)
    tdays = sorted(tr)
    if tdays:
        req = [num(r"\| dodane (-?\d+) \(przyjete", tr[d], default=0) for d in tdays]
        got = [num(r"\| dodane -?\d+ \(przyjete (-?\d+)\)", tr[d], default=0) for d in tdays]
        src = {}
        for d in tdays:
            mt = re.search(r"\| zrodla \(przyjete/wywolan\): (.*?) \| zdjete", tr[d])
            if not mt:
                continue
            for k, (xp, n) in e8p1_sources(mt.group(1)).items():
                a = src.get(k, (0, 0))
                src[k] = (a[0] + xp, a[1] + n)
        ts = sum(v[0] for v in src.values())
        rep.add("E8/P1: XP wojska (srednio na dobe)",
                (f"dodane {sum(req) / len(tdays):.0f}, przyjete {sum(got) / len(tdays):.0f} ({100.0 * sum(got) / sum(req):.0f}%)" if sum(req) > 0 else "dodane 0"),
                "INFO", None)
        rep.add("E8/P1: XP wojska wedlug zrodla (przyjete)",
                (", ".join(f"{k} {100.0 * v[0] / ts:.0f}%" for k, v in sorted(src.items(), key=lambda kv: -kv[1][0])[:6]) if ts > 0 else "-"), "INFO", None)
    lv = {d: s for d, s in by_day(lines, E8_P1_LV).items() if 0 <= run_day(d, start) <= until + 1}
    if lv:
        a, b = min(lv), max(lv)

        def lvl(s):
            out = ["suma " + str(num(r"suma poziomow mediana (\d+)", s, default=0))]
            for k in ("Scouting", "Steward", "Leadership", "Tactics", "OneHanded"):
                v = num(r"[ ,]" + k + r" (\d+)/\d+", s)
                if v is not None:
                    out.append(f"{k} {v}")
            return ", ".join(out)
        n_l = num(r"lordowie AI (\d+)", lv[b], default=0)
        rep.add("E8/P1: poziomy lordow AI - mediana, pierwsza i ostatnia linia okna",
                f"d{run_day(a, start)} [{lvl(lv[a])}] -> d{run_day(b, start)} [{lvl(lv[b])}] ({len(lv)} linii, lordow {n_l})", "INFO", None)


# ============================================================ ETAP 8 (E8/P2, paczka 244): pomiary sprzetu AI, lupu i korony - blok etap8_p2
E8_P2_WEAR = "Zuzycie AI - pomiary (E8/P2): dzien"
E8_P2_BUY = "ZakupyAI cena do wartosci (E8/P2): dzien"
E8_P2_LOOT = "Lup DTE - kopie (E8/P2): dzien"
E8_P2_MONO = "Monopole korony (E8/P2): dzien"
E8_P2_ROW = re.compile(r"^(.+?): szt\. (\d+), zaplacone (\d+) zl za wartosc (\d+) zl, cena/wartosc mediana ([0-9.]+), p90 ([0-9.]+), maks\. ([0-9.]+); "
                       r"ponad 1\.5x (\d+) szt\./(\d+) zl, ponad 2\.0x (\d+) szt\./(\d+) zl, ponad 3\.0x (\d+) szt\./(\d+) zl; dodatnie stany (\d+) szt\., doplata (\d+) zl$")


def e8p2_three(label, s):
    """'<label>lup obity a, zuzyte b, naprawione c' -> [a, b, c] albo None."""
    m = re.search(label + r"lup obity (\d+), zuzyte (\d+), naprawione (\d+)", s)
    return [int(m.group(1)), int(m.group(2)), int(m.group(3))] if m else None


def etap8_p2(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/P2 (244, projekt etapu 8 v2 rozdz. 3 "E8/P2" Test): cztery linie pomiarow - "Zuzycie AI - pomiary (E8/P2)" (AiWear.cs; etykieta = doba zdarzen,
    jak "Zuzycie AI"), "ZakupyAI cena do wartosci (E8/P2)" (Measure174b.cs), "Lup DTE - kopie (E8/P2)" (HorseFate.cs), "Monopole korony (E8/P2)"
    (KingdomTreasury.cs). P2-1 kazda z czterech linii w kazdej dobie okna (bez pierwszej i ostatniej); P2-2 zgodnosc: zalogi + pozostale partie = razem
    i razem = liczby linii "Zuzycie AI" tej doby (lup obity, zuzyte, naprawione; doba bez linii "Zuzycie AI" - razem 0); P2-3 INFO: kopie lupu u ocalalych
    pokonanych (szt./dobe, kto, jakie rodzaje), monopole - przyczyna 0 i dwie drogi (wzieto / nowy wzor wzialby). INFO dla E8/W, E8/Z, E8/L, E8/R: udzial
    zalog, powody stania napraw, "Amunicja AI: zeszloby", cena do wartosci wedlug kupujacego, dodatnie stany, "sufit 2.0 zablokowalby"."""
    sets = [("Zuzycie AI - pomiary", {d: s for d, s in by_day(lines, E8_P2_WEAR).items() if 1 <= run_day(d, start) <= until}),
            ("ZakupyAI cena do wartosci", {d: s for d, s in by_day(lines, E8_P2_BUY).items() if 1 <= run_day(d, start) <= until}),
            ("Lup DTE - kopie", {d: s for d, s in by_day(lines, E8_P2_LOOT).items() if 1 <= run_day(d, start) <= until}),
            ("Monopole korony", {d: s for d, s in by_day(lines, E8_P2_MONO).items() if 1 <= run_day(d, start) <= until})]
    wear, buy, loot, mono = sets[0][1], sets[1][1], sets[2][1], sets[3][1]
    if not (wear or buy or loot or mono):
        rep.add("E8/P2: linie pomiarow (E8/P2)", "brak w logu", "sa od wgrania E8/P2 (Stage8MeasureLog)", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    parts, bad = [], 0
    for name, dd in sets:
        miss = [run_day(d, start) for d in inner if d not in dd]
        bad += len(miss)
        parts.append(f"{name} {len(dd)} dob (brak {len(miss)}" + (f": doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") if miss else "") + ")")
    rep.add("P2-1: cztery linie pomiarow (E8/P2) w kazdej dobie okna", "; ".join(parts) + f" z {len(inner)}",
            "0 brakow (bez pierwszej i ostatniej doby okna)", (bad == 0) if inner else None)
    # P2-2: zalogi + pozostale partie = razem = linia "Zuzycie AI"
    zu = by_day(lines, "Zuzycie AI: dzien")
    wdays = sorted(wear)
    okd, badd, tg, tl = 0, [], [0, 0, 0], [0, 0, 0]
    for d in wdays:
        s = wear[d]
        g, l, t = e8p2_three(r"w tym zalogi: ", s), e8p2_three(r"pozostale partie: ", s), e8p2_three(r"razem \(linia Zuzycie AI\): ", s)
        if g is None or l is None or t is None:
            badd.append(run_day(d, start))
            continue
        ok = all(g[i] + l[i] == t[i] for i in range(3))
        z = zu.get(d)
        if z is None:
            ok = ok and sum(t) == 0   # linia "Zuzycie AI" powstaje tylko w dobie z lupem, zuzyciem, naprawa albo czekaniem na material
        else:
            ok = ok and t == [num(r"lup obity (\d+) szt\.", z, default=-1), num(r"zuzyte w bitwach (\d+)", z, default=-1), num(r"naprawione w miastach (\d+)", z, default=-1)]
        if ok:
            okd += 1
        else:
            badd.append(run_day(d, start))
        for i in range(3):
            tg[i] += g[i]
            tl[i] += l[i]
    if wdays:
        rep.add("P2-2: zalogi + pozostale partie = razem = linia Zuzycie AI (lup obity, zuzyte, naprawione)",
                f"dob zgodnych {okd} z {len(wdays)}" + (f" (niezgodne doby kampanii {badd[:8]}" + (" ..." if len(badd) > 8 else "") + ")" if badd else ""),
                "wszystkie doby zgodne", not badd)
        nd = max(1, len(wdays))

        def avg(pat, cast=float):
            v = [num(pat, wear[d], cast=cast, default=0) for d in wdays]
            return sum(v) / nd

        def share(i):
            tot = tg[i] + tl[i]
            return f"{tg[i] / nd:.0f}/d ({100.0 * tg[i] / tot:.0f}%)" if tot > 0 else "0"
        rep.add("E8/P2: zalogi w zuzyciu AI (srednio na dobe, udzial w calosci)", f"lup obity {share(0)}, zuzyte w bitwach {share(1)}, naprawione {share(2)} ({len(wdays)} dob)",
                "INFO (PLAN 8.7a: zalogi zuzywaja i naprawiaja - zuzyte i naprawione > 0)", None)
        st = [avg(p) for p in (r"naprawy: zlecen (\d+)", r"sztuk do naprawy (\d+)", r"stoja - sakiewka (\d+) partii", r"stoja - sakiewka \d+ partii / (\d+) szt",
                               r"reszta sakiewek tych partii (\d+) zl", r"godziny kowali (\d+) partii", r"godziny kowali \d+ partii / (\d+) szt", r"material (\d+) partii",
                               r"material \d+ partii / (\d+) szt", r"nie robota kowala (\d+) szt", r"inne (\d+) szt")]
        rep.add("E8/P2: naprawy AI - powody stania (srednio na dobe)",
                (f"zlecen {st[0]:.0f}, sztuk do naprawy {st[1]:.0f}; stoja: sakiewka {st[2]:.0f} partii / {st[3]:.0f} szt. (reszta sakiewek {st[4]:.0f} zl), godziny kowali "
                 f"{st[5]:.0f} partii / {st[6]:.0f} szt., material {st[7]:.0f} partii / {st[8]:.0f} szt., nie robota kowala {st[9]:.0f} szt., inne {st[10]:.0f} szt."),
                "INFO (stan 'przed' dla E8/W: kolejka od najtanszej, continue zamiast break)", None)
        am = [avg(p) for p in (r"Amunicja AI: zeszloby ([0-9.]+) szt", r"zeszloby [0-9.]+ szt\. \(strzaly ([0-9.]+)", r"belty ([0-9.]+), miotane", r"miotane ([0-9.]+); zwyciezcy",
                               r"zwyciezcy ([0-9.]+), pokonani", r"pokonani ([0-9.]+)\) z", r"\) z (\d+) w uzyciu")]
        # recenzja E8/P2: natezenie = srednia na partie po bitwie w oknie (wazona liczba partii doby); doba bez bitew ("-") nie wchodzi do sredniej
        iw = [(num(r"natezenie bitew srednio ([0-9.]+) \(", wear[d], cast=float), num(r"\((\d+) partii po bitwie\)", wear[d], default=0)) for d in wdays]
        iw = [(x, n) for x, n in iw if x is not None and n > 0]
        ipar = sum(n for x, n in iw)
        inten = f"{sum(x * n for x, n in iw) / ipar:.2f} ({ipar} partii po bitwie w {len(iw)} dobach)" if ipar > 0 else "- (brak bitew partii z zapisem)"
        rep.add("E8/P2: Amunicja AI - zeszloby (srednio na dobe)",
                (f"{am[0]:.1f} szt. (strzaly {am[1]:.1f}, belty {am[2]:.1f}, miotane {am[3]:.1f}; zwyciezcy {am[4]:.1f}, pokonani {am[5]:.1f}) z {am[6]:.0f} w uzyciu; "
                 f"natezenie bitew srednio na partie {inten}"),
                "INFO (E8/W amunicja AI W CIENIU; produkcja strzelarzy Z33 ok. 290-320 snopow strzal i 130-480 beltow na dobe)", None)
        stum = max([num(r"potkniecia \(sesja\) (\d+)", wear[d], default=0) for d in wdays] + [0])
        if stum:
            rep.add("E8/P2: potkniecia pomiaru AiWear", f"{stum}", "0", False)
    # ZakupyAI cena do wartosci
    bdays = sorted(buy)
    if bdays:
        rows = {}
        for d in bdays:
            for seg in buy[d].split(" | ")[1:]:
                m = E8_P2_ROW.match(seg.strip())
                if not m:
                    continue
                r = rows.setdefault(m.group(1), {"n": 0, "paid": 0, "worth": 0, "med": [], "p90": [], "mx": 0.0, "c2n": 0, "c2g": 0, "fn": 0, "fg": 0})
                r["n"] += int(m.group(2))
                r["paid"] += int(m.group(3))
                r["worth"] += int(m.group(4))
                r["med"].append(float(m.group(5)))
                r["p90"].append(float(m.group(6)))
                r["mx"] = max(r["mx"], float(m.group(7)))
                r["c2n"] += int(m.group(10))
                r["c2g"] += int(m.group(11))
                r["fn"] += int(m.group(14))
                r["fg"] += int(m.group(15))

        def mid(v):
            v = sorted(v)
            return v[(len(v) - 1) // 2] if v else 0.0
        txt = "; ".join(f"{k}: {r['n']} szt., zaplacone/wartosc {r['paid'] / r['worth']:.2f}, mediana dob {mid(r['med']):.2f}, p90 dob {mid(r['p90']):.2f}, maks. {r['mx']:.1f}, "
                        f"ponad 2.0x {r['c2n']} szt. ({100.0 * r['c2n'] / max(1, r['n']):.0f}%) / {r['c2g']} zl"
                        for k, r in sorted(rows.items(), key=lambda kv: -kv[1]["n"]) if r["worth"] > 0)
        rep.add("E8/P2: cena do wartosci sztuki ze stanem wedlug kupujacego (okno)", txt[:900] if txt else "brak zakupow w liniach", "INFO (E8/Z: wartosc AiGearMaxPriceFactor po tym pomiarze)", None)
        c15 = [sum(num(p, buy[d], default=0) for d in bdays) for p in (r"\(sufit 1\.5: (\d+) szt\.", r"\(sufit 1\.5: \d+ szt\. / (\d+) zl")]
        c20 = [sum(num(p, buy[d], default=0) for d in bdays) for p in (r"sufit 2\.0 zablokowalby (\d+) szt\.", r"sufit 2\.0 zablokowalby \d+ szt\. / (\d+) zl")]
        c30 = [sum(num(p, buy[d], default=0) for d in bdays) for p in (r"; sufit 3\.0: (\d+) szt\.", r"; sufit 3\.0: \d+ szt\. / (\d+) zl")]
        gaps = sum(r["n"] for k, r in rows.items() if "lepsze za swoje" not in k and not k.startswith("notable") and not k.startswith("ludzie gracza"))
        rep.add("E8/P2: sufit ceny zablokowalby (zakupy brakow AiGear lordow i zalog, okno)",
                f"2.0x: {c20[0]} szt. / {c20[1]} zl ({100.0 * c20[0] / max(1, gaps):.1f}% z {gaps} szt.); 1.5x: {c15[0]} szt. / {c15[1]} zl; 3.0x: {c30[0]} szt. / {c30[1]} zl ({len(bdays)} dob)",
                "INFO (E8/Z sufit W CIENIU - wlaczany w fazie poprawek, prog Z-2)", None)
        fn = sum(num(r"dodatnie stany kupione razem (\d+) szt\.", buy[d], default=0) for d in bdays)
        fg = sum(num(r"dodatnie stany kupione razem \d+ szt\., doplata (\d+) zl", buy[d], default=0) for d in bdays)
        rep.add("E8/P2: dodatnie stany kupione przez AI (okno)", f"{fn} szt., doplata {fg} zl ({fn / max(1, len(bdays)):.1f} szt./d, {fg / max(1, len(bdays)):.0f} zl/d)",
                "INFO (PLAN 8.8a: stan ginie po zakupie; po E8/Z prog Z-1 = 0)", None)
    # P2-3 INFO: kopie lupu i monopole
    ldays = sorted(loot)
    if ldays:
        nd = max(1, len(ldays))

        def lsum(pat):
            return sum(num(pat, loot[d], default=0) for d in ldays)
        kept, moved, gained = lsum(r"kopie u ocalalych pokonanych (\d+) szt\."), lsum(r"u rozbitych \(przeniesienie\) (\d+) szt\."), lsum(r"dopisane zwyciezcom \(bez koni\) (\d+) szt\.")
        kinds = ", ".join(k + " " + str(lsum(k + r" (\d+)[,)]")) for k in ("bron", "pociski", "zbroja", "tarcze", "uprzaz i inne"))
        wired = sorted(set((re.search(r"\| okno DTE (.*?)\.$", loot[d]) or [None, "?"])[1] for d in ldays))
        lp = [lsum(x) for x in (r"szt\. w (\d+) partiach \(zalogi", r"partiach \(zalogi (\d+)", r"partie lordow (\d+)", r", inne (\d+);", r"bitew z lupem DTE (\d+)")]
        rep.add("P2-3a: lup DTE - kopie u ocalalych pokonanych (bez koni)",
                (f"{kept / nd:.0f} szt./d (okno {kept} szt. w {lp[0]} partiach: zalogi {lp[1]}, partie lordow {lp[2]}, inne {lp[3]}; {kinds}) | u rozbitych (przeniesienie) {moved} szt. "
                 f"| dopisane zwyciezcom {gained} szt. w {lp[4]} bitwach | okno DTE: " + ", ".join(wired)),
                "INFO (stan 'przed' dla E8/L; po E8/L prog L-1: kopie u ocalalych = 0)", None)
    mdays = sorted(mono)
    if mdays:
        why = {}
        for d in mdays:
            m = re.search(r"\| przyczyna 0: (.*)\.$", mono[d])
            k = m.group(1) if m else "?"
            why[k] = why.get(k, 0) + 1

        def msum(pat):
            return sum(num(pat, mono[d], default=0) for d in mdays)
        last = mono[mdays[-1]]
        mp = [num(x, last, default=0) for x in (r"warsztaty w nich (\d+)", r", cudze (\d+),", r"z zyskiem \(ProfitMade > 0\) (\d+)", r"swiat: warsztatow z wlascicielem \d+, z zyskiem (\d+)",
                                                r"swiat: warsztatow z wlascicielem (\d+)", r"swiat: warsztatow z wlascicielem \d+, z zyskiem \d+, suma ProfitMade (\d+)")]
        took, would = msum(r"wzieto dzis (\d+) zl"), msum(r"wzialby (\d+) zl \| swiat")
        kings = max(num(r"z polityka StateMonopolies (\d+)", mono[x], default=0) for x in mdays)
        rep.add("P2-3b: monopole korony - przyczyna 0 i dwie drogi",
                ("przyczyna 0: " + ", ".join(f"{k} x{v}" for k, v in sorted(why.items(), key=lambda kv: -kv[1])) + f" | okno: wzieto {took} zl, nowy wzor wzialby {would} zl"
                 f" | krolow z polityka najwiecej {kings} | ostatnia doba: warsztaty w miastach rodu krola {mp[0]}, cudze {mp[1]}, z zyskiem {mp[2]}; swiat: z zyskiem {mp[3]} z {mp[4]},"
                 f" suma ProfitMade {mp[5]} zl"),
                "INFO (E8/R: nowy wzor 5% dziennej wyplaty; prog R-3)", None)


# ============================================================ ETAP 8 (E8/X, paczka 248): doswiadczenie za skutek - blok etap8_x
E8_X_LINE = "Doswiadczenie (E8/X): dzien"
E8_X_ST = "FairXp (E8/X): start sesji"
E8_X_ROWS = ("gracz", "lordowie AI 300+", "lordowie AI ponizej 300", "pozostale")


def e8x_seg(s, name):
    """Odcinek linii doby '| <name> [stan]: tresc' -> (stan, tresc); brak = (None, None)."""
    m = re.search(r"\| " + re.escape(name) + r" \[([^\]]*)\]: (.*?)(?= \| |$)", s)
    return (m.group(1), m.group(2)) if m else (None, None)


def etap8_x(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/X (248, projekt etapu 8 v2 rozdz. 3 "E8/X" Test, regula R10): linia doby "Doswiadczenie (E8/X)" (XpFair.cs) podaje dla kazdej sprawy
    "gra X / po Y" z tego samego biegu (gra = ile zaplacilaby regula gry / RBM / RBL dla tych samych wywolan).
    X-1 strzal poza bitwa (arena, turniej, cwiczenia): po = 0, a ksiega E8/P1 nie pokazuje u gracza wiecej XP "strzal RBM" niz zaplacono w bitwach
    (bieg bez misji - autotest - nie ma strzalow: INFO, sprawdza Jeff w grze, 8.16); X-2 Steward z jedzenia partii lordow AI 300+: sam pierwiastek/gra 0.4-0.6 w dobach bez zimy (TRIAZ-2; po/gra i rodzaje od pol dnia - INFO);
    X-3 Scouting z marszu partii lordow AI 300+: po/gra 0.4-0.6 (gra = marsz + premia tylko-AI); X-4 kazdy start sesji "latki wpiete 6/6"
    (strzal RBM, jedzenie, zwiad 2, RBL 2 - RBL potwierdzony w dekompilacji), wyplaty RBL 3/3, bez "nie znaleziono", potkniecia 0; do tego
    (recenzja E8/X) dowod, ze prefiksy BIEGNA, nie tylko sa wpiete: przy stanie [wl] w calym oknie (>= 3 doby) jedzenie ma > 0 partii, zwiad > 0 godzin,
    a ksiega E8/P1 nie pokazuje u lordow AI zrodla "marsz premia AI" (prefiks OnAIPartiesTravel je zdejmuje) - inaczej NIE z dopiskiem "prefiksy nie biegna".
    INFO: jedzenie i zwiad wedlug partii (gra -> po na dobe), rodzaje jedzenia liczone gra / po, zima, postoj, strzaly, paser, samonaprawa, RBL,
    koszt wlasny, ksiega E8/P1 w tym samym oknie (jedzenie, marsz, marsz premia AI - po zmianie)."""
    xl = {d: s for d, s in by_day(lines, E8_X_LINE).items() if 1 <= run_day(d, start) <= until}
    st = [s for s in lines if s.startswith(E8_X_ST)]
    if not xl and not st:
        rep.add("E8/X: linia Doswiadczenie (E8/X)", "brak w logu", "jest od wgrania E8/X (ShotXpFair, StewardFoodXpFair, ScoutXpFair, SmallXpFair, RblPaidXpFair)", None)
        return
    days = sorted(xl)
    nd = max(1, len(days))
    shot = [0, 0, 0, 0, 0, 0]                       # w bitwie: strzalow, gra, po; poza bitwa: strzalow, gra, po
    food = {r: [0, 0, 0] for r in E8_X_ROWS}        # partii, gra, po
    scout = {r: [0, 0, 0, 0] for r in E8_X_ROWS}    # godzin, gra (z premia AI), premia AI, po
    small = [0, 0, 0, 0, 0, 0, 0, 0]                # paser: n, gra, po; samonaprawa: n, gra, po; RBL: n, gra
    kinds_g, kinds_p, winter, idle, root = [], [], 0, 0, 0
    # narzedzie progow p2 (TRIAZ-2 c "X-2"): partie lordow 300+ osobno dla dob bez zimy ("zima 0 partii") i zimowych - doba kampanii -> (gra, po, pierwiastek)
    big_day, big_win = {}, {}
    states = {}
    for d in days:
        s = xl[d]
        for name in ("strzal", "jedzenie", "zwiad", "drobne", "RBL"):
            stt, seg = e8x_seg(s, name)
            if stt is not None:
                states.setdefault(name, set()).add(stt)
            if not seg:
                continue
            if name == "strzal":
                m = re.search(r"w bitwie (\d+) strzalow gra (-?\d+) / po (-?\d+), poza bitwa (\d+) strzalow gra (-?\d+) / po (-?\d+)", seg)
                if m:
                    for i in range(6):
                        shot[i] += int(m.group(i + 1))
            elif name == "jedzenie":
                for r in E8_X_ROWS:
                    m = re.search(r"(?:^|, )" + re.escape(r) + r" (\d+) partii gra (-?\d+) / po (-?\d+)", seg)
                    if m:
                        for i in range(3):
                            food[r][i] += int(m.group(i + 1))
                m = re.search(r"; rodzaje na partie gra ([0-9.]+) / po ([0-9.]+)", seg)
                if m:
                    kinds_g.append(float(m.group(1)))
                    kinds_p.append(float(m.group(2)))
                wn = num(r"; zima (\d+) partii", seg, default=0)
                rt = num(r"; lordowie AI 300\+ sam pierwiastek (-?\d+)", seg, default=0)
                winter += wn
                root += rt
                mb = re.search(r"(?:^|, )lordowie AI 300\+ (\d+) partii gra (-?\d+) / po (-?\d+)", seg)
                if mb:
                    (big_win if wn > 0 else big_day)[run_day(d, start)] = (int(mb.group(2)), int(mb.group(3)), rt)
            elif name == "zwiad":
                for r in E8_X_ROWS:
                    m = re.search(r"(?:^|, )" + re.escape(r) + r" (\d+) godzin gra (-?\d+) \(w tym premia AI (-?\d+)\) / po (-?\d+)", seg)
                    if m:
                        for i in range(4):
                            scout[r][i] += int(m.group(i + 1))
                idle += num(r"; stoi (\d+) godzin", seg, default=0)
            elif name == "drobne":
                m = re.search(r"paser (\d+) sprzedazy gra (-?\d+) / po (-?\d+), samonaprawa (\d+) sztuk gra (-?\d+) / po (-?\d+)", seg)
                if m:
                    for i in range(6):
                        small[i] += int(m.group(i + 1))
            else:
                m = re.search(r"(\d+) wyplat gra (-?\d+) / po", seg)
                if m:
                    small[6] += int(m.group(1))
                    small[7] += int(m.group(2))

    def state(name):
        v = sorted(states.get(name, ()))
        return "" if v in ([], ["wl"]) else " [" + ", ".join(v) + "]"

    # ksiega E8/P1 w tym samym oknie (po zmianie): zrodla lordow AI i gracza
    p1 = {d: s for d, s in by_day(lines, E8_P1_UM).items() if d in xl}
    p1_l, p1_g = {}, {}
    for d in sorted(p1):
        ml = re.search(r"\| zrodla lordow AI: (.*?) \| zrodla gracza: (.*?) \| umiejetnosci lordow AI:", p1[d])
        if not ml:
            continue
        for acc, seg in ((p1_l, ml.group(1)), (p1_g, ml.group(2))):
            for k, (xp, n) in e8p1_sources(seg).items():
                acc[k] = acc.get(k, 0) + xp
    # X-1
    shots = shot[0] + shot[3]
    p1_shot = p1_g.get("strzal RBM", 0)
    if shots == 0 and p1_shot == 0:
        rep.add("X-1: XP ze strzalu poza bitwa (arena, turniej, cwiczenia) = 0", "brak strzalow bohaterow w biegu (autotest bez misji)" + state("strzal"),
                "po 0 poza bitwa; ksiega P1 'strzal RBM' gracza <= zaplacone w bitwach (sprawdza Jeff w grze - 8.16)", None)
    else:
        rep.add("X-1: XP ze strzalu poza bitwa (arena, turniej, cwiczenia) = 0",
                (f"poza bitwa {shot[3]} strzalow gra {shot[4]} / po {shot[5]}; w bitwie {shot[0]} strzalow gra {shot[1]} / po {shot[2]}"
                 + (f" (po/gra {shot[2] / shot[1]:.2f})" if shot[1] > 0 else "") + f"; ksiega P1 gracz 'strzal RBM' {p1_shot}" + state("strzal")),
                "po 0 poza bitwa; ksiega P1 'strzal RBM' gracza <= zaplacone w bitwach", shot[5] == 0 and p1_shot <= shot[2] + len(days))
    # X-2, X-3
    big = "lordowie AI 300+"
    fg, fp = food[big][1], food[big][2]
    # narzedzie progow p2 (TRIAZ-2 c "X-2", "Poprawka ostateczna"): pasmo 0.4-0.6 policzono w projekcie dla SAMEGO pierwiastka (stosunek = 10 / pierwiastek
    # z ludzi: 300 ludzi 0.577, 350 ludzi 0.535 = "-47%" z RA8 1.3, 625 ludzi 0.40), a wiersz mierzyl zlozenie z druga regula ("rodzaj od pol dnia zapasu"),
    # ktorej wielkosc byla jawnie nieznana (audyt: "nie wiem, ile rodzajow jedzenia wioza lordowie AI"). Bieg 2: po/gra 0.315 = pierwiastek 0.503 x
    # rodzaje 0.626; sam pierwiastek w pasmie w kazdej ze 119 dob (0.472-0.537). Wiazace: sam pierwiastek / gra w dobach BEZ zimy (zima placi x1.25 i
    # podnosi prog pol dnia - osobny pomiar); po/gra i czynnik rodzajow zostaja w opisie. Stawka FoodBase 50 bez zmian (decyzja rozpoznania).
    dg, dp, dr = (sum(v[i] for v in big_day.values()) for i in range(3))
    rep.add("X-2: Steward z jedzenia partii lordow AI 300+, sam pierwiastek/gra (doby bez zimy)",
            (f"{dr / dg:.2f} ({len(big_day)} dob bez zimy; po/gra w tych dobach {dp / dg:.2f}, czynnik rodzajow od pol dnia x{dp / dr:.2f})" if (dg > 0 and dr > 0)
             else (f"brak dob bez zimy z liczba 'sam pierwiastek' ({len(big_day)} dob bez zimy, {len(big_win)} zimowych)" if fg > 0
                   else f"brak partii lordow 300+ z kwatermistrzem i ponad 3 rodzajami jedzenia ({len(days)} dob)"))
            + (f" | cale okno: po/gra {fp / fg:.2f} (gra {fg / nd:.0f} -> po {fp / nd:.0f} XP/dobe, {food[big][0] / nd:.1f} partii/dobe, {len(days)} dob"
               + (f"; sam pierwiastek x{root / fg:.2f}, rodzaje od pol dnia i zima x{fp / root:.2f}" if root > 0 else "") + ")" if fg > 0 else "") + state("jedzenie"),
            "0.4-0.6 dla samego pierwiastka poza zima (projekt: ok. -47% przy 350 ludziach); rodzaje od pol dnia i zima - INFO",
            (0.4 <= dr / dg <= 0.6) if (dg > 0 and dr > 0) else None)

    def kinds_part(sel):
        p, r = sum(v[1] for v in sel), sum(v[2] for v in sel)
        return f"{p / r:.2f}" if r > 0 else "-"
    if big_day or big_win:
        ks = sorted(big_day)
        half = len(ks) // 2
        rep.add("E8/X: rodzaje od pol dnia - po/pierwiastek partii lordow AI 300+ (pierwsza / druga polowa dob bez zimy; doby zimowe)",
                (f"{kinds_part([big_day[k] for k in ks[:half]])} / {kinds_part([big_day[k] for k in ks[half:]])} ({len(ks)} dob bez zimy)" if len(ks) >= 2 else f"dob bez zimy {len(ks)}")
                + f"; doby zimowe: {kinds_part(list(big_win.values()))} ({len(big_win)} dob)",
                "INFO (trend zapasow jedzenia lordow i skutek zimy - druga regula E8/X, zamierzona)", None)
    sg, sp = scout[big][1], scout[big][3]
    rep.add("X-3: Scouting z marszu partii lordow AI 300+, po/gra",
            (f"{sp / sg:.2f} (gra {sg / nd:.0f} w tym premia AI {scout[big][2] / nd:.0f} -> po {sp / nd:.0f} XP/dobe, {scout[big][0] / nd:.0f} godzin marszu/dobe, {len(days)} dob)"
             if sg > 0 else f"brak marszu partii lordow 300+ ({len(days)} dob)") + state("zwiad"),
            "0.4-0.6", (0.4 <= sp / sg <= 0.6) if sg > 0 else None)
    # X-4
    wired = [(num(r"\| latki wpiete (\d+)/\d+", s), num(r"\| latki wpiete \d+/(\d+)", s)) for s in st]
    rbl = [(num(r"wyplaty (\d+)/\d+", s), num(r"wyplaty \d+/(\d+)", s)) for s in st if "| RBL wpiete" in s]
    nf = [s.split(" | nie znaleziono: ", 1)[1] for s in st if " | nie znaleziono: " in s]
    offs = sorted(set(m for s in st for m in re.findall(r"WYLACZON[EY] \((\w+) off\)", s)))
    stum = max([num(r"\| potkniecia (\d+)", xl[d], default=0) for d in days] + [0])
    bad = [f"{a}/{b}" for a, b in wired if a is None or b is None or a != b or b != 6]
    bad_rbl = [f"{a}/{b}" for a, b in rbl if a != b]
    # recenzja E8/X: "wpiete" to nie dowod dzialania - bez tego bieg z martwymi prefiksami dawal X-1..X-3 INFO ("brak ...") i X-4 TAK
    dead = []
    if len(days) >= 3:
        if states.get("jedzenie") == {"wl"} and sum(food[r][0] for r in E8_X_ROWS) == 0:
            dead.append("jedzenie 0 partii w oknie")
        if states.get("zwiad") == {"wl"}:
            if sum(scout[r][0] for r in E8_X_ROWS) == 0:
                dead.append("zwiad 0 godzin marszu w oknie")
            if p1_l.get("marsz premia AI", 0) > 0:
                dead.append(f"ksiega P1: marsz premia AI lordow {p1_l['marsz premia AI']} XP (ma byc 0)")
    rep.add("X-4: latki E8/X wpiete przy kazdym starcie sesji, potkniecia 0",
            (f"starty {len(st)}, wpiete " + (", ".join(sorted(set(f"{a}/{b}" for a, b in wired))) if wired else "-")
             + ", wyplaty RBL " + (", ".join(sorted(set(f"{a}/{b}" for a, b in rbl))) if rbl else "-") + f", potkniecia {stum}"
             + (f" | wylaczone: {', '.join(offs)}" if offs else "") + (f" | nie znaleziono: {nf[-1][:220]}" if nf else "")
             + (f" | prefiksy nie biegna: {'; '.join(dead)}" if dead else "")),
            "6/6 (strzal RBM, jedzenie, zwiad 2, RBL 2), wyplaty RBL 3/3, potkniecia 0, prefiksy jedzenia i zwiadu wywolywane",
            (len(st) > 0 and not bad and not bad_rbl and not nf and stum == 0 and not dead))
    # INFO
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in xl]

    def rows(acc, unit, gi, pi, extra=None):
        out = []
        for r in E8_X_ROWS:
            a = acc[r]
            if a[0] == 0 and a[gi] == 0 and a[pi] == 0:
                continue
            out.append(f"{r}: {a[0] / nd:.1f} {unit}, gra {a[gi] / nd:.0f} -> po {a[pi] / nd:.0f}" + (f" (x{a[pi] / a[gi]:.2f})" if a[gi] > 0 else "")
                       + (extra(a) if extra else ""))
        return "; ".join(out) if out else "-"
    rep.add("E8/X: linia Doswiadczenie (E8/X) w dobach okna", f"{len(xl)} dob" + (f", brak w dobach kampanii {miss[:8]}" + (" ..." if len(miss) > 8 else "") if miss else ""),
            "INFO (pierwszy takt sesji bez linii)", None)
    rep.add("E8/X: Steward z jedzenia wedlug partii (XP na dobe)",
            rows(food, "partii/d", 1, 2) + (f" | rodzaje na partie gra {sum(kinds_g) / len(kinds_g):.1f} / po {sum(kinds_p) / len(kinds_p):.1f}" if kinds_g else "")
            + f" | zima (premia) {winter} partio-dob" + state("jedzenie"),
            "INFO (100 ludzi bez zmian; mala druzyna wiecej, duza mniej; rodzaj od pol dnia zapasu)", None)
    # narzedzie progow p2 (TRIAZ-2 X-3 pkt 3): stawka zwiadu z linii startu sesji ("zwiad A/B na godzine marszu"), nie z literalu w narzedziu
    mr = re.search(r"zwiad (\d+)/(\d+) na godzine marszu", st[-1]) if st else None
    rate = f"{mr.group(1)} / {mr.group(2)}" if mr else "stawka z linii startu sesji"
    rep.add("E8/X: Scouting z marszu wedlug partii (XP na dobe)",
            rows(scout, "godzin/d", 1, 3, lambda a: f", premia AI gry {a[2] / nd:.0f}") + f" | stoi (predkosc <= 1) {idle / nd:.0f} godzin/d" + state("zwiad"),
            f"INFO ({rate} na godzine marszu, karawany polowa, premia tylko-AI 0)", None)
    rep.add("E8/X: drobne w oknie - paser, samonaprawa, RBL (gra -> po)",
            f"paser {small[0]} sprzedazy {small[1]} -> {small[2]}; samonaprawa {small[3]} sztuk {small[4]} -> {small[5]}; RBL {small[6]} wyplat {small[7]} -> 0"
            + state("drobne") + state("RBL"), "INFO (autotest bez gracza przy kowadle i w rozmowach - sprawdza Jeff, 8.16)", None)
    cost = [fnum(r"\| koszt wlasny ~([0-9.]+) ms", xl[d]) for d in days]
    cost = [c for c in cost if c is not None]
    if cost:
        rep.add("E8/X: koszt wlasny prefiksow jedzenia i zwiadu", f"srednio {sum(cost) / len(cost):.1f} ms/dobe, najwiecej {max(cost):.1f} ms ({len(cost)} dob; bez nauki gry)",
                "INFO (projekt: < 5 ms/dobe)", None)
    if p1_l:
        npd = max(1, len(p1))
        rep.add("E8/X: ksiega E8/P1 w tym samym oknie - lordowie AI (surowe XP na dobe, po zmianie)",
                ", ".join(f"{k} {p1_l.get(k, 0) / npd:.0f}" for k in ("jedzenie", "marsz", "marsz premia AI", "strzal RBM")),
                "INFO (marsz premia AI = 0 przy ScoutXpFair; 'przed' w biegu bez E8/X)", None)


