def e8w_corr(xs, ys):
    """Wspolczynnik korelacji Pearsona albo None (za malo dob albo brak zmiennosci)."""
    n = len(xs)
    if n < 5:
        return None
    mx, my = sum(xs) / n, sum(ys) / n
    sx = sum((x - mx) ** 2 for x in xs)
    sy = sum((y - my) ** 2 for y in ys)
    if sx <= 0 or sy <= 0:
        return None
    return sum((x - mx) * (y - my) for x, y in zip(xs, ys)) / (sx * sy) ** 0.5


def e8w_arrows(lines):
    """Strzaly na polkach miast wedlug doby: linia "Rynek broni: na polkach ... Arrows N" (bez etykiety doby) stoi przed "Pieniadz swiata: dzien N" tej samej doby."""
    out, pend = {}, None
    for s in lines:
        if s.startswith("Rynek broni: na polkach"):
            pend = num(r"Arrows (\d+)", s)
        elif s.startswith("Pieniadz swiata: dzien") and pend is not None:
            d = num(r"dzien (\d+)", s)
            if d is not None:
                out[d] = pend
            pend = None
    return out


def etap8_w(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/W (249, projekt etapu 8 v2 rozdz. 3 "E8/W" Test, progi wzgledne): linia "Zuzycie AI (E8/W)" (AiWear.cs; etykieta = doba zdarzen, jak "Zuzycie AI").
    W-1 kolejka napraw: naprawione / (zuzyte w bitwach + lup obity) w ostatnich 30 dobach okna (doby 91-120) >= baza zb58 w tych samych dobach (TRIAZ-2; Z33 w tresci);
    W-2 linia "stare zuzycie N% zuzyloby" w tym samym biegu: stosunek nowe / stare INFO, naprawy na sztuke zuzyta w bitwie WEDLUG STAREJ REGULY wobec Z33
    - INFO (TRIAZ-2: licznik to glownie naprawy lupu, nie mierzy kolejki); W-3 INFO: zuzycie a straty (korelacja dob > 0); W-4 amunicja AI: W CIENIU - INFO, po wlaczeniu
    zeszlo > 0 i strzaly na polkach w ostatniej dobie okna >= 50% Z33 doby 120 (2 853); W-5 potkniecia 0, koszt dopasowania INFO (projekt: < 5 ms/d)."""
    wl = {d: s for d, s in by_day(lines, E8_W_LINE).items() if 1 <= run_day(d, start) <= until}
    if not wl:
        rep.add("E8/W: linia Zuzycie AI (E8/W)", "brak w logu", "jest od wgrania E8/W (AiWearEnabled)", None)
        return
    days = sorted(wl)
    nd = max(1, len(days))
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in wl]

    def state(tag):
        on = sum(1 for d in days if tag in wl[d])
        return on, len(days) - on
    z_on, z_off = state("| zuzycie [WL")
    q_on, q_off = state("| naprawy [WL")
    a_on, a_off = state("| amunicja AI [WL]")
    rep.add("W-0: linia Zuzycie AI (E8/W) w kazdej dobie okna; stan kluczy",
            (f"{len(days)} dob (brak {len(miss)}" + (f": doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") if miss else "") + f" z {len(inner)}); "
             f"AiWearByIntensity wl {z_on} / wyl {z_off} dob, AiMendQueueContinue wl {q_on} / wyl {q_off}, AiAmmoUse wl {a_on} / w cieniu {a_off}"),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def col(pat, cast=int):
        return {d: num(pat, wl[d], cast=cast, default=0) for d in days}
    sound, step, wreck, bottom = col(r"sprawne -> obite (\d+)"), col(r"obite o stopien nizej (\d+)"), col(r"w tym do wraku (\d+)"), col(r"trafienia w dno drabinki (\d+)")
    lost, parties = col(r"straty (\d+) ludzi"), col(r"partii po bitwie (\d+)")
    old_exp = {d: num(r"stare zuzycie [0-9.]+% zuzyloby ([0-9.]+) szt", wl[d], cast=float) for d in days}
    # okno progow: ostatnie 30 dob okna (doby kampanii until-29 .. until), te same doby w Z33
    lo = max(1, until - 29)
    zu = by_day(lines, "Zuzycie AI: dzien")
    tri = {}
    skip = {}   # recenzja E8/W: E6/N1 "pominiete (lup nienoszony)" z tej samej linii - kontekst do W-1 (Z33 jest sprzed N1)
    for d, s in zu.items():
        rd = run_day(d, start)
        if lo <= rd <= until:
            tri[rd] = (num(r"lup obity (\d+) szt\.", s, default=0), num(r"zuzyte w bitwach (\d+)", s, default=0), num(r"naprawione w miastach (\d+)", s, default=0))
            skip[rd] = num(r"pominiete \(lup nienoszony\) (\d+) szt", s)
    both = sorted(rd for rd in tri if rd in E8_W_Z33)
    if len(both) >= 10:
        a = [sum(tri[rd][i] for rd in both) for i in range(3)]
        z = [sum(E8_W_Z33[rd][i] for rd in both) for i in range(3)]
        r1, z1 = a[2] / max(1, a[0] + a[1]), z[2] / max(1, z[0] + z[1])
        sk = [skip[rd] for rd in both if skip.get(rd) is not None]
        # narzedzie progow p2 (TRIAZ-2 d): W-1 wobec bazy zb58 (E6/N1 jest, E8/W nie ma) w tych samych dobach - opis przy E8_W_ZB58; Z33 zostaje w tresci.
        # Do tego z linii E8/P2 tych samych dob: ile sztuk u kowala stoi przez sakiewke (to jedyne, co kolejka E8/W moze poprawic).
        bb = [rd for rd in both if rd in E8_W_ZB58]
        rb = b1 = None
        if len(bb) >= 10:
            ab = [sum(tri[rd][i] for rd in bb) for i in range(3)]
            bz = [sum(E8_W_ZB58[rd][i] for rd in bb) for i in range(3)]
            rb, b1 = ab[2] / max(1, ab[0] + ab[1]), bz[2] / max(1, bz[0] + bz[1])
        p2 = [s for d, s in by_day(lines, E8_P2_WEAR).items() if run_day(d, start) in both]
        todo = sum(num(r"sztuk do naprawy (\d+)", s, default=0) for s in p2)
        purse = sum(num(r"stoja - sakiewka \d+ partii / (\d+) szt", s, default=0) for s in p2)
        rep.add(f"W-1: kolejka napraw - naprawione / (zuzyte w bitwach + lup obity), doby {both[0]}-{both[-1]}",
                (f"{r1:.3f} ({a[2]} / ({a[1]} + {a[0]}), {len(both)} dob)"
                 + (f" wobec bazy zb58 (E6/N1 jest, E8/W nie ma) w dobach {bb[0]}-{bb[-1]} {b1:.3f} ({bz[2]} / ({bz[1]} + {bz[0]})) = x{rb / b1 if b1 > 0 else 0:.2f}" if b1 is not None
                    else " - baza zb58 tylko dla dob 91-120 (krotszy bieg - INFO)")
                 + f"; Z33 (sprzed E6/N1) w tych samych dobach {z1:.3f} ({z[2]} / ({z[1]} + {z[0]})) = x{r1 / z1 if z1 > 0 else 0:.2f}"
                 + (f"; E6/N1: w zleceniach pominieto {sum(sk)} szt. lupu nienoszonego ({len(sk)} dob, liczone przy kazdej wizycie) - tego lupu kowale juz nie naprawiaja, a jest w mianowniku" if sk else "")
                 + (f"; u kowala (E8/P2, {len(p2)} dob): sztuk do naprawy {todo}, z tego stoi przez sakiewke {purse} ({100.0 * purse / todo:.1f}%)" if todo > 0 else "")
                 + ("" if q_off == 0 else f"; klucz AiMendQueueContinue wylaczony w {q_off} dobach")),
                ">= baza zb58 w tych samych dobach (bieg z E6/N1 bez E8/W: 0.250 w dobach 91-120); stary prog 1.2 x Z33 mierzyl skutek E6/N1 (Z33 naprawial tez "
                "lup nienoszony), a sakiewka zatrzymuje < 1% sztuk - TRIAZ-2",
                (rb >= b1) if (q_off == 0 and b1) else None)
        wdays = [d for d in days if run_day(d, start) in both]
        olds = [old_exp[d] for d in wdays if old_exp[d] is not None]
        if wdays and len(olds) == len(wdays) and sum(olds) > 0:
            so = sum(olds)
            sn = sum(sound[d] + step[d] for d in wdays)
            ws = sum(sound[d] for d in wdays)
            rn = sum(tri[run_day(d, start)][2] for d in wdays)
            zn, zz = sum(E8_W_Z33[run_day(d, start)][2] for d in wdays), sum(E8_W_Z33[run_day(d, start)][1] for d in wdays)
            r2, z2 = rn / so, zn / max(1, zz)
            rep.add(f"W-2: stara regula w tym samym biegu - naprawy na sztuke zuzyta w bitwie wedlug starej reguly, doby {both[0]}-{both[-1]}",
                    (f"{r2:.2f} ({rn} naprawionych / {so:.0f} 'stare zuzycie zuzyloby') wobec Z33 {z2:.2f} ({zn} / {zz}) | nowa regula: {sn} trafien "
                     f"(sprawne -> obite {ws}, o stopien nizej {sn - ws}) = x{sn / so:.2f} starej; naprawy na sztuke 'sprawne -> obite' {rn / max(1, ws):.2f} ({len(wdays)} dob)"),
                    # narzedzie progow p2 (TRIAZ-2 d): licznik to glownie naprawy LUPU, a mianownik to tylko zuzycie w bitwach - gdy lupu obitego jest
                    # mniej (bieg 2: 95 768 wobec 118 498 w zb58 i 113 177 w Z33), stosunek spada bez zwiazku z kolejka (zb58 bez E8/W mial 2.27) - INFO
                    "INFO (Z33 w tych samych dobach i zb58 2.27: licznik to glownie naprawy lupu, ktorego jest mniej - nie mierzy kolejki E8/W; TRIAZ-2)",
                    None)
        else:
            rep.add("W-2: stara regula w tym samym biegu", "linia nie ma liczby 'stare zuzycie zuzyloby' (Stage8MeasureLog wylaczony?) albo brak bitew w oknie",
                    "INFO (liczba oczekiwana starej reguly jest liczona tylko przy Stage8MeasureLog)", None)
    else:
        rep.add("W-1 / W-2: kolejka napraw wobec Z33", f"za malo dob wspolnych z Z33 w dobach {lo}-{until} ({len(both)})", "co najmniej 10 dob z linia Zuzycie AI w ostatnich 30 dobach okna", None)
    # W-3 INFO: zuzycie a straty
    bd = [d for d in days if parties[d] > 0]
    c = e8w_corr([float(lost[d]) for d in bd], [float(sound[d] + step[d]) for d in bd])
    inten = [(num(r"natezenie srednio ([0-9.]+)", wl[d], cast=float), parties[d]) for d in bd]
    inten = [(x, n) for x, n in inten if x is not None and n > 0]
    ip = sum(n for x, n in inten)
    rep.add("W-3: zuzycie w bitwach a straty partii (korelacja dob)",
            (("brak dob z bitwami" if c is None else f"r = {c:.2f} ({len(bd)} dob z bitwami)") + f"; srednio na dobe: partii po bitwie {sum(parties.values()) / nd:.0f}, straty "
             f"{sum(lost.values()) / nd:.0f} ludzi, trafien {sum(sound[d] + step[d] for d in days) / nd:.0f}; natezenie srednio na partie "
             + (f"{sum(x * n for x, n in inten) / ip:.2f}" if ip > 0 else "-")),
            "INFO (korelacja > 0: wiecej strat = wiecej zuzycia)", None)
    # W-4: amunicja AI
    gone = col(r"amunicja AI \[[^\]]*\]: zeszlo (\d+) szt")
    arrows = e8w_arrows(lines)
    last_arrow = None
    for d in reversed(win):
        if d in arrows:
            last_arrow = (run_day(d, start), arrows[d])
            break
    atxt = f"strzaly na polkach doba {last_arrow[0]}: {last_arrow[1]} (Z33 doba 120: {E8_W_Z33_ARROWS_D120})" if last_arrow else "brak linii Rynek broni"
    if a_on == 0:
        rep.add("W-4: amunicja AI (W CIENIU)", f"klucz AiAmmoUse wylaczony - zeszlo {sum(gone.values())} szt.; 'zeszloby' w wierszu E8/P2; {atxt}",
                "INFO (wlaczenie w fazie poprawek; wtedy: zeszlo > 0 i strzaly na polkach >= 50% Z33)", None)
    else:
        tot = sum(gone.values())
        kinds = [sum(col(p).values()) for p in (r"zeszlo \d+ szt\. \(strzaly (\d+)", r"belty (\d+), miotane \d+\) w \d+ partiach \| wrakow", r"miotane (\d+)\) w \d+ partiach \| wrakow")]
        ok = tot > 0 and last_arrow is not None and last_arrow[1] >= 0.5 * E8_W_Z33_ARROWS_D120
        rep.add("W-4: amunicja AI wlaczona - kolczany zuzyte i strzaly na polkach",
                f"zeszlo {tot} szt. w oknie ({tot / nd:.0f}/d: strzaly {kinds[0]}, belty {kinds[1]}, miotane {kinds[2]}; wlaczone {a_on} z {len(days)} dob); {atxt}",
                "zeszlo > 0 i strzaly na polkach w ostatniej dobie okna >= 50% Z33 doby 120 (1 427)", ok)
    # W-5: potkniecia i koszt
    stum = max([num(r"potkniecia \(sesja\) (\d+)", wl[d], default=0) for d in days] + [0])
    fb = sum(col(r"partie na starej regule po potknieciu (\d+)").values())
    cost = col(r"koszt dopasowania ([0-9.]+) ms", cast=float)
    cmax = max(cost.values()) if cost else 0.0
    rep.add("W-5: potkniecia E8/W i koszt dopasowania 'co nosza ludzie' po bitwie",
            f"potkniecia (sesja) {stum}, partie na starej regule po potknieciu {fb}; koszt srednio {sum(cost.values()) / nd:.1f} ms/d, najwiecej {cmax:.1f} ms",
            "potkniecia 0 (koszt - INFO; projekt: < 5 ms/d)", stum == 0 and fb == 0)
    # INFO: kolejka, zakupy, wraki
    pp, pn, ap = col(r"partie z brakiem w sakiewce (\d+)"), col(r"sztuki czekajace na sakiewke (\d+)"), col(r"naprawione po pierwszej sztuce bez pieniedzy (\d+) szt")
    bn, bg, bk = col(r"zaplat z rezerwa (\d+)"), col(r"kiesa pana zamiast rezerwy napraw zaplacila(?:by)? (\d+) zl"), col(r"zl w (\d+) zaplatach")
    wr = col(r"wrakow w ksiedze (\d+)")
    rep.add("E8/W: kolejka napraw i zakupy brakow (srednio na dobe)",
            (f"partie z brakiem w sakiewce {sum(pp.values()) / nd:.1f}, sztuki czekajace na sakiewke {sum(pn.values()) / nd:.0f}, naprawione po pierwszej sztuce bez pieniedzy "
             f"{sum(ap.values()) / nd:.1f} szt. (stara petla stanelaby) | zakupy brakow: zaplat z rezerwa {sum(bn.values()) / nd:.1f}, kiesa pana zamiast rezerwy napraw "
             f"{sum(bg.values()) / nd:.0f} zl/d w {sum(bk.values()) / nd:.1f} zaplatach (okno {sum(bg.values())} zl)"),
            "INFO (lordowie placa wiecej - zamierzone; granica: wspolny prog rodow na minusie, projekt rozdz. 4 pkt 5)", None)
    rep.add("E8/W: obite schodza o stopien - wraki",
            (f"o stopien nizej {sum(step.values()) / nd:.0f}/d, w tym do wraku {sum(wreck.values()) / nd:.1f}/d (okno {sum(wreck.values())}), trafienia w dno drabinki "
             f"{sum(bottom.values()) / nd:.1f}/d; wrakow w ksiedze: pierwsza doba {wr[days[0]]}, ostatnia {wr[days[-1]]}"),
            "INFO (wraku kowale nie naprawiaja, a AI go nie wymienia - do decyzji po liczbach)", None)

# ============================================================ ETAP 8 (E8/A, paczka 250): misja gracza - odzysk wedlug strony, arena nie obija, lup z wlasnych zabojstw
E8_A_ST_AMMO = "Misja gracza (E8/A): start - odzysk amunicji wedlug strony agenta"
E8_A_ST_LOOT = "Misja gracza (E8/A): start - lup z wlasnych zabojstw w calosci"
E8_A_AMMO = "AmmoRecovery: po bitwie - strona gracza odzysk"
E8_A_AMMO_OLD = "AmmoRecovery: po bitwie kolczanow/stosow wrocilo"
E8_A_SKIP = "Zuzycie (E8/A): misja poza bitwa"
E8_A_ZERO = "Zuzycie (E8/A): poczatek bitwy - ksiega ciosow wyzerowana"
E8_A_LOST = "Zuzycie (E8/A): bitwa przegrana albo opuszczona"
E8_A_LOOT = "BattlefieldLaw (E8/A): lup cialo po ciele"


def e8a_pts(pat, s):
    """Punkty ksiegi ciosow z linii (ulamek z kropka albo przecinkiem - zalezy od ustawien systemu)."""
    m = re.search(pat, s)
    if not m:
        return 0.0
    try:
        return float(m.group(1).replace(",", "."))
    except ValueError:
        return 0.0


def etap8_a(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/A (250, projekt etapu 8 v2 rozdz. 3 "E8/A" Test; odpowiedz Jeffa 12.10 nr 1). Autotest nie gra misji, wiec progiem jest tylko A-1; reszta
    to wiersze dla biegu z gra Jeffa (8.16 punkty 9-10) - w biegu bez bitew z misja sa INFO "brak".
    A-1 dwie linie startu "Misja gracza (E8/A)": latki wpiete 1/1 (DTE Global.ProcessAgentEquipment - biezacy agent) i 2/2 (DTE OnAgentRemoved - zabojca,
    PartyBattleRecord.AddLootedItem - sztuka), bez "nie znaleziono";
    A-2 linia "AmmoRecovery: po bitwie - strona gracza odzysk X z N, przeciwnik Y z M, bez rozstrzygniecia Z z K": trzy pozycje sumuja sie do linii
    "kolczanow/stosow wrocilo / przepadlo" tej samej bitwy, latka wpieta, potkniecia 0 (udzialy wedlug stron - INFO: strona, ktora oddala pole,
    traci wszystko, co wystrzelila, ale niewystrzelona czesc zostaje - kolczan wraca z szansa "1 - wystrzelona czesc", wiec jej udzial jest
    NIZSZY niz strony zwycieskiej, nie zerowy);
    A-3 INFO: "Zuzycie (E8/A)" - misje poza bitwa (ciosy i strzaly pominiete), ksiega wyzerowana na poczatku bitwy, po bitwie przegranej;
    A-4 "BattlefieldLaw (E8/A): lup cialo po ciele": sztuki z wlasnych zabojstw w calosci, zolnierskie x trzecia, dzialka wobec sredniej z puli;
    potkniecia 0, a przy >= 5 wrogach powalonych przez gracza i towarzyszy sztuk z ich cial > 0 (inaczej DTE nie dopisuje lupu zabojcy-gracza).
    Recenzja E8/A: wygrana bitwa z misja i dzialka DTE daje zawsze linie "BattlefieldLaw: N szt. (...) z magazynu wojska czeka na ekran lupow";
    przy wlaczonym kluczu i dzialajacych znacznikach ma ona "cialo po ciele". Sama stara linia przy [wl] i ani jednej linii E8/A = znaczniki
    zabojcy nie doszly (prefiks AddLootedItem nie biegnie - regula po cichu nie dziala) -> NIE; wyjatek opisany w wierszu: bitwa morska
    (lup z losowania DTE, bez zabojcy) albo klucz wylaczony w trakcie sesji."""
    st_a = [s for s in lines if s.startswith(E8_A_ST_AMMO)]
    st_l = [s for s in lines if s.startswith(E8_A_ST_LOOT)]
    am = [s for s in lines if s.startswith(E8_A_AMMO)]
    am_old = [s for s in lines if s.startswith(E8_A_AMMO_OLD)]
    skip = [s for s in lines if s.startswith(E8_A_SKIP)]
    zero = [s for s in lines if s.startswith(E8_A_ZERO)]
    lost = [s for s in lines if s.startswith(E8_A_LOST)]
    loot = [s for s in lines if s.startswith(E8_A_LOOT)]
    if not (st_a or st_l or am or skip or zero or lost or loot):
        rep.add("E8/A: linie Misja gracza (E8/A)", "brak w logu", "sa od wgrania E8/A (AmmoRecoveryBySide, ArenaNoWear, OwnKillsLootWhole)", None)
        return

    def states(rows, name):
        v = sorted(set(m for s in rows for m in re.findall(re.escape(name) + r" \[(\w+)\]", s)))
        return "/".join(v) if v else "-"
    # A-1
    wa = [(num(r"latki wpiete (\d+)/\d+", s), num(r"latki wpiete \d+/(\d+)", s)) for s in st_a]
    wl = [(num(r"latki wpiete (\d+)/\d+", s), num(r"latki wpiete \d+/(\d+)", s)) for s in st_l]
    nf = [s.split(" | nie znaleziono: ", 1)[1] for s in st_a + st_l if " | nie znaleziono: " in s]
    bad = [f"{a}/{b}" for a, b in wa if a != 1 or b != 1] + [f"{a}/{b}" for a, b in wl if a != 2 or b != 2]
    rep.add("A-1: latki E8/A wpiete przy starcie (biezacy agent DTE 1/1, zabojca i sztuka lupu 2/2)",
            (f"linie startu: odzysk {len(st_a)} ({', '.join(sorted(set(f'{a}/{b}' for a, b in wa))) or '-'}), lup {len(st_l)} "
             f"({', '.join(sorted(set(f'{a}/{b}' for a, b in wl))) or '-'}) | klucze przy starcie: odzysk wedlug strony [{states(st_a, 'strony agenta')}], "
             f"arena nie obija [{states(st_a, 'arena nie obija')}], lup z wlasnych zabojstw [{states(st_l, 'w calosci')}]"
             + (f" | nie znaleziono: {nf[-1][:200]}" if nf else "")),
            "obie linie przy starcie, 1/1 i 2/2, bez 'nie znaleziono'", len(st_a) > 0 and len(st_l) > 0 and not bad and not nf)
    # A-2
    if not am:
        rep.add("A-2: odzysk amunicji wedlug stron po bitwie gracza", "brak bitew gracza z misja i strzelaniem w biegu" + (f" (stara linia {len(am_old)}x)" if am_old else ""),
                "trzy pozycje = linia 'wrocilo / przepadlo', latka wpieta, potkniecia 0 (sprawdza Jeff w grze - 8.16 pkt 9)", None if not am_old else False)
    else:
        tot = [0, 0, 0, 0, 0, 0]
        for s in am:
            m = re.search(r"strona gracza odzysk (\d+) z (\d+), przeciwnik (\d+) z (\d+), bez rozstrzygniecia \([^)]*\) (\d+) z (\d+)", s)
            if m:
                for i in range(6):
                    tot[i] += int(m.group(i + 1))
        kept = sum(num(r"wrocilo (\d+)", s, default=0) for s in am_old)
        gone = sum(num(r"przepadlo (\d+)", s, default=0) for s in am_old)
        stum = max([num(r"potkniecia \(sesja\) (\d+)", s, default=0) for s in am] + [0])
        unw = sum(1 for s in am if "latka NIE WPIETA" in s)
        ok = (tot[0] + tot[2] + tot[4] == kept and tot[1] + tot[3] + tot[5] == kept + gone and len(am) == len(am_old) and stum == 0 and unw == 0)

        def share(a, b):
            return f"{a} z {b}" + (f" ({100.0 * a / b:.0f}%)" if b > 0 else "")
        rep.add("A-2: odzysk amunicji wedlug stron po bitwie gracza",
                (f"{len(am)} bitew: strona gracza {share(tot[0], tot[1])}, przeciwnik {share(tot[2], tot[3])}, bez rozstrzygniecia (w trakcie misji - stara regula) "
                 f"{share(tot[4], tot[5])} | linia 'wrocilo / przepadlo': {kept} / {gone} | stan [{states(am, 'odzysk wedlug strony (E8/A)')}], potkniecia {stum}"
                 + (f", latka NIE WPIETA w {unw} liniach" if unw else "")),
                "trzy pozycje = linia 'wrocilo / przepadlo', latka wpieta, potkniecia 0 (strona, ktora oddala pole: udzial nizszy - zostaje jej tylko niewystrzelona czesc)", ok)
    # A-3
    hits = sum(num(r"- (\d+) ciosow", s, default=0) for s in skip)
    shots = sum(num(r"i (\d+) strzalow", s, default=0) for s in skip)
    zp = sum(e8a_pts(r"wyzerowana, ([0-9.,]+) pkt", s) for s in zero)
    lp = sum(e8a_pts(r"opuszczona - ([0-9.,]+) pkt", s) for s in lost)
    rep.add("A-3: arena nie obija - ciosy poza bitwa i ksiega ciosow",
            (f"misje poza bitwa z pominietymi ciosami: {len(skip)} ({hits} ciosow, {shots} strzalow bohatera); ksiega wyzerowana na poczatku bitwy: {len(zero)}x "
             f"({zp:.1f} pkt); po bitwie przegranej albo opuszczonej: {len(lost)}x ({lp:.1f} pkt)") if (skip or zero or lost)
            else "brak misji poza bitwa i bitew gracza z ciosami w biegu",
            "INFO (sprawdza Jeff w grze - 8.16 pkt 10: po arenie i wygranej bitwie rynsztunek bez obic z areny)", None)
    # A-4
    # recenzja E8/A: dzialki DTE bez "cialo po ciele" (stara linia) - przy kluczu [wl] to bitwa bez znacznikow zabojcy
    # (tylko linie PO pierwszej linii startu E8/A - log z kilku sesji moze miec dzialki sprzed paczki)
    first = next((i for i, s in enumerate(lines) if s.startswith(E8_A_ST_LOOT)), None)
    plain = [] if first is None else [s for s in lines[first:] if s.startswith("BattlefieldLaw: ") and "z magazynu wojska czeka na ekran lupow" in s
                                      and "cialo po ciele" not in s]
    key_on = "wl" in states(st_l, "w calosci").split("/")
    if not loot and plain and key_on:
        rep.add("A-4: lup z wlasnych zabojstw w calosci (cialo po ciele)",
                (f"{len(plain)} wygranych bitew z dzialka DTE przy kluczu [wl], ale ani jednej linii 'lup cialo po ciele' - znaczniki zabojcy nie doszly "
                 f"(latka AddLootedItem nie biegnie?) i dzialka liczy sie po staremu, srednia z puli; ostatnia: {plain[-1][:120]}"),
                "kazda wygrana bitwa ladowa z dzialka DTE ma linie 'lup cialo po ciele' (wyjatek: same bitwy morskie - lup z losowania DTE - albo klucz wylaczony w trakcie sesji)",
                False)
    elif not loot:
        rep.add("A-4: lup z wlasnych zabojstw w calosci (cialo po ciele)", "brak wygranych bitew gracza z misja i lupem DTE w biegu",
                "potkniecia 0; przy >= 5 powalonych przez gracza i towarzyszy sztuki z ich cial > 0 (sprawdza Jeff w grze)", None)
    else:
        h = sum(num(r"i towarzyszy (\d+) szt\. w calosci", s, default=0) for s in loot)
        k = sum(num(r"\(powalonych wrogow (\d+)\)", s, default=0) for s in loot)
        t = sum(num(r"przez zolnierzy (\d+) szt\.", s, default=0) for s in loot)
        u = sum(num(r"bez znanego zabojcy (\d+) szt\.", s, default=0) for s in loot)
        new = sum(num(r"dzialka gracza (\d+) szt\.", s, default=0) for s in loot)
        avg = sum(num(r"srednia z puli dalaby (\d+) szt\.", s, default=0) for s in loot)
        stum = max([num(r"potkniecia \(sesja\) (\d+)", s, default=0) for s in loot] + [0])
        rep.add("A-4: lup z wlasnych zabojstw w calosci (cialo po ciele)",
                (f"{len(loot)} bitew: z cial powalonych przez gracza i towarzyszy {h} szt. w calosci (powalonych wrogow {k}), przez zolnierzy {t} szt., "
                 f"bez znanego zabojcy {u} szt. | dzialka gracza {new} szt., srednia z puli dalaby {avg} szt. | potkniecia {stum}"
                 + (f" | dzialki bez znacznikow zabojcy (stara linia - bitwa morska albo klucz wylaczony): {len(plain)}" if plain else "")),
                "potkniecia 0; dzialka >= sztuki z wlasnych zabojstw; przy >= 5 powalonych przez gracza i towarzyszy sztuki z ich cial > 0",
                stum == 0 and new >= h and not (k >= 5 and h == 0))


# ============================================================ ETAP 8 (E8/Z, paczka 251): zakupy i nadwyzki AI - blok etap8_z
E8_Z_LINE = "Zakupy i nadwyzki AI (E8/Z): dzien"
E8_Z_COVER = "Pokrycie zbrojowni AI (171): dzien"
E8_Z_Z33_GARR_BODY_D120 = 90   # Z33 doba 120: "zalogi AI (77310 ludzi): korpus 90%" (L:35726)
E8_Z_AIGEAR_ROWS = ("lordowie", "zalogi miast", "zalogi zamkow (wlasna polka)", "zamowienia zamkow (w miescie)")   # wiersze linii E8/P2 z zakupow brakow AiGear


def etap8_z(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/Z (251, projekt etapu 8 v2 rozdz. 3 "E8/Z" Test): linia doby "Zakupy i nadwyzki AI (E8/Z)" (AiBuyRules.cs; ten sam takt doby i ta sama etykieta
    co "ZakupyAI cena do wartosci (E8/P2)"). Z-0 linia w kazdej dobie okna i stan czterech kluczy; Z-1 kupione dodatnie stany = 0 w dobach z kluczem [WL]
    (linia E8/Z i - gdy jest - wiersze zakupow brakow AiGear linii E8/P2 tych samych dob), stroj mieszczan kupiony = 0 tak samo; Z-2 sufit ceny: W CIENIU -
    INFO "tyle zablokowalby sufit 2.0"; po wlaczeniu - sztuki kupione ponad sufit 0, p90 cena / wartosc wierszy AiGear linii E8/P2 <= sufit i pokrycie
    korpusu zalog w ostatniej dobie okna >= Z33 doby 120 (90%); Z-3 uprzaz w zbrojowniach AI: doba `until` <= 1.2 x doba until/2 (projekt: d120 <= d60 x 1.2);
    Z-4 potkniecia 0, koszt spisu INFO."""
    zl = {d: s for d, s in by_day(lines, E8_Z_LINE).items() if 1 <= run_day(d, start) <= until}
    if not zl:
        rep.add("E8/Z: linia Zakupy i nadwyzki AI (E8/Z)", "brak w logu", "jest od wgrania E8/Z", None)
        return
    days = sorted(zl)
    nd = max(1, len(days))
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in zl]

    def on_days(tag):
        return [d for d in days if tag in zl[d]]
    fine_on, dress_on = on_days("| dodatnie stany [WL]"), on_days("| stroj mieszczan bez zolnierza [WL]")
    cap_on, har_on = on_days("| sufit ceny [WL x"), on_days("| uprzaz ponad zapas [WL]")
    rep.add("Z-0: linia Zakupy i nadwyzki AI (E8/Z) w kazdej dobie okna; stan kluczy",
            (f"{len(days)} dob (brak {len(miss)}" + (f": doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") if miss else "") + f" z {len(inner)}); "
             f"AiSkipFineGoods wl {len(fine_on)} / wyl {len(days) - len(fine_on)} dob, AiSkipTownsfolkDress wl {len(dress_on)} / wyl {len(days) - len(dress_on)}, "
             f"AiGearMaxPriceFactor wl {len(cap_on)} / w cieniu {len(days) - len(cap_on)}, AiHarnessSurplusSell wl {len(har_on)} / wyl {len(days) - len(har_on)}"),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def col(pat, cast=int):
        return {d: num(pat, zl[d], cast=cast, default=0) for d in days}

    def tot(c, sel=None):
        return sum(c[d] for d in (days if sel is None else sel))
    # wiersze linii E8/P2 tych samych dob: dodatnie stany i p90 wedlug kupujacego
    p2 = {d: s for d, s in by_day(lines, E8_P2_BUY).items() if d in zl}

    def p2_rows(sel):
        fa, fo, p90 = 0, 0, []
        for d in sel:
            s = p2.get(d)
            if s is None:
                continue
            for seg in s.split(" | ")[1:]:
                m = E8_P2_ROW.match(seg.strip())
                if not m:
                    continue
                if m.group(1) in E8_Z_AIGEAR_ROWS:
                    fa += int(m.group(14))
                    p90.append(float(m.group(6)))
                else:
                    fo += int(m.group(14))
        return fa, fo, p90
    # Z-1: dodatnie stany
    f_skip, f_vis, f_buy, f_gold = col(r"dodatnie stany \[[^\]]*\]: odrzucenia kandydatow (\d+)"), col(r"dodatnie stany \[[^\]]*\]: odrzucenia kandydatow \d+ w (\d+) wizytach"), \
        col(r"kupione dodatnie stany (\d+) szt"), col(r"kupione dodatnie stany \d+ szt\. \(doplata (-?\d+) zl")
    p2n = sum(1 for d in fine_on if d in p2)
    fa, fo, _ = p2_rows(fine_on)
    off_days = [d for d in days if d not in fine_on]
    txt = (f"klucz [WL] {len(fine_on)} dob: kupione {tot(f_buy, fine_on)} szt. (doplata {tot(f_gold, fine_on)} zl), odrzucenia kandydatow {tot(f_skip, fine_on)} w "
           f"{tot(f_vis, fine_on)} wizytach (ta sama sztuka liczona przy kazdym przegladzie polki)"
           + (f"; linia E8/P2 w {p2n} z tych dob: zakupy brakow AiGear {fa} szt., pozostali kupujacy (notable, lepsze za swoje, ludzie gracza) {fo} szt." if p2n else "; linii E8/P2 brak")
           + (f" | klucz wylaczony {len(off_days)} dob: kupione {tot(f_buy, off_days)} szt., doplata {tot(f_gold, off_days)} zl" if off_days else ""))
    rep.add("Z-1: AI nie kupuje dodatnich stanow (zakupy brakow lordow i zalog, zamowienia zamkow)", txt,
            "kupione dodatnie stany = 0 w dobach z kluczem [WL] (linia E8/Z i wiersze AiGear linii E8/P2); notable i ludzie gracza - INFO (stan zostaje przy sztuce)",
            (tot(f_buy, fine_on) == 0 and fa == 0) if fine_on else None)
    d_skip, d_vis, d_buy = col(r"stroj mieszczan bez zolnierza \[[^\]]*\]: odrzucenia kandydatow (\d+)"), \
        col(r"stroj mieszczan bez zolnierza \[[^\]]*\]: odrzucenia kandydatow \d+ w (\d+) wizytach"), col(r"kupiony stroj mieszczan (\d+) szt")
    off_days = [d for d in days if d not in dress_on]
    rep.add("Z-1b: AI nie kupuje stroju mieszczan, ktorego nie nosi zaden zolnierz",
            (f"klucz [WL] {len(dress_on)} dob: kupione {tot(d_buy, dress_on)} szt., odrzucenia kandydatow {tot(d_skip, dress_on)} w {tot(d_vis, dress_on)} wizytach"
             + (f" | klucz wylaczony {len(off_days)} dob: kupione {tot(d_buy, off_days)} szt." if off_days else "")),
            "kupiony stroj mieszczan = 0 w dobach z kluczem [WL]", (tot(d_buy, dress_on) == 0) if dress_on else None)
    # Z-2: sufit ceny
    c_skip, c_vis, c_n, c_g, c_all = col(r"sufit ceny \[[^\]]*\]: odrzucenia kandydatow (\d+)"), col(r"sufit ceny \[[^\]]*\]: odrzucenia kandydatow \d+ w (\d+) wizytach"), \
        col(r"kupione ponad sufit (\d+) szt"), col(r"kupione ponad sufit \d+ szt\. / (\d+) zl"), col(r"zl z (\d+) kupionych sztuk")
    cov = {d: s for d, s in by_day(lines, E8_Z_COVER).items() if 1 <= run_day(d, start) <= until}
    cv = None
    for d in sorted(cov, reverse=True):
        v = num(r"zalogi AI \(\d+ ludzi\): korpus (\d+)%", cov[d])
        if v is not None:
            cv = (run_day(d, start), v)
            break
    ctxt = f"pokrycie korpusu zalog doba {cv[0]}: {cv[1]}% (Z33 doba 120: {E8_Z_Z33_GARR_BODY_D120}%)" if cv else "brak linii Pokrycie zbrojowni AI (171)"
    sh_days = [d for d in days if d not in cap_on]
    if not cap_on:
        allp = tot(c_all)
        rep.add("Z-2: sufit ceny zakupow brakow AI (W CIENIU)",
                (f"klucz AiGearMaxPriceFactor = 0 - sufit 2.0 zablokowalby {tot(c_n)} szt. / {tot(c_g)} zl z {allp} kupionych sztuk "
                 f"({100.0 * tot(c_n) / max(1, allp):.1f}% sztuk; {tot(c_n) / nd:.1f} szt. i {tot(c_g) / nd:.0f} zl na dobe); {ctxt}"),
                "INFO (wlaczenie w fazie poprawek; wtedy: kupione ponad sufit 0, p90 cena / wartosc <= sufit, pokrycie korpusu zalog >= Z33)", None)
    else:
        fac = [num(r"sufit ceny \[WL x([0-9.]+)\]", zl[d], cast=float) for d in cap_on]
        fac = [x for x in fac if x is not None]
        fmax = max(fac) if fac else 0.0
        _, _, p90 = p2_rows(cap_on)
        p90m = max(p90) if p90 else None
        ok = tot(c_n, cap_on) == 0 and (p90m is None or p90m <= fmax + 0.005) and cv is not None and cv[1] >= E8_Z_Z33_GARR_BODY_D120
        rep.add("Z-2: sufit ceny zakupow brakow AI wlaczony",
                (f"klucz [WL x{fmax:.2f}] {len(cap_on)} dob: kupione ponad sufit {tot(c_n, cap_on)} szt. / {tot(c_g, cap_on)} zl, odrzucenia kandydatow {tot(c_skip, cap_on)} w "
                 f"{tot(c_vis, cap_on)} wizytach; p90 cena / wartosc wierszy AiGear linii E8/P2 najwyzej " + (f"{p90m:.2f}" if p90m is not None else "- (brak linii E8/P2)")
                 + f"; {ctxt}" + (f" | w cieniu {len(sh_days)} dob: sufit 2.0 zablokowalby {tot(c_n, sh_days)} szt. / {tot(c_g, sh_days)} zl" if sh_days else "")),
                f"kupione ponad sufit 0, p90 cena / wartosc <= sufit, pokrycie korpusu zalog w ostatniej dobie okna >= Z33 doby 120 ({E8_Z_Z33_GARR_BODY_D120}%)", ok)
    orders = col(r"na polce lezala tylko sztuka nie dla AI: (\d+)")
    l_fine, l_dress, l_cap = col(r"nie kupiono przez regule\): dodatni stan (\d+) szt"), col(r"nie kupiono przez regule\): dodatni stan \d+ szt\., stroj mieszczan (\d+) szt"), \
        col(r"stroj mieszczan \d+ szt\., ponad sufit (\d+) szt")
    allb = tot(c_all)
    rep.add("E8/Z: brak zostal przy polce ze sztuka nie dla AI (najwyzej tyle AI nie kupilo przez regule)",
            (f"dodatni stan {tot(l_fine)} szt. ({tot(l_fine) / nd:.0f}/d = {100.0 * tot(l_fine) / max(1, allb + tot(l_fine)):.1f}% wobec kupionych {allb} + tych sztuk), "
             f"stroj mieszczan {tot(l_dress)} szt. ({tot(l_dress) / nd:.1f}/d), ponad sufit {tot(l_cap)} szt. ({tot(l_cap) / nd:.1f}/d); zamowienia dla warsztatow z tego powodu "
             f"{tot(orders)} ({tot(orders) / nd:.1f}/d); {ctxt}"),
            "INFO - koszt reguly dla zbrojowni AI (warsztaty daja dodatni stan ok. 26% wyrobow - wagi modyfikatorow gry i RBM); granica: pokrycie zbrojowni wobec Z33", None)
    # Z-3: uprzaz w zbrojowniach AI
    h_all, h_lord, h_gar = col(r"uprzaz w zbrojowniach AI (\d+) szt"), col(r"uprzaz w zbrojowniach AI \d+ szt\. \(lordowie (\d+)"), col(r"uprzaz w zbrojowniach AI \d+ szt\. \(lordowie \d+, zalogi (\d+)\)")
    riders, over, overp = col(r"przy jezdzcach (\d+)"), col(r"zostaje (\d+) szt\. w \d+ partiach"), col(r"zostaje \d+ szt\. w (\d+) partiach")
    sold, gold, sold_g, third, parts, nob = col(r"uprzaz ponad zapas \[[^\]]*\]: sprzedana (\d+) szt"), col(r"sprzedana \d+ szt\. za (\d+) zl \(w tym zalogi"), \
        col(r"\(w tym zalogi (\d+) szt"), col(r"trzecia panom (\d+) zl"), col(r"zl\) w (\d+) partiach, zabraklo kupca"), col(r"zabraklo kupca (\d+) razy")
    cens = {run_day(d, start): d for d in days if "uprzaz w zbrojowniach AI: brak spisu" not in zl[d] and "uprzaz w zbrojowniach AI " in zl[d]}
    half = until // 2
    last = days[-1]
    info = (f"sprzedana w oknie {tot(sold)} szt. za {tot(gold)} zl ({tot(sold) / nd:.1f} szt./d; w tym zalogi {tot(sold_g)} szt.; trzecia panom {tot(third)} zl) w {tot(parts)} wizytach, "
            f"zabraklo kupca {tot(nob)} razy; ostatnia doba: ponad 1.5 x (jezdzcy + luz) zostaje {over[last]} szt. w {overp[last]} partiach")
    if not har_on:
        rep.add("Z-3: uprzaz w zbrojowniach AI", "klucz AiHarnessSurplusSell wylaczony w calym oknie; " + info, "INFO (prog liczony przy wlaczonym kluczu)", None)
    elif half in cens and until in cens:
        a, b = cens[half], cens[until]

        def per(d):
            return f"{h_all[d]} szt. (lordowie {h_lord[d]}, zalogi {h_gar[d]}) przy {riders[d]} jezdzcach = {h_all[d] / max(1, riders[d]):.2f} na jezdzca"
        rep.add(f"Z-3: uprzaz w zbrojowniach AI - doba {until} wobec doby {half}",
                f"doba {half}: {per(a)}; doba {until}: {per(b)} = x{h_all[b] / max(1, h_all[a]):.2f} | " + info
                + ("" if len(har_on) == len(days) else f" | klucz wylaczony w {len(days) - len(har_on)} dobach"),
                f"uprzaz w zbrojowniach AI w dobie {until} <= 1.2 x doba {half} (projekt: d120 <= d60 x 1.2; po E8/H prog do przeliczenia - H celowo podnosi stan uprzezy)",
                h_all[b] <= 1.2 * h_all[a])
    else:
        rep.add("Z-3: uprzaz w zbrojowniach AI", f"brak spisu w dobie {half} albo {until} (spis w {len(cens)} dobach); " + info,
                f"potrzebne doby kampanii {half} i {until} z linia E8/Z", None)
    # Z-4: potkniecia i koszt spisu
    stum = max([num(r"potkniecia \(sesja\) (\d+)", zl[d], default=0) for d in days] + [0])
    cost = col(r"koszt spisu ([0-9.]+) ms", cast=float)
    rep.add("Z-4: potkniecia E8/Z i koszt spisu uprzezy", f"potkniecia (sesja) {stum}; koszt spisu srednio {sum(cost.values()) / nd:.1f} ms/d, najwiecej {max(cost.values()) if cost else 0.0:.1f} ms",
            "potkniecia 0 (koszt - INFO; projekt: koszt paczki ok. 0)", stum == 0)


# ============================================================ ETAP 8 (E8/L, paczka 252): lup i dary Spoils - blok etap8_l
E8_L_LINE = "Lup i dary (E8/L): dzien"
E8_L_START = "Lup i dary (E8/L): start"
E8_L_KINDS = ("bron", "pociski", "zbroja", "tarcze", "uprzaz i inne")
E8_L_TR = re.compile(r"przeniesienie \[(wl|wyl)\]: bitew z lupem DTE innym niz konie (\d+), dopisane zwyciezcom (\d+) szt\., zdjete u pokonanych (\d+) szt\. w (\d+) partiach "
                     r"\(zalogi (\d+), partie lordow (\d+), inne (\d+); bron (\d+), pociski (\d+), zbroja (\d+), tarcze (\d+), uprzaz i inne (\d+)\), brak u pokonanych (\d+)")
E8_L_SIM = re.compile(r"Send troops \[(wl|wyl)\]: bitew (\d+), lup DTE z poleglych (\d+) szt\., dzialka kapitana na ekran (\d+) szt\., loteria Spoils pominieta w (\d+) bitwach "
                      r"\((\d+) szt\. z niczego\), szablonowa loteria gry pominieta (\d+) razy")
E8_L_GIFT = re.compile(r"dar dla miasta \[(wl|wyl), milicja z daru (wycieta|zostaje)\]: darow (\d+), sztuk (\d+), do zbrojowni zalogi (\d+), na polke miasta (\d+) \(w tym wrakow (\d+)\), "
                       r"z powrotem do sakw (\d+), przepadlo \(klucz wylaczony\) (\d+), milicja z niczego: nie przyznano ([0-9.]+), przyznano ([0-9.]+)")
E8_L_REM = re.compile(r"trofea zostawione na polu \[(wl|wyl)\]: wyjsc z resztka (\d+), na polke warowni (\d+) szt\., zostalo na polu \(unikaty, nie-towar\) (\d+), bez warowni (\d+), "
                      r"przepadlo \(klucz wylaczony\) (\d+), loteria Spoils \(z niczego - przepada jak dotad\) (\d+), pozostalosc pola Spoils (\d+)")


def etap8_l(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/L (252, projekt etapu 8 v2 rozdz. 3 "E8/L" Test; odpowiedzi Jeffa 12.10 nr 1 i 6). Linia doby "Lup i dary (E8/L)" (HorseFate.LLine - ten sam
    takt i ta sama etykieta doby co "Lup DTE - kopie (E8/P2)") i linia startu "Lup i dary (E8/L): start" (SpoilsSeal.LWire).
    L-0 linia startu: latki Spoils wpiete 4/4, okno DTE wpiete, prawo zachowania lupu czynne; linia doby w kazdej dobie okna (bez pierwszej i ostatniej);
    L-1 (prog projektu) lup to przeniesienie - w dobach z kluczem [wl]: zdjete u pokonanych + brak u pokonanych = dopisane zwyciezcom i brak = 0
        (sztuka dopisana zwyciezcy, ktorej u pokonanych nie bylo, to jedyna mozliwa kopia); gdy jest linia E8/P2 tych samych dob: dopisane (E8/L) =
        dopisane zwyciezcom bez koni (E8/P2 - drugi, niezalezny pomiar tego samego okna DTE) i kopie u ocalalych pokonanych (E8/P2) = 0;
    L-2 INFO (projekt: przybytek zbrojowni zalog po oblezeniach): komu zeszlo - zalogi, partie lordow, inne - i jakie rodzaje;
    L-3 dary i "Send troops" (autotest ich nie gra - zwykle zera; progi dla gry Jeffa, 8.16 punkty 8 i 11): dar - sztuk = do zalogi + na polke + do sakw
        + przepadlo, przy [wl] przepadlo 0, przy "milicja wycieta" przyznano 0; trofea - przy [wl] przepadlo (klucz wylaczony) 0; Send troops - dzialka
        kapitana <= lup DTE z poleglych;
    L-4 potkniecia (sesja) 0."""
    ll = {d: s for d, s in by_day(lines, E8_L_LINE).items() if 1 <= run_day(d, start) <= until}
    st = [s for s in lines if s.startswith(E8_L_START)]
    if not ll and not st:
        rep.add("E8/L: linia Lup i dary (E8/L)", "brak w logu", "jest od wgrania E8/L (LootIsTransfer, SendTroopsOneLoot, SpoilsGoodsHome, SpoilsGiftNoMilitia, SpoilsRemnantsHome)", None)
        return
    days = sorted(ll)
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ll]
    # L-0: start i komplet linii
    if st:
        s0 = st[-1]
        w = re.search(r"latki Spoils wpiete (\d+)/(\d+)", s0)
        ok0 = bool(w) and w.group(1) == w.group(2) and "okno DTE wpiete" in s0 and "prawo zachowania lupu czynne" in s0 and "wylaczone w tej wersji" in s0
        rep.add("L-0a: linia startu Lup i dary (E8/L)",
                (f"latki Spoils wpiete {w.group(1)}/{w.group(2)}" if w else "brak liczby latek") + " | " + s0.split(" | ", 1)[-1][:260],
                "latki Spoils wpiete 4/4, pozostalosci pola Spoils wylaczone w tej wersji, okno DTE wpiete, prawo zachowania lupu czynne", ok0)
    else:
        rep.add("L-0a: linia startu Lup i dary (E8/L)", "brak linii startu", "jest przy starcie gry (SpoilsSeal.ApplyAll) - bez Spoils of War jej nie ma", None)
    rep.add("L-0b: linia Lup i dary (E8/L) w kazdej dobie okna", f"dob z linia {len(days)}; brak w dobach kampanii: {miss[:10] if miss else 'brak'}",
            "linia w kazdej dobie okna (bez pierwszej i ostatniej)", (not miss) if inner else None)
    if not days:
        return
    tr = {d: E8_L_TR.search(ll[d]) for d in days}
    bad_fmt = [run_day(d, start) for d in days if not tr[d]]
    if bad_fmt:
        rep.add("L-1: lup to przeniesienie", f"linia w innym formacie w dobach {bad_fmt[:10]}", "format linii z HorseFate.LLine", False)
        return
    on = [d for d in days if tr[d].group(1) == "wl"]

    def tsum(i, dd):
        return sum(int(tr[d].group(i)) for d in dd)
    ev, gained, taken, parties, gar, lord, oth, missing = (tsum(i, on) for i in (2, 3, 4, 5, 6, 7, 8, 14))
    kinds = ", ".join(f"{E8_L_KINDS[k]} {tsum(9 + k, on)}" for k in range(5))
    p2 = {d: s for d, s in by_day(lines, "Lup DTE - kopie (E8/P2): dzien").items() if d in ll}
    p2on = [d for d in on if d in p2]
    p2g = sum(num(r"dopisane zwyciezcom \(bez koni\) (\d+)", p2[d], default=0) for d in p2on)
    p2k = sum(num(r"kopie u ocalalych pokonanych (\d+) szt\.", p2[d], default=0) for d in p2on)
    lg = tsum(3, p2on)
    if not on:
        off_g = tsum(3, days)
        rep.add("L-1: lup to przeniesienie", f"klucz LootIsTransfer wylaczony we wszystkich {len(days)} dobach (dopisane {off_g} szt. - kopie zostaja jak przed paczka)",
                "klucz wlaczony: zdjete + brak = dopisane, brak 0, kopie u ocalalych (E8/P2) 0", None)
    else:
        ok1 = taken + missing == gained and missing == 0 and (not p2on or (lg == p2g and p2k == 0))
        rep.add("L-1: lup to przeniesienie (sztuki inne niz konie)",
                (f"{len(on)} dob z kluczem [wl]: bitew z lupem DTE {ev}, dopisane zwyciezcom {gained} szt., zdjete u pokonanych {taken} szt., brak u pokonanych {missing}"
                 + (f" | E8/P2 w {len(p2on)} tych dobach: dopisane (bez koni) {p2g} szt. wobec {lg} z linii E8/L, kopie u ocalalych pokonanych {p2k} szt."
                    + (" (jesli brak = 0 i sumy sie zgadzaja, to nie kopie, tylko sztuki, ktorych DTE zwyciezcom nie rozdal - sprawdzic w logu)" if p2k else "")
                    if p2on else " | linii E8/P2 brak (Stage8MeasureLog wylaczony) - bez drugiego pomiaru")
                 + ("" if len(on) == len(days) else f" | klucz wylaczony w {len(days) - len(on)} dobach")),
                "zdjete + brak = dopisane i brak u pokonanych 0; z linia E8/P2: dopisane (E8/L) = dopisane (E8/P2) i kopie u ocalalych = 0", ok1)
        rep.add("L-2: komu zeszlo ze zbrojowni (pokonani po bitwie)",
                f"{parties} partii w {ev} bitwach: zalogi {gar} szt., partie lordow {lord} szt., inne {oth} szt. | rodzaje: {kinds} | srednio {taken / max(1, len(on)):.0f} szt./d",
                "INFO (rozbite partie i tak tracily zbrojownie - nowe jest tylko to, co zeszlo ocalalym; ilu ocalalo - linia E8/P2)", None)
    # L-3: Send troops, dar dla miasta, trofea zostawione
    sim = [E8_L_SIM.search(ll[d]) for d in days]
    if all(sim):
        sb, sg, ss_, sc, scn, sgame = (sum(int(m.group(i)) for m in sim) for i in (2, 3, 4, 5, 6, 7))
        son = sum(1 for m in sim if m.group(1) == "wl")
        rep.add("L-3a: Send troops - jedna droga lupu",
                f"bitew {sb}, lup DTE z poleglych {sg} szt., dzialka kapitana {ss_} szt., loteria Spoils pominieta w {sc} bitwach ({scn} szt. z niczego), szablonowa loteria gry pominieta {sgame} razy"
                f" | klucz [wl] w {son} z {len(days)} dob",
                "dzialka kapitana <= lup DTE z poleglych (autotest nie gra bitew gracza - zera to INFO)", (ss_ <= sg) if sb else None)
    else:
        rep.add("L-3a: Send troops - jedna droga lupu", "linia w innym formacie", "format linii z HorseFate.LLine", False)
    if any("Spoils of War nieobecny" in ll[d] for d in days):
        rep.add("L-3b: dar dla miasta i trofea zostawione", "Spoils of War nieobecny", "INFO (bez Spoils nie ma tych drog)", None)
    else:
        gf = [E8_L_GIFT.search(ll[d]) for d in days]
        rm = [E8_L_REM.search(ll[d]) for d in days]
        if not all(gf) or not all(rm):
            rep.add("L-3b: dar dla miasta i trofea zostawione", "linia w innym formacie", "format czesci Spoils z SpoilsSeal.TakeLPart", False)
        else:
            gn, gp, ga, gs, gw, gb, gl = (sum(int(m.group(i)) for m in gf) for i in (3, 4, 5, 6, 7, 8, 9))
            mc, ml = sum(float(m.group(10)) for m in gf), sum(float(m.group(11)) for m in gf)
            lost_on = sum(int(m.group(9)) for m in gf if m.group(1) == "wl")
            mil_on = sum(float(m.group(11)) for m in gf if m.group(2) == "wycieta")
            okg = gp == ga + gs + gb + gl and lost_on == 0 and mil_on < 0.005
            rep.add("L-3b: dar dla miasta (Donate to town) - sztuki do zalogi, bez milicji z niczego",
                    f"darow {gn}, sztuk {gp}: do zbrojowni zalogi {ga}, na polke miasta {gs} (w tym wrakow {gw}), z powrotem do sakw {gb}, przepadlo {gl} (przy kluczu [wl] {lost_on})"
                    f" | milicja z niczego: nie przyznano {mc:.2f}, przyznano {ml:.2f} (przy kluczu 'wycieta' {mil_on:.2f})",
                    "sztuk = zaloga + polka + sakwy + przepadlo; przy [wl] przepadlo 0; przy 'milicja wycieta' przyznano 0 (autotest nie daje darow - zera to INFO)",
                    okg if gn else None)
            rn, rp_, rk, rw, rl_, rlot, rmade = (sum(int(m.group(i)) for m in rm) for i in (2, 3, 4, 5, 6, 7, 8))
            rl_on = sum(int(m.group(6)) for m in rm if m.group(1) == "wl")
            rep.add("L-3c: trofea zostawione na polu (Leave) - na polke najblizszej przyjaznej warowni",
                    f"wyjsc z resztka {rn}: na polke warowni {rp_} szt., zostalo na polu (unikaty, nie-towar) {rk}, bez warowni {rw}, przepadlo (klucz wylaczony) {rl_} (przy kluczu [wl] {rl_on}),"
                    f" loteria Spoils (z niczego - przepada) {rlot}, pozostalosc pola Spoils {rmade}",
                    "przy [wl] przepadlo (klucz wylaczony) 0 i bez warowni 0 (autotest nie zbiera trofeow - zera to INFO)", (rl_on == 0 and rw == 0) if rn else None)
    # L-4: potkniecia
    stum = max([num(r"potkniecia \(sesja\) (\d+)", ll[d], default=0) for d in days] + [0])
    wired = sorted(set((re.search(r"\| okno DTE (.*?) \| potkniecia", ll[d]) or [None, "?"])[1] for d in days))
    rep.add("L-4: potkniecia E8/L", f"potkniecia (sesja) {stum} | okno DTE: " + ", ".join(wired), "potkniecia 0 (HorseFate, SpoilsSeal E8/L, BattlefieldLaw E8/L razem)", stum == 0)


E8_C_START = "HistoricalPrices: uprzaz z wagi prawdziwej"
E8_C_MED = "Cennik (E8/C): mediany"
# Wzor Z33 (WGRANIE 33, Armoury-2026-10-12_02-44-09.log, doba 120): polki z linii "Rynek broni" (L:35865), kasy miast z "Nadwyzka kas (E5/0)" (L:36070),
# rody na minusie = suma "na minusie N" linii "Skarbce" ostatniej doby (projekt etapu 8 v2 rozdz. 4 pkt 5), polki koni z "Konie (E6/0)" (zwykly / bojowy)
E8_C_Z33_SHELF = {"Bow": 2995, "HeadArmor": 945, "Thrown": 373, "HorseHarness": 1253}
E8_C_Z33_RANGED_BUY = 348.5     # Z33: zakupy broni strzeleckiej AI (lordowie, zalogi miast, zamowienia zamkow, notable; linia "ZakupyAI wedlug kupujacego (174b)") szt./d w dobach 91-120; zb58: 375.8
E8_C_Z33_TOWN_GOLD = 10264881
E8_C_Z33_CLANS_MINUS = 197
E8_C_Z33_HORSES = (3599, 1737)
E8_C_BARD6_MAX = 2600      # prog projektu (z szacunku 2 531 przy stali szlachetnej 8 d/kg)
E8_C_BARD6_DECIDE = 2850   # ten sam wzor ze stala zamkowa t6 (12 d/kg, 177-1) daje ok. 2 760 - powyzej progu projektu, ponizej tej granicy = DECYZJA
E8_C_MED_RE = r" (-|[0-9.]+) \((\d+) szt\.(?:, (\d+)-(\d+))?\)"


def e8c_med(line, label):
    """'<label> 47 (13 szt., 28-79)' -> (mediana, liczba, min, maks) albo None; '- (0 szt.)' -> (None, 0, None, None)."""
    m = re.search(re.escape(label) + E8_C_MED_RE, line)
    if not m:
        return None
    if m.group(1) == "-":
        return (None, 0, None, None)
    return (float(m.group(1)), int(m.group(2)), int(m.group(3)) if m.group(3) else None, int(m.group(4)) if m.group(4) else None)


def e8c_shelves(lines):
    """Polki uzbrojenia wedlug doby: linia "Rynek broni: na polkach N szt. [Typ N, ...]" (bez etykiety doby) stoi przed "Pieniadz swiata: dzien N" tej samej doby."""
    out, pend = {}, None
    for s in lines:
        if s.startswith("Rynek broni: na polkach"):
            m = re.search(r"\[([^\]]*)\]", s)
            pend = dict((k, int(v)) for k, v in re.findall(r"(\w+) (\d+)", m.group(1))) if m else None
        elif s.startswith("Pieniadz swiata: dzien") and pend is not None:
            d = num(r"dzien (\d+)", s)
            if d is not None:
                out[d] = pend
            pend = None
    return out


def etap8_c(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/C (253, projekt etapu 8 v2 rozdz. 3 "E8/C" Test; odpowiedz Jeffa 12.10 nr 2 - konie wedlug kategorii TAK). Linie startu sesji (PriceList8.StartLine,
    po HistoricalPrices.Apply): "HistoricalPrices: uprzaz z wagi prawdziwej N szt., helmy t4-6 N, luki N, oszczepy N, konie N (E8/C) | ..." i
    "Cennik (E8/C): mediany wartosci sztuk na handel bez unikatow ...". Brana ostatnia para linii w logu (ostatnie wczytanie sesji).
    C-0 linie sa, klucze, potkniecia 0; C-1 mediany (progi projektu; reguly z wylaczonym kluczem - INFO); C-2 kwit kuzni uprzezy metalowej < wartosc;
    C-3 polki lukow: ostatnia doba <= 1.1 x stan sprzed 30 dob i zakupy broni strzeleckiej AI >= Z33 (TRIAZ-2; poziom wobec Z33 - INFO); C-4 kasy miast i rody na minusie wobec Z33 (wspolne progi rozdz. 4 pkt 5, tu dla zmiany cen helmow i lukow);
    C-5 INFO (reczne 8.16); C-6 INFO konie."""
    st = [s for s in lines if s.startswith(E8_C_START)]
    md = [s for s in lines if s.startswith(E8_C_MED)]
    if not st and not md:
        rep.add("E8/C: linie startu cennika", "brak w logu", "sa od wgrania E8/C (HarnessKgPerArmor, HelmDaysPerKg, HistBowDaysNew, HistThrownOwnDays, HistHorsePrices, ThrownAsMissile)", None)
        return
    s0 = st[-1] if st else ""
    m0 = md[-1] if md else ""
    # ---- C-0
    cnt = re.search(r"uprzaz z wagi prawdziwej (\d+) szt\., helmy t4-6 (\d+), luki (\d+), oszczepy (\d+), konie (\d+)", s0)
    hist = "ceny historyczne CZYNNE" in s0
    k_har = "| uprzaz: [wl]" in s0
    k_helm = "| helm plytowy t4-6: [wl]" in s0
    k_bow = "| luki [wl]" in s0
    k_thr = "| bron miotana bez mnoznika snopa [wl]" in s0
    k_mis = "bez obijania (R3) [wl]" in s0
    k_hor = "konie wedlug kategorii [wl]" in s0
    stum = max([num(r"potkniecia (\d+)\.$", x, default=0) for x in (s0, m0) if x] + [0])
    if cnt:
        nh, nhe, nb, nt, nk = (int(cnt.group(i)) for i in range(1, 6))
        okc = hist and (nh > 0 or not k_har) and (nhe > 0 or not k_helm) and (nb > 0 or not k_bow) and (nt > 0 or not k_thr) and (nk > 0 or not k_hor) and bool(m0)
        rep.add("C-0a: linie startu cennika (E8/C)",
                f"uprzaz z wagi prawdziwej {nh} szt., helmy t4-6 {nhe}, luki {nb}, oszczepy {nt}, konie {nk} | ceny historyczne {'CZYNNE' if hist else 'WYLACZONE'}"
                f" | klucze: uprzaz {'wl' if k_har else 'WYL'}, helm {'wl' if k_helm else 'WYL'}, luki {'wl' if k_bow else 'WYL'}, bron miotana bez snopa {'wl' if k_thr else 'WYL'},"
                f" konie {'wl' if k_hor else 'WYL'}, bron miotana jak pocisk {'wl' if k_mis else 'WYL'} | linia median {'jest' if m0 else 'BRAK'}",
                "obie linie sa, ceny historyczne czynne, kazda wlaczona regula obejmuje > 0 sztuk", okc)
    else:
        rep.add("C-0a: linie startu cennika (E8/C)", "linia startu w innym formacie albo brak" + ("" if m0 else "; linii median brak"), "format linii z PriceList8.StartLine", False)
    rep.add("C-0b: potkniecia cennika (E8/C)", f"potkniecia {stum}", "0 (PriceList8 i konie HistoricalPrices razem)", stum == 0)
    if not m0:
        return
    # ---- C-1 mediany
    def row(name, label, lo, hi, key_on, note=""):
        v = e8c_med(m0, label)
        if v is None:
            rep.add(name, "brak w linii median", "format linii z PriceList8.StartLine", False)
            return None
        if v[1] == 0:
            rep.add(name, "0 sztuk", "INFO (brak sztuk tej grupy na handel)", None)
            return None
        rng = f", zakres {v[2]}-{v[3]}" if v[2] is not None else ""
        txt = f"mediana {v[0]:g} ({v[1]} szt.{rng}){note}"
        if lo is None and hi is None:
            rep.add(name, txt, "INFO", None)
        elif not (hist and key_on):
            rep.add(name, txt + " | regula wylaczona albo bez cen historycznych", f"INFO (prog przy wlaczonym kluczu: {lo if lo is not None else '-'}-{hi})", None)
        else:
            rep.add(name, txt, (f"{lo}-{hi}" if lo is not None else f"<= {hi}"), (lo is None or v[0] >= lo) and v[0] <= hi)
        return v
    row("C-1a: siodla (uprzaz z pancerzem konia do 10)", "siodla", 24, 90, k_har, " | historia 24-60, tolerancja do 90")
    row("C-1b: kropierze (pancerz konia 11-30)", "kropierze", None, None, k_har)
    row("C-1c: bardy t1-3 (w tym 'siodla' ROT z naczolkiem, pancerz 38-44)", "bardy t1-3", None, None, k_har)
    row("C-1d: bardy t4-5", "bardy t4-5", None, 2400, k_har)
    b6 = e8c_med(m0, "bardy t6")
    if b6 is None:
        rep.add("C-1e: barda t6", "brak w linii median", "format linii z PriceList8.StartLine", False)
    elif b6[1] == 0:
        rep.add("C-1e: barda t6", "0 sztuk", "INFO", None)
    elif not (hist and k_har):
        rep.add("C-1e: barda t6", f"mediana {b6[0]:g} ({b6[1]} szt., maks. {b6[3]}) | regula wylaczona albo bez cen historycznych", f"INFO (prog przy wlaczonym kluczu <= {E8_C_BARD6_MAX})", None)
    else:
        ok6 = b6[0] <= E8_C_BARD6_MAX
        rep.add("C-1e: barda t6 (maks. INFO)",
                f"mediana {b6[0]:g} ({b6[1]} szt., maks. {b6[3]})"
                + ("" if ok6 else f" | prog projektu {E8_C_BARD6_MAX} liczony z szacunku 2 531 (stal szlachetna 8 d/kg); t6 kuje sie ze stali zamkowej 12 d/kg (177-1) - ten sam wzor"
                                  f" 0.4 kg na punkt daje ok. 2 760; do decyzji: zostawic (historia: 'najlepsze wyzej') albo HarnessKgPerArmor 0.37"),
                f"<= {E8_C_BARD6_MAX} (do {E8_C_BARD6_DECIDE} = DECYZJA - opis w wierszu)", ok6, decide=(not ok6 and b6[0] <= E8_C_BARD6_DECIDE))
    h3 = row("C-1f: helm t3 (bez zmiany - regula od t4)", "helm t3", None, None, k_helm)
    h4 = row("C-1g: helm t4", "helm t4", 30, 50, k_helm)
    row("C-1h: helm t5", "helm t5", 60, 100, k_helm)
    row("C-1i: helm t6", "helm t6", 100, 160, k_helm)
    if h3 and h4 and h3[0] is not None and h4[0] is not None:
        rep.add("C-1j: helm t3 wobec t4", f"t3 {h3[0]:g}, t4 {h4[0]:g}" + (" - helm t3 drozszy od t4 (regula projektu obejmuje tylko t4-6; opcja z rozpoznania B 2.5: ta sama regula od t3)" if h3[0] > h4[0] else ""),
                "INFO (do decyzji, gdy t3 > t4)", None)
    row("C-1k: luk t1", "luk t1", None, None, k_bow)
    row("C-1l: luk t2", "luk t2", None, None, k_bow)
    row("C-1m: luk t3", "luk t3", 15, 24, k_bow)
    row("C-1n: luk t4", "luk t4", 20, 32, k_bow)
    row("C-1o: luk t5", "luk t5", 28, 44, k_bow)
    row("C-1p: luk t6", "luk t6", 38, 60, k_bow)
    row("C-1q: bron miotana (stos)", "bron miotana", None, 40, k_thr)
    # ---- C-2 kwit kuzni
    q = re.search(r"uprzaz z plyty i kolczugi - material >= wartosc (\d+) z (\d+)( \[[^\]]*\])?, uprzaz ze skory i tkaniny \([^)]*\) (\d+) z (\d+)( \[[^\]]*\])?", m0)
    if q:
        rep.add("C-2a: kwit kuzni gracza - uprzaz z plyty i kolczugi", f"material >= wartosc {q.group(1)} z {q.group(2)}{q.group(3) or ''}",
                "0 sztuk (kwit z tej samej wagi co wartosc - R7)" + ("" if k_har else " - INFO przy wylaczonym kluczu"), (int(q.group(1)) == 0) if (hist and k_har) else None)
        rep.add("C-2b: kwit kuzni gracza - uprzaz ze skory i tkaniny", f"material >= wartosc {q.group(4)} z {q.group(5)}{q.group(6) or ''}",
                "INFO (kwit z punktow pancerza w calych sztukach skory 40 d i plotna 100 d - poza E8/C)", None)
    else:
        rep.add("C-2: kwit kuzni gracza wobec wartosci", "brak w linii median", "format linii z PriceList8.StartLine", False)
    # ---- C-3 polki
    sh = e8c_shelves(lines)
    days = [d for d in sorted(sh) if 1 <= run_day(d, start) <= until]
    if days:
        last = days[-1]
        cur = sh[last]
        bows = cur.get("Bow", 0)
        full = run_day(last, start) >= until
        # narzedzie progow p2 (TRIAZ-2 e "C-3a"): poziom wobec Z33 nie mierzy tego, przed czym prog chronil (luki, ktorych nikt nie kupuje). Nadmiar powstal
        # w dobach 1-30 (po E8/C luk to 1.5-2.5 dnia pracy - wiecej sztuk z roboczodnia, a po E8/T cech lucznikow zuzywa caly budzet startowy) i od doby 60
        # stoi (bieg 2: d30 11381, d60 7334, d90 7247, d120 7176), a AI kupuje tyle samo sztuk co w Z33, tylko taniej (357 wobec 349 szt./d w dobach 91-120).
        # Wiazace: trend (ostatnia doba <= 1.1 x stan sprzed 30 dob) i zakupy broni strzeleckiej AI w ostatnich 30 dobach >= Z33; poziom wobec Z33 - INFO.
        rdl = run_day(last, start)
        ref30 = [d for d in days if run_day(d, start) == rdl - 30]
        b30 = sh[ref30[0]].get("Bow", 0) if ref30 else 0
        rb = []
        for d, s in by_day(lines, "ZakupyAI wedlug kupujacego (174b): dzien").items():
            if rdl - 29 <= run_day(d, start) <= rdl:
                rb.append(sum(int(x) for x in re.findall(r"bron strzelecka (\d+)/", s.split("; nadwyzki sprzedane")[0])))
        pb = (sum(rb) / len(rb)) if rb else None
        rep.add(f"C-3a: polki lukow (doba {rdl}) - trend 30 dob i zakupy broni strzeleckiej AI",
                (f"{bows} szt. wobec doby {rdl - 30}: {b30} (x{bows / b30:.2f})" if b30 > 0 else f"{bows} szt. (brak stanu sprzed 30 dob)")
                + (f"; zakupy broni strzeleckiej AI {pb:.1f} szt./d ({len(rb)} dob; Z33 doby 91-120: {E8_C_Z33_RANGED_BUY})" if pb is not None else "; brak linii ZakupyAI wedlug kupujacego (174b)")
                + f"; poziom wobec Z33 doba 120: {E8_C_Z33_SHELF['Bow']} (x{bows / E8_C_Z33_SHELF['Bow']:.2f}) - INFO",
                f"polki <= 1.1 x stan sprzed 30 dob i zakupy >= Z33 ({E8_C_Z33_RANGED_BUY} szt./d)" + ("" if (full and until == 120) else " - INFO poza doba 120"),
                (bows <= 1.1 * b30 and pb >= E8_C_Z33_RANGED_BUY) if (full and until == 120 and b30 > 0 and pb is not None) else None)
        rep.add(f"C-3b: polki helmow, broni miotanej i uprzezy (doba {run_day(last, start)})",
                ", ".join(f"{k} {cur.get(k, 0)} (Z33 {E8_C_Z33_SHELF[k]})" for k in ("HeadArmor", "Thrown", "HorseHarness")),
                "INFO (warsztaty robia wiecej helmow i lukow na roboczodzien; bron miotana bez mnoznika snopa)", None)
    else:
        rep.add("C-3: polki lukow", "brak linii Rynek broni w oknie", "INFO", None)
    # ---- C-4 kasy miast, rody na minusie
    nad = {d: s for d, s in by_day(lines, "Nadwyzka kas (E5/0): dzien").items() if 1 <= run_day(d, start) <= until}
    if nad:
        last = max(nad)
        gold = num(r"miasta \d+: kasy (-?\d+)", nad[last])
        full = run_day(last, start) >= until - 1 and until == 120
        if gold is not None:
            rep.add(f"C-4a: suma kas miast (doba {run_day(last, start)})", f"{gold} wobec Z33 doba 120: {E8_C_Z33_TOWN_GOLD} ({100.0 * gold / E8_C_Z33_TOWN_GOLD:.1f}%)",
                    ">= 80% Z33" + ("" if full else " - INFO poza doba 120"), (gold >= 0.8 * E8_C_Z33_TOWN_GOLD) if full else None)
        ours = [num(r"nasze sciezki (\d+) z", s, default=None) for s in nad.values()]
        ours = [v for v in ours if v is not None]
        if ours:
            rep.add("C-4b: kasy miast ponizej zapasu przez nasze sciezki (suma okna)", f"{sum(ours)} w {len(ours)} dobach (niezerowe {sum(1 for v in ours if v)})",
                    "0 (wspolny prog rozdz. 4 pkt 5; rozbicie - bloki etapu 5)", sum(ours) == 0)
    else:
        rep.add("C-4a: suma kas miast", "brak linii Nadwyzka kas (E5/0)", "INFO", None)
    minus = {}
    for s in lines:
        if s.startswith("Skarbce: dzien"):
            d = num(r"dzien (\d+)", s)
            v = num(r"na minusie (\d+)", s)
            if d is not None and v is not None and 1 <= run_day(d, start) <= until + 1:
                minus[d] = minus.get(d, 0) + v
    if minus:
        last = max(minus)
        full = run_day(last, start) >= until and until == 120
        lim = E8_C_Z33_CLANS_MINUS * 1.1
        rep.add(f"C-4c: rody na minusie (linie Skarbce, dzien {last})", f"{minus[last]} wobec Z33 {E8_C_Z33_CLANS_MINUS}",
                f"<= Z33 + 10% ({lim:.0f})" + ("" if full else " - INFO poza doba 120"), (minus[last] <= lim) if full else None)
    # ---- C-5, C-6
    rep.add("C-5: obity oszczep w sakwach przez zapis i wczytanie", "autotest nie ma obitej broni miotanej w sakwach gracza", "INFO - reczne 8.16 (stan zostaje: CleanseAmmo czysci tylko strzaly i belty)", None)
    hl = re.search(r"konie wedlug kategorii \[wl\]: ([^|]*)", s0)
    dem = [x for x in lines if x.startswith("HistoricalPrices: popyt miast przeliczony")]
    r1 = num(r"[ ,]horse /(\d+(?:\.\d+)?)", dem[-1], cast=float, default=None) if dem else None
    r2 = num(r"war_horse /(\d+(?:\.\d+)?)", dem[-1], cast=float, default=None) if dem else None
    kon = {d: s for d, s in by_day(lines, "Konie (E6/0): dzien").items() if 1 <= run_day(d, start) <= until}
    ktxt = ""
    if kon:
        km = re.search(r"polki miast i zamkow (\d+)/(\d+)/", kon[max(kon)])
        if km:
            ktxt = f" | polki koni doba {run_day(max(kon), start)}: zwykle {km.group(1)} (Z33 {E8_C_Z33_HORSES[0]}), bojowe {km.group(2)} (Z33 {E8_C_Z33_HORSES[1]})"
    rep.add("C-6: konie wedlug kategorii",
            (hl.group(1).strip()[:300] if hl else "klucz wylaczony albo bez cen historycznych")
            + f" | przelicznik popytu: horse {'/' + format(r1, 'g') if r1 else 'brak'}, war_horse {'/' + format(r2, 'g') if r2 else 'brak'}" + ktxt,
            "przy wlaczonym kluczu przelicznik popytu horse /2.3-2.7 i war_horse /0.6-0.75 (mieszczanie kupuja tyle samo tych koni co dotad); polki koni INFO",
            None if not (k_hor and hist) else bool(r1 and r2 and 2.3 <= r1 <= 2.7 and 0.6 <= r2 <= 0.75))


# E8/P3 (245): blok etap8_p3 - pomiary swiata (Stage8World.cs)
E8_P3 = (("owce", "Owce (E8/P3): dzien"), ("postoj karawan", "Postoj karawan (E8/P3): dzien"), ("najemnicy BK", "Najemnicy BK (E8/P3): dzien"),
         ("rozkazy morskie", "Rozkazy morskie (E8/P3): dzien"), ("wsie bez wozu", "Wsie bez wozu (E8/P3): dzien"), ("koszt", "Pomiary swiata (E8/P3): dzien"))


def etap8_p3(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/P3 (245, projekt etapu 8 v2 rozdz. 3 "E8/P3" Test): pomiary swiata (Stage8World.cs) - sam log, stan "przed" dla E8/G1 i E8/G2.
    P3-0 latki pomiaru wpiete N/N (R11); P3-1 linie obecne: szesc linii doby w kazdej dobie okna (bez pierwszej i ostatniej), dopisek "pomiar E8/P3" w linii
    "BK i Diplomacy (E5/A8)" i linia "Produkcja wsi - model (E8/P3)" raz na sesje; P3-2 zatkane wsie Normal bez wozu ponad 7 dob - zadna 3 doby z rzedu (TRIAZ-2)
    (zamyka 8.12c); P3-3 INFO - pozostale liczby (model pod NavalDLC, postoj karawan, zamiana BK najemnikow, zrodla i ujscia BK, owce, rozkazy morskie,
    kara Underequipped po bitwach gracza, koszt); P3-K potkniecia i linie "ERROR in Stage8World.*" 0."""
    books = {k: {d: s for d, s in by_day(lines, p).items() if 1 <= run_day(d, start) <= until} for k, p in E8_P3}
    wire = [x for x in lines if x.startswith("Pomiary swiata (E8/P3): latki przy starcie gry")]
    model = [x for x in lines if x.startswith("Produkcja wsi - model (E8/P3): dzien")]
    if not wire and not model and not any(books.values()):
        rep.add("E8/P3: linie pomiarow swiata (E8/P3)", "brak w logu", "sa od wgrania E8/P3 (Stage8WorldLog)", None)
        return
    # ---------------- P3-0: latki
    if wire:
        w = wire[-1]
        a, b = num(r"wpiete (\d+)/\d+", w), num(r"wpiete \d+/(\d+)", w)
        rep.add("P3-0: latki pomiaru (DTE wystawiony z przydzialem i koniec misji; BK GiveFood, FinancialCompromise, DrainGold, BuyGoods)", w[:200],
                "wpiete N/N, BRAK: -", a is not None and b is not None and a == b and "; BRAK: - |" in w)
    else:
        rep.add("P3-0: latki pomiaru", "brak linii startowej", "wpiete N/N", False)
    # ---------------- P3-1: linie obecne
    inner = win[1:-1] if len(win) > 2 else []
    gaps = []
    for k, _ in E8_P3:
        miss = [run_day(d, start) for d in inner if d not in books[k]]
        if miss:
            gaps.append(f"{k} brak w {len(miss)} (doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") + ")")
    a8 = by_day(lines, "BK i Diplomacy (E5/A8): dzien")
    seg = {d: s[s.find("| pomiar E8/P3"):] for d, s in a8.items() if "| pomiar E8/P3" in s and 1 <= run_day(d, start) <= until}
    miss_seg = [run_day(d, start) for d in inner if d not in seg]
    if miss_seg:
        gaps.append(f"dopisek w linii BK i Diplomacy brak w {len(miss_seg)}" + (" (brak samej linii BK i Diplomacy)" if not a8 else ""))
    if not model:
        gaps.append("brak linii Produkcja wsi - model")
    rep.add("P3-1: linie pomiarow obecne (6 linii doby, dopisek BK i Diplomacy, model produkcji wsi raz na sesje)",
            (f"dob okna {len(inner)}: " + ("komplet" if not gaps else "; ".join(gaps))) + f"; linii modelu {len(model)}, dob z dopiskiem BK {len(seg)}",
            "komplet w kazdej dobie okna (bez pierwszej i ostatniej)", (not gaps) if inner else None)
    # ---------------- P3-2: zatkane wsie Normal bez wozu ponad 7 dob
    cart = books["wsie bez wozu"]
    if cart:
        vals = [(num(r"zatkane Normal bez wozu > 7 dob: (\d+)", cart[d], int, 0) or 0, d) for d in sorted(cart)]
        mx = max(vals)
        low = max(num(r"gra nie wystawi nowego: (\d+)", cart[d], int, 0) or 0 for d in cart)
        last = cart[max(cart)]
        a_none = num(r"wszystkie wsie bez wozu (\d+)", last, int, 0)
        a_norm = num(r"gra wystawia woz dopiero przy pelnym magazynie\) (\d+)", last, int, 0)
        # narzedzie progow p2 (TRIAZ-2 f "P3-2"): licznik "bez wozu" biegnie od utraty wozu, takze gdy wies byla spladrowana; gra wystawia nowy woz tylko
        # wsi Normal z pelnym magazynem, losem 15% na godzine (VillagerCampaignBehavior), wiec wies wpada w wiersz w dniu powrotu do Normal i znika po
        # wystawieniu wozu (bieg 2: po 1 wsi w dobach 32, 62-63, 106, 119, nastepnego dnia 0). Zatkana naprawde = stoi w wierszu doby z rzedu. Linia nie
        # podaje nazw wsi, wiec liczony jest najdluzszy ciag kolejnych dob z liczba > 0 (gorna granica postoju jednej wsi): NIE od 3 dob z rzedu.
        streak = best = 0
        prev = None
        for v, d in vals:
            streak = (streak + 1 if (prev is not None and d == prev + 1 and streak > 0) else 1) if v > 0 else 0
            best = max(best, streak)
            prev = d
        rep.add("P3-2: zatkane wsie Normal bez wozu ponad 7 dob (zamyka 8.12c)",
                f"najwiecej {mx[0]} (d{run_day(mx[1], start)}), dob z > 0: {sum(1 for v, _ in vals if v > 0)} z {len(vals)}, najdluzszy ciag dob z > 0: {best}"
                f"; w tym hearth ponizej progu wozu najwyzej {low}; ostatnia doba: wszystkie wsie bez wozu {a_none}, Normal > 7 dob (tez niezatkane) {a_norm}",
                "zadna wies w wierszu 3 doby z rzedu (ciag kolejnych dob z > 0 najwyzej 2; 1-2 doby = wies wrocila do Normal i czeka na los wozu)", best < 3)
    else:
        rep.add("P3-2: zatkane wsie Normal bez wozu ponad 7 dob", "brak linii Wsie bez wozu (E8/P3) - diagnoza zatkanych wsi wylaczona?", "0", None)

    # ---------------- P3-3: INFO
    def tot(book, rx):
        return sum(num(rx, s, int, 0) or 0 for s in book.values())

    def lastn(book, rx):
        return num(rx, book[max(book)], int, 0)
    if model:
        m = model[-1]
        ch = re.search(r"lancuch modeli \(czynny -> pod nim\): (.*?) \| pod czynnym", m)
        r_avg, r_n = fnum(r"iloraz sredni ([0-9.]+)", m), num(r"iloraz sredni [0-9.-]+ z (\d+) typow", m)
        rep.add("P3-3: produkcja wsi - lancuch modeli i iloraz czynny / pod nim (10 typow wsi, bez mnoznikow Armoury)",
                (ch.group(1) if ch else "?") + f"; iloraz sredni {r_avg} z {r_n} typow", "INFO (1.00 = czynny model nic nie doklada ponad model pod nim)", None)
    car = books["postoj karawan"]
    if car:
        n = len(car)
        left = tot(car, r"wyjazdy z miast tej doby (\d+):")
        hrs = sum((num(r"wyjazdy z miast tej doby (\d+):", s, int, 0) or 0) * (fnum(r"postoj srednio ([0-9.]+) h", s) or 0.0) for s in car.values())
        rep.add("P3-3: postoj karawan AI w miastach (stan przed E8/G1)",
                (f"sredni postoj {hrs / left:.1f} h z {left} wyjazdow" if left else "brak wyjazdow z wjazdem w pamieci"), "INFO (prog G1-2 po E8/G1: <= 12 h)", None)
        enter, long7, unk = tot(car, r"wjazdy do miast tej doby (\d+)"), tot(car, r", 7\+ dob (\d+) \|"), tot(car, r"nowa karawana\) (\d+)")
        c_town, c_all, c_idle = lastn(car, r"w miastach teraz (\d+)"), lastn(car, r"karawany AI swiata (\d+)"), lastn(car, r"h, 7\+ dob (\d+)\)")
        rep.add("P3-3: karawany AI - wyjazdy i stojace",
                f"wyjazdy {left / n:.1f}/dobe, wjazdy {enter / n:.1f}/dobe; wyjazdy po 7+ dobach {long7}; ostatnia doba: w miastach "
                f"{c_town} z {c_all}, stoja 7+ dob {c_idle}; wyjazdy bez wjazdu w pamieci {unk}", "INFO (Z33: 29 karawan bez statkow 7+ dob w tym samym miescie)", None)
    mer = books["najemnicy BK"]
    if mer:
        n = len(mer)
        h, a = tot(mer, r"bohaterow zamienionych na zolnierza z niczego (\d+)"), tot(mer, r"ludzi dosypanych z niczego (\d+)")
        calls = tot(mer, r"wywolan (\d+) \(w sluzbie")
        wired = "wpieta" if "prefiks SpoilsCompany): wpieta" in mer[max(mer)] else "BRAK"
        m_cl, m_in, m_men = lastn(mer, r"bez klanu Spoils\) (\d+)"), lastn(mer, r"w sluzbie krolestwa (\d+)"), lastn(mer, r"druzyn \d+, ludzi (\d+)")
        rep.add("P3-3: zamiana BK u klanow najemnikow (stan przed E8/G2)",
                f"bohaterow zamienionych {h} ({h / n:.2f}/dobe), ludzi dosypanych {a} ({a / n:.2f}/dobe), wywolan {calls / n:.1f}/dobe; ostatnia doba: klanow "
                f"{m_cl} (w sluzbie {m_in}), ludzi {m_men}; latka {wired}", "INFO (prog G2-1 po E8/G2: 0 i 0)", None)
    if seg:
        n = len(seg)
        fu, fv = tot(seg, r"razy, (\d+) szt\. zywnosci"), tot(seg, r"zywnosci wartej (\d+)")
        fc, dr, bg = tot(seg, r"\(FinancialCompromise\) \d+ razy / (\d+) zl"), tot(seg, r"\(DrainGold\) \d+ razy / (\d+) zl"), tot(seg, r"\(BuyGoods\) \d+ razy / (\d+) zl")
        fn = tot(seg, r"\(GiveFood\) (\d+) razy")
        rep.add("P3-3: zrodla i ujscia BK bez platnika (suma okna; na dobe)",
                f"zywnosc band hersztow {fn} razy / {fu} szt. warte {fv} ({fv / n:.0f}/d); ugoda z grupa interesu {fc} zl"
                f"; zloto dworzan {dr} zl ({dr / n:.0f}/d); zakupy laski dworu {bg} zl ({bg / n:.0f}/d)", "INFO (kod po liczbach - decyzja po tescie)", None)
    sh = books["owce"]
    if sh:
        n = len(sh)
        wool = sum(fnum(r"szt\./d, welna ([0-9.]+) szt\./d", s) or 0.0 for s in sh.values()) / n
        gw, uw = tot(sh, r"welna \d+ szt\. / (\d+) zl"), tot(sh, r"zl; welna (\d+) szt\.")
        gs, gm, go = tot(sh, r"owce \d+ szt\. / (\d+) zl"), tot(sh, r"mieso \d+ szt\. / (\d+) zl"), tot(sh, r"inne towary \d+ szt\. / (\d+) zl")
        s_vil, s_herd, s_wool = lastn(sh, r"wsi owczych \(sheep_farm\) (\d+)"), lastn(sh, r"owiec w magazynach wsi (\d+)"), lastn(sh, r"welna: w magazynach wsi (\d+)")
        rep.add("P3-3: owce - wsie owcze, stada, welna, utarg wozow",
                f"wsi {s_vil}, owiec w magazynach {s_herd}, welny w magazynach "
                f"{s_wool} (ostatnia doba); welna wedlug modelu {wool:.1f} szt./d; utarg wozow na dobe: welna {gw / n:.0f} zl"
                f" ({uw / n:.1f} szt.), owce {gs / n:.0f} zl, mieso {gm / n:.0f} zl, inne {go / n:.0f} zl", "INFO (stan przed welna z uboju E8/B)", None)
    od = books["rozkazy morskie"]
    if od:
        g, dif = tot(od, r"rozkaz oddawany o swicie (\d+)"), tot(od, r"INNA niz przed snem (\d+)")
        rep.add("P3-3: rozkazy partii ze statkami - po switcie inna droga niz przed snem (RememberOrder bez drogi i portu)",
                (f"{dif} z {g} oddawanych ({100.0 * dif / g:.1f}%)" if g else "brak rozkazow partii ze statkami"), "INFO (kod tylko przy rozjezdzie)", None)
    ue = [x for x in lines if x.startswith("Underequipped (E8/P3): dzien")]
    if ue:
        def us(rx):
            return sum(num(rx, s, int, 0) or 0 for s in ue)
        p0, p1, p2 = us(r"druzyna gracza [^|]*kara 0: (\d+)"), us(r"druzyna gracza [^|]*2-10: (\d+)"), us(r"druzyna gracza [^|]*12-20: (\d+)")
        e0, e1, e2 = us(r"przeciwnik [^|]*kara 0: (\d+)"), us(r"przeciwnik [^|]*2-10: (\d+)"), us(r"przeciwnik [^|]*12-20: (\d+)")
        rep.add("P3-3: kara Underequipped DTE po bitwach gracza (kara 0 / 2-10 / 12-20)",
                f"misji {len(ue)}: druzyna gracza {p0} / {p1} / {p2}; przeciwnik (tylko oznaczeni) {e0} / {e1} / {e2}", "INFO (8.16 - bitwa gracza)", None)
    else:
        rep.add("P3-3: kara Underequipped DTE po bitwach gracza", "brak linii (autotest nie gra bitew gracza)", "INFO (8.16 - bitwa gracza)", None)
    ks = books["koszt"]
    if ks:
        cs = [fnum(r"koszt linii ([0-9.]+) ms", s) for s in ks.values()]
        cs = [c for c in cs if c is not None]
        if cs:
            rep.add("P3-3: koszt linii pomiarow swiata", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms", "INFO (cel projektu < 10 ms/dobe)", None)
        sm = tot(ks, r"potkniecia dzis (\d+)")
        errs = sum(1 for x in lines if x.startswith("ERROR in Stage8World."))
        rep.add("P3-K: kontrola (potkniecia pomiarow, linie ERROR in Stage8World.*)", f"{sm} / {errs}", "0 / 0", sm == 0 and errs == 0)


# E8/S (246): blok etap8_s - porzadek stanu (StateHygiene.cs)
E8_S = "Porzadek stanu (E8/S): "
E8_S_DAY = "Porzadek stanu (E8/S): dzien"


def etap8_s(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/S (246, projekt etapu 8 v2 rozdz. 3 "E8/S" Test): porzadek stanu (StateHygiene.cs). Bieg "nowa kampania -> zapis -> wczytanie innego zapisu
    w tej samej sesji" (procedura "zapis 9 dob") daje w JEDNYM logu co najmniej dwie linie startu - blok czyta log po kolei, nie po numerach dob
    (druga kampania moze miec te same doby), i nie uzywa okna --do-doby.
    S-1 stajnie AI kupuja w pierwszej dobie po wczytaniu: "znacznik z przyszlosci" 0 w kazdej linii doby calego logu, a po OSTATNIEJ linii startu
    (przy >= 2 startach) zakupy > 0 w pierwszych dwoch liniach doby (pierwsza obejmuje niepelna dobe); jeden start w logu albo zero zakupow - INFO;
    S-2 linia startu przy kazdym starcie sesji (tyle, ile linii "Jedna skala czasu (E7/C): odwet kryjowek"): "wyzerowane 5 klas", potkniecia
    zerowania 0; WYLACZONE albo UWAGA = NIE;
    S-3 klimat: potkniecia 0 (brak linii "ERROR in WesterosClimate.Init") albo ponowione i czynne (w kazdej sesji z potknieciem ostatnia linia doby
    ma "czynny tak");
    S-K linie "ERROR in StateHygiene*" 0 i potkniecia linii 0; INFO - co bylo w pamieci przy kazdym starcie, kryjowka, martwe wpisy obozu, stajnie."""
    idx = [i for i, s in enumerate(lines) if s.startswith(E8_S) and not s.startswith(E8_S_DAY)]
    days = [(i, s) for i, s in enumerate(lines) if s.startswith(E8_S_DAY)]
    if not idx and not days:
        rep.add("E8/S: linie Porzadek stanu (E8/S)", "brak w logu", "sa od wgrania E8/S (StateHygieneEnabled)", None)
        return

    def tot(rows, rx):
        return sum(num(rx, s, int, 0) or 0 for s in rows)
    all_days = [s for _, s in days]
    # ---------------- S-2: linia startu
    ref = sum(1 for s in lines if s.startswith("Jedna skala czasu (E7/C): odwet kryjowek"))
    bad = []
    for i in idx:
        s = lines[i]
        if "WYLACZONE" in s or "UWAGA" in s or num(r"wyzerowane (\d+) klas", s) != 5 or num(r"potkniecia zerowania (\d+)", s) != 0:
            bad.append(s[len(E8_S):len(E8_S) + 90])
    ok2 = bool(idx) and not bad and (ref == 0 or len(idx) == ref)
    rep.add("S-2: linia startu przy kazdym starcie sesji (wyzerowane 5 klas, potkniecia zerowania 0)",
            f"linii startu {len(idx)}, startow sesji wedlug linii E7/C {ref if ref else '?'}" + (f"; zle: {bad[:2]}" if bad else ""),
            "kazdy start: wyzerowane 5 klas, potkniecia zerowania 0", ok2)
    # ---------------- S-1: stajnie AI po wczytaniu
    fut = tot(all_days, r"znacznik z przyszlosci (\d+)")
    if len(idx) >= 2:
        after = [s for i, s in days if i > idx[-1]]
        buys2 = tot(after[:2], r"stajnie AI: zakupy (\d+)")
        had = num(r"stajnie AI \(wpisy\) (\d+)", lines[idx[-1]])
        val = (f"startow {len(idx)}; przy ostatnim starcie w pamieci {had if had is not None else '?'} wpisow stajni; po nim linii doby {len(after)}, zakupy w pierwszych dwoch {buys2}"
               f"; znacznik z przyszlosci w calym logu {fut}")
        ok1 = False if fut > 0 else (True if buys2 > 0 else None)
        if not after:
            val += " (brak linii doby po ostatnim starcie - bieg za krotki)"
    else:
        val = f"jeden start sesji w logu - bieg \"nowa kampania -> zapis -> wczytanie innego zapisu\" nie byl grany; znacznik z przyszlosci {fut}"
        ok1 = False if fut > 0 else None
    rep.add("S-1: stajnie AI kupuja w pierwszej dobie po wczytaniu (bez znacznika zakupu z innej kampanii)", val,
            "znacznik z przyszlosci 0 i zakupy > 0 po ostatnim starcie (>= 2 starty w logu)", ok1)
    # ---------------- S-3: klimat - potkniecia 0 albo ponowione i czynne (osobno w kazdej sesji logu)
    cuts = idx + [len(lines)]
    segs = [(cuts[k], cuts[k + 1]) for k in range(len(idx))] or [(0, len(lines))]
    n_err, dead = 0, 0
    for a, b in segs:
        e = sum(1 for s in lines[a:b] if s.startswith("ERROR in WesterosClimate.Init"))
        if e == 0:
            continue
        n_err += e
        seg_days = [s for i, s in days if a <= i < b]
        if not seg_days or "czynny tak" not in seg_days[-1]:
            dead += 1
    last = all_days[-1] if all_days else ""
    st = re.search(r"klimat: (potkniecia \d+/3, ponowien \d+, czynny \w+)", last)
    rep.add("S-3: klimat - potkniecia startu 0 albo ponowione i czynne",
            f"linii ERROR in WesterosClimate.Init {n_err}, sesji z potknieciem bez czynnego klimatu na koncu {dead}; ostatnia doba: {st.group(1) if st else '?'}",
            "0 potkniec albo po ponowieniu \"czynny tak\"", (dead == 0) if (all_days or n_err == 0) else None)
    # ---------------- S-K i INFO
    errs = sum(1 for s in lines if s.startswith("ERROR in StateHygiene"))
    sm = max([num(r"potkniecia linii (\d+)", s, int, 0) or 0 for s in all_days] or [0])
    rep.add("S-K: kontrola (linie ERROR in StateHygiene*, potkniecia linii doby)", f"{errs} / {sm}", "0 / 0", errs == 0 and sm == 0)
    mem = []
    for i in idx:
        m = re.search(r"bylo: (.*?) \| potkniecia zerowania", lines[i])
        mem.append(m.group(1) if m else "?")
    rep.add("E8/S: w pamieci po poprzedniej kampanii przy kolejnych startach sesji", " || ".join(mem[:4]) if mem else "-",
            "INFO (pierwszy start po uruchomieniu gry: same 0; po wczytaniu w tej samej sesji zwykle > 0 - to zostalo wyzerowane)", None)
    if all_days:
        b_all, h_all = tot(all_days, r"stajnie AI: zakupy (\d+)"), tot(all_days, r"wizyty w przerwie zakupow (\d+)")
        hs, hg, do = tot(all_days, r"potkniecia przeszukania (\d+)"), tot(all_days, r"porzucone (\d+)"), tot(all_days, r"dluznikom w osadzie (\d+)")
        rep.add("E8/S: stajnie AI, kryjowka, oboz (suma linii doby)",
                f"zakupy stajni {b_all}, wizyty w przerwie zakupow {h_all}; kryjowka: potkniecia przeszukania {hs}, porzucone {hg}"
                f"; martwe wpisy obozu zdjete dluznikom w osadzie {do}", "INFO", None)


# E8/Q (262): blok etap8_q - straz przeprawy na zegarze gry (CrossingLaw.cs)
E8_Q_DAY = "Straz przeprawy (E8/Q): dzien"


def etap8_q(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/Q (262, projekt etapu 8 v2 rozdz. 3 "E8/Q" Test): petla AI strazy przeprawy na zegarze gry (CrossingLaw.AiHourly). Linia doby
    "Straz przeprawy (E8/Q): dzien N" (dzien = doba gry, jak "Przeprawa Bliznaki (E7/B)"; "Pieniadz swiata" nosi dzien ksiegi = doba gry - 1).
    Q-0 linia z licznikiem (zegar gry TAK, przebiegi > 0) w kazdej dobie okna - WYLACZONE albo doba bez przebiegow = NIE;
    Q-1 INFO: zawrocone N (N/d) wedlug przeprawy, wrogie partio-godziny przy przeprawach i w strefie (> 0 zawrocen dopiero przy wojnie z panem przeprawy);
    Q-2 koszt <= 5 ms/dobe (srednio i najdrozsza doba);
    Q-3 zadna partia zawracana > 3 razy na dobe (suma "partii zawroconych ponad 3 razy" w oknie = 0; zakleszczenie);
    Q-4 INFO: szczelnosc przy Bliznakach - wrogich lordow przez most (licznik E7/B) wobec zawrocen przy ROT_town3, w tym w ciagu 3 h po zawroceniu;
    Q-5 INFO: partie w strefie bez rozkazu (spiacy, przerwa 3 h, oblezenie, eskorty, osada / bitwa, woda, AI wylaczone, brak punktu na ladzie), punkt odwrotu;
    Q-K potkniecia 0 i linie "ERROR in CrossingLaw.*" 0."""
    rows = {}
    for d, s in by_day(lines, E8_Q_DAY).items():
        rd = run_day(d, start)
        if 1 <= rd <= until:
            rows[rd] = s
    if not rows:
        rep.add("E8/Q: linie Straz przeprawy (E8/Q)", "brak w logu", "sa od wgrania E8/Q (CrossingLawAiClock, LogEnabled)", None)
        return
    days = sorted(rows)
    off = [x for x in days if "WYLACZONE" in rows[x]]
    live = [x for x in days if "| zegar gry TAK" in rows[x] and (num(r"\| przebiegi (\d+),", rows[x], int, 0) or 0) > 0]
    need = max(0, len(win) - 1)
    val = f"{len(live)} dob z przebiegami (wszystkich linii {len(days)}; dob okna {len(win)})"
    if off:
        why = re.search(r"WYLACZONE \((.*?)\)", rows[off[0]])
        val += f"; WYLACZONE w {len(off)} dobach ({why.group(1)[:60] if why else '?'})"
    rep.add("Q-0: linia Straz przeprawy z licznikiem (zegar gry TAK, przebiegi > 0)", val,
            f">= {need} (codziennie w oknie; dzien gry = dzien ksiegi + 1), WYLACZONE 0", (not off and len(live) >= need and need > 0) if win else None)
    if not live:
        return
    w = [rows[x] for x in live]

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    # ---------------- Q-1: zawrocone (INFO)
    turned = tot(r"\| zawrocone (\d+) \(")
    per = {}
    for x in w:
        m = re.search(r"\| zawrocone \d+ \((.*?); punkt odwrotu", x)
        if m:
            for name, v in re.findall(r"(\S+) (\d+)", m.group(1)):
                per[name] = per.get(name, 0) + int(v)
    near, zone = tot(r", wrogich przy przeprawach (\d+) partio-godzin"), tot(r"partio-godzin, w strefie (\d+)")
    seen = _mean([num(r"\(srednio (\d+) na przebieg\)", x) for x in w])
    miss = [x for x in live if num(r"; przeprawy (\d+)/", rows[x]) != num(r"; przeprawy \d+/(\d+)\)", rows[x])]
    v1 = f"{turned} ({turned / len(w):.2f}/d): " + (", ".join(f"{k} {v}" for k, v in per.items()) if per else "-")
    v1 += f"; wrogich przy przeprawach {near} partio-godzin, w strefie {zone}"
    if seen is not None:
        v1 += f"; partii lordow na przebieg srednio {seen:.0f}"
    rep.add("Q-1: zawrocone partie lordow (suma okna)", v1,
            "INFO (> 0 dopiero przy wojnie z panem przeprawy - np. z Freyami; 0 wrogich w strefie = nie bylo kogo zawracac)", None)
    if miss:
        rep.add("Q-1b: przeprawy znalezione po id (ROT_town3, castle_B1, castle_EN2)", f"brak osady w {len(miss)} dobach (pierwsza d{miss[0]})", "3/3", False)
    # ---------------- Q-2: koszt
    cost = [num(r"\| koszt ([\d.]+) ms/dobe", x, float) for x in w]
    cm = _mean(cost)
    cx = max([c for c in cost if c is not None] or [0.0])
    rep.add("Q-2: koszt petli godzinnej", f"srednio {cm:.3f} ms/dobe, najdrozsza doba {cx:.3f} ms" if cm is not None else "brak liczby w linii",
            "<= 5 ms/dobe (srednio i najdrozsza doba)", (cm <= 5.0 and cx <= 5.0) if cm is not None else None)
    # ---------------- Q-3: zakleszczenie
    over = tot(r"partii zawroconych ponad 3 razy (\d+)")
    worst, who, wd = 0, "-", None
    for x in live:
        m = re.search(r"najwiecej zawrocen jednej partii (\d+) \((.*?)\)", rows[x])
        if m and int(m.group(1)) > worst:
            worst, who, wd = int(m.group(1)), m.group(2), x
    rep.add("Q-3: zadna partia zawracana ponad 3 razy na dobe (zakleszczenie)",
            f"partio-dob ponad 3 zawrocenia: {over}; najwiecej {worst}" + (f" ({who}, d{wd})" if wd is not None else ""), "0", over == 0)
    # ---------------- Q-4, Q-5: INFO
    cross, cool = tot(r"wrogich lordow przez most (\d+) \("), tot(r"\(w ciagu 3 h po zawroceniu (\d+)\)")
    tw = per.get("ROT_town3", 0)
    dead = sum(1 for x in w if "(licznik E7/B): nieczynny" in x)
    rep.add("Q-4: szczelnosc przy Bliznakach - wrogich lordow przez most (licznik E7/B) wobec zawrocen",
            f"przez most {cross} (w ciagu 3 h po zawroceniu {cool}), zawrocone przy ROT_town3 {tw}" + (f"; licznik E7/B nieczynny w {dead} z {len(w)} dob" if dead else ""),
            "INFO (przejscia mimo strazy: przerwa 3 h po zawroceniu, armie w drodze na oblezenie, eskorty; decyzja po tescie)", None)
    skip = (("spiacy", r"spiacy (\d+),"), ("w przerwie 3 h", r"w przerwie 3 h (\d+),"), ("oblezenie przeprawy", r"oblezenie przeprawy (\d+),"),
            ("eskorty armii", r"eskorty armii (\d+),"), ("w osadzie albo bitwie", r"w osadzie albo bitwie (\d+),"), ("na wodzie", r"na wodzie (\d+),"),
            ("AI wylaczone", r"AI wylaczone (\d+),"), ("bez punktu na ladzie", r"bez punktu na ladzie (\d+) "))
    back = (("skad przyszla", r"skad przyszla (\d+) /"), ("prosto od zamku", r"prosto od zamku (\d+)\)"))
    rep.add("Q-5: partie w strefie bez rozkazu i punkt odwrotu (suma okna, partio-godziny)",
            ", ".join(f"{k} {tot(p)}" for k, p in skip) + "; punkt odwrotu: " + ", ".join(f"{k} {tot(p)}" for k, p in back), "INFO", None)
    # ---------------- Q-K
    stu = tot(r"potkniecia dzis (\d+)")
    errs = sum(1 for s in lines if s.startswith("ERROR in CrossingLaw."))
    rep.add("Q-K: kontrola (potkniecia petli, linie ERROR in CrossingLaw.*)", f"{stu} / {errs}", "0 / 0", stu == 0 and errs == 0)


# E8/G1 (260): blok etap8_g1 - karawany: BK w miescie co godzine i wyspy bez drogi (CaravanFlow.cs)
E8_G1_DAY = "Karawany (E8/G1): dzien"
E8_G1_Z33_TOWNS = 10264881      # suma kas miast w dobie 120 biegu Z33 (WGRANIE 33, linia "Nadwyzka kas (E5/0)")
E8_G1_Z33_CARAVANS = 4076294    # kiesy karawan w dobie 120 biegu Z33 (linia "Pieniadz swiata": partie bez wodza - karawany; 902 karawany notabli i 57 lordow)
E8_G1_Z33_CARAVAN_COUNT = 962   # karawany w dobie 120 biegu Z33 (linia "Karawany (stan): dzien 108955 - miast 97, karawan 962", L:35944) - mianownik G1-5c
# recenzja E8/G1: dowoz surowca kontraktami (174.2) bierze przewoznika sposrod karawan STOJACYCH w miescie-zrodle - przy postoju ok. 3 h stoi ich kilkanascie razy mniej
E8_G1_Z33_ORE_TOWNS = 25.8      # miasta bez rudy w biegu Z33, srednia probek dob 91-120 (linia "Miasta bez rudy i strzal (174b)" co 5 dob: 29, 31, 29, 19, 25, 22)
E8_G1_Z33_CONTRACTS = 12.7      # kontrakty surowca zawarte na dobe w biegu Z33 (linia "Kontrakty surowca (174)", doby 1-120)
E8_G1_Z33_NOCAR = 74.0          # zamowienia bez kontraktu z powodu "brak karawany w zrodle" na dobe w biegu Z33 (ta sama linia)


def etap8_g1(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/G1 (260, projekt etapu 8 v2 rozdz. 3 "E8/G1" Test; odpowiedz Jeffa 3: TAK): karawany BK w miescie co godzine (postfiks na prefiksie BKROT) i wyspy
    bez drogi (zakup lorda pominiety, karawana bez drogi rozwiazana). Linia doby "Karawany (E8/G1): dzien N" (dzien ksiegi, jak "Postoj karawan (E8/P3)").
    G1-0 latki wpiete N/N, linia w kazdej dobie okna (bez pierwszej i ostatniej), oba klucze czynne, spis slepych zaulkow mapy najwyzej 25% osad (kontrola
    reguly - pamiec drog zna pary wies - miasto);
    G1-1 karawany bez statkow 7+ dob w tym samym miescie <= 10 w ostatniej dobie okna (linia "Wyspy i drogi"; Z33: 29);
    G1-2 sredni postoj karawan AI w miescie <= 12 h (linia "Postoj karawan (E8/P3)", srednia wazona wyjazdami okna);
    G1-3 karawany bez drogi na koniec biegu 0 ("zostalo" w ostatniej linii), ponowne rozwiazania u tego samego wlasciciela 0, nieudane 0;
    G1-4 koszt dodatkowych tikow BK srednio <= 2.2 ms x nowy cel + 150 ms/dobe (TRIAZ-2: czas brutto otwartych tikow zawiera nieunikniona decyzje wyjazdu BK);
    G1-5 (prog, nie INFO): suma kas miast w dobie 120 >= 80% i <= 110% Z33 (TRIAZ-2: prog projektu, jak C-4a), kasy ponizej zapasu przez nasza wyplate 0, kiesy karawan NA KARAWANE w dobie 120 w +-20% Z33 (TRIAZ-2)
    (bieg krotszy niz 120 dob - INFO); wizyty i zakupy karawan - INFO;
    G1-6 (recenzja - regresja dowozu surowca 174.2: przewoznikiem kontraktu jest karawana STOJACA w miescie-zrodle, a po E8/G1 stoi ich wielokrotnie mniej):
    G1-6a miasta bez rudy, srednia probek dob 91-120 <= 1.25 x Z33 (bieg krotszy - INFO); G1-6b INFO kontrakty zawarte i "brak karawany w zrodle" na dobe
    wobec Z33, karawany stojace w miastach;
    G1-K potkniecia i linie "ERROR in CaravanFlow.*" 0."""
    rows = {d: s for d, s in by_day(lines, E8_G1_DAY).items() if 1 <= run_day(d, start) <= until}
    wire = [x for x in lines if x.startswith("Karawany (E8/G1): latki przy starcie gry")]
    if not rows and not wire:
        rep.add("E8/G1: linie Karawany (E8/G1)", "brak w logu", "sa od wgrania E8/G1 (CaravanFlow.cs)", None)
        return
    # ---------------- G1-0: latki, linia, klucze, spis slepych zaulkow
    if wire:
        w0 = wire[-1]
        a, b = num(r"wpiete (\d+)/\d+", w0), num(r"wpiete \d+/(\d+)", w0)
        rep.add("G1-0: latki (postfiks na prefiksie BKROT, pomiar tiku BK, zakup karawany lorda BK)", w0[:200],
                "wpiete N/N, BRAK: -", a is not None and b is not None and a == b and "; BRAK: - |" in w0)
    else:
        rep.add("G1-0: latki", "brak linii startowej", "wpiete N/N", False)
    if not rows:
        rep.add("G1-0b: linia Karawany (E8/G1)", "brak linii doby", "codziennie w oknie", False)
        return
    days = sorted(rows)
    w = [rows[d] for d in days]
    last = rows[days[-1]]
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rows]
    off_h = [d for d in days if "(Caravan Town Hourly WYLACZONE)" in rows[d]]
    off_i = [d for d in days if "(Island Caravan Fix WYLACZONE)" in rows[d]]
    val = f"linii {len(days)}, dob okna {len(inner)}" + (f", brak w {len(miss)} (doby {miss[:5]})" if miss else ", komplet")
    if off_h:
        val += f"; Caravan Town Hourly WYLACZONE w {len(off_h)} dobach"
    if off_i:
        val += f"; Island Caravan Fix WYLACZONE w {len(off_i)} dobach"
    rep.add("G1-0b: linia Karawany (E8/G1) w kazdej dobie okna, oba klucze czynne", val,
            "komplet (bez pierwszej i ostatniej doby), WYLACZONE 0", (not miss and not off_h and not off_i) if inner else None)
    cen = re.search(r"slepe zaulki mapy dla karawany bez statkow \(raz na sesje\): miasta (\d+), zamki (\d+), wsie (\d+) z (\d+) osad", last)
    if cen:
        ct, cc, cv, ca = (int(x) for x in cen.groups())
        share = 100.0 * (ct + cc + cv) / ca if ca else 0.0
        rep.add("G1-0c: slepe zaulki mapy (osady bez drogi ladowej do dwoch miast) - kontrola reguly zakupu",
                f"miasta {ct}, zamki {cc}, wsie {cv} z {ca} osad ({share:.1f}%)", "<= 25% osad (wiecej = pamiec drog nie zna par osad - zakup lordow blokowany na ladzie)",
                share <= 25.0)
    else:
        bad = re.search(r"slepe zaulki mapy dla karawany bez statkow \(raz na sesje\): (.*?) \| latki", last)
        rep.add("G1-0c: slepe zaulki mapy - kontrola reguly zakupu", bad.group(1)[:120] if bad else "brak w linii", "spis pelny, <= 25% osad", False)

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    n = len(w)
    # ---------------- G1-1: karawany 7+ dob w tym samym miescie
    isl = {d: s for d, s in by_day(lines, "Wyspy i drogi (").items() if 1 <= run_day(d, start) <= until}
    p3 = {d: s for d, s in by_day(lines, "Postoj karawan (E8/P3): dzien").items() if 1 <= run_day(d, start) <= until}
    if isl:
        li = isl[max(isl)]
        idle = num(r"w tym samym miescie od 7\+ dob \(kazde miasto, probka dobowa\): (\d+)", li)
        where = re.search(r"probka dobowa\): \d+( \[.*?\])", li)
        p3idle = num(r"h, 7\+ dob (\d+)\)", p3[max(p3)], int, None) if p3 else None
        rep.add("G1-1: karawany bez statkow 7+ dob w tym samym miescie (ostatnia doba okna, linia Wyspy i drogi)",
                ((f"{idle}" + (where.group(1) if where else "")) if idle is not None else "brak liczby w linii")
                + (f"; wszystkie karawany AI z wjazdem w pamieci (E8/P3) 7+ dob: {p3idle}" if p3idle is not None else ""),
                "<= 10 (Z33: 29; licznik postoju zeruje sie przy wczytaniu - bieg bez wczytania w ostatnich 7 dobach)", (idle <= 10) if idle is not None else None)
    else:
        rep.add("G1-1: karawany bez statkow 7+ dob w tym samym miescie", "brak linii Wyspy i drogi", "<= 10", None)
    # ---------------- G1-2: sredni postoj w miescie
    if p3:
        left = sum(num(r"wyjazdy z miast tej doby (\d+):", s, int, 0) or 0 for s in p3.values())
        hrs = sum((num(r"wyjazdy z miast tej doby (\d+):", s, int, 0) or 0) * (fnum(r"postoj srednio ([0-9.]+) h", s) or 0.0) for s in p3.values())
        rep.add("G1-2: sredni postoj karawan AI w miescie (linia Postoj karawan (E8/P3), srednia wazona wyjazdami)",
                (f"{hrs / left:.1f} h z {left} wyjazdow ({left / len(p3):.1f}/dobe)" if left else "brak wyjazdow z wjazdem w pamieci"),
                "<= 12 h (przed E8/G1 ok. 3 doby)", (hrs / left <= 12.0) if left else None)
    else:
        rep.add("G1-2: sredni postoj karawan AI w miescie", "brak linii Postoj karawan (E8/P3) - Stage8WorldLog wylaczony?", "<= 12 h", None)
    # ---------------- G1-3: karawany bez drogi
    left_now = num(r", zostalo (\d+) \(w cieniu", last)
    done, again, fail = tot(r", rozwiazane (\d+)"), tot(r"ponowne u tego samego wlasciciela (\d+)"), tot(r"nie zniknely mimo rozkazu (\d+)")
    skip, ask = tot(r"zakup pominiety (\d+)"), tot(r"BK chcial kupic karawane lordowi (\d+) razy")
    why = re.search(r"; powody( \[.*?\]| -)\), ponowne", last)
    rep.add("G1-3: karawany bez drogi na koniec biegu (bez statkow w miescie bez innego miasta w zasiegu ladu)",
            (f"zostalo {left_now}" if left_now is not None else "brak liczby") + (f" (powody{why.group(1)})" if why and left_now else "")
            + f"; w oknie rozwiazane {done}, ponowne u tego samego wlasciciela {again}, nieudane {fail}; zakup karawany lorda pominiety {skip} z {ask} zamiarow BK",
            "zostalo 0, ponowne 0, nieudane 0", (left_now == 0 and again == 0 and fail == 0) if left_now is not None else None)
    ob = {d: s for d, s in by_day(lines, "Obieg: notable i karawany: dzien").items() if 1 <= run_day(d, start) <= until}
    if ob:
        bought = sum(num(r"kupione przez lordow BK (\d+)", s, int, 0) or 0 for s in ob.values())
        rep.add("G1-3c: postfiks zakupu biegnie - zamiary BK widziane przez latke wobec karawan kupionych przez lordow (ksiega obiegu)",
                f"zamiary {ask}, pominiete {skip}, kupione wedlug ksiegi {bought}", "zamiary - pominiete >= kupione (0 zamiarow przy zakupach = latka omijana)",
                (ask - skip >= bought) if (ask or bought) else None)
    if done:
        sold_u, sold_g = tot(r"towar sprzedany miastu (\d+) szt\."), tot(r"szt\. za (\d+) zl z nadwyzki kasy")
        uns_u, uns_v = tot(r"niesprzedane (\d+) szt\."), tot(r"szt\. warte (\d+) zl")
        purse, got = tot(r"kiesa z utargiem (\d+) zl"), tot(r"wlascicielom przybylo (\d+)\)")
        men, mp = tot(r"\), ludzie (\d+) \(do domu"), tot(r"sakiewki ludzi (\d+) zl")
        rep.add("G1-3b: rozwiazane karawany - dokad poszedl dobytek (suma okna)",
                f"towar miastu {sold_u} szt. za {sold_g} zl, niesprzedane na polke {uns_u} szt. warte {uns_v} zl; kiesa z utargiem {purse} zl (wlascicielom przybylo {got})"
                f"; ludzie do domu {men}; sakiewki ludzi do kas miast {mp} zl", "INFO (kiesa = przybylo, gdy wlasciciel zyje)", None)
    # ---------------- G1-4: koszt dodatkowych tikow
    cost = [fnum(r"koszt dodatkowych tikow ([0-9.]+) ms/dobe", x) for x in w]
    cm = _mean(cost)
    cx = max([c for c in cost if c is not None] or [0.0])
    opened, ran, orders = tot(r" - otwarte (\d+) u "), tot(r"po otwarciu: tiki BK (\d+)"), tot(r"nowy cel karawany (\d+)")
    # narzedzie progow p2 (TRIAZ-2 "G1-4 prog" i G1-4 "Poprawka ostateczna" pkt 4): stoper mierzy czas BRUTTO otwartych tikow, a w nim nieunikniona
    # decyzje BK przy kazdym wyjezdzie (zakup + wybor celu: 1.73 ms na nowy cel, regresja 118 dob R2 0.98; biegi bez E8/G1 placily to samo za swoje
    # 123-135 wyjazdow/d, tylko nikt tego nie mierzyl). "<= 5 ms/d" to 3 wyjazdy na dobe - prog zakladal, ze tik BK w miescie jest darmowy.
    # Nowy prog: srednio <= 2.2 ms x nowy cel + 150 ms/dobe (przy 304 wyjazdach ok. 820 ms). Bieg 2: 1411 ms wobec 820 = NIE - objaw prawdziwy:
    # 62% kosztu to tiki karawan, ktore i tak nie wyjezdzaja (704/d ponad 24 tiki w postoju) - czeka na limit otwartych tikow na postoj (G1b).
    lim4 = 2.2 * orders / n + 150.0
    rep.add("G1-4: koszt dodatkowych tikow BK karawan w miescie (czas brutto otwartych tikow)",
            (f"srednio {cm:.2f} ms/dobe, najdrozsza doba {cx:.2f} ms" if cm is not None else "brak liczby w linii")
            + f"; otwarte {opened / n:.0f}/dobe, nowy cel {orders / n:.1f}/dobe"
            + (f" = {cm * n / orders:.2f} ms na nowy cel (sama decyzja wyjazdu BK ok. 1.7 ms)" if (cm is not None and orders > 0) else ""),
            f"srednio <= 2.2 ms x nowy cel + 150 ms/dobe = {lim4:.0f} ms (decyzja wyjazdu BK jest nieunikniona; NIE = tiki karawan, ktore nie wyjezdzaja - "
            "limit otwartych tikow na postoj, TRIAZ-2 G1-4)", (cm <= lim4) if cm is not None else None)
    # G1-4b czyta opis sprzed limitu postoju ("w tym ponad 24 tiki w tym samym postoju: N tikow u M karawan (bez celu albo ranni)"); po poprawce G1b linia
    # ma inny opis (tiki zamkniete po limicie) - wtedy wiersz mowi to wprost, zamiast liczyc cudze pole jako "otwarte bez skutku"
    old4 = [x for x in w if "ponad 24 tiki w tym samym postoju" in x]
    if old4:
        lng = sum(num(r"ponad 24 tiki w tym samym postoju: (\d+) tikow", x, int, 0) or 0 for x in old4)
        lngc = _mean([num(r"tikow u (\d+) karawan \(bez celu", x) for x in old4])
        rep.add("G1-4b: otwarte tiki bez skutku - ponad 24 tiki w tym samym postoju (karawany bez celu albo ranni)",
                f"{lng / len(old4):.0f} tikow/dobe" + (f" u srednio {lngc:.1f} karawan" if lngc is not None else "") + f"; tiki BK po otwarciu {ran / n:.0f}/dobe"
                + (f" ({len(old4)} z {n} dob z tym opisem)" if len(old4) < n else ""),
                "INFO (cel po limicie otwartych tikow na postoj: 0 - TRIAZ-2 G1-4)", None)
    else:
        rep.add("G1-4b: otwarte tiki bez skutku - ponad 24 tiki w tym samym postoju",
                f"brak opisu 'ponad 24 tiki w tym samym postoju' w linii doby (linia po limicie postoju G1b ma inny opis); tiki BK po otwarciu {ran / n:.0f}/dobe",
                "INFO (wiersz do dopasowania do nowego opisu linii po scaleniu poprawki G1b)", None)
    # ---------------- G1-5: ekonomia (prog)
    full = bool(win) and run_day(win[-1], start) >= 120
    nk = {d: s for d, s in by_day(lines, "Nadwyzka kas (E5/0): dzien").items() if 1 <= run_day(d, start) <= until}
    if nk:
        tg = num(r"\| miasta \d+: kasy (-?\d+)", nk[max(nk)])
        if tg is not None:
            dev = 100.0 * (tg - E8_G1_Z33_TOWNS) / E8_G1_Z33_TOWNS
            # narzedzie progow p2 (TRIAZ-2 h "G1-5a"): wlasne +-10% bylo ciasniejsze niz prog projektu etapu 8 (rozdz. 4 pkt 5: kasy miast >= 80% i <= 110%
            # Z33 - ten sam, ktory na tej samej liczbie stosuje C-4a). Bieg 2: 84.4% - kasy nie leca bez dna (dno d60 8.10 mln, potem +5..+18 tys./d).
            rep.add("G1-5a: suma kas miast w ostatniej dobie okna wobec Z33", f"{tg} ({dev:+.1f}% wobec {E8_G1_Z33_TOWNS}; doba {run_day(max(nk), start)})",
                    ">= 80% i <= 110% Z33 w dobie 120 (prog projektu etapu 8 rozdz. 4 pkt 5, jak C-4a; bieg krotszy - INFO)", (-20.0 <= dev <= 10.0) if full else None)
    below = tot(r"kasy ponizej zapasu przez nasza wyplate (\d+)")
    rep.add("G1-5b: kasy miast ponizej zapasu przez nasza wyplate za towar rozwiazanej karawany", f"{below}", "0", below == 0)
    pw = {d: s for d, s in by_day(lines, "Pieniadz swiata: dzien").items() if 1 <= run_day(d, start) <= until}
    if pw:
        cg = num(r"partie bez wodza: tabory wsi -?\d+ \([^)]*\), karawany (-?\d+)", pw[max(pw)])
        if cg is not None:
            dev = 100.0 * (cg - E8_G1_Z33_CARAVANS) / E8_G1_Z33_CARAVANS
            # narzedzie progow p2 (TRIAZ-2 S1 pkt C, S2 pkt 3, "POZA LISTA" pkt 3): suma kies zalezy od LICZBY karawan (bieg 2: 1594 wobec 962 w Z33 -
            # stary przeciek "spiaca karawana nie liczy sie jako karawana", potrojony przez E8/G1), wiec +-20% sumy przechodzilo przy kiesie na karawane
            # o polowe chudszej (niedoplata zoldu karawan 107 tys. zl/d wobec 20-25 tys.). Wiazace: kiesa NA KARAWANE +-20% Z33 (liczba karawan z linii
            # "Karawany (stan)" tej samej doby); suma zostaje w tresci. Bez linii stanu - stara miara (suma).
            ks = {d: s for d, s in by_day(lines, "Karawany (stan): dzien").items() if 1 <= run_day(d, start) <= until}
            cn = num(r"miast \d+, karawan (\d+)", ks[max(ks)]) if ks else None
            if cn:
                per, zper = cg / cn, E8_G1_Z33_CARAVANS / E8_G1_Z33_CARAVAN_COUNT
                devp = 100.0 * (per - zper) / zper
                rep.add("G1-5c: kiesy karawan na karawane w ostatniej dobie okna wobec Z33",
                        f"{per:.0f} zl na karawane ({devp:+.1f}% wobec {zper:.0f}); karawan {cn} (Z33 {E8_G1_Z33_CARAVAN_COUNT}), suma kies {cg} ({dev:+.1f}% wobec "
                        f"{E8_G1_Z33_CARAVANS}; doba {run_day(max(pw), start)})",
                        "+-20% na karawane w dobie 120 (bieg krotszy - INFO; NIE przy nadmiarze karawan = czeka na limit karawan kupca, TRIAZ-2)",
                        (abs(devp) <= 20.0) if full else None)
            else:
                rep.add("G1-5c: kiesy karawan w ostatniej dobie okna wobec Z33", f"{cg} ({dev:+.1f}% wobec {E8_G1_Z33_CARAVANS}; doba {run_day(max(pw), start)}; brak linii Karawany (stan))",
                        "+-20% w dobie 120 (bieg krotszy - INFO)", (abs(dev) <= 20.0) if full else None)
    vis = {d: s for d, s in by_day(lines, "Karawany: dzien").items() if 1 <= run_day(d, start) <= until}
    why2 = {d: s for d, s in by_day(lines, "Karawany (przyczyny): dzien").items() if 1 <= run_day(d, start) <= until}
    info = []
    if vis:
        v_in = sum(num(r"wjazdy karawan do miast (\d+)", s, int, 0) or 0 for s in vis.values())
        info.append(f"wjazdy do miast {v_in / len(vis):.0f}/dobe (Z33 doba 120: 138)")
    if why2:
        v_buy = sum(num(r"zakup surowcow przed wyborem celu (\d+) wizyt", s, int, 0) or 0 for s in why2.values())
        info.append(f"zakup surowcow przed wyborem celu {v_buy / len(why2):.0f} wizyt/dobe (Z33 doba 120: 115)")
    if info:
        rep.add("G1-5d: wiecej handlu karawan - wizyty i zakupy (CaravanBulk)", "; ".join(info), "INFO", None)
    # ---------------- G1-6 (recenzja): dowoz surowca kontraktami (174.2) - przewoznik to karawana stojaca w zrodle
    ore = {d: s for d, s in by_day(lines, "Miasta bez rudy i strzal (174b): dzien").items() if 91 <= run_day(d, start) <= until}
    if ore:
        ov = [num(r"miast \d+; bez rudy (\d+)", ore[d]) for d in sorted(ore)]
        om = _mean(ov)
        lim = 1.25 * E8_G1_Z33_ORE_TOWNS
        rep.add("G1-6a: miasta bez rudy w dobach 91-120 (dowoz kontraktami 174.2 przy krotkim postoju karawan)",
                (f"srednio {om:.1f} z {len([x for x in ov if x is not None])} probek {[x for x in ov if x is not None]}" if om is not None else "brak liczby w linii")
                + f" (Z33: {E8_G1_Z33_ORE_TOWNS})", f"<= {lim:.1f} (1.25 x Z33; bieg krotszy niz 120 dob - INFO)",
                (om <= lim) if (full and om is not None) else None)
    mo = {d: s for d, s in by_day(lines, "Kontrakty surowca (174): dzien").items() if 1 <= run_day(d, start) <= until}
    if mo:
        made = sum(num(r" - zawarto (\d+) \[", s, int, 0) or 0 for s in mo.values())
        nocar = sum(num(r"brak karawany w zrodle (\d+)", s, int, 0) or 0 for s in mo.values())
        stand = _mean([num(r"w miastach teraz (\d+)", s) for s in p3.values()]) if p3 else None
        rep.add("G1-6b: kontrakty surowca (174.2) - przewoznikiem jest karawana stojaca w miescie-zrodle",
                f"zawarto {made / len(mo):.1f}/dobe (Z33: {E8_G1_Z33_CONTRACTS}), bez kontraktu z braku karawany w zrodle {nocar / len(mo):.1f}/dobe (Z33: {E8_G1_Z33_NOCAR})"
                + (f"; karawany AI stojace w miastach srednio {stand:.0f} (Z33 doba 120: 355)" if stand is not None else ""),
                "INFO (duzo mniej kontraktow przy G1-6a NIE = decyzja: przewoznik takze z karawan wjezdzajacych albo Caravan Town Hourly wylaczone)", None)
    # ---------------- G1-K
    stu = tot(r"potkniecia dzis (\d+)")
    errs = sum(1 for s in lines if s.startswith("ERROR in CaravanFlow."))
    rep.add("G1-K: kontrola (potkniecia, linie ERROR in CaravanFlow.*)", f"{stu} / {errs}", "0 / 0", stu == 0 and errs == 0)


# E8/G2 (261): blok etap8_g2 - najemnicy i uczta BK (MercFeast.cs)
E8_G2_DAY = "Najemnicy i uczta BK (E8/G2): dzien"


def etap8_g2(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/G2 (261, projekt etapu 8 v2 rozdz. 3 "E8/G2" Test; odpowiedz Jeffa 4: TAK): klany najemnikow bez ludzi z niczego i bez wyrzucania wodza (zamiana
    BK ConvertTroopsMercenaries robiona u nas, bez bohaterow) i uczta BK bez towaru z niczego (zakup schodzi z rynku). Linia doby "Najemnicy i uczta BK
    (E8/G2): dzien N" (dzien ksiegi, jak "Najemnicy BK (E8/P3)").
    G2-0 latki wpiete N/N i tresc metody BK zgodna ze sprawdzona (dlugosc IL), linia w kazdej dobie okna (bez pierwszej i ostatniej), oba klucze czynne;
    G2-1 bohaterowie zamienieni 0 i ludzie dosypani 0 (pomiar E8/P3 - linia "Najemnicy BK (E8/P3)", suma okna), rozjazd liczby ludzi przy zamianie 1:1 = 0,
    wywolania w cieniu 0; G2-1b zamiana czynna: wywolania klanow w sluzbie >= polowa klano-dob w sluzbie (0 przy klanach w sluzbie = latka omijana);
    G2-2 INFO wielkosc druzyn klanow (pierwsza i ostatnia doba), zolnierze zamienieni 1:1, bohaterowie zostawieni, ochotnicy z mapy gry (poza paczka);
    G2-3 uczta: towar z niczego po calosci 0 i rynek nie stracil ponad zakup (suma okna; bez zakupow w oknie - INFO); G2-3b INFO zakupy uczt;
    G2-K potkniecia i linie "ERROR in MercFeast.*" 0."""
    rows = {d: s for d, s in by_day(lines, E8_G2_DAY).items() if 1 <= run_day(d, start) <= until}
    wire = [x for x in lines if x.startswith("Najemnicy i uczta BK (E8/G2): latki przy starcie gry")]
    if not rows and not wire:
        rep.add("E8/G2: linie Najemnicy i uczta BK (E8/G2)", "brak w logu", "sa od wgrania E8/G2 (MercFeast.cs)", None)
        return
    # ---------------- G2-0: latki, tresc metody BK, linia, klucze
    if wire:
        w0 = wire[-1]
        a, b = num(r"wpiete (\d+)/\d+", w0), num(r"wpiete \d+/(\d+)", w0)
        rep.add("G2-0: latki (prefiks na BK ConvertTroopsMercenaries, metoda szansy BK, okno uczty na Feast.Automanage) i tresc metody BK", w0[:260],
                "wpiete N/N, BRAK: -, tresc BK zgodna ze sprawdzona",
                a is not None and b is not None and a == b and "; BRAK: - |" in w0 and "zgodna ze sprawdzona" in w0)
    else:
        rep.add("G2-0: latki", "brak linii startowej", "wpiete N/N", False)
    if not rows:
        rep.add("G2-0b: linia Najemnicy i uczta BK (E8/G2)", "brak linii doby", "codziennie w oknie", False)
        return
    days = sorted(rows)
    w = [rows[d] for d in days]
    first, last = rows[days[0]], rows[days[-1]]
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rows]
    off_m = [d for d in days if "(Merc Clans Real Soldiers WYLACZONE)" in rows[d]]
    off_f = [d for d in days if "(Feast No Free Goods WYLACZONE)" in rows[d]]
    val = f"linii {len(days)}, dob okna {len(inner)}" + (f", brak w {len(miss)} (doby {miss[:5]})" if miss else ", komplet")
    if off_m:
        val += f"; Merc Clans Real Soldiers WYLACZONE w {len(off_m)} dobach"
    if off_f:
        val += f"; Feast No Free Goods WYLACZONE w {len(off_f)} dobach"
    rep.add("G2-0b: linia Najemnicy i uczta BK (E8/G2) w kazdej dobie okna, oba klucze czynne", val,
            "komplet (bez pierwszej i ostatniej doby), WYLACZONE 0", (not miss and not off_m and not off_f) if inner else None)

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    n = len(w)
    # ---------------- G2-1: bohaterowie zamienieni 0, dosypani 0
    p3 = {d: s for d, s in by_day(lines, "Najemnicy BK (E8/P3): dzien").items() if 1 <= run_day(d, start) <= until}
    drift, sh_calls, sh_her = tot(r"rozjazd liczby ludzi (\d+)"), tot(r"BK jak dotad\): wywolan (\d+)"), tot(r"bohaterow do zamiany (\d+)")
    own = f"linia E8/G2: rozjazd liczby ludzi przy zamianie 1:1 {drift}, w cieniu wywolan {sh_calls} (bohaterow do zamiany {sh_her})"
    if p3:
        h3 = sum(num(r"bohaterow zamienionych na zolnierza z niczego (\d+)", s, int, 0) or 0 for s in p3.values())
        a3 = sum(num(r"ludzi dosypanych z niczego (\d+)", s, int, 0) or 0 for s in p3.values())
        c3 = sum(num(r"wywolan (\d+) \(w sluzbie", s, int, 0) or 0 for s in p3.values())
        rep.add("G2-1: klany najemnikow - bohaterowie zamienieni na zolnierza z niczego i ludzie dosypani z niczego (pomiar E8/P3, suma okna)",
                f"bohaterow zamienionych {h3}, ludzi dosypanych {a3} (wywolan zmierzonych {c3}, linii {len(p3)}); " + own,
                "0 i 0; rozjazd 0; w cieniu 0", h3 == 0 and a3 == 0 and drift == 0 and sh_calls == 0)
    else:
        rep.add("G2-1: klany najemnikow - bohaterowie zamienieni i ludzie dosypani z niczego",
                "brak linii Najemnicy BK (E8/P3) - pomiar wylaczony (Stage8WorldLog); " + own,
                "0 i 0 w pomiarze E8/P3; rozjazd 0; w cieniu 0", False if (drift or sh_calls) else None)
    calls, c_k = tot(r"nasza zamiast BK (\d+) razy"), tot(r"nasza zamiast BK \d+ razy \(w sluzbie (\d+)")
    c_f = tot(r"nasza zamiast BK \d+ razy \(w sluzbie \d+, bez sluzby (\d+)\)")
    svc_days = tot(r"w sluzbie krolestwa (\d+)")
    if svc_days > 0:
        rep.add("G2-1b: zamiana czynna - wywolania klanow najemnikow w sluzbie wobec klano-dob w sluzbie",
                f"wywolan w sluzbie {c_k} przy {svc_days} klano-dobach w sluzbie ({100.0 * c_k / svc_days:.0f}%); bez sluzby {c_f} (galaz BK martwa - oczekiwane 0)",
                ">= 50% klano-dob (BK wola metode raz na dobe dla klanu w krolestwie z wodzem; 0 = latka omijana)", c_k * 2 >= svc_days)
    else:
        rep.add("G2-1b: zamiana czynna", f"brak klanow najemnikow w sluzbie w calym oknie (wywolan {calls}) - zamiana nie miala okazji", "INFO", None)

    # ---------------- G2-2: INFO wielkosc druzyn
    def state(s):
        g = re.search(r"bez klanu Spoils\) (\d+), w sluzbie krolestwa (\d+), bez sluzby \d+; druzyn (\d+) \(w sluzbie (\d+)\), ludzi (\d+), bohaterow w druzynach (\d+)"
                      r" \(w sluzbie (\d+)\), wodzow prowadzacych druzyne (\d+) z \d+ \(w sluzbie (\d+) z \d+\)", s)
        if not g:
            return "brak stanu w linii"
        c, k, p, pk, m, h, hk, ld, ldk = (int(x) for x in g.groups())
        return f"klanow {c} (w sluzbie {k}), druzyn {p} (w sluzbie {pk}), ludzi {m}, bohaterow {h} (w sluzbie {hk}), wodz prowadzi {ld} (w sluzbie {ldk})"
    rep.add("G2-2: wielkosc druzyn klanow najemnikow (pierwsza -> ostatnia doba okna)",
            f"d{run_day(days[0], start)}: {state(first)} -> d{run_day(days[-1], start)}: {state(last)}",
            "INFO (mniejsze druzyny bez sluzby sa zamierzone - bez doplat)", None)
    sw, kept = tot(r"zolnierzy zamienionych 1:1 na szablon klanu (\d+)"), tot(r"bohaterow zostawionych w druzynach (\d+)")
    free_p, no_tpl, no_to, no_luck = tot(r"niezaszla w (\d+) druzynach"), tot(r"bez szablonu (\d+)"), tot(r"bez wzorca zamiany (\d+)"), tot(r"pominiete (\d+)")
    v_t, v_m = tot(r"tylko licznik\): (\d+) razy"), tot(r"tylko licznik\): \d+ razy / (\d+) ludzi")
    rep.add("G2-2b: zamiana 1:1 i bohaterowie (suma okna; na dobe)",
            f"zolnierzy zamienionych 1:1 {sw} ({sw / n:.1f}/d), bohaterow zostawionych {kept} ({kept / n:.1f}/d - tylu BK zamienialby co dobe na zolnierza z niczego)"
            f"; dosypka BK bez sluzby niezaszla w {free_p} druzynach; bez szablonu {no_tpl}, bez wzorca {no_to}, szansa BK ponizej 1: {no_luck}",
            "INFO", None)
    rep.add("G2-2c: ochotnicy z mapy gry u klanow najemnikow (poza paczka - ludzie bez pochodzenia u klanu bez sluzby)",
            f"{v_t} razy / {v_m} ludzi ({v_m / n:.1f}/d)", "INFO (do decyzji: ta sama blokada co klan Spoils)", None)
    # ---------------- G2-3: uczta
    g_calls, g_buys = tot(r"zakupy BK Automanage (\d+) razy"), tot(r"razy \(z towarem (\d+)\)")
    g_in, g_bk, g_out = tot(r"do spizarni (\d+) szt\."), tot(r"BK dopisal rynkowi (\d+) szt\."), tot(r"zdjete z rynku (\d+) szt\.")
    g_free, g_lost = tot(r"towar z niczego po calosci (\d+) szt\."), tot(r"rynek stracil ponad zakup (\d+) szt\.")
    g_odd, g_short, g_nor = tot(r"rynek zmieniony bez zakupu (\d+)"), tot(r"rynek mial mniej niz kupiono (\d+)"), tot(r"bez rynku albo spizarni (\d+)")
    rep.add("G2-3: uczta BK - towar z niczego po calosci i rynek ponad zakup (suma okna)",
            f"z niczego {g_free} szt., rynek stracil ponad zakup {g_lost} szt.; zakupow z towarem {g_buys} z {g_calls} wywolan, do spizarni {g_in} szt.",
            "0 i 0 (bez zakupow uczt w oknie - INFO)", (g_free == 0 and g_lost == 0) if g_buys > 0 else (None if g_free == 0 and g_lost == 0 else False))
    rep.add("G2-3b: uczta BK - zakupy (suma okna; na dobe)",
            f"do spizarni {g_in} szt. ({g_in / n:.1f}/d), BK dopisal rynkowi z niczego {g_bk} szt., zdjete z rynku {g_out} szt. (zakup + dopisek BK)"
            f"; rynek zmieniony bez zakupu {g_odd}, rynek mial mniej niz kupiono {g_short}, bez rynku albo spizarni {g_nor}",
            "INFO (zdjete = do spizarni + dopisek BK)", None)
    # ---------------- G2-4 / G2-K: koszt i kontrola
    cs = [c for c in (fnum(r"koszt ([0-9.]+) ms/dobe", x) for x in w) if c is not None]
    if cs:
        rep.add("G2-4: koszt (zamiana, okno uczty, linia)", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms", "INFO", None)
    stu = tot(r"potkniecia dzis (\d+)")
    errs = sum(1 for s in lines if s.startswith("ERROR in MercFeast."))
    rep.add("G2-K: kontrola (potkniecia, linie ERROR in MercFeast.*)", f"{stu} / {errs}", "0 / 0", stu == 0 and errs == 0)


E8_T_LATE = "Dorobek startowy (E8/T): dzien"
E8_T_PLAYER = "Rekrut gracza (E8/T): dzien"
E8_T_Z33_BUYS = (2451, 6123, 5037)   # zakupy AI (szt.) w dobach 1-3 biegu Z33 (WGRANIE 33, linie "ZakupyAI: dzien" L:337, L:653, L:942)
E8_T_Z33_LORD_KIT = (2229, 5267)     # Z33: lordowie - korpus i bron biala (szt.) w trzech pierwszych liniach "ZakupyAI wedlug kupujacego (174b)" (L:578, L:867, L:1159)
E8_T_Z33_NEW_D1 = 541                # nowe partie AI bez darmowego kompletu DTE w dobie 1 biegu Z33 (linia "Werbunek: dzien", L:341)
E8_T_Z33_LORDS_D1 = 276              # z tego partie lordow (linia "dziura werbunku ... nowe partie z szablonu klanu ... (276 partii)" tej samej doby)


def etap8_t(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/T (263, projekt etapu 8 v2 rozdz. 3 "E8/T" Test; NOWA KAMPANIA): start kampanii i rekruci gracza (ColdStart.cs, LevyGold.cs, RecruitKit.cs,
    PlayerRecruit.cs). Linie: "Start kampanii (E8/T): sesja" (klucze, przy kazdym starcie sesji), "Rekrut gracza (E8/T): latki przy starcie gry",
    "ColdStart: zbrojownie" i "ColdStart: budzet cechow (E8/T)" (raz, nowa gra), "Dorobek startowy (E8/T): dzien N" (doby 1-4 kampanii),
    "Rekrut gracza (E8/T): dzien N" (kazdy werbunek / najem gracza).
    T-0 latki rekruta gracza wpiete N/N; T-K0 trzy klucze czynne w ostatniej linii sesji;
    T-1 partie lordow z dorobkiem (sprzed startu + nowe z dob 1-3) >= 280 (projekt: ok. 280-300; Z33 mial 34 sprzed startu i 276 + 23 + 38 nowych);
    T-2 budzet cechow przepadly 0 (roboczodni, po zaokragleniu); T-2b INFO podzial na cechy i sztuki z wyzszego tieru;
    T-3 nowe partie lordow AI w dobach 1-3 bez dorobku z innego powodu niz "drugi raz ten sam wodz", "bez ludzi", umarli (sprzet umarlych poza
    gospodarka - recenzja E8/T) albo rod gracza = 0; T-3b INFO wszystkie nowe
    partie AI bez kompletu w dobie 1 wobec Z33 (541, z czego 276 lordow) i progu projektu 100 - reszta to wozy wsi, bandy i karawany, ktore dorobku
    z projektu nie dostaja;
    T-4 komplet (korpus + bron biala) kupiony przez partie lordow w pierwszych trzech dobach <= 50% Z33 (TRIAZ-2; cala linia ZakupyAI - INFO);
    T-5 rekrut gracza (gdy gracz werbowal): ludzi tieru 2+ = komplety DTE zablokowane i tier 1 = komplety DTE dane; bez werbunku gracza - INFO
    (sprawdzenie reczne 8.16 p. 2 i 19);
    T-K potkniecia 0 i linie "ERROR in ColdStart.*", "ERROR in PlayerRecruit.*", "ERROR in LevyGold.*" 0."""
    ses = [s for s in lines if s.startswith("Start kampanii (E8/T): sesja")]
    wire = [s for s in lines if s.startswith("Rekrut gracza (E8/T): latki przy starcie gry")]
    bud = [s for s in lines if s.startswith("ColdStart: budzet cechow (E8/T)")]
    late = {d: s for d, s in by_day(lines, E8_T_LATE).items() if 1 <= run_day(d, start) <= until}
    pl = [s for s in lines if s.startswith(E8_T_PLAYER)]
    if not ses and not wire and not bud and not late and not pl:
        rep.add("E8/T: linie Start kampanii (E8/T) / Dorobek startowy (E8/T) / Rekrut gracza (E8/T)", "brak w logu", "sa od wgrania E8/T", None)
        return
    # ---------------- T-0 / T-K0: latki i klucze
    if wire:
        w0 = wire[-1]
        a, b = num(r"wpiete (\d+)/\d+", w0), num(r"wpiete \d+/(\d+)", w0)
        rep.add("T-0: latki rekruta gracza (komplet DTE, okno werbunku, najem w rozmowie i w menu)", w0[:150], "wpiete N/N, BRAK: -",
                a is not None and b is not None and a == b and "; BRAK: - |" in w0)
    else:
        rep.add("T-0: latki rekruta gracza", "brak linii startowej", "wpiete N/N", False)
    if ses:
        s0 = ses[-1]
        keys = ("Cold Start Tier Up", "Cold Start Late Lord Parties", "Player Recruit No Free Kit")
        off = [k for k in keys if (k + " CZYNNE") not in s0]
        path = "sciezka czynna" in s0
        rep.add("T-K0: klucze paczki w ostatniej linii sesji (sesji w logu %d)" % len(ses),
                ("wszystkie CZYNNE" if not off else "WYLACZONE: " + ", ".join(off)) + ("; rekrut gracza: sciezka czynna" if path else "; rekrut gracza: sciezka NIECZYNNA"),
                "trzy klucze CZYNNE, sciezka rekruta gracza czynna", not off and path)
    else:
        rep.add("T-K0: klucze paczki", "brak linii \"Start kampanii (E8/T): sesja\"", "linia przy kazdym starcie sesji", False)

    def tot(rows, pat):
        return sum(num(pat, x, int, 0) or 0 for x in rows)
    d13 = [late[d] for d in sorted(late) if 1 <= run_day(d, start) <= 3]
    # ---------------- T-1: partie lordow z dorobkiem
    arm = [s for s in lines if s.startswith("ColdStart: zbrojownie - ")]
    if arm:
        a0 = arm[-1]
        allp, gar = num(r"zbrojownie - (\d+) partii", a0, int, 0) or 0, num(r"w tym garnizonow (\d+)", a0, int, 0) or 0
        lp = tot(d13, r"nowe partie lordow AI z dorobkiem (\d+)")
        pcs = tot(d13, r"nowe partie lordow AI z dorobkiem \d+ \(szt\. (\d+)\)")
        rep.add("T-1: partie lordow z dorobkiem stuleci (sprzed startu + nowe z dob 1-3 kampanii)",
                f"{allp - gar} sprzed startu + {lp} nowych = {allp - gar + lp} (nowe dostaly {pcs} szt.; linii doby {len(d13)} z 3)",
                ">= 280 (projekt ok. 280-300; Z33: 34 sprzed startu, nowych 276 + 23 + 38)", (allp - gar + lp) >= 280 if d13 else False)
    else:
        rep.add("T-1: partie lordow z dorobkiem stuleci", "brak linii \"ColdStart: zbrojownie\" - log nie zaczyna nowej kampanii", "INFO (prog tylko w nowej kampanii)", None)
    # ---------------- T-2: budzet cechow
    if bud:
        b0 = bud[-1]
        giv, used, lost = num(r"dany (\d+) roboczodni", b0), num(r"zuzyty (\d+), przepadly", b0), num(r", przepadly (\d+) \(los tieru", b0)
        draw, none, guard = num(r"stara regula (\d+) w", b0, int, 0), num(r"cech bez zadnej sztuki (\d+) w", b0, int, 0), num(r"straznik petli (\d+) w", b0, int, 0)
        up = num(r"\): (\d+) szt\.; cechy", b0, int, 0)
        rep.add("T-2: budzet cechow na starcie - przepadly (roboczodni)",
                f"dany {giv}, zuzyty {used}, przepadly {lost} (los tieru - stara regula {draw}, cech bez zadnej sztuki {none}, straznik petli {guard}); z wyzszego tieru {up} szt.",
                "przepadly 0", lost == 0 if lost is not None else False)
        g = re.search(r"cechy \[(.*)\]\.", b0)
        rep.add("T-2b: budzet wedlug cechu", g.group(1)[:420] if g else "brak podzialu w linii", "INFO", None)
    else:
        rep.add("T-2: budzet cechow na starcie", "brak linii \"ColdStart: budzet cechow (E8/T)\" - log nie zaczyna nowej kampanii albo zapas kupiecki wylaczony",
                "INFO (prog tylko w nowej kampanii)", None)
    # ---------------- T-3: nowe partie lordow bez dorobku
    if d13:
        lords = tot(d13, r"w tym partie lordow (\d+)\)")
        empty, again = tot(d13, r"bez ludzi albo bez brakow (\d+)"), tot(d13, r"drugi raz ten sam wodz (\d+)")
        nolead, keyoff = tot(d13, r"bez wodza (\d+)"), tot(d13, r"klucz wylaczony (\d+)")
        # recenzja E8/T: umarli (sprzet umarlych poza gospodarka) i rod gracza - celowo bez dorobku; log sprzed recenzji nie ma tych pol (0)
        undead, pclan = tot(d13, r"umarli \(sprzet poza gospodarka\) (\d+)"), tot(d13, r"rod gracza (\d+); nowe partie AI")
        bad = lords - empty - again - undead - pclan
        rep.add("T-3: nowe partie lordow AI w dobach 1-3 bez dorobku z innego powodu niz \"drugi raz ten sam wodz\", \"bez ludzi\", umarli albo rod gracza",
                f"{bad} (bez dorobku razem {lords}: bez ludzi albo bez brakow {empty}, drugi raz ten sam wodz {again}, umarli {undead}, rod gracza {pclan}, "
                f"bez wodza {nolead}, klucz wylaczony {keyoff})",
                "0", bad == 0)
        first = [late[d] for d in sorted(late) if run_day(d, start) == 1]
        if first:
            n1, l1 = num(r"bez kompletu DTE i bez dorobku (\d+)", first[0], int, 0), num(r"w tym partie lordow (\d+)\)", first[0], int, 0)
            rep.add("T-3b: wszystkie nowe partie AI bez kompletu w dobie 1",
                    f"{n1} (w tym partie lordow {l1}); Z33 {E8_T_Z33_NEW_D1}, z czego {E8_T_Z33_LORDS_D1} partii lordow - reszta ({E8_T_Z33_NEW_D1 - E8_T_Z33_LORDS_D1}) to wozy wsi, bandy, karawany",
                    "INFO (prog projektu <= 100 liczyl wszystkie rodzaje partii; dorobek z projektu dostaja tylko partie lordow - patrz T-3)", None)
    else:
        rep.add("T-3: nowe partie lordow AI w dobach 1-3 bez dorobku", "brak linii \"Dorobek startowy (E8/T)\" w dobach 1-3", "linia co dobe w dobach 1-3 nowej kampanii",
                False if arm else None)
    # ---------------- T-4: zakupy AI w dobach 1-3
    buys = by_day(lines, "ZakupyAI: dzien")
    got = []
    for k in (1, 2, 3):
        dd = [d for d in buys if run_day(d, start) == k]
        got.append(num(r"wizyt, (\d+) szt\. kupionych", buys[dd[0]]) if dd else None)
    # narzedzie progow p2 (TRIAZ-2 i "T-4"): linia "ZakupyAI" liczy tez kupujacych, ktorych dorobek nie obejmuje (zalogi: 12 / 48 / 45 zakupow jak w Z33)
    # i kategorie, ktorych dorobek nie pokrywa albo ktore doszly pozniej (reszta zbroi, helmy, bron strzelecka, konie i rzedy z E8/H i F5). Dorobek daje
    # partiom lordow KOMPLET - korpus i bron biala; miara: te dwie kategorie u lordow w trzech pierwszych liniach "ZakupyAI wedlug kupujacego (174b)"
    # kampanii (etykiety dob 2-4 = zakupy pierwszych trzech dob) razem <= 50% Z33 (korpus 787 + 926 + 516, bron biala 1594 + 2300 + 1373).
    # Prog "kazda doba <= 50%" calej linii ZakupyAI zdjety - liczby zostaja w tresci.
    kb = by_day(lines, "ZakupyAI wedlug kupujacego (174b): dzien")
    kit = []
    for k in (2, 3, 4):
        dd = [d for d in kb if run_day(d, start) == k]
        ml = re.search(r"- lordowie \[([^\]]*)\]", kb[dd[0]]) if dd else None
        kit.append((num(r"korpus (\d+)/", ml.group(1), int, 0) or 0, num(r"bron biala (\d+)/", ml.group(1), int, 0) or 0) if ml else None)
    if arm and all(x is not None for x in got) and all(x is not None for x in kit):
        kc, km = sum(x[0] for x in kit), sum(x[1] for x in kit)
        zk = E8_T_Z33_LORD_KIT[0] + E8_T_Z33_LORD_KIT[1]
        rep.add("T-4: zakupy kompletu (korpus + bron biala) partii lordow AI w pierwszych trzech dobach wobec Z33",
                f"{kc + km} szt. ({100.0 * (kc + km) / zk:.0f}% z {zk}; korpus {kc} wobec {E8_T_Z33_LORD_KIT[0]}, bron biala {km} wobec {E8_T_Z33_LORD_KIT[1]})"
                + " | cala linia ZakupyAI (z zalogami i kategoriami spoza dorobku): "
                + " / ".join(f"{x} ({100.0 * x / z:.0f}% z {z})" for x, z in zip(got, E8_T_Z33_BUYS)),
                "komplet u lordow <= 50% Z33 (dorobek daje korpus i bron biala partiom lordow; zalogi i pozostale kategorie - INFO)", 2 * (kc + km) <= zk)
    elif arm and all(x is not None for x in got):
        rep.add("T-4: zakupy AI w dobach 1-3 (szt.) wobec Z33",
                " / ".join(f"{x} ({100.0 * x / z:.0f}% z {z})" for x, z in zip(got, E8_T_Z33_BUYS)) + " | brak trzech linii ZakupyAI wedlug kupujacego (174b) z lordami",
                "INFO (prog liczony z linii 174b: komplet u lordow <= 50% Z33)", None)
    else:
        rep.add("T-4: zakupy AI w dobach 1-3 (szt.) wobec Z33", "brak linii ZakupyAI w dobach 1-3 albo log nie zaczyna nowej kampanii: " + str(got),
                "INFO (prog tylko w nowej kampanii)", None)
    # ---------------- T-5: rekrut gracza
    if pl:
        men, blocked = tot(pl, r"ludzi tieru 2\+ (\d+)"), tot(pl, r"komplet DTE zablokowany dla (\d+) ludzi")
        rec, own, tpl = tot(pl, r"z zapisu notabla (\d+)"), tot(pl, r"z tym co ma (\d+)"), tot(pl, r"wzorzec - wylacznik (\d+)")
        pcs, hp, ref = tot(pl, r"do zbrojowni druzyny (\d+) szt\."), tot(pl, r"konie i rzedy najemnikow (\d+)"), tot(pl, r"nieprzyjete przez DTE (\d+)")
        t1, t1d, noc = tot(pl, r"tier 1 z wlasnym dobytkiem (\d+)"), tot(pl, r"\(komplet DTE dla (\d+)\)"), tot(pl, r"ochotnik spoza koszyka (\d+)")
        mer = sum(1 for s in pl if "najemnicy z karczmy" in s)
        rep.add("T-5: rekrut gracza - ludzi tieru 2+ wobec zablokowanych kompletow DTE; tier 1 wobec kompletow DTE",
                f"tier 2+: {men} ludzi / {blocked} zablokowanych kompletow; tier 1: {t1} ludzi / {t1d} kompletow DTE (werbunkow {len(pl)}, w tym najem z karczmy {mer})",
                "rowne (kazdy rekrut tieru 2+ bez kompletu DTE, kazdy tieru 1 z kompletem DTE)", men == blocked and t1 == t1d)
        rep.add("T-5b: rekrut gracza - skad rzeczy (suma logu)",
                f"z zapisu notabla {rec}, z tym co ma {own}, wzorzec (wylacznik) {tpl}; do zbrojowni druzyny {pcs} szt. (konie i rzedy najemnikow {hp}, nieprzyjete przez DTE {ref})"
                f"; ochotnik spoza koszyka {noc}", "INFO", None)
    else:
        rep.add("T-5: rekrut gracza", "gracz nie werbowal w tym logu (autotest)", "INFO - sprawdzenie reczne 8.16 p. 2 (rekrut u notabla) i p. 19 (najemnik z karczmy)", None)
    # ---------------- T-K: kontrola
    stu_l = max([num(r"; potkniecia (\d+) \(Cold Start Late", s, int, 0) or 0 for s in late.values()] or [0])
    stu_p = max([num(r"; potkniecia (\d+)\.$", s, int, 0) or 0 for s in pl] or [0])
    stu_s = max([num(r"sciezka (?:czynna|nieczynna), potkniecia (\d+)\)", s, int, 0) or 0 for s in ses] or [0])
    errs = sum(1 for s in lines if s.startswith("ERROR in ColdStart.") or s.startswith("ERROR in PlayerRecruit.") or s.startswith("ERROR in LevyGold."))
    rep.add("T-K: kontrola (potkniecia dorobku / rekruta gracza / w linii sesji, linie ERROR in ColdStart.*, PlayerRecruit.*, LevyGold.*)",
            f"{stu_l} / {stu_p} / {stu_s} / {errs}", "0 / 0 / 0 / 0", stu_l == 0 and stu_p == 0 and stu_s == 0 and errs == 0)


# E8/K (255): blok etap8_k - kuznia: zlecenia kowalskie gry i ksiegarz BK (CraftOrders8.cs, GiverPay.cs, HistoricalPrices.cs)
E8_K_DAY = "Kuznia (E8/K): dzien"
E8_K_BOOKS = 24   # ksiazki BK (BKItems: 6 opowiesci po 750, 18 ksiazek umiejetnosci po 1000 - po BKROTPatch 7 i 10)


def etap8_k(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/K (255, projekt etapu 8 v2 rozdz. 3 "E8/K" Test): ksiazki BK, zlecenia kowalskie gry (CraftingOrder), kupno u ksiegarza BK. Linie: start gry
    "Kuznia (E8/K): latki przy starcie gry", start sesji "HistoricalPrices: ksiazek BK przeliczonych N" i "Kuznia (E8/K): sesja", doba "Kuznia (E8/K): dzien N".
    K-0 latki wpiete N/N, kazda podmiana wywolania w kodzie gry znaleziona dokladnie raz, lambda kupna BK jedna; K-0b linia doby w kazdej dobie okna (bez
    pierwszej i ostatniej), trzy klucze czynne; K-1 ksiazek BK przeliczonych 24; K-2 zlecenia sprzed sesji (zapis albo start nowej kampanii): po przeliczeniu
    zadna nagroda ponad 3 x nowa, INFO ile przeliczono; K-3 okno "zlecenia kowalskie" (suma okna): zloto z niczego 0, zolnierz z niczego dany 0, bron w nicosc 0
    (gracz nie oddal zlecenia - INFO, sprawdzenie reczne 8.16 p. 6), K-3b INFO obiecane / zaplacone / niedoplata; K-4 okno "ksiegarz": zloto w nicosc 0, ksiazka
    z niczego 0, stara droga BK mimo klucza 0 (bez kupna - INFO, 8.16 p. 7); K-5 nowe zlecenia: los gry spoza dozwolonych klas 0 i srednia nagroda w nowej
    monecie <= 1000 ("w setkach, nie w tysiacach"), K-5b INFO klasy dozwolone, tier przyciety, wymiana zlecen startowych nowej kampanii; K-6 INFO doswiadczenie
    zlecen; K-K potkniecia i linie ERROR in CraftOrders8.* / GiverPay.* / HistoricalPrices.PriceDesign 0."""
    rows = {d: s for d, s in by_day(lines, E8_K_DAY).items() if 1 <= run_day(d, start) <= until}
    wire = [x for x in lines if x.startswith("Kuznia (E8/K): latki przy starcie gry")]
    ses = [x for x in lines if x.startswith("Kuznia (E8/K): sesja")]
    books = [x for x in lines if x.startswith("HistoricalPrices: ksiazek BK przeliczonych")]
    if not rows and not wire and not ses:
        rep.add("E8/K: linie Kuznia (E8/K)", "brak w logu", "sa od wgrania E8/K (CraftOrders8.cs)", None)
        return
    # ---------------- K-0: latki i podmiany wywolan
    if wire:
        w0 = wire[-1]
        a, b = num(r"wpiete (\d+)/\d+", w0), num(r"wpiete \d+/(\d+)", w0)
        calls = "CompleteOrder wyplata 1, zolnierz 1; CreateTownOrder szablon 1, czesci 1; CreateCustomOrderForHero szablon 1, czesci 1" in w0
        lam = num(r"\(pasujacych (\d+)\)", w0)
        rep.add("K-0: latki (konstruktor CraftingOrder, GetOrderExperience, CompleteOrder, CreateTownOrder, CreateCustomOrderForHero, ksiegarz BK) i podmiany wywolan",
                f"wpiete {a}/{b}; podmiany po 1: {'tak' if calls else 'NIE'}; lambda kupna BK pasujacych {lam if lam is not None else 'brak BK'} | " + w0[:200],
                "wpiete N/N, BRAK: -, kazde wywolanie znalezione dokladnie raz, lambda kupna BK 1",
                a is not None and b is not None and a == b and "; BRAK: - |" in w0 and calls and lam == 1)
    else:
        rep.add("K-0: latki", "brak linii startowej", "wpiete N/N", False)
    # ---------------- K-1: ksiazki BK
    if books:
        nb = num(r"ksiazek BK przeliczonych (\d+)", books[-1], int, 0)
        off = "WYLACZONE" in books[-1]
        rep.add("K-1: ksiazki BK przeliczone (x100, kategoria book, wartosc ponizej 100)", f"{nb}" + (" (Book Price Fix WYLACZONE)" if off else "") + f"; linii {len(books)}",
                f"{E8_K_BOOKS} przy kazdym starcie sesji", (not off) and all(num(r"ksiazek BK przeliczonych (\d+)", x, int, 0) == E8_K_BOOKS for x in books))
    else:
        rep.add("K-1: ksiazki BK przeliczone", "brak linii HistoricalPrices: ksiazek BK przeliczonych (ceny historyczne wylaczone albo log sprzed E8/K)", f"{E8_K_BOOKS}", False)
    # ---------------- K-2: zlecenia sprzed sesji
    if ses:
        s0 = ses[-1]
        n_all, n_q = num(r"w miastach (\d+)", s0, int, 0), num(r"w tym zlecen zadan (\d+)", s0, int, 0)
        priced, nopr = num(r"projekt w cenach historycznych (\d+)", s0, int, 0), num(r"bez wyceny (\d+)", s0, int, 0)
        conv, kept, high = num(r"nagroda z zapisu przeliczona (\d+)", s0, int, 0), num(r"najwyzej 3 x nowa\) (\d+)", s0, int, 0), num(r"ponad 3 x nowa (\d+)", s0, int, 0)
        g = re.search(r"przeliczona \d+ \(suma (\d+) -> (\d+)\)", s0)
        early = num(r"start nowej kampanii\) (\d+)", s0, int, 0)
        on = "Craft Orders Historical CZYNNE" in s0
        rep.add("K-2: zlecenia kowalskie sprzed sesji (zapis albo start nowej kampanii) - nagroda w nowej monecie (ostatni start sesji; sesji w logu " + str(len(ses)) + ")",
                f"zlecen {n_all} (zadan {n_q}), projekt wyceniony {priced}, bez wyceny {nopr}; nagroda przeliczona {conv}"
                + (f" (suma {g.group(1)} -> {g.group(2)})" if g else "") + f", bez zmiany {kept}, po przeliczeniu ponad 3 x nowa {high}; zalozone przed przeliczeniem cen {early}"
                + ("" if on else "; Craft Orders Historical WYLACZONE"),
                "po przeliczeniu ponad 3 x nowa 0, klucz czynny (bieg zapisu: przeliczona > 0 przy pierwszym wczytaniu, 0 przy nastepnych)", on and high == 0)
    else:
        rep.add("K-2: zlecenia kowalskie sprzed sesji", "brak linii Kuznia (E8/K): sesja", "linia przy kazdym starcie sesji", False)
    if not rows:
        rep.add("K-0b: linia Kuznia (E8/K)", "brak linii doby", "codziennie w oknie", False)
        return
    days = sorted(rows)
    w = [rows[d] for d in days]
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rows]
    off_h = [d for d in days if "(Craft Orders Historical WYLACZONE" in rows[d]]
    off_o = [d for d in days if "Craft Orders Opened Only WYLACZONE" in rows[d]]
    off_b = [d for d in days if "(Book Price Fix WYLACZONE)" in rows[d]]
    val = f"linii {len(days)}, dob okna {len(inner)}" + (f", brak w {len(miss)} (doby {miss[:5]})" if miss else ", komplet")
    for nm, off in (("Craft Orders Historical", off_h), ("Craft Orders Opened Only", off_o), ("Book Price Fix", off_b)):
        if off:
            val += f"; {nm} WYLACZONE w {len(off)} dobach"
    wired = [(num(r"latki wpiete (\d+)/\d+", x), num(r"latki wpiete \d+/(\d+)", x)) for x in w]
    bad_w = sum(1 for a, b in wired if a is None or a != b)
    if bad_w:
        val += f"; latki niekompletne w {bad_w} liniach"
    rep.add("K-0b: linia Kuznia (E8/K) w kazdej dobie okna, trzy klucze czynne, latki komplet", val,
            "komplet (bez pierwszej i ostatniej doby), WYLACZONE 0", (not miss and not off_h and not off_o and not off_b and not bad_w) if inner else None)

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    n = len(w)
    # ---------------- K-3: okno "zlecenia kowalskie"
    done, quest = tot(r"oddanych (\d+) \(w tym"), tot(r"w tym zlecen zadan (\d+)\)")
    due, paid, short_n = tot(r"obiecane (\d+)"), tot(r"zaplacone przez zleceniodawce (\d+)"), tot(r"niedoplata przy pustej kiesie -?\d+ w (\d+) zleceniach")
    nothing, t_cut, t_given = tot(r"zloto z niczego (\d+)"), tot(r"zolnierz z niczego: wyciety (\d+)"), tot(r"wyciety \d+, dany (\d+)")
    hand, tabor, shelf, lost = tot(r"lord wzial do reki (\d+)"), tot(r"do taboru lorda (\d+)"), tot(r"na polke miasta (\d+)"), tot(r"bron w nicosc (\d+)")
    if done > 0:
        rep.add("K-3: okno \"zlecenia kowalskie\" (suma okna) - zloto z niczego, zolnierz z niczego, bron w nicosc",
                f"z niczego {nothing}, zolnierz dany {t_given} (wyciety {t_cut}), bron w nicosc {lost}; oddanych {done} (zadan {quest}): lord do reki {hand}, tabor lorda {tabor}, polka miasta {shelf}",
                "0 / 0 / 0; oddanych = do reki + tabor + polka", nothing == 0 and t_given == 0 and lost == 0 and done == hand + tabor + shelf)
        rep.add("K-3b: zlecenia kowalskie - obiecane i zaplacone przez zleceniodawcow (suma okna)",
                f"obiecane {due}, zaplacone {paid}, niedoplata {due - paid} w {short_n} zleceniach (pusta kiesa zleceniodawcy - bez doplat)", "INFO", None)
    else:
        rep.add("K-3: okno \"zlecenia kowalskie\"", "gracz nie oddal zadnego zlecenia w oknie (autotest)" + (f"; UWAGA liczniki bez oddania: z niczego {nothing}, w nicosc {lost}" if nothing or lost else ""),
                "INFO - sprawdzenie reczne 8.16 p. 6 (nagroda w setkach, zloto od zleceniodawcy, komunikat przy pustej kiesie)", None if not (nothing or lost) else False)
    # ---------------- K-4: okno "ksiegarz"
    talks, empty, sold, b_gold = tot(r"rozmow o kupnie (\d+)"), tot(r"pusta oferta (\d+)"), tot(r"sprzedanych (\d+)"), tot(r"zaplacone ksiegarzowi (\d+)")
    poor, gone, old, void, free = tot(r"brak zlota (\d+)"), tot(r"brak ksiazki (\d+)"), tot(r"stara droga BK mimo klucza (\d+)"), tot(r"zloto w nicosc (\d+)"), tot(r"ksiazka z niczego (\d+)")
    if talks > 0 or sold > 0 or free > 0:
        rep.add("K-4: okno \"ksiegarz\" (suma okna) - zloto w nicosc, ksiazka z niczego, stara droga BK mimo klucza",
                f"w nicosc {void}, z niczego {free}, stara droga {old}; rozmow {talks}, sprzedanych {sold} za {b_gold} (srednio {b_gold / sold:.0f})" if sold else
                f"w nicosc {void}, z niczego {free}, stara droga {old}; rozmow {talks}, sprzedanych 0 (pusta oferta {empty}, brak zlota {poor}, brak ksiazki {gone})",
                "0 / 0 / 0", void == 0 and free == 0 and old == 0)
    else:
        rep.add("K-4: okno \"ksiegarz\"", "gracz nie kupowal ksiazek w oknie (autotest)", "INFO - sprawdzenie reczne 8.16 p. 7 (cena 700-1 000, ksiazka znika z oferty, kiesa ksiegarza rosnie)", None)
    # ---------------- K-5: nowe zlecenia
    new, priced = tot(r"\): nowych (\d+) \(nagroda"), tot(r"nagroda przeliczona w (\d+):")
    r_game, r_hist = tot(r"przeliczona w \d+: gra (\d+) ->"), tot(r"-> historyczna (\d+)\)")
    picks, fall, cut = tot(r"szablon z dozwolonych klas (\d+) razy"), tot(r"brak dozwolonej klasy - los gry (\d+)"), tot(r"tier czesci przyciety (\d+) razy")
    sh, sh_closed = tot(r"wylaczony\): los gry (\d+) razy"), tot(r"z klasy zamknietej (\d+)")
    avg = r_hist / priced if priced else None
    rep.add("K-5: nowe zlecenia (suma okna) - los gry spoza dozwolonych klas i srednia nagroda w nowej monecie",
            f"nowych {new} ({new / n:.1f}/d), nagroda przeliczona w {priced}: gra {r_game} -> historyczna {r_hist}"
            + (f" (srednio {r_game / priced:.0f} -> {avg:.0f})" if priced else "") + f"; szablon z dozwolonych klas {picks} razy, los gry bez dozwolonej klasy {fall}"
            + (f"; w cieniu los gry {sh} razy, z klasy zamknietej {sh_closed}" if sh else ""),
            "los gry spoza dozwolonych klas 0; srednia nagroda <= 1000 (w setkach, nie w tysiacach); bez nowych zlecen - INFO",
            (fall == 0 and sh == 0 and avg is not None and avg <= 1000.0) if (new > 0 and priced > 0) else (None if fall == 0 and sh == 0 else False))
    last = rows[days[-1]]
    cls = re.search(r"klasy broni dozwolone (\d+) z (\d+)( \[zamkniete: [^\]]*\])?", last)
    nk = [(run_day(d, start), num(r"zlecenia startowe nowej kampanii wymienione (\d+)", rows[d])) for d in days]
    nk = [(d, v) for d, v in nk if v is not None]
    rep.add("K-5b: klasy broni dozwolone (ostatnia doba), tier czesci przyciety, wymiana zlecen startowych nowej kampanii",
            (f"dozwolone {cls.group(1)} z {cls.group(2)}{cls.group(3) or ''}" if cls else "brak stanu klas w linii") + f"; tier przyciety {cut} razy"
            + ("; wymiana startowa: " + ", ".join(f"d{d}: {v}" for d, v in nk) if nk else "; wymiana startowa nie biegla (stary zapis albo klucz wylaczony)"),
            "INFO (nowa kampania: wymiana raz w pierwszej dobie, liczba = zlecenia startowe)", None)
    # ---------------- K-6: doswiadczenie zlecen
    xp, xps = tot(r"doswiadczenie zlecen: odczytow (\d+)"), tot(r"od wartosci sprzed przeliczenia (\d+)")
    rep.add("K-6: doswiadczenie zlecen (suma okna)", f"odczytow {xp}, policzonych od wartosci sprzed przeliczenia {xps}", "INFO (bez zmian wobec gry - liczone od dawnej wartosci projektu)", None)
    # ---------------- K-K: koszt i kontrola
    cs = [c for c in (fnum(r"koszt ([0-9.]+) ms/dobe", x) for x in w) if c is not None]
    if cs:
        rep.add("K-7: koszt (nowe zlecenia, linia)", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms", "INFO", None)
    stu = tot(r"potkniecia dzis (\d+)")
    stu_s = max([num(r"potkniecia (\d+)\.$", x, int, 0) or 0 for x in ses] or [0])
    errs = sum(1 for s in lines if s.startswith("ERROR in CraftOrders8.") or s.startswith("ERROR in GiverPay.") or s.startswith("ERROR in HistoricalPrices.PriceDesign"))
    rep.add("K-K: kontrola (potkniecia doby / przy starcie sesji, linie ERROR in CraftOrders8.*, GiverPay.*, HistoricalPrices.PriceDesign)",
            f"{stu} / {stu_s} / {errs}", "0 / 0 / 0", stu == 0 and stu_s == 0 and errs == 0)


# E8/H (271): blok etap8_h - jezdziec = kon + uprzaz (SaddleLaw.cs; brama awansu, bitwa gracza, zakup siodel, pula weteranow)
E8_H_LINE = "Jezdzcy i uprzaz (E8/H): dzien"
E8_H_START = "Jezdzcy i uprzaz (E8/H): start"
E8_H_BOOK = "Uzbrojenie wedlug zrodla (E6/0): dzien"
E8_H_Z33_HORSED_SHARE = 4.60    # Z33 doba 120: jezdzcy z koniem 7 711 z 167 462 ludzi partii lordow i zalog AI (L:36040) - odniesienie progu H-2
E8_H_Z33_UPGRADES = 823         # Z33: awanse AI na jezdzca w 120 dob (konie-krolestwa.csv) - odniesienie progu H-5
E8_H_ZB58_UPGRADES = 3047       # bieg zb58 (z E6/K3, bez E8/H): konie za awans AI w 120 dob (TRIAZ-zb58-120 "Styk K3 z E8/H") - odniesienie INFO przy H-5a
E8_H_Z33_MADE = 13.4            # Z33: uprzaz wykonana na dobe w dobach 91-120 (linia "Warsztaty")
E8_H_GROUP = (r"\| %s: partii (\d+), ludzi (\d+), jazda wedlug typu (\d+) \([0-9.]+%%\), objeci regula (\d+), z koniem (\d+) \([0-9.]+%%\), z para (\d+) \([0-9.]+%%\), "
              r"z koniem bez uprzezy (\d+), bez konia (\d+), wzorzec bez uprzezy (\d+); zbrojownie: konie (\d+), uprzaz rodziny konia (\d+), innej rodziny (\d+), wolna (\d+)")
E8_H_FIELDS = ("partii", "ludzi", "typ", "regula", "kon", "para", "bez_uprzezy", "bez_konia", "wyjatek", "konie", "uprzaz", "inna", "wolna")


def e8h_group(s, name):
    m = re.search(E8_H_GROUP % re.escape(name), s)
    return dict(zip(E8_H_FIELDS, (int(x) for x in m.groups()))) if m else None


def etap8_h(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/H (271; decyzja Jeffa 12.10 "jezdziec = kon + uprzaz"; rozpoznanie docs/etap8/rozpoznanie-H-jezdziec-uprzaz.md rozdz. 5 "Progi do testu"): linia doby
    "Jezdzcy i uprzaz (E8/H)" (SaddleLaw.cs, takt doby po "Konie AI (175)") - spis par osobno dla partii rodow AI, zalog i rodu gracza (takze przy wylaczonej
    regule: "z koniem bez uprzezy" = tylu zeszloby z koni). H-0 linia w kazdej dobie okna, stan reguly, brama gracza wpieta; H-1 jezdzcy z koniem bez uprzezy
    <= 10% jezdzcow z koniem w dobach 61-until (partie rodow AI; doby 1-30, zalogi i rod gracza - INFO); H-2 udzial jezdzcow z para w ludziach partii rodow AI
    i zalog w ostatniej dobie okna wobec Z33 "z koniem" 4.60% (>= TAK, ponizej 80% tej liczby NIE); H-3 uprzaz wykonana >= 40 szt. na dobe w dobach 31-until;
    H-4 nic z niczego, nic w nicosc: rzad najemnika ze wzorca 0 w dobach z regula, reszta uprzezy w ksiedze uzbrojenia |suma okna| <= 10% zrodel; H-5 awanse AI
    na jezdnego >= 50% Z33 i "wstrzymane z braku uprzezy" nie rosnie w dobach 91-until wobec 61-90; H-6 polki uprzezy w ostatniej dobie 300-2500 i kupno siodla
    w 7 dob po sprzedazy uprzezy tej samej partii = 0; H-7 koszt zdarzen <= 5 i razem ze spisem <= 15 ms na dobe, potkniecia i linie ERROR 0 (TRIAZ-2: H-3 TAK takze przy H-1 <= 10%, H-4a po siewie puli weteranow, H-5b INFO przy H-1 NIE, H-6b <= 1% kupionych siodel). Reczne (8.16): awans piechura na jezdzca u gracza
    bez siodla - komunikat; bitwa z jezdzcami bez siodla - ida pieszo, komunikat "riders no saddle"; wczytanie zapisu sprzed E8/H bez bledu."""
    hl = {d: s for d, s in by_day(lines, E8_H_LINE).items() if 1 <= run_day(d, start) <= until}
    if not hl:
        rep.add("E8/H: linia Jezdzcy i uprzaz (E8/H)", "brak w logu", "jest od wgrania E8/H", None)
        return
    days = sorted(hl)
    nd = max(1, len(days))
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in hl]
    on = [d for d in days if "| regula [WL]" in hl[d]]
    st = [s for s in lines if s.startswith(E8_H_START)]
    wired = bool(st) and "brama awansu gracza wpieta 1/1" in st[-1]
    rep.add("H-0: linia Jezdzcy i uprzaz (E8/H) w kazdej dobie okna; stan reguly; brama awansu gracza",
            (f"{len(days)} dob (brak {len(miss)}" + (f": doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") if miss else "") + f" z {len(inner)}); regula wl {len(on)} / wyl "
             f"{len(days) - len(on)} dob; linia startu " + ("brak" if not st else ("brama wpieta 1/1" if wired else "brama NIE wpieta"))),
            "0 brakow (bez pierwszej i ostatniej doby okna), brama awansu gracza wpieta 1/1", ((not miss) and wired) if inner else None)

    def col(pat, cast=int):
        return {d: num(pat, hl[d], cast=cast, default=0) for d in days}

    def tot(c, sel=None):
        return sum(c[d] for d in (days if sel is None else sel))

    def rng(a, b):
        return [d for d in days if a <= run_day(d, start) <= b]
    grp = {n: {d: e8h_group(hl[d], n) for d in days} for n in ("partie rodow AI", "zalogi", "rod gracza")}
    bad = [run_day(d, start) for d in days if grp["partie rodow AI"][d] is None or grp["zalogi"][d] is None]
    if bad:
        rep.add("E8/H: spis par w linii", f"nie odczytany w {len(bad)} dobach (np. {bad[:5]})", "format linii z SaddleLaw.Daily", False)
        return

    def share(name, sel, a, b):
        x = sum(grp[name][d][a] for d in sel if grp[name][d])
        y = sum(grp[name][d][b] for d in sel if grp[name][d])
        return x, y, (100.0 * x / y if y else 0.0)
    # H-1: jezdzcy z koniem bez uprzezy
    late, early = [d for d in rng(61, until) if d in on], rng(1, 30)
    e_x, e_y, e_p = share("partie rodow AI", early, "bez_uprzezy", "kon")
    g_x, g_y, g_p = share("zalogi", rng(61, until), "bez_uprzezy", "kon")
    p_x, p_y, p_p = share("rod gracza", rng(61, until), "bez_uprzezy", "kon")
    info = (f"doby 1-30: {e_p:.1f}% ({e_x} z {e_y} jezdzco-dob); zalogi doby 61-{until}: {g_p:.1f}% ({g_x} z {g_y}; nie kupuja uprzezy); "
            f"rod gracza: {p_p:.1f}% ({p_x} z {p_y})")
    h1_ok = None   # werdykt H-1 (None = brak dob 61+ z regula) - od niego zaleza H-3 i H-5b (narzedzie progow p2, TRIAZ-2 GLOWNE pkt 4 i H-5b pkt 3a)
    if late:
        l_x, l_y, l_p = share("partie rodow AI", late, "bez_uprzezy", "kon")
        h1_ok = l_p <= 10.0
        peak = max(days, key=lambda d: grp["partie rodow AI"][d]["bez_uprzezy"])
        rep.add(f"H-1: jezdzcy z koniem bez uprzezy - partie rodow AI, doby 61-{until}",
                f"{l_p:.1f}% ({l_x} z {l_y} jezdzco-dob w {len(late)} dobach z regula); szczyt okna: doba {run_day(peak, start)} = "
                f"{grp['partie rodow AI'][peak]['bez_uprzezy']} z {grp['partie rodow AI'][peak]['kon']} | " + info,
                "<= 10% jezdzcow z koniem (doby 1-30, zalogi, rod gracza - INFO)", l_p <= 10.0)
    else:
        rep.add("H-1: jezdzcy z koniem bez uprzezy", "brak dob 61+ z wlaczona regula | " + info
                + ("" if on else " | regula wylaczona: tylu zeszloby z koni (pomiar 'przed')"), "INFO (prog liczony w dobach 61+ z regula)", None)
    # H-2: udzial jezdzcow z para
    last = days[-1]
    a, g = grp["partie rodow AI"][last], grp["zalogi"][last]
    men = a["ludzi"] + g["ludzi"]
    pair = 100.0 * (a["para"] + g["para"]) / max(1, men)
    horsed = 100.0 * (a["kon"] + g["kon"]) / max(1, men)
    typ = 100.0 * (a["typ"] + g["typ"]) / max(1, men)
    full = run_day(last, start) >= until and until == 120
    lo = 0.8 * E8_H_Z33_HORSED_SHARE
    rep.add(f"H-2: udzial jazdy w ludziach partii rodow AI i zalog (doba {run_day(last, start)})",
            (f"wedlug typu jednostki {typ:.2f}%, z koniem {horsed:.2f}%, Z PARA {pair:.2f}% (Z33 doba 120 z koniem: {E8_H_Z33_HORSED_SHARE:.2f}%); same partie rodow AI: typ "
             f"{100.0 * a['typ'] / max(1, a['ludzi']):.2f}%, z koniem {100.0 * a['kon'] / max(1, a['ludzi']):.2f}%, z para {100.0 * a['para'] / max(1, a['ludzi']):.2f}%; "
             f"bez konia {a['bez_konia'] + g['bez_konia']}, wzorzec bez uprzezy {a['wyjatek'] + g['wyjatek']}"),
            f"z para >= {E8_H_Z33_HORSED_SHARE:.2f}% (Z33 z koniem); ponizej {lo:.2f}% (80%) = NIE; pomiedzy - INFO" + ("" if full else " - INFO poza doba 120"),
            (True if pair >= E8_H_Z33_HORSED_SHARE else (False if pair < lo else None)) if (full and last in on) else None)
    # H-3: produkcja uprzezy
    ws = {run_day(d, start): num(r"wykonano \d+ szt\. \[[^\]]*HorseHarness (\d+)", s, int, 0) or 0 for d, s in by_day(lines, "Warsztaty: dzien").items()}
    w31 = [v for rd, v in ws.items() if 31 <= rd <= until]
    if w31:
        avg = sum(w31) / len(w31)
        # narzedzie progow p2 (TRIAZ-2 GLOWNE "Poprawka ostateczna" pkt 4, H-3 pkt 3d): prog 40 szt./d zostaje (odpowiada popytowi); po zdjeciu zaleglosci
        # siodel produkcje ogranicza POPYT (ok. 33-45 siodel/d), wiec H-3 czyta sie razem z H-1: przy H-1 <= 10% wiersz jest TAK takze ponizej 40.
        rep.add(f"H-3: uprzaz wykonana przez warsztaty (srednio doby 31-{until})", f"{avg:.1f} szt./d ({len(w31)} dob; Z33: {E8_H_Z33_MADE})"
                + ("; H-1 <= 10% - produkcje ogranicza popyt" if (avg < 40.0 and h1_ok) else ("; NIE = czeka na podaz siodel (zwykle siodlo w kazdej krainie, TRIAZ-2)" if avg < 40.0 else "")),
                ">= 40 szt./d albo H-1 <= 10% (wtedy produkcje ogranicza popyt); druga droga progu - linie siodel t1 z pustym rankingiem <= 10 miast - w warsztaty.log, "
                "poza tym narzedziem", avg >= 40.0 or bool(h1_ok))
    else:
        rep.add("H-3: uprzaz wykonana przez warsztaty", "brak linii Warsztaty w dobach 31+", "INFO", None)
    # H-4: nic z niczego, nic w nicosc
    tpl, loose, refd = col(r"rzad ze wzorca \(z niczego\) (\d+)"), col(r"w tym do zbrojowni nietrwalej (\d+)"), col(r"DTE nie przyjal (\d+)\)")
    spoil = col(r"dobytek rozbitych: uprzaz zbrojowni (\d+)")
    # narzedzie progow p2 (TRIAZ-2 "H-4a"; ta sama rzecz co K1-4 / K1-4a po triazu zb58): kon i rzad z puli weteranow dzialaja dopiero po siewie puli
    # (RecruitKit: vetHorse = HorseFate.VetHorseOn && troop.IsMounted; VetHorseOn wymaga PeopleBook.VetLive, a siew jest w pierwszym ticku doby kampanii -
    # linia "Weterani (E4/10): siew dnia N"). Najem z karczm przed siewem idzie sciezka gry - dorobek startowy (bieg 2: 30 szt. tylko w pierwszej linii
    # kampanii, ci sami najemnicy co "kon z wzorca 30" w K1-4a; potem z para z puli 247, rzad ze wzorca 0). Prog 0 dotyczy dob po siewie (linie z dniem
    # > N); doby do siewu wlacznie - INFO. Log bez linii siewu (wczytany zapis) - liczy sie cale okno.
    sow = None
    for x in lines:
        if x.startswith("Weterani (E4/10): siew dnia "):
            sow = num(r"siew dnia (\d+)", x)
            break
    on_post = [d for d in on if sow is None or d > sow]
    pre_n = tot(tpl, [d for d in on if d not in on_post])
    rep.add("H-4a: uprzaz z niczego - rzad najemnika ze wzorca (doby z regula po siewie puli weteranow)",
            f"{tot(tpl, on_post)} szt." + (f"; przed siewem puli weteranow (siew dnia {sow}, linii do siewu {len(on) - len(on_post)}): {pre_n} szt. - INFO (karczmy jak w grze, dorobek startowy)" if sow is not None else "")
            + (f"; doby bez reguly: {tot(tpl, [d for d in days if d not in on])} szt." if len(on) < len(days) else "")
            + f"; uprzaz zbrojowni rozbitych partii przeniesiona {tot(spoil)} szt.; z taboru do zbrojowni nietrwalej {tot(loose)} szt., DTE nie przyjal {tot(refd)}",
            "rzad ze wzorca = 0 w dobach z regula po siewie puli weteranow (doby do siewu i reszta - INFO)", (tot(tpl, on_post) == 0) if on_post else None)
    bk = {d: s for d, s in by_day(lines, E8_H_BOOK).items() if d in hl}
    src = rest = 0
    nb = 0
    for d, s in bk.items():
        m = re.search(r"uprzaz t1-2/t3-4/t5-6: stan [\d/-]+, zrodla (\d+)/(\d+)/(\d+), reszta (-?\d+)/(-?\d+)/(-?\d+)", s)
        if m:
            nb += 1
            src += int(m.group(1)) + int(m.group(2)) + int(m.group(3))
            rest += int(m.group(4)) + int(m.group(5)) + int(m.group(6))
    if nb:
        rep.add("H-4b: reszta uprzezy w ksiedze uzbrojenia (E6/0) - suma okna", f"reszta {rest:+d} szt. przy zrodlach {src} szt. ({nb} dob; Z33: -1118 przy 1356)",
                "|reszta| <= 10% zrodel (uprzaz nie powstaje i nie znika poza warsztatami i zlomem)", abs(rest) <= 0.10 * max(1, src))
    else:
        rep.add("H-4b: reszta uprzezy w ksiedze uzbrojenia (E6/0)", "brak linii z rodzajem uprzaz", "INFO (potrzebny Stage6MeasureLog)", None)
    # H-5: awanse AI na jezdnego i czekajacy na uprzaz
    up, ref, trim, payr = col(r"awanse na jezdnego z para (\d+)"), col(r"cele odrzucone (\d+) ludzi"), col(r"ludzi, przyciete (\d+)"), col(r"przy zaplacie (\d+)")
    need_up = 0.5 * E8_H_Z33_UPGRADES * len(on) / 120.0
    # recenzja E8/H (TRIAZ zb58 "Styk K3 z E8/H"): prog z Z33 spelnia juz sam K3 (3047 awansow w biegu zb58) - skutek bramy uprzezy pokazuje procent biegu z K3 (INFO)
    k3_up = E8_H_ZB58_UPGRADES * len(on) / 120.0
    rep.add("H-5a: awanse AI na jezdnego (z para) w dobach z regula",
            (f"{tot(up, on)} w {len(on)} dobach ({tot(up, on) / max(1, len(on)):.1f}/d; Z33: {E8_H_Z33_UPGRADES} w 120 dob = 6.9/d; bieg z K3 bez bramy uprzezy (zb58): "
             f"{E8_H_ZB58_UPGRADES} = 25.4/d - teraz {100.0 * tot(up, on) / max(1.0, k3_up):.0f}% tego biegu)"),
            f">= 50% Z33 w przeliczeniu na liczbe dob ({need_up:.0f}); prog z Z33 spelnia sam K3 - procent biegu z K3 to INFO o skutku bramy uprzezy",
            (tot(up, on) >= need_up) if len(on) >= 30 else None)
    a1, a2 = [d for d in rng(61, 90) if d in on], [d for d in rng(91, until) if d in on]
    if a1 and a2:
        m1, m2 = tot(ref, a1) / len(a1), tot(ref, a2) / len(a2)
        # narzedzie progow p2 (TRIAZ-2 "H-5b", "Poprawka ostateczna" pkt 3): licznik to OSOBO-PROBY, nie ludzie - ci sami gotowi z koniem bez wolnej uprzezy
        # sa liczeni co dobe i po kazdej bitwie, w kazdym oddziale partii (bieg 2: 54 666 w oknie przy ok. 1 233 naprawde wstrzymanych awansach), wiec
        # liczba rosnie, dopoki siodel brakuje - pochodna H-1 / H-3 (podaz siodel), nie osobny blad; brama dziala zgodnie z decyzja Jeffa. Prog "nie
        # rosnie" liczony dopiero, gdy H-1 jest TAK; przy H-1 NIE - INFO. Odniesienia w tresci: awanse z para na dobe w obu oknach wobec biegu z K3 bez
        # bramy (zb58: 25.4/d) i wzrost kolejki do KONIA w tych samych oknach (linia "Konie AI (175)": ta sama miara rosnie we wszystkich biegach -
        # W33 x1.45, zb58 x1.22).
        u1, u2 = tot(up, a1) / len(a1), tot(up, a2) / len(a2)
        kq = {}
        for d, s in by_day(lines, "Konie AI (175): dzien").items():
            v = num(r"czeka na konia swojej kategorii[^0-9|]*(\d+)", s)
            if v is not None:
                kq[run_day(d, start)] = v
        q1, q2 = [v for rd, v in kq.items() if 61 <= rd <= 90], [v for rd, v in kq.items() if 91 <= rd <= until]
        qtxt = (f"; kolejka do konia w tych samych oknach (Konie AI 175) {sum(q1) / len(q1):.0f} -> {sum(q2) / len(q2):.0f} (x{(sum(q2) / len(q2)) / (sum(q1) / len(q1)):.2f})"
                if (q1 and q2 and sum(q1) > 0) else "")
        rep.add(f"H-5b: wstrzymane z braku uprzezy (osobo-proby na dobe) - doby 91-{until} wobec 61-90",
                f"{m1:.1f}/d -> {m2:.1f}/d (x{m2 / m1 if m1 > 0 else 0:.2f}; kolejka: gotowi z koniem bez wolnej uprzezy, liczeni co dobe i po bitwie, w kazdym oddziale partii)"
                f"; w oknie: cele odrzucone {tot(ref)} osobo-prob, przyciete {tot(trim)}, przy zaplacie {tot(payr)}; awanse z para {u1:.1f}/d -> {u2:.1f}/d "
                f"(bieg z K3 bez bramy uprzezy: {E8_H_ZB58_UPGRADES / 120.0:.1f}/d)" + qtxt
                + ("" if h1_ok else " | pochodna H-1 / H-3 - podaz siodel (brama uprzezy bez zmian)"),
                "nie rosnie (<= 1.1 x + 5), liczone gdy H-1 jest TAK; przy H-1 NIE - INFO (kolejka rosnie, dopoki brakuje siodel - TRIAZ-2 H-5b)",
                (m2 <= 1.1 * m1 + 5.0) if h1_ok else None)
    else:
        rep.add("H-5b: wstrzymane z braku uprzezy", f"cele odrzucone {tot(ref)} osobo-prob, przyciete {tot(trim)}, przy zaplacie {tot(payr)} (brak dob 61-90 i 91+ z regula)", "INFO", None)
    # H-6: polki i kupno po sprzedazy
    shelf = col(r"polki miast i zamkow: uprzaz (\d+)")
    rebuy, held = col(r"dob po sprzedazy uprzezy (\d+) szt"), col(r"zatrzymane pod zapas przy sprzedazy nadwyzek (\d+)")
    has_shelf = "polki miast i zamkow: uprzaz brak spisu" not in hl[last]
    rep.add(f"H-6a: polki uprzezy miast i zamkow (doba {run_day(last, start)})",
            (f"{shelf[last]} szt." if has_shelf else "brak spisu") + f" (Z33 doba 120: 1253); najmniej w oknie {min(shelf[d] for d in days)} szt.",
            "300 - 2500 szt." + ("" if full else " - INFO poza doba 120"), (300 <= shelf[last] <= 2500) if (full and has_shelf) else None)
    bp, bn, bpc, bg, bs, bo, rs = col(r"partie z brakiem (\d+)"), col(r"brak przed zakupem (\d+)"), col(r", kupione (\d+) szt\. za \d+ zl, brak po zakupach"), \
        col(r", kupione \d+ szt\. za (\d+) zl, brak po zakupach"), col(r"brak po zakupach (\d+)"), col(r"zamowienia dla siodlarzy (\d+)"), col(r"z taboru do zbrojowni przy postoju (\d+)")
    # narzedzie progow p2 (TRIAZ-2 "H-6b"): licznik lapie KAZDE kupno partii, ktora w 7 dobach sprzedala nadwyzke E8/Z - wystarczy, ze po sprzedazy doszedl
    # jej kon (bieg 2: 1 sztuka na 3120 kupionych siodel, jedna doba; sprzedaz nadwyzek mala - 19 szt. w 7 partiach w dobie 119, petli nie ma).
    # Prog "0" nie zostawial miejsca na jeden zbieg okolicznosci w 120 dobach: kupno po sprzedazy <= 1% kupionych siodel w oknie (petla dalaby kilkanascie %).
    rb_n, bought_n = tot(rebuy), tot(bpc)
    rep.add("H-6b: kupno siodla w 7 dob po sprzedazy uprzezy tej samej partii",
            (f"{rb_n} szt. z {bought_n} kupionych siodel ({100.0 * rb_n / bought_n:.2f}%)" if bought_n else f"{rb_n} szt. (kupionych siodel 0)")
            + f" (zatrzymane pod zapas przy sprzedazy nadwyzek {tot(held)} szt.)",
            "<= 1% kupionych siodel w oknie (petla kup-sprzedaj; pojedynczy zbieg okolicznosci to nie petla)", (rb_n <= 0.01 * bought_n) if on else None)
    rep.add("E8/H: zakupy siodel lordow AI (okno)",
            (f"kupione {tot(bpc)} szt. za {tot(bg)} zl ({tot(bpc) / nd:.1f} szt./d, {tot(bg) / nd:.0f} zl/d, srednio {tot(bg) / max(1, tot(bpc)):.0f} zl za sztuke); wizyty z brakiem "
             f"{tot(bp)}, brak przed zakupem {tot(bn)}, po zakupach {tot(bs)}; zamowienia dla siodlarzy {tot(bo)}; z taboru do zbrojowni przy postoju {tot(rs)} szt."),
            "INFO (rozpoznanie: 30-50 siodel na dobe, 2-7 tys. zl na dobe)", None)
    rp, rn = col(r"zamiany ROT: z para (\d+)"), col(r"zamiany ROT: z para \d+, bez pary (\d+)")
    mp_, mb = col(r"najemnicy: z para z puli (\d+)"), col(r"kon z puli bez uprzezy (\d+)")
    vi, vn, vo, vs = col(r"pula weteranow: uprzaz \+(\d+)"), col(r"weteran bez uprzezy (\d+)"), col(r"\), na polki (\d+), stan"), col(r"\), na polki \d+, stan (\d+)")
    rep.add("E8/H: zamiany ROT, najemnicy, pula weteranow (okno)",
            (f"zamiany ROT z para {tot(rp)}, bez pary (pieszy albo konny bez konia) {tot(rn)}; najemnicy z para z puli {tot(mp_)}, kon bez uprzezy {tot(mb)}; "
             f"pula weteranow: uprzaz +{tot(vi)} (weteran bez uprzezy {tot(vn)}), na polki {tot(vo)}, stan w ostatniej dobie {vs[last]}"), "INFO", None)
    pr, ps = col(r"gracz: awanse wstrzymane z braku uprzezy (\d+)"), col(r"uprzaz z sakw do zbrojowni (\d+)")
    bpl, bl, bgr = col(r"z braku uprzezy - gracz (\d+)"), col(r"z braku uprzezy - gracz \d+, lordowie (\d+)"), col(r"z braku uprzezy - gracz \d+, lordowie \d+, zalogi (\d+)")
    rep.add("E8/H: gracz - brama awansu i bitwy (okno)",
            (f"awanse wstrzymane z braku uprzezy {tot(pr)}, uprzaz z sakw do zbrojowni {tot(ps)} szt.; bitwy gracza: zeszlo z koni z braku uprzezy - gracz {tot(bpl)}, "
             f"lordowie {tot(bl)}, zalogi {tot(bgr)}"), "INFO (autotest bez gracza: 0; sprawdzenie reczne 8.16)", None)
    # H-7: koszt i potkniecia
    c1, c2 = col(r"koszt: spis ([0-9.]+) ms", cast=float), col(r"ms, zdarzenia ([0-9.]+) ms", cast=float)
    cost = [c1[d] + c2[d] for d in days]
    stum = max([num(r"potkniecia dzis \d+ \(sesja (\d+)\)", hl[d], default=0) for d in days] + [0])
    errs = sum(1 for s in lines if s.startswith("ERROR in SaddleLaw.") or s.startswith("ERROR in GarrisonKit.SaddleGuard"))
    # narzedzie progow p2 (TRIAZ-2 "H-7" - dwa wpisy): prog 5 ms pochodzil z szacunku [S] "1-2 ms na 850 partii". Mechanika (zdarzenia bramy i zakupow)
    # miesci sie w nim (2.5 ms/d); ponad prog jest tylko SPIS par do linii logu - co dobe wszystkie partie rodow i zalogi (SaddleLaw.CensusOne): 8.3 ms/d,
    # d120 10.0 ms przy 661 partiach + 227 zalogach = 0.05% doby. Prog: zdarzenia <= 5 ms/d (jak dotad dla mechaniki) i razem ze spisem <= 15 ms/d.
    # Optymalizacja spisu - na koniec projektu (decyzja Jeffa 08.10); wiersze H czytaja spis dobowy.
    ev_ms, all_ms = sum(c2.values()) / nd, sum(cost) / nd
    rep.add("H-7: koszt E8/H na dobe (spis par + zdarzenia), potkniecia, linie ERROR in SaddleLaw.*",
            f"srednio {all_ms:.1f} ms/d (spis {sum(c1.values()) / nd:.1f}, zdarzenia {ev_ms:.1f}), najwiecej {max(cost):.1f} ms; potkniecia (sesja) {stum}; ERROR {errs}",
            "zdarzenia <= 5 ms/d i razem ze spisem <= 15 ms/d srednio, potkniecia 0, ERROR 0 (wczytanie zapisu sprzed E8/H - procedura 'zapis 9 dob', recznie)",
            ev_ms <= 5.0 and all_ms <= 15.0 and stum == 0 and errs == 0)
# E8/D1 (256): blok etap8_d1 - nagrody i wyplaty w zadaniach (QuestPay8.cs, GiverPay.cs)
E8_D1_DAY = "Nagrody zadan (E8/D1): dzien"
E8_D1_MIN = 40   # projekt: linia startu, N >= 40 (skan zywych bibliotek 1.4.8: 91 metod - gra 76, SandBox 13, ROT 1, NavalDLC 1)


def etap8_d1(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/D1 (256, projekt etapu 8 v2 rozdz. 3 "E8/D1" Test): nagrody zadan od zleceniodawcy w dniach zoldu, wyplaty gracza z odbiorca, towar zadan.
    Linie: start sesji "Nagrody zadan (E8/D1): wpiete N metod w M typach", doba "Nagrody zadan (E8/D1): dzien N", zdarzenia "przyjete", "wyplata",
    "gracz placi", "rzecz na wymiane". D1-1 linia startu: N >= 40, wpiete = kandydaci, BRAK: -, miejsca towaru i gettery nagrody komplet; D1-0b linia doby
    w kazdej dobie okna (bez pierwszej i ostatniej), cztery klucze czynne, latki komplet; D1-2 (suma okna) zloto z niczego 0 i w nicosc 0 - oba kierunki
    (bez wyplat - INFO, sprawdzenie reczne 8.16 p. 13); D1-3 obiecane = zaplacone + niedoplata przy pustej kiesie (rachunek sie zgadza), INFO niedoplaty;
    D1-4 towar z niczego 0 / w nicosc 0 (bez ruchu towaru - INFO); D1-5 INFO typy "kwota gry / po skali"; D1-6 INFO kwoty zamrozone; D1-7 INFO koszt;
    D1-K potkniecia i linie ERROR in QuestPay8.* 0."""
    rows = {d: s for d, s in by_day(lines, E8_D1_DAY).items() if 1 <= run_day(d, start) <= until}
    wire = [x for x in lines if x.startswith("Nagrody zadan (E8/D1): wpiete")]
    if not rows and not wire:
        rep.add("E8/D1: linie Nagrody zadan (E8/D1)", "brak w logu", "sa od wgrania E8/D1 (QuestPay8.cs)", None)
        return
    # ---------------- D1-1: linia startu
    if wire:
        w0 = wire[0]
        n, m = num(r"wpiete (\d+) metod", w0, int, 0), num(r"metod w (\d+) typach", w0, int, 0)
        cand = num(r"kandydatow (\d+)", w0, int, 0)
        gs = re.search(r"miejsc towaru (\d+)/(\d+)", w0)
        gt = re.search(r"gettery nagrody (\d+)/(\d+)", w0)
        calls = num(r"wywolan podmienionych: zloto (\d+)", w0, int, 0)
        asm = re.search(r"zestawy:([^;]*);", w0)
        ms = re.search(r"skan (\d+) ms, skan i wpiecie (\d+) ms", w0)
        ok = (n >= E8_D1_MIN and n == cand and "; BRAK: -;" in w0 and gs is not None and gs.group(1) == gs.group(2)
              and gt is not None and gt.group(1) == gt.group(2) and int(gt.group(2)) > 0)
        rep.add("D1-1: linia startu - latki na metodach zadan (wyplaty, towar, gettery nagrody)",
                f"wpiete {n} metod w {m} typach (kandydatow {cand}), wywolan zlota {calls}, miejsc towaru {gs.group(1) + '/' + gs.group(2) if gs else '?'}, "
                f"gettery {gt.group(1) + '/' + gt.group(2) if gt else '?'}; zestawy:{asm.group(1) if asm else ' ?'}"
                + (f"; skan {ms.group(1)} ms, razem {ms.group(2)} ms" if ms else "") + ("" if "; BRAK: -;" in w0 else " | " + w0[w0.find("BRAK:"):][:200]),
                f"N >= {E8_D1_MIN}, wpiete = kandydaci, BRAK: -, miejsca towaru i gettery komplet", ok)
    else:
        rep.add("D1-1: linia startu", "brak linii Nagrody zadan (E8/D1): wpiete", f"N >= {E8_D1_MIN}", False)
    if not rows:
        rep.add("D1-0b: linia Nagrody zadan (E8/D1)", "brak linii doby", "codziennie w oknie", False)
        return
    days = sorted(rows)
    w = [rows[d] for d in days]
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rows]
    keys = ("Quest Reward From Giver", "Quest Reward In Wage Days", "Quest Player Pays Someone", "Quest Goods Real")
    val = f"linii {len(days)}, dob okna {len(inner)}" + (f", brak w {len(miss)} (doby {miss[:5]})" if miss else ", komplet")
    off_any = False
    for nm in keys:
        off = [d for d in days if nm + " WYLACZONE" in rows[d]]
        if off:
            off_any = True
            val += f"; {nm} WYLACZONE w {len(off)} dobach"
    wired = [(num(r"latki wpiete (\d+)/\d+", x), num(r"latki wpiete \d+/(\d+)", x)) for x in w]
    bad_w = sum(1 for (a, b), x in zip(wired, w) if a is None or a != b or "(BRAK:" in x)
    if bad_w:
        val += f"; latki niekompletne w {bad_w} liniach"
    rep.add("D1-0b: linia Nagrody zadan (E8/D1) w kazdej dobie okna, cztery klucze czynne, latki komplet", val,
            "komplet (bez pierwszej i ostatniej doby), WYLACZONE 0", (not miss and not off_any and not bad_w) if inner else None)

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)
    # ---------------- D1-2 / D1-3: zloto w obu kierunkach
    n_in, game, due = tot(r"nic -> gracz\): (\d+),"), tot(r"nic -> gracz\): \d+, kwota gry (\d+)"), tot(r"kwota gry \d+, obiecane (\d+)")
    paid, p_hero, p_vil = tot(r"obiecane \d+, zaplacone (\d+)"), tot(r"\(zleceniodawcy (\d+)"), tot(r"kiesy wsi (\d+)\)")
    short, short_n, nothing = tot(r"niedoplata przy pustej kiesie (\d+) w"), tot(r"niedoplata przy pustej kiesie \d+ w (\d+) wyplatach"), tot(r"wyplatach, z niczego (\d+)")
    n_out, out_all = tot(r"gracz -> nic\): (\d+),"), tot(r"gracz -> nic\): \d+, kwota (\d+):")
    o_town, o_hero, o_vil, void = tot(r"do kas osad (\d+)"), tot(r"do zleceniodawcow (\d+)"), tot(r"do kies wsi (\d+)"), tot(r"do kies wsi \d+, w nicosc (\d+)")
    nopay = sorted({t.strip() for x in w for g in re.findall(r"\[brak platnika: ([^\]]*)\]", x) for t in g.split(",") if t.strip()})
    if n_in > 0 or n_out > 0:
        rep.add("D1-2: zloto zadan (suma okna) - z niczego (nic -> gracz) i w nicosc (gracz -> nic)",
                f"z niczego {nothing}" + (f" [brak platnika: {', '.join(nopay)}]" if nopay else "") + f", w nicosc {void}; wyplat dla gracza {n_in}: kwota gry {game} -> obiecane {due}"
                f", zaplacone {paid} (zleceniodawcy {p_hero}, kiesy wsi {p_vil}); wyplat gracza {n_out}: {out_all} (kasy osad {o_town}, zleceniodawcy {o_hero}, kiesy wsi {o_vil})",
                "0 / 0", nothing == 0 and void == 0)
        rep.add("D1-3: obiecane = zaplacone, gdy platnik ma pieniadze (obiecane = zaplacone + niedoplata przy pustej kiesie + z niczego)",
                f"obiecane {due}, zaplacone {paid}, niedoplata {short} w {short_n} wyplatach, z niczego {nothing}; roznica rachunku {due - paid - short - nothing}",
                "roznica rachunku 0 (niedoplata tylko przy pustej kiesie platnika - bez doplat)", due == paid + short + nothing)
    else:
        rep.add("D1-2: zloto zadan (z niczego / w nicosc)", "gracz nie dostal ani nie zaplacil nic w zadaniach w oknie (autotest nie robi zadan)",
                "INFO - sprawdzenie reczne 8.16 p. 13 (oferta w nowej skali, zloto od zleceniodawcy, tyle, ile obiecal)", None)
        rep.add("D1-3: obiecane = zaplacone", "bez wyplat w oknie", "INFO - 8.16 p. 13", None)
    # ---------------- D1-4: towar
    g_shelf, g_tabor, g_from = tot(r"od gracza na polke osady (\d+) szt"), tot(r"do taboru zleceniodawcy (\d+) szt"), tot(r"z magazynu osady (\d+) szt")
    g_miss, g_gold, g_gshort = tot(r"zabraklo (\d+) szt"), tot(r"zamiast nich zloto (\d+)"), tot(r"zamiast nich zloto \d+ \(niedoplata (\d+)\)")
    g_nothing, g_void = tot(r"towar z niczego (\d+) szt"), tot(r"/ w nicosc (\d+) szt")
    if g_shelf + g_tabor + g_from + g_miss + g_nothing + g_void > 0:
        rep.add("D1-4: towar zadan (suma okna) - z niczego / w nicosc",
                f"z niczego {g_nothing} szt. / w nicosc {g_void} szt.; od gracza: polka osady {g_shelf}, tabor zleceniodawcy {g_tabor}; dla gracza z magazynu osady {g_from}"
                f", zabraklo {g_miss} szt. - zamiast nich zloto {g_gold} (niedoplata {g_gshort})", "0 / 0", g_nothing == 0 and g_void == 0)
    else:
        rep.add("D1-4: towar zadan (z niczego / w nicosc)", "bez ruchu towaru zadan w oknie (autotest nie robi zadan)",
                "INFO - sprawdzenie reczne 8.16 p. 13 (dostawa trafia do zleceniodawcy albo na polke osady)", None)
    # ---------------- D1-5: typy
    types = {}
    for x in w:
        seg = re.search(r"\| typy \(wyplat: kwota gry / po skali\):(.*?) \| latki wpiete", x)
        if not seg:
            continue
        for g in re.finditer(r"(\S+) (\d+): (\d+) / (\d+)", seg.group(1)):
            a = types.setdefault(g.group(1), [0, 0, 0])
            a[0] += int(g.group(2)); a[1] += int(g.group(3)); a[2] += int(g.group(4))
    rep.add("D1-5: typy zadan (suma okna) - wyplat: kwota gry / po skali",
            "; ".join(f"{k} {v[0]}: {v[1]} / {v[2]}" for k, v in sorted(types.items())) if types else "bez wyplat w oknie", "INFO (skala: N ludzi x D dni x zold x 1.25; dostawy - tylko stala czesc)", None)
    # ---------------- D1-6: kwoty zamrozone
    frozen_new, closed = tot(r"przyjete dzis (\d+)"), tot(r"zamkniete (\d+),")
    f_pay, f_now, shown = tot(r"wyplat z kwota zamrozona (\d+)"), tot(r"liczonych przy wyplacie (\d+)"), tot(r"oferta pokazana po skali (\d+) razy")
    mem = num(r"kwoty zamrozone: w pamieci (\d+)", rows[days[-1]], int, 0)
    ev = {k: sum(1 for x in lines if x.startswith("Nagrody zadan (E8/D1): " + k)) for k in ("przyjete", "wyplata", "gracz placi", "rzecz na wymiane")}
    rep.add("D1-6: kwoty zamrozone przy przyjeciu (suma okna) i linie zdarzen w logu",
            f"przyjete {frozen_new}, zamkniete {closed}, w pamieci na koniec {mem}; wyplat z kwota zamrozona {f_pay}, liczonych przy wyplacie {f_now} (stary zapis / rozwiazanie przez lorda)"
            f"; oferta pokazana po skali {shown} razy; linie: przyjete {ev['przyjete']}, wyplata {ev['wyplata']}, gracz placi {ev['gracz placi']}, rzecz na wymiane {ev['rzecz na wymiane']}",
            "INFO", None)
    # ---------------- D1-7 / D1-K: koszt i kontrola
    cs = [c for c in (fnum(r"koszt ([0-9.]+) ms/dobe", x) for x in w) if c is not None]
    if cs:
        rep.add("D1-7: koszt linii doby", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms", "INFO (skan przy starcie - w linii startu)", None)
    stu = tot(r"potkniecia dzis (\d+)")
    stu_s = max([num(r"potkniecia (\d+)\.$", x, int, 0) or 0 for x in wire] or [0])
    errs = sum(1 for s in lines if s.startswith("ERROR in QuestPay8."))
    rep.add("D1-K: kontrola (potkniecia doby / w linii startu, linie ERROR in QuestPay8.*)", f"{stu} / {stu_s} / {errs}", "0 / 0 / 0", stu == 0 and stu_s == 0 and errs == 0)


# E8/D2 (257): blok etap8_d2 - nagroda turnieju gracza, zaklady, oplaty i drobne zrodla gracza (PlayerFees8.cs; RealPayer.cs - tylko migawka sakw)
E8_D2_DAY = "Wydatki gracza (E8/D2): dzien"
E8_D2_MIN = 21   # latki bez cudzych modow (Tournaments XPanded 2, NavalDLC 1); u Jeffa 24
E8_D2_SNAP = "platnik: nagroda turnieju (GivePrizeToWinner)"   # etykieta Seal31.Patch (RealPayer.ApplyAll) - w jej prefiksie biegnie migawka sakw gracza


def etap8_d2(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/D2 (257, projekt etapu 8 v2 rozdz. 3 "E8/D2" Test): oplaty i zaklady gracza z odbiorca, nagroda turnieju gracza z polki albo cena z kasy miasta,
    drobne zrodla z platnikiem. Linie: start sesji "Wydatki gracza (E8/D2): wpiete N/M latek", doba "Wydatki gracza (E8/D2): dzien N", zdarzenia
    "lapowka strazy", "odbicie wieznia", "nagroda turnieju". D2-0 linia startu: wpiete N/M komplet (N >= 21), podmiany komplet, BRAK: -, modele gry;
    D2-0b linia doby w kazdej dobie okna, cztery klucze czynne, latki komplet; D2-1 (suma okna) oplaty i zaklady: w nicosc 0 i z niczego 0 (bez wydatkow -
    INFO, 8.16 p. 12 i 14); D2-2 nagroda turnieju gracza: przedmiot z niczego 0, zloto z niczego 0 (bez wygranej - INFO, 8.16 p. 12); D2-2b drobne zrodla
    z niczego 0 (bez zdarzen - INFO); D2-3 kontrolka RealPayer (linia "Szczelnosc (164a)"): czynny, jency / nagrody turniejow / gracz u posrednika policzone,
    niedopasowane 0 i stos 0 - dowod, ze E8/D2 nie dubluje RealPayer (sumy do porownania z Z33), oraz latka "platnik: nagroda turnieju" wpieta przy starcie
    gry (w jej prefiksie biegnie migawka sakw gracza - recenzja E8/D2); D2-4 kasa miasta ponizej zapasu przez nasza wyplate 0;
    D2-5 INFO oplaty wedlug rodzaju (zaplacone / gra chciala), odbiorcy; D2-6 INFO koszt; D2-K potkniecia i linie ERROR in PlayerFees8.* 0."""
    rows = {d: s for d, s in by_day(lines, E8_D2_DAY).items() if 1 <= run_day(d, start) <= until}
    wire = [x for x in lines if x.startswith("Wydatki gracza (E8/D2): wpiete")]
    if not rows and not wire:
        rep.add("E8/D2: linie Wydatki gracza (E8/D2)", "brak w logu", "sa od wgrania E8/D2 (PlayerFees8.cs)", None)
        return
    # ---------------- D2-0: linia startu
    if wire:
        w0 = wire[0]
        m = re.search(r"wpiete (\d+)/(\d+) latek", w0)
        c = re.search(r"podmian wywolan (\d+)/(\d+), stalych (\d+)/(\d+)", w0)
        absent = re.search(r"mody nieobecne: (.*?); modele:", w0)
        models = re.search(r"modele: (.*?); zwrot ceny warsztatu", w0)
        ok = (m is not None and c is not None and m.group(1) == m.group(2) and int(m.group(2)) >= E8_D2_MIN and c.group(1) == c.group(2) and c.group(3) == c.group(4)
              and "; BRAK: -;" in w0 and "INNY MODEL" not in w0)
        rep.add("D2-0: linia startu - latki w miejscach wyplat gracza (wrappery, stale oplat, modele lapowek)",
                (f"wpiete {m.group(1)}/{m.group(2)}" if m else "wpiete ?") + (f", podmian wywolan {c.group(1)}/{c.group(2)}, stalych {c.group(3)}/{c.group(4)}" if c else "")
                + (f"; mody nieobecne: {absent.group(1)}" if absent else "") + (f"; modele: {models.group(1)}" if models else "")
                + ("" if "; BRAK: -;" in w0 else " | " + w0[w0.find("BRAK:"):][:220]),
                f"N = M >= {E8_D2_MIN}, podmiany komplet, BRAK: -, modele gry (Default...)", ok)
    else:
        rep.add("D2-0: linia startu", "brak linii Wydatki gracza (E8/D2): wpiete", "wpiete N/M komplet", False)
    if not rows:
        rep.add("D2-0b: linia Wydatki gracza (E8/D2)", "brak linii doby", "codziennie w oknie", False)
        return
    days = sorted(rows)
    w = [rows[d] for d in days]
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rows]
    keys = ("Player Tourney Prize From Town", "Player Bets Counterparty", "Player Fees Historical", "Player Small Sources Closed")
    val = f"linii {len(days)}, dob okna {len(inner)}" + (f", brak w {len(miss)} (doby {miss[:5]})" if miss else ", komplet")
    off_any = False
    for nm in keys:
        off = [d for d in days if nm + " WYLACZONE" in rows[d]]
        if off:
            off_any = True
            val += f"; {nm} WYLACZONE w {len(off)} dobach"
    wired = [(num(r"latki wpiete (\d+)/\d+", x), num(r"latki wpiete \d+/(\d+)", x)) for x in w]
    bad_w = sum(1 for (a, b), x in zip(wired, w) if a is None or a != b or "(BRAK:" in x)
    if bad_w:
        val += f"; latki niekompletne w {bad_w} liniach"
    rep.add("D2-0b: linia Wydatki gracza (E8/D2) w kazdej dobie okna, cztery klucze czynne, latki komplet", val,
            "komplet (bez pierwszej i ostatniej doby), WYLACZONE 0", (not miss and not off_any and not bad_w) if inner else None)

    def tot(pat):
        return sum(num(pat, x, int, 0) or 0 for x in w)

    def src(label):
        """(liczba, nalezne, zaplacone, niedoplata, z niczego) zrodla o etykiecie label - suma okna."""
        p = re.escape(label) + r" (\d+), nalezne (\d+), zaplacone (\d+), niedoplata (\d+) w (\d+), z niczego (\d+)"
        out = [0, 0, 0, 0, 0]
        for x in w:
            g = re.search(p, x)
            if g:
                out[0] += int(g.group(1)); out[1] += int(g.group(2)); out[2] += int(g.group(3)); out[3] += int(g.group(4)); out[4] += int(g.group(6))
        return out
    # ---------------- D2-1: oplaty i zaklady
    f_n, f_sum, f_game = tot(r"oplaty \(gracz -> odbiorca\): (\d+),"), tot(r"oplaty \(gracz -> odbiorca\): \d+, kwota (\d+)"), tot(r"kwota \d+ \(gra chciala (\d+)\)")
    to_g, to_c, to_t, to_f = tot(r"do sakiewek zalog (\d+)"), tot(r"do kies zalog (\d+)"), tot(r"do kas osad (\d+), do kiesy ludu"), tot(r"do kiesy ludu (\d+)")
    f_void = tot(r"oplaty w nicosc (\d+)")
    s_n, s_sum, s_void = tot(r"turniej - postawione (\d+):"), tot(r"turniej - postawione \d+: (\d+)"), tot(r"stawki w nicosc (\d+)")
    l_n, l_sum, l_kept, l_noth = tot(r"przegrane (\d+): \d+ \(zostalo"), tot(r"przegrane \d+: (\d+) \(zostalo"), tot(r"zostalo w kasie (\d+)"), tot(r"kasie z niczego (\d+)")
    stale = tot(r"stawki z przerwanych turniejow w kasie (\d+)")
    b_n, b_sum, b_void = tot(r"plansza - przegrane (\d+):"), tot(r"plansza - przegrane \d+: (\d+)"), tot(r"plansza w nicosc (\d+)")
    won, bwon = src("wygrane turnieju"), src("wygrane planszy")
    if f_n + s_n + l_n + b_n + won[0] + bwon[0] > 0:
        void_all, noth_all = f_void + s_void + b_void, l_noth + won[4] + bwon[4]
        rep.add("D2-1: oplaty i zaklady gracza (suma okna) - w nicosc / z niczego",
                f"w nicosc {void_all} (oplaty {f_void}, stawki {s_void}, plansza {b_void}) / z niczego {noth_all} (przegrana dopisana kasie {l_noth}, wygrane turnieju {won[4]}, planszy {bwon[4]})"
                f"; oplaty {f_n}: {f_sum} (gra chciala {f_game}) -> sakiewki zalog {to_g}, kiesy zalog {to_c}, kasy osad {to_t}, kiesa ludu {to_f}"
                f"; zaklad turniejowy: postawione {s_n}: {s_sum}, przegrane {l_n}: {l_sum} (w kasie {l_kept}), wygrane {won[0]}: nalezne {won[1]}, zaplacone {won[2]}, niedoplata {won[3]}"
                f"; plansza: przegrane {b_n}: {b_sum}, wygrane {bwon[0]}: nalezne {bwon[1]}, zaplacone {bwon[2]}, niedoplata {bwon[3]}" + (f"; stawki z przerwanych turniejow w kasie {stale}" if stale else ""),
                "0 / 0", void_all == 0 and noth_all == 0)
    else:
        rep.add("D2-1: oplaty i zaklady gracza (w nicosc / z niczego)", "gracz nie placil oplat i nie stawial zakladow w oknie (autotest tego nie robi)",
                "INFO - sprawdzenie reczne 8.16 p. 12 (zaklad) i p. 14 (lapowka 60 / 36 / 6, golibroda 3, karczmarz 12, kolejka 0.3 na czlowieka)", None)
    # ---------------- D2-2: nagroda turnieju gracza i zloto TXP
    pz_n, pz_shelf, pz_alt = tot(r"nagroda turnieju gracza: (\d+) szt"), tot(r"z polki miasta (\d+)"), tot(r"w tym w stanie z polki (\d+)")
    pz_noth, pz_noth_v, pz_noitem = tot(r"przedmiot z niczego (\d+) szt"), tot(r"przedmiot z niczego \d+ szt\. o wartosci (\d+)"), tot(r"wygrane bez sztuki w sakwach (\d+)")
    pg, txp = src("cena zamiast przedmiotu"), src("zloto TXP")
    if pz_n + pz_noitem + txp[0] > 0:
        rep.add("D2-2: nagroda turnieju gracza (suma okna) - przedmiot z polki / cena od miasta, z niczego",
                f"z niczego: przedmiot {pz_noth} szt. (wartosc {pz_noth_v}), cena {pg[4]}, zloto TXP {txp[4]}; nagrod {pz_n}: z polki miasta {pz_shelf} (w stanie z polki {pz_alt})"
                f", cena zamiast przedmiotu {pg[0]}: nalezne {pg[1]}, zaplacone {pg[2]}, niedoplata {pg[3]}; zloto TXP {txp[0]}: nalezne {txp[1]}, zaplacone {txp[2]}, niedoplata {txp[3]}"
                + (f"; wygrane bez sztuki w sakwach {pz_noitem} (inny mod wydal nagrode inaczej)" if pz_noitem else ""),
                "z niczego 0 (przedmiot, cena, zloto TXP); kazda nagroda z polki albo ceny", pz_noth == 0 and pg[4] == 0 and txp[4] == 0 and pz_n == pz_shelf + pg[0])
    else:
        rep.add("D2-2: nagroda turnieju gracza (z polki / cena od miasta)", "gracz nie wygral turnieju w oknie (autotest nie walczy w turniejach)",
                "INFO - sprawdzenie reczne 8.16 p. 12 (przedmiot znika z polki miasta albo cena z kasy miasta)", None)
    # ---------------- D2-2b: drobne zrodla
    arena, force = src("arena"), src("zapasy wsi")
    ed, ed_pay = tot(r"pominiete rozliczenia (\d+)"), tot(r"pominiete rozliczenia \d+ \(z wyplata (\d+)\)")
    if arena[0] + force[0] > 0:
        rep.add("D2-2b: drobne zrodla gracza (suma okna) - z niczego",
                f"z niczego {arena[4] + force[4]}; arena {arena[0]}: nalezne {arena[1]}, zaplacone {arena[2]}, niedoplata {arena[3]}; zapasy wsi {force[0]}: nalezne {force[1]}, zaplacone {force[2]}, niedoplata {force[3]}"
                f"; edykt strazy wybrzeza - pominiete rozliczenia {ed} (z wyplata {ed_pay})", "0", arena[4] + force[4] == 0)
    else:
        rep.add("D2-2b: drobne zrodla gracza (arena, wymuszone zapasy wsi)", f"bez zdarzen w oknie; edykt strazy wybrzeza - pominiete rozliczenia {ed} (z wyplata {ed_pay})",
                "INFO - sprawdzenie reczne 8.16 p. 15", None)
    # ---------------- D2-3: kontrolka RealPayer - E8/D2 nie dubluje (jency, nagrody turniejow AI)
    sea = {d: s for d, s in by_day(lines, "Szczelnosc (164a): dzien").items() if d in rows}
    if sea:
        sv = list(sea.values())

        def st(pat):
            return sum(num(pat, x, int, 0) or 0 for x in sv)
        pr_due, pr_paid = st(r"jency sprzedani przez partie: gra chciala (\d+)"), st(r"jency sprzedani przez partie: gra chciala \d+, zaplacili (\d+)")
        tr_due, tr_paid, tr_n = st(r"nagrody turniejow: gra chciala (\d+)"), st(r"nagrody turniejow: gra chciala \d+, zaplacili (\d+)"), st(r"nagrody turniejow: gra chciala \d+, zaplacili \d+, uciete \d+ \((\d+) wyplat")
        pl_due, pl_paid = st(r"gracz u posrednika i w miescie: wycena (\d+)"), st(r"gracz u posrednika i w miescie: wycena \d+, zaplacone (\d+)")
        strays, over = st(r"zdarzenia z niczego w kontekscie niedopasowane (\d+)"), st(r"stos przepelniony (\d+)")
        off = sum(1 for x in sv if "WYLACZONE (Town Pays Rewards)" in x)
        # recenzja E8/D2: migawka sakw gracza (PlayerFees8.PrizeBefore) biegnie w prefiksie RealPayer.TourneyPre - bez tej latki nagroda gracza nie jest
        # rozliczana, a licznik N/M paczki (D2-0) tego nie widzi; wpiecie pokazuje linia startu gry "Szczelnosc (164a): latki przy starcie gry"
        seal0 = [x for x in lines if x.startswith("Szczelnosc (164a): latki przy starcie gry")]
        snap = bool(seal0) and E8_D2_SNAP in seal0[0].split("; BRAK:")[0]
        rep.add("D2-3: kontrolka RealPayer (Szczelnosc 164a) - jency i nagrody turniejow AI dalej przez RealPayer, E8/D2 ich nie dubluje; latka z migawka sakw gracza wpieta",
                f"linii {len(sv)}, WYLACZONE w {off}; jency: gra chciala {pr_due}, zaplacili {pr_paid}; nagrody turniejow: gra chciala {tr_due}, zaplacili {tr_paid} ({tr_n} wyplat)"
                f"; gracz u posrednika: wycena {pl_due}, zaplacone {pl_paid}; niedopasowane {strays}, stos {over}"
                f"; latka \"{E8_D2_SNAP}\": " + ("wpieta" if snap else ("BRAK w linii startu gry" if seal0 else "brak linii startu gry Szczelnosc (164a)")),
                "RealPayer czynny, niedopasowane 0, stos 0, zaplacili <= gra chciala (sumy do porownania z Z33 - bez zmian); latka nagrody turnieju wpieta",
                off == 0 and strays == 0 and over == 0 and pr_paid <= pr_due and tr_paid <= tr_due and pl_paid <= pl_due and snap)
    else:
        rep.add("D2-3: kontrolka RealPayer (Szczelnosc 164a)", "brak linii Szczelnosc (164a) w dobach okna", "linia jest (RealPayer E3/1)", False)
    # ---------------- D2-4: zapas kupcow
    below = tot(r"kasa miasta ponizej zapasu kupcow przez nasza wyplate (\d+)")
    rep.add("D2-4: kasa miasta ponizej zapasu kupcow przez nasza wyplate (suma okna)", f"{below}", "0 (wyplaty tylko z nadwyzki Seal31.Spare; zwrot stawki gracza nie liczy sie)", below == 0)
    # ---------------- D2-5: oplaty wedlug rodzaju
    kinds = {}
    for x in w:
        seg = re.search(r"\(gra chciala \d+\):(.*?) - do sakiewek zalog", x)
        if not seg:
            continue
        for g in re.finditer(r"([^;:]+?) (\d+): (\d+) / (\d+)", seg.group(1)):
            a = kinds.setdefault(g.group(1).strip(), [0, 0, 0])
            a[0] += int(g.group(2)); a[1] += int(g.group(3)); a[2] += int(g.group(4))
    ev = {k: sum(1 for x in lines if x.startswith("Wydatki gracza (E8/D2): " + k)) for k in ("lapowka strazy", "odbicie wieznia", "nagroda turnieju")}
    rep.add("D2-5: oplaty wedlug rodzaju (suma okna) - razy: zaplacone / gra chciala; linie zdarzen",
            ("; ".join(f"{k} {v[0]}: {v[1]} / {v[2]}" for k, v in kinds.items() if v[0] > 0) or "bez oplat w oknie")
            + f"; linie: lapowka strazy {ev['lapowka strazy']}, odbicie wieznia {ev['odbicie wieznia']}, nagroda turnieju {ev['nagroda turnieju']}", "INFO", None)
    # ---------------- D2-6 / D2-K: koszt i kontrola
    cs = [c for c in (fnum(r"koszt ([0-9.]+) ms/dobe", x) for x in w) if c is not None]
    if cs:
        rep.add("D2-6: koszt linii doby", f"srednio {sum(cs) / len(cs):.2f} ms/dobe, najwiecej {max(cs):.2f} ms", "INFO (latki raz na proces - czas w linii startu)", None)
    stu = tot(r"potkniecia dzis (\d+)")
    stu_s = max([num(r"potkniecia (\d+)\.$", x, int, 0) or 0 for x in wire] or [0])
    errs = sum(1 for s in lines if s.startswith("ERROR in PlayerFees8."))
    rep.add("D2-K: kontrola (potkniecia doby / w linii startu, linie ERROR in PlayerFees8.*)", f"{stu} / {stu_s} / {errs}", "0 / 0 / 0", stu == 0 and stu_s == 0 and errs == 0)
# ============================================================ ETAP 8 (E8/R, paczka 254): rynek i korona - blok etap8_r
E8_R_LINE = "Rynek i korona (E8/R): dzien"
# Wzor Z33 (WGRANIE 33, Armoury-2026-10-12_02-44-09.log): 70 linii "ArmsPricing: wojna ... kupcy oczekuja zakupow broni" w 120 dobach; doba 120 (L:35865):
# 22 frakcje z premia, srednio +16% popytu, najwyzsza +63% (Tyrosh) = cena polki do x1.28 przy elastycznosci 0.5
E8_R_Z33_WAR_LINES = 70
E8_R_Z33_WAR_D120 = (22, 16, 63)
E8_R_PROBE_NEW = re.compile(r"nowa droga: zysk najwyzszy (-?\d+) zl, z zyskiem (\d+), sprzedaz/kupno mediana ([0-9.]+) \(([0-9.]+)-([0-9.]+)\)")
E8_R_PROBE_OLD = re.compile(r"stara droga: zysk najwyzszy (-?\d+) zl, z zyskiem (\d+), sprzedaz/kupno mediana ([0-9.]+) \(([0-9.]+)-([0-9.]+)\)")


def etap8_r(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/R (254, projekt etapu 8 v2 rozdz. 3 "E8/R" Test i rozdz. 4 pkt 5): linia doby "Rynek i korona (E8/R)" (MarketAndCrown.cs, z KingdomTreasury.Levies).
    R-0 linia w kazdej dobie okna i stan trzech kluczy; R-1 premie wojenne: przy kluczu [wyl] frakcji z premia 0 w kazdej dobie, 0 linii "kupcy oczekuja
    zakupow broni" i kazda linia "Rynek broni" okna z "premie wojenne: brak" (mnoznik ceny z premii x1.00 wobec Z33 do x1.28); R-2 proba kup-sprzedaj konia
    w jednym miescie: w dobach z kluczem [WL] zysk najwyzszy nowa droga <= 0 i 0 prob z zyskiem (stara droga - INFO, dwie drogi w jednej linii); wyceny
    sprzedazy koni nowa / stara droga - INFO; R-3 monopole: w dobach z kluczem [WL] i poborem > 0: wzieto <= 1/20 dziennej wyplaty wlascicielom tych
    warsztatow i nie wiecej niz stary wzor (pobor 0 w calym oknie - INFO z przyczyna z linii E8/P2); R-4 potkniecia 0, koszt proby INFO."""
    rl = {d: s for d, s in by_day(lines, E8_R_LINE).items() if 1 <= run_day(d, start) <= until}
    if not rl:
        rep.add("E8/R: linia Rynek i korona (E8/R)", "brak w logu", "jest od wgrania E8/R", None)
        return
    days = sorted(rl)
    nd = max(1, len(days))
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in rl]

    def on_days(tag):
        return [d for d in days if tag in rl[d]]

    def col(pat, cast=int, default=0):
        return {d: num(pat, rl[d], cast=cast, default=default) for d in days}

    def tot(c, sel=None):
        return sum(c[d] for d in (days if sel is None else sel))
    war_on, horse_on, mono_on = on_days("| premie wojenne [WL]"), on_days("| kon przy sprzedazy [WL]"), on_days("| monopole [WL]")
    horse_half = on_days("| kon przy sprzedazy [wyl - kupno nie z wartosci]")
    rep.add("R-0: linia Rynek i korona (E8/R) w kazdej dobie okna; stan kluczy",
            (f"{len(days)} dob (brak {len(miss)}" + (f": doby {miss[:5]}" + (" ..." if len(miss) > 5 else "") if miss else "") + f" z {len(inner)}); "
             f"WarExpectationEnabled wl {len(war_on)} / wyl {len(days) - len(war_on)} dob, HorseSellFromWorth wl {len(horse_on)} / wyl {len(days) - len(horse_on)}"
             + (f" (w tym {len(horse_half)} dob: klucz wlaczony, ale kupno nie z wartosci - RetailFromWorth albo ceny historyczne wylaczone)" if horse_half else "")
             + f", MonopolyFromDailyProfit wl {len(mono_on)} / wyl {len(days) - len(mono_on)}"),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    # R-1: premie oczekiwan wojennych
    wn, wmax = col(r"frakcji z premia (\d+)"), col(r"najwyzsza \+(\d+)%")
    war_off = [d for d in days if d not in war_on]
    prem_days = [d for d in war_off if wn[d] > 0]
    bumps = sum(1 for s in lines if s.startswith("ArmsPricing: wojna ") and "kupcy oczekuja zakupow broni" in s)
    mk_all, mk_prem, pend = 0, 0, None
    for s in lines:   # linia "Rynek broni" (bez etykiety doby) stoi przed "Pieniadz swiata: dzien N" tej samej doby
        if s.startswith("Rynek broni: na polkach"):
            pend = "premie wojenne: brak" not in s
        elif s.startswith("Pieniadz swiata: dzien") and pend is not None:
            d = num(r"dzien (\d+)", s)
            if d is not None and 1 <= run_day(d, start) <= until:
                mk_all += 1
                mk_prem += 1 if pend else 0
            pend = None
    top = max(wmax.values()) if wmax else 0
    z = E8_R_Z33_WAR_D120
    txt = (f"klucz [wyl] {len(war_off)} dob: dob z premia {len(prem_days)}, najwiecej frakcji z premia {max([wn[d] for d in war_off] + [0])}; linie 'Rynek broni' okna z premia "
           f"{mk_prem} z {mk_all}; linie 'kupcy oczekuja zakupow broni' (caly log) {bumps} (Z33: {E8_R_Z33_WAR_LINES}); najwyzsza premia okna +{top}% = cena polki najwyzej "
           f"x{(1 + top / 100.0) ** 0.5:.2f} przy elastycznosci 0.5 (Z33 doba 120: {z[0]} frakcje, srednio +{z[1]}%, najwyzsza +{z[2]}% = do x{(1 + z[2] / 100.0) ** 0.5:.2f})"
           + (f" | klucz [WL] {len(war_on)} dob: najwiecej frakcji z premia {max([wn[d] for d in war_on] + [0])}" if war_on else ""))
    rep.add("R-1: ceny broni w wojnie bez premii oczekiwan (popyt wojenny tylko z prawdziwych zamowien armii)", txt,
            "przy kluczu [wyl]: 0 dob z premia, 0 linii 'kupcy oczekuja', kazda linia 'Rynek broni' z 'premie wojenne: brak' (mnoznik z premii x1.00 <= Z33)",
            (not prem_days and bumps == 0 and mk_prem == 0) if (war_off and not war_on) else None)

    # R-2: proba kup-sprzedaj konia w jednym miescie (dwie drogi w jednej linii)
    seen, probed, failed = col(r"proba kup-sprzedaj konia \([^)]*\): osad (\d+)"), col(r"z koniem na polce (\d+)"), col(r", nieudane (\d+)")
    pn, po = {}, {}
    for d in days:
        a, b = E8_R_PROBE_NEW.search(rl[d]), E8_R_PROBE_OLD.search(rl[d])
        if a and b:
            pn[d] = (int(a.group(1)), int(a.group(2)), float(a.group(3)), float(a.group(4)), float(a.group(5)))
            po[d] = (int(b.group(1)), int(b.group(2)), float(b.group(3)), float(b.group(4)), float(b.group(5)))
    pd_ = sorted(pn)

    def way(p, sel):
        if not sel:
            return "brak prob"
        med = sorted(p[d][2] for d in sel)
        return (f"zysk najwyzszy {max(p[d][0] for d in sel)} zl, prob z zyskiem {sum(p[d][1] for d in sel)} w {sum(1 for d in sel if p[d][1] > 0)} dobach, "
                f"sprzedaz/kupno mediana dob {med[len(med) // 2]:.2f} (zakres {min(p[d][3] for d in sel):.2f}-{max(p[d][4] for d in sel):.2f})")
    on_p = [d for d in pd_ if d in horse_on]
    off_p = [d for d in pd_ if d not in horse_on]
    head = (f"proby w {len(pd_)} dobach: osad sprawdzonych {tot(seen)}, z koniem na polce {tot(probed)}, nieudane {tot(failed)}"
            + (f" | klucz [WL] {len(on_p)} dob - nowa droga: {way(pn, on_p)}; stara droga dalaby: {way(po, on_p)}" if on_p else "")
            + (f" | klucz wylaczony {len(off_p)} dob - stara droga (czynna): {way(po, off_p)}; nowa dalaby: {way(pn, off_p)}" if off_p else ""))
    worst = None
    if on_p:
        wd = max(on_p, key=lambda d: pn[d][0])
        m = re.search(r"najblizej zysku nowa droga: (.*?) \| monopole", rl[wd])
        worst = f" | najblizej zysku: doba {run_day(wd, start)} {m.group(1)[:90]}" if m else ""
    rep.add("R-2: kup konia i sprzedaj w tym samym miescie nie zarabia (proba, jak przy paczce 155)", head + (worst or ""),
            "w dobach z kluczem [WL]: zysk najwyzszy nowa droga <= 0 i 0 prob z zyskiem (stara droga - INFO); bez prob z kluczem [WL] - INFO",
            (max(pn[d][0] for d in on_p) <= 0 and sum(pn[d][1] for d in on_p) == 0) if on_p else None)
    hs_n, hs_old, hs_new = col(r"wycen sprzedazy koni nowa droga (\d+)"), col(r"stara droga dalaby razem (\d+) zl"), col(r"stara droga dalaby razem \d+ zl, nowa (\d+) zl")
    rep.add("E8/R: wyceny sprzedazy koni w miastach i zamkach (kazda wycena, takze podglad ceny)",
            (f"{tot(hs_n)} wycen nowa droga w oknie ({tot(hs_n) / nd:.0f}/d): stara droga dalaby {tot(hs_old)} zl, nowa {tot(hs_new)} zl"
             + (f" = x{tot(hs_new) / tot(hs_old):.2f}" if tot(hs_old) > 0 else "")),
            "INFO (kon liczony raz: zawalona polka placi wiecej niz dotad, pusta mniej; kasy miast - prog wspolny C-4)", None)

    # R-3: monopole korony
    taken, shops = col(r"monopole \[[^\]]*\]: wzieto (\d+) zl"), col(r"monopole \[[^\]]*\]: wzieto \d+ zl z (\d+) warsztatow")
    payout = {d: num(r"dzienna wyplata wlascicielom tych warsztatow (\d+) zl", rl[d]) for d in days}
    oldw = col(r"stary wzor \(5% stanu zysku\) wzialby (\d+) zl")
    nodata = [d for d in days if "]: brak danych tej doby" in rl[d]]
    on_t = [d for d in mono_on if taken[d] > 0]
    over = [run_day(d, start) for d in on_t if payout[d] is None or taken[d] * 20 > payout[d]]
    more = [run_day(d, start) for d in on_t if taken[d] > oldw[d]]
    why = {}
    for d, s in by_day(lines, E8_P2_MONO).items():
        if d in rl:
            m = re.search(r"\| przyczyna 0: (.*)\.$", s)
            k = m.group(1) if m else "?"
            why[k] = why.get(k, 0) + 1
    wtxt = ("; przyczyna 0 (linia E8/P2): " + ", ".join(f"{k} x{v}" for k, v in sorted(why.items(), key=lambda kv: -kv[1]))) if why else "; linii E8/P2 brak"
    off_m = [d for d in days if d not in mono_on]
    txt = (f"klucz [WL] {len(mono_on)} dob: wzieto {tot(taken, mono_on)} zl w {len(on_t)} dobach z {tot(shops, on_t)} warsztato-dob, dzienna wyplata wlascicielom tych warsztatow "
           f"{sum(payout[d] or 0 for d in on_t)} zl (pobor = {100.0 * tot(taken, on_t) / max(1, sum(payout[d] or 0 for d in on_t)):.1f}% wyplaty), stary wzor wzialby "
           f"{tot(oldw, mono_on)} zl" + (f"; ponad 1/20 wyplaty w dobach {over[:5]}" if over else "") + (f"; ponad stary wzor w dobach {more[:5]}" if more else "")
           + (f" | klucz wylaczony {len(off_m)} dob: wzieto {tot(taken, off_m)} zl (stary wzor)" if off_m else "")
           + (f" | bez danych (wyjatek w Levies) {len(nodata)} dob" if nodata else "") + ("" if on_t else wtxt))
    rep.add("R-3: monopole korony - 5% dziennej wyplaty wlascicielowi warsztatu", txt,
            "w dobach z kluczem [WL] i poborem > 0: wzieto <= 1/20 dziennej wyplaty tych warsztatow i <= stary wzor; pobor 0 w calym oknie - INFO (przyczyna w E8/P2)",
            (not over and not more) if on_t else None)

    # R-4: potkniecia i koszt proby
    stum = max([num(r"potkniecia \(sesja\) (\d+)", rl[d], default=0) for d in days] + [0])
    cost = col(r"koszt proby ([0-9.]+) ms", cast=float, default=0.0)
    rep.add("R-4: potkniecia E8/R i koszt proby kup-sprzedaj", f"potkniecia (sesja) {stum}; koszt proby srednio {sum(cost.values()) / nd:.1f} ms/d, najwiecej {max(cost.values()) if cost else 0.0:.1f} ms",
            "potkniecia 0 (koszt - INFO; projekt: koszt paczki ok. 0)", stum == 0)


# ============================================================ ETAP 8 (E8/B, paczka 258): warsztaty i kowadlo - blok etap8_b
E8_B_BY_LINE = "Wyroby uboczne (E8/B): dzien"
E8_B_FIX_LINE = "Kowadlo i drobne (E8/B): dzien"
# Wzor Z33 (WGRANIE 33, Armoury-2026-10-12_02-44-09.log): "Towary: dzien 108955 - wool (83 d): zapas 8737" (doba 120; doba 1: 2175)
E8_B_Z33_WOOL_D120 = 8737


def etap8_b(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/B (258, projekt etapu 8 v2 rozdz. 3 "E8/B" Test; odpowiedz Jeffa 12.10 nr 5): linie doby "Wyroby uboczne (E8/B)" (ArtisanInputs.cs) i "Kowadlo
    i drobne (E8/B)" (SmallFixes8.cs). B-0 obie linie w kazdej dobie okna i stan kluczy; B-1 wyroby uboczne: przy kluczu [WL] dopisane > 0, gdy stara
    regula cos gubila, kasy ponizej zapasu przez nasza wyplate 0 w kazdej dobie, potkniecia 0 (zaplata kas miast, sztuki bez zaplaty, niesprzedane - INFO);
    B-2 welna (INFO): zapas welny w ostatniej dobie okna wobec Z33, pelne sztuki z licznikow i zdjete ponad regule; B-3 ksiega licznikow welny zamknieta:
    liczniki dzis = wczoraj + dopisane - pelne sztuki (+-0.05 szt. na dobe; liczby linii maja 2 miejsca); B-4 linia startu ekranu rodu (wpiete 1/1),
    potkniecia 0, robocizna gracza do ludu <= robocizna; liczby kowadla INFO (gracz w autotescie nie kuje i nie naprawia - sprawdzenia reczne 8.16)."""
    bl = {d: s for d, s in by_day(lines, E8_B_BY_LINE).items() if 1 <= run_day(d, start) <= until}
    fl = {d: s for d, s in by_day(lines, E8_B_FIX_LINE).items() if 1 <= run_day(d, start) <= until}
    if not bl and not fl:
        rep.add("E8/B: linie Wyroby uboczne (E8/B) i Kowadlo i drobne (E8/B)", "brak w logu", "sa od wgrania E8/B", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss_b = [run_day(d, start) for d in inner if d not in bl]
    miss_f = [run_day(d, start) for d in inner if d not in fl]
    bdays, fdays = sorted(bl), sorted(fl)
    nb = max(1, len(bdays))
    by_on = [d for d in bdays if "ArtisanByproductsFull [WL]" in bl[d]]

    def keys_of(tag):
        return sum(1 for d in fdays if (tag + " [WL]") in fl[d])
    rep.add("B-0: linie Wyroby uboczne (E8/B) i Kowadlo i drobne (E8/B) w kazdej dobie okna; stan kluczy",
            (f"wyroby uboczne {len(bdays)} dob (brak {len(miss_b)}" + (f": doby {miss_b[:5]}" if miss_b else "") + f"), kowadlo {len(fdays)} dob (brak {len(miss_f)}"
             + (f": doby {miss_f[:5]}" if miss_f else "") + f") z {len(inner)}; ArtisanByproductsFull wl {len(by_on)} / wyl {len(bdays) - len(by_on)} dob; "
             f"z {len(fdays)} dob kowadla: ArmourBotchHalfBack wl {keys_of('ArmourBotchHalfBack')}, MendTakeByKind wl {keys_of('MendTakeByKind')}, "
             f"PlayerMineBulkSkip wl {keys_of('PlayerMineBulkSkip')}, SmallFixes8 wl {keys_of('SmallFixes8')}, robocizna gracza do ludu wl {keys_of('robocizna gracza do ludu')}"),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss_b and not miss_f) if inner else None)

    def col(pat, src, days, cast=int, default=0):
        return {d: num(pat, src[d], cast=cast, default=default) for d in days}

    def tot(c, sel):
        return sum(c[d] for d in sel)

    # B-1: wyroby uboczne z kazdego cyklu
    if bdays:
        lost = col(r"bez wyrobu zostawalo (\d+) szt\.", bl, bdays)
        added = col(r"\| dopisane (\d+) szt\.", bl, bdays)
        paid = col(r"zaplacone przez kasy miast (\d+) zl", bl, bdays)
        below = col(r"kasy ponizej zapasu przez nasza wyplate (\d+)\)", bl, bdays)
        free = col(r"bez zaplaty \(start gry albo linia bez zlota\) (\d+) szt\.", bl, bdays)
        unsold = col(r"niesprzedane (\d+) szt\.", bl, bdays)
        unsold_v = col(r"niesprzedane \d+ szt\. warte (\d+) zl", bl, bdays)
        stum = col(r"\| potkniecia (\d+)\.", bl, bdays)
        kinds = {}
        for d in by_on:
            m = re.search(r"\| dopisane \d+ szt\. \[([^\]]*)\]", bl[d])
            if m and m.group(1) != "nic":
                for part in m.group(1).split(", "):
                    k, _, v = part.rpartition(" ")
                    if v.isdigit():
                        kinds[k] = kinds.get(k, 0) + int(v)
        off = [d for d in bdays if d not in by_on]
        below_days = [run_day(d, start) for d in bdays if below[d] > 0]
        ok = None
        if by_on:
            ok = (tot(added, by_on) > 0 or tot(lost, by_on) == 0) and not below_days and tot(stum, bdays) == 0
        txt = (f"klucz [WL] {len(by_on)} dob: stara regula zostawilaby bez wyrobu {tot(lost, by_on)} szt. ({tot(lost, by_on) / max(1, len(by_on)):.0f}/d), dopisane "
               f"{tot(added, by_on)} szt. ({tot(added, by_on) / max(1, len(by_on)):.0f}/d)"
               + (" [" + ", ".join(f"{k} {v}" for k, v in sorted(kinds.items(), key=lambda kv: -kv[1])) + "]" if kinds else "")
               + f", zaplacone przez kasy miast {tot(paid, by_on)} zl z nadwyzki, bez zaplaty {tot(free, by_on)} szt., niesprzedane {tot(unsold, by_on)} szt. warte "
               f"{tot(unsold_v, by_on)} zl; kasy ponizej zapasu przez nasza wyplate {tot(below, bdays)}" + (f" (doby {below_days[:5]})" if below_days else "")
               + f"; potkniecia {tot(stum, bdays)}" + (f" | klucz wylaczony {len(off)} dob: stara regula zostawila bez wyrobu {tot(lost, off)} szt., dopisane {tot(added, off)}" if off else ""))
        rep.add("B-1: wyroby uboczne rzemieslnikow z kazdego cyklu, zaplacone przez kasy miast z nadwyzki", txt,
                "przy kluczu [WL]: dopisane > 0, gdy stara regula cos gubila; kasy ponizej zapasu przez nasza wyplate 0; potkniecia 0 (zaplata, bez zaplaty, niesprzedane - INFO)", ok)

        # B-2: welna (INFO)
        sheep = col(r"owce dodatkowych cykli (\d+) x", bl, bdays)
        inc = col(r"= \+([0-9.]+) szt\. do licznikow", bl, bdays, cast=float, default=0.0)
        whole = col(r"pelne sztuki z licznikow (\d+)", bl, bdays)
        cut = col(r"zdjete ponad regule (\d+)", bl, bdays)
        mem = col(r"osadach razem ([0-9.]+) szt\.", bl, bdays, cast=float, default=0.0)
        towns = col(r"liczniki w (\d+) osadach", bl, bdays)
        stock = {}
        for s in lines:
            if s.startswith("Towary: dzien "):
                m = re.match(r"Towary: dzien (\d+) - wool \([^)]*\): zapas (-?\d+)", s)
                if m and 1 <= run_day(int(m.group(1)), start) <= until:
                    stock[run_day(int(m.group(1)), start)] = int(m.group(2))
        last = max(stock) if stock else None
        rep.add("B-2: welna z uboju przez pamiec ulamkow; zapas welny wobec Z33",
                (f"owce dodatkowych cykli {tot(sheep, by_on)} ({tot(sheep, by_on) / max(1, len(by_on)):.0f}/d), do licznikow +{tot(inc, by_on):.1f} szt., pelne sztuki z licznikow "
                 f"{tot(whole, by_on)} ({tot(whole, by_on) / max(1, len(by_on)):.1f}/d), zdjete ponad regule {tot(cut, by_on)}, liczniki w ostatniej dobie: "
                 f"{towns[bdays[-1]]} osad, {mem[bdays[-1]]:.2f} szt.; zapas welny "
                 + (f"w dobie {last}: {stock[last]} (Z33 doba 120: {E8_B_Z33_WOOL_D120}" + (f", x{stock[last] / E8_B_Z33_WOOL_D120:.2f}" if last >= 120 else ", okno krotsze niz 120 dob") + ")"
                    if last is not None else "brak linii Towary - wool")),
                "INFO (projekt: indeks welny bez zalegania ponad Z33)", None)

        # B-3: ksiega licznikow welny zamknieta
        bad, pairs = [], 0
        for a, b in zip(bdays, bdays[1:]):
            if b != a + 1 or a not in by_on or b not in by_on:
                continue
            pairs += 1
            if abs(mem[b] - (mem[a] + inc[b] - whole[b])) > 0.05:
                bad.append(run_day(b, start))
        rep.add("B-3: liczniki welny - nic nie znika i nic nie powstaje (dzis = wczoraj + dopisane - pelne sztuki)",
                f"par kolejnych dob {pairs}, rozjazd > 0.05 szt. w {len(bad)}" + (f" (doby {bad[:5]})" if bad else ""),
                "0 rozjazdow (wczytanie zapisu w oknie moze dac jeden: ulamek przyciety do 0.999)", (not bad) if pairs else None)
    else:
        rep.add("B-1: wyroby uboczne rzemieslnikow z kazdego cyklu", "brak linii Wyroby uboczne (E8/B) - ArtisanOwnInputs wylaczone albo latki nie wpiete", "linia w kazdej dobie", None)

    # B-4: kowadlo i drobne
    wired = [s for s in lines if s.startswith("Kowadlo i drobne (E8/B): ekran rodu")]
    wired_ok = any("(wpiete 1/1)" in s for s in wired)
    if fdays:
        fstum = max([num(r"\| potkniecia (\d+)\.", fl[d], default=0) for d in fdays] + [0])
        last = fl[fdays[-1]]
        labor, folk = col(r"robocizna (\d+) zl, z kasy do kiesy ludu", fl, fdays), col(r"z kasy do kiesy ludu (\d+) zl", fl, fdays)
        over = [run_day(d, start) for d in fdays if folk[d] > labor[d]]
        m = re.search(r"\| od wczytania: (.*?) \| potkniecia", last)
        rep.add("B-4: kowadlo i drobne - latka ekranu rodu, potkniecia, robocizna gracza do kiesy ludu",
                (f"linia startu ekranu rodu: {'wpiete 1/1' if wired_ok else ('nie znaleziono celu' if wired else 'brak linii')}; potkniecia {fstum}; zaplaty gracza kowalom w oknie: "
                 f"robocizna {tot(labor, fdays)} zl, do kiesy ludu {tot(folk, fdays)} zl" + (f" (ponad robocizne w dobach {over[:5]})" if over else "")
                 + (f"; od wczytania: {m.group(1)[:260]}" if m else "")),
                "wpiete 1/1, potkniecia 0, do ludu <= robocizna (pekniecia, material, kopalnia, zamowienia, wyceny - INFO; sprawdzenia reczne 8.16 pkt 2-4)",
                wired_ok and fstum == 0 and not over)
    else:
        rep.add("B-4: kowadlo i drobne", "brak linii Kowadlo i drobne (E8/B)", "linia w kazdej dobie", None)


# ============================================================ ETAP 8 (E8/O1, paczka 265): polka po wlasnym zdjeciu sztuki; delegaty - blok etap8_o1
E8_O1_LINE = "Polka i delegaty (E8/O1): dzien"
# Progi projektu etapu 8 v2 rozdz. 3 "E8/O1" i rozdz. 4 pkt 4 (wzor Z33: przebudowy pamieci polki ok. 13.8 tys./dobe, ceny sprzetu 617 ms/dobe)
E8_O1_BUILDS_MAX = 9000
E8_O1_PRICE_US_MAX = 11.5   # us na wywolanie PricePostfix (TRIAZ-2 O1-3; stary prog 450 ms/d liczony od Z33 z zapisu)


def etap8_o1(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/O1 (265, projekt etapu 8 v2 rozdz. 3 "E8/O1" Test, R9): linia doby "Polka i delegaty (E8/O1)" (ShelfIndex.DailyOwn) + "Koszt 171-174 (doba)"
    (przebudowy, samokontrola, ceny sprzetu) + "Profil doby (E8/0)" (przebudowy wlasne / reszta). O1-0 linia w kazdej dobie okna i stan kluczy;
    O1-1 rozjazdy 0 - probka 1/64 poprawki po wlasnej zmianie (stara i nowa droga), samokontrola odczytow, potkniecia 0 (bez probek - INFO);
    O1-2 przebudowy pamieci polki <= 9 000/dobe srednio w dobach z kluczem [WL] i poprawione w pamieci > 0; O1-3 ceny sprzetu <= 11.5 us na wywolanie (TRIAZ-2);
    O1-4 delegaty: zbudowane N/N (ostatnia doba), wywolan przez Invoke przy kluczu [WL] 0; INFO: sredni czas poprawki i przebudowy z probek."""
    ol = {d: s for d, s in by_day(lines, E8_O1_LINE).items() if 1 <= run_day(d, start) <= until}
    if not ol:
        rep.add("E8/O1: linia Polka i delegaty (E8/O1)", "brak w logu", "jest od wgrania E8/O1", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ol]
    days = sorted(ol)
    on = [d for d in days if "ShelfIndexOwnUpdate [WL]" in ol[d] and "pamiec polki WYLACZONA" not in ol[d]]
    don = [d for d in days if "delegaty DteDelegates [WL]" in ol[d]]
    rep.add("O1-0: linia Polka i delegaty (E8/O1) w kazdej dobie okna; stan kluczy",
            f"dob z linia {len(days)}, brak w {len(miss)} z {len(inner)}" + (f" (doby {miss[:5]})" if miss else "")
            + f"; ShelfIndexOwnUpdate wl {len(on)} / wyl {len(days) - len(on)} dob, DteDelegates wl {len(don)} / wyl {len(days) - len(don)} dob",
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def tot(pat, src, sel, cast=int):
        return sum(num(pat, src[d], cast=cast, default=0) for d in sel)

    kos = {d: s for d, s in by_day(lines, "Koszt 171-174 (doba): dzien").items() if 1 <= run_day(d, start) <= until}
    prof = {d: s for d, s in by_day(lines, E8_PROF).items() if 1 <= run_day(d, start) <= until}

    # O1-1: rozjazdy (R9)
    own_mis = max([num(r"rozjazdow od startu sesji (\d+)", ol[d], default=0) for d in days] + [0])
    self_mis = max([num(r"samokontroli \d+, rozjazdow od startu sesji (\d+)", kos[d], default=0) for d in kos] + [0])
    stum = max([num(r"\| potkniecia od startu sesji (\d+)\.", ol[d], default=0) for d in days] + [0])
    probes = tot(r"probka 1/64 \(stara i nowa droga\): (\d+),", ol, days)
    checks = tot(r"samokontroli (\d+),", kos, sorted(kos))
    alarm = sum(1 for s in lines if s.startswith("Polka i delegaty (E8/O1): ROZJAZD") or s.startswith("Pamiec polki (174b.5): ROZJAZD"))
    ok = None
    if on and (probes > 0 or own_mis or self_mis or stum):
        ok = own_mis == 0 and self_mis == 0 and stum == 0
    rep.add("O1-1: rozjazdy - poprawka po wlasnej zmianie polki wobec pelnej przebudowy (probka 1/64) i samokontrola odczytow",
            f"probek poprawki {probes}, rozjazdow {own_mis}; samokontroli odczytow {checks}, rozjazdow {self_mis}; linii ROZJAZD w logu {alarm}; potkniecia {stum}",
            "0 rozjazdow i 0 potkniec (R9: rozjazd > 0 = paczka wylaczona); bez probek - INFO", ok)

    # O1-2: przebudowy pamieci polki
    deltas, skips, noidx = tot(r"poprawione w pamieci (\d+)", ol, on), tot(r"bez poprawki (\d+)", ol, on), tot(r"polka bez pamieci (\d+)", ol, on)
    kon = [d for d in on if d in kos]
    kb = [num(r"przebudow (\d+),", kos[d]) for d in kon]
    kb = [x for x in kb if x is not None]
    pon = [d for d in on if d in prof]
    p_own = [num(r"polka przebudowy wlasne (\d+) / reszta \d+", prof[d]) for d in pon]
    p_rest = [num(r"polka przebudowy wlasne \d+ / reszta (\d+)", prof[d]) for d in pon]
    p_own, p_rest = [x for x in p_own if x is not None], [x for x in p_rest if x is not None]
    n_on = max(1, len(on))
    txt = (f"poprawione w pamieci {deltas} ({deltas / n_on:.0f}/d), bez poprawki {skips} ({skips / n_on:.0f}/d), polka bez pamieci {noidx} ({noidx / n_on:.0f}/d)"
           + (f"; z linii Profil doby: przebudowy wlasne {sum(p_own) / len(p_own):.0f}/d, reszta {sum(p_rest) / len(p_rest):.0f}/d" if p_own and p_rest else ""))
    if kb:
        avg = sum(kb) / len(kb)
        rep.add("O1-2: przebudowy pamieci polki na dobe (Koszt 171-174) przy kluczu [WL]",
                f"srednio {avg:.0f}/d ({len(kb)} dob, najwiecej {max(kb)}; Z33 ok. 13 800); " + txt,
                f"<= {E8_O1_BUILDS_MAX}/d srednio i poprawione w pamieci > 0", avg <= E8_O1_BUILDS_MAX and deltas > 0)
    else:
        rep.add("O1-2: przebudowy pamieci polki na dobe", ("brak dob z kluczem [WL] i linia Koszt 171-174 (doba); " if on else "klucz ShelfIndexOwnUpdate wylaczony w calym oknie; ") + txt,
                f"<= {E8_O1_BUILDS_MAX}/d srednio przy kluczu [WL]", None)

    # O1-3: ceny sprzetu
    # narzedzie progow p2 (TRIAZ-2 "O1-3"): 450 ms/d policzono od Z33 617 ms (bieg z zapisu) minus oczekiwany zysk, a bieg bez E8/O1 (zb58) mial juz
    # 525 ms/d; ms na dobe zaleza od LICZBY wywolan (bieg 2 ma ich o 11% wiecej niz zb58). Miara skutku O1 = koszt na wywolanie: w calym oknie Z33 13.75 us,
    # zb58 12.39 us, bieg 2 zbior-e8 10.71 us (doby 31-120: 13.1 / 11.7 / 10.4). Prog: <= 11.5 us na wywolanie (srednio w dobach z kluczem [WL]).
    pm = [re.search(r"ceny sprzetu \(PricePostfix\) ([0-9.]+) ms/(\d+)", kos[d]) for d in kon]
    pm = [(float(m.group(1)), int(m.group(2))) for m in pm if m]
    pr = [x for x, _ in pm]
    calls = sum(c for _, c in pm)
    if pr and calls > 0:
        avg = sum(pr) / len(pr)
        us = 1000.0 * sum(pr) / calls
        rep.add("O1-3: ceny sprzetu (PricePostfix) - koszt na wywolanie przy kluczu [WL]",
                f"{us:.2f} us na wywolanie; srednio {avg:.0f} ms/d przy {calls / len(pr):.0f} wywolaniach/d ({len(pr)} dob, najwiecej {max(pr):.0f} ms; Z33 617 ms/d = 13.75 us, "
                f"zb58 525 ms/d = 12.39 us)",
                f"<= {E8_O1_PRICE_US_MAX:.1f} us na wywolanie (ms/d zaleza od liczby wywolan; stary prog 450 ms/d liczony od Z33 z zapisu - TRIAZ-2 O1-3)",
                us <= E8_O1_PRICE_US_MAX)
    else:
        rep.add("O1-3: ceny sprzetu (PricePostfix) - koszt na wywolanie", "brak dob z kluczem [WL] i linia Koszt 171-174 (doba)",
                f"<= {E8_O1_PRICE_US_MAX:.1f} us na wywolanie", None)

    # O1-4: delegaty
    last = ol[days[-1]]
    m = re.search(r"zbudowane (\d+)/(\d+)", last)
    built, wanted = (int(m.group(1)), int(m.group(2))) if m else (0, 0)
    badm = re.search(r"\(nieudane - dalej przez Invoke: ([^)]*)\)", last)
    fast_on, slow_on = tot(r"wywolania delegatem (\d+)", ol, don), tot(r"/ przez Invoke (\d+)", ol, don)
    off = [d for d in days if d not in don]
    slow_off = tot(r"/ przez Invoke (\d+)", ol, off)
    ok = None
    if don and wanted > 0:
        ok = built == wanted and slow_on == 0
    rep.add("O1-4: delegaty zamiast MethodInfo.Invoke (DTE, BK, gra)",
            f"ostatnia doba: zbudowane {built}/{wanted}" + (f" (nieudane: {badm.group(1)[:160]})" if badm else "")
            + f"; przy kluczu [WL] ({len(don)} dob): wywolania delegatem {fast_on}, przez Invoke {slow_on}"
            + (f"; klucz wylaczony {len(off)} dob: przez Invoke {slow_off}" if off else ""),
            "zbudowane N/N i 0 wywolan przez Invoke przy kluczu [WL] (zadne miejsce jeszcze nie wolane - INFO)", ok)

    # INFO: czas poprawki i przebudowy z probek (wazony liczba probek doby)
    wd = wb = wn = 0.0
    for d in days:
        n = num(r"probka 1/64 \(stara i nowa droga\): (\d+),", ol[d], default=0)
        a, c = fnum(r"srednio poprawka ([0-9.]+) us", ol[d]), fnum(r"/ przebudowa ([0-9.]+) us", ol[d])
        if n and a is not None and c is not None:
            wd, wb, wn = wd + a * n, wb + c * n, wn + n
    if wn:
        saved = (wb - wd) / wn * deltas / n_on / 1000.0
        rep.add("E8/O1: czas jednej poprawki i jednej przebudowy (probki)", f"poprawka {wd / wn:.2f} us, przebudowa {wb / wn:.2f} us ({int(wn)} probek); "
                f"szacunek oszczednosci przy {deltas / n_on:.0f} poprawkach/d: {saved:.1f} ms/d", "INFO (projekt: zysk 70-150 ms/d z delegatami)", None)


# ============================================================ ETAP 8 (E8/O2, paczka 266): WorkshopLaw bez refleksji i powtorzen - blok etap8_o2
E8_O2_LINE = "Warsztaty bez powtorzen (E8/O2): dzien"
# Prog projektu etapu 8 v2 rozdz. 3 "E8/O2" i rozdz. 1 (wzor Z33: WorkshopLaw.CyclePrefix 840 ms / 7 093 cykli w dobie 120, srednio 806 ms/dobe)
E8_O2_CYCLE_MS_MAX = 500.0


def etap8_o2(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/O2 (266, projekt etapu 8 v2 rozdz. 3 "E8/O2" Test, R9): linia doby "Warsztaty bez powtorzen (E8/O2)" (WorkshopLaw.DailyFast) + "Koszt 171-174
    (doba)" (WorkshopLaw.CyclePrefix ms / cykli) + "Profil doby (E8/0)" (cykle z planem doby / kolejne) + "Warsztaty (zapis 174)" (zapis i wczytanie).
    O2-0 linia w kazdej dobie okna, stan klucza i tryb kluczy; O2-1 rozjazdy 0 - probka 1/64 kazdej pamieci (stara i nowa droga), linie ROZJAZD,
    potkniecia 0 (bez probek - INFO); O2-2 CyclePrefix <= 500 ms/dobe srednio w dobach z kluczem [WL]; O2-3 zapis -> wczytanie: ta sama liczba sztuk
    w toku (pary zapis / wczytanie w tym samym logu - bieg zapisu) i kazdy zapis = sztuki w pamieci; INFO: ile pracy przejely pamieci."""
    ol = {d: s for d, s in by_day(lines, E8_O2_LINE).items() if 1 <= run_day(d, start) <= until}
    if not ol:
        rep.add("E8/O2: linia Warsztaty bez powtorzen (E8/O2)", "brak w logu", "jest od wgrania E8/O2", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ol]
    days = sorted(ol)
    on = [d for d in days if "WorkshopLawFast [WL]" in ol[d] and "WYLACZONE w MCM" not in ol[d]]
    fastk = [d for d in days if "klucze linii (robota w toku i ranking): wlasne porownanie" in ol[d]]
    rep.add("O2-0: linia Warsztaty bez powtorzen (E8/O2) w kazdej dobie okna; stan klucza",
            f"dob z linia {len(days)}, brak w {len(miss)} z {len(inner)}" + (f" (doby {miss[:5]})" if miss else "")
            + f"; WorkshopLawFast wl {len(on)} / wyl {len(days) - len(on)} dob, klucze z wlasnym porownaniem {len(fastk)} dob",
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def tot(pat, src, sel, cast=int):
        return sum(num(pat, src[d], cast=cast, default=0) for d in sel)

    # O2-1: rozjazdy (R9)
    mis = max([num(r"rozjazdow od startu sesji (\d+)", ol[d], default=0) for d in days] + [0])
    stum = max([num(r"\| potkniecia od startu sesji (\d+)\.", ol[d], default=0) for d in days] + [0])
    probes = tot(r"probka 1/64 \(stara i nowa droga\): (\d+),", ol, days)
    alarm = sum(1 for s in lines if s.startswith("Warsztaty bez powtorzen (E8/O2): ROZJAZD"))
    errs = sum(1 for s in lines if s.startswith("ERROR in WorkshopLaw.Fast(") or s.startswith("ERROR in WorkshopLaw.DailyFast"))
    ok = None
    if on and (probes > 0 or mis or stum or alarm or errs):
        ok = mis == 0 and stum == 0 and alarm == 0 and errs == 0
    rep.add("O2-1: rozjazdy - pamieci warsztatow wobec starej drogi (probka 1/64: klucze, nazwa linii, mnoznik polki, zakazane)",
            f"probek {probes}, rozjazdow {mis}; linii ROZJAZD w logu {alarm}; potkniecia {stum}, linii bledu nowej drogi {errs}",
            "0 rozjazdow i 0 potkniec (R9: rozjazd > 0 = paczka wylaczona); bez probek - INFO", ok)

    # O2-2: czas CyclePrefix
    kos = {d: s for d, s in by_day(lines, "Koszt 171-174 (doba): dzien").items() if 1 <= run_day(d, start) <= until}
    pat = r"WorkshopLaw\.CyclePrefix ([0-9.]+) ms/"

    def cyc(sel):
        v = [fnum(pat, kos[d]) for d in sel if d in kos]
        return [x for x in v if x is not None]

    c_on, c_off = cyc(on), cyc([d for d in days if d not in on])
    calls = [num(r"WorkshopLaw\.CyclePrefix [0-9.]+ ms/(\d+)", kos[d]) for d in on if d in kos]
    calls = [x for x in calls if x is not None]
    prof = {d: s for d, s in by_day(lines, E8_PROF).items() if 1 <= run_day(d, start) <= until}
    p0 = [fnum(r"CyclePrefix z planem doby ([0-9.]+) ms/", prof[d]) for d in on if d in prof]
    p1 = [fnum(r"\), kolejne ([0-9.]+) ms/", prof[d]) for d in on if d in prof]
    p0, p1 = [x for x in p0 if x is not None], [x for x in p1 if x is not None]
    extra = (f"; z linii Profil doby: z planem doby {sum(p0) / len(p0):.0f} ms/d, kolejne {sum(p1) / len(p1):.0f} ms/d" if p0 and p1 else "") \
        + (f"; klucz wylaczony {len(c_off)} dob: srednio {sum(c_off) / len(c_off):.0f} ms/d" if c_off else "")
    if c_on:
        avg = sum(c_on) / len(c_on)
        per = (avg * 1000.0 / (sum(calls) / len(calls))) if calls and sum(calls) > 0 else None
        rep.add("O2-2: WorkshopLaw.CyclePrefix na dobe (Koszt 171-174) przy kluczu [WL]",
                f"srednio {avg:.0f} ms/d ({len(c_on)} dob, najwiecej {max(c_on):.0f}; Z33 806)" + (f", {per:.0f} us na cykl (Z33 136)" if per is not None else "") + extra,
                f"<= {E8_O2_CYCLE_MS_MAX:.0f} ms/d srednio", avg <= E8_O2_CYCLE_MS_MAX)
    else:
        rep.add("O2-2: WorkshopLaw.CyclePrefix na dobe", ("brak dob z kluczem [WL] i linia Koszt 171-174 (doba)" if on else "klucz WorkshopLawFast wylaczony w calym oknie") + extra,
                f"<= {E8_O2_CYCLE_MS_MAX:.0f} ms/d srednio przy kluczu [WL]", None)

    # O2-3: zapis -> wczytanie (caly log - zapis i wczytanie nie maja doby w linii)
    saves, pairs, mism, bad_saves, last_save = 0, 0, [], [], None
    for s in lines:
        if not s.startswith("Warsztaty (zapis 174):"):
            continue
        if "zapis gry - sztuk w toku" in s:
            n, m, k = num(r"sztuk w toku (\d+) \(w pamieci", s), num(r"\(w pamieci (\d+)\)", s), num(r"pominietych (\d+)", s, default=0)
            if n is None or m is None:
                continue
            saves += 1
            last_save = n
            if not (n <= m and m - n <= k):
                bad_saves.append(f"zapisano {n} / w pamieci {m} (pominietych {k})")
        elif "wczytano sztuk w toku" in s:
            p, sk = num(r"wczytano sztuk w toku (\d+)", s), num(r", pominieto (\d+) \(warsztatu", s, default=0)
            if last_save is not None and p is not None:
                pairs += 1
                if not (p <= last_save <= p + sk):
                    mism.append(f"wczytano {p} + pominieto {sk} / zapisano {last_save}")
    ok = None
    if bad_saves or mism:
        ok = False
    elif pairs:
        ok = True
    rep.add("O2-3: zapis -> wczytanie - sztuki w toku warsztatow (Warsztaty (zapis 174))",
            f"zapisow {saves}, niezgodnych z pamiecia {len(bad_saves)}" + (f" ({'; '.join(bad_saves[:3])})" if bad_saves else "")
            + f"; par zapis -> wczytanie {pairs}, niezgodnych {len(mism)}" + (f" ({'; '.join(mism[:3])})" if mism else ""),
            "wczytano tyle sztuk, ile zapisano (wczytanie ostatniego zapisu tego biegu); kazdy zapis = sztuki w pamieci; bez pary - INFO", ok)

    # INFO: ile pracy przejely pamieci (doby z kluczem [WL])
    n_on = max(1, len(on))
    kh, kc = tot(r"skrotow (\d+),", ol, on), tot(r"porownan (\d+),", ol, on)
    lh, ln = tot(r"nazwa linii z pamieci (\d+)", ol, on), tot(r"nazwa linii z pamieci \d+ / liczona (\d+)", ol, on)
    fh, fn_ = tot(r"mnoznik polki koszyka z pamieci (\d+)", ol, on), tot(r"mnoznik polki koszyka z pamieci \d+ / liczony (\d+)", ol, on)
    bh, bn = tot(r"lista zakazanych z pamieci (\d+)", ol, on), tot(r"lista zakazanych z pamieci \d+ / liczona (\d+)", ol, on)
    rk = max([num(r"przepisan slownikow od startu gry (\d+)", ol[d], default=0) for d in days] + [0])
    # recenzja E8/O2 (R9 "wynik i czas"): szacunek oszczednosci z czasu probek - trafienia doby x (stara - nowa droga); linia sprzed recenzji nie ma czasow
    kinds = ((r"porownan (\d+),", r"klucz ([0-9.]+) / ([0-9.]+)", "klucze"), (r"nazwa linii z pamieci (\d+)", r"nazwa linii ([0-9.]+) / ([0-9.]+)", "nazwa linii"),
             (r"mnoznik polki koszyka z pamieci (\d+)", r"mnoznik polki ([0-9.]+) / ([0-9.]+)", "mnoznik polki"),
             (r"lista zakazanych z pamieci (\d+)", r"zakazane ([0-9.]+) / ([0-9.]+)", "zakazane"))
    saved, timed = {k[2]: 0.0 for k in kinds}, 0
    for d in on:
        seg = ol[d].split("czas w probce, stara / nowa droga (us):", 1)
        if len(seg) < 2:
            continue
        timed += 1
        for hp, tp, name in kinds:
            m = re.search(tp, seg[1])
            if m:
                try:
                    saved[name] += num(hp, ol[d], default=0) * (float(m.group(1)) - float(m.group(2))) / 1000.0
                except ValueError:
                    pass
    est = (f"; szacunek oszczednosci z czasu probek ({timed} dob): {sum(saved.values()) / timed:.1f} ms/d ("
           + ", ".join(f"{k} {v / timed:.1f}" for k, v in saved.items()) + "; klucze - same porownania, bez skrotow)") if timed else "; czasu probek brak w linii"
    rep.add("E8/O2: praca przejeta przez pamieci (na dobe, doby z kluczem [WL])",
            f"klucze: skrotow {kh / n_on:.0f}, porownan {kc / n_on:.0f}; nazwa linii z pamieci {lh / n_on:.0f} / liczona {ln / n_on:.0f}; "
            f"mnoznik polki {fh / n_on:.0f} / {fn_ / n_on:.0f}; zakazane {bh / n_on:.0f} / {bn / n_on:.0f}; przepisan slownikow kluczy {rk}" + est,
            "INFO (projekt: zysk 150-400 ms/d)", None)


# ============================================================ ETAP 8 (E8/O3, paczka 267): wywoz kupcow - cele w zasiegu z pamieci - blok etap8_o3
E8_O3_LINE = "Wywoz kupcow (E8/O3): dzien"
# Progi projektu etapu 8 v2 rozdz. 3 "E8/O3", rozdz. 1 i rozdz. 4 pkt 4 (wzor Z33: czas wywozu 608 ms w dobie 1 -> 312.5 ms w dobie 120)
E8_O3_MS_ALONE = 220.0     # sam O3
E8_O3_MS_WITH_O1 = 150.0   # O1 + O3 (ShelfIndexOwnUpdate [WL] w linii "Polka i delegaty (E8/O1)")
E8_O3_LAST_DAYS = 10       # prog liczony ze sredniej ostatnich dob okna - wzor Z33 to doba 120, a czas wywozu spada z doba kampanii
E8_O3_MIN_DAY = 110        # okno musi siegac tej doby kampanii; krotsze - INFO


def etap8_o3(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/O3 (267, projekt etapu 8 v2 rozdz. 3 "E8/O3" Test, R9): linia doby "Wywoz kupcow (E8/O3)" (TradeExportMemo.Daily, z konca
    SupplyDemand.DailyTrade) + stan klucza O1 z linii "Polka i delegaty (E8/O1)". O3-0 linia w kazdej dobie okna, stan klucza; O3-1 rozjazdy 0 -
    probka 1/64 wyboru celu i popytu zrodla (stara i nowa droga), linie ROZJAZD, potkniecia i linie bledu 0 (bez probek - INFO); O3-2 czas wywozu:
    srednia ostatnich 10 dob okna z kluczem [WL] <= 150 ms (O1+O3) albo <= 220 ms (sam O3), gdy okno siega doby >= 110 (inaczej INFO); O3-3 sztuki
    i zaplacone w probce: rozjazdow celu i sztuk 0 (zdjecie sztuk i zaplata ida wspolnym kodem - ten sam wybor = te same sztuki i zloto);
    INFO: praca przejeta przez pamiec i szacunek oszczednosci z czasu probek."""
    ol = {d: s for d, s in by_day(lines, E8_O3_LINE).items() if 1 <= run_day(d, start) <= until}
    if not ol:
        rep.add("E8/O3: linia Wywoz kupcow (E8/O3)", "brak w logu", "jest od wgrania E8/O3", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ol]
    days = sorted(ol)
    on = [d for d in days if "TradeExportFast [WL]" in ol[d]]
    ran = [d for d in days if "wywozu tej doby nie bylo" not in ol[d]]
    rep.add("O3-0: linia Wywoz kupcow (E8/O3) w kazdej dobie okna; stan klucza",
            f"dob z linia {len(days)}, brak w {len(miss)} z {len(inner)}" + (f" (doby {miss[:5]})" if miss else "")
            + f"; TradeExportFast wl {len(on)} / wyl {len(days) - len(on)} dob; dob bez wywozu {len(days) - len(ran)}",
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def tot(pat, sel, cast=int):
        return sum(num(pat, ol[d], cast=cast, default=0) for d in sel)

    def top(pat):
        return max([num(pat, ol[d], default=0) for d in days] + [0])

    # O3-1: rozjazdy (R9)
    mis = top(r"rozjazdow od startu sesji (\d+) \(cel")
    m_t, m_p, m_s = top(r"\(cel (\d+), sztuki albo droga"), top(r"sztuki albo droga (\d+), zrodlo"), top(r", zrodlo (\d+)\)")
    stum = top(r"\| potkniecia od startu sesji (\d+)\.")
    pp, pt = tot(r"\): wybor celu (\d+) \(z celem", on), tot(r"\(z celem (\d+),", on)
    ps = tot(r"popyt zrodla (\d+), rozjazdow", on)
    alarm = sum(1 for s in lines if s.startswith("Wywoz kupcow (E8/O3): ROZJAZD"))
    errs = sum(1 for s in lines if s.startswith("ERROR in TradeExportMemo.") or s.startswith("ERROR in SupplyDemand.DailyTrade"))
    ok = None
    if on and (pp + ps > 0 or mis or stum or alarm or errs):
        ok = mis == 0 and stum == 0 and alarm == 0 and errs == 0
    rep.add("O3-1: rozjazdy - wybor celu i popyt zrodla z pamieci wobec starej drogi (probka 1/64)",
            f"probek wyboru celu {pp}, popytu zrodla {ps}; rozjazdow {mis} (cel {m_t}, sztuki albo droga {m_p}, zrodlo {m_s}); linii ROZJAZD w logu {alarm}; "
            f"potkniecia {stum}, linii bledu wywozu {errs}",
            "0 rozjazdow i 0 potkniec (R9: rozjazd > 0 = paczka wylaczona); bez probek - INFO", ok)

    # O3-2: czas wywozu (jedna klatka na dobe)
    ms = {d: fnum(r"czas wywozu ([0-9.]+) ms", ol[d]) for d in ran}
    ms = {d: v for d, v in ms.items() if v is not None}
    o1 = by_day(lines, E8_O1_LINE)

    def with_o1(d):
        return d in o1 and "ShelfIndexOwnUpdate [WL]" in o1[d] and "pamiec polki WYLACZONA" not in o1[d]

    on_ms = [d for d in on if d in ms]
    off_ms = [d for d in days if d not in on and d in ms]
    last_run = max([run_day(d, start) for d in (win or days)] + [0])
    tail = [d for d in on_ms if run_day(d, start) > last_run - E8_O3_LAST_DAYS]
    extra = ""
    if on_ms:
        worst = max(on_ms, key=lambda d: ms[d])
        first = min(on_ms)
        extra = (f"; cale okno z kluczem [WL]: srednio {sum(ms[d] for d in on_ms) / len(on_ms):.1f} ms ({len(on_ms)} dob), pierwsza doba ({run_day(first, start)}) "
                 f"{ms[first]:.1f} ms, najwiecej {ms[worst]:.1f} ms (doba {run_day(worst, start)})")
    if off_ms:
        extra += f"; klucz wylaczony {len(off_ms)} dob: srednio {sum(ms[d] for d in off_ms) / len(off_ms):.1f} ms"
    both = bool(tail) and all(with_o1(d) for d in tail)
    lim = E8_O3_MS_WITH_O1 if both else E8_O3_MS_ALONE
    rule = (f"<= {E8_O3_MS_WITH_O1:.0f} ms przy O1+O3 (ShelfIndexOwnUpdate [WL]) albo <= {E8_O3_MS_ALONE:.0f} ms przy samym O3 - srednio w ostatnich "
            f"{E8_O3_LAST_DAYS} dobach okna (Z33: 312.5 ms w dobie 120); okno krotsze niz {E8_O3_MIN_DAY} dob - INFO")
    if tail and last_run >= E8_O3_MIN_DAY and len(tail) >= E8_O3_LAST_DAYS // 2:
        avg = sum(ms[d] for d in tail) / len(tail)
        rep.add("O3-2: czas wywozu kupcow (jedna klatka) przy kluczu [WL]",
                f"ostatnie {len(tail)} dob okna (do doby {last_run}): srednio {avg:.1f} ms, najwiecej {max(ms[d] for d in tail):.1f} ms; prog "
                f"{lim:.0f} ms ({'O1+O3' if both else 'sam O3 - ShelfIndexOwnUpdate nie byl [WL] w tych dobach'})" + extra, rule, avg <= lim)
    else:
        if not on:
            why = "klucz TradeExportFast wylaczony w calym oknie"
        elif not on_ms:
            why = "brak dob z wywozem"
        elif last_run < E8_O3_MIN_DAY:
            why = f"okno siega doby {last_run}"
        else:   # recenzja E8/O3: okno dosc dlugie, ale w jego koncu za malo dob z wywozem przy kluczu [WL] - powod wprost, nie "okno siega doby"
            why = (f"w ostatnich {E8_O3_LAST_DAYS} dobach okna (do doby {last_run}) tylko {len(tail)} dob z wywozem przy kluczu [WL] "
                   f"(potrzeba {E8_O3_LAST_DAYS // 2})")
        rep.add("O3-2: czas wywozu kupcow (jedna klatka)", why + extra, rule, None)

    # O3-3: sztuki i zaplacone w probce
    pieces, gold = tot(r"wywiezione po nich (\d+) szt\.", on), tot(r"szt\. za (-?\d+) zl\)", on)
    rep.add("O3-3: sztuki i zaplacone w probce - ten sam cel, ta sama liczba sztuk do wziecia i droga (zdjecie sztuk i zaplata ida wspolnym kodem)",
            f"wyborow w probce {pp}, z celem {pt}; po nich wywiezione {pieces} szt. za {gold} zl; rozjazdow celu {m_t}, sztuk albo drogi {m_p}",
            "0 rozjazdow celu i sztuk; bez probek - INFO", (m_t == 0 and m_p == 0) if (on and pp > 0) else None)

    # INFO: ile pracy przejela pamiec (doby z kluczem [WL] i wywozem) i szacunek oszczednosci z czasu probek
    sel = [d for d in on if d in ran]
    n_on = max(1, len(sel))
    pn, po = tot(r"wybor celu: nowa droga (\d+)", sel), tot(r"wybor celu: nowa droga \d+ / stara droga (\d+)", sel)
    dh, dn = tot(r"popyt osady w koszyku z pamieci (\d+)", sel), tot(r"popyt osady w koszyku z pamieci \d+ / liczony (\d+)", sel)
    mh, mn = tot(r"mnoznik ceny z pamieci (\d+)", sel), tot(r"mnoznik ceny z pamieci \d+ / liczony (\d+)", sel)
    builds = top(r"budowana od startu sesji (\d+)")
    pairs = num(r"par zrodlo-cel w zasiegu (\d+)", ol[sel[-1]], default=0) if sel else 0
    places = num(r"\| osad (\d+),", ol[sel[-1]], default=0) if sel else 0
    saved, timed = 0.0, 0
    for d in sel:
        seg = ol[d].split("czas w probce, stara / nowa droga (us):", 1)
        m = re.search(r"wybor celu ([0-9.]+) / ([0-9.]+)", seg[1]) if len(seg) > 1 else None
        if m:
            try:
                saved += num(r"wybor celu: nowa droga (\d+)", ol[d], default=0) * (float(m.group(1)) - float(m.group(2))) / 1000.0
                timed += 1
            except ValueError:
                pass
    est = f"; szacunek oszczednosci z czasu probek ({timed} dob): {saved / timed:.1f} ms/d" if timed else "; czasu probek brak w linii"
    rep.add("E8/O3: praca przejeta przez pamiec (na dobe, doby z kluczem [WL] i wywozem)",
            f"wybor celu nowa droga {pn / n_on:.0f} / stara {po / n_on:.0f}; popyt osady z pamieci {dh / n_on:.0f} / liczony {dn / n_on:.0f}; "
            f"mnoznik ceny z pamieci {mh / n_on:.0f} / liczony {mn / n_on:.0f}; osad {places}, par zrodlo-cel w zasiegu {pairs}"
            + (f" (srednio {pairs / places:.1f} celow na zrodlo zamiast {places - 1})" if places else "") + f"; pamiec celow budowana {builds} razy" + est,
            "INFO (projekt: zysk 50-110 ms w jednej klatce)", None)


# ============================================================ ETAP 8 (E8/O5, paczka 269): nadwyzki zalog po godzinach - blok etap8_o5
E8_O5_LINE = "Nadwyzki zalog po godzinach (E8/O5): dzien"
# Progi projektu etapu 8 v2 rozdz. 3 "E8/O5" (poza regula R9 - to zmiana kolejnosci w dobie) i rozdz. 4 pkt 4
E8_O5_TICK_MS = 1000.0   # O5-1: maks. taktu doby (linia "Profil doby (E8/0)")
E8_O5_BAND = 0.15        # O5-2: sprzedane sztuki i utarg zalog tygodniowo w +-15% Z33
E8_O5_MIN_WEEKS = 8      # O5-2 wiaze od tylu pelnych tygodni okna (kazda zaloga sprzedaje raz w tygodniu; pierwsze tygodnie to wyprzedaz zapasow startowych)
# Wzor Z33 (WGRANIE 33, Armoury-2026-10-12_02-44-09.log, start kampanii 108836, kolejka w takcie doby): linia "Sakiewka ludzi: dzien N ... (w tym zalogi A za B" -
# sztuki i utarg zalog w dobach kampanii 1..120 (indeks = doba - 1). Pelne tygodnie od doby 2: 17 tygodni = 101 362 szt. za 215 748 zl; tygodnie 5-17: 36 878 / 88 033.
# Ksiega kas Z33 (srednio na dobe): zamki "skup nadwyzek zbrojowni" -2, "pozostale moduly ticku" -255; miasta -12 180 (nadwyzki lordow) i -1 536.
E8_O5_Z33_PCS = (
    0, 2712, 1760, 2783, 3224, 5269, 5542, 2605, 6649, 4207, 6610, 1969, 1831, 2205, 386, 1284, 1391, 2707, 1557, 1136,
    1598, 963, 1691, 1172, 1263, 401, 993, 229, 347, 199, 562, 1164, 269, 234, 380, 300, 353, 312, 1521, 689,
    26, 753, 409, 611, 1665, 1802, 327, 650, 587, 492, 186, 605, 1096, 125, 445, 468, 217, 214, 223, 920,
    204, 654, 258, 408, 324, 70, 61, 169, 472, 592, 287, 42, 325, 291, 74, 339, 318, 63, 591, 111,
    536, 78, 373, 151, 140, 85, 167, 340, 275, 92, 235, 121, 486, 448, 594, 224, 388, 70, 537, 121,
    355, 579, 88, 281, 268, 78, 328, 408, 380, 518, 403, 728, 861, 154, 505, 192, 589, 633, 60, 552,
)
E8_O5_Z33_GOLD = (
    0, 2794, 1863, 3313, 5134, 10347, 9278, 4108, 14201, 7846, 12968, 3284, 5828, 5129, 900, 3225, 2647, 6502, 2120, 4794,
    3722, 1089, 4429, 2281, 4693, 698, 3662, 294, 566, 244, 915, 4295, 368, 1190, 560, 316, 371, 346, 6159, 736,
    26, 840, 651, 707, 1950, 5225, 379, 4068, 1111, 834, 198, 1415, 5589, 254, 3225, 1086, 254, 214, 499, 4435,
    246, 2732, 576, 438, 380, 117, 261, 217, 1009, 992, 335, 58, 497, 1333, 91, 1472, 697, 68, 639, 128,
    2393, 81, 2756, 334, 140, 87, 197, 1275, 280, 689, 320, 121, 511, 747, 1050, 297, 750, 165, 663, 138,
    676, 1289, 103, 816, 346, 78, 371, 571, 2215, 999, 533, 839, 873, 160, 521, 886, 939, 1410, 61, 607,
)


def etap8_o5(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/O5 (269, projekt etapu 8 v2 rozdz. 3 "E8/O5" Test - poza R9): linia doby "Nadwyzki zalog po godzinach (E8/O5)" (GarrisonArmory.LineO5, z
    GarrisonArmory.Daily; dzien linii = dzien gry - 1) + "Profil doby (E8/0)", "Sakiewka ludzi", "Zakupy i nadwyzki AI (E8/Z)", "Przeplywy osad".
    O5-0 linia w kazdej dobie okna, stan klucza; O5-1 maks. taktu doby <= 1.0 s w dobach z kluczem [WL] (Profil doby; czas i najdluzsza godzina sprzedazy
    po godzinach - INFO); O5-2 sztuki i utarg zalog w pelnych tygodniach okna w +-15% Z33 w tych samych dobach (bez uprzezy E8/Z, ktorej Z33 nie
    sprzedawal; wiaze od 8 pelnych tygodni przy kluczu [WL], krotsze okno - INFO; doba 1 kampanii w 1. tygodniu); O5-3 INFO ksiega kas: "skup nadwyzek
    zbrojowni" (poza taktem doby) wobec "pozostale moduly ticku"; O5-4 potkniecia i linie bledu GarrisonArmory 0."""
    ol = {d: s for d, s in by_day(lines, E8_O5_LINE).items() if 1 <= run_day(d, start) <= until}
    if not ol:
        rep.add("E8/O5: linia Nadwyzki zalog po godzinach (E8/O5)", "brak w logu", "jest od wgrania E8/O5", None)
        return
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ol]
    days = sorted(ol)
    on = [d for d in days if "GarrisonSellHourly [WL]" in ol[d]]
    on_set = set(on)
    off = [d for d in days if d not in on_set]
    dead = [d for d in days if "sprzedaz nadwyzek zalog wylaczona" in ol[d]]
    rep.add("O5-0: linia Nadwyzki zalog po godzinach (E8/O5) w kazdej dobie okna; stan klucza",
            f"dob z linia {len(days)}, brak w {len(miss)} z {len(inner)}" + (f" (doby {miss[:5]})" if miss else "")
            + f"; GarrisonSellHourly wl {len(on)} / wyl {len(off)} dob" + (f"; sprzedaz nadwyzek zalog wylaczona w {len(dead)} dobach" if dead else ""),
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    def tot(pat, sel, cast=int):
        return sum(num(pat, ol[d], cast=cast, default=0) for d in sel)

    # O5-1: maks. taktu doby. Linia profilu "dzien D" mierzy takt doby gry D; stan klucza w tym takcie podaje linia E8/O5 "dzien D - 1" (ten sam takt)
    prof = by_day(lines, E8_PROF)
    tick = {}
    for d, s in prof.items():
        if (d - 1) in ol:
            v = fnum(r"\| takt doby ([0-9.]+) ms", s)
            if v is not None:
                tick[d] = v
    t_on = {d: v for d, v in tick.items() if (d - 1) in on_set}
    t_off = {d: v for d, v in tick.items() if (d - 1) not in on_set}
    rule1 = f"<= {E8_O5_TICK_MS:.0f} ms w kazdej dobie z kluczem [WL] (projekt rozdz. 3 \"E8/O5\" i rozdz. 4 pkt 4; bez linii Profil doby - INFO)"
    if t_on:
        vals = sorted(t_on.values())
        worst = sorted(t_on, key=lambda d: -t_on[d])[:3]
        over = sum(1 for v in vals if v > E8_O5_TICK_MS)

        def lap(d):   # odcinek GarrisonArmory.Daily w 15 najdluzszych odcinkach taktu (po paczce: sama linia)
            return fnum(r"GarrisonArmory\.Daily ([0-9.]+)", prof[d].split("; inne sluchacze", 1)[0])

        laps = [x for x in (lap(d) for d in t_on) if x is not None]
        extra = (f"; odcinek GarrisonArmory.Daily w czolowce taktu w {len(laps)} dobach (najwiecej {max(laps):.1f} ms)" if laps
                 else "; odcinka GarrisonArmory.Daily nie ma w czolowce taktu")
        if t_off:
            lo = [x for x in (lap(d) for d in t_off) if x is not None]
            extra += (f"; klucz wylaczony {len(t_off)} dob: takt maks. {max(t_off.values()):.0f} ms"
                      + (f", GarrisonArmory.Daily srednio {sum(lo) / len(lo):.1f} ms w {len(lo)} dobach" if lo else ""))
        rep.add("O5-1: najdluzszy takt doby (jedna klatka) przy kluczu [WL]",
                f"maks. {vals[-1]:.0f} ms, mediana {vals[len(vals) // 2]:.0f} ms, dob ponad prog {over} z {len(vals)}; najdluzsze: "
                + ", ".join(f"d{run_day(d, start)} {t_on[d]:.0f} ms" for d in worst) + extra, rule1, vals[-1] <= E8_O5_TICK_MS)
    else:
        why = "brak linii Profil doby (E8/0) - Stage8ProfileLog wylaczony?" if not tick else "klucz GarrisonSellHourly wylaczony w calym oknie"
        rep.add("O5-1: najdluzszy takt doby (jedna klatka)", why + (f"; takt maks. {max(t_off.values()):.0f} ms przy wylaczonym kluczu" if t_off else ""), rule1, None)

    # INFO: czas sprzedazy po godzinach i najdluzsza godzina (zamrozenie nie moze sie tylko przeniesc z taktu doby na godzine)
    if on:
        ms = tot(r"jednej godziny \d+, czas ([0-9.]+) ms", on, float)
        busy = tot(r"\(z kolejka (\d+),", on)
        hmax = {d: fnum(r"najdluzsza godzina ([0-9.]+) ms", ol[d], 0.0) for d in on}
        omax = {d: fnum(r"najdluzsza zaloga ([0-9.]+) ms", ol[d], 0.0) for d in on}
        dh, do = max(on, key=lambda d: hmax[d]), max(on, key=lambda d: omax[d])
        mo = re.search(r"najdluzsza zaloga [0-9.]+ ms \((.*?)\) \| w takcie doby", ol[do])
        most = max(num(r"najwiecej w kolejce jednej godziny (\d+)", ol[d], default=0) for d in on)
        hq = num(r"najdluzsza godzina [0-9.]+ ms \(zalog w kolejce (\d+)\)", ol[dh], default=0)
        due = tot(r"zalog w terminie (\d+)", on)
        caught, rept = tot(r"nadrobione numery godzin (\d+)", on), tot(r"powtorzone (\d+)\)", on)
        txt = (f"srednio {ms / len(on):.1f} ms/dobe w {busy / len(on):.1f} godzinach z kolejka; najdluzsza godzina {hmax[dh]:.1f} ms (d{run_day(dh, start)}, zalog w kolejce "
               f"{hq}); najdluzsza zaloga {omax[do]:.1f} ms ({mo.group(1) if mo else '-'}, d{run_day(do, start)}); najwiecej zalog w kolejce jednej godziny {most}; "
               f"zalog w terminie srednio {due / len(on):.1f}/d; nadrobione numery godzin {caught}, powtorzone {rept}")
        if off:
            tq = [fnum(r"w takcie doby: zalog w kolejce \d+, czas ([0-9.]+) ms", ol[d], 0.0) for d in off]
            txt += f"; klucz wylaczony {len(off)} dob: w takcie doby srednio {sum(tq) / len(tq):.1f} ms, najwiecej {max(tq):.1f} ms"
        rep.add("E8/O5: sprzedaz po godzinach - czas i najdluzsza godzina", txt,
                "INFO (projekt: 0 CPU, znika zamrozenie w takcie doby; Z33 w takcie doby srednio 103 ms, najwiecej 748 ms - godzina o takim czasie = zamrozenie tylko przeniesione)", None)

    # O5-2: sztuki i utarg zalog w pelnych tygodniach okna wobec Z33 w tych samych dobach (linia "Sakiewka ludzi" - doba wedlug chwili sprzedazy w obu biegach)
    cur = {}
    for d, s in by_day(lines, "Sakiewka ludzi: dzien").items():
        rd = run_day(d, start)
        m = re.search(r"\(w tym zalogi (\d+) za (\d+)", s)
        if m and 1 <= rd <= until:
            cur[rd] = (int(m.group(1)), int(m.group(2)))
    har = {}   # E8/Z: uprzaz ponad zapas sprzedana przez zalogi (sztuki dokladnie; zloto - udzial zalog w sztukach x zloto calej sprzedazy uprzezy)
    for d, s in by_day(lines, E8_Z_LINE).items():
        m = re.search(r"uprzaz ponad zapas \[(?:WL|wyl)\]: sprzedana (\d+) szt\. za (\d+) zl \(w tym zalogi (\d+) szt\.", s)
        if m and int(m.group(1)) > 0:
            har[run_day(d, start)] = (int(m.group(3)), int(m.group(2)) * int(m.group(3)) / int(m.group(1)))
    rule2 = (f"sztuki i utarg zalog w pelnych tygodniach okna w +-{100 * E8_O5_BAND:.0f}% Z33 w tych samych dobach (bez uprzezy E8/Z; wiaze od {E8_O5_MIN_WEEKS} pelnych "
             "tygodni przy kluczu [WL]). Wzor Z33 jest sprzed etapow 5-8 (ceny E8/C, naprawy E8/W, lup E8/L tez zmieniaja nadwyzki) - poza pasmem przy "
             "czystych O5-0 i O5-4 rozstrzyga bieg kontrolny z kluczem wylaczonym. Doba 1 kampanii liczona do 1. tygodnia: po godzinach czesc zalog "
             "sprzedaje juz przed pierwszym taktem doby, w Z33 (kolejka w takcie doby) doba 1 to zero")
    last_rd = min(max(cur) if cur else 0, until, len(E8_O5_Z33_PCS))
    weeks = max(0, (last_rd - 1) // 7)
    if weeks >= 1:
        # doby kampanii tygodnia k (1..): 2 + 7(k-1) .. 1 + 7k. Recenzja E8/O5: 1. tydzien bierze tez dobe 1 - po godzinach ok. 26 ze 168 terminow tygodnia
        # (24 godziny doby 1 i dwie nadrabiane przy starcie sesji) wypada przed pierwszym taktem doby, a kolejka w takcie doby (Z33, klucz wylaczony)
        # rusza od doby 2 (wzor ma w dobie 1 zero). Bez doby 1 pierwsza sprzedaz tych zalog wypadala z porownania (ok. -3% sztuk przy pasmie +-15%)
        def wk(k):
            return range(1 if k == 1 else 2 + 7 * (k - 1), 2 + 7 * k)

        rows = []
        for k in range(1, weeks + 1):
            cp = sum(cur.get(rd, (0, 0))[0] for rd in wk(k)); cg = sum(cur.get(rd, (0, 0))[1] for rd in wk(k))
            hp = sum(har.get(rd, (0, 0.0))[0] for rd in wk(k)); hg = sum(har.get(rd, (0, 0.0))[1] for rd in wk(k))
            zp = sum(E8_O5_Z33_PCS[rd - 1] for rd in wk(k)); zg = sum(E8_O5_Z33_GOLD[rd - 1] for rd in wk(k))
            rows.append((cp - hp, cg - hg, zp, zg, hp, hg))

        def ratio(sel, i):
            a, z = sum(r[i] for r in sel), sum(r[i + 2] for r in sel)
            return (a / z) if z > 0 else None

        rp, rg = ratio(rows, 0), ratio(rows, 1)
        span_on = {run_day(d, start) for d in on}
        span_all = {run_day(d, start) for d in days}
        key_off = sorted(rd for rd in range(1, 2 + 7 * weeks) if rd in span_all and rd not in span_on)
        wr = [r[0] / r[2] for r in rows if r[2] > 0]
        d1 = cur.get(1, (0, 0))
        txt = (f"{weeks} pelnych tygodni (doby 1-{1 + 7 * weeks}, doba 1 w 1. tygodniu): sztuki {sum(r[0] for r in rows):.0f} wobec Z33 {sum(r[2] for r in rows)}"
               + (f" (x{rp:.2f})" if rp is not None else "") + f", utarg {sum(r[1] for r in rows):.0f} zl wobec {sum(r[3] for r in rows)}"
               + (f" (x{rg:.2f})" if rg is not None else "") + f"; w tym doba 1 (przed pierwszym taktem doby) {d1[0]} szt. / {d1[1]} zl"
               + f"; odjeta uprzaz E8/Z zalog {sum(r[4] for r in rows):.0f} szt. / ok. {sum(r[5] for r in rows):.0f} zl")
        if weeks > 4:
            sp, sg = ratio(rows[4:], 0), ratio(rows[4:], 1)
            txt += f"; tygodnie 5-{weeks}: sztuki " + (f"x{sp:.2f}" if sp is not None else "-") + ", utarg " + (f"x{sg:.2f}" if sg is not None else "-")
        if wr:
            txt += f"; pojedynczy tydzien sztuk od x{min(wr):.2f} do x{max(wr):.2f}"
        if key_off:
            txt += f"; klucz wylaczony w {len(key_off)} dobach tych tygodni"
        binding = weeks >= E8_O5_MIN_WEEKS and not key_off and bool(on) and rp is not None and rg is not None
        ok = (abs(rp - 1.0) <= E8_O5_BAND and abs(rg - 1.0) <= E8_O5_BAND) if binding else None
        rep.add("O5-2: sprzedane sztuki i utarg zalog tygodniowo wobec Z33", txt, rule2, ok)
    else:
        rep.add("O5-2: sprzedane sztuki i utarg zalog tygodniowo wobec Z33",
                "brak linii Sakiewka ludzi z segmentem 'w tym zalogi'" if not cur else f"okno siega doby {last_rd} - nie ma pelnego tygodnia", rule2, None)

    # O5-3 (INFO): ksiega kas - utarg zalog schodzi z kas w pozycji "skup nadwyzek zbrojowni" (poza taktem doby), nie w "pozostale moduly ticku"
    def flow(prefix, pat, head=None):
        out = []
        for d, s in by_day(lines, prefix).items():
            if not (1 <= run_day(d, start) <= until):
                continue
            seg = s
            if head is not None:
                seg = next((p for p in s.split(" | ") if p.startswith(head)), "")
            out.append(num(pat, seg, default=0))
        return out

    cz, cm = flow("Przeplywy osad (przyczyny): dzien", r"skup nadwyzek zbrojowni ([+-]?\d+)", "kasy zamkow:"), flow("Przeplywy osad (przyczyny): dzien", r"skup nadwyzek zbrojowni ([+-]?\d+)", "kasy miast:")
    pz, pm = flow("Przeplywy osad (kasy zamkow): dzien", r"pozostale moduly ticku ([+-]?\d+)"), flow("Przeplywy osad (kasy miast): dzien", r"pozostale moduly ticku ([+-]?\d+)")
    if cz or pz:
        avg = lambda L: (sum(L) / len(L)) if L else 0.0
        gd = [v[1] for v in cur.values()]
        rep.add("O5-3: ksiega kas - skup nadwyzek zbrojowni (poza taktem doby) wobec pozostale moduly ticku (srednio na dobe)",
                f"kasy zamkow: skup {avg(cz):+.0f}, pozostale moduly ticku {avg(pz):+.0f}; kasy miast: skup {avg(cm):+.0f}, pozostale moduly ticku {avg(pm):+.0f}; "
                f"utarg zalog {avg(gd):.0f}/d",
                "INFO - przy [WL] utarg zalog schodzi z kas w pozycji 'skup nadwyzek zbrojowni' (ta sama co nadwyzki lordow), nie w 'pozostale moduly ticku' "
                "(Z33: zamki skup -2 i pozostale -255, miasta skup -12 180 i pozostale -1 536); to przelew kasa -> pan i sakiewka zalogi, reszta R bilansu swiata bez zmian", None)

    # O5-4: potkniecia (licznik GarrisonArmory doby - takze A7 i ekran druzyny) i linie bledu
    stum = tot(r"\| potkniecia (\d+)\.", days)
    errs = sum(1 for s in lines if s.startswith("ERROR in GarrisonArmory."))
    rep.add("O5-4: potkniecia zbrojowni zalog i linie bledu GarrisonArmory", f"potkniecia {stum} (suma dob okna), linii ERROR in GarrisonArmory.* w logu {errs}",
            "0 i 0 (wyjatek jednej zalogi nie gasi kolejki - liczony)", stum == 0 and errs == 0)


# ============================================================ ETAP 8 (E8/O6, paczka 270): zapis logu otwartym plikiem - blok etap8_o6
E8_O6_LINE = "Log (E8/O6): dzien"
E8_O6_CTL = "Log (E8/O6) wpis kontrolny drogi bledu"
E8_O6_WRITE_MS = 20.0   # O6-1: czas zapisu logu na dobe przy kluczu [WL] (projekt etapu 8 v2 rozdz. 3 "E8/O6"; linia "Profil doby (E8/0)": "log zapis X ms / N linii")
E8_O6_SAMPLE = re.compile(r"\| proba (\d)/(\d): plikow (\d+), bajtow wyslanych (\d+), w plikach (\d+), rozjazd (\d+) \(plikow z rozjazdem (\d+)\), "
                          r"glowny plik linii wyslanych (\d+) \(z ta linia\)")


def etap8_o6(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """E8/O6 (270, projekt etapu 8 v2 rozdz. 3 "E8/O6" Test, regula R9, krytyka K2-5): linia doby "Log (E8/O6)" (Log.DailyO6 - dzien linii = dzien gry - 1),
    wpisy "Log (E8/O6) wpis kontrolny drogi bledu" i "Profil doby (E8/0)". O6-0 linia w kazdej dobie okna, stan klucza; O6-1 "log zapis" <= 20 ms/dobe
    srednio w dobach z kluczem [WL] bez zapisow stara droga; O6-2 proba 3 dob sesji - bajty wyslane do kazdego pliku = rozmiar pliku i numer linii doby
    w glownym pliku = liczba linii wyslanych (narzedzie liczy linie w pliku logu); O6-3 wpisy kontrolne drogi Log.Error w pliku = wyslane, >= 1;
    O6-4 zapisy stracone, potkniecia pisarza, linie bledu Log.DailyO6 0 i zapisy stara droga w dobach [WL] 0."""
    allo = [s for s in lines if s.startswith(E8_O6_LINE)]
    if not allo:
        rep.add("E8/O6: linia Log (E8/O6)", "brak w logu", "jest od wgrania E8/O6", None)
        return
    ol = {d: s for d, s in by_day(lines, E8_O6_LINE).items() if 1 <= run_day(d, start) <= until}
    inner = win[1:-1] if len(win) > 2 else []
    miss = [run_day(d, start) for d in inner if d not in ol]
    days = sorted(ol)
    on = [d for d in days if "LogKeepOpen [WL]" in ol[d]]
    on_set = set(on)
    off = [d for d in days if d not in on_set]
    wr = max((num(r"pisarze otwarci (\d+)", ol[d], default=0) for d in days), default=0)
    rep.add("O6-0: linia Log (E8/O6) w kazdej dobie okna; stan klucza",
            f"dob z linia {len(days)}, brak w {len(miss)} z {len(inner)}" + (f" (doby {miss[:5]})" if miss else "")
            + f"; LogKeepOpen wl {len(on)} / wyl {len(off)} dob; najwiecej otwartych pisarzy {wr}",
            "0 brakow (bez pierwszej i ostatniej doby okna)", (not miss) if inner else None)

    # O6-1: czas zapisu logu. Linia profilu "dzien D" i linia E8/O6 "dzien D" powstaja w tym samym takcie doby (okres od poprzedniego taktu)
    prof = by_day(lines, E8_PROF)
    wms, wn, wms_off, wms_mix = {}, {}, {}, {}
    for d in days:
        if d not in prof:
            continue
        v, n = fnum(r"\| log zapis ([0-9.]+) ms", prof[d]), num(r"\| log zapis [0-9.]+ ms / (\d+) linii", prof[d])
        if v is None:
            continue
        if d in on_set and num(r"stara droga (\d+)", ol[d], default=0) == 0:
            wms[d] = v
            wn[d] = n or 0
        elif d not in on_set:
            wms_off[d] = v
        else:
            wms_mix[d] = v   # klucz [WL], ale czesc zapisow doby poszla stara droga (przelaczenie w trakcie doby albo potkniecie pisarza) - poza srednia, liczone w O6-4
    rule1 = f"<= {E8_O6_WRITE_MS:.0f} ms/dobe srednio w dobach z kluczem [WL] (projekt rozdz. 3 \"E8/O6\"; bez linii Profil doby - INFO)"
    if wms:
        avg = sum(wms.values()) / len(wms)
        dmax = max(wms, key=lambda d: wms[d])
        tot_n = sum(wn.values())
        txt = (f"srednio {avg:.1f} ms/dobe w {len(wms)} dobach, najwiecej {wms[dmax]:.1f} ms (d{run_day(dmax, start)}); zapisow srednio {tot_n / len(wms):.0f}/d"
               + (f", {1000.0 * sum(wms.values()) / tot_n:.1f} us na zapis" if tot_n else ""))
        if wms_off:
            txt += f"; klucz wylaczony {len(wms_off)} dob: srednio {sum(wms_off.values()) / len(wms_off):.1f} ms/dobe"
        if wms_mix:
            txt += f"; poza srednia {len(wms_mix)} dob [WL] z zapisami stara droga (patrz O6-4): srednio {sum(wms_mix.values()) / len(wms_mix):.1f} ms/dobe"
        rep.add("O6-1: czas zapisu logu przy kluczu [WL]", txt, rule1, avg <= E8_O6_WRITE_MS)
    else:
        # recenzja E8/O6: prawdziwy powod werdyktu INFO (bylo "klucz wylaczony w calym oknie" takze wtedy, gdy klucz byl wlaczony, a doby wypadly ze sredniej)
        if not any(d in prof for d in days):
            why = "brak linii Profil doby (E8/0) - Stage8ProfileLog wylaczony?"
        elif not on:
            why = "klucz LogKeepOpen wylaczony w calym oknie"
        elif wms_mix:
            why = (f"klucz [WL] w {len(on)} dobach, zadna nie wchodzi do sredniej: w {len(wms_mix)} byly zapisy stara droga (klucz przelaczany w trakcie doby "
                   f"albo potkniecia pisarza - patrz O6-4; srednio {sum(wms_mix.values()) / len(wms_mix):.1f} ms/dobe)")
        else:
            why = f"klucz [WL] w {len(on)} dobach, zadna z nich nie ma linii Profil doby (E8/0) z czasem zapisu"
        rep.add("O6-1: czas zapisu logu", why + (f"; przy wylaczonym kluczu srednio {sum(wms_off.values()) / len(wms_off):.1f} ms/dobe" if wms_off else ""), rule1, None)

    # O6-2: proba 3 dob sesji (cala sesja, nie tylko okno): bajty i numer linii doby w glownym pliku
    samp = [(s, E8_O6_SAMPLE.search(s)) for s in allo]
    samp = [(s, m) for s, m in samp if m]
    rule2 = ("rozjazd bajtow 0 i plikow z rozjazdem 0 w kazdej probie; numer linii doby w glownym pliku = liczba linii wyslanych "
             "(R9 - tak samo przy kluczu wlaczonym i wylaczonym; bez prob w logu - INFO)")
    if samp:
        gap = sum(int(m.group(6)) for _, m in samp)
        gapf = sum(int(m.group(7)) for _, m in samp)
        last = samp[-1][1]
        want = {int(m.group(8)) for _, m in samp}
        pos, bad_pos, how = {}, [], ""
        if logp and os.path.isfile(logp):
            mark = (E8_O6_LINE).encode("utf-8")
            with open(logp, "rb") as f:
                for i, ln in enumerate(f, 1):
                    if mark in ln and b"glowny plik linii wyslanych " in ln:
                        k = num(r"glowny plik linii wyslanych (\d+)", ln.decode("utf-8", errors="replace"))
                        if k is not None:
                            pos[k] = i
            bad_pos = sorted(k for k in want if pos.get(k) != k)
            how = (f"; numer linii w pliku zgodny w {len(want) - len(bad_pos)} z {len(want)} prob"
                   + (f" (niezgodne: " + ", ".join(f"wyslanych {k} / linia {pos.get(k, '?')}" for k in bad_pos[:3]) + ")" if bad_pos else ""))
        else:
            how = "; numer linii w pliku - brak pliku logu (INFO)"
        keys = "".join("W" if "LogKeepOpen [WL]" in s else "w" for s, _ in samp)
        ctrl_ms = [fnum(r"sprawdzenie ([0-9.]+) ms", s, 0.0) for s, _ in samp]
        worst = [s.split("[najwiekszy rozjazd: ", 1)[1].rstrip("]") for s, _ in samp if "[najwiekszy rozjazd: " in s]
        rep.add("O6-2: proba 3 dob - wyslane do plikow wobec plikow (bajty wszystkich plikow, linie glownego)",
                f"prob {len(samp)} z {last.group(2)} (klucz w probach: {keys}; W = wlaczony); ostatnia: plikow {last.group(3)}, bajtow wyslanych {last.group(4)} / "
                f"w plikach {last.group(5)}; rozjazd bajtow lacznie {gap}, plikow z rozjazdem {gapf}" + how
                + (f"; najwiekszy: {worst[0]}" if worst else "") + f"; koszt sprawdzenia najwiecej {max(ctrl_ms):.2f} ms",
                rule2, gap == 0 and gapf == 0 and not bad_pos)
    else:
        rep.add("O6-2: proba 3 dob - wyslane do plikow wobec plikow", "brak linii z proba (sesja bez pierwszych trzech taktow doby w logu?)", rule2, None)

    # O6-3: wpisy kontrolne drogi Log.Error (K2-5) - sa w pliku logu, bo narzedzie czyta je z pliku
    n_ctl = sum(1 for s in lines if s.startswith(E8_O6_CTL))
    tried = max((num(r"wpisow kontrolnych drogi bledu (\d+)", s, default=0) for s in allo), default=0)
    key3 = [s for s, _ in samp]
    rep.add("O6-3: wpisy kontrolne drogi Log.Error w pliku logu",
            f"w pliku {n_ctl}, wyslanych {tried}" + (f"; klucz [WL] w {sum(1 for s in key3 if 'LogKeepOpen [WL]' in s)} z {len(key3)} prob" if key3 else ""),
            "w pliku = wyslanych i >= 1 (wpis idzie droga Log.Error - plik glowny, ten sam pisarz; bez slow 'ERROR in', zeby T0 go nie liczyl)",
            (n_ctl == tried and tried >= 1) if (tried or n_ctl) else None)

    # O6-4: zapisy stracone i potkniecia pisarza (liczniki sesji - ostatnia linia), zapisy stara droga w dobach [WL], linie bledu
    lost = num(r"straconych (\d+)", allo[-1], default=0)
    stum = num(r"potkniecia pisarza (\d+)", allo[-1], default=0)
    old_on = sum(num(r"stara droga (\d+)", ol[d], default=0) for d in on)
    errs = sum(1 for s in lines if s.startswith("ERROR in Log.DailyO6"))
    first = allo[-1].split("[pierwsze: ", 1)[1].split("]", 1)[0] if "[pierwsze: " in allo[-1] else ""
    opened, closed = num(r"od startu sesji otwarc (\d+)", allo[-1], default=0), num(r"zamkniec (\d+)\)", allo[-1], default=0)
    rep.add("O6-4: zapisy stracone, potkniecia pisarza, zapisy stara droga przy [WL], linie bledu Log.DailyO6",
            f"{lost} / {stum} / {old_on} / {errs}" + (f" (pierwsze potkniecie: {first})" if first else "") + f"; od startu sesji otwarc pisarzy {opened}, zamkniec {closed}",
            "0 / 0 / 0 / 0 (blad pisarza = potkniecie, linia idzie stara droga - liczony, bez wylacznika na sesje)",
            lost == 0 and stum == 0 and old_on == 0 and errs == 0)


def etap8_p3woj(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """P3/WOJSKO (bieg roczny 364 doby WGRANIA 34/35, TRIAZ-3 obszar "wojsko": O1-2, O1-3, O1-4, O1-7 A). Linie doby (dzien gry - klucz = dzien ksiegi):
    "Renty korony (180)" (pola P3/W1), "Budzet rodow (166)" (pola P3/W2), "Kontrakty najemnikow (185)" (pola P3/W3), "Wezwania do wojny (168)" (pole P3/W4)
    i budzet-rodow.csv. W1: rody z lennem bez warunku renty <= 10% (sr28; bylo 27%), "sluzba" <= 8 i "oba" <= 2, E5/F9 <= 20 tys. zl/d (bylo 62.6), rody z lennem
    z 0 ludzi <= 12 (bylo 29), Polnoc >= 7.5 tys. (bieg roczny); W2: zold na zwalnianego >= 5 zl (bylo 3.65), zold na czlowieka rodow na pulapie <= 1.25 x
    rodow z luzem (bylo 1.51 x); W3: latka zadatku BK wpieta, ludzie najemnikow >= 2 000, kiesy kompanii <= +10 tys. zl/d (bylo 48.7); W4: dlug "sprzed
    paczki" nowy 0 i splacone w nicosc 0 (bylo 3.56 / 2.0 mln). Calosc: partie rodow AI sr28 >= 70 tys. w biegu rocznym (bylo 63 tys.). Progi wiaza tylko,
    gdy log ma pola paczki (log sprzed paczki - te same liczby jako INFO, do porownania); liczby "na dobe 337-364" wiaza przy oknie >= 337 dob."""
    def series(prefix):
        return {d: s for d, s in e4_series(lines, prefix, 1).items() if 1 <= run_day(d, start) <= until}
    r180, b166, k185, c168 = series("Renty korony (180): dzien"), series("Budzet rodow (166): dzien"), series("Kontrakty najemnikow (185): dzien"), series("Wezwania do wojny (168): dzien")
    year = until >= 337
    def tail(d, n=28):
        return sorted(d)[-n:]
    def avg(xs):
        xs = [x for x in xs if x is not None]
        return (sum(xs) / len(xs)) if xs else None
    def fmt(v, f="{:.0f}"):
        return "-" if v is None else f.format(v)

    # ---- W1: renty korony (180)
    p1 = [d for d in r180 if "P3/W1 sluzba na miare srodkow" in r180[d]]
    if not r180:
        rep.add("P3W1: linia Renty korony (180)", "brak w oknie", "jest (180 czynne)", None)
    else:
        on = [d for d in p1 if "(Crown Rent Service At Means): wylaczone" not in r180[d]]
        called = [d for d in p1 if "(nie zobowiazuja - Crown Rent Contact Only When Called)" in r180[d]]
        rep.add("P3W1-0: pola P3/W1 w linii 180; klucze Crown Rent Service At Means / Contact Only When Called",
                f"dob z polami {len(p1)} z {len(r180)}; na miare srodkow wl {len(on)} dob, tylko przy wezwaniu wl {len(called)} dob",
                "pola w kazdej dobie od wgrania paczki; oba klucze wlaczone (wylaczony = stan sprzed)", (len(on) == len(p1) and len(called) == len(p1)) if p1 else None)
        t = tail(r180)
        rx = re.compile(r"z warunkiem \d+, bez warunku (\d+) \(([0-9.]+)%\) - zaloga (\d+), sluzba (\d+), oba (\d+)")
        mm = [rx.search(r180[d]) for d in t]
        mm = [m for m in mm if m]
        if mm:
            pc = [float(m.group(2)) for m in mm]
            last = mm[-1]
            a = sum(pc) / len(pc)
            rep.add(f"P3W1-1: rody z lennem bez warunku renty korony (sr{len(mm)} ostatnich dob okna)", f"{a:.1f}% (najwiecej {max(pc):.1f}%)",
                    "<= 10% (bieg roczny przed paczka: 27% w d337-364, 28.8% w d364)", (a <= 10.0) if p1 else None)
            rep.add("P3W1-2: bez warunku wedlug przyczyny, ostatnia doba okna (sluzba / zaloga / oba)", f"{last.group(4)} / {last.group(3)} / {last.group(5)}",
                    "sluzba <= 8, oba <= 2 (przed paczka w d364: 47 / 3 / 7); 'oba' > 2 po 120 dobach = drugi krok dla warunku zalogi (do decyzji)",
                    (int(last.group(4)) <= 8 and int(last.group(5)) <= 2) if p1 else None)
        f9 = avg([num(r"\(Crown Rent Held To Serving\): (\d+) \(siedza w rentach\)", r180[d]) for d in t])
        rep.add("P3W1-3: E5/F9 udzialy rodow bez warunku oddane sluzacym (sr28, zl/d)", fmt(f9), "<= 20 000 (przed paczka 62 558 w d337-364)",
                (f9 <= 20000) if (p1 and f9 is not None) else None)
        rm = re.compile(r"P3/W1 sluzba na miare srodkow \(Crown Rent Service At Means\): rodow w wojnie (\d+) \(z nich sluzylo i tak (\d+), doba zaliczona (\d+)\), wymog sluzby zdjety u (\d+) rodow")
        ms = [rm.search(r180[d]) for d in t if d in p1]
        ms = [m for m in ms if m]
        if ms:
            g = [sum(int(m.group(i)) for m in ms) / len(ms) for i in (1, 2, 3, 4)]
            rep.add("P3W1-4: na miare srodkow (sr28): rodow w wojnie / z nich sluzylo i tak / doba zaliczona / wymog zdjety (rody z lennem)",
                    f"{g[0]:.0f} / {g[1]:.0f} / {g[2]:.0f} / {g[3]:.0f}", "INFO (rachunek triazu: 51 rodow z lennem w d84, 118 w d364 przy progu 0.6; wymog zdjety - ok. 48)", None)
            # recenzja P3: skutek w zlocie i ludziach - rody z lennem "na miare", ile z nich z renta, ich renty i ludzie w ich druzynach
            rf = re.compile(r"rody z lennem na miare (\d+) \(z renta dzis (\d+)\), ich renty dzis (\d+) zl, w ich druzynach (\d+) ludzi")
            fs = [rf.search(r180[d]) for d in t if d in p1]
            fs = [m for m in fs if m]
            if fs:
                h = [sum(int(m.group(i)) for m in fs) / len(fs) for i in (1, 2, 3, 4)]
                rep.add("P3W1-4b: rody z lennem na miare srodkow (sr28): rodow / z renta / ich renty zl na dobe / ludzi w ich druzynach",
                        f"{h[0]:.0f} / {h[1]:.0f} / {h[2]:.0f} / {h[3]:.0f}",
                        "INFO (przed paczka 57 rodow bez renty mialo w druzynach 5 785 ludzi w d337-364, 24 264 w d57-84; utracona renta 73.9 tys. zl/d)", None)
        rs = re.compile(r"P3/W1 styk krolestw w wojnie wedlug zrodla \(krolestw w wojnie (\d+)\): armia w polu (\d+), oblezenie (\d+), napad na wlasna osade (\d+), tylko rajdy i bitwy wlasnych lordow (\d+)")
        ss = [rs.search(r180[d]) for d in t if d in p1]
        ss = [m for m in ss if m]
        if ss:
            g = [sum(int(m.group(i)) for m in ss) / len(ss) for i in (1, 2, 3, 4, 5)]
            lc = avg([num(r"tylko rajdy i bitwy wlasnych lordow \d+, w nich rodow (\d+)", r180[d]) for d in t if d in p1])   # recenzja P3
            rep.add("P3W1-5: styk krolestw w wojnie wedlug zrodla (sr28 krolestw na dobe): w wojnie / armia w polu / oblezenie / napad na wlasna osade / tylko rajdy",
                    f"{g[0]:.1f} / {g[1]:.1f} / {g[2]:.1f} / {g[3]:.1f} / {g[4]:.1f}" + (f" (w nich rodow {lc:.0f})" if lc is not None else ""),
                    "INFO (brakujacy pomiar triazu: ile krolestw ma dobe wojny tylko z rajdow wlasnych lordow)", None)

    # ---- W2: budzet rodow (166)
    p2 = [d for d in b166 if "P3/W2 zwolnieni wedlug tieru" in b166[d]]
    if b166:
        t = tail(b166)
        rt = re.compile(r"P3/W2 zwolnieni wedlug tieru \(ludzi / ich zold zl\): t1-2 (\d+) / (\d+), t3-4 (\d+) / (\d+), t5\+ (\d+) / (\d+) \(Release Across Tiers(: losowo| wylaczone)")
        tt = [rt.search(b166[d]) for d in t if d in p2]
        tt = [m for m in tt if m]
        if tt:
            men = [sum(int(m.group(i)) for m in tt) for i in (1, 3, 5)]
            wage = [sum(int(m.group(i)) for m in tt) for i in (2, 4, 6)]
            key_on = all(m.group(7) == ": losowo" for m in tt)
            per = (sum(wage) / sum(men)) if sum(men) > 0 else None
            rep.add(f"P3W2-1: zwolnieni 166 wedlug tieru (suma {len(tt)} dob): ludzi t1-2 / t3-4 / t5+; zold na zwalnianego",
                    f"{men[0]} / {men[1]} / {men[2]}; " + (f"{per:.2f} zl" if per is not None else "nikt nie zwolniony") + f"; Release Across Tiers {'wl' if key_on else 'WYL (w czesci dob)'}",
                    ">= 5.0 zl na zwalnianego przy kluczu (przed paczka 3.65 zl przy sredniej partii 9.28 zl; t3+ 22-32% zwalnianych)",
                    (per >= 5.0) if (per is not None and key_on) else None)
        else:
            rep.add("P3W2-1: zwolnieni 166 wedlug tieru", "brak pola P3/W2 (log sprzed paczki)", ">= 5.0 zl na zwalnianego przy kluczu", None)
        rel = avg([num(r"zwolnieni: do wsi \d+ ludzi \(z partii (\d+), z zalog \d+\)", b166[d]) for d in t])
        rep.add("P3W2-2: zwolnieni przez budzet z partii (sr28 na dobe)", fmt(rel),
                "INFO (przed paczka 215/d w d57-84, 520/d w d337-364; oczekiwane ok. polowa glow przy tym samym zoldzie zwalnianych)", None)
        ge = [re.search(r"zajely caly pulap \(na partie 0\): (\d+), z tego bez ludzi w partiach (\d+)", b166[d]) for d in t if d in p2]
        ge = [m for m in ge if m]
        if ge:
            rep.add("P3W2-3: rody w wojnie, ktorym zalogi i karawany zajely caly pulap / z tego bez ludzi w partiach (ostatnia doba okna)",
                    f"{ge[-1].group(1)} / {ge[-1].group(2)}", "INFO (triaz: 38 rodow, partie 17 950 -> 616 ludzi - kolejnosc zwolnien nic tu nie zmienia; poprawia je renta W1)", None)

    # ---- W3: kontrakty najemnikow (185)
    wired = [s for s in lines if s.startswith("Kontrakty najemnikow (185): kontrakt gry dla AI")]
    p3 = [d for d in k185 if "P3/W3 zadatek BK wstrzymany" in k185[d]]
    if k185:
        dn = [re.search(r"P3/W3 zadatek BK wstrzymany \(Merc Bk Down Payment Ai Off\): (\d+) najmow, (\d+) zl", k185[d]) for d in sorted(p3)]
        dn = [m for m in dn if m]
        hires, gold = sum(int(m.group(1)) for m in dn), sum(int(m.group(2)) for m in dn)
        w_ok = bool(wired) and all("AddDownPayment) wpiety" in s for s in wired)
        # recenzja P3: latka wpieta to za malo - prefiks musi byc wolany (wzor bledu W4: latka konca porozumienia wpieta, a w naszym wywolaniu nie odpalala).
        # Kazdy najem kompanii z ludzmi w polu daje nowa umowe 185 (bieg roczny: 681 najmow, 678 nowych umow) - najmow co najmniej polowa nowych umow;
        # pierwsza doba okna pominieta (start kampanii: umowy kompanii, ktore zaczynaja gre w sluzbie - bez najmu)
        deals = sum(num(r"\(nowe umowy (\d+),", k185[d], default=0) for d in p3 if d != min(k185))
        called = deals == 0 or hires * 2 >= deals
        rep.add("P3W3-1: zadatek BK dla kompanii AI wstrzymany: latka; najmy i zloto, ktore zostalo w kiesach krolow (suma okna)",
                (("wpieta" if w_ok else "BRAK latki albo linii startowej") + f"; {hires} najmow ({hires / max(1, len(p3)):.2f} na dobe) przy {deals} nowych umowach 185, {gold} zl ({gold / max(1, len(p3)):.0f} zl/d)"
                 + ("" if called else " - LATKA NIE JEST WOLANA (najmy bez wstrzymanego zadatku)")
                 + (f"; klucz wylaczony w {len(p3) - len(dn)} dobach" if len(dn) < len(p3) else "")) if p3 else "brak pola P3/W3 (log sprzed paczki)",
                "latka wpieta i wolana (najmow >= polowa nowych umow 185), klucz wlaczony; ok. 1.9 najmu na dobe i ok. 33 tys. zl/d (przed paczka 681 najmow i 12.09 mln w roku z kies krolow do kompanii)",
                (w_ok and called and len(dn) == len(p3)) if p3 else None)
        pn = [re.search(r"P3/W3 kontrakt za ludzi pod bronia \(Merc Contract Pays Men Under Arms\): nalezne wedlug umowy (\d+), za ludzi pod bronia (\d+)", k185[d]) for d in sorted(p3)]
        pn = [m for m in pn if m]
        if pn:
            deal, now = sum(int(m.group(1)) for m in pn), sum(int(m.group(2)) for m in pn)
            rep.add("P3W3-2: kontrakty najemnikow: nalezne za ludzi pod bronia wobec naleznych wedlug umowy (suma okna)",
                    f"{now} wobec {deal} ({100.0 * now / deal:.0f}%; w skarbcach zostaje {(deal - now) / max(1, len(pn)):.0f} zl/d)" if deal > 0 else "brak kontraktow",
                    "INFO (rachunek: ok. 65% - 5.73 z 8.85 mln w roku, czyli ok. 7.6 tys. zl/d zostaje we wplywach dnia koron)", None)
        elif p3:
            rep.add("P3W3-2: kontrakty najemnikow: nalezne za ludzi pod bronia", "klucz Merc Contract Pays Men Under Arms wylaczony albo brak pola", "klucz wlaczony", False)
        mn = avg([num(r"ludzie najemnikow AI (\d+) / z umowy", k185[d]) for d in tail(k185)])
        rep.add("P3W3-3: ludzie najemnikow AI (sr28)", fmt(mn), ">= 2 000 (przed paczka 2 531 w d337-364; mniej = marza 0.30 nie starcza kompaniom)",
                (mn >= 2000) if (p3 and mn is not None) else None)

    # ---- W4: wezwania do wojny (168)
    if c168:
        p4 = [d for d in c168 if "P3/W4 po zerwaniu reszta ceny zdjeta" in c168[d]]
        new = sum(num(r"sprzed paczki \(wezwany dostal od gry z niczego\): nowy (\d+)", c168[d], default=0) for d in c168)
        void = sum(num(r"splacone dzis ze skarbcow w nicosc \(rownowazy\) (\d+)", c168[d], default=0) for d in c168)
        ended = sum(num(r"reszta ceny skreslona (\d+)", c168[d], default=0) for d in c168)
        ours = sum(num(r"\(latka konca porozumienia nie zadzialala\) (\d+)", c168[d], default=0) for d in p4)
        off = len([d for d in p4 if "Call To War Break Restores Wallet wylaczone" in c168[d]])
        rep.add("P3W4-1: wezwania 168: dlug 'sprzed paczki' nowy / splacony ze skarbcow w nicosc (suma okna)", f"{new} / {void}",
                "0 / 0 w kampanii zaczetej z paczka (przed paczka w roku 3 558 755 / 2 005 256)", (new == 0 and void == 0 and off == 0) if p4 else None)
        rep.add("P3W4-2: reszta cen zerwanych wezwan (suma okna) wobec reszty zdjetej z portfela przez nas",
                f"{ended} wobec {ours}" + (f"; klucz wylaczony w {off} dobach" if off else "") if p4 else f"{ended}; brak pola P3/W4 (log sprzed paczki)",
                "rowne (latka gry nie zadzialala - zdejmujemy sami) albo 0 przy braku 'nowego' dlugu (latka gry zadzialala)",
                ((ours == ended or ours == 0) and new == 0) if p4 else None)
    else:
        rep.add("P3W4: linia Wezwania do wojny (168)", "brak w oknie (zadnego porozumienia)", "INFO", None)

    # ---- budzet-rodow.csv: ludzie, kiesy kompanii, rody bez ludzi
    packed = bool(p1 or p2 or p3)
    try:
        rows = read_csv(csv_path_of(logp)) if logp else []
    except Exception:
        rows = []
    def ival(r, k):
        try:
            return int(float(r.get(k) or 0))
        except ValueError:
            return 0
    byd = {}
    for r in rows:
        try:
            d = int(r.get("dzien") or -1)
        except ValueError:
            continue
        if 1 <= run_day(d, start) <= until:
            byd.setdefault(d, []).append(r)
    if not byd:
        rep.add("P3W-CSV: budzet-rodow.csv", "brak pliku albo dob w oknie", "plik obok logu (uklad archiwum albo gry)", None)
        return
    days = sorted(byd)
    t = days[-28:]
    men = avg([sum(ival(r, "ludzi_partie") for r in byd[d]) for d in t])
    rep.add(f"P3W-5: ludzie w partiach rodow AI (budzet-rodow.csv, sr{len(t)} ostatnich dob okna)", fmt(men),
            ">= 70 000 w biegu rocznym (przed paczka 63 129 w d337-364 i dalej w dol do ok. 50 tys.; rachunek paczki 72-80 tys.); krotsze okno - INFO",
            (men >= 70000) if (packed and year and men is not None) else None)
    last = byd[days[-1]]
    fief = [r for r in last if r.get("rodzaj") in ("miasto", "zamek")]
    zero = sum(1 for r in fief if ival(r, "ludzi_partie") == 0)
    rep.add("P3W1-6: rody z lennem z 0 ludzi w partiach (ostatnia doba okna)", f"{zero} z {len(fief)}",
            "<= 12 (przed paczka 8 w d84, 15 w d196, 29 w d364)", (zero <= 12) if packed else None)
    north = avg([sum(ival(r, "ludzi_partie") for r in byd[d] if r.get("krolestwo") == "The North") for d in t])
    rep.add("P3W1-7: Polnoc - ludzie w partiach rodow (sr28)", fmt(north), ">= 7 500 w biegu rocznym (przed paczka 5 118 sr d337-364, 4 855 w d364); krotsze okno - INFO",
            (north >= 7500) if (packed and year and north is not None) else None)
    # rod "na pulapie zoldu": zold razem (partie + zalogi + karawany) z 28 dob >= 0.9 x pulap z tych dob; reszta - "z luzem" (kolumna na_suficie to co
    # innego - sufit WIELKOSCI partii). Wasale i rody bez lenna z budzetem; kompanie najemne osobno (pulap = zold z umowy)
    acc = {}
    for d in t:
        for r in byd[d]:
            if r.get("rodzaj") not in ("miasto", "zamek", "bez lenna") or not (r.get("pulap") or "").strip():
                continue
            a = acc.setdefault(r.get("rod_id"), [0, 0, 0, 0])
            a[0] += ival(r, "zold_partii") + ival(r, "zold_zalog") + ival(r, "zold_karawan"); a[1] += ival(r, "pulap")
            a[2] += ival(r, "zold_partii"); a[3] += ival(r, "ludzi_partie")
    cw = sum(a[2] for a in acc.values() if a[0] >= 0.9 * a[1]); cm = sum(a[3] for a in acc.values() if a[0] >= 0.9 * a[1])
    fw = sum(a[2] for a in acc.values() if a[0] < 0.9 * a[1]); fm = sum(a[3] for a in acc.values() if a[0] < 0.9 * a[1])
    ncap = sum(1 for a in acc.values() if a[0] >= 0.9 * a[1])
    capd, free = (cw / cm) if cm > 0 else None, (fw / fm) if fm > 0 else None
    rep.add("P3W2-4: zold partii na czlowieka (sr28): rody na pulapie zoldu (zold >= 0.9 pulapu) wobec rodow z luzem",
            f"{fmt(capd, '{:.2f}')} zl ({ncap} rodow, {cm / max(1, len(t)):.0f} ludzi) wobec {fmt(free, '{:.2f}')} zl ({len(acc) - ncap} rodow, {fm / max(1, len(t)):.0f} ludzi)"
            + (f" = {capd / free:.2f} x" if capd and free else ""),
            "<= 1.25 x w biegu rocznym (przed paczka 7.89 wobec 5.21 zl = 1.51 x w d337-364, 6.07 wobec 4.49 = 1.35 x w d57-84); krotsze okno - INFO",
            (capd / free <= 1.25) if (p2 and year and capd and free) else None)
    # kompanie = rody, ktore w oknie choc raz byly w sluzbie najemnej (rodzaj "najemnik" maja tylko w dobach sluzby - poza nia "bez lenna")
    mids = {r.get("rod_id") for d in days for r in byd[d] if r.get("rodzaj") == "najemnik"}
    mg0 = sum(ival(r, "G") for r in byd[days[0]] if r.get("rod_id") in mids)
    mg1 = sum(ival(r, "G") for r in last if r.get("rod_id") in mids)
    rate = (mg1 - mg0) / max(1, len(days) - 1)
    rep.add(f"P3W3-4: kiesy {len(mids)} kompanii najemnych: pierwsza -> ostatnia doba okna (przyrost na dobe)", f"{mg0} -> {mg1} ({rate:+.0f} zl/d)",
            "<= +10 000 zl/d (przed paczka 2.87 -> 20.60 mln w roku = +48.7 tys. zl/d; rachunek po A i B ok. +4.5 tys. zl/d)", (rate <= 10000) if p3 else None)
def etap8_p3_zelazo(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """P3/ZELAZO (TRIAZ-3 bieg roczny 13.10, obszar "zelazo": O2-1 kontrakt wozem Z1 + pomiary P2, O2-2 bezpiecznik regulatora Z2, O2-3 zamki Z3-A / Z3-B,
    O2-7 towar kasowany lordom Z4). Linie: "Kontrakty surowca (174)" (wstawka "wozem kupcow (P3/Z1)"), "Zelazo wedlug ladow (P3/P2a)", "Miasta bez rudy i
    strzal (174b)", "Regulator wsi (221)" (bezpiecznik), "Targ przy zamku (5.11)" (wjazdy nieskierowane), "Konie - smierc, lup, dobytek (E6/K1)" (polki wedlug
    osady, porzucone przez lordow), "Zelazo (lupy) (214)", "Towary: ... iron". Brak linii = INFO (log sprzed paczki), nigdy wyjatek. Uwaga na daty: linia K1
    ma numer dnia o 1 wiekszy niz "Towary" z tego samego taktu - sumy okna licza sie po dobach kazdej linii osobno."""
    def inwin(d):
        return 1 <= run_day(d, start) <= until

    def isum(pat, rows):
        return sum((num(pat, s, int, 0) or 0) for s in rows)

    mo = {d: s for d, s in by_day(lines, "Kontrakty surowca (174): dzien").items() if inwin(d)}
    z1 = {d: s for d, s in mo.items() if "wozem kupcow (P3/Z1): " in s}
    if not z1:
        rep.add("P3/Z1: wstawka wozem kupcow (P3/Z1) w linii Kontrakty surowca (174)", "brak w logu", "jest od wgrania P3/ZELAZO", None)
    else:
        days = sorted(z1)
        rows = [z1[d] for d in days]
        on = [d for d in days if "wozem kupcow (P3/Z1): CZYNNE" in z1[d]]
        rep.add("P3/Z1-1: kontrakt wozem czynny", f"dob z wstawka {len(days)}, CZYNNE {len(on)}", "CZYNNE w kazdej dobie (klucz TownMaterialOrderByCart)", len(on) == len(days))
        made = isum(r"wozem kupcow \(P3/Z1\): \w+(?: \([^)]*\))? - zawarto (\d+) \[", rows)
        ore = isum(r"wozem kupcow \(P3/Z1\): .*? - zawarto \d+ \[ruda (\d+)", rows)
        gold = isum(r"sztuk\] za (\d+) zl \(kasy miast-celow", rows)
        cas = isum(r"w tym ze zrodel-zamkow (\d+) ", rows)
        casq = isum(r"w tym ze zrodel-zamkow \d+ \(sztuk (\d+)\)", rows)
        sea = isum(r"\), morzem (\d+) \(sztuk \d+\); dojechalo wozow", rows)
        arr = isum(r"dojechalo wozow (\d+) ", rows)
        arrq = isum(r"dojechalo wozow \d+ \(sztuk (\d+),", rows)
        back = isum(r", zawrocone (\d+) \(sztuk", rows)
        mix = isum(r"w tym ladem i morzem (\d+) \(sztuk", rows)   # recenzja P3/Z1: para bez drogi ladowej i bez rejsu port-port
        rest = [(run_day(d, start), num(r"reszta wozow (-?\d+)", z1[d])) for d in days]
        bad = [x for x in rest if x[1] not in (None, 0)]
        n = max(1, len(days))
        road = num(r", w drodze (\d+) sztuk w", rows[-1], int, 0)
        rep.add("P3/Z1-2: wozy kupcow - zakupy i dostawy (INFO)",
                f"zawarto {made} ({made / n:.1f}/d), rudy {ore} lup ({ore / n:.1f}/d), za {gold} zl; ze zrodel-zamkow {cas} (sztuk {casq}), morzem {sea}, ladem i morzem {mix}; "
                f"dojechalo {arr} wozow ({arrq} sztuk), zawrocone {back}; w drodze na koniec {road} sztuk",
                "INFO (rachunek: kilkadziesiat wozow/d w pierwszych tygodniach, potem kilkanascie)", None)
        rep.add("P3/Z1-3: kontrola wozow (wczoraj + kupione - dowiezione - zawrocone = dzis)", f"dob z reszta != 0: {len(bad)}" + (f" {bad[:5]}" if bad else ""),
                "reszta wozow 0 w kazdej dobie (nic z niczego, nic w nicosc)", not bad)
        st_ = isum(r"potkniecia wozow (\d+)", rows)
        ms = [fnum(r"czas wozow ([0-9.]+) ms", s) for s in rows]
        ms = [x for x in ms if x is not None]
        rep.add("P3/Z1-4: potkniecia i czas wozow", f"potkniecia {st_}; czas srednio {sum(ms) / max(1, len(ms)):.1f} ms/d, najwiecej {max(ms) if ms else 0:.1f} ms",
                "potkniecia 0; czas <= 30 ms/d srednio (zasada kosztu paczki)", st_ == 0 and (sum(ms) / max(1, len(ms)) <= 30.0 if ms else True))
        why = {}
        for s in rows:
            m = re.search(r"bez kontraktu wedlug surowca \(P3\): (.*?); wozem kupcow", s)
            g = re.search(r"ruda \d+ \(([^)]*)\)", m.group(1)) if m else None
            if g:
                for part in g.group(1).split(", "):
                    k = part.rsplit(" ", 1)
                    if len(k) == 2 and k[1].isdigit():
                        why[k[0]] = why.get(k[0], 0) + int(k[1])
        rep.add("P3/Z1-5: powody bez kontraktu dla rudy (suma okna; INFO)", ", ".join(f"{k} {v}" for k, v in sorted(why.items(), key=lambda x: -x[1])) or "-",
                "INFO (do decyzji P3: brak zrodla = brak produkcji na ladzie, kasa miasta = miasta przy zapasie kupcow)", None)
    # miasta bez zelaza: srednia od d91 i ostatnie 30 dob okna (linia doby 174; prog narzedzia 30, cel projektu 15)
    emp = {run_day(d, start): num(r"miast bez rudy (\d+) z", s) for d, s in mo.items()}
    emp = {k: v for k, v in emp.items() if v is not None}
    late = [v for k, v in emp.items() if k >= 91]
    if late:
        last30 = [v for k, v in emp.items() if k > until - 30] or late
        rep.add("P3/Z1-6: miasta bez zelaza (linia 174, doby 91+ i ostatnie 30 dob okna)",
                f"srednio od d91 {sum(late) / len(late):.1f}, ostatnie 30 dob {sum(last30) / len(last30):.1f} (bieg roczny przed paczka: 40.1 i 51-61)",
                "<= 30 srednio w ostatnich 30 dobach (rachunek podwazenia 20-29; cel projektu 15 wymaga P3 - Essos)", sum(last30) / len(last30) <= 30.0)
    else:
        rep.add("P3/Z1-6: miasta bez zelaza (doby 91+)", "okno krotsze niz 91 dob albo brak linii", "INFO", None)
    lands = {d: s for d, s in by_day(lines, "Zelazo wedlug ladow (P3/P2a): dzien").items() if inwin(d) and run_day(d, start) >= 91}
    if lands:
        def land(name, pat):
            v = [num(name + r" \(miast \d+\): .*?" + pat, s) for s in lands.values()]
            v = [x for x in v if x is not None]
            return sum(v) / len(v) if v else 0.0
        ls = sorted(lands)[-1]
        pp, pu, pe = r"lupy z kopaln (\d+)", r"zuzycie zmierzone (\d+)", r"miast bez zelaza (\d+) z"
        how = re.search(r"podzial: (.*?) \|", lands[ls])
        how = how.group(1)[:110] if how else "?"
        rep.add("P3/P2a: zelazo wedlug ladow (srednio doby 91+; INFO)",
                f"Westeros: lupy {land('Westeros', pp):.0f}/d, zuzycie {land('Westeros', pu):.0f}/d, bez zelaza {land('Westeros', pe):.1f}; "
                f"Essos: lupy {land('Essos', pp):.0f}/d, zuzycie {land('Essos', pu):.0f}/d, bez zelaza {land('Essos', pe):.1f}; podzial: {how}",
                "INFO (do decyzji P3: dluzszy rejs albo regulator wsi osobno na lad; rozpoznanie: Westeros 60 miast, Essos 37)", None)
    nm = {d: s for d, s in by_day(lines, "Miasta bez rudy i strzal (174b): dzien").items() if inwin(d)}
    if nm:
        s = nm[sorted(nm)[-1]]
        m = re.search(r"porty bez rudy (\d+): rejs <= 1000 (\d+), 1000-2400 (\d+), > 2400 (\d+), bez zrodla-portu (\d+)", s)
        c = re.search(r"; zamki z ruda (\d+) \(razem (\d+)\), najwiekszy zapas: ([^;]*)", s)
        if m or c:
            rep.add("P3/P2b,d: zamki z ruda i rejsy portow bez rudy (ostatnia linia nazw; INFO)",
                    (f"zamki z ruda {c.group(1)} (razem {c.group(2)} lup; {c.group(3)[:120]})" if c else "zamki -")
                    + (f"; porty bez rudy {m.group(1)}: rejs <= 1000 {m.group(2)}, 1000-2400 {m.group(3)}, > 2400 {m.group(4)}, bez zrodla-portu {m.group(5)}" if m else ""),
                    "INFO (P3 MORZE: czy podniesienie TownMaterialOrderSeaMaxRoute do 2400 obejmie porty bez rudy)", None)

    # Z2: bezpiecznik regulatora wsi
    vd = {d: s for d, s in by_day(lines, "Regulator wsi (221): dzien").items() if inwin(d) and " - CZYNNY, decyzja " in s}
    if not vd:
        rep.add("P3/Z2: decyzje regulatora wsi w oknie", "brak decyzji (pierwsza w d56)", "INFO", None)
    else:
        seg = [s for s in vd.values() if "bezpiecznik braku w miastach (P3/Z2): " in s]
        if not seg:
            rep.add("P3/Z2: bezpiecznik braku w miastach w linii decyzji", "brak wstawki", "jest od wgrania P3/ZELAZO", None)
        else:
            held = isum(r"ciecia wstrzymane (\d+),", seg)
            backn = isum(r"powroty do bazy (\d+),", seg)
            badv = []
            for d in sorted(vd):
                s = vd[d]
                g = re.search(r"\biron: x([\d.]+)(?: -> x([\d.]+))?, zuzycie/produkcja", s)
                if not g:
                    continue
                m1 = float(g.group(2) or g.group(1))
                e = num(r"miast bez towaru \[[^\]]*\biron (\d+)", s)
                if e is None and d in mo:
                    e = num(r"miast bez rudy (\d+) z", mo[d])
                rising = g.group(2) is not None and float(g.group(2)) > float(g.group(1))
                if e is not None and e > 15 and m1 < 0.999 and not rising:
                    badv.append((run_day(d, start), m1, e))
            act = sum(1 for s in seg if "(P3/Z2): CZYNNY" in s)
            rep.add("P3/Z2-1: zelazo nie ciete ponizej bazy przy braku w miastach",
                    f"decyzji {len(vd)}, bezpiecznik CZYNNY w {act}; zle decyzje (doba, mnoznik, miast bez zelaza): {badv[:5] if badv else 'brak'}",
                    "w kazdej decyzji mnoznik iron >= 1.00 przy miastach bez zelaza > 15 (powrot krokiem w gore dozwolony)", not badv and act == len(seg))
            rep.add("P3/Z2-2: ciecia wstrzymane i powroty do bazy (suma decyzji; INFO)", f"wstrzymane {held}, powroty {backn}",
                    "INFO (bieg roczny przed paczka: ciecie zelaza d196 x0.73 i d308 x0.61 przy 34-50 miastach bez zelaza)", None)
    il = {d: s for d, s in by_day(lines, "Zelazo (lupy) (214): dzien").items() if inwin(d)}
    if il:
        d0, d1 = sorted(il)[0], sorted(il)[-1]
        tot = num(r"zapas: miasta .*?, razem (\d+)", il[d1])
        c0, c1 = num(r", zamki (\d+), wsie", il[d0]), num(r", zamki (\d+), wsie", il[d1])
        car = num(r"karawany (\d+), lordowie", il[d1])
        top4 = 0
        if nm:
            g = re.search(r"najwiekszy zapas rudy: ([^;]*)", nm[sorted(nm)[-1]])
            if g:
                top4 = sum(int(x) for x in re.findall(r" (\d+)(?:,|$)", g.group(1).strip())[:4])
        if tot and c1 is not None and car is not None:
            rep.add("P3/Z2-3: zapas zelaza poza zasiegiem zuzycia na koniec okna (INFO)",
                    f"zamki {c1}, juki karawan {car}, cztery najwieksze miasta {top4} = {100.0 * (c1 + car + top4) / tot:.0f}% z {tot} lup",
                    "INFO (bieg roczny przed paczka: 79% z 14 517)", None)
        if c0 is not None and c1 is not None and d1 > d0:
            g = (c1 - c0) / float(d1 - d0)
            rep.add("P3/Z3-1: przyrost zelaza w zamkach", f"{c0} -> {c1} lup w {d1 - d0} dob = {g:+.1f}/d (bieg roczny przed paczka +9.2/d, II polrocze +13.8/d)",
                    "<= +2 lupy/d (zmiana A zamyka wjazdy, zmiana B dobytek, wozy Z1 wywoza nadwyzke)", g <= 2.0)

    # Z3-A: wjazdy nieskierowane do zamkow
    cm = {d: s for d, s in by_day(lines, "Targ przy zamku (5.11): dzien").items() if inwin(d) and "wjazdy nieskierowane (P3/Z3): " in s}
    if not cm:
        rep.add("P3/Z3-A: wstawka wjazdy nieskierowane (P3/Z3) w linii Targ przy zamku (5.11)", "brak w logu", "jest od wgrania P3/ZELAZO", None)
    else:
        rows = list(cm.values())
        n = len(rows)
        on = sum(1 for s in rows if "(P3/Z3): CZYNNE" in s)
        load = isum(r"\(P3/Z3\): .*? - z ladunkiem (\d+) ", rows)
        fl = isum(r"cel domyslny inny niz ten zamek (\d+);", rows)
        li = isum(r"ladunek: zelazo (\d+),", rows)
        onw = isum(r", dalej do miasta (\d+) \(zatrzymane", rows)
        ki = isum(r"zatrzymane w wozie: zelazo (\d+),", rows)
        nt = isum(r"bez miasta dalej (\d+);", rows)
        di = isum(r"caly woz sprzedany zamkowi \(gra\): zelazo (\d+),", rows)
        ge = isum(r"straz wygasla z ladunkiem (\d+);", rows)
        bo = isum(r", lodzie (\d+),", rows)
        rep.add("P3/Z3-A1: woz nieskierowany nie zostawia zelaza w zamku",
                f"CZYNNE w {on} z {n} dob; wjazdy z ladunkiem {load} ({load / max(1, n):.1f}/d, schronienie {fl}), zelazo wwiezione {li} lup, sprzedane zamkom w calosci {di}, "
                f"zatrzymane w wozie {ki}; dalej do miasta {onw}, bez miasta dalej {nt}",
                "zelazo sprzedane zamkom w calosci <= 10% wwiezionego (bieg roczny przed paczka: 100%, 6-7 lup/d)", (di <= 0.10 * li) if li > 0 else None)
        rep.add("P3/Z3-A2: straz wygasla z ladunkiem, lodzie (INFO)", f"straz wygasla z ladunkiem {ge} (kurs przepada, towar wraca do wsi), lodzie rybackie {bo}",
                "INFO (pojedyncze; duzo = wozy stoja w zamkach ponad dobe)", None)
    # Z3-B i Z4: linia K1
    k1 = {d: s for d, s in by_day(lines, "Konie - smierc, lup, dobytek (E6/K1): dzien").items() if inwin(d)}
    zb = [s for s in k1.values() if "polki wedlug osady (P3/Z3-B" in s]
    if not zb:
        rep.add("P3/Z3-B: wstawka polki wedlug osady (P3/Z3-B) w linii K1", "brak w logu", "jest od wgrania P3/ZELAZO", None)
    else:
        ic, it_ = 0, 0
        for s in zb:
            g = re.search(r"zelazo zamki/miasta (\d+)/(\d+)", s)
            if g:
                ic += int(g.group(1)); it_ += int(g.group(2))
        mv = isum(r"towar nie-zywnosciowy z zamku do miasta (\d+),", zb)
        nt = isum(r"z zamku do miasta \d+, bez miasta (\d+);", zb)
        rep.add("P3/Z3-B1: dobytek rozbitych - zelazo na polki miast, nie zamkow",
                f"zelazo z dobytku: zamki {ic}, miasta {it_} ({(ic + it_) / max(1, len(zb)):.1f}/d); towar nie-zywnosciowy przekierowany z zamku do miasta {mv}, bez miasta {nt}",
                "zelazo do zamkow <= 10% zelaza z dobytku (rachunek przed paczka: 3.5-5.7 lup/d do zamkow)", (ic <= 0.10 * (ic + it_)) if ic + it_ > 0 else None)
    z4 = [s.split("porzucone przez lordow (gra, P3/Z4): ", 1)[1].split(" | ", 1)[0] for s in k1.values() if "porzucone przez lordow (gra, P3/Z4): " in s]
    if not z4:
        rep.add("P3/Z4: wstawka porzucone przez lordow (gra, P3/Z4) w linii K1", "brak w logu", "jest od wgrania P3/ZELAZO", None)
    else:
        hooked = all(s.startswith("latka wpieta") for s in z4)
        keyon = sum(1 for s in z4 if "na polke miasta TAK" in s)
        g_, f_, l_, h_, a_ = (isum(p, z4) for p in (r", towar (\d+) \(w tym zelazo", r", zywnosc (\d+),", r", zywy inwentarz (\d+),", r", konie (\d+) \(ksiega koni", r"uzbrojenie i inne (\d+) "))
        fe = isum(r"\(w tym zelazo (\d+)\)", z4)
        sh = isum(r"; na polki miast (\d+) \(zelazo", z4)
        she = isum(r"; na polki miast \d+ \(zelazo (\d+)\)", z4)
        ns = isum(r"\), bez polki (\d+),", z4)
        n = max(1, len(z4))
        rep.add("P3/Z4-1: towar kasowany lordom przez gre - pomiar i polka miasta",
                f"latka {'wpieta' if hooked else 'NIE wpieta'}, klucz TAK w {keyon} z {len(z4)} dob; towar {g_} ({g_ / n:.1f}/d, zelazo {fe}), zywnosc {f_} ({f_ / n:.1f}/d), "
                f"zywy inwentarz {l_}, konie {h_} ({h_ / n:.1f}/d - bez zmian, do decyzji), uzbrojenie i inne {a_} (bez zmian); na polki miast {sh} (zelazo {she}), bez polki {ns}",
                "latka wpieta i bez polki 0 (kazda skasowana sztuka towaru ma odbiorce)", hooked and ns == 0)
    # zelazo "bez wyjasnienia" w ksiedze towarow (suma okna; prog roczny -150 przeliczony na dlugosc okna)
    un, nd = 0, 0
    for s in lines:
        if s.startswith("Towary: dzien ") and " - iron (" in s:
            d = num(r"dzien (\d+)", s)
            if d is None or not inwin(d):
                continue
            v = num(r"\| bez wyjasnienia ([+-]?\d+)", s)
            if v is not None:
                un += v; nd += 1
    if nd:
        lim = -max(50.0, 150.0 * nd / 364.0)
        rep.add("P3/Z4-2: zelazo bez wyjasnienia w ksiedze towarow (suma okna)", f"{un:+d} lup w {nd} dobach (bieg roczny przed paczka -1474 w 363 dobach; biegi 119 dob -46..-357)",
                f">= {lim:.0f} (roczny prog -150 przeliczony na okno, najmniej -50); wozy kupcow nie moga dawac nowej pozycji", un >= lim)


# ============================================================ N3 (poprawka 3 po biegu rocznym 13.10): pobity oblegajacy uchodzi - blok etap8_n3
# Linia doby "Przegrani pod murami (N3): dzien" (LosersFlee.WallsLine, klucz LosersFleeBesiegers); liczby tej linii sa tez wliczone w "Przegrani (H3)".
N3_SEG = r"\| %s: bitew (\d+), przegrani (\d+) ludzi: zabici (\d+) \([^;]*; gra dalaby (\d+)\), jency (\d+) \([^;]*; gra ok\. (\d+)\), rozbici (\d+) \("
N3_CLS = (("wypad", "wypad - pobity oblegajacy"), ("mury", "pod murami - pobity oblegajacy"), ("odsiecz", "pod murami - pobita odsiecz albo inna strona w polu"))


def etap8_n3(rep, lines, start, win, until=120, logp=None, csp=None, **kw):
    """N3 (decyzja Jeffa 13.10 "pobity oblegajacy ma uchodzic jak przegrany w polu"; LosersFlee.cs - WallsClass, klucz LosersFleeBesiegers). Bieg roczny
    przed paczka: 38 wypadow - oblegajacy stracili 55 018 ludzi (100%: 19 328 zabitych, 35 687 do niewoli); pod murami 6 bitew z pobitym oblegajacym
    (8 824 ludzi, 100%) i 10 z pobita odsiecza (6 052 ludzi, 100%). Linia doby "Przegrani pod murami (N3): dzien D" ma numer dnia gry (bitwy doby D-1,
    jak "Przegrani (H3)"). Brak linii = INFO (log sprzed paczki), WYLACZONE = INFO, nigdy wyjatek."""
    rows = {d: s for d, s in by_day(lines, "Przegrani pod murami (N3): dzien").items() if 1 <= run_day(d - 1, start) <= until}
    if not rows:
        rep.add("N3: linia Przegrani pod murami (N3)", "brak w logu", "jest od wgrania N3 (log sprzed paczki - INFO)", None)
        return
    on = [rows[d] for d in sorted(rows) if " - WYLACZONE" not in rows[d]]
    if not on:
        rep.add("N3: pobity oblegajacy uchodzi", f"WYLACZONE w {len(rows)} dobach", "INFO (klucz LosersFleeBesiegers wylaczony - jak przed paczka)", None)
        return

    def isum(pat, grp=1):
        return sum(int(m.group(grp)) for m in (re.search(pat, s) for s in on) if m)

    def pc(x, of):
        return f"{100.0 * x / of:.1f}%" if of > 0 else "-"

    tot = {}
    for key, name in N3_CLS:
        pat = re.compile(N3_SEG % re.escape(name))
        a = [0] * 7      # bitew, przegrani, zabici, gra dalaby zabitych, jency, gra ok. jencow, rozbici
        for s in on:
            m = pat.search(s)
            if m:
                for i in range(7):
                    a[i] += int(m.group(i + 1))
        tot[key] = a
    sa, wa, ra = tot["wypad"], tot["mury"], tot["odsiecz"]
    b = [sa[i] + wa[i] for i in range(7)]
    off = len(rows) - len(on)
    rep.add("N3-1: pobity oblegajacy - zabici i jency (wypad + pod murami, suma okna)",
            f"bitew {b[0]} (wypad {sa[0]}, pod murami {wa[0]}), przegrani {b[1]}: zabici {b[2]} ({pc(b[2], b[1])}), jency {b[4]} ({pc(b[4], b[1])}), razem {pc(b[2] + b[4], b[1])}, "
            f"rozbici {b[6]} ({pc(b[6], b[1])}); gra dalaby {b[3]} zabitych i ok. {b[5]} jencow; dob z linia {len(on)}" + (f", WYLACZONE {off}" if off else ""),
            "zabici + jency <= 45% przegranych (bieg roczny przed paczka 100%: 55 018 ludzi w 38 wypadach i 8 824 w 6 bitwach pod murami)",
            ((b[2] + b[4]) <= 0.45 * b[1]) if b[1] > 0 else None)
    ctl = isum(r"sprawdzenia: kontrola kodu k \+ j \+ f - n = (-?\d+),")
    odd = isum(r", listy gry inne niz plan (\d+) ludzi,")
    lost = isum(r", jency zgubieni przez gre (-?\d+),")
    unc = isum(r", bitew bez sprawdzenia jencow (\d+)")
    gap = sum(a[1] - a[2] - a[4] - a[6] for a in (sa, wa, ra))
    rep.add("N3-2: ksiega bitew pod murami (zabici + jency + rozbici = przegrani; listy gry = plan)",
            f"kontrola kodu {ctl}, listy gry inne niz plan {odd} ludzi, przegrani - (zabici + jency + rozbici) = {gap}; jency zgubieni przez gre {lost}, bitew bez sprawdzenia jencow {unc} (INFO)",
            "kontrola kodu 0, listy 0, roznica 0", ctl == 0 and odd == 0 and gap == 0)
    st_ = [isum(r"potkniecia H3 tej doby \(wszystkie bitwy\): liczenie (\d+), zastosowanie (\d+), pomiar (\d+)", g) for g in (1, 2, 3)]
    rep.add("N3-3: potkniecia H3 (wszystkie bitwy, suma okna)", f"liczenie {st_[0]}, zastosowanie {st_[1]}, pomiar {st_[2]}", "0 / 0 / 0", sum(st_) == 0)
    wm = isum(r"\| zwyciezcy tych bitew (\d+) ludzi: zabici (\d+) \(", 1)
    wd = isum(r"\| zwyciezcy tych bitew (\d+) ludzi: zabici (\d+) \(", 2)
    wr = isum(r"\), z poleglych ranni \+(\d+) \| poza regula")
    fs = isum(r"przegrany wypad (\d+) \(twierdza pada\), pod murami (\d+)", 1)
    fw = isum(r"przegrany wypad (\d+) \(twierdza pada\), pod murami (\d+)", 2)
    rep.add("N3-4: pobita odsiecz, zwyciezcy, strona twierdzy (suma okna; INFO)",
            f"pobita odsiecz albo inna strona w polu: bitew {ra[0]}, przegrani {ra[1]}: zabici {ra[2]} ({pc(ra[2], ra[1])}), jency {ra[4]} ({pc(ra[4], ra[1])}), rozbici {ra[6]} ({pc(ra[6], ra[1])}); "
            f"zwyciezcy bitew pod murami {wm} ludzi: zabici {wd} ({pc(wd, wm)}), z poleglych ranni +{wr}; poza regula - pobita strona twierdzy: przegrany wypad {fs}, pod murami {fw}",
            "INFO (bieg roczny przed paczka: odsiecz 10 bitew / 6 052 ludzi - 100% strat; zwyciezcy wypadow 11.5% zabitych; strona twierdzy: wypad 0, pod murami 5 bitew / 3 604 ludzi)", None)


def etap8_main(logp, start_arg, until=120, csp=None):
    """E8/0 (242): grupa --grupa etap8 (projekt etapu 8 v2 rozdz. 3 i 4). Okno: doby kampanii 1-until (--do-doby), start kampanii jak etap7_main.
    Kolejne paczki dopisuja WLASNE bloki etap8_<paczka>(rep, lines, start, win, until=, logp=, csp=) do listy `blocks` (wedlug numeru paczki);
    kazdy blok rusza tylko przy swojej linii - brak linii = wiersz INFO, nigdy wyjatek."""
    lines = read(logp)
    rep = Report()
    start = start_arg
    if start is None:
        for s in lines:
            if s.startswith("Pomiary 169c: okna"):
                start = num(r"start kampanii dzien (\d+)", s)
                if start is not None:
                    break
    alld = sorted(by_day(lines, "Pieniadz swiata: dzien"))
    if start is None:
        start = alld[0] if alld else 0
    win = [d for d in alld if 1 <= run_day(d, start) <= until]
    print(f"plik: {logp} | doby z linia Pieniadz swiata: {len(alld)} (doby kampanii {run_day(alld[0], start) if alld else '-'}-{run_day(alld[-1], start) if alld else '-'})"
          f" | start kampanii {start} | okno progow: doby kampanii 1-{until} ({len(win)} dob)")
    blocks = [etap8_t0, etap8_0]   # kolejne paczki etapu 8 dopisuja tu swoje bloki
    blocks.append(etap8_p1)   # E8/P1 (243): ksiega umiejetnosci
    blocks.append(etap8_p2)   # E8/P2 (244): pomiary sprzetu AI, lupu i korony
    blocks.append(etap8_x)    # E8/X (248): doswiadczenie za skutek
    blocks.append(etap8_w)    # E8/W (249): zuzycie i naprawy AI
    blocks.append(etap8_a)    # E8/A (250): misja gracza - odzysk wedlug strony, arena nie obija, lup z wlasnych zabojstw
    blocks.append(etap8_z)    # E8/Z (251): zakupy i nadwyzki AI - bez dodatnich stanow, sufit ceny (W CIENIU), uprzaz ponad zapas
    blocks.append(etap8_l)    # E8/L (252): lup to przeniesienie, Send troops - jedna droga, dar dla miasta do zalogi bez milicji, trofea zostawione na polke
    blocks.append(etap8_c)    # E8/C (253): cennik - rzad konski z wagi prawdziwej, helmy t4-6, luki, bron miotana, konie wedlug kategorii
    blocks.append(etap8_p3)   # E8/P3 (245): pomiary swiata (scalenie etapu 8: osobna linia - na galezi e8-c blok stal w liscie startowej)
    blocks.append(etap8_s)   # E8/S (246): porzadek stanu (osobna linia - czyste scalenie z lista drugiej galezi)
    blocks.append(etap8_q)   # E8/Q (262): straz przeprawy na zegarze gry
    blocks.append(etap8_g1)   # E8/G1 (260): karawany BK w miescie co godzine, wyspy bez drogi
    blocks.append(etap8_g2)   # E8/G2 (261): klany najemnikow bez bohaterow w zamianie BK, uczta BK bez towaru z niczego
    blocks.append(etap8_t)   # E8/T (263): start kampanii (budzet cechow, dorobek partii lordow z dob 1-3) i rekrut gracza jak u AI
    blocks.append(etap8_k)   # E8/K (255): ksiazki BK, zlecenia kowalskie gry (nagroda, platnik, bron, szablon), kupno u ksiegarza BK
    blocks.append(etap8_h)   # E8/H (271): jezdziec = kon + uprzaz - brama awansu, bitwa gracza, zakup siodel, pula weteranow
    blocks.append(etap8_d1)   # E8/D1 (256): nagrody zadan od zleceniodawcy w dniach zoldu, wyplaty gracza z odbiorca, towar zadan
    blocks.append(etap8_d2)   # E8/D2 (257): nagroda turnieju gracza, zaklady, oplaty i drobne zrodla gracza - odbiorca i platnik, kontrolka RealPayer
    blocks.append(etap8_r)    # E8/R (254): rynek i korona - bez premii wojennej, kon przy sprzedazy liczony raz, monopole od dziennej wyplaty
    blocks.append(etap8_b)    # E8/B (258): warsztaty i kowadlo - wyroby uboczne z kazdego cyklu, welna z uboju przez pamiec ulamkow, drobne poprawki kowadla
    blocks.append(etap8_o1)   # E8/O1 (265): pamiec polki po wlasnym zdjeciu sztuki (poprawka zamiast przebudowy), delegaty DTE/BK zamiast Invoke
    blocks.append(etap8_o2)   # E8/O2 (266): WorkshopLaw bez refleksji i powtorzen - klucze, pamieci nazw linii i zakazanych, mnoznik polki raz na koszyk
    blocks.append(etap8_o3)   # E8/O3 (267): wywoz kupcow - cele w zasiegu z pamieci z kluczem, popyt i mnoznik ceny raz na osade w koszyku
    blocks.append(etap8_o5)   # E8/O5 (269): nadwyzki zalog po godzinach - maks. taktu doby, sztuki i utarg zalog tygodniowo wobec Z33, ksiega kas
    blocks.append(etap8_o6)   # E8/O6 (270): zapis logu otwartym plikiem - czas zapisu, proba 3 dob (bajty i linie), wpis kontrolny drogi bledu
    blocks.append(etap8_p3woj)   # P3/WOJSKO (TRIAZ-3): sluzba na miare srodkow, zwolnienia wedlug tieru, zadatek BK i kontrakt najemnikow, zerwane wezwania 168
    blocks.append(etap8_p3_zelazo)   # P3/ZELAZO (TRIAZ-3 bieg roczny): kontrakt wozem, bezpiecznik regulatora, zamki, towar kasowany lordom
    blocks.append(etap8_n3)   # N3 (poprawka 3 po biegu rocznym): pobity oblegajacy i pobita odsiecz uchodza - zabici + jency <= 45%, ksiega bitew pod murami
    for blk in blocks:
        try:
            blk(rep, lines, start, win, until=until, logp=logp, csp=csp)
        except Exception as e:   # narzedzie nigdy nie przerywa raportu
            rep.add(f"blok {blk.__name__}", f"wyjatek narzedzia: {e}", "bez wyjatku", False)
    rep.show()
    return 0


def main(argv):
    args = argv[1:]
    group, logp, base_in, base_out, csvp, start_arg = None, None, None, None, None, None
    csp = None      # poprawki po tescie koncowym etapu 4 (P11-progi-T1): log sesji CrashScribe do T1 / E50-T1
    bdp = None      # recenzja fixC (4): log Armoury biegu bazowego do wiersza "doba wobec biegu bazowego" (T8)
    until_arg = 120
    final = False
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--koniec-etapu":
            final = True; i += 1; continue
        if a == "--grupa":
            group = args[i + 1]; i += 2; continue
        if a == "--baza":
            base_in = args[i + 1]; i += 2; continue
        if a == "--zapisz-baze":
            base_out = args[i + 1]; i += 2; continue
        if a == "--csv":
            csvp = args[i + 1]; i += 2; continue
        if a == "--start-kampanii":
            start_arg = int(args[i + 1]); i += 2; continue
        if a == "--do-doby":
            until_arg = int(args[i + 1]); i += 2; continue
        if a == "--crashscribe":
            csp = args[i + 1]; i += 2; continue
        if a == "--baza-doby":
            bdp = args[i + 1]; i += 2; continue
        logp = a; i += 1
    if group == "etap3" and logp:
        return etap3_main(logp, start_arg)   # 3.1 (31, E3/0)
    if group == "etap4" and logp:
        return etap4_main(logp, start_arg, until_arg, csp, bdp)   # E4/0 (188)
    if group == "etap5" and logp:
        return etap5_main(logp, start_arg, until_arg, csvp, csp)   # E5/0 (195): szkielet etapu 5 + blok E5/0; kolejne paczki dopisuja bloki
    if group == "etap7" and logp:
        return etap7_main(logp, start_arg, until_arg, csp)   # E7/0 (224) + E7/B (231): szkielet etapu 7 + bloki obu galezi; kolejne paczki dopisuja bloki
    if group == "etap8" and logp:
        return etap8_main(logp, start_arg, until_arg, csp)   # E8/0 (242): szkielet etapu 8 + bloki T0 i E8/0; kolejne paczki dopisuja bloki
    if group != "etap2" or not logp:
        print(__doc__)
        return 2
    lines = read(logp)
    rep = Report()
    budget = by_day(lines, "Budzet rodow (na sucho): dzien")
    alld = sorted(set(budget) | set(by_day(lines, "Pieniadz swiata: dzien")))
    first = alld[0] if alld else 0
    last = alld[-1] if alld else 0
    # doba kampanii: --start-kampanii, potem linia "Pomiary 169c: ... start kampanii dzien N", na koncu pierwsza doba logu
    start, how = start_arg, "--start-kampanii"
    if start is None:
        for s in lines:
            if s.startswith("Pomiary 169c: okna"):
                v = num(r"start kampanii dzien (\d+)", s)
                if v is not None:
                    start, how = v, "linia Pomiary 169c"
                    break
    if start is None or (alld and (start > first + 1 or first - start > 5000)):
        start, how = first, "pierwsza doba logu (brak linii startu - w logu kontynuacji podaj --start-kampanii)"
    if csvp is None:
        csvp = csv_path_of(logp)
    rows = read_csv(csvp)
    balp = os.path.join(os.path.dirname(csvp), "balans-krolestw.csv")
    print(f"plik: {logp} | doby gry {first}-{last} ({len(alld)} dob) | start kampanii {start} ({how}): doby kampanii {run_day(first, start)}-{run_day(last, start)}"
          f" | CSV: {csvp if rows else 'brak (' + csvp + ')'}" + (" | TEST KONCA ETAPU (--koniec-etapu)" if final else ""))
    # plik bazowy i liczby tego biegu (B-3: na poczatku - wiersze warunkow etapu porownuja sie z baza)
    base = None
    if base_in:
        with open(base_in, encoding="utf-8") as f:
            base = json.load(f)
        for k in ("dni", "krolestwa_dni", "twierdze_dni"):
            if k in base:
                base[k] = intkeys(base[k])
    now = baseline_of(lines, rows, start, balp)
    sw, bw = now["swiat"], (base or {}).get("swiat", {})
    b_on = bool(by_day(lines, "Zawor zamkow (110): dzien"))   # krok B w biegu (linia 110)
    etap_rule = "" if final else "; ETAP, gdy nie gorzej niz baza"

    # 1. glowy < 5 000 (doba kampanii 120, 364, 728; i ostatnia). B-3: bez --koniec-etapu ETAP, gdy nie wiecej niz baza +20% (min. +2) w dobie 120.
    # B-4 (przeglad B-3): +20% za luzne dla kroku, ktory tylko doklada panom - ETAP tylko do bazy + 2 glowy (rozrzut kampanii jeszcze niezmierzony;
    # druga para biegow przed C1)
    heads = {run_day(d, start): num(r"glowy < 5000: (\d+)", s) for d, s in budget.items()}
    for n in (120, 364, 728):
        if n in heads:
            v = heads[n]
            ok = v is not None and v <= 10
            gb, et, note = bw.get("glowy_120") if n == 120 else None, False, ""
            if not ok and not final and v is not None and gb is not None:
                lim = gb + 2
                et, note = v <= lim, f" (baza {gb}; nie gorzej niz baza: <= {lim:.0f})"
            rep.add(f"glowy < 5000 (doba {n})", f"{v}{note}", "<= 10 (warunek etapu 2 - C/D)" + ("" if final else "; ETAP, gdy nie wiecej niz baza + 2"), ok, et)
    if heads:
        lastn = max(heads)
        rep.add("glowy < 5000 (ostatnia doba)", f"{heads[lastn]} (doba {lastn})", "<= 10 w dobach 120/364/728", None)
    else:
        rep.add("glowy < 5000", "brak linii", "<= 10", None)

    # 2. bankructwo do wgrania 168 (projekt rozdz. 1): K39 lub bankrut Banku. Linia "D staly" po przegladzie 169c ma liczbe rodow AI (bez podwojnego
    # liczenia); starsza - K39 z "D staly" + "bankrutow N" z linii IronBank tej samej doby (IronBank liczy tez gracza; rod moze byc w obu - gorna granica)
    sd = by_day(lines, "D staly (169c)")
    ib = by_day(lines, "IronBank: dzien")
    bank_rows = []
    for d in sorted(set(sd) | set(ib)):
        s = sd.get(d, "")
        m = re.search(r"bankruci do 168 \(K39 lub bankrut Banku, rody AI\): (\d+) \(K39 - [^:]*: (\d+), w tym z doba bez znanego salda (\d+); bankruci Banku: (\d+)", s)
        if m:
            bank_rows.append((d, int(m.group(1)), int(m.group(2)), int(m.group(3)), int(m.group(4)), "linia D staly"))
            continue
        k39 = num(r"z rzedu\): (\d+)", s) if s else None
        b = num(r"bankrutow (\d+)", ib.get(d, "")) if d in ib else None
        if k39 is None and b is None:
            continue
        bank_rows.append((d, (k39 or 0) + (b or 0), k39 or 0, 0, b or 0, "K39 + IronBank (suma)"))
    if bank_rows:
        worst = max(bank_rows, key=lambda x: x[1])
        bb = bw.get("bankruci_max")
        et = (not final) and bb is not None and worst[1] <= bb
        rep.add("bankruci do 168 (K39 lub bankrut Banku)", f"{worst[1]} (doba {run_day(worst[0], start)}: K39 {worst[2]}, w tym bez znanego salda {worst[3]}; Bank {worst[4]}; {worst[5]})"
                + (f" (baza najwiecej {bb})" if bb is not None else ""),
                "0 w kazdej dobie (warunek etapu 2 - 168)" + ("" if final else "; ETAP, gdy najwiecej nie wiecej niz w bazie"), worst[1] == 0, et)
    else:
        rep.add("bankruci do 168 (K39 lub bankrut Banku)", "brak linii", "0 w kazdej dobie", None)

    # 3. zajecie dochodu - dopiero 168
    rep.add("zajecie dochodu (D3)", "brak (168 niewgrane)", "<= 1 w 120 dobach, <= 5 w roku", None)

    # 4. skarbiec w wojnie < 0.25 mln dluzej niz 28 dob
    # B-3: krolestwa, ktore powstaly w trakcie biegu (bunty - "X (Y Rebels)", a takze kazde krolestwo bez linii w pierwszej dobie "Skarbce"),
    # rodza sie z pustym skarbcem - osobny wiersz (INFO; wiazacy z --koniec-etapu). Bieg 120 dob kroku B: Volentin League (Braavos Rebels)
    # od doby 62 i Moharis League (Pentos Rebels) od doby 79 - skarbiec 1 zl od narodzin; w bazie buntow nie bylo
    ks = kingdom_war_series(lines)
    d0 = min((d for ser in ks.values() for d, _, _, _ in ser), default=None)
    worst, worstk, nworst, nworstk = 0, "-", 0, "-"
    for k, ser in ks.items():
        run = best = 0
        for d, war, wallet, men in sorted(ser):
            run = run + 1 if (war and wallet < 250000) else 0
            best = max(best, run)
        born = REB.match(k) is not None or (d0 is not None and min(d for d, _, _, _ in ser) > d0)
        if born:
            if best > nworst:
                nworst, nworstk = best, k
        elif best > worst:
            worst, worstk = best, k
    rep.add("skarbiec w wojnie < 0.25 mln (najdluzsza seria, krolestwa z poczatku biegu)", f"{worst} dob ({worstk})" if ks else "brak linii", "0 serii > 28 dob",
            (worst <= 28) if ks else None)
    if ks:
        rep.add("skarbiec w wojnie < 0.25 mln (krolestwa powstale w biegu - bunty)", f"{nworst} dob ({nworstk})",
                "0 serii > 28 dob" + (" (koniec etapu)" if final else " - INFO: bunt rodzi sie z pustym skarbcem (wiazace z --koniec-etapu)"),
                (nworst <= 28) if final else None)

    # 5. niedoplata korony (169c) - swiat i krolestwa w wojnie; rok 1 / rok 2 wedlug doby kampanii
    ar = by_day(lines, "Korona: niedoplata 28 dob (169c)")
    if ar:
        dl = max(ar)
        s = ar[dl]
        paid = num(r"wyplacone ([\d.]+)%", s, float)
        year = run_day(dl, start)
        rule = ">= 65% (rok 1)" if year <= 364 else ">= 50% (rok 2)"
        lim = 65.0 if year <= 364 else 50.0
        rep.add("korona: wyplacone z naleznego (28 dob, swiat)", f"{paid}% (doba {year})" if paid is not None else "-", rule, (paid >= lim) if paid is not None else None)
        bad = []
        for d in sorted(ar):
            part = ar[d].split("na krolestwo: ", 1)[-1]
            for m in re.finditer(r"([^,]+?) (\d+)%( \(pokoj\))?(?:,|\.$)", part):
                k, n, peace = m.group(1).strip(), int(m.group(2)), bool(m.group(3))
                if not peace and n > 50 and not any(p in k.lower() for p in LORE_POOR):
                    bad.append(f"{k} {n}% (doba {run_day(d, start)})")
        rep.add("korona: krolestwo w wojnie z niedoplata > 50% (28 dob)", ", ".join(bad[-5:]) if bad else "0", "zadne (poza biednymi z lore)", not bad)
    else:
        rep.add("korona: niedoplata 28 dob", "brak linii", ">= 65% / >= 50%", None)

    # 6. zalegly zold w zlocie - linia "Zold:"
    zold = by_day(lines, "Zold: dzien")
    shares = []
    for d in last_window(zold):
        s = zold[d]
        a = num(r"partie rodow: naliczony (\d+)", s) or 0
        g = num(r"garnizony: naliczony (\d+)", s) or 0
        cut = num(r"glowy: (\d+) w \d+ rodach", s) or 0
        if a + g > 0:
            shares.append(100.0 * cut / (a + g))
    rep.add("zalegly zold w zlocie (28 dob)", f"{st.mean(shares):.2f}%" if shares else "brak linii", "<= 2%", (st.mean(shares) <= 2.0) if shares else None)

    # 7. zalegly zold w partiach - linia "Budzet rodow"
    parts = []
    for d in last_window(budget):
        m = re.search(r"zalegly zold: (\d+) partii i zalog z (\d+)", budget[d])
        if m and int(m.group(2)) > 0:
            parts.append(100.0 * int(m.group(1)) / int(m.group(2)))
    rep.add("zalegly zold w partiach (28 dob)", f"{st.mean(parts):.2f}%" if parts else "brak linii", "<= 2%", (st.mean(parts) <= 2.0) if parts else None)

    # 8. wojsko w druzynach lordow W WOJNIE - cel 95-115 tys., twarda podloga 85 tys. B-3: srednia 28 dob (dotad ostatnia doba - jedna doba
    # wojny wiecej albo mniej przesuwala wynik o kilka tysiecy: bieg 120 dob kroku B 125.4 tys. w dobie 120 przy 118.0 tys. sredniej 28 dob).
    # B-4 (przeglad B-3): ETAP tylko, gdy bieg NIE JEST GORSZY niz baza w tych samych dobach - nie dalej od pasma 95-115 tys. niz baza, albo
    # (los kampanii: inne krolestwa w wojnie) wojsko tych samych krolestw w tych samych dobach wojny obu biegow, przeniesione na wojsko w wojnie
    # bazy (baza x bieg/baza na wspolnych dobach wojny), nie dalej od pasma niz baza - i wojsko swiata w pasmie bazy (+-10%). Dotad sam
    # warunek swiata: baza 111.5 tys. w pasmie, bieg 118.0 tys. poza - dostawal ETAP.
    tot, totall, nwar = {}, {}, {}
    for k, ser in ks.items():
        for d, war, wallet, men in ser:
            totall[d] = totall.get(d, 0) + men
            if war:
                tot[d] = tot.get(d, 0) + men
                nwar[d] = nwar.get(d, 0) + 1
    world_ok = None
    if totall:
        lw = last_window(totall)
        v = mean_days(tot, lw) or 0
        allm = mean_days(totall, lw)
        nw = mean_days(nwar, lw) or 0
        lastd = max(totall)
        # wobec bazy w TYCH SAMYCH dobach kampanii (wojsko rosnie przez kampanie - bieg 40 dob nie porownuje sie z dobami 93-120 bazy);
        # plik bazowy sprzed B-3 (bez szeregow dobowych) - ostatnie 28 dob bazy
        bwa, bwv, allm_c, bwin = bw.get("wojsko_swiat"), bw.get("wojsko_wojna_swiat"), allm, "ostatnie 28 dob bazy"
        vwc, like, nkn, nkb = None, None, None, None
        kn0, kb0 = now.get("krolestwa_dni") or {}, (base or {}).get("krolestwa_dni") or {}
        if kn0 and kb0:
            hi0 = min(max(d for x in kn0.values() for d in x), max(d for x in kb0.values() for d in x))
            cw = list(range(max(1, hi0 - 27), hi0 + 1))

            def sums(T, war_only):
                return {d: sum(x[d][1] for x in T.values() if d in x and (x[d][0] or not war_only)) for d in cw}
            allm_c, bwa, bwv = mean_days(sums(kn0, False), cw), mean_days(sums(kb0, False), cw), mean_days(sums(kb0, True), cw)
            vwc = mean_days(sums(kn0, True), cw)
            bwin = f"doby {cw[0]}-{cw[-1]} obu biegow"
            # B-4: te same krolestwa w tych samych dobach wojny obu biegow (bunty z macierzystym) - bieg / baza; liczba krolestw w wojnie (srednio)
            cr = cb = 0
            for d in cw:
                for k in set(kn0) & set(kb0):
                    a, c = kn0[k].get(d), kb0[k].get(d)
                    if a and c and a[0] and c[0]:
                        cr += a[1]; cb += c[1]
            like = cr / cb if cb > 0 else None
            nkn = mean_days({d: sum(1 for x in kn0.values() if d in x and x[d][0]) for d in cw}, cw)
            nkb = mean_days({d: sum(1 for x in kb0.values() if d in x and x[d][0]) for d in cw}, cw)
        if bwa and allm_c:
            ch = allm_c / bwa - 1
            # B-4 (przeglad B-3): +-10% - suma ok. 30 krolestw usrednia los pojedynczych (pasmo -25%..+20% jest na krolestwo)
            world_ok = -0.10 <= ch <= 0.10
            rep.add("wojsko swiata wobec bazy (wszystkie krolestwa, srednia 28 dob)", f"{allm_c:.0f} wobec bazy {bwa:.0f} ({100 * ch:+.1f}%; {bwin})",
                    "+-10% (krok paczki nie zmienia wojska swiata ponad to; rozrzut kampanii do zmierzenia druga para biegow)", world_ok)
        if v == 0:
            rep.add("wojsko w druzynach lordow (krolestwa w wojnie, srednia 28 dob)", f"0 (zadne krolestwo w wojnie; wszystkie {allm:.0f})", "95-115 tys. w wojnie", None)
        else:
            if 95000 <= v <= 115000:
                ok, note = True, ""
            elif 85000 <= v < 95000:
                ok, note = False, " - ponizej celu 95 tys. (nad podloga 85 tys.)"
            else:
                ok, note = False, (" - ponizej podlogi 85 tys." if v < 85000 else " - powyzej 115 tys.")
            # bwv - wojsko w wojnie bazy w tych samych dobach (wyzej); bez szeregow w bazie - ostatnie 28 dob bazy
            def gap(x):
                return 0.0 if 95000 <= x <= 115000 else (95000 - x if x < 95000 else x - 115000)
            et, etxt = False, ""
            if not final and world_ok is True and bwv:
                vv = vwc if vwc is not None else v
                if gap(vv) <= gap(bwv):
                    et, etxt = True, f"; nie dalej od pasma niz baza ({vv:.0f} wobec {bwv:.0f})"
                elif like is not None and gap(bwv * like) <= gap(bwv):
                    et, etxt = True, (f"; te same krolestwa w tych samych dobach wojny: {100 * (like - 1):+.1f}% wobec bazy -> {bwv * like:.0f}"
                                      f" (reszta z krolestw w wojnie tylko w biegu; krolestw w wojnie srednio {nkn:.1f} wobec {nkb:.1f}, bunty z macierzystym)")
                else:
                    etxt = f"; gorzej niz baza: {vv:.0f} wobec {bwv:.0f}" + (f", te same krolestwa i doby wojny {100 * (like - 1):+.1f}% -> {bwv * like:.0f}" if like is not None else "")
            rep.add("wojsko w druzynach lordow (krolestwa w wojnie, srednia 28 dob)",
                    f"{v:.0f} (srednio {nw:.1f} krolestw w wojnie; wszystkie {allm:.0f}; ostatnia doba {tot.get(lastd, 0)})" + (f"; baza w wojnie {bwv:.0f}" if bwv else "") + note + etxt,
                    "95-115 tys. w wojnie; twarda podloga 85 tys. (warunek etapu 2 - budzet 166)"
                    + ("" if final else "; ETAP, gdy wojsko swiata w pasmie bazy i bieg nie dalej od pasma niz baza (te same doby albo te same krolestwa w tych samych dobach wojny)"),
                    ok, et)

    # 9. zalogi, dezercja, okupy, pieniadz swiata - wobec bazy (plik bazowy i liczby biegu - na poczatku main)
    def vs(name, key, rule, test, info=False):
        v, b = sw.get(key), bw.get(key)
        if v is None:
            rep.add(name, "brak linii", rule, None)
        elif b is None or b == 0:
            rep.add(name, f"{v:.0f} (bez bazy)", rule, None)
        else:
            rep.add(name, f"{v:.0f} wobec bazy {b:.0f} ({100.0 * v / b - 100:+.0f}%)", rule, None if info else test(v, b))

    vs("zalogi swiata (28 dob)", "zalogi", "INFO - prog na twierdze i na krolestwo (wiersze nizej)", None, info=True)
    # B-3: zalogi NA TWIERDZE (balans-krolestw.csv) - spadek zalog krolestwa, ktore stracilo twierdze, to nie mniejsza zaloga (krok B: Pentos 2 twierdze
    # wobec 6, The Reach 15 wobec 17 - na twierdze -2..+5%); doby wojny z linii "Skarbce". Swiat wiazacy; na krolestwo - warunek etapu (166).
    # B-4 (przeglad B-3): los jednej kampanii odwraca znak zmiany miedzy oknami 28 dob - spadek, ktory we WSZYSTKICH oknach ma ten sam znak, to
    # znak skutku, nie losu: DECYZJA (dotad tylko opis przy ETAP - Qohor -11/-16/-7%, Tyrosh -11/-12/-13% dostaly ETAP). Nie NIE wprost: trzy
    # okna jednej pary biegow daja ten sam znak tez z losu (krolestwo, ktore wczesnie stracilo twierdze, zostaje slabsze) - rozstrzyga druga para
    # biegow (rozrzut kampanii) przed C1. ETAP tylko dla zmian, ktore zmieniaja znak miedzy oknami, i przy jednym oknie (bieg < 58 dob - nie da sie
    # odroznic; wiaze bieg 120 dob), gdy swiat w normie; swiat poza norma albo --koniec-etapu - NIE
    tn, tb = now.get("twierdze_dni") or {}, (base or {}).get("twierdze_dni") or {}
    garr_ok = None
    if tn and tb:
        hi = min(max(d for x in tn.values() for d in x), max(d for x in tb.values() for d in x))
        lw = list(range(hi - 27, hi + 1))
        ids = sorted(set(tn) & set(tb))

        def per_fort(T, keys, days):
            men = tw = 0
            for k in keys:
                for d in days:
                    x = T.get(k, {}).get(d)
                    if not x or x[0] <= 0 or x[2] == 0:   # bez twierdz albo w pokoju (wojna nieznana -1 liczona jak wojna)
                        continue
                    men += x[1]; tw += x[0]
            return men / tw if tw > 0 else None
        wn, wb = per_fort(tn, ids, lw), per_fort(tb, ids, lw)
        if wn and wb:
            garr_ok = wn >= 0.95 * wb
            rep.add("zalogi swiata na twierdze w wojnie (28 dob, balans-krolestw.csv)", f"{wn:.0f} wobec bazy {wb:.0f} ({100 * (wn / wb - 1):+.1f}%; {len(ids)} krolestw w obu biegach)",
                    ">= 95% bazy", garr_ok)
        ws = wins28(hi) or [(max(1, hi - 27), hi)]          # bieg krotszy niz 58 dob - jedno okno (ostatnie 28 dob)
        low = []
        for k in ids:
            r = []
            for a, b in ws:
                pn, pb = per_fort(tn, [k], range(a, b + 1)), per_fort(tb, [k], range(a, b + 1))
                r.append(pn / pb - 1 if pn and pb else None)
            if r and r[-1] is not None and r[-1] < -0.05:
                low.append((k, r, len(r) >= 2 and all(x is not None and x < 0 for x in r)))
        pers_n = sum(1 for _, _, pers in low if pers)
        txt = ", ".join(f"{k} {100 * r[-1]:+.0f}%" + ((" (ten sam znak we wszystkich oknach " if pers else " (okna ") + "/".join("-" if x is None else f"{100 * x:+.0f}" for x in r) + ")"
                                                      if len(r) >= 2 else "") for k, r, pers in low)
        one = "; jedno okno 28 dob (bieg < 58 dob) - skutku od losu nie da sie odroznic" if len(ws) < 2 else ""
        rep.add("zalogi na twierdze w wojnie na krolestwo (28 dob)", (txt + (f" - ten sam znak we wszystkich oknach: {pers_n}" if pers_n else "") + one) if low else f"wszystkie w normie ({len(ids)} krolestw)",
                ">= 95% bazy (warunek etapu 2 - 166)" + ("" if final else "; swiat (wiersz wyzej) w normie: spadek o tym samym znaku we wszystkich oknach 28 dob - DECYZJA"
                                                       " (skutek albo trwaly los - druga para biegow), znak zmienia sie miedzy oknami (albo jedno okno - bieg < 58 dob) - ETAP"),
                not low, (not final) and garr_ok is True and pers_n == 0, decide=(not final) and garr_ok is True and pers_n > 0)
    elif base:
        low, have = [], 0
        for k, cur in now["krolestwa"].items():
            cg, bg = cur.get("zalogi_wojna"), base["krolestwa"].get(k, {}).get("zalogi_wojna")
            if cg is None or not bg:
                continue
            have += 1
            if cg < 0.95 * bg:
                low.append(f"{k} {100.0 * cg / bg:.0f}%")
        rep.add("zalogi w wojnie na krolestwo (28 dob, CSV)", (", ".join(low) if low else f"wszystkie w normie ({have} krolestw)") if have else "brak danych (CSV albo baza bez zalog)",
                ">= 95% bazy w wojnie (baza bez twierdz - zapisac baze jeszcze raz)", (not low) if have else None)
    else:
        ng = sum(1 for k in now["krolestwa"].values() if k.get("zalogi_wojna"))
        rep.add("zalogi w wojnie na krolestwo (28 dob, CSV)", f"{ng} krolestw (bez bazy)" if rows else "brak CSV", ">= 95% bazy w wojnie", None)
    vs("dezercja AI z morale i zaleglego zoldu (28 dob)", "dezercja_ai_morale_zold", "<= baza + 50% (prog 183)", lambda v, b: v <= 1.5 * b)
    vs("dezercja AI razem z limitem zoldu gry (28 dob)", "dezercja_ai", "INFO (166 wylacza limit gry)", None, info=True)
    vs("lordowie w niewoli > 60 dni (28 dob)", "lordowie_ponad_60", "<= baza + 20%", lambda v, b: v <= 1.2 * b)
    v, b = sw.get("pieniadz_zmiana"), bw.get("pieniadz_zmiana")
    dn0, db0 = now.get("dni") or {}, (base or {}).get("dni") or {}
    if dn0 and db0:
        # B-3: te same doby kampanii obu biegow (ostatnie 28 wspolnych dob) - bieg 40 dob nie porownuje sie z dobami 93-120 bazy
        hi0 = min(max(dn0), max(db0))
        cw = list(range(max(1, hi0 - 27), hi0 + 1))
        v0, b0 = mean_days(dn0, cw, "Z"), mean_days(db0, cw, "Z")
        if v0 is not None and b0 is not None:
            v, b = v0, b0
    rep.add("pieniadz swiata - zmiana na dobe (28 dob)", f"{v:+.0f}" + (f" wobec bazy {b:+.0f} (roznica {v - b:+.0f})" if b is not None and v is not None else "") if v is not None else "brak linii",
            "C/D: +-50 tys./dobe wobec biegu bez paczki" + (" - w kroku B INFO: wiazace wiersze 'B: pieniadz swiata' nizej (okno dob 31+, bez wojny)" if b_on else ""),
            None if (v is None or b is None or b_on) else abs(v - b) <= 50000)

    # 10. krolestwa w wojnie wobec bazy (-25% / +20%; biedne z lore -35%). B-3: bunty razem z krolestwem macierzystym (Braavos + Volentin League),
    # okna 28 dob od doby 37; bez --koniec-etapu ETAP, gdy wojsko swiata w pasmie bazy - z jedna para biegow znak zmiany krolestwa odwraca sie
    # miedzy oknami (krok B: Lys +29/-10/-34%, Tyrosh -17/-12/+44%), a wojsko idzie za dochodem rodow do budzetu 166 (projekt 2.0a pkt 6).
    # B-4 (przeglad B-3): krolestwo poza pasmem w ostatnim oknie, ktorego zmiana ma ten sam znak we WSZYSTKICH oknach - DECYZJA (znak skutku albo
    # trwalego losu - druga para biegow; jak zalogi wyzej); ETAP tylko dla zmian zmieniajacych znak (i przy jednym oknie - bieg < 58 dob)
    kn, kb = now.get("krolestwa_dni") or {}, (base or {}).get("krolestwa_dni") or {}
    if kn and kb:
        hi = min(max(d for x in kn.values() for d in x), max(d for x in kb.values() for d in x))
        ws = wins28(hi) or [(max(1, hi - 27), hi)]

        def war_mean(T, k, a, b):
            v = [T[k][d][1] for d in range(a, b + 1) if d in T.get(k, {}) and T[k][d][0]]
            return st.mean(v) if v else None
        worse, other = [], 0
        for k in sorted(set(kn) & set(kb)):
            low = -0.35 if any(p in k.lower() for p in LORE_POOR) else -0.25
            r = []
            for a, b in ws:
                cn, cb = war_mean(kn, k, a, b), war_mean(kb, k, a, b)
                r.append(cn / cb - 1 if cn and cb else None)
            if r[-1] is None:
                if war_mean(kn, k, *ws[-1]) or war_mean(kb, k, *ws[-1]):
                    other += 1                                    # w wojnie tylko w jednym biegu (krok B: Riverlands)
                continue
            if r[-1] < low or r[-1] > 0.20:
                up = r[-1] > 0.20
                pers = len(r) >= 2 and all(x is not None and ((x > 0) if up else (x < 0)) for x in r)
                worse.append((f"{k} {100 * r[-1]:+.0f}%" + ((" (ten sam znak we wszystkich oknach " if pers else " (okna ") + "/".join("-" if x is None else f"{100 * x:+.0f}" for x in r) + ")"
                                                            if len(r) >= 2 else ""), pers))
        pers_n = sum(1 for _, pers in worse if pers)
        rep.add("krolestwa w wojnie: wojsko wobec bazy (bunty z macierzystym, 28 dob)",
                (", ".join(w for w, _ in worse) + (f" - ten sam znak we wszystkich oknach: {pers_n}" if pers_n else "")
                 + ("; jedno okno 28 dob (bieg < 58 dob) - skutku od losu nie da sie odroznic" if len(ws) < 2 else "") if worse else "wszystkie w normie")
                + (f"; w wojnie tylko w jednym biegu: {other}" if other else ""),
                "-25%..+20% (lore -35%; warunek etapu 2 - 166)" + ("" if final else "; wojsko swiata w pasmie bazy: zmiana o tym samym znaku we wszystkich oknach 28 dob - DECYZJA"
                                                                  " (skutek albo trwaly los - druga para biegow), znak zmienia sie miedzy oknami (albo jedno okno - bieg < 58 dob) - ETAP"),
                not worse, (not final) and world_ok is True and pers_n == 0, decide=(not final) and world_ok is True and pers_n > 0)
    elif base:
        worse = []
        for k, cur in now["krolestwa"].items():
            bk = base["krolestwa"].get(k, {})
            cw, bwv = cur.get("wojsko_wojna"), bk.get("wojsko_wojna")
            if cw is None or not bwv:
                continue
            ch = cw / bwv - 1
            low = -0.35 if any(p in k.lower() for p in LORE_POOR) else -0.25
            if ch < low or ch > 0.20:
                worse.append(f"{k} {100 * ch:+.0f}%")
        rep.add("krolestwa w wojnie: wojsko wobec bazy", ", ".join(worse) if worse else "wszystkie w normie", "-25%..+20% (lore -35%)", not worse)

    # 11. Bank - wolny kapital >= 1 mln
    caps = [num(r"kapital Banku (-?\d+)", s) for s in ib.values()]
    caps = [c for c in caps if c is not None]
    rep.add("Bank: kapital (minimum)", min(caps) if caps else "brak linii", ">= 1 mln w kazdej dobie", (min(caps) >= 1000000) if caps else None)

    # 12. D staly pana zamku (doba kampanii 40); linie modelu nierozpoznane (prog); zamkniecie sumy - INFO (z budowy)
    sdr = {run_day(d, start): s for d, s in sd.items()}
    if 40 in sdr:
        v = num(r"panowie samych zamkow \(\d+\): D staly mediana (-?\d+)", sdr[40])
        b40 = bw.get("d_staly_zamki_d40")
        if b_on and b40 is not None and v is not None:
            # B-3: 400-1300 to sprawdzenie miary 169c bez paczek; krok B z projektu tylko DOKLADA panom zamkow (wies ok. +130, zamek do +310 zl/dobe),
            # wiec po B prog wobec bazy: nie mniej niz baza i nie wiecej niz baza + 440. B-4 (przeglad B-3): dolna granica baza (dotad baza -10% - spadek
            # o kilkanascie procent przechodzil jako TAK; rozrzut mediany do zmierzenia druga para biegow)
            rep.add("D staly pana samych zamkow (doba 40) wobec bazy", f"{v} wobec bazy {b40} ({v - b40:+d})", "baza .. baza +440 (krok B tylko doklada panom zamkow)",
                    b40 <= v <= b40 + 440)
            rep.add("D staly pana samych zamkow (doba 40)", v, "INFO po kroku B (169c bez paczek: 400-1300)", None)
        elif any(s.startswith("Wyrownanie panow zamkow (E5/B3)") for s in lines):
            # narzedzie progow zb58 (TRIAZ "D staly pana samych zamkow"): 400-1300 to sprawdzenie miary 169c bez paczek; od paczek 180 i E5/B3 D pana
            # samych zamkow to glownie korona (renty korony rodow samych zamkow - linia "Wyrownanie panow zamkow (E5/B3)"). Bez pliku bazy: pasmo wobec
            # wzorca W33 (2222) +-20%. Log bez linii E5/B3 - stara miara 400-1300.
            rep.add("D staly pana samych zamkow (doba 40)", v, "1800-2700 (wzorzec W33 2222 +-20%, po 180 i E5/B3; 400-1300 = miara 169c sprzed paczek)",
                    (1800 <= v <= 2700) if v is not None else None)
        else:
            rep.add("D staly pana samych zamkow (doba 40)", v, "400-1300", (400 <= v <= 1300) if v is not None else None)
    unr = [(d, num(r"nierozpoznane: modul \d+ zl = ([\d.]+)% wplywu", s, float)) for d, s in sd.items()]
    unr = [(d, x) for d, x in unr if x is not None]
    if unr:
        dw, xw = max(unr, key=lambda t: t[1])
        rep.add("D staly: linie modelu nierozpoznane (najwiecej w dobie)", f"{xw:.2f}% wplywu D169 (doba {run_day(dw, start)})", "<= 2% swiata", xw <= 2.0)
    else:
        rep.add("D staly: linie modelu nierozpoznane", "brak linii (przed przegladem 169c)", "<= 2% swiata", None)
    clos = [num(r"roznica (-?[\d.]+)%", s, float) for s in sd.values()]
    clos = [c for c in clos if c is not None]
    rep.add("D staly: zamkniecie sumy (najwieksza roznica)", f"{max(abs(c) for c in clos):.2f}%" if clos else "brak linii", "INFO - z budowy (inne z modelu to reszta)", None)

    # 13. linie 169c obecne; ludnosc BK bez danych (pomiar nie inicjuje danych BK); koszt pomiaru
    need = ["Niewola lordow i okupy (169c)", "Zalogi: przyrost bez werbunku (169c)", "Kasy miast (169c)", "Wydatki rycerzy (169c)", "Dezercja AI wedlug przyczyny (169c)",
            "Ludnosc BK (169c)", "Sluby AI (169c)", "Towar wedrowcow BK (169c)", "Wzrost Innych (169c)", "Miara historyczna cz. 2 (169c)", "D staly (169c)",
            "Korona: niedoplata 28 dob (169c)", "Pomiary 169c: czas dzien"]
    missing = [n for n in need if not any(s.startswith(n) for s in lines)]
    rep.add("linie 169c obecne", f"{len(need) - len(missing)} z {len(need)}" + (" - brak: " + ", ".join(missing) if missing else ""), "wszystkie", not missing)
    pop = [num(r"bez danych BK (\d+)", s) for s in lines if s.startswith("Ludnosc BK (169c)")]
    pop = [x for x in pop if x is not None]
    rep.add("Ludnosc BK: osady bez danych BK (najwiecej)", max(pop) if pop else "brak linii", "0", (max(pop) == 0) if pop else None)
    vno = [num(r"wsie bez danych BK \(podatek pominiety\): (\d+)", s) for s in sd.values()]
    vno = [x for x in vno if x is not None]
    rep.add("D staly: wsie bez danych BK (najwiecej)", max(vno) if vno else "brak linii", "INFO (oczekiwane 0)", None)
    cost = [num(r"\| razem (\d+) ms na dobe", s) for s in lines if s.startswith("Pomiary 169c: czas dzien")]
    cost = [x for x in cost if x is not None]
    rep.add("koszt pomiarow 169c (srednio ms na dobe)", f"{st.mean(cost):.0f} (max {max(cost)})" if cost else "brak linii",
            "<= 390 ms (3% z 13.1 s/dobe; okna Harmony - czas doby biegu)", (st.mean(cost) <= 390) if cost else None)

    # 14. 2.6 - potkniecia korony
    kor = [s for s in lines if s.startswith("Korona: dzien") and "powinnosci wasali" in s]
    st26 = [num(r"rodow pominietych przez blad (\d+)", s) for s in kor]
    st26 = [x for x in st26 if x is not None]
    rep.add("2.6: rody pominiete przez blad (powinnosci)", max(st26) if st26 else "brak licznika (przed 2.6)", "0", (max(st26) == 0) if st26 else None)

    # 15. 2.14 - przeplywy okupu i harness niewoli (krok 1/1b - okup gracza i odbiorcy; krok 2 - kurier na sucho; 2b/2c - PRAWDZIWE AcceptRansomOffer)
    h = [s for s in lines if s.startswith("Okupy (2.14)")]
    void = [num(r"w nicosc (\d+)", s) for s in h]
    void = [x for x in void if x is not None]
    rep.add("2.14: okup gracza w nicosc / dosypka kuriera", max(void) if void else "brak linii (przed 2.14)", "0 zl", (max(void) == 0) if void else None)
    town = sum(num(r"zapasowy: kasa najblizszego miasta (\d+)", s) or 0 for s in h if s.startswith("Okupy (2.14): dzien"))
    hide = sum(num(r"kasa kryjowki bandy (\d+)", s) or 0 for s in h if s.startswith("Okupy (2.14): dzien"))
    rep.add("2.14: okup do kasy osady (kryjowka / miasto bez pana)", f"kryjowka {hide}, kasa miasta {town}" if h else "brak linii", "INFO (kasa miasta ponad cel regulatora gry jest kasowana)", None)
    harn = [s for s in lines if s.startswith("Harness niewoli (2.14)")]
    # narzedzie progow zb58 (TRIAZ "2.14 kurier prawdziwy w harnessie"): od paczki 178 harness przy Ransom178.On robi prawdziwe AcceptRansomOffer w galezi
    # 178 i wraca przed krokami 2b/2c (RansomFlows) - prawdziwy kurier biegnie pod nazwa "Harness niewoli (178): krok 2 - kurier prawdziwy". Gdy ta linia
    # jest: TAK, jesli konczy sie "OK." i ma "z niczego 0"; brak 2b/2c jest wtedy oczekiwany.
    h178 = [s for s in lines if s.startswith("Harness niewoli (178): krok 2 - kurier prawdziwy")]
    if not harn:
        rep.add("2.14: harness niewoli (krok 1 i 2)", "brak linii (nie autotest albo RansomHarnessInAutotest wylaczone)", "wynik OK w kazdym kroku", None)
        if h178:
            rep.add("2.14: kurier prawdziwy w harnessie (krok 2b, 2c)", "178: ..." + h178[-1][-150:], "krok 2 galezi 178: OK. i z niczego 0",
                    all(s.rstrip().endswith("OK.") and "z niczego 0," in s for s in h178))
        else:
            rep.add("2.14: kurier prawdziwy w harnessie (krok 2b, 2c)", "brak linii", "2b i 2c OK", None)
    else:
        base_steps = [s for s in harn if not s.startswith("Harness niewoli (2.14): krok 2b") and not s.startswith("Harness niewoli (2.14): krok 2c - ")
                      and not s.startswith("Harness niewoli (2.14): sprzatanie")]
        bad = [s for s in base_steps if " OK" not in s]
        rep.add("2.14: harness niewoli (krok 1, 1b, 2 na sucho)", f"{len(base_steps)} linii" + (" - " + bad[0][:160] if bad else ""), "wynik OK w kazdym kroku",
                (not bad) and len(base_steps) > 0)
        real = {k: [s for s in harn if s.startswith("Harness niewoli (2.14): krok " + k + " - ")] for k in ("2b", "2c")}
        skip = [s for s in harn if s.startswith("Harness niewoli (2.14): krok 2b/2c")]
        if real["2b"] and real["2c"]:
            okr = all(s.rstrip(".").endswith(" OK") for k in ("2b", "2c") for s in real[k])
            rep.add("2.14: kurier prawdziwy w harnessie (krok 2b, 2c)", " / ".join(k + ": ..." + real[k][-1][-120:] for k in ("2b", "2c")), "2b i 2c OK", okr)
        elif h178:
            rep.add("2.14: kurier prawdziwy w harnessie (krok 2b, 2c)", "178: ..." + h178[-1][-150:],
                    "2b i 2c OK albo (od 178) krok 2 galezi 178: OK. i z niczego 0 - 2b/2c wtedy nie biegna",
                    all(s.rstrip().endswith("OK.") and "z niczego 0," in s for s in h178))
        else:
            why = skip[-1][:160] if skip else ("tylko 2b" if real["2b"] else "brak linii 2b/2c")
            rep.add("2.14: kurier prawdziwy w harnessie (krok 2b, 2c)", why, "2b i 2c OK (pominiety = NIE)", False)

    # 16b. krok B (projekt etapu 2, "110 + 112 + klucz 114"; progi rozdz. 1 i test kroku B) - linie paczek, regulator zamkow, zawor, pieniadz swiata
    zz = by_day(lines, "Zawor zamkow (110): dzien")
    b_on = bool(zz)
    rep.add("110: linia Zawor zamkow (110)", f"{len(zz)} dob" if zz else "brak (przed 110 albo Castle Purse Enabled wylaczone)", "obecna po wgraniu B", True if zz else None)
    cas_b = by_day(lines, "Przeplywy osad (kasy zamkow): dzien")
    sk = [num(r"skasowal (\d+);", cas_b[k]) for k in sorted(cas_b)]
    sk = [x for x in sk if x is not None]
    rep.add("110: regulator kas zamkow - skasowane (najwiecej w dobie)", max(sk) if sk else "brak linii", "0 (kasowanie zablokowane)",
            (max(sk) == 0) if (sk and b_on) else None)
    dos = [num(r"dosypka do zapasu \(tryb 1, zostaje do etapu 3\) (\d+)", zz[k]) for k in last_window(zz)]
    dos = [x for x in dos if x is not None]
    # 110-p: prog zamiast INFO. Projekt liczyl dosypke ok. 3.7 tys./dobe; bieg bazowy (kopia-baza120, doby 31-120) ma w kasach zamkow "zakupy" +55 tys.,
    # dosypke 26 tys. i kasowanie 34 tys., a prawdziwe przeplywy netto -40 tys./dobe - po 110 dosypka trybu 1 moze przejac role "zakupow" (zloto z niczego
    # w zamkach bez spadku). TAK, gdy dosypka <= 10 tys./dobe (Z9) albo zloto z niczego netto w kasach zamkow ("zakupy" + dosypka - kasowanie, linia
    # "Przeplywy osad (kasy zamkow)") nie wyzsze niz w biegu bazowym; inaczej NIE
    def cas_net(w):
        if any(w.get(k) is None for k in ("zamki_zakupy", "zamki_dosypal", "zamki_skasowal")):
            return None
        return w["zamki_zakupy"] + w["zamki_dosypal"] - w["zamki_skasowal"]
    net_now, net_base = cas_net(sw), cas_net(bw)
    if dos:
        dm = st.mean(dos)
        ok_dos = dm <= 10000 or (net_now is not None and net_base is not None and net_now <= net_base)
        rep.add("110: dosypka regulatora do zapasu zamkow (tryb 1, 28 dob)",
                f"{dm:.0f} na dobe; zloto z niczego netto w kasach zamkow " + (f"{net_now:+.0f}" if net_now is not None else "-")
                + (f" wobec bazy {net_base:+.0f}" if net_base is not None else " (bez bazy)"),
                "<= 10 tys./dobe (Z9) albo z niczego netto w kasach zamkow <= baza (projekt: ok. 3.7 tys.)", ok_dos if b_on else None)
    else:
        rep.add("110: dosypka regulatora do zapasu zamkow (tryb 1, 28 dob)", "brak linii", "<= 10 tys./dobe (Z9) albo z niczego netto w kasach zamkow <= baza", None)
    pz = [num(r"z zaworu srednio (\d+)", zz[k]) for k in last_window(zz)]
    pz = [x for x in pz if x is not None]
    # 200-350 zl/dobe projekt liczyl z kasowania regulatora ok. 105 tys./dobe (stare logi: zold zalog 60 tys., sprzet AI 23 tys.); bieg bazowy
    # (kopia-baza120) ma w kasach zamkow kasowanie 34 tys., zold zalog 35-38 tys., sprzet AI ok. 0 (171 C8 - zamek nie jest targiem broni) i prawdziwe
    # przeplywy netto -30 tys./dobe: kupcy przywoza do zamkow konie i uprzaz (BK: ludnosc zamku je zuzywa, popyt kategorii koni 0.14 x dobrobyt).
    # Po B-2 zamek kupuje tylko z nadwyzki, wiec zawor bierze 7% doplywu doby (szacunek B-2: 15-25 zl/dobe na pana samych zamkow).
    # B-4 (przeglad B-3): B-3 zrobil z progu INFO bez decyzji, a zaden inny prog nie pilnuje tego dochodu (D staly pomija zawor z wlasnego zoldu -
    # "wlasne" 169c; wiersz Z8 nizej byl prawdziwy z definicji). Prog projektu zostaje: TAK w 200-350, ponizej - DECYZJA (przyczyna poza krokiem B:
    # konie zjadane przez ludnosc zamkow wbrew "kon ginie jak ginie" - paczka koni P1/P2; albo nowy cel z rachunku E2 przeliczonego z zaworem
    # zmierzonym po B-2 - poprawka projektu przed C1), powyzej - NIE
    if pz:
        pm = st.mean(pz)
        rep.add("110: pan samych zamkow - wplyw z zaworu (srednio, 28 dob)", f"{pm:.0f} zl/dobe",
                "200-350 (projekt, test kroku B); ponizej - DECYZJA: konie zjadane w zamkach (paczka koni P1/P2) albo nowy cel z E2 po biegu B-2 (poprawka projektu przed C1)",
                (200 <= pm <= 350) if b_on else None, decide=pm < 200)
    else:
        rep.add("110: pan samych zamkow - wplyw z zaworu (srednio, 28 dob)", "brak linii", "200-350 (projekt, test kroku B)", None)
    # B-3 (Z8): to, co pan dostaje z zaworu, minus polowa zoldu zalog zamkow, ktorego korona mu nie zwraca, bo "wraca zaworem". Bieg 120 dob kroku B
    # (114-p HomePart z przewidywania): zawor panom 5.9 tys., bez zwrotu 17.7 tys. -> -3 tys./dobe. B-4 (przeglad B-3): po B-2 ciecie rodu to
    # min(zold zalog zamkow, zawor rodu dzis, zold rodu) - suma ciec nie przekracza zaworu panom z tej samej doby, wiec wiersz jest prawdziwy z
    # definicji: INFO (kontrola zgodnosci - ciecie <= zawor). Wiazacy Z8 - wiersz nizej (gorna granica z 1 zl, rody w wojnie)
    zo = by_day(lines, "Zold: dzien")
    hv, lv, hv_b2 = [], [], False
    for k in last_window(zo):
        h = num(r"bez zwrotu korony \((?:114-p|Z8, B-2[^)]*)\) (\d+)", zo[k])
        if h is not None:
            hv.append(h)
            hv_b2 = hv_b2 or "bez zwrotu korony (Z8, B-2" in zo[k]
    for k in last_window(zz):
        a1 = num(r"zawor: (\d+) do panow", zz[k])
        if a1 is not None:
            lv.append(a1)
    # E5/F9: procent zwrotu z linii "Obieg" (zwrot zoldu N (P% z M)) - Crown Wage Refund Percent 70 od poprawki wojska; bez linii 50% jak dotad
    obg_z8 = by_day(lines, "Obieg: dzien")
    pz = [num(r"zwrot zoldu \d+ \(([\d.]+)% z", obg_z8[k], float) for k in last_window(obg_z8)] if obg_z8 else []
    pz = [x for x in pz if x is not None]
    pct_z8 = st.mean(pz) / 100.0 if pz else 0.5
    if hv and lv:
        net = st.mean(lv) - pct_z8 * st.mean(hv)
        rep.add("110/Z8: zawor zamkow do panow minus utracony zwrot korony (28 dob)", f"{net:+.0f} na dobe (zawor panom {st.mean(lv):.0f}, zold bez zwrotu {st.mean(hv):.0f} x {pct_z8 * 100:.0f}%)"
                + (("; ciecie <= zawor: " + ("tak" if st.mean(hv) <= st.mean(lv) else "NIE - blad TakePaid")) if hv_b2
                   else "; log sprzed B-2 (114-p: ciecie z przewidywania - bez kontroli zgodnosci)"),
                "po B-2 INFO - kontrola zgodnosci (ciecie <= zawor z definicji), wiazacy Z8 - wiersz nizej; log sprzed B-2 (114-p) >= 0",
                (net >= 0) if (b_on and not hv_b2) else None)
    else:
        rep.add("110/Z8: zawor zamkow do panow minus utracony zwrot korony (28 dob)", "brak linii", "INFO - kontrola zgodnosci", None)
    # B-4 (Z8 2.0b, gorna granica): rody, ktorym korona zwraca zold (krolestwo w wojnie, nie najemnik), z zoldem zalog wplaconym do kas WLASNYCH zamkow -
    # z 1 zl tego zoldu wraca do rodu nalezny zwrot korony od reszty zoldu (po cieciu) + zawor panom tych rodow < 1. Moze pasc: ciecie ma gorna granice
    # w zoldzie zalog, a zawor rodu bierze tez inne wplaty do kasy zamku (place budow, zakupy na targu zamku). Licznik z linii "Zold:" (od B-4)
    z8p = z8d = z8r = 0
    z8n = 0
    for k in last_window(zo):
        m8 = re.search(r"Z8 rody w wojnie z zoldem zalog we wlasnych zamkach: zold do kas zamkow (\d+), zawor panom (\d+), nalezny zwrot korony od reszty (\d+)", zo[k])
        if m8:
            z8p += int(m8.group(1)); z8d += int(m8.group(2)); z8r += int(m8.group(3)); z8n += 1
    if z8n and z8p > 0:
        back = (z8d + z8r) / z8p
        rep.add("Z8: z 1 zl zoldu zalog we wlasnych zamkach wraca (rody w wojnie, 28 dob)", f"{back:.3f} (zawor {z8d / z8p:.3f} + nalezny zwrot korony {z8r / z8p:.3f}; zold {z8p / z8n:.0f} na dobe)",
                "< 1 (Z8 2.0b - nikt nie zarabia na wlasnym wydatku; gorna granica: zwrot nalezny, nie wyplacony)", (back < 1.0) if b_on else None)
    else:
        rep.add("Z8: z 1 zl zoldu zalog we wlasnych zamkach wraca (rody w wojnie, 28 dob)", "brak licznika (log sprzed B-4)" if not z8n else "0 zoldu", "< 1", None)
    # B-3: pieniadz swiata - zmiana tempa wobec bazy minus zamkniete ujscia, uczciwiej (diagnoza biegu 120 dob kroku B):
    #  (a) okno dob 31+ obu biegow (przy biegu >= 58 dob), nie ostatnie 28 dob - w dobach 1-30 przyciecie daru startowego zamkow (110) przesuwa
    #      w czasie to, co w bazie kasowal regulator (ok. 170 tys./dobe), a ostatnie 28 dob to los wojny (krok B: +212 tys. w 93-120, -50 tys. w 61-92);
    #  (b) bez wojennych zrodel z niczego, ktorych B nie dotyka (statki NavalDLC, bitwy, jency, lup z oblezen, minus lup z cial): krok B +41.5 tys.;
    #  (c) zamkniete ujscie taborow: baza "U8 tabory" minus sakwy, ktore naprawde zniknely (linia 112), nie U8 biegu B - do B-1 ksiega liczyla
    #      sakwe oddana przez 112 jako zniknieta (U8 = sakwy 112 w 119 z 119 dob);
    #  (d) B-4 (przeglad B-3): regulator kas miast ROZDZIELONY - dotad odejmowana byla zmiana netto (dosypal - skasowal), ktora laczyla dwie
    #      przeciwne rzeczy: mniej dosypki (zamkniete zrodlo z niczego - oczekiwane) i wiecej kasowania (zloto, ktore B zatrzymal we wsiach, regulator
    #      miast kasuje w nicosc - nowe ujscie). Teraz: spadek dosypki odejmowany jako oczekiwany, wzrost dosypki NIGDY (zostaje w wyniku - zloto
    #      z niczego); zmiana kasowania wylaczona z wyniku, ale jej wzrost ma WLASNY wiersz z progiem <= 10 tys./dobe (powyzej - DECYZJA: zamyka to
    #      dopiero 111' w etapie 5, a czesc kasowania to odpowiedz regulatora na wojenne zloto z niczego z (b) - jedna para biegow tego nie rozdziela).
    #      Bez rozbicia w bazie (plik sprzed B-4) - wynik jak dotad, ale INFO.
    # Do tego reszta ksiegi (niezmierzone) wobec bazy: paczka, ktora tworzy albo kasuje zloto bez nazwy, przesuwa reszte. Reszta B poprawiona o ten
    # sam blad ksiegi (U8 tabory minus sakwy zniklo z linii 112; po B-1 = 0). B-4: reszta wiaze na kazdej dlugosci biegu (ostatnie 28 wspolnych dob,
    # od doby 31 przy biegu >= 58 dob) - nie zalezy od przyciecia daru w dobach 1-30 (osobna pozycja ksiegi), wiec zloto bez nazwy wykryje juz
    # autotest 40 dob; wiersz "bez wojny" przy biegu < 58 dob - INFO (wiaze bieg 120 dob).
    dn, db = now.get("dni") or {}, (base or {}).get("dni") or {}
    if dn and db and b_on:
        hi = min(max(dn), max(db))
        binding = hi >= 58
        days = list(range(31, hi + 1)) if binding else list(range(max(1, hi - 27), hi + 1))

        def m(T, key, dflt=0.0):
            v = mean_days(T, days, key)
            return dflt if v is None else v

        # E8/0 (242): "bitwy" netto tylko, gdy oba biegi maja rozbicie (klucz bitwy_brutto - baza zapisana po E8/0); baza starsza - obie strony brutto
        both_net = mean_days(dn, days, "bitwy_brutto") is not None and mean_days(db, days, "bitwy_brutto") is not None

        def war(T):
            b = m(T, "bitwy") if both_net else m(T, "bitwy_brutto", m(T, "bitwy"))
            return sum(m(T, k) for k in WAR_KEYS if k != "bitwy") + b - m(T, "lup_cial")

        def cas_nothing(T):
            return m(T, "zamki_zakupy") + m(T, "zamki_dosypal") - m(T, "zamki_skasowal")
        has112 = mean_days(dn, days, "sakwy_zniklo_112") is not None
        lost_now = m(dn, "sakwy_zniklo_112") if has112 else m(dn, "u8_tabory")
        fix_r = (m(dn, "u8_tabory") - lost_now) if has112 else 0.0          # B-1: sakwy 112 liczone jako znikniete (stary log) - po B-1 ok. 0
        dz = m(dn, "Z") - m(db, "Z")
        dwar = war(dn) - war(db)
        e_cas = cas_nothing(dn) - cas_nothing(db)
        e_vil = (m(db, "utarg_zniklo") - m(dn, "utarg_zniklo")) + (m(db, "prow_wsie") - m(dn, "prow_wsie")) + (m(db, "u8_tabory") - lost_now)
        dreg = m(dn, "miasta_reg") - m(db, "miasta_reg")
        split_reg = mean_days(dn, days, "miasta_dos") is not None and mean_days(db, days, "miasta_dos") is not None
        wtxt = f"doby {days[0]}-{days[-1]}"
        if split_reg:
            d_dos = m(dn, "miasta_dos") - m(db, "miasta_dos")
            d_kas = m(dn, "miasta_kas") - m(db, "miasta_kas")
            exp_dos = min(d_dos, 0.0)                     # tylko spadek dosypki (zamkniete zrodlo z niczego) jest oczekiwany
            res = dz - dwar - e_cas - e_vil - exp_dos + d_kas
            rtxt = (f"regulator kas miast: dosypka {d_dos:+.0f} (odjete {exp_dos:+.0f} - tylko spadek), kasowanie {d_kas:+.0f} (poza wynikiem - wiersz nizej)")
        else:
            res = dz - dwar - e_cas - e_vil - dreg
            rtxt = f"regulator kas miast netto {dreg:+.0f} - baza bez rozbicia dosypka/kasowanie (zapisz baze jeszcze raz), wiersz INFO"
        rep.add("B: pieniadz swiata bez wojny - zmiana tempa wobec bazy minus zamkniete ujscia i spadek dosypki miast",
                f"{res:+.0f} ({wtxt}: zmiana tempa {dz:+.0f}, wojenne zrodla z niczego {dwar:+.0f} (bitwy {'netto' if both_net else 'brutto - baza sprzed E8/0'}), zamki - zloto z niczego netto {e_cas:+.0f}, "
                f"wsie i tabory - zamkniete ujscia {e_vil:+.0f}, {rtxt})",
                "+-30 tys./dobe" + ("" if binding else " (INFO - wiaze bieg 120 dob: okno dob 31+ przy biegu >= 58 dob)"),
                (abs(res) <= 30000) if (binding and split_reg) else None)
        if split_reg:
            rep.add("B: ujscie w nicosc przeniesione do regulatora kas miast (wzrost kasowania wobec bazy)",
                    f"{d_kas:+.0f} na dobe ({wtxt}: skasowal {m(dn, 'miasta_kas'):.0f} wobec bazy {m(db, 'miasta_kas'):.0f}; zatrzymane przez B we wsiach i tabory {e_vil:+.0f})",
                    "<= 10 tys./dobe; powyzej - DECYZJA: regulator miast kasuje zloto, ktore B zatrzymal (zamyka 111' w etapie 5 - wczesniej?; czesc to wojenne zloto"
                    " z niczego, ktore regulator tez kasuje - rozrzut druga para biegow)" + ("" if binding else " (INFO - wiaze bieg 120 dob)"),
                    (d_kas <= 10000) if binding else None, decide=True)
        rn, rb = m(dn, "R") - fix_r, m(db, "R")
        rep.add("B: reszta ksiegi pieniadza (niezmierzone) wobec bazy", f"{rn - rb:+.0f} ({wtxt}: bieg {rn:+.0f}" + (f" po poprawce sakw 112 {-fix_r:+.0f}" if fix_r else "")
                + f", baza {rb:+.0f})", "+-10 tys./dobe (paczka nie tworzy ani nie kasuje zlota bez nazwy; te same doby obu biegow - wiaze tez autotest 40 dob)",
                abs(rn - rb) <= 10000)
    elif b_on:
        rep.add("B: pieniadz swiata bez wojny - zmiana tempa wobec bazy minus zamkniete ujscia i spadek dosypki miast", "brak bazy albo szeregow dobowych w bazie (zapisz baze jeszcze raz z logu biegu bazowego)",
                "+-30 tys./dobe", None)
    # dawny wiersz (28 dob, bez wojny i bez regulatora miast) - INFO dla porownania z wczesniejszymi raportami
    keys = ("zamki_zakupy", "zamki_dosypal", "zamki_skasowal", "wsie_utarg_zniklo", "wsie_prowizja", "tabory_kiesy_zniknely")
    if base and all(bw.get(k) is not None for k in keys) and all(sw.get(k) is not None for k in keys) and sw.get("pieniadz_zmiana") is not None \
            and bw.get("pieniadz_zmiana") is not None:
        e_cas = (sw["zamki_zakupy"] + sw["zamki_dosypal"] - sw["zamki_skasowal"]) - (bw["zamki_zakupy"] + bw["zamki_dosypal"] - bw["zamki_skasowal"])
        e_vil = (bw["wsie_utarg_zniklo"] - sw["wsie_utarg_zniklo"]) + (bw["wsie_prowizja"] - sw["wsie_prowizja"]) \
                + (bw["tabory_kiesy_zniknely"] - sw["tabory_kiesy_zniknely"])
        dv = sw["pieniadz_zmiana"] - bw["pieniadz_zmiana"]
        rep.add("B: pieniadz swiata - zmiana tempa wobec bazy minus zamkniete ujscia (ostatnie 28 dob, z wojna)",
                f"{dv - e_cas - e_vil:+.0f} (zmiana tempa {dv:+.0f}; zamkniete: zamki {e_cas:+.0f}, wsie i tabory {e_vil:+.0f})",
                "INFO - wiersz sprzed B-3 (los wojny ostatnich 28 dob, U8 z bledem kolejnosci ksiegi); wiazacy wiersz wyzej", None)
    # 112: utarg wsi, towar kupiony we wsi, sakwy taborow; bandy najwyzej +20% wobec bazy (S16)
    ut = by_day(lines, "Utarg wsi (112): dzien")
    rep.add("112: linia Utarg wsi (112)", f"{len(ut)} dob" if ut else "brak (przed 112)", "obecna po wgraniu B", True if ut else None)
    # 112-p (2.0b: licznik "bez odbiorcy" z progiem 0): kazda doba linii 112 - utarg nieprzypisany, towar kupiony we wsi i sakwy taborow, ktore zniknely
    def seg_of(line, head):
        for part in line.split(" | "):
            if part.startswith(head):
                return part
        return ""
    for name, head, pat in (("nieprzypisane (utarg)", "powroty taborow z utargiem", r"nieprzypisane (-?\d+)"),
                            ("zniklo (towar kupiony we wsi)", "towar kupiony we wsiach", r"zniklo (-?\d+)"),
                            ("zniklo (sakwy zniszczonych taborow)", "tabory zniszczone", r"zniklo (-?\d+)")):
        vals = []
        for k in sorted(ut):
            m = re.findall(pat, seg_of(ut[k], head))
            if m:
                vals.append(int(m[-1]))
        if not vals:
            rep.add(f"112: {name} - suma wszystkich dob", "brak linii", "0 (2.0b: bez odbiorcy - prog 0)", None)
            continue
        tot, bad = sum(vals), sum(1 for v in vals if v != 0)
        rep.add(f"112: {name} - suma wszystkich dob", f"{tot} ({bad} z {len(vals)} dob ponad 0)", "0 (2.0b: bez odbiorcy - prog 0)", tot == 0 and bad == 0)
    zn = [num(r"z utargu wsi zniklo (-?\d+)", s2) for s2 in by_day(lines, "Pieniadz swiata (bilans): dzien").values()]
    zn = [x for x in zn if x is not None]
    rep.add("112: z utargu wsi zniklo (srednio na dobe)", f"{st.mean(zn):.0f}" + (f" (baza {bw['wsie_utarg_zniklo']:.0f})" if bw.get("wsie_utarg_zniklo") is not None else "") if zn else "brak linii",
            "INFO - po 112 ok. 0 (reszta nieprzypisana w linii 112)", None)
    zam = [num(r"zamkniete ujscia razem \(dopisane wsiom, panom i zwyciezcom\): (\d+)", ut[k]) for k in last_window(ut)]
    zam = [x for x in zam if x is not None]
    rep.add("112: zamkniete ujscia (oddane wsiom, panom i zwyciezcom, 28 dob)", f"{st.mean(zam):.0f} na dobe" if zam else "brak linii",
            "INFO - projekt: ok. +47 tys./dobe do kies wsi + zywnosc i sakwy", None)
    # B-3: S16 pilnuje, czy bandy sie nie wzmacniaja (Jeff 09.10 04:55, Q3b: "autotest pilnuje, czy bandy sie nie wzmacniaja; zloto band ma platnika
    # i ujscie"). Samo zloto band nie jest miara sily: decyzja D (04:25 - zwyciezca bierze cala sakwe taboru) daje bandom doplyw (krok B: 0 -> 17 tys./dobe,
    # 99.5% sakw), a zapas ustala sie na doplyw / tempo wydatkow (ok. 10% kiesy dziennie w miastach) - kazde wykonanie D to ok. +100% zlota band.
    # Kiesy band - INFO; wiazace: sila (tier, liczba band, ludzie, awanse i zloto u pasera, tabory rozbite) <= baza +20% i ujscie zlota (wydatki
    # w miastach na dobe / kiesy band) nie mniej niz 80% bazy
    for key, name in (("bandy_tier", "sredni tier ludzi band"), ("bandy_liczba", "liczba band"), ("bandy_ludzie", "ludzie band"),
                      ("bandy_awanse_paser", "awanse band u pasera"), ("bandy_paser_zl", "zloto band u pasera"), ("tabory_rozbite_bandy", "tabory rozbite przez bandy na dobe"),
                      ("bandy_zloto", "kiesy band")):
        v, b = sw.get(key), bw.get(key)
        info = key == "bandy_zloto"
        rule = "INFO - decyzja D (zwyciezca bierze cala sakwe): zapas = doplyw / tempo wydatkow; wiazace sila i ujscie" if info else "<= baza + 20% (S16 - bandy sie nie wzmacniaja)"
        if v is None:
            rep.add(f"112: bandy - {name} (28 dob)", "brak linii", rule, None)
        elif b is None or b == 0:
            rep.add(f"112: bandy - {name} (28 dob)", f"{v:.3f}" if key == "bandy_tier" else f"{v:.0f}", rule + "; brak w bazie - porownac z biegiem z Villager Purse Survives wylaczonym", None)
        else:
            rep.add(f"112: bandy - {name} (28 dob)", (f"{v:.3f}" if key == "bandy_tier" else f"{v:.0f}") + f" wobec bazy " + (f"{b:.3f}" if key == "bandy_tier" else f"{b:.0f}")
                    + f" ({100.0 * v / b - 100:+.0f}%)", rule, None if info else ((v <= 1.2 * b) if b_on else None))
    sn, sb = sw.get("bandy_wydaly"), bw.get("bandy_wydaly")
    gn, gb = sw.get("bandy_zloto"), bw.get("bandy_zloto")
    if sn is not None and gn:
        qn = 100.0 * sn / gn
        qb = (100.0 * sb / gb) if (sb is not None and gb) else None
        rep.add("112: bandy - ujscie zlota (wydatki w miastach / kiesy band na dobe, 28 dob)", f"{qn:.1f}%" + (f" wobec bazy {qb:.1f}%" if qb is not None else " (bez bazy)"),
                ">= 80% bazy (zloto band ma ujscie - Q3b)", (qn >= 0.8 * qb) if (qb is not None and b_on) else None)
    else:
        rep.add("112: bandy - ujscie zlota (wydatki w miastach / kiesy band na dobe, 28 dob)", "brak linii", ">= 80% bazy", None)
    # klucz 114: udzial korony w zaworze zamkow = 1 - CastleDuesLordShare (domyslnie 0.33) - suma 28 dob z linii 110
    lp = cp = 0
    for k in last_window(zz):
        a1, c1 = num(r"zawor: (\d+) do panow", zz[k]), num(r"skarbcom krolestw (\d+) z", zz[k])
        if a1 is not None and c1 is not None:
            lp += a1; cp += c1
    rep.add("114: udzial korony w zaworze zamkow (28 dob)", f"{100.0 * cp / (lp + cp):.1f}% (korona {cp}, panowie {lp})" if lp + cp > 0 else "brak linii (przed 114 albo podzial wylaczony)",
            "ok. 33% (1 - Castle Dues Lord Share; zamki rodow bez krolestwa - calosc panu)", (28.0 <= 100.0 * cp / (lp + cp) <= 34.0) if (lp + cp > 0 and b_on) else None)
    v, b = sw.get("utarg_miasta"), bw.get("utarg_miasta")
    rep.add("B: zakupy plonu przez miasta (utarg taborow, 28 dob)", f"{v:.0f}" + (f" wobec bazy {b:.0f} ({100.0 * v / b:.0f}%)" if b else " (bez bazy)") if v is not None else "brak linii",
            ">= 95% bazy (bez zmian)", (v >= 0.95 * b) if (v is not None and b and b_on) else None)

    # 16. bledy naszych modow
    errs = [s for s in lines if s.startswith("ERROR in ")]
    rep.add("bledy Armoury (ERROR in)", len(errs), "0", len(errs) == 0)

    rep.show()
    if base_out:
        with open(base_out, "w", encoding="utf-8") as f:
            json.dump(now, f, ensure_ascii=False, indent=1)
        print(f"plik bazowy zapisany: {base_out}")
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
